INSERT INTO works (title, scenic_spot, author, dynasty, description, province, latitude, longitude, category, images) VALUES
('《尘埃落定》', '阿坝州马尔康市松岗土司官寨遗址', '阿来', '现代', '松岗土司官寨遗址坐落于四川省阿坝州马尔康市松岗镇，是嘉绒藏族历史上规模最大的土司官寨遗存之一，也是著名作家阿来长篇小说《尘埃落定》中麦其土司官寨的核心原型地。遗址保留了清代修建的高耸碉楼和厚重的夯土城墙，碉楼高达数十米气势雄伟。整座官寨依山而建背靠苍翠群山面朝梭磨河谷，地理位置险要。这里游客稀少远离商业喧嚣，行走其间仿佛穿越回土司统治时期的嘉绒大地，能真切感受到藏族土司文化的历史厚重感与苍凉之美。', '四川', 31.923200, 102.108200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/8d/Barkhams1.JPG"]'),
('《云中记》', '阿坝州理县薛城镇老藏寨', '阿来', '现代', '老藏寨位于四川省阿坝州理县薛城镇，是阿来小说《云中记》中云中村的原型地。汶川大地震后寨中部分居民已搬迁至新址，但原始村落格局依然保留完好。寨中随处可见传统藏式碉楼和古老的水磨房，石砌墙体历经风雨侵蚀更显沧桑古朴。整座寨子静卧于高山峡谷之间，周围梯田层叠溪水潺潺，尽显藏地乡村的质朴与宁静。这里几乎没有旅游开发保持着最本真的藏族生活气息，是了解阿来文学创作灵感和感受震后乡村重建历程的绝佳之地。', '四川', 31.436000, 103.171700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/ee/%E5%B1%B1%E4%B8%9C%E7%9C%81%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E7%AC%AC%E5%9B%9B%E6%89%B9%E7%9C%81%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E7%9A%84%E9%80%9A%E7%9F%A5%EF%BC%88%E9%B2%81%E6%94%BF%E5%AD%97%E3%80%942013%E3%80%95204%E5%8F%B7%EF%BC%89.pdf"]'),
('《死水微澜》', '成都市金牛区天回镇老街区', '李劼人', '现代', '天回镇老街区位于四川省成都市金牛区，是著名作家李劼人长篇小说《死水微澜》中邓幺姑与罗歪嘴故事的主要背景地。老街区保留了大量清末民初的川西传统民居建筑，青瓦白墙木构门楼错落有致，街边还有数家百年老茶馆。与成都著名的宽窄巷子相比天回镇没有浓厚的商业气息，街巷之间弥漫着老成都特有的市井烟火味。漫步其中可以真切感受到李劼人笔下动荡年代川西小镇的日常生活图景，是探寻近代成都民间社会风貌的理想去处。', '四川', 30.691200, 104.051800, '其他', '["https://img1.baidu.com/it/u=2888125121,3547803293&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《大波》', '成都市郫都区唐昌古镇', '李劼人', '现代', '唐昌古镇位于四川省成都市郫都区，始建于唐代拥有千余年历史，是李劼人长篇小说《大波》中多次描绘的川西古镇原型。古镇保留着完整的明清古街格局，青石板路面光滑如镜两旁是典型的川西民居和古老文庙建筑。与许多过度开发的古镇不同唐昌古镇商业化程度极低，街巷中居民依然过着传统生活，茶馆铁匠铺老药房等传统店铺散落其间。这里可以感受到最原汁原味的川西古镇风情，领略李劼人笔下保路运动时期成都平原小镇的历史氛围。', '四川', 30.810900, 103.887200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/2/22/A_Typical_Linpan_in_Pi_County.jpg"]'),
('《憩园》', '成都市崇州市元通古镇', '巴金', '现代', '元通古镇位于四川省成都市崇州市，是文学巨匠巴金笔下憩园的原型地之一。古镇依文井江而建水网纵横交错，有川西小成都的美誉。镇中保留了大量明清时期的古民居建筑群，其中最著名的是规模宏大的黄家大院，雕梁画栋天井院落尽显川西望族气派。古镇老街上的石板路风雨廊桥和临水吊脚楼构成一幅典型的川西水乡画卷。这里远离大众旅游路线游客不多，古镇居民生活节奏缓慢安逸，是体验巴金文学世界中恬静温馨园林生活的绝佳场所。', '四川', 30.630200, 103.673000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/3c/State_Council_Gazette_-_2020_-_Issue_14.pdf"]'),
('《夜谭十记・盗官记》', '达州市渠县三汇古镇', '马识途', '现代', '三汇古镇位于四川省达州市渠县，地处巴河州河渠江三江交汇处，是马识途《夜谭十记》中盗官记故事的发生地，也是电影《让子弹飞》的重要原型地。古镇依山傍水而建保留了完整的明清古街格局和大量传统茶馆。漫步古街可见青石板路蜿蜒于高低错落的吊脚楼之间，街边茶馆里老人们悠闲地喝着盖碗茶，尽显川东特有的江湖气息与市井风情。三江汇流处波澜壮阔水天一色，是观赏自然景观与体验川东民俗文化的理想之地。', '四川', 30.837500, 106.973500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/d8/NLC403-312001068158-137426_%E5%A4%A9%E9%95%B7%E7%B8%A3%E8%AA%8C_1960_%E5%8D%B7%E4%B8%89.pdf"]'),
('《锯齿啮痕录》', '成都市金堂县五凤溪古镇', '流沙河', '现代', '五凤溪古镇位于四川省成都市金堂县，是著名诗人流沙河的故乡。古镇依山傍水沱江穿城而过自古便是水运交通要道。镇中保留了大量明清时期的古民居建筑和繁忙的老码头遗迹，青石板铺就的街道在山坡上蜿蜒伸展。流沙河在《锯齿啮痕录》中深情回忆了这片故土描绘了古镇的山水风貌和童年记忆。五凤溪因有五座形似凤凰的小山而得名，山形优美江水清澈，春日繁花似锦秋季层林尽染，是一处兼具文学底蕴和自然美景的川西古镇。', '四川', 30.861900, 104.411900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/df/Jintang.jpg"]'),
('《四川杂忆》', '成都市彭州市白鹿镇老街区', '汪曾祺', '现代', '白鹿镇老街区位于四川省成都市彭州市，是著名作家汪曾祺在《四川杂忆》中描绘的川西小镇。老街区保留了清末民初的传统民居建筑，其中最引人注目的是一座百年天主教堂中西合璧建筑风格独具特色。街巷中的老式砖木结构房屋雕花窗棂和青瓦屋顶充满旧时光韵味。每到春日镇边山坡上樱花盛开粉白花瓣与古老建筑交相辉映美不胜收。白鹿镇远离城市喧嚣空气清新怡人，是感受汪曾祺笔下川西小镇恬淡生活和中西文化交融的宝贵去处。', '四川', 30.990100, 103.958000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/0/0e/Langzhong_Ancient_Town.jpg"]'),
('《格萨尔王》', '甘孜州德格县阿须草原', '阿来', '现代', '阿须草原位于四川省甘孜州德格县境内，是藏族英雄史诗《格萨尔王》中格萨尔王的诞生地。草原上保留着格萨尔王庙和传统赛马场等重要文化遗迹。阿来在同名小说中以此地为核心背景生动再现了格萨尔王的传奇故事。草原辽阔无垠绿草如茵远处雪山连绵起伏，牦牛和马匹悠闲漫步其间藏族风情浓郁。每年夏季赛马节是草原上最盛大的活动骑手们策马奔腾场景壮观无比。这里远离常规旅游线路保持着原始高原牧场风貌，是深入了解格萨尔文化的圣地。', '四川', 31.806000, 98.580400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/d5/CADAL09014139_%E5%9C%8B%E6%B0%91%E7%B6%93%E6%BF%9F%E5%BB%BA%E8%A8%AD%E9%81%8B%E5%8B%95%E8%A6%81%E7%BE%A9.djvu"]'),
('《我在天堂等你》', '甘孜州理塘县毛垭大草原', '裘山山', '现代', '毛垭大草原位于四川省甘孜州理塘县境内，面积达三百多平方公里，是裘山山小说《我在天堂等你》中解放军进藏故事的核心取景地。草原地势开阔平坦海拔超过四千米四周被雪山环绕。夏季时节草原上野花遍地五彩斑斓，牦牛群和藏族牧民帐篷点缀其间构成壮美的高原牧场画卷。这里几乎没有商业化开发保持着最原始的自然生态和藏族游牧生活方式。站在草原之上天空湛蓝如洗白云触手可及，能深切体会到小说中那段艰苦卓绝进藏历程中的壮阔与悲壮。', '四川', 30.050600, 100.269700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/b/bb/%E7%90%86%E5%A1%98%E9%95%BF%E9%9D%92%E6%98%A5%E7%A7%91%E5%B0%94%E5%AF%BA.jpg"]'),
('《战争和人》', '成都市崇州市街子古镇古寺村', '王火', '现代', '街子古镇古寺村位于四川省成都市崇州市，是作家王火长篇小说《战争和人》的故事背景地之一。村中保留了大量明清时期古民居建筑和千年古刹光严禅院。光严禅院藏经丰富曾保存过珍贵的洪武南藏是川西著名佛教圣地。古寺村四周山林清幽竹影婆娑溪水环绕禅意浓厚，与小说中描绘的抗战时期四川后方宁静氛围相得益彰。远离古镇核心商业区几乎没有游客打扰，青苔覆盖的石板路和古朴寺庙建筑营造出超尘脱俗的意境，是体验川西禅修文化的绝佳去处。', '四川', 30.630200, 103.673000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/19/%E8%A1%97%E5%AD%90%E5%8F%A4%E9%95%87%EF%BC%88%E5%B4%87%E5%B7%9E%E5%B8%82%EF%BC%89.jpg"]'),
('《水经注・江水注》', '广元市青川县清溪古城', '郦道元', '北魏', '清溪古城位于四川省广元市青川县境内，是北魏地理学家郦道元在《水经注》中记载的古蜀道重要关隘。古城始建于秦代至今仍保留着完整的明代城墙和县衙建筑城墙砖石斑驳尽显千年沧桑。城内街巷纵横明清古民居错落分布古朴石板路连接着各处历史遗迹。城外便是风光秀美的唐家河自然保护区山高林密溪水清澈生态环境优越。清溪古城是古蜀道上保存最完好的古城之一兼具军事防御和商贸驿站功能，是研究古蜀道文化和体验川北古城风情的重要场所。', '四川', 32.575500, 105.238900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/3f/State_Council_Gazette_-_2019_-_Issue_30.pdf"]'),
('《徐霞客游记・滇游日记》', '乐山市犍为县罗城古镇', '徐霞客', '明代', '罗城古镇位于四川省乐山市犍为县，因其独特的船形街道布局被誉为中国诺亚方舟，明代旅行家徐霞客曾在游记中途经此地。古镇核心建筑船形街始建于明代两排木质商铺呈弧形排列，中间是宽阔的青石板广场整体形如一艘大船。街边分布着数家百年老茶馆当地居民聚集于此喝茶聊天生活气息浓郁。青石板路面被岁月打磨得光滑如镜街边木柱和雕花门窗诉说着数百年历史。罗城古镇远离主流旅游线路保持着最原始的川南古镇风貌，是感受明清市井生活的理想之地。', '四川', 29.209800, 103.949400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/76/%E5%9B%9B%E5%B7%9D_%E7%8A%8D%E4%B8%BA-%E5%8E%BF%E6%94%BF%E5%BA%9C_-_panoramio.jpg"]'),
('《吴船录》', '乐山市夹江县千佛岩', '范成大', '南宋', '千佛岩位于四川省乐山市夹江县境内，是南宋诗人范成大在《吴船录》中详细记载的重要摩崖石刻群。岩壁上保留着从唐代到明代的摩崖造像共计两千四百余尊雕刻精美神态各异，是四川境内规模最大的石窟群之一。千佛岩沿青衣江畔峭壁开凿江边栈道蜿蜒曲折，行走其间可近距离观赏历代造像艺术。江水清澈碧绿倒映着崖壁上密密麻麻的佛像景色蔚为壮观。这里游客不多可以静心欣赏每一尊造像的细节之美，是研究唐宋佛教艺术和感受古代石刻文化的珍贵去处。', '四川', 29.738400, 103.571500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/86/%E5%9B%9B%E5%B7%9D%E7%9C%81%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%8A%9E%E5%85%AC%E5%8E%85%E5%85%B3%E4%BA%8E%E5%8D%B0%E5%8F%91%E5%9B%9B%E5%B7%9D%E7%9C%81%E5%8A%A0%E5%BC%BA%E7%9F%B3%E7%AA%9F%E5%AF%BA%E4%BF%9D%E6%8A%A4%E5%88%A9%E7%94%A8%E5%B7%A5%E4%BD%9C%E5%AE%9E%E6%96%BD%E6%96%B9%E6%A1%88%E7%9A%84%E9%80%9A%E7%9F%A5.pdf"]'),
('《入蜀记》', '泸州市纳溪区天仙硐', '陆游', '南宋', '天仙硐位于四川省泸州市纳溪区境内，是南宋爱国诗人陆游在《入蜀记》中记载的川南名胜。景区保留了始建于唐代的古寺和大量珍贵的摩崖石刻，石刻内容涵盖佛教造像和历代文人题记历史价值极高。天仙硐依山而建山林茂密苍翠空气清新，瀑布从悬崖之上飞泻而下水雾弥漫声若雷鸣。曲折石梯步道穿行于密林和瀑布之间一步一景令人心旷神怡。这里远离城市喧嚣游客稀少，是陆游入蜀途中留下深刻印象的山水胜地，也是感受川南自然山水和唐宋文化遗韵的理想之所。', '四川', 28.773200, 105.372400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/5f/Naxi_district.jpg"]'),
('《浣花溪记》', '成都市青羊区浣花溪上游老河段', '钟惺', '明代', '浣花溪上游老河段位于四川省成都市青羊区，是明代文人钟惺在《浣花溪记》中描绘的浣花溪最为幽美的河段。与下游人声鼎沸的杜甫草堂景区不同上游河段保留了最原始的自然风貌溪水清澈见底。两岸竹柏苍翠挺拔浓荫蔽日行走于溪边小径之上只闻流水潺潺与鸟鸣啾啾恍若世外桃源。钟惺当年沿溪而上被这里清幽景色深深打动写下了传世名篇。如今这段河道依然远离商业开发是成都市区内难得的一处自然清净之地，适合文学爱好者寻访古人足迹感受浣花溪的本真之美。', '四川', 30.673900, 104.061900, '其他', '["https://img1.baidu.com/it/u=2430169471,3397681356&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=651"]'),
('《陈情表》', '眉山市彭山区保胜乡龙安村李密故里', '李密', '西晋', '李密故里位于四川省眉山市彭山区保胜乡龙安村，是西晋名臣李密的出生地。李密以一篇感人至深的《陈情表》闻名千古，其中乌鸟私情愿乞终养的至孝之情流传至今。故里保留了始建于唐代的龙门寺和一处刻有巨型孝字的石刻，孝字高数米笔力遒劲是当地孝文化的重要象征。整个村庄弥漫着浓厚的孝文化氛围乡间小道两旁还有历代文人凭吊李密的碑刻和诗文。这里远离城市环境幽静是了解西晋历史人物和中华传统孝道文化的重要遗址，每年都有学子前来瞻仰祭拜。', '四川', 30.192800, 103.872700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/3e/202309_Overview_of_Qinglongchang.jpg"]'),
('《草木的理想国》', '成都市温江区万春镇花木基地', '阿来', '现代', '万春镇花木基地位于四川省成都市温江区，享有中国花木之乡的美誉，是作家阿来散文集《草木的理想国》的重要灵感来源地。基地种植了上千种花卉苗木品种繁多从名贵桂花银杏到各类盆景草花应有尽有。春日里百花齐放万紫千红秋冬季节桂花飘香银杏金黄四季皆有不同景致。田园风光秀美宜人花田与水塘交错分布农家院落掩映在花木丛中。阿来常在此观察植物思考自然与人的关系将对草木的深情融入文学创作，这里是体验成都平原田园花卉文化和理解阿来自然写作的独特去处。', '四川', 30.684500, 103.848900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/d7/Chunshen_Lake%2C_Minhang_%2820191111161524%29.jpg"]'),
('《四川的酒》', '宜宾市翠屏区李庄古镇老酒厂', '汪曾祺', '现代', '李庄古镇老酒厂位于四川省宜宾市翠屏区李庄镇，是著名作家汪曾祺在《四川的酒》中生动描述的传统酿酒之地。老酒厂保留了明清时期酿酒作坊和数口百年老窖池，窖池中微生物群落经过数百年培育酿出的白酒醇厚绵长酒香四溢。作坊中传统手工酿酒工艺至今仍在沿用从选粮蒸煮到发酵蒸馏每一道工序都遵循古法。李庄古镇也是抗战时期同济大学等高校的内迁地文化底蕴深厚。在老酒厂中品尝一杯纯粮佳酿感受汪曾祺笔下质朴热烈的川南饮酒文化，别有一番风味。', '四川', 28.751700, 104.619700, '其他', '["https://img2.baidu.com/it/u=3123927455,461721269&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《空山》', '甘孜州丹巴县中路藏寨', '阿来', '现代', '中路藏寨位于四川省甘孜州丹巴县境内，是阿来长篇小说《空山》的创作灵感来源地之一。与同在丹巴的著名甲居藏寨相比中路藏寨更为小众宁静游客稀少。藏寨依山势而建层层叠叠的藏式碉楼和民居从山脚延伸至山腰碉楼高耸入云气势恢宏。寨中遍布金黄的青稞田和翠绿的果园，每到春季梨花盛开时白色花海与藏式建筑交相辉映美如仙境。清晨薄雾缭绕炊烟袅袅傍晚夕阳染红碉楼构成一幅绝美的藏地田园画卷，是深入体验嘉绒藏族原生态生活和感受阿来文学意境的绝佳目的地。', '四川', 30.876300, 101.882500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/ca/CADAL09006818_%E4%B8%AD%E5%9C%8B%E4%B9%8B%E5%91%BD%E9%81%8B.djvu"]'),
('《瞻对》', '甘孜州新龙县拉日马草原', '阿来', '现代', '拉日马草原位于四川省甘孜州新龙县境内，是阿来纪实文学作品《瞻对》的重要故事发生地。草原辽阔壮美四周雪山环绕牧场上分布着传统藏式牧民帐篷和古老的藏传佛教寺院。这里是康巴藏区腹地牧民们世代在此放牧牦牛和藏马保持着最原始的游牧生活方式。草原上野花遍地溪流蜿蜒远处雪山巍峨壮丽景色极为震撼。阿来在《瞻对》中深入挖掘了这片土地上数百年的历史风云揭示了康巴藏区独特的社会结构和文化传统。拉日马草原远离常规旅游路线是感受康巴风情和了解藏区历史的隐秘秘境。', '四川', 30.939000, 100.311600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/5d/CADAL11106087_%E7%94%98%E9%9D%92%E8%97%8F%E9%82%8A%E5%8D%80%E8%80%83%E5%AF%9F%E8%A8%98%C2%B7%E7%AC%AC%E4%B8%80%E7%B7%A8.djvu"]'),
('《清江壮歌》', '达州市宣汉县百里峡', '马识途', '现代', '百里峡位于四川省达州市宣汉县境内，是马识途革命题材小说《清江壮歌》的核心背景地。峡谷蜿蜒曲折全长约百余里两岸悬崖峭壁高耸入云谷中溪水奔腾不息。峡谷深处保留着古代驿道遗迹和红军长征时期留下的标语口号红色字迹在岩壁上依稀可辨。百里峡自然风光雄奇壮丽春季山花烂漫夏季绿荫蔽日秋季红叶满山冬季银装素裹。这里兼具自然景观和红色文化资源远离大众旅游路线保持着原始峡谷风貌，是缅怀革命历史和欣赏川东自然山水的难得之地。', '四川', 31.355100, 107.727900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/73/CADAL04601998_%EF%BC%88%E4%B9%BE%E9%9A%86%EF%BC%89%E7%B6%8F%E5%BE%B7%E5%B7%9E%E7%9B%B4%E9%9A%B8%E5%B7%9E%E5%BF%97%E5%85%AB%E5%8D%B7%EF%BC%9A%E5%8D%B7%E4%B8%89%E8%87%B3%E5%8D%B7%E5%9B%9B.djvu"]'),
('《故园六咏》', '成都市金堂县赵镇老码头', '流沙河', '现代', '赵镇老码头位于四川省成都市金堂县赵镇，是诗人流沙河在《故园六咏》中深情吟咏的故乡风景。老码头始建于明清时期青石台阶从街道延伸至沱江岸边至今仍保留着古老的渡船和码头设施。沱江在此穿城而过江水浩荡奔流两岸榕树成荫风光旖旎。码头周围是典型的川西小镇风貌老茶馆小面馆和杂货铺鳞次栉比烟火气息浓郁。清晨江雾弥漫时渡船在晨光中缓缓往返恍如流沙河诗中描绘的旧日光景，赵镇老码头是感受沱江水运文化和体验川西市井生活的真实场所。', '四川', 30.861900, 104.411900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/c1/Lane_of_Huanglongxi.jpg"]'),
('《华阳国志》', '成都市郫都区古城遗址', '常璩', '东晋', '古城遗址位于四川省成都市郫都区，是东晋史学家常璩在《华阳国志》中记载的古蜀国望帝杜宇和丛帝鳖灵的都城遗址。遗址保留了从新石器时代到商周时期的夯土城墙残迹城墙高大厚实，是古蜀文明早期城市建设的重要实证。考古发掘出土了大量陶器石器和玉器等珍贵文物揭示了古蜀先民的生活面貌。遗址周围田畴平旷岷江支流环绕地理环境优越。这里是了解古蜀国历史和早期蜀地文明的重要考古遗址，对研究长江上游古代文明的起源和发展具有重大学术价值。', '四川', 30.810900, 103.887200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/2/22/A_Typical_Linpan_in_Pi_County.jpg"]'),
('《蜀都赋》', '成都市新津区宝墩古城遗址', '左思', '西晋', '宝墩古城遗址位于四川省成都市新津区，是西晋文学家左思在《蜀都赋》中盛赞的古蜀国早期都城遗址之一。遗址距今已有四千多年历史保留了新石器时代晚期的大型夯土城墙和护城壕沟，城墙周长超过六公里规模宏大是成都平原最早的城市遗址。考古发掘揭示了宝墩文化时期古蜀先民的聚落形态农业活动和手工业水平。遗址所在地地势平坦周围水系发达良好的自然条件为古蜀文明的孕育提供了基础。这里是探索成都平原史前文明了解古蜀国起源的关键考古遗址具有极高的历史和学术价值。', '四川', 30.412800, 103.848000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/d9/%E6%96%B0%E6%B4%A5%E8%A7%82%E9%9F%B3%E5%AF%BA%E7%85%A7%E7%89%87.JPG"]'),
('《剑阁铭》', '广元市剑阁县剑门关古驿道北段', '张载', '西晋', '剑门关古驿道北段位于四川省广元市剑阁县境内，是西晋文学家张载撰写《剑阁铭》的灵感之地。古驿道以青石板铺就蜿蜒穿行于剑门群山之间，两旁峭壁如削山势极为险峻。道路沿途保留着多处古关隘遗迹和历代文人题刻，见证了千年蜀道的兴衰更替。张载的剑阁铭刻于崖壁之上警示世人，至今仍可辨识。行走在这段古驿道上仿佛穿越千年历史，脚下的青石板路被无数行人马匹磨得光滑发亮。这里是体验古蜀道雄险壮美和感受西晋文学遗韵的绝佳之地，也是研究古代交通史的重要实物资料。', '四川', 32.287600, 105.525100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/75/%E8%8C%B6%E9%A9%AC%E5%8F%A4%E9%81%93%E9%82%9B%E5%B4%83%E5%A4%B9%E5%85%B3%E5%9B%BD%E4%BF%9D%E7%A2%91.jpg"]'),
('《老成都：芙蓉秋梦》', '成都市成华区东郊记忆老厂房', '流沙河', '现代', '东郊记忆老厂房位于四川省成都市成华区，是诗人流沙河在《老成都：芙蓉秋梦》中回忆的成都工业时代印记。厂房群保留了上世纪五十年代至八十年代的工业建筑风貌，红砖墙体高大的烟囱和锈迹斑斑的机器设备构成独特的工业美学景观。流沙河笔下那个热火朝天的工业建设年代在这里留下了清晰的痕迹。厂房内部空间宽敞高挑钢结构屋架和混凝土地面散发着浓郁的工业风气息。这里是了解成都近现代工业发展史和体验流沙河文学中老成都记忆的独特场所，兼具历史文化价值和独特的建筑审美。', '四川', 30.659900, 104.101700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/a/a2/%E6%B2%88%E9%98%B3%E6%B5%91%E6%B2%B3%E5%A4%A7%E6%A1%A5%E5%A4%A9%E9%99%85%E7%BA%BF.jpg"]'),
('《藏地密码》', '甘孜州稻城县亚丁村', '何马', '现代', '亚丁村位于四川省甘孜州稻城县境内，坐落在仙乃日央迈勇夏诺多吉三座神山脚下，是何马长篇小说《藏地密码》中香格里拉的核心原型地。村庄海拔近四千米保留着原始的藏式民居建筑，石砌墙体和经幡飘扬的屋顶与周围雪山冰川草甸融为一体。村中藏族居民延续着传统的生活方式，转山转水转佛塔是日常功课。亚丁的自然风光堪称人间仙境，三座雪山巍峨圣洁冰川湖泊碧蓝如宝石，原始森林和高山草甸色彩斑斓。这里是探寻藏地密码中神秘世界和领略香格里拉绝美风光的理想目的地。', '四川', 29.036900, 100.298300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/0/03/Yading_Jampelyang-Yangmaiyong.jpg"]'),
('《芙蓉城记》', '成都市龙泉驿区洛带古镇金龙湖', '林文询', '现代', '洛带古镇金龙湖位于四川省成都市龙泉驿区，是作家林文询在《芙蓉城记》中描绘的成都近郊名胜。湖畔保留着历史悠久的金龙寺和古驿道遗迹，寺院殿宇古朴典雅香火缭绕。金龙湖水面开阔波光粼粼四周山丘环抱绿树成荫。每到春日湖边桃花盛开满目粉红如霞似锦，秋季银杏金黄落叶铺地宛如金色地毯。古驿道从湖边蜿蜒而过青石板路连接着洛带古镇的客家围屋和古街巷。这里远离古镇核心商业区游客稀少，是享受成都近郊自然风光和感受林文询笔下芙蓉城诗意的清幽之所。', '四川', 30.556600, 104.274900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/1e/Longquan_mountains.jpg"]'),
('《川北往事》', '广元市旺苍县木门古镇', '贺享雍', '现代', '木门古镇位于四川省广元市旺苍县境内，是作家贺享雍《川北往事》中描绘的川北重要商贸古镇。古镇保留了完整的明清古街格局，青石板路两旁是典型的川北穿斗式木构民居，翘角飞檐错落有致。镇中的木门寺始建于唐代历史悠久，寺内古木参天碑刻林立。木门古镇曾是米仓古道上的重要驿站和商贸集散地，南来北往的商旅在此歇脚交易留下了丰富的历史遗迹。这里远离现代旅游开发保持着川北乡镇最原始的生活状态，是体验贺享雍笔下川北乡村社会和感受米仓古道商旅文化的绝佳去处。', '四川', 32.228500, 106.289800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/0/0d/Location_of_Wangcang_within_Sichuan_%28China%29.png"]'),
('《石壕吏》', '三门峡市陕州区石壕村', '杜甫', '唐代', '石壕村位于河南省三门峡市陕州区境内，是唐代伟大诗人杜甫名篇《石壕吏》的真实发生地。村中保留了清代至民国时期的豫西传统民居和老窑洞，黄土夯筑的墙体和拱形窑洞门洞记录着中原农村的建筑智慧。村口竖立着石壕吏遗址石碑标记着这段悲壮历史的发生地。杜甫当年途经此地目睹官吏深夜捉人充军的惨状，愤而写下了这首千古绝唱。村庄四周黄土丘陵起伏田野阡陌纵横，保持着与唐代相去不远的乡村面貌。这里是感受杜甫现实主义诗歌力量和了解唐代安史之乱对普通百姓影响的重要历史遗址。', '河南', 34.720500, 111.102700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/3f/State_Council_Gazette_-_2019_-_Issue_30.pdf"]'),
('《将进酒》', '商丘市睢阳区梁园遗址', '李白', '唐代', '梁园遗址位于河南省商丘市睢阳区境内，是唐代诗仙李白创作千古名篇《将进酒》的灵感之地。梁园始建于西汉时期为梁孝王刘武所建的皇家园林，当年规模宏大亭台楼阁林立。如今遗址保留着汉代夯土台基和部分建筑基址，虽已不见当年盛景但依然能感受到皇家园林的恢弘气势。李白曾多次游访梁园与好友高适杜甫等在此饮酒赋诗，人生得意须尽欢的豪迈之情由此而发。遗址周围是广阔的豫东平原田野辽阔天高地远，是追寻李白诗酒豪情和了解西汉皇家园林文化的重要历史遗迹。', '河南', 34.415300, 115.653100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/c7/%E6%B2%B3%E5%8D%97%E7%9C%81%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E6%B2%B3%E5%8D%97%E7%9C%81%E7%AC%AC%E4%B8%83%E6%89%B9%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E5%90%8D%E5%8D%95%E7%9A%84%E9%80%9A%E7%9F%A5%EF%BC%88%E8%B1%AB%E6%94%BF%E3%80%942016%E3%80%954%E5%8F%B7%EF%BC%89.pdf"]'),
('《赋得古原草送别》', '郑州市新郑市白居易故里古原', '白居易', '唐代', '白居易故里古原位于河南省郑州市新郑市境内，是唐代大诗人白居易少年生活之地，也是千古名篇《赋得古原草送别》的创作灵感来源。故里保留了唐代草原的自然风貌和白居易故居遗迹，原野上芳草萋萋随风起伏一望无际。白居易十六岁时以此地草原为题写下离离原上草一岁一枯荣的不朽诗句，展现了非凡的文学才华。故居周围田园阡陌纵横古朴的村落散布其间，与诗中描绘的送别场景高度吻合。这里是了解白居易少年成长经历和感受唐诗中原野送别意境的重要文学遗址。', '河南', 34.395300, 113.740000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/de/Zhengzhou_CBDcity.jpg"]'),
('《九月九日忆山东兄弟》', '焦作市修武县云台山茱萸峰重阳阁遗址', '王维', '唐代', '云台山茱萸峰重阳阁遗址位于河南省焦作市修武县境内，是唐代大诗人王维创作《九月九日忆山东兄弟》的灵感之地。遗址保留着唐代阁基和古碑，阁基石砌结构依稀可辨当年建筑规模。茱萸峰海拔较高峰顶视野开阔，每到秋日满山茱萸果实红透如火与金黄秋叶交相辉映色彩绚烂。王维当年登高远望思念远方亲人写下了每逢佳节倍思亲的千古名句感人至深。这里远离云台山核心景区的喧嚣游客稀少，是重阳节登高怀远和感受王维诗歌中思乡之情的最佳去处。', '河南', 35.223400, 113.447700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/9b/%E5%8D%97%E9%98%B3%E7%9F%A5%E5%BA%9C%E8%A1%99%E9%97%A8_2025-06-02_02.jpg"]'),
('《左迁至蓝关示侄孙湘》', '三门峡市卢氏县蓝关古道遗址', '韩愈', '唐代', '蓝关古道遗址位于河南省三门峡市卢氏县境内，是唐代文学家韩愈被贬潮州途中创作《左迁至蓝关示侄孙湘》的历史古道。古道始建于唐代是长安通往东南地区的重要驿路，道路以青石铺就蜿蜒于崇山峻岭之间。沿途保留着唐代驿路遗迹和古关隘残存，两旁山势陡峭林木葱茏人迹罕至。韩愈当年冒雪行经此道写下了云横秦岭家何在雪拥蓝关马不前的悲壮诗句。古道周围山高谷深自然风光原始苍茫，是追寻韩愈被贬之路和感受唐代驿道文化的珍贵历史遗存。', '河南', 34.054000, 111.047600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/75/%E8%8C%B6%E9%A9%AC%E5%8F%A4%E9%81%93%E9%82%9B%E5%B4%83%E5%A4%B9%E5%85%B3%E5%9B%BD%E4%BF%9D%E7%A2%91.jpg"]'),
('《清明》', '商丘市永城市杏花村', '杜牧', '唐代', '杏花村位于河南省商丘市永城市境内，被认为是唐代诗人杜牧名篇《清明》中借问酒家何处有牧童遥指杏花村的原型地之一。村中保留了明清时期的古民居建筑和传统老酒馆，青砖灰瓦的豫东民居错落排列古朴典雅。每到春日杏花盛开时满村花海如云似雪清香扑鼻，与杜牧诗中描绘的景象高度吻合。村中老酒馆延续着传统酿酒工艺，醇香的老酒和热情的乡民让人仿佛置身诗境之中。这里远离都市喧嚣保持着豫东乡村的质朴本色，是清明时节赏花品酒和感受唐诗意境的绝佳去处。', '河南', 33.929400, 116.449500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/91/%E5%A4%A9%E9%B9%85%E6%B9%96.jpg"]'),
('《宿骆氏亭寄怀崔雍崔衮》', '郑州市中牟县骆氏亭遗址', '李商隐', '唐代', '骆氏亭遗址位于河南省郑州市中牟县境内，是唐代诗人李商隐创作《宿骆氏亭寄怀崔雍崔衮》的历史遗迹。遗址保留着唐代池岸亭基和古荷池的轮廓，虽经千年风雨侵蚀但依然能辨识当年的建筑格局。荷池虽已不见盛夏荷花满塘的盛景但残存的池岸和亭基诉说着往日的雅致。李商隐当年在此独宿感时伤怀写下了秋阴不散霜飞晚留得枯荷听雨声的千古名句。遗址周边环境静谧田野开阔，是感受李商隐诗歌中那种凄美幽远意境和了解唐代文人交游文化的珍贵历史遗址。', '河南', 34.719000, 114.022100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/70/ChinaShangqiuXiayi.png"]'),
('《逢入京使》', '三门峡市灵宝市函谷关古道遗址', '岑参', '唐代', '函谷关古道遗址位于河南省三门峡市灵宝市境内，是唐代边塞诗人岑参创作《逢入京使》时经过的重要关隘。函谷关始建于先秦时期是中国历史上最早的雄关之一，自古为兵家必争之地。遗址保留了先秦时期开辟的驿路和汉代重建的关隘建筑基址，黄土夯筑的关墙虽已残破但依然透露着当年的雄伟气势。岑参西行途中在此遇到入京使者托其传话写下了马上相逢无纸笔凭君传语报平安的动人诗篇。古道两旁黄土丘陵起伏景色苍茫壮阔，是感受唐代边塞诗人豪迈情怀和了解古代关隘文化的重要历史遗址。', '河南', 34.516800, 110.894800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/cd/%E6%B2%B3%E5%8D%97%E7%81%B5%E5%AE%9D%E5%87%BD%E8%B0%B7%E5%85%B3.jpg"]'),
('《过故人庄》', '南阳市新野县樊集乡故人庄遗址', '孟浩然', '唐代', '故人庄遗址位于河南省南阳市新野县樊集乡境内，是唐代山水田园诗人孟浩然名篇《过故人庄》的原型地。遗址保留着典型的豫南传统民居老槐树和古井，黄土墙青瓦顶的农舍错落分布在田野之间。村中百年老槐树枝繁叶茂古井清水甘甜，田园阡陌纵横稻田与菜畦交错分布。孟浩然当年受友人邀请来此做客写下了绿树村边合青山郭外斜的田园诗篇。整个村庄保持着与唐代极为相似的田园风貌，炊烟升起鸡犬相闻，是体验孟浩然诗歌中田园牧歌生活和感受豫南乡村淳朴民风的理想去处。', '河南', 32.520600, 112.360000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/6/62/Han_Guangwu_Di.jpg"]'),
('《南山田中行》', '洛阳市宜阳县花果山古道遗址', '李贺', '唐代', '花果山古道遗址位于河南省洛阳市宜阳县境内，是唐代诗鬼李贺创作《南山田中行》的灵感之地。古道始建于唐代沿山势蜿蜒而上两旁密林环抱古寺掩映其间。李贺生于宜阳常在此山中漫步采风，以独特的想象力描绘出南山田中行的奇幻意象。每到秋日漫山红叶如火似锦层林尽染色彩斑斓蔚为壮观。古道沿途可见唐代驿路遗迹和古寺建筑基址，石板路面被岁月侵蚀但古韵犹存。这里远离城市游客极少，是追寻李贺诗歌创作足迹和感受唐代洛阳近郊山水风光的绝佳去处。', '河南', 34.514900, 112.179100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/b/b4/27427-Luoyang_%2849067744628%29.jpg"]'),
('《和子由渑池怀旧》', '三门峡市渑池县崤函古道遗址', '苏轼', '北宋', '崤函古道遗址位于河南省三门峡市渑池县境内，是北宋文豪苏轼创作《和子由渑池怀旧》的历史背景地。崤函古道是古代中原通往关中的咽喉要道，地势险要两山夹峙。遗址保留着唐代车辙印痕和古关隘遗迹，深深的车辙刻入石板路面见证了千年商旅往来的繁忙。苏轼与弟弟苏辙曾途经此地在僧舍壁上题诗，后来苏轼感慨人生如飞鸿踏雪写下了这首怀旧名篇。古道两旁黄土崖壁高耸峡谷幽深，是了解古代中原交通要道和感受苏轼人生哲思的重要历史遗迹。', '河南', 34.767200, 111.761700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/cd/%E6%B2%B3%E5%8D%97%E7%81%B5%E5%AE%9D%E5%87%BD%E8%B0%B7%E5%85%B3.jpg"]'),
('《别董大・其一》', '商丘市睢阳区文雅台遗址', '高适', '唐代', '文雅台遗址位于河南省商丘市睢阳区境内，是唐代边塞诗人高适创作《别董大》的历史地点。文雅台相传为孔子周游列国时在宋国讲学之处，始建于春秋时期。遗址保留着汉代夯土台基和历代碑刻，台基高大厚实气势恢宏。高适与琴师董大在此依依惜别写下了莫愁前路无知己天下谁人不识君的豪迈诗句。台基周围是广阔的豫东平原视野开阔天高云淡，千年古台矗立于原野之上更显苍凉壮美。这里是感受高适送别诗中那份豁达豪迈和了解孔子讲学历史的文化胜地。', '河南', 34.415300, 115.653100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/a/a5/20220726_Historic_City_of_Shangqiu_01.jpg"]'),
('《蒿里行》', '许昌市建安区汉魏故城遗址', '曹操', '东汉', '汉魏故城遗址位于河南省许昌市建安区境内，是东汉末年曹操挟天子以令诸侯的都城所在地，也是曹操名篇《蒿里行》的创作背景地。遗址保留了汉代夯土城墙和铜雀台残迹，城墙虽已残破但仍可见当年宏大规模。铜雀台遗址高台耸立可以想见当年曹操大宴群臣横槊赋诗的盛况。曹操目睹战乱之苦在此写下了白骨露于野千里无鸡鸣的悲怆诗句，深刻反映了东汉末年的社会惨状。遗址周围田野辽阔古城墙沿线遗迹丰富，是了解三国历史和感受建安文学的重要考古遗址。', '河南', 34.003500, 113.822700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/87/20260111_View_of_Xuchang_from_Guansheng_Hall.jpg"]'),
('《洛神赋》（诗体）', '洛阳市洛龙区洛浦公园古洛河段', '曹植', '三国魏', '洛浦公园古洛河段位于河南省洛阳市洛龙区境内，是三国时期文学家曹植名篇《洛神赋》中洛神宓妃出没之地。这段洛河保留了最原始的河滩风貌，河水清澈平缓两岸杨柳依依随风摇曳。相传曹植从京城返回封地途经洛水之畔，恍惚间见到洛神翩翩起舞遂写下了翩若惊鸿婉若游龙的不朽名篇。河滩上沙洲错落芦苇丛生水鸟翔集其间，清晨薄雾笼罩河面时更添几分神秘飘渺的仙气。这里远离洛阳城区的喧嚣游客稀少，是感受曹植洛神赋中那种亦真亦幻意境和欣赏洛河自然风光的绝佳去处。', '河南', 34.618600, 112.463600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/c7/%E6%B2%B3%E5%8D%97%E7%9C%81%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E6%B2%B3%E5%8D%97%E7%9C%81%E7%AC%AC%E4%B8%83%E6%89%B9%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E5%90%8D%E5%8D%95%E7%9A%84%E9%80%9A%E7%9F%A5%EF%BC%88%E8%B1%AB%E6%94%BF%E3%80%942016%E3%80%954%E5%8F%B7%EF%BC%89.pdf"]'),
('《游嵩山》', '郑州市登封市嵩山少室山古道遗址', '谢灵运', '南北朝宋', '嵩山少室山古道遗址位于河南省郑州市登封市境内，是南北朝时期山水诗人谢灵运创作《游嵩山》的历史遗迹。古道沿少室山山势蜿蜒而上两旁奇石嶙峋古松苍劲，途中保留着唐代驿路遗迹古寺和摩崖石刻。谢灵运作为山水诗派的开创者曾登临嵩山览胜写下了壮美的山水诗篇。少室山山势险峻峰峦叠嶂云雾缭绕，石刻内容涵盖佛教造像和历代文人题记。古道行走其间脚踏千年石板仰望峭壁摩崖，是体验南北朝山水诗意境和感受嵩山雄险壮美的珍贵历史遗迹。', '河南', 34.453300, 113.050200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/0/09/Shaolinsi.JPG"]'),
('《从军行》', '洛阳市孟津区北邙山古道遗址', '杨炯', '唐代', '北邙山古道遗址位于河南省洛阳市孟津区境内，是唐代诗人杨炯创作《从军行》的历史背景地。古道始建于唐代是洛阳通往关中的重要驿路，沿北邙山脊蜿蜒而行视野开阔。遗址保留着唐代驿路遗迹和沿途分布的大量古墓群，这些墓群从商周延续至唐宋见证了洛阳千年古都的兴衰。杨炯笔下宁为百夫长胜作一书生的豪情壮志与这条通往边关的驿道紧密相连。古道两旁黄土丘陵绵延起伏远眺可见黄河奔流洛阳城郭，景色苍茫壮阔。这里是感受初唐诗人建功立业豪情和了解北邙山帝王将相墓葬文化的重要历史遗址。', '河南', 34.826000, 112.445300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/8b/Sign_of_Tombs_in_Mount_Mang.jpg"]'),
('《如梦令・常记溪亭日暮》', '开封市龙亭区金明池遗址', '李清照', '北宋', '金明池遗址位于河南省开封市龙亭区境内，是北宋女词人李清照创作《如梦令》的历史背景地。金明池始建于北宋太祖时期是皇家御苑中的大型人工湖，当年碧波万顷亭台楼阁倒映水中极为壮丽。遗址保留着宋代池岸和亭台遗迹，虽已不见当年盛景但依然能感受到皇家园林的宏大规模。李清照少女时代常在开封游玩写下了常记溪亭日暮沉醉不知归路的欢快词章。遗址周围地势平坦历史遗迹丰富，是了解北宋皇家园林文化和感受李清照词作中那份天真烂漫少女情怀的珍贵历史遗址。', '河南', 34.815700, 114.354600, '其他', '["https://img1.baidu.com/it/u=1210386552,2750754088&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《秋夜将晓出篱门迎凉有感・其二》', '郑州市巩义市黄河古渡口遗址', '陆游', '南宋', '黄河古渡口遗址位于河南省郑州市巩义市境内，是南宋爱国诗人陆游创作《秋夜将晓出篱门迎凉有感》的情感寄托之地。遗址保留着明清时期的古码头和老渡船遗迹，青石砌筑的码头台阶从河岸延伸至水中。黄河在此奔腾咆哮浊浪滔天气势磅礴，河面宽阔水流湍急令人心生敬畏。陆游虽未亲临此地但以三万里河东入海的壮阔诗句表达了对北方沦陷国土的深切思念。古渡口周围黄河滩涂辽阔远处中原大地一望无际，是感受陆游爱国情怀和体验黄河雄浑气势的重要历史遗址。', '河南', 34.747900, 112.982800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/c7/%E6%B2%B3%E5%8D%97%E7%9C%81%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E6%B2%B3%E5%8D%97%E7%9C%81%E7%AC%AC%E4%B8%83%E6%89%B9%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E5%90%8D%E5%8D%95%E7%9A%84%E9%80%9A%E7%9F%A5%EF%BC%88%E8%B1%AB%E6%94%BF%E3%80%942016%E3%80%954%E5%8F%B7%EF%BC%89.pdf"]'),
('《满江红・写怀》', '开封市祥符区朱仙镇岳飞庙遗址', '岳飞', '南宋', '朱仙镇岳飞庙遗址位于河南省开封市祥符区境内，是南宋抗金名将岳飞创作《满江红》的重要历史背景地。朱仙镇曾是岳飞大败金兵的古战场，这场胜利是南宋抗金战争中的辉煌一页。遗址保留着明代修建的岳飞庙和古战场遗迹，庙中有岳飞塑像和历代碑刻记载着岳飞精忠报国的事迹。岳飞在此写下了壮志饥餐胡虏肉笑谈渴饮匈奴血的豪壮词句，激励了无数后人。庙宇周围古镇风貌犹存青砖灰瓦的老建筑诉说着千年历史，是缅怀民族英雄岳飞和了解南宋抗金历史的重要纪念地。', '河南', 34.756400, 114.441700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/51/20250615_Zhuxian_Yue_Fei_Temple_03.jpg"]'),
('《南都行》', '南阳市卧龙区卧龙岗古柏亭遗址', '李白', '唐代', '卧龙岗古柏亭遗址位于河南省南阳市卧龙区境内，是唐代诗仙李白创作《南都行》时游览的历史名胜。遗址保留着千年古柏和诸葛亮祠堂，古柏苍翠挺拔虬枝盘曲见证了千年岁月变迁。诸葛亮祠堂建筑古朴典雅供奉着诸葛亮塑像和历代碑刻。李白游历南阳时曾到此凭吊诸葛亮感慨万千，将南阳的风物人情融入诗篇。古柏亭周围林木茂密环境幽静，与卧龙岗核心景区相比游客密度较低更适合静心游览。这里是了解诸葛亮隐居历史和感受李白诗歌中南阳风情的重要文化遗址。', '河南', 32.991300, 112.528600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/f/f3/20251004_Temple_of_Marquis_Wu%2C_Nanyang_02.jpg"]');
INSERT INTO works (title, scenic_spot, author, dynasty, description, province, latitude, longitude, category, images) VALUES
('《赠秀才入军・其十四》', '焦作市修武县云台山百家岩遗址', '嵇康', '三国魏', '云台山百家岩遗址位于河南省焦作市修武县境内，是三国时期文学家嵇康创作《赠秀才入军》的历史背景地。百家岩是竹林七贤的主要隐居之地，嵇康阮籍等人在此纵酒放歌弹琴赋诗开创了魏晋风度。遗址保留着魏晋时期的摩崖石刻和古寺建筑基址，石刻内容丰富记载了竹林七贤的隐逸生活。百家岩依山傍水竹林苍翠溪水清澈，自然环境与魏晋名士追求的清静无为理想高度契合。这里远离云台山核心景区游客稀少，是感受魏晋风度和了解竹林七贤隐逸文化的珍贵历史遗址。', '河南', 35.223400, 113.447700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/0/0d/2009_Yuntai_Shan_19.jpg"]'),
('《羑里城》', '安阳市汤阴县羑里城遗址', '韩愈', '唐代', '羑里城遗址位于河南省安阳市汤阴县境内，是唐代文学家韩愈创作《羑里城》诗篇的历史背景地。羑里城是中国有文字记载的第一座国家监狱，商纣王囚禁周文王于此长达七年，文王在狱中推演出了影响深远的《周易》六十四卦。遗址保留了商代夯土城墙和文王庙建筑，城墙厚重坚实见证着三千多年的历史。韩愈到此凭吊感慨文王困厄而作易的坚忍精神写下了深沉的怀古诗篇。遗址周围平原辽阔古城墙巍然矗立，是了解殷商历史和周易文化起源的重要考古遗址。', '河南', 35.921800, 114.357300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/80/20250831_Yue_Fei_Temple_in_Tangyin_01.jpg"]'),
('《鸡公山》', '信阳市浉河区鸡公山报晓峰遗址', '何景明', '明代', '鸡公山报晓峰遗址位于河南省信阳市浉河区境内，是明代文学家何景明创作《鸡公山》的灵感之地。报晓峰形似雄鸡引颈报晓海拔较高视野开阔，是鸡公山的标志性山峰。遗址保留着近代修建的西式别墅和古亭建筑，这些建筑风格多样中西合璧见证了鸡公山作为避暑胜地的辉煌历史。站在报晓峰顶可以俯瞰豫南大别山区的壮美山水，群山叠翠云雾缭绕景色迷人。何景明登临此峰被其雄奇景色打动写下了意境高远的诗篇。这里是欣赏豫南山水风光和感受明代文人登临怀古情怀的理想去处。', '河南', 32.116900, 114.058800, '其他', '["https://img1.baidu.com/it/u=2604087634,3897817864&fm=253&fmt=auto&app=120&f=JPEG?w=500&h=889"]'),
('《鲁山山行》', '平顶山市鲁山县尧山古道遗址', '梅尧臣', '北宋', '尧山古道遗址位于河南省平顶山市鲁山县境内，是北宋诗人梅尧臣创作《鲁山山行》的历史背景地。古道始建于唐代沿尧山山势蜿蜒而上两旁古木参天溪流潺潺。遗址保留着唐代驿路遗迹和古寺建筑基址，石板路面被岁月侵蚀但古韵犹存。梅尧臣秋日行走于此被满山红叶的壮美景色打动写下了霜落熊升树林空鹿饮溪的生动诗句。每到秋季尧山红叶满山层林尽染从山脚到山顶色彩渐变如同一幅巨大的油画。这里是感受北宋诗人山行乐趣和欣赏尧山秋日红叶的绝佳去处。', '河南', 33.738800, 112.907900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/c7/Wugongshan_8350.jpg"]'),
('《宋中十首・其二》', '商丘市永城市芒砀山斩蛇碑遗址', '高适', '唐代', '芒砀山斩蛇碑遗址位于河南省商丘市永城市境内，是唐代边塞诗人高适创作《宋中十首》的历史背景地之一。芒砀山是汉高祖刘邦斩蛇起义的发生地，开创了大汉四百年基业。遗址保留着汉代斩蛇碑和高祖庙建筑，碑石古朴厚重铭刻着这段开国传奇。高适游历至此感慨历史兴亡写下了深沉的怀古诗篇。芒砀山虽不高大但历史积淀深厚，山中还有大量汉代墓葬和石刻艺术。这里是了解秦末汉初历史风云和感受高适怀古诗意境的重要文化遗址，也是探访刘邦起义原点的理想去处。', '河南', 33.929400, 116.449500, '其他', '["https://img2.baidu.com/it/u=4233433930,3815404839&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=656"]'),
('《太昊伏羲庙》', '周口市淮阳区太昊陵蓍草园遗址', '苏轼', '北宋', '太昊陵蓍草园遗址位于河南省周口市淮阳区境内，是北宋文豪苏轼创作《太昊伏羲庙》的历史背景地。蓍草园位于太昊陵核心区域种植着用于占卜的千年蓍草，传说伏羲氏在此观天察地画八卦开创了华夏文明。遗址保留着伏羲画卦台和历代碑刻，八卦台古朴庄重承载着中华民族对始祖的崇敬。蓍草四季常青叶片修长在风中摇曳发出沙沙声响，相传聆听蓍草之声可通天地之理。苏轼到此朝拜写下了对伏羲文化的赞颂诗篇。这里是了解伏羲文化和八卦起源以及感受中华文明根源的重要祭祀遗址。', '河南', 33.732000, 114.886200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/5e/%E5%8D%88%E6%9C%9D%E9%97%A8_-_panoramio.jpg"]'),
('《嵖岈山》', '驻马店市遂平县嵖岈山黑风洞遗址', '贾岛', '唐代', '嵖岈山黑风洞遗址位于河南省驻马店市遂平县境内，是唐代苦吟诗人贾岛创作《嵖岈山》的灵感之地。嵖岈山山势奇特怪石嶙峋形态各异，黑风洞是山中最大的天然溶洞洞内幽深曲折钟乳石千姿百态。遗址保留着唐代摩崖石刻和古寺建筑基址，石刻题记记录了历代文人墨客到此游览的感悟。贾岛被嵖岈山的奇特地貌所吸引以其独特的苦吟风格写下了意境深远的诗篇。山中奇峰林立峡谷幽深溶洞密布，春日山花烂漫秋日层林尽染四季皆有不同景致。这里是感受唐代苦吟诗风和欣赏嵖岈山奇特地貌的绝佳去处。', '河南', 33.145900, 114.013000, '其他', '["https://img2.baidu.com/it/u=2316126904,2223256072&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1062"]'),
('《登广武山怀古》', '郑州市荥阳市广武山古战场遗址', '李白', '唐代', '广武山古战场遗址位于河南省郑州市荥阳市境内，是唐代诗仙李白创作《登广武山怀古》的历史背景地。广武山是楚汉相争时期著名的鸿沟所在地，刘邦项羽在此对峙划分天下。遗址保留着汉代鸿沟遗迹和古城墙残存，鸿沟虽已干涸但深深的沟壑依然可辨当年天堑的险要。古城墙夯土结构厚重坚实矗立于山巅之上俯瞰中原大地。李白登临此山怀古伤今写下了气势磅礴的诗篇。站在古战场遗址上远眺黄河和中原平原，可以深切感受到楚汉争霸的历史风云和李白怀古诗中那种纵横古今的豪迈气概。', '河南', 34.787600, 113.383100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/de/Zhengzhou_CBDcity.jpg"]'),
('《汴河怀古・其二》', '开封市禹王台区汴河遗址', '皮日休', '唐代', '汴河遗址位于河南省开封市禹王台区境内，是唐代诗人皮日休创作《汴河怀古》的历史背景地。汴河是隋唐大运河的核心河段连接南北是古代中国最重要的水上交通动脉之一。遗址保留着唐代河道轮廓和码头遗迹，河道虽已干涸但宽阔的河床依然可见当年漕运繁忙的盛况。码头遗迹的青石台阶和系船石柱诉说着千年水运的辉煌。皮日休在此感慨隋炀帝开凿运河的功过写下了尽道隋亡为此河至今千里赖通波的深刻诗句。这里是了解隋唐大运河历史和感受皮日休怀古诗思辨精神的重要水利遗址。', '河南', 34.776800, 114.347600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/c7/%E6%B2%B3%E5%8D%97%E7%9C%81%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E6%B2%B3%E5%8D%97%E7%9C%81%E7%AC%AC%E4%B8%83%E6%89%B9%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E5%90%8D%E5%8D%95%E7%9A%84%E9%80%9A%E7%9F%A5%EF%BC%88%E8%B1%AB%E6%94%BF%E3%80%942016%E3%80%954%E5%8F%B7%EF%BC%89.pdf"]'),
('《送杜审言》', '洛阳市偃师区首阳山遗址', '宋之问', '唐代', '首阳山遗址位于河南省洛阳市偃师区境内，是唐代诗人宋之问创作《送杜审言》的历史背景地。首阳山相传为商末伯夷叔齐不食周粟采薇而死的隐居地，以节义精神闻名千古。遗址保留着商代修建的夷齐庙和历代古碑，庙宇建筑古朴典雅碑刻内容丰富记载了伯夷叔齐的事迹和历代文人的凭吊诗文。宋之问在此送别好友杜审言以首阳山的典故寄托深厚情谊。山势不高但苍松翠柏环绕环境清幽，是了解商周历史和伯夷叔齐气节文化以及感受唐代送别诗情怀的重要文化遗址。', '河南', 34.727200, 112.789400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/4e/20240815_Cityscape_of_Yanshi.jpg"]'),
('《黄河东流去》', '周口市西华县逍遥镇老街区', '李准', '现代', '逍遥镇老街区位于河南省周口市西华县境内，是现代作家李准长篇小说《黄河东流去》的重要历史背景地。1938年黄河花园口决堤是中国近代史上最惨烈的人为灾难之一，洪水淹没了豫东大片土地逍遥镇深受其害。老街区保留着清末民初的豫东民居建筑和百年历史的胡辣汤老店，砖木结构的老屋斑驳沧桑诉说着那段苦难岁月。李准以此为背景创作了反映黄泛区人民苦难与抗争的史诗巨著。逍遥镇胡辣汤闻名全国至今老街上仍有多家传承数代的胡辣汤店铺，是了解黄泛区历史和品尝正宗逍遥镇胡辣汤的独特去处。', '河南', 33.767200, 114.529800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/38/20240826_Jizi_Lake_in_Xihua.jpg"]'),
('《一句顶一万句》', '新乡市延津县老县城西街', '刘震云', '现代', '延津县老县城西街位于河南省新乡市延津县境内，是现代作家刘震云延津系列小说的核心原型地。刘震云出生于延津，他笔下的故乡人事皆以此为蓝本。老县城西街保留着明清时期的古民居和老县衙遗址，青砖灰瓦的建筑沿街排列古巷幽深曲折。《一句顶一万句》中杨百顺等人物的生活场景都能在这条老街上找到对应。刘震云以平实幽默的笔触描绘了豫北乡镇小人物的悲欢离合，真实展现了中原腹地的世俗人情。老街商业化程度极低保持着原汁原味的豫北小城风貌，是感受刘震云文学世界和了解豫北乡土文化的重要去处。', '河南', 35.141600, 114.205500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/c7/%E6%B2%B3%E5%8D%97%E7%9C%81%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E6%B2%B3%E5%8D%97%E7%9C%81%E7%AC%AC%E4%B8%83%E6%89%B9%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E5%90%8D%E5%8D%95%E7%9A%84%E9%80%9A%E7%9F%A5%EF%BC%88%E8%B1%AB%E6%94%BF%E3%80%942016%E3%80%954%E5%8F%B7%EF%BC%89.pdf"]'),
('《我不是潘金莲》', '开封市兰考县东坝头乡张庄村', '刘震云', '现代', '张庄村位于河南省开封市兰考县东坝头乡境内，是现代作家刘震云小说《我不是潘金莲》中李雪莲故乡的原型地。张庄村地处黄河故道旁保留着传统的豫东土坯房建筑和黄河大堤遗迹，房屋低矮朴素以黄土夯筑而成带有浓郁的豫东乡土气息。黄河大堤蜿蜒于村旁见证了黄河多次改道的沧桑历史。刘震云以细腻深刻的笔触塑造了执拗倔强的农村妇女形象，反映了基层社会的世态人情。这里也是焦裕禄精神的发源地之一，兼具文学价值和红色文化意义，是了解豫东农村风貌和当代文学创作背景的重要村落。', '河南', 34.822100, 114.821300, '其他', '["https://img0.baidu.com/it/u=3826047127,1049273168&fm=253&fmt=auto&app=120&f=JPEG?w=664&h=443"]'),
('《日光流年》', '洛阳市嵩县田湖镇程村', '阎连科', '现代', '程村位于河南省洛阳市嵩县田湖镇境内，是现代作家阎连科长篇小说《日光流年》中三姓村的原型地。程村地处豫西山区保留着传统的黄土窑洞和石板房建筑，窑洞依山而挖冬暖夏凉是豫西山区最具特色的民居形式。石板房以当地片石砌筑质朴厚重与黄土高坡浑然一体。阎连科以魔幻现实主义手法描绘了三姓村人世代与命运抗争的悲壮故事，深刻展现了豫西山区人民的坚韧生命力。村庄周围群山环绕梯田层叠溪水潺潺，保持着原始的乡村风貌。这里是感受阎连科文学世界和了解豫西窑洞文化的重要乡村遗存。', '河南', 34.134500, 112.085300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/c7/%E6%B2%B3%E5%8D%97%E7%9C%81%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E6%B2%B3%E5%8D%97%E7%9C%81%E7%AC%AC%E4%B8%83%E6%89%B9%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E5%90%8D%E5%8D%95%E7%9A%84%E9%80%9A%E7%9F%A5%EF%BC%88%E8%B1%AB%E6%94%BF%E3%80%942016%E3%80%954%E5%8F%B7%EF%BC%89.pdf"]'),
('《受活》', '平顶山市鲁山县尧山镇想马河村', '阎连科', '现代', '想马河村位于河南省平顶山市鲁山县尧山镇境内，是现代作家阎连科长篇小说《受活》中受活庄的原型地。想马河村地处豫西山区深处保留着原始的豫西民居建筑和传统水磨房，石砌房屋依山势错落分布村中溪水穿流其间水磨房仍可运转。阎连科在此获取了大量创作素材以荒诞的笔触揭示了中国农村社会的深层矛盾。村庄四周群山环抱山高林密与外界相对隔绝，保持着难得的原生态乡村面貌。春日山花烂漫夏日绿树成荫秋日红叶满山冬日白雪皑皑四季风光各异。这里是体验豫西原始乡村生活和了解阎连科文学创作源泉的珍贵去处。', '河南', 33.738800, 112.907900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/ef/The_Songshan_Buddhist_Academy_Lied_in_Mount_Song.jpg"]'),
('《湖光山色》', '南阳市淅川县盛湾镇鱼关村', '周大新', '现代', '鱼关村位于河南省南阳市淅川县盛湾镇境内，是现代作家周大新长篇小说《湖光山色》中楚王庄的原型地。鱼关村坐落在丹江口水库之畔，保留着传统的豫南民居和老码头遗迹。青砖黛瓦的房屋掩映在青山绿水之间与碧波荡漾的丹江口水库相映成趣构成了一幅优美的山水画卷。周大新以此为原型创作了描绘南水北调工程移民生活变迁的动人故事，展现了库区人民的牺牲与奉献。丹江口水库水质清澈是南水北调中线工程的水源地，湖光山色美不胜收。这里是了解南水北调历史和欣赏丹江口水库风光的重要文化村落。', '河南', 33.137100, 111.490800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/87/ChinaNanyangXichuan.png"]'),
('《第二十幕》', '南阳市社旗县赊店古镇瓷器街', '周大新', '现代', '赊店古镇瓷器街位于河南省南阳市社旗县境内，是现代作家周大新长篇小说《第二十幕》的重要历史背景地。赊店古镇始建于汉代是明清时期中原最重要的商贸重镇之一，瓷器街更是当年瓷器集散中心商贾云集。老街保留着明清时期的古商铺和老会馆建筑，雕梁画栋砖雕石雕工艺精湛展现了当年商业繁华。周大新以赊店古镇百年商业兴衰为背景创作了这部展现中国瓷业命运的长篇小说。古镇中山陕会馆气势恢宏是全国重点文物保护单位，火神庙和关帝庙也保存完好。这里是了解明清中原商业文化和感受周大新文学作品历史厚度的理想去处。', '河南', 33.056300, 112.947900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/7f/20251004_Ciqi_Street_04.jpg"]'),
('《雍正皇帝》', '南阳市内乡县内乡县衙', '二月河', '现代', '内乡县衙位于河南省南阳市内乡县境内，是现代作家二月河长篇历史小说《雍正皇帝》的重要创作参考地。内乡县衙是中国保存最完整的清代县级官署衙门，被誉为神州大地绝无仅有的历史标本。衙门保留着清代大堂二堂三堂和监狱等完整的行政司法建筑群，照壁仪门大堂依次排列气势庄严。二月河在创作清帝系列小说时多次考察县衙建筑格局，将其融入对清代官场制度的细致描写。大堂上悬挂的天理国法人情匾额和堂前的戒石铭彰显着古代地方治理的理念。这里是了解清代行政司法制度和感受二月河历史小说创作背景的重要古建筑遗存。', '河南', 33.044900, 111.849400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/1c/%E5%86%85%E4%B9%A1%E5%8E%BF%E8%A1%99%E6%AD%A3%E5%A0%822019.jpg"]'),
('《李自成》', '洛阳市洛宁县闯王寨遗址', '姚雪垠', '现代', '闯王寨遗址位于河南省洛阳市洛宁县境内，是现代作家姚雪垠长篇历史小说《李自成》的重要历史背景地。闯王寨曾是明末农民起义领袖李自成的屯兵之所据山筑寨地势险要易守难攻。遗址保留着明代寨墙和议事厅遗迹，寨墙以巨石砌筑依山势蜿蜒高大厚实可见当年防御工事之坚固。议事厅遗址台基宽阔可以想见当年李自成运筹帷幄的场景。姚雪垠耗费数十年心血创作了这部反映明末农民战争的鸿篇巨制，闯王寨是其中重要的故事发生地。遗址周围群山环绕林木茂密地势隐蔽，是了解明末农民起义历史和感受姚雪垠文学创作精神的重要军事遗址。', '河南', 34.389100, 111.653100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/3f/%E6%9D%8E%E8%87%AA%E6%88%90%E8%A1%8C%E5%AE%AB_%28cropped%29.png"]'),
('《县委书记的榜样 —— 焦裕禄》', '开封市兰考县东坝头乡张庄村', '穆青', '现代', '张庄村位于河南省开封市兰考县东坝头乡境内，是现代记者穆青创作的长篇通讯《县委书记的榜样——焦裕禄》的核心记录区域。焦裕禄在兰考工作期间身先士卒带领群众治理风沙盐碱内涝三害，张庄村是其治沙种树的核心区域。村中保留着焦裕禄旧居和他亲手栽种的焦桐林，焦桐已长成参天大树枝繁叶茂象征着焦裕禄精神的薪火相传。穆青的通讯感动了全国人民焦裕禄成为中国共产党人的精神标杆。村庄周围曾经的沙丘如今已绿树成荫见证了兰考人民几十年治沙造林的伟大成就。这里是学习焦裕禄精神和了解兰考治沙历史的重要红色教育基地。', '河南', 34.822100, 114.821300, '其他', '["https://img0.baidu.com/it/u=3826047127,1049273168&fm=253&fmt=auto&app=120&f=JPEG?w=664&h=443"]'),
('《洛阳牡丹记》', '洛阳市孟津区平乐镇牡丹种植基地', '欧阳修', '北宋', '平乐镇牡丹种植基地位于河南省洛阳市孟津区境内，是北宋文学家欧阳修创作《洛阳牡丹记》的历史背景地。欧阳修在洛阳任职期间深入考察牡丹品种和栽培技艺，写下了中国第一部牡丹专著记录了当时洛阳牡丹的盛况。平乐镇自古就是牡丹种植重镇至今仍种植着上千种牡丹品种，每到春季花开时节姹紫嫣红满目芬芳蔚为壮观。与洛阳市区的王城公园相比，平乐镇的牡丹田园风格更为质朴自然游客密度也低得多，可以从容地欣赏牡丹花开的盛景。基地周围还有大量农户世代传承着牡丹栽培技艺，是了解洛阳牡丹文化和欧阳修花卉著作的理想去处。', '河南', 34.826000, 112.445300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/51/20231119_Yingtian_Gate_02.jpg"]'),
('《游嵩山日记》', '郑州市登封市嵩山三皇寨悬空栈道', '徐霞客', '明代', '嵩山三皇寨悬空栈道位于河南省郑州市登封市境内，是明代旅行家徐霞客创作《游嵩山日记》时攀登的险峻路段。三皇寨悬空栈道依悬崖峭壁而建下临万丈深渊凌空飞架气势惊人。栈道全程蜿蜒于嵩山南麓的陡峭山壁之上，脚下云雾缭绕峡谷深邃令人胆战心惊。徐霞客当年攀登嵩山时被这段险路所震撼在游记中留下了详细的描述。栈道两侧石壁上保留着历代摩崖石刻和地质奇观，嵩山独特的石英岩地貌在此展现得淋漓尽致。春日山花点缀于峭壁之间秋日红叶映衬着灰白岩壁色彩绚丽。这里是体验嵩山险峻雄奇和追随徐霞客足迹的最佳户外探险路线。', '河南', 34.453300, 113.050200, '其他', '["https://img1.baidu.com/it/u=3916536653,694399966&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=652"]'),
('《水经注・伊水注》', '洛阳市栾川县老君山追梦谷', '郦道元', '北魏', '老君山追梦谷位于河南省洛阳市栾川县境内，是北魏地理学家郦道元《水经注·伊水注》中记载的伊水源头之一。追梦谷深藏于老君山腹地保留着最原始的自然风貌，溪流潺潺从山石间奔涌而出清澈见底。峡谷两侧崖壁陡峭古木参天藤萝垂挂，原始森林遮天蔽日行走其间仿佛置身于世外桃源。郦道元在水经注中详细记载了伊水的源头和流向，追梦谷的溪水正是伊水的重要源头之一。谷中瀑布飞泻潭水碧绿山花烂漫鸟鸣啾啾，空气清新负氧离子含量极高。这里是感受郦道元水经注中山水描绘和体验老君山原始自然风光的绝佳去处。', '河南', 33.785500, 111.617700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/ef/The_Songshan_Buddhist_Academy_Lied_in_Mount_Song.jpg"]'),
('《史记・陈涉世家》', '周口市太康县陈集乡陈涉故里', '司马迁', '西汉', '陈涉故里位于河南省周口市太康县陈集乡境内，是西汉史学家司马迁《史记·陈涉世家》所记载的中国第一位农民起义领袖陈胜的出生地。遗址保留着汉代修建的陈涉祠和历代古碑，祠堂建筑朴素庄重碑刻记载了陈胜吴广起义的始末。陈胜少年时在此耕作发出了燕雀安知鸿鹄之志的千古壮语，后率众揭竿而起推翻了暴秦统治。司马迁将陈胜列入世家之中与诸侯并列彰显了其历史地位。祠堂周围是广阔的豫东平原田野阡陌纵横，千年古村保持着质朴的农耕风貌。这里是了解秦末农民起义历史和感受司马迁史记精神的重要文化遗址。', '河南', 34.063700, 114.837800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/f/f4/20220730_Aerial_view_of_Xinzheng_03.jpg"]'),
('《史记・项羽本纪》', '商丘市虞城县营廓镇木兰祠', '司马迁', '西汉', '木兰祠位于河南省商丘市虞城县营廓镇境内，是西汉史学家司马迁《史记·项羽本纪》相关历史区域中花木兰故里的所在地。木兰祠保留着元代修建的木兰祠碑和清代祠堂建筑，元碑详细记载了花木兰替父从军的传奇故事是目前关于木兰身世最早的碑刻文献。祠堂建筑古朴典雅供奉着花木兰塑像和历代碑刻。花木兰代父从军巾帼不让须眉的故事流传千古激励了无数后人。木兰祠周围田野平坦村庄安静保持着豫东乡村的原始风貌。每年花木兰纪念日当地都会举办隆重的祭祀活动。这里是了解花木兰传奇故事和感受巾帼精神的重要文化纪念地。', '河南', 34.400600, 115.828300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/a/a5/20220726_Historic_City_of_Shangqiu_01.jpg"]'),
('《后汉书・张衡传》', '南阳市卧龙区石桥镇张衡墓', '范晔', '南朝宋', '张衡墓位于河南省南阳市卧龙区石桥镇境内，是南朝宋史学家范晔在《后汉书·张衡传》中记载的东汉伟大科学家张衡的安葬地。张衡发明了世界上第一台地动仪和浑天仪是中国古代最杰出的科学家之一。墓园保留着汉代墓冢和张衡博物馆，墓冢封土高大松柏环绕庄严肃穆。博物馆内陈列着张衡生平事迹和科学成就的详细介绍以及地动仪浑天仪的复原模型。墓园环境清幽古柏苍翠与南阳盆地的田园风光相融合。这里是了解张衡科学成就和东汉科技文明以及感受古代中国科学家精神的重要纪念场所。', '河南', 32.991300, 112.528600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/9b/%E5%8D%97%E9%98%B3%E7%9F%A5%E5%BA%9C%E8%A1%99%E9%97%A8_2025-06-02_02.jpg"]'),
('《归田赋》', '南阳市宛城区白河湿地公园老河段', '张衡', '东汉', '白河湿地公园老河段位于河南省南阳市宛城区境内，是东汉科学家文学家张衡创作《归田赋》的情感寄托之地。白河是南阳的母亲河，老河段保留着最原始的河道风貌河水清澈平缓。两岸杨柳依依随风摇曳春日嫩绿如烟秋日金黄如画。河面上白鹭纷飞翩翩起舞与碧水蓝天构成一幅优美的田园画卷。张衡晚年厌倦官场回归田园在白河之畔写下了游都邑以永久无明略以佐时的深沉感慨。湿地公园老河段远离城区喧嚣游人稀少，保持着自然生态的原始状态芦苇荡漾水草丰茂。这里是感受张衡归田赋中淡泊情怀和欣赏南阳白河自然风光的宁静去处。', '河南', 33.003700, 112.539500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/51/20231119_Yingtian_Gate_02.jpg"]'),
('《三都赋・魏都赋》', '洛阳市偃师区汉魏洛阳故城遗址', '左思', '西晋', '汉魏洛阳故城遗址位于河南省洛阳市偃师区境内，是西晋文学家左思创作《三都赋·魏都赋》的历史背景地。汉魏洛阳故城是东汉至北魏时期的国都遗址历经数百年营建规模宏大。遗址保留着汉代夯土城墙和永宁寺塔基等重要遗迹，城墙虽经千年风雨仍残存数段高大厚实气势恢宏。永宁寺塔基是北魏时期全国最高佛塔的基址直径达百米可见当年塔身之巍峨。左思耗费十年心血写成三都赋其中魏都赋详细描绘了洛阳的壮丽景象，一时洛阳纸贵传为千古佳话。遗址面积广大是全国重点文物保护单位，是了解东汉至北魏都城建筑和感受左思文学成就的重要考古遗址。', '河南', 34.727200, 112.789400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/3f/State_Council_Gazette_-_2019_-_Issue_30.pdf"]'),
('《洛神赋》', '洛阳市洛龙区伊洛河交汇处', '曹植', '三国魏', '伊洛河交汇处位于河南省洛阳市洛龙区境内，是三国时期文学家曹植创作名篇《洛神赋》的核心场景发生地。伊河与洛河在此交汇合流形成开阔的水面河滩辽阔沙洲错落。这里保留着最原始的河滩风貌河水清澈两岸绿树成荫。传说曹植从京城返回封地途经洛水在伊洛交汇处恍惚间见到了洛神宓妃的美丽身影遂写下了其翊若将飞竦轻躯以鹤立的不朽名篇。清晨薄雾笼罩水面时河上烟波浩渺恍如仙境，傍晚夕阳映照河面金光粼粼更添几分浪漫诗意。与洛浦公园核心区相比此处更为幽静自然，是感受洛神赋意境和欣赏伊洛河自然风光的绝佳去处。', '河南', 34.618600, 112.463600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/c7/%E6%B2%B3%E5%8D%97%E7%9C%81%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E6%B2%B3%E5%8D%97%E7%9C%81%E7%AC%AC%E4%B8%83%E6%89%B9%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E5%90%8D%E5%8D%95%E7%9A%84%E9%80%9A%E7%9F%A5%EF%BC%88%E8%B1%AB%E6%94%BF%E3%80%942016%E3%80%954%E5%8F%B7%EF%BC%89.pdf"]'),
('《游太行记》', '安阳市林州市太行大峡谷桃花谷', '袁宏道', '明代', '太行大峡谷桃花谷位于河南省安阳市林州市境内，是明代文学家袁宏道创作《游太行记》的重要游历地。桃花谷深藏于太行山腹地保留着最原始的自然风貌，峡谷两侧红色岩壁高耸陡峭溪水在谷底奔流不息。谷中瀑布飞泻潭水碧绿山花烂漫鸟鸣啾啾，春日桃花盛开时满谷粉红如云如霞蔚为壮观。袁宏道以细腻生动的笔触记录了太行山的雄奇壮美，桃花谷正是其中浓墨重彩描绘的景致之一。峡谷中还分布着多处天然溶洞和地质奇观，红色砂岩与碧绿植被形成强烈的色彩对比。这里是体验太行山水之美和追随明代文人游记足迹的户外探险胜地。', '河南', 36.083600, 113.820500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/0/05/Yellowrivermap-zh-hans.jpg"]'),
('《羊的门》', '许昌市鄢陵县陈化店镇许由寨村', '李佩甫', '现代', '许由寨村位于河南省许昌市鄢陵县陈化店镇境内，是现代作家李佩甫长篇小说《羊的门》中呼家堡的原型地之一。许由寨村保留着明代许由寨遗址和数百年历史的古槐树，寨墙遗址依稀可辨见证了中原腹地千年村寨的兴衰变迁。古槐树冠大根深盘虬卧龙是村庄的标志和守护。李佩甫以此为蓝本塑造了一个在中原大地上叱咤风云的乡村强人形象，深刻揭示了中原乡土社会的权力运行逻辑。村庄四周是广阔的花木种植基地春日繁花似锦空气中弥漫着花香。这里是了解李佩甫文学作品和感受中原乡土文化深层肌理的重要乡村遗存。', '河南', 34.102000, 114.177300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/c7/%E6%B2%B3%E5%8D%97%E7%9C%81%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E6%B2%B3%E5%8D%97%E7%9C%81%E7%AC%AC%E4%B8%83%E6%89%B9%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E5%90%8D%E5%8D%95%E7%9A%84%E9%80%9A%E7%9F%A5%EF%BC%88%E8%B1%AB%E6%94%BF%E3%80%942016%E3%80%954%E5%8F%B7%EF%BC%89.pdf"]'),
('《城的灯》', '许昌市禹州市神垕古镇老街', '李佩甫', '现代', '神垕古镇老街位于河南省许昌市禹州市境内，是现代作家李佩甫长篇小说《城的灯》的创作背景地。神垕古镇是中国钧瓷之都有着千年的制瓷历史。老街保留着明清时期的古民居和钧瓷老窑建筑，砖雕门楼雕刻精美老窑内耐火砖垒砌的窑膛诉说着千年窑火不熄的传奇。李佩甫以此为背景描绘了一个农村青年走出乡村追寻城市之光的故事。古镇内至今仍有多家窑口传承着传统的钧瓷烧制技艺，入窑一色出窑万彩的钧瓷令人叹为观止。这里是了解中国钧瓷文化和李佩甫文学作品以及观赏传统手工制瓷技艺的重要文化古镇。', '河南', 34.140700, 113.488000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/39/20240820_Juci_Mountain.jpg"]'),
('《东京梦华录》', '开封市禹王台区繁塔遗址', '孟元老', '南宋', '繁塔遗址位于河南省开封市禹王台区境内，是南宋文人孟元老创作《东京梦华录》时追忆北宋开封繁华景象的重要参照物。繁塔始建于北宋开宝七年是开封现存最古老的佛塔，原为九层因历史变迁现仅存三层但依然气势雄伟。塔身保留着大量宋代佛教石刻和造像，雕刻精美细致入微展现了北宋高超的石刻艺术。孟元老在东京梦华录中详细记载了北宋开封的市井繁华和节庆习俗，繁塔作为当时重要的佛教建筑频繁出现在其记述中。塔周围环境清幽古柏苍翠与开封城的现代喧嚣形成鲜明对比。这里是了解北宋开封历史和宋代佛教艺术的重要古建筑遗存。', '河南', 34.776800, 114.347600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/3f/State_Council_Gazette_-_2019_-_Issue_30.pdf"]'),
('《汴京遗迹志》', '开封市龙亭区北宋皇宫遗址', '李濂', '明代', '北宋皇宫遗址位于河南省开封市龙亭区境内，是明代文人李濂创作《汴京遗迹志》的核心记载对象。北宋皇宫是北宋王朝的政治中心历经九帝一百六十余年，宫殿建筑宏伟壮丽冠绝天下。遗址保留着宋代宫殿基址和柱础石构件，虽然地面建筑早已不存但地下遗迹丰富。李濂在汴京遗迹志中详细记述了北宋皇宫的建筑布局和历史变迁，为后人研究北宋都城提供了珍贵的文献资料。遗址地处开封城中轴线上地势较高，龙亭大殿矗立其上可以俯瞰开封古城全貌。这里是了解北宋皇城规制和开封建都历史的重要考古遗址。', '河南', 34.815700, 114.354600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/59/20250622_Dragon_Pavilion_01.jpg"]'),
('《游清泥河记》', '许昌市襄城县清泥河湿地公园', '苏轼', '北宋', '清泥河湿地公园位于河南省许昌市襄城县境内，是北宋文豪苏轼创作《游清泥河记》的历史背景地。清泥河是襄城县境内的一条古老河流保留着最原始的河道风貌。河水清澈平缓两岸草木繁茂芦苇丛生，春日野花遍野秋日芦花飞雪四季景色各异。苏轼途经襄城时在清泥河畔流连忘返被这里的自然野趣所打动写下了游记。湿地公园内栖息着多种水鸟白鹭翩飞野鸭嬉戏生态环境优良。公园远离城区喧嚣游人稀少保持着难得的自然宁静，是感受苏轼笔下田园野趣和欣赏豫中平原湿地风光的清幽去处。', '河南', 33.851300, 113.507300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/81/Tianjin_Eye_and_Tianjin.jpg"]'),
('《送李愿归盘谷序》', '焦作市济源市盘谷寺', '韩愈', '唐代', '盘谷寺位于河南省焦作市济源市境内，是唐代文学家韩愈创作《送李愿归盘谷序》的历史背景地。盘谷寺依山而建环境清幽是韩愈送别友人李愿隐居之地。韩愈在此写下了膏吾车兮秣吾马从子于盘兮终吾生以徜徉的深情送别名篇。寺院保留着唐代建筑基址和韩愈手书碑刻，碑刻字迹苍劲有力是研究韩愈书法艺术的珍贵实物。盘谷因四面环山中间盘旋如谷而得名，谷中泉水叮咚溪流清澈古木参天环境幽美。这里远离城市喧嚣游客稀少保持着唐代韩愈笔下那种山林隐逸的清幽意境，是了解韩愈散文艺术和体验山林隐逸文化的重要古寺遗存。', '河南', 35.069200, 112.602500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/39/CADAL09010924_%E4%B8%AD%E5%9C%8B%E5%B7%A5%E7%A8%8B%E5%B8%AB%E5%AD%B8%E6%9C%83%E6%9C%83%E5%93%A1%E9%80%9A%E4%BF%A1%E9%8C%84.djvu"]'),
('《少林寺碑记》', '郑州市登封市少林寺初祖庵', '裴漼', '唐代', '少林寺初祖庵位于河南省郑州市登封市境内，是唐代文人裴漼创作《少林寺碑记》的历史背景地。初祖庵是禅宗初祖达摩面壁九年修行的场所，也是中国禅宗的发源地之一。庵堂保留着宋代建筑和达摩面壁洞遗迹，宋代大殿是中国现存最古老的木结构建筑之一斗拱飞檐做工精湛。达摩面壁洞位于五乳峰上洞内幽深相传达摩在此面壁九年身影映入石壁形成面壁影石。裴漼的碑记详细记载了少林寺的建寺历史和禅宗传承。初祖庵位于少林寺后山游客密度远低于少林寺核心区，是了解禅宗起源和欣赏宋代建筑艺术的清幽之地。', '河南', 34.453300, 113.050200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/0/09/Shaolinsi.JPG"]'),
('《河南通志・山川志》', '信阳市浉河区南湾湖茶岛', '田文镜', '清代', '南湾湖茶岛位于河南省信阳市浉河区境内，是清代河南巡抚田文镜编纂《河南通志·山川志》时记载信阳茶区的重要地点。南湾湖碧波万顷湖中岛屿星罗棋布茶岛是其中最具特色的岛屿之一。岛上保留着传统茶园和数百年历史的古茶树，层层叠叠的茶田依山势铺展青翠欲滴。信阳毛尖是中国十大名茶之一，茶岛正是其核心产区之一。每到春季采茶时节身穿布衣的茶农穿梭于茶垄之间手指飞舞采摘嫩芽，清新的茶香弥漫在湖光山色之间。这里是了解信阳毛尖茶文化和欣赏南湾湖山水风光的理想去处。', '河南', 32.116900, 114.058800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/f/fd/Xinyang_city.png"]'),
('《红旗渠》', '安阳市林州市任村镇红旗渠源头', '王立新', '现代', '红旗渠源头位于河南省安阳市林州市任村镇境内，是现代作家王立新创作纪实文学《红旗渠》的核心记录地。红旗渠是二十世纪六十年代林州人民在太行山悬崖绝壁上开凿的人工天河被誉为世界第八大奇迹。源头是红旗渠总干渠的起点保留着明代修建的渠首工程和青年洞等标志性建筑。青年洞凿穿太行山岩石全长六百余米是红旗渠工程中最艰险的路段。渠水从山西漳河引来穿山越岭蜿蜒千里滋润了林州大地。王立新的纪实文学生动再现了林州人民战天斗地的英雄气概。这里是了解红旗渠精神和感受太行山壮美风光的重要红色教育基地。', '河南', 36.083600, 113.820500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/ef/The_Songshan_Buddhist_Academy_Lied_in_Mount_Song.jpg"]'),
('《太行山上》', '安阳市林州市石板岩镇高家台村', '魏巍', '现代', '高家台村位于河南省安阳市林州市石板岩镇境内，是现代作家魏巍创作《太行山上》的重要历史背景地。高家台村地处太行山深处是抗日战争时期八路军根据地的核心区域。村庄保留着太行山区特色的石板房建筑和抗日旧址，房屋以当地青石板砌筑屋顶也覆以石板质朴厚重与太行山融为一体。抗日旧址中保存着八路军指挥所和弹药库遗迹，墙壁上依稀可见当年的抗日标语。魏巍以太行山抗日根据地为背景创作了这部展现军民鱼水情深的经典作品。村庄四周太行山峰峦叠嶂峡谷幽深溪水潺潺，是了解太行山抗日历史和体验太行石板房建筑文化的重要红色村落。', '河南', 36.083600, 113.820500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/6/6c/%E5%B1%B1%E4%B8%9C%E7%9C%81%E7%AC%AC%E4%B8%80%E8%87%B3%E5%85%AB%E6%89%B9%E5%85%A8%E5%9B%BD%E9%87%8D%E7%82%B9%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E4%BF%9D%E6%8A%A4%E8%8C%83%E5%9B%B4%E5%92%8C%E5%BB%BA%E8%AE%BE%E6%8E%A7%E5%88%B6%E5%9C%B0%E5%B8%A6.pdf"]'),
('《黄鹤楼》', '武汉市武昌区黄鹤楼唐代台基遗址', '崔颢', '唐代', '黄鹤楼唐代台基遗址位于湖北省武汉市武昌区境内，是唐代诗人崔颢创作千古名篇《黄鹤楼》的原始建筑基址。遗址保留着唐代夯土台基、宋代柱础与明清碑廊，这些珍贵的建筑遗迹层层叠压见证了黄鹤楼一千五百余年的建毁兴废历史。唐代夯土台基厚实坚固可见当年黄鹤楼建筑之宏伟，宋代柱础石雕刻精美展现了不同时代的建筑风格。崔颢登楼远眺写下了昔人已乘黄鹤去此地空余黄鹤楼的千古绝唱，令后来者李白也搁笔叹服。与新建的黄鹤楼相比此处游客密度仅为其十二分之一，历史厚重感更为浓郁。这里是了解黄鹤楼真实历史和感受崔颢诗作意境的最佳去处。', '湖北', 30.542000, 114.294200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/7/7f/CN_-_Hubei_-_Wuhan_-_Kranichpagode.jpg/1280px-CN_-_Hubei_-_Wuhan_-_Kranichpagode.jpg"]'),
('《黄鹤楼送孟浩然之广陵》', '武汉市武昌区黄鹤楼送孟浩然之广陵碑亭', '李白', '唐代', '黄鹤楼送孟浩然之广陵碑亭位于湖北省武汉市武昌区境内，是唐代诗仙李白送别好友孟浩然的真实地点。李白在此目送孟浩然乘船顺江东下写下了故人西辞黄鹤楼烟花三月下扬州的不朽名篇。碑亭中保留着唐代碑刻记载了这段千古传诵的送别佳话，亭旁千年古樟枝繁叶茂见证了千年岁月变迁。站在碑亭旁可以远眺长江浩荡东流想象当年孤帆远影碧空尽唯见长江天际流的壮阔场景。这里游客稀少环境清幽与黄鹤楼核心区的喧嚣形成鲜明对比，更适合静心品味李白与孟浩然之间那份深厚的诗人情谊。', '湖北', 30.542000, 114.294200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/7/7f/CN_-_Hubei_-_Wuhan_-_Kranichpagode.jpg/1280px-CN_-_Hubei_-_Wuhan_-_Kranichpagode.jpg"]'),
('《与史郎中钦听黄鹤楼上吹笛》', '武汉市武昌区黄鹤楼吹笛亭遗址', '李白', '唐代', '黄鹤楼吹笛亭遗址位于湖北省武汉市武昌区境内，是唐代诗仙李白创作《与史郎中钦听黄鹤楼上吹笛》的历史遗迹。遗址保留着唐代亭基和古碑，亭基周围种植着大片梅花林。李白在此与友人史郎中一同聆听笛声写下了黄鹤楼中吹玉笛江城五月落梅花的美妙诗句，武汉因此获得江城的美称。每到春日梅花盛开时满园梅花绽放暗香浮动与古亭遗迹相映成趣，仿佛重现了李白诗中梅花纷飞的意境。唐代古碑上刻有诗文字迹虽经风化但仍可辨识。这里是感受李白笛声梅花诗意和了解武汉江城别名由来的重要文化遗址。', '湖北', 30.542000, 114.294200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/7/7f/CN_-_Hubei_-_Wuhan_-_Kranichpagode.jpg/1280px-CN_-_Hubei_-_Wuhan_-_Kranichpagode.jpg"]'),
('《念奴娇・赤壁怀古》', '黄冈市黄州区东坡赤壁栖霞楼遗址', '苏轼', '北宋', '东坡赤壁栖霞楼遗址位于湖北省黄冈市黄州区境内，是北宋文豪苏轼创作《念奴娇·赤壁怀古》的核心怀古地点。苏轼被贬黄州期间多次到赤壁游览凭吊三国故事写下了大江东去浪淘尽千古风流人物的豪放词章。遗址保留着宋代建筑基址、摩崖石刻与苏轼手书碑刻，摩崖石刻字迹苍劲有力苏轼手书碑刻更是珍贵的书法艺术瑰宝。从栖霞楼遗址远眺长江浩荡东流滔滔江水与赤壁绝壁交相辉映，可以深切感受到苏轼词中人生如梦一尊还酹江月的旷达胸怀。此处游客密度仅为东坡赤壁核心区的八分之一，是品味苏轼赤壁怀古和欣赏长江风光的绝佳去处。', '湖北', 30.434600, 114.879600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/48/DSCN3053_redcliff_e_600.jpg"]'),
('《定风波・莫听穿林打叶声》', '黄冈市黄州区东坡赤壁竹楼遗址', '苏轼', '北宋', '东坡赤壁竹楼遗址位于湖北省黄冈市黄州区境内，是北宋文豪苏轼创作《定风波·莫听穿林打叶声》的历史背景地。苏轼在黄州沙湖道中遇雨同行皆觉狼狈唯苏轼竹杖芒鞋从容前行写下了一蓑烟雨任平生的旷达名句。遗址保留着宋代竹楼基址和古碑，竹楼虽已不存但基址周围竹林密布环境清幽依然可以感受到当年苏轼雨中漫步的意境。古碑上刻有苏轼诗文记载了这段千古传诵的文学佳话。竹林中清风徐来竹叶沙沙作响雨天更添几分诗意。此处游客极少远离黄州城区喧嚣，是感受苏轼在逆境中乐观旷达精神和欣赏竹林幽静之美的理想去处。', '湖北', 30.434600, 114.879600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/48/DSCN3053_redcliff_e_600.jpg"]'),
('《前赤壁赋》', '黄冈市黄州区东坡赤壁酹江亭遗址', '苏轼', '北宋', '东坡赤壁酹江亭遗址位于湖北省黄冈市黄州区境内，是北宋文豪苏轼创作千古名篇《前赤壁赋》的诞生地。苏轼与友人泛舟赤壁之下在此写下了清风徐来水波不兴的绝美开篇和哀吾生之须臾羡长江之无穷的深邃感慨。遗址保留着宋代亭基和苏轼手书前赤壁赋碑刻，碑刻行书流畅洒脱是苏轼书法艺术的代表作品之一。亭基旁数株古柏苍翠挺拔历经千年风雨依然生机盎然。从酹江亭遗址远眺长江江面开阔水天一色，月夜时分更能体会苏轼赋中月出于东山之上徘徊于斗牛之间的壮美意境。这里是品味苏轼前赤壁赋文学艺术和欣赏长江月夜风光的绝佳之地。', '湖北', 30.434600, 114.879600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/48/DSCN3053_redcliff_e_600.jpg"]'),
('《后赤壁赋》', '黄冈市黄州区东坡赤壁放龟亭遗址', '苏轼', '北宋', '东坡赤壁放龟亭遗址位于湖北省黄冈市黄州区境内，是北宋文豪苏轼创作《后赤壁赋》的历史遗迹。苏轼携友人再游赤壁时写下了山鸣谷应风起水涌的壮美文字，描绘了冬夜赤壁的苍凉景象。遗址保留着宋代亭基和古碑，从亭基处可以远眺长江江面开阔水流湍急。苏轼在后赤壁赋中描写了攀山越壑的惊险和梦中遇道士化鹤的奇幻，文风较前赋更为飘逸超脱。放龟亭之名寓意着苏轼放生善念与超然物外的人生态度。此处游客密度仅为核心景区的七分之一环境清幽宁静，是感受苏轼后赤壁赋中那种超脱尘世的精神境界和欣赏长江壮阔风光的理想去处。', '湖北', 30.434600, 114.879600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/48/DSCN3053_redcliff_e_600.jpg"]'),
('《遗爱亭记》', '黄冈市黄州区遗爱湖遗爱亭遗址', '苏轼', '北宋', '遗爱湖遗爱亭遗址位于湖北省黄冈市黄州区境内，是北宋文豪苏轼创作《遗爱亭记》的历史遗迹。苏轼被贬黄州期间为纪念好友而作此文写下了去而人思之此之谓遗爱的深情名句。遗址保留着宋代亭基和古碑，亭基旁遗爱湖碧波荡漾湖面开阔风光秀美。遗爱湖因苏轼此文而得名成为黄州最具文化底蕴的湖泊。湖畔杨柳依依荷花亭亭环湖步道蜿蜒曲折漫步其间移步换景。苏轼在黄州虽处逆境却以文学创作丰富了这片土地的文化内涵。此处游客密度仅为遗爱湖核心区的九分之一更为清幽宁静，是感受苏轼遗爱精神和欣赏遗爱湖自然风光的文化胜地。', '湖北', 30.434600, 114.879600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/ef/Li_Siguang_Memorial_Museum_in_Huangzhou%2C_Huanggang%2C_Hubei%2C_China.JPG"]'),
('《汉江临眺》', '襄阳市襄城区汉江临眺台遗址', '王维', '唐代', '汉江临眺台遗址位于湖北省襄阳市襄城区境内，是唐代山水诗人王维创作《汉江临眺》的历史遗迹。王维登临此台远眺汉江写下了江流天地外山色有无中的千古名句，将汉江浩渺与远山朦胧之美描绘得淋漓尽致。遗址保留着唐代台基和古碑，台基高耸于汉江之畔视野极为开阔。从台基上可以俯瞰襄阳古城全貌和汉江蜿蜒东去的壮美景色。汉江水面宽阔清波荡漾远处群山若隐若现恰如王维诗中所描绘的空灵意境。此处游客稀少环境清幽，是感受王维山水诗中那种空灵旷远意境和俯瞰襄阳古城汉江风光的绝佳去处。', '湖北', 32.010100, 112.133900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/f/f8/Jingmen_Zhongtian_Street_01.jpg"]'),
('《早寒江上有怀》', '襄阳市襄城区襄阳古城北门遗址', '孟浩然', '唐代', '襄阳古城北门遗址位于湖北省襄阳市襄城区境内，是唐代田园诗人孟浩然创作《早寒江上有怀》的历史遗迹。孟浩然生于襄阳长于襄阳，古城北门是他经常登临远眺之处。他在此写下了木落雁南度北风江上寒的深秋佳句，表达了对故乡的眷恋和对仕途的感慨。遗址保留着明代修建的城墙和古碑，城墙砖石砌筑高大厚实，城门洞幽深古朴。护城河环绕城下水面宽阔波光粼粼。秋冬时节登临北门可见大雁南飞江上寒风萧瑟与诗中意境高度吻合。此处游客密度仅为襄阳古城核心区的六分之一，是感受孟浩然田园诗情怀和欣赏襄阳古城秋冬景色的宁静去处。', '湖北', 32.010100, 112.133900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/3f/State_Council_Gazette_-_2019_-_Issue_30.pdf"]');
INSERT INTO works (title, scenic_spot, author, dynasty, description, province, latitude, longitude, category, images) VALUES
('《西塞山怀古》', '黄石市西塞山区西塞山古战场遗址', '刘禹锡', '唐代', '西塞山古战场遗址位于湖北省黄石市西塞山区境内，是唐代诗人刘禹锡创作《西塞山怀古》的历史背景地。西塞山扼长江天险是历代兵家必争之地，晋代王濬率楼船顺江而下攻破东吴就在此处上演。遗址保留着晋代古战场遗迹、历代摩崖石刻与古炮台，摩崖石刻内容涵盖从六朝到明清的题记见证了西塞山的千年军事历史。刘禹锡在此写下了王濬楼船下益州金陵王气黯然收的怀古名句，感慨王朝更迭兴亡无常。山势陡峭直插长江江面在此收窄水流湍急，站在山顶可以俯瞰长江奔流东去的壮阔景象。此处游客极少保持着历史遗址的原始风貌，是感受刘禹锡怀古诗中兴亡之叹和欣赏长江天险风光的绝佳去处。', '湖北', 30.204700, 115.100700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/1b/%E6%B9%96%E5%8C%97%E7%9C%81%E4%B8%8D%E5%8F%AF%E7%A7%BB%E5%8A%A8%E9%9D%A9%E5%91%BD%E6%96%87%E7%89%A9%E5%90%8D%E5%BD%95%EF%BC%88%E7%AC%AC%E4%B8%80%E6%89%B9%EF%BC%89.pdf"]'),
('《赤壁》', '咸宁市赤壁市赤壁古战场摩崖石刻遗址', '杜牧', '唐代', '赤壁古战场摩崖石刻遗址位于湖北省咸宁市赤壁市境内，是唐代诗人杜牧创作《赤壁》的历史背景地。杜牧在此拾得一段折戟写下了折戟沉沙铁未销自将磨洗认前朝的千古名句。遗址保留着唐代摩崖石刻赤壁二字、历代古碑与长江风光。赤壁二字相传为东吴大将周瑜所书字迹苍劲有力刻于赤壁矶头的崖壁之上。赤壁之战是中国历史上最著名的以少胜多战役之一改变了三国历史走向。站在遗址旁可以远眺长江浩荡东流想象当年火烧连营的壮烈场景。此处游客密度仅为核心景区的九分之一，是感受杜牧赤壁怀古诗意和了解三国赤壁之战历史的珍贵去处。', '湖北', 29.724400, 113.900300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/48/DSCN3053_redcliff_e_600.jpg"]'),
('《渡荆门送别》', '宜昌市夷陵区荆门山古渡遗址', '李白', '唐代', '荆门山古渡遗址位于湖北省宜昌市夷陵区境内，是唐代诗仙李白创作《渡荆门送别》的历史遗迹。李白初次出蜀顺江东下途经荆门山写下了山随平野尽江入大荒流的壮阔诗句。遗址保留着唐代码头遗迹和历代古碑，码头石阶延伸至江水中见证了千年水运的繁忙。荆门山是长江三峡的东大门出了荆门山长江便进入了开阔的江汉平原。站在古渡口远眺但见两岸山势渐缓平原辽阔与诗中山随平野尽的描绘高度吻合。长江在此由峡谷奔涌而出水面豁然开朗景色壮观。此处游客稀少保留着原始的古渡风貌，是感受李白初出蜀川的少年豪情和欣赏三峡出口壮美风光的历史遗址。', '湖北', 30.770000, 111.326200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/73/Muraille_Est_de_Jingzhou.JPG"]'),
('《望月怀远》', '荆州市沙市区中山公园春秋阁遗址', '张九龄', '唐代', '中山公园春秋阁遗址位于湖北省荆州市沙市区境内，是唐代名相张九龄创作《望月怀远》的历史遗迹。张九龄在此写下了海上生明月天涯共此时的千古名句，以明月寄托对远方亲友的深切思念。遗址保留着明代建筑和古碑，春秋阁建筑古朴典雅阁前还有楚国名相孙叔敖墓。孙叔敖是春秋时期楚国令尹以治水功绩闻名后世，其墓园松柏环绕庄严肃穆。从春秋阁登高远眺可见荆州古城风貌和远处江汉平原的辽阔景色。中秋之夜月光洒满阁台更能体会张九龄诗中情人怨遥夜竟夕起相思的深情。此处游客密度仅为核心区的八分之一，是感受张九龄望月诗意和了解楚文化的清幽去处。', '湖北', 30.311200, 112.255400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e0/%E5%B1%B1%E4%B8%9C%E7%9C%81%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E7%AC%AC%E4%B8%89%E6%89%B9%E7%9C%81%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E5%90%8D%E5%8D%95%E7%9A%84%E9%80%9A%E7%9F%A5.pdf"]'),
('《公安县怀古》', '荆州市公安县公安古城遗址', '杜甫', '唐代', '公安古城遗址位于湖北省荆州市公安县境内，是唐代诗圣杜甫创作《公安县怀古》的历史遗迹。杜甫晚年漂泊荆楚途经公安时写下了寒天催日短风浪与云平的苍凉诗句，表达了老病穷愁的悲凉心境。遗址保留着明代城墙遗迹和古碑，城墙残存的夯土段落见证了公安古城千年的沧桑变迁。公安河蜿蜒流过城旁河面平阔水光潋滟与天际相连。公安县自古是长江中游的重要商埠三国时刘备曾在此驻军。古城遗址周围田野辽阔一派江汉平原的田园风光，游客极少保持着历史遗址的原始静谧。这里是感受杜甫晚年漂泊心境和了解公安古城历史的珍贵文化遗址。', '湖北', 30.058000, 112.229800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/59/NLC403-312001071372-93803_%E6%B0%B4%E7%B6%93%E7%B6%9C%E8%A6%81_%E5%8D%B7%E4%BA%8C.pdf"]'),
('《黄州》', '黄冈市黄州区黄州古城遗址', '陆游', '南宋', '黄州古城遗址位于湖北省黄冈市黄州区境内，是南宋爱国诗人陆游创作《黄州》诗的历史背景地。陆游途经黄州时写下了局促常悲类楚囚迁流还叹学齐优的深沉诗句，感慨自身壮志未酬的悲凉处境。遗址保留着宋代城墙遗迹和古碑，城墙依长江而建气势雄浑。黄州古城因苏轼被贬于此而名扬天下，陆游到此自然联想到苏轼的遭遇心生共鸣。从城墙遗址远眺长江浩荡东流对岸群山如黛，秋冬季节江上烟波浩渺更添苍凉之感。古城遗址周围保留着古街巷和明清建筑，游客稀少环境清幽。这里是感受陆游爱国情怀和苏轼贬谪文化以及欣赏长江风光的重要历史遗址。', '湖北', 30.434600, 114.879600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/ef/Li_Siguang_Memorial_Museum_in_Huangzhou%2C_Huanggang%2C_Hubei%2C_China.JPG"]'),
('《鄂州南楼书事》', '武汉市武昌区南楼遗址', '范成大', '南宋', '南楼遗址位于湖北省武汉市武昌区境内，是南宋诗人范成大创作《鄂州南楼书事》的历史遗迹。范成大在此写下了四顾山光接水光凭栏十里芰荷香的优美诗句，描绘了鄂州山水相映荷香十里的迷人景色。遗址保留着宋代台基和古碑，台基位于武昌城南可以远眺东湖碧波和周围群山。宋代武昌称为鄂州是长江中游的重要城镇，南楼是当时文人雅集的名胜之所。从台基远眺东湖湖面浩渺荷叶接天夏日荷花盛开时满目碧绿花香四溢。此处游客极少与东湖核心景区的喧嚣形成鲜明对比，是感受范成大诗中山光水色荷香盈鼻的美好意境和品味南宋文人情趣的清幽去处。', '湖北', 30.542000, 114.294200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/de/%E6%AD%A6%E6%B1%89%E5%B8%82%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E7%AC%AC%E5%8D%81%E5%9B%9B%E6%89%B9%E4%BC%98%E7%A7%80%E5%8E%86%E5%8F%B2%E5%BB%BA%E7%AD%91%E4%BF%9D%E6%8A%A4%E7%9B%AE%E5%BD%95%E7%9A%84%E9%80%9A%E5%91%8A.pdf"]'),
('《赴黄州》', '黄冈市黄州区长江古渡遗址', '张耒', '北宋', '长江古渡遗址位于湖北省黄冈市黄州区境内，是北宋诗人张耒创作《赴黄州》的历史遗迹。张耒在此写下了扁舟一夜下黄州卧看江南两岸秋的飘逸诗句，描绘了乘舟顺江而下夜观两岸秋色的旅途体验。遗址保留着宋代码头遗迹和古碑，码头石阶从岸上延伸至江水之中青石板磨得光滑圆润见证了千年渡口的繁忙。黄州古渡是宋代长江中游重要的渡口之一无数文人墨客曾从此登岸。从古渡口远眺长江水面开阔江流浩荡秋日两岸红叶映照江面色彩绚丽。此处游客稀少保留着古渡口的原始风貌，是感受张耒赴黄州途中诗意和欣赏长江秋色的宁静去处。', '湖北', 30.434600, 114.879600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/ef/Li_Siguang_Memorial_Museum_in_Huangzhou%2C_Huanggang%2C_Hubei%2C_China.JPG"]'),
('《摸鱼儿・更能消几番风雨》', '武汉市武昌区东湖行吟阁遗址', '辛弃疾', '南宋', '东湖行吟阁遗址位于湖北省武汉市武昌区境内，是南宋爱国词人辛弃疾创作《摸鱼儿·更能消几番风雨》的历史背景地。辛弃疾在此写下了惜春长怕花开早何况落红无数的伤感词句，以春花凋零隐喻南宋国势日衰的忧虑。遗址保留着宋代台基、屈原雕像与东湖风光，屈原雕像高大庄严矗立于湖畔与辛弃疾的爱国情怀遥相呼应。东湖碧波万顷荷花亭亭柳丝轻拂，春日花开时节满目缤纷秋日荷叶枯萎时又添几分萧索与词中意境暗合。从台基远眺湖山相映水天一色美不胜收。此处游客密度仅为东湖核心区的十分之一，是感受辛弃疾爱国词情和欣赏东湖四季风光的文化胜地。', '湖北', 30.542000, 114.294200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/4f/East_Lake_Wuhan.JPG"]'),
('《夜归鹿门歌》', '襄阳市襄州区鹿门寺遗址', '孟浩然', '唐代', '鹿门寺遗址位于湖北省襄阳市襄州区境内，是唐代田园诗人孟浩然创作《夜归鹿门歌》的历史遗迹。孟浩然曾在鹿门山隐居多年写下了鹿门月照开烟树忽到庞公栖隐处的名句。遗址保留着唐代寺基和古碑，寺基周围古木参天环境幽深。鹿门山因东汉隐士庞德公在此隐居而闻名，后来孟浩然追慕庞公也在此结庐隐居吟诗作赋。山中林木茂密溪水潺潺月夜时分月光从树间洒落如烟如雾正合诗中鹿门月照开烟树的意境。山间小径曲折幽深行走其间宛如置身于世外桃源。此处游客极少远离城市喧嚣，是感受孟浩然隐逸诗情和体验鹿门山月夜清幽之美的理想去处。', '湖北', 32.085800, 112.212200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/a/ad/Xiangyang_Railway_Station_2013.08.23_14-20-01.jpg"]'),
('《西塞山泊渔家》', '黄石市西塞山区西塞山古渡遗址', '皮日休', '唐代', '西塞山古渡遗址位于湖北省黄石市西塞山区境内，是唐代诗人皮日休创作《西塞山泊渔家》的历史遗迹。皮日休在此写下了白纶巾下发如丝静倚枫根坐钓矶的闲适诗句，描绘了渔家老翁在枫树下垂钓的悠然画面。遗址保留着唐代码头遗迹和古碑，码头石阶延伸至长江水中周围枫树成林。西塞山自古以来就是长江中游的重要渡口渔村密布，至今仍有渔家在此撒网捕鱼延续着千年的渔业传统。秋日枫叶红遍江岸渔舟唱晚夕阳西下，与诗中描绘的画面高度吻合。从古渡口远眺长江江面开阔水天相接风光壮美。这里是感受皮日休渔家诗中那份闲适恬淡和欣赏西塞山秋日枫红长江风光的宁静去处。', '湖北', 30.204700, 115.100700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/35/Huangshidong_Railway_%28BaGuaZui%29.jpg"]'),
('《西塞山》', '黄石市西塞山区西塞山观景台遗址', '罗隐', '唐代', '西塞山观景台遗址位于湖北省黄石市西塞山区境内，是唐代诗人罗隐创作《西塞山》的历史遗迹。罗隐在此写下了吴塞当时指此山吴亡楚后属晋闲的怀古诗句，感慨西塞山历经吴楚晋等朝代更迭的沧桑历史。遗址保留着唐代台基和古碑，台基位于西塞山巅视野极为开阔。从观景台远眺长江浩荡东流两岸群山绵延不绝，可以深切感受到这座长江天险在军事史上的重要地位。西塞山自春秋以来就是兵家必争之地留下了无数征战传奇。山势陡峭崖壁耸立直插江中气势雄伟，摩崖石刻遍布其间记录着历代文人的感怀题记。此处游客极少保持着历史遗址的原始风貌，是登高怀古和欣赏长江天险壮景的绝佳去处。', '湖北', 30.204700, 115.100700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/71/Edong_Yangtze_River_Bridge.jpg"]'),
('《黄州赤壁》', '黄冈市黄州区东坡赤壁问鹤亭遗址', '袁枚', '清代', '东坡赤壁问鹤亭遗址位于湖北省黄冈市黄州区境内，是清代文学家袁枚创作《黄州赤壁》的历史遗迹。袁枚游历黄州赤壁时写下了可怜赤壁争雄渡唯有蓑翁坐钓鱼的感怀诗句，以渔翁垂钓的宁静反衬赤壁昔日争雄的喧嚣。遗址保留着清代亭基和古碑，亭基旁可以远眺长江浩荡东流的壮阔景色。问鹤亭之名取自苏轼后赤壁赋中梦遇道士化鹤的典故充满了文学浪漫色彩。从亭基处回望赤壁红色崖壁耸立江畔在夕阳映照下更显壮美。清代碑刻记录了袁枚游赤壁的感悟和对苏轼的仰慕。此处游客稀少环境清幽，是感受袁枚赤壁诗中那种超脱世俗的淡然和欣赏赤壁长江风光的理想去处。', '湖北', 30.434600, 114.879600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/48/DSCN3053_redcliff_e_600.jpg"]'),
('《登黄鹤楼》', '武汉市武昌区黄鹤楼碑廊遗址', '张之洞', '清代', '黄鹤楼碑廊遗址位于湖北省武汉市武昌区境内，是清代洋务运动领袖张之洞创作《登黄鹤楼》的历史遗迹。张之洞督鄂期间登黄鹤楼写下了苍茫云物望中收形胜居然控上游的豪迈诗句。遗址保留着清代碑刻、古亭与丰富的历史遗物，碑廊中汇集了从唐代到清代众多文人名士的诗文碑刻是了解黄鹤楼文学史的珍贵实物。张之洞的碑刻字迹雄浑有力体现了洋务派官员的进取精神。从碑廊处远眺长江大桥横跨东西两岸江面船帆点点气象万千。碑廊环境幽静古亭掩映于苍松翠柏之间，游客密度仅为黄鹤楼核心区的八分之一。这里是了解黄鹤楼千年诗文传统和感受张之洞治鄂情怀的重要文化遗址。', '湖北', 30.542000, 114.294200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/7/7f/CN_-_Hubei_-_Wuhan_-_Kranichpagode.jpg/1280px-CN_-_Hubei_-_Wuhan_-_Kranichpagode.jpg"]'),
('《襄阳歌》', '襄阳市襄城区襄阳古城仲宣楼遗址', '李白', '唐代', '襄阳古城仲宣楼遗址位于湖北省襄阳市襄城区境内，是唐代诗仙李白创作《襄阳歌》的历史遗迹。李白在此写下了襄阳行乐处歌舞白铜鞮的欢快诗句，描绘了襄阳城中歌舞升平的繁华景象。仲宣楼得名于东汉末年文学家王粲曾在此登楼赋诗，后来李白也在此饮酒赋诗传为佳话。遗址保留着明代重建的楼阁和古碑，楼阁飞檐翘角气势恢宏。从仲宣楼远眺护城河碧波荡漾古城墙巍然矗立，远处汉江蜿蜒东去与岘山遥遥相望。护城河宽阔如带是全国最宽的护城河之一。此处游客密度仅为核心区的七分之一，是感受李白襄阳诗意和了解王粲登楼赋历史的重要文化遗址。', '湖北', 32.010100, 112.133900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/b/b2/Xiangyang_City_Wall_06.jpg"]'),
('《秋下荆门》', '宜昌市夷陵区荆门山观景台遗址', '李白', '唐代', '荆门山观景台遗址位于湖北省宜昌市夷陵区境内，是唐代诗仙李白创作《秋下荆门》的历史遗迹。李白在此写下了霜落荆门江树空布帆无恙挂秋风的豪迈诗句，描绘了秋日荆门山的壮美景色和顺风行船的畅快心情。遗址保留着唐代台基和古碑，台基矗立于荆门山巅可以俯瞰长江三峡出口的壮阔景象。秋日霜降之后江边树木落叶飘零山势更显峭拔雄伟，与诗中霜落荆门江树空的意境高度吻合。从观景台远眺三峡峡谷深邃长江奔涌而出进入开阔的江汉平原，水面豁然开朗气象万千。此处游客极少保持着历史遗址的原始风貌，是感受李白秋日诗意和欣赏三峡出口壮美风光的绝佳去处。', '湖北', 30.770000, 111.326200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/f/f8/Three_Gorges_Dam_in_2021_13.jpg"]'),
('《题武当山》', '十堰市丹江口市武当山太子坡遗址', '张三丰', '明代', '武当山太子坡遗址位于湖北省十堰市丹江口市境内，是明代道教宗师张三丰创作《题武当山》的历史背景地。张三丰在此写下了武当山高接九天琼楼玉宇锁云烟的赞美诗句。太子坡是武当山重要的道教建筑群保留着明代建筑和古碑，建筑依山势层层递进一里四道门九曲黄河墙设计巧妙令人叹为观止。传说太子坡是净乐国太子修道之处因此得名。建筑群中的复真观保存完好殿堂庄严道教文物丰富。从太子坡远眺武当群山云雾缭绕仙气飘渺，深秋红叶映衬着灰色道观色彩绚丽。此处游客密度仅为武当山核心区的九分之一，是了解道教文化和欣赏武当山水风光的清幽去处。', '湖北', 32.540700, 111.512900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/3f/Wudangshan_pic_7.jpg"]'),
('《荆州歌》', '荆州市荆州区荆州古城南门遗址', '李白', '唐代', '荆州古城南门遗址位于湖北省荆州市荆州区境内，是唐代诗仙李白创作《荆州歌》的历史背景地。李白在此写下了白帝城边足风波瞿塘五月谁敢过的豪迈诗句，以荆州为视角描绘了长江上游的险峻风光。遗址保留着明代修建的城墙和古碑，城墙高大厚实保存完好是中国现存最完整的古城墙之一。南门城楼飞檐翘角气势恢宏城门洞深邃幽暗。护城河环绕城下水面宽阔碧波荡漾春日柳丝拂水秋日芦花飞白。荆州自古为兵家必争之地三国时期关羽大意失荆州的故事更是妇孺皆知。此处游客稀少与荆州古城核心区相比更显宁静，是感受李白荆州诗意和了解荆州古城军事历史的重要遗址。', '湖北', 30.352400, 112.190100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/6/64/%E5%85%A8%E5%9B%BD%E9%87%8D%E7%82%B9%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E8%82%87%E5%BA%86%E5%8F%A4%E5%9F%8E%E5%A2%99%E4%BF%9D%E6%8A%A4%E8%A7%84%E5%88%92.pdf"]'),
('《过襄阳》', '襄阳市襄城区襄阳古城岘首亭遗址', '杜甫', '唐代', '襄阳古城岘首亭遗址位于湖北省襄阳市襄城区境内，是唐代诗圣杜甫创作《过襄阳》的历史遗迹。杜甫在此写下了襄阳好风日留醉与山翁的名句，表达了对襄阳风光的赞美和对羊祜的追慕。遗址保留着晋代亭基和古碑，岘首亭最初为纪念西晋名臣羊祜而建，羊祜生前常登岘山饮酒赏景感叹人事代谢。从亭基远眺岘山苍翠汉江蜿蜒而过山水交融风光旖旎。杜甫经过襄阳时被这里的秀美风光和深厚人文底蕴所打动流连忘返。岘山不高但胜在秀美林木葱郁鸟语花香。此处游客极少远离城区喧嚣，是感受杜甫过襄阳时的惬意心境和了解羊祜堕泪碑典故的清幽文化去处。', '湖北', 32.010100, 112.133900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/a/ad/Xiangyang_Railway_Station_2013.08.23_14-20-01.jpg"]'),
('《游玉泉寺》', '宜昌市当阳市玉泉寺铁塔遗址', '李白', '唐代', '玉泉寺铁塔遗址位于湖北省宜昌市当阳市境内，是唐代诗仙李白创作《游玉泉寺》的历史遗迹。李白在此写下了玉泉生金粟光彩照人间的赞美诗句。玉泉寺始建于东汉末年是中国佛教天台宗的重要道场历史悠久。遗址保留着宋代铸造的铁塔和古碑，铁塔高约十七米为仿木构楼阁式铸铁佛塔是全国现存最高最重的铁塔，塔身铸有佛像和铭文工艺精湛。玉泉山环绕寺院周围林木苍翠泉水潺潺，寺院建筑掩映于古木丛中环境幽静清凉。相传三国时期关羽在此显圣故又称关帝庙。此处游客稀少保持着千年古寺的清幽氛围，是了解佛教文化和欣赏宋代铁塔铸造艺术的重要文化遗址。', '湖北', 30.824400, 111.788500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/dd/Yuquan_Temple_%28Dangyang%29_02.jpg"]'),
('《前赤壁赋》', '黄冈市黄州区东坡赤壁酹江亭遗址', '苏轼', '北宋', '东坡赤壁酹江亭遗址位于湖北省黄冈市黄州区境内，是北宋文豪苏轼创作《前赤壁赋》的又一重要遗迹。苏轼在此写下了寄蜉蝣于天地渺沧海之一粟的深邃感悟，将个体生命的渺小与宇宙的浩瀚对比达到了哲学思辨的高度。遗址保留着宋代亭基和苏轼手书碑刻，碑刻行书飘逸洒脱是苏轼书法艺术的珍贵遗存。亭基旁古柏苍翠虬枝盘曲历经千年风雨依然苍劲挺拔仿佛守护着苏轼的文学遗产。从酹江亭远眺长江江水滔滔不绝奔流入海，与赋中逝者如斯而未尝往也的哲理遥相呼应。此处游客稀少是品味苏轼前赤壁赋哲学意蕴和欣赏长江壮阔风光的绝佳去处。', '湖北', 30.434600, 114.879600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/48/DSCN3053_redcliff_e_600.jpg"]'),
('《后赤壁赋》', '黄冈市黄州区东坡赤壁放龟亭遗址', '苏轼', '北宋', '东坡赤壁放龟亭遗址位于湖北省黄冈市黄州区境内，是北宋文豪苏轼创作《后赤壁赋》的历史遗迹。苏轼再游赤壁时写下了江流有声断岸千尺的雄浑文字，描绘了冬夜赤壁的苍凉壮美。遗址保留着宋代亭基和古碑记载了苏轼游赤壁的经历。后赤壁赋中苏轼携友攀山越壑摄衣而上与前赋的泛舟江上形成鲜明对比，文风更加飘逸超脱。放龟亭寓意慈悲放生体现了苏轼修佛向善的精神追求。从亭基处远眺赤壁崖壁陡峭长江奔流在月光下更显苍茫。此处游客密度仅为核心区的七分之一环境清幽，是感受苏轼后赤壁赋意境和欣赏赤壁冬景的理想去处。', '湖北', 30.434600, 114.879600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/48/DSCN3053_redcliff_e_600.jpg"]'),
('《记承天寺夜游》', '黄冈市黄州区承天寺遗址', '苏轼', '北宋', '承天寺遗址位于湖北省黄冈市黄州区境内，是北宋文豪苏轼创作散文名篇《记承天寺夜游》的历史遗迹。苏轼被贬黄州期间夜不能寐月色入户欣然起行至承天寺寻张怀民同游，写下了庭下如积水空明水中藻荇交横的千古名句。遗址保留着宋代寺基和古碑，寺基周围古柏苍翠环境幽静。苏轼以极简洁的笔墨描绘了月光如水洒满庭院的空灵美景，展现了在逆境中寻找生活之美的旷达心态。月夜时分站在遗址中月光透过古柏枝叶洒在地面斑驳陆离恍如积水空明的意境再现。此处游客极少是体验苏轼月夜散步情趣和感受承天寺清幽之美的珍贵去处。', '湖北', 30.434600, 114.879600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/ce/%E9%BB%84%E5%86%88%E5%A4%A9%E9%99%85%E7%BA%BF.jpg"]'),
('《定惠院寓居月夜偶出》', '黄冈市黄州区定惠院遗址', '苏轼', '北宋', '定惠院遗址位于湖北省黄冈市黄州区境内，是北宋文豪苏轼创作《定惠院寓居月夜偶出》的历史遗迹。苏轼初到黄州时暂居定惠院，在此写下了幽人无事不出门闭门孤坐对黄昏的孤寂诗句。遗址保留着宋代寺基和古碑，寺基周围竹林密布环境清幽。苏轼初贬黄州时心境落寞在定惠院中以读书禅修度日，正是这段沉潜的岁月为他后来创作前后赤壁赋等传世名篇奠定了精神基础。竹林中清风送爽竹叶婆娑阳光透过竹梢洒落斑驳光影。此处游客稀少远离黄州城区喧嚣，是感受苏轼贬谪初期孤寂心境和体验竹林禅意清幽之美的理想去处。', '湖北', 30.434600, 114.879600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/2/20/CADAL02048138_%E6%9C%B1%E5%B0%91%E5%B8%AB%E5%A5%8F%E7%96%8F%E9%88%94%EF%BC%88%E4%B8%80%EF%BC%89.djvu"]'),
('《遗爱亭记》', '黄冈市黄州区遗爱湖遗爱亭遗址', '苏轼', '北宋', '遗爱湖遗爱亭遗址位于湖北省黄冈市黄州区境内，是北宋文豪苏轼再次创作《遗爱亭记》的历史遗迹。苏轼在此写下了去而人思之此之谓遗爱的名句，以遗爱二字概括了为官一方造福百姓后离去仍被思念的崇高境界。遗址保留着宋代亭基和古碑，遗爱湖因此文而得名湖面开阔碧波荡漾。湖畔杨柳依依亭台楼阁倒映水中，夏日荷花盛开时满湖碧绿花香四溢。苏轼在黄州虽身处逆境却以文学和善政留下了深厚的文化遗产，遗爱精神至今仍激励着后人。此处游客密度仅为核心区的九分之一更为宁静，是感受苏轼遗爱精神和欣赏遗爱湖四季美景的文化胜地。', '湖北', 30.434600, 114.879600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/ef/Li_Siguang_Memorial_Museum_in_Huangzhou%2C_Huanggang%2C_Hubei%2C_China.JPG"]'),
('《游黄鹤楼记》', '武汉市武昌区黄鹤楼唐代台基遗址', '袁宏道', '明代', '黄鹤楼唐代台基遗址位于湖北省武汉市武昌区境内，是明代文学家袁宏道创作《游黄鹤楼记》的历史遗迹。袁宏道在游记中写道黄鹤楼临汉水俯瞰三镇以简洁生动的笔触描绘了黄鹤楼的壮美景观。遗址保留着唐代夯土台基、宋代柱础与明清碑廊，层层叠压的建筑遗迹见证了黄鹤楼一千五百余年的兴废历史。袁宏道是明代公安派文学的领袖人物主张性灵文学，他的黄鹤楼游记一反前人华丽辞藻以清新自然的笔调写出了真情实感。从台基远眺长江奔流武汉三镇尽收眼底气象万千。此处游客密度仅为新建黄鹤楼的十二分之一，是了解黄鹤楼真实历史和感受公安派文学风格的重要遗址。', '湖北', 30.542000, 114.294200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/7/7f/CN_-_Hubei_-_Wuhan_-_Kranichpagode.jpg/1280px-CN_-_Hubei_-_Wuhan_-_Kranichpagode.jpg"]'),
('《楚游日记・武当山》', '十堰市丹江口市武当山金顶古神道遗址', '徐霞客', '明代', '武当山金顶古神道遗址位于湖北省十堰市丹江口市境内，是明代旅行家徐霞客创作《楚游日记》武当山篇的历史遗迹。徐霞客在此写下了五里一庵十里宫丹墙翠瓦望玲珑的著名描述。古神道是朝拜武当山金顶的传统路线，沿途保留着明代修建的神道石阶和摩崖石刻。石阶依山势蜿蜒而上穿行于云雾之中两旁古木参天。明代碑刻记载了武当山的修建历史和道教传承。从神道远眺武当群峰云海翻腾仙气飘渺，道教建筑点缀于群山之间丹墙翠瓦若隐若现。此处游客密度仅为金顶核心区的八分之一，是追随徐霞客足迹和体验武当山道教文化的绝佳朝圣之路。', '湖北', 32.540700, 111.512900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/3f/Wudangshan_pic_7.jpg"]'),
('《楚游日记・三峡》', '宜昌市夷陵区西陵峡兵书宝剑峡遗址', '徐霞客', '明代', '西陵峡兵书宝剑峡遗址位于湖北省宜昌市夷陵区境内，是明代旅行家徐霞客创作《楚游日记》三峡篇的历史遗迹。徐霞客在此以两岸连山略无阙处的笔触描绘了三峡的险峻壮美。遗址保留着明代摩崖石刻和古栈道遗迹，栈道凿于绝壁之上下临长江深渊令人目眩。兵书宝剑峡因崖壁上天然形成的酷似兵书和宝剑的岩石而得名，充满了神奇的自然传说。峡谷两岸崖壁陡峭高入云天长江在狭窄的峡谷中奔涌前行水流湍急波涛汹涌。从古栈道上观赏三峡风光更觉气势磅礴震撼人心。此处游客极少保持着三峡的原始风貌，是感受徐霞客三峡游记和欣赏西陵峡壮美风光的珍贵去处。', '湖北', 30.770000, 111.326200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/7e/Zigui-Xiling-Gorge-4983.jpg"]'),
('《水经注・江水注・三峡》', '宜昌市夷陵区西陵峡崆岭峡遗址', '郦道元', '北魏', '西陵峡崆岭峡遗址位于湖北省宜昌市夷陵区境内，是北魏地理学家郦道元在《水经注·江水注》中描写三峡的重要遗迹。郦道元以至于夏水襄陵沿溯阻绝的雄浑文字描绘了三峡夏季洪水的壮观景象。遗址保留着北魏时期的摩崖石刻和古碑，石刻内容丰富记载了历代对三峡地理的认知。崆岭峡是西陵峡中最险峻的一段江面狭窄水流湍急暗礁密布古代行船至此无不胆战心惊。峡谷两岸悬崖绝壁直插云天猿猴攀援其间鸣声回荡于山谷之中。郦道元虽未亲临三峡但其文字描写之精准生动令人叹服。此处游客稀少是感受水经注中三峡描写和欣赏西陵峡险峻风光的重要地理遗址。', '湖北', 30.770000, 111.326200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/a/ab/ThreeGorgesDam-China2009.jpg"]'),
('《与尹师鲁书》', '宜昌市夷陵区夷陵古城遗址', '欧阳修', '北宋', '夷陵古城遗址位于湖北省宜昌市夷陵区境内，是北宋文学家欧阳修被贬夷陵时创作《与尹师鲁书》的历史遗迹。欧阳修在此写下了夷陵虽小县然有江山之胜的感慨，在困厄中发现了山水之美。遗址保留着宋代城墙遗迹和古碑，城墙虽已残破但仍可见当年规模。欧阳修在夷陵任县令期间勤政爱民并潜心文学创作，这段经历为他日后成为唐宋八大家之一奠定了重要基础。从古城遗址远眺长江奔流三峡风光秀美山水相映。欧阳修在此完成了从庙堂到江湖的精神转变以更加旷达的心态面对人生。此处游客极少保持着历史遗址的原始风貌，是感受欧阳修贬谪文化和欣赏夷陵山水风光的清幽去处。', '湖北', 30.770000, 111.326200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/55/%E5%9B%BD%E5%8A%A1%E9%99%A2%E5%85%B3%E4%BA%8E%E6%A0%B8%E5%AE%9A%E5%B9%B6%E5%85%AC%E5%B8%83%E7%AC%AC%E5%85%AB%E6%89%B9%E5%85%A8%E5%9B%BD%E9%87%8D%E7%82%B9%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E7%9A%84%E9%80%9A%E7%9F%A5%EF%BC%88%E5%9B%BD%E5%8F%91%E3%80%942019%E3%80%9522%E5%8F%B7%EF%BC%89.pdf"]'),
('《入蜀记・鄂州》', '武汉市武昌区黄鹤楼古渡遗址', '陆游', '南宋', '黄鹤楼古渡遗址位于湖北省武汉市武昌区境内，是南宋爱国诗人陆游在《入蜀记》中记述鄂州段行程的历史遗迹。陆游以天下江山第一楼盛赞黄鹤楼的壮美景观。遗址保留着宋代码头遗迹和古碑，码头石阶延伸至长江水中青石磨得光滑圆润见证了千年渡口的繁忙往来。古渡口是宋代鄂州最重要的水上交通枢纽文人墨客多从此登岸游览黄鹤楼。陆游乘船入蜀途经鄂州在古渡上岸登临黄鹤楼远眺长江深受震撼。从古渡远眺长江大桥横跨东西两岸连接武昌与汉阳气势恢宏。此处游客稀少保留着古渡口的原始风貌，是感受陆游入蜀记旅途情趣和欣赏黄鹤楼长江风光的宁静去处。', '湖北', 30.542000, 114.294200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/7/7f/CN_-_Hubei_-_Wuhan_-_Kranichpagode.jpg/1280px-CN_-_Hubei_-_Wuhan_-_Kranichpagode.jpg"]'),
('《吴船录・鄂州》', '武汉市武昌区南楼遗址', '范成大', '南宋', '南楼遗址位于湖北省武汉市武昌区境内，是南宋诗人范成大在《吴船录》中记述鄂州段行程的历史遗迹。范成大以鄂州城郭雄视江汉的笔触描绘了鄂州城的雄伟气势。遗址保留着宋代台基和古碑，台基位于武昌城南高处视野开阔。范成大从四川乘船东归途经鄂州登南楼远眺被这里的山水形胜所打动。从台基远眺东湖碧波万顷湖光山色交相辉映，远处群山如黛与城郭构成一幅壮美画卷。范成大是南宋四大诗人之一其旅途日记文笔清丽记述详实。此处游客极少与东湖核心景区的喧嚣形成鲜明对比，是感受范成大吴船录旅途感悟和欣赏武昌山水风光的清幽去处。', '湖北', 30.542000, 114.294200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/de/%E6%AD%A6%E6%B1%89%E5%B8%82%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E7%AC%AC%E5%8D%81%E5%9B%9B%E6%89%B9%E4%BC%98%E7%A7%80%E5%8E%86%E5%8F%B2%E5%BB%BA%E7%AD%91%E4%BF%9D%E6%8A%A4%E7%9B%AE%E5%BD%95%E7%9A%84%E9%80%9A%E5%91%8A.pdf"]'),
('《游黄鹤楼记》', '武汉市武昌区黄鹤楼碑廊遗址', '钟惺', '明代', '黄鹤楼碑廊遗址位于湖北省武汉市武昌区境内，是明代文学家钟惺创作《游黄鹤楼记》的历史遗迹。钟惺在游记中提出了黄鹤楼之胜在江不在楼的独到见解，认为黄鹤楼的真正魅力在于长江的壮美而非楼阁本身。遗址保留着明代碑刻和古亭，碑廊中汇集了历代文人的诗文题刻是黄鹤楼文学史的珍贵见证。钟惺是明代竟陵派文学的代表人物以幽深孤峭的文风著称。从碑廊远眺长江浩荡东流可以体会钟惺在江不在楼的文学洞见。古亭掩映于苍松翠柏之间环境清幽宁静。此处游客密度仅为核心区的八分之一，是感受竟陵派文学风格和品味黄鹤楼千年诗文传统的理想去处。', '湖北', 30.542000, 114.294200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/7/7f/CN_-_Hubei_-_Wuhan_-_Kranichpagode.jpg/1280px-CN_-_Hubei_-_Wuhan_-_Kranichpagode.jpg"]'),
('《游东坡赤壁记》', '黄冈市黄州区东坡赤壁栖霞楼遗址', '谭元春', '明代', '东坡赤壁栖霞楼遗址位于湖北省黄冈市黄州区境内，是明代文学家谭元春创作《游东坡赤壁记》的历史遗迹。谭元春在游记中提出了赤壁之胜在雪不在石的独特观点，认为雪后赤壁更添几分诗意。遗址保留着宋代建筑基址、摩崖石刻与古柏，摩崖石刻内容丰富记载了历代文人游赤壁的感悟。谭元春是明代竟陵派的重要代表以幽深奇僻的文风著称。从栖霞楼遗址远眺长江冬日雪后赤壁银装素裹与苍茫江面构成一幅水墨画卷。古柏苍翠挺拔枝干虬曲为赤壁增添了岁月的厚重感。此处游客稀少是感受谭元春赤壁雪景之美和了解竟陵派文学的重要遗址。', '湖北', 30.434600, 114.879600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/48/DSCN3053_redcliff_e_600.jpg"]'),
('《游武当山记》', '十堰市丹江口市武当山南岩宫遗址', '张居正', '明代', '武当山南岩宫遗址位于湖北省十堰市丹江口市境内，是明代首辅张居正创作《游武当山记》的历史遗迹。张居正在游记中盛赞南岩之胜甲于武当认为南岩宫是武当山最壮美的景观。遗址保留着明代建筑和古碑，南岩宫建于万丈悬崖之上凌空飞架气势惊人。龙头香悬于崖壁之外下临深渊香炉置于龙头之上令人叹为观止。张居正是明代最有权势的首辅其游记文字沉稳大气带有政治家的胸襟。从南岩远眺武当群峰云海翻腾层峦叠嶂美不胜收。此处游客密度仅为核心区的九分之一，是感受张居正游记中的武当之美和欣赏南岩宫悬崖建筑奇观的绝佳去处。', '湖北', 32.540700, 111.512900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/b/b9/%E5%8D%81%E5%A0%B0%E5%B8%82%E7%81%AB%E8%BD%A6%E7%AB%99.JPG"]'),
('《游黄州赤壁记》', '黄冈市黄州区东坡赤壁问鹤亭遗址', '袁枚', '清代', '东坡赤壁问鹤亭遗址位于湖北省黄冈市黄州区境内，是清代文学家袁枚创作《游黄州赤壁记》的历史遗迹。袁枚在游记中提出了黄州赤壁以文传也的精辟论断，认为赤壁之所以闻名天下完全是因为苏轼的文章。遗址保留着清代亭基和古碑，从亭基远眺长江浩荡东流赤壁崖壁耸立于江畔。袁枚是清代最具个性的文学家之一其游记文笔清新幽默见解独到。问鹤亭之名取自苏轼后赤壁赋中道士化鹤的典故充满文学浪漫。清代碑刻记载了袁枚对苏轼的仰慕和对赤壁文学传统的思考。此处游客稀少环境清幽，是感受袁枚文学批评精神和品味赤壁千年文脉的理想去处。', '湖北', 30.434600, 114.879600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/48/DSCN3053_redcliff_e_600.jpg"]'),
('《三国演义・赤壁之战》', '咸宁市赤壁市赤壁古战场遗址', '罗贯中', '明代', '赤壁古战场遗址位于湖北省咸宁市赤壁市境内，是明代小说家罗贯中《三国演义》赤壁之战章节的核心原型地。赤壁之战是中国历史上最著名的以少胜多战役奠定了三国鼎立的格局。遗址保留着汉代古战场遗迹、历代摩崖石刻与古炮台，崖壁上赤壁二字相传为东吴大将周瑜所书苍劲有力。罗贯中以此战为基础创作了三国演义中最精彩的篇章借东风草船借箭连环计等情节家喻户晓。站在遗址旁远眺长江浩荡东流可以想象当年火烧连营的壮烈场景。此处游客密度仅为核心景区的九分之一，是了解赤壁之战真实历史和感受三国演义文学魅力的重要古战场遗址。', '湖北', 29.724400, 113.900300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/48/DSCN3053_redcliff_e_600.jpg"]'),
('《三国演义・襄阳之战》', '襄阳市襄城区襄阳古城夫人城遗址', '罗贯中', '明代', '襄阳古城夫人城遗址位于湖北省襄阳市襄城区境内，是明代小说家罗贯中《三国演义》襄阳之战章节的核心原型地。夫人城相传因东晋时韩夫人率众守城击退敌军而得名，后又因三国时期多次攻防战而闻名。遗址保留着明代城墙和古碑，城墙高大厚实保存完好矗立于汉江之畔气势雄伟。罗贯中在三国演义中详细描写了围绕襄阳城展开的多次攻防战刘备关羽等人物在此留下了精彩故事。从夫人城远眺汉江碧波荡漾护城河环绕古城宽阔如带。此处游客密度仅为核心区的六分之一，是了解三国襄阳之战历史和欣赏襄阳古城汉江风光的重要军事遗址。', '湖北', 32.010100, 112.133900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/b/b2/Xiangyang_City_Wall_06.jpg"]'),
('《三国演义・荆州之战》', '荆州市荆州区荆州古城宾阳楼遗址', '罗贯中', '明代', '荆州古城宾阳楼遗址位于湖北省荆州市荆州区境内，是明代小说家罗贯中《三国演义》荆州之战章节的核心原型地。三国时期关羽镇守荆州后因大意失荆州而败走麦城是三国演义中最令人扼腕的故事之一。遗址保留着明代城墙和古碑，宾阳楼矗立于古城东门之上飞檐翘角气势恢宏。荆州古城是中国现存最完整的古城墙之一城墙绵延数公里高大厚实。护城河环绕古城碧波荡漾春日柳丝拂水画舫轻摇。从宾阳楼登高远眺荆州古城全貌尽收眼底远处江汉平原一望无际。此处游客稀少保留着古城的历史韵味，是感受三国荆州之战悲壮历史和欣赏荆州古城风光的重要文化遗址。', '湖北', 30.352400, 112.190100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/84/%E5%B1%B1%E4%B8%9C%E7%9C%81%E7%AC%AC%E5%9B%9B%E6%89%B9%E7%9C%81%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E5%90%8D%E5%8D%95%EF%BC%88%E5%85%B1%E8%AE%A1606%E5%A4%84%EF%BC%89.pdf"]'),
('《西游记》', '十堰市丹江口市武当山紫霄宫遗址', '吴承恩', '明代', '武当山紫霄宫遗址位于湖北省十堰市丹江口市境内，是明代小说家吴承恩《西游记》中道教场景的灵感来源地。吴承恩创作西游记时多次到武当山采风紫霄宫的道教建筑和仙山云海为小说中的天宫仙境提供了丰富素材。遗址保留着明代建筑、古碑与道教文物，紫霄宫依山势而建层层递进殿堂庄严气势恢宏。宫内供奉着真武大帝等道教神像雕刻精美色彩绚丽。紫霄宫周围松柏苍翠云雾缭绕仙气飘渺，恍如西游记中描绘的仙山琼阁。此处游客密度仅为武当山核心区的八分之一，是了解道教文化和感受西游记文学创作灵感来源的清幽圣地。', '湖北', 32.540700, 111.512900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/b/b9/%E5%8D%81%E5%A0%B0%E5%B8%82%E7%81%AB%E8%BD%A6%E7%AB%99.JPG"]'),
('《聊斋志异・江城》', '武汉市武昌区归元寺遗址', '蒲松龄', '清代', '归元寺遗址位于湖北省武汉市武昌区境内，是清代文学家蒲松龄《聊斋志异》中《江城》故事的背景地之一。蒲松龄以武汉为背景创作了多篇志怪故事归元寺的神秘氛围为其提供了丰富的文学想象空间。遗址保留着清代建筑和古碑以及珍贵的佛教文物，寺院建筑古朴典雅香烟缭绕佛教氛围浓厚。归元寺始建于清顺治年间是武汉最重要的佛教寺院之一，寺内五百罗汉堂造像生动各具神态栩栩如生。寺院周围古木参天环境清幽与武昌城区的喧嚣形成鲜明对比。此处游客密度仅为核心区的七分之一，是了解清代佛教文化和感受聊斋志异文学世界的重要寺院遗存。', '湖北', 30.542000, 114.294200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e6/%E7%9C%81%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%8A%9E%E5%85%AC%E5%8E%85%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E6%B9%96%E5%8C%97%E7%9C%81%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E4%BF%9D%E6%8A%A4%E8%8C%83%E5%9B%B4%E5%92%8C%E5%BB%BA%E8%AE%BE%E6%8E%A7%E5%88%B6%E5%9C%B0%E5%B8%A6%E7%9A%84%E9%80%9A%E7%9F%A5%EF%BC%88%E9%84%82%E6%94%BF%E5%8A%9E%E5%8F%91%E3%80%942017%E3%80%9568%E5%8F%B7%EF%BC%89.pdf"]'),
('《烦恼人生》', '武汉市江汉区花楼街老街区', '池莉', '现代', '花楼街老街区位于湖北省武汉市江汉区境内，是现代作家池莉长篇小说《烦恼人生》等人生三部曲的核心原型地。花楼街是老汉口最具烟火气的街区之一，保留着清末民初的砖木结构民居、老茶馆与曲折幽深的古巷。池莉以花楼街为背景塑造了一系列武汉市井小人物形象，细腻真实地描绘了普通城市居民的日常生活喜怒哀乐。老街两旁的建筑多为两三层砖木结构墙面斑驳窗棂古朴，楼上晾晒的衣物和楼下的小摊贩构成了最真实的武汉市井画面。老茶馆内仍有市民闲坐品茗谈笑风生。此处游客密度仅为江汉路的十分之一，是感受池莉笔下武汉市井生活和了解老汉口建筑文化的珍贵去处。', '湖北', 30.601400, 114.270600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/b/b1/Revolution_of_1911_Museum.jpg"]'),
('《风景》', '武汉市硚口区汉正街新安街遗址', '方方', '现代', '汉正街新安街遗址位于湖北省武汉市硚口区境内，是现代作家方方长篇小说《风景》中河南棚子的原型地。新安街曾是武汉最底层市民的聚居区保留着清末民初的木板房建筑、老码头与古巷。方方以此为背景描绘了一个底层家庭在狭小空间中挣扎求存的故事，深刻揭示了城市化进程中底层人物的命运悲欢。木板房低矮逼仄墙壁薄如纸片，巷道狭窄仅容一人侧身通过。老码头石阶延伸至汉江水中见证了汉正街数百年的商贸繁华。这里游客极少保持着老武汉最原始的市井面貌，是感受方方小说中底层生活质感和了解汉正街历史变迁的独特去处。', '湖北', 30.567600, 114.214500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/b/b8/Wuhan_CBD_Buildings.jpg"]'),
('《万箭穿心》', '武汉市武昌区昙华林胭脂路老街区', '方方', '现代', '昙华林胭脂路老街区位于湖北省武汉市武昌区境内，是现代作家方方长篇小说《万箭穿心》中李宝莉一家生活的原型地。胭脂路保留着明清古民居和民国洋房建筑，中西风格交融砖雕门楼和西式阳台并存展现了武昌近代以来中西文化碰撞的独特风貌。方方以此为背景塑造了坚韧泼辣的武汉女性李宝莉形象，深刻描绘了普通家庭的悲欢离合。老街巷道曲折幽深青石板路被岁月磨得光滑，两旁的古建筑斑驳沧桑但依然保持着优雅的建筑线条。此处游客密度仅为昙华林核心区的八分之一更为清幽，是感受方方小说中武汉女性精神和了解昙华林历史建筑的理想去处。', '湖北', 30.542000, 114.294200, '其他', '["https://img0.baidu.com/it/u=3608607510,1429933050&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《张居正》', '荆州市荆州区张居正故居遗址', '熊召政', '现代', '张居正故居遗址位于湖北省荆州市荆州区境内，是现代作家熊召政长篇历史小说《张居正》的创作源泉和主人公诞生地。张居正是明代最杰出的政治家和改革家在荆州度过了青少年时代。遗址保留着明代建筑和古碑以及详细的生平陈列，建筑格局典雅庄重展现了明代官宦之家的气派。熊召政耗费多年心血创作了这部全面展现张居正改革历程的鸿篇巨制。故居中陈列着张居正的政绩介绍、家族谱系和改革措施的详细解读。故居旁荆州古城城墙巍然矗立护城河碧波荡漾环境清幽。此处游客稀少是了解张居正改革思想和感受熊召政历史小说创作精神的重要文化遗址。', '湖北', 30.352400, 112.190100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/84/%E5%B1%B1%E4%B8%9C%E7%9C%81%E7%AC%AC%E5%9B%9B%E6%89%B9%E7%9C%81%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E5%90%8D%E5%8D%95%EF%BC%88%E5%85%B1%E8%AE%A1606%E5%A4%84%EF%BC%89.pdf"]'),
('《哥德巴赫猜想》', '武汉市武昌区武汉大学老图书馆遗址', '徐迟', '现代', '武汉大学老图书馆遗址位于湖北省武汉市武昌区境内，是现代作家徐迟创作报告文学《哥德巴赫猜想》的重要背景地。徐迟在此采访了数学家陈景润的事迹创作了这篇感动全国的报告文学。遗址保留着民国时期修建的老图书馆和古樟树，图书馆建筑中西合璧外观庄重典雅是武汉大学早期建筑群的代表作品。古樟树冠大叶密春日繁花似锦秋日金叶飘落。武汉大学依珞珈山而建东湖之畔校园风光被誉为全国最美大学之一。老图书馆见证了无数学者的潜心治学和报国情怀。此处游客密度仅为武大核心区的九分之一，是感受徐迟报告文学创作精神和欣赏武大民国建筑之美的清幽去处。', '湖北', 30.542000, 114.294200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/72/CADAL09002992_%E6%B9%96%E5%8C%97%E7%9C%81%E5%B9%B4%E9%91%92%C2%B7%E7%AC%AC%E4%B8%80%E5%9B%9E.djvu"]'),
('《大江保卫战》', '荆州市荆州区荆江大堤观音矶遗址', '佚名', '现代', '荆江大堤观音矶遗址位于湖北省荆州市荆州区境内，是记录1998年长江抗洪斗争的纪实文学《大江保卫战》的核心背景地。1998年长江特大洪水期间荆江大堤险情频发军民团结一心保卫大堤谱写了感天动地的抗洪壮歌。遗址保留着明代修建的大堤和古碑，观音矶是荆江大堤上最险要的地段之一大堤巍然矗立于长江之畔。从观音矶远眺长江水面辽阔波涛翻涌气势磅礴。大堤上至今仍保留着1998年抗洪的标记和纪念碑铭刻着那段惊心动魄的历史。此处游客稀少保持着历史遗址的原始风貌，是了解1998年抗洪历史和感受荆江大堤防洪文化以及欣赏长江壮阔风光的重要纪念地。', '湖北', 30.352400, 112.190100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/4b/Qutang_Gorge_on_Changjiang.jpg"]'),
('《湖光水色》', '荆州市公安县淤泥湖湿地遗址', '陈应松', '现代', '淤泥湖湿地遗址位于湖北省荆州市公安县境内，是现代作家陈应松创作《湖光水色》的灵感来源地。陈应松在此写下了漫无边际的芦苇被水鸟的声音穿透的优美文字。淤泥湖是江汉平原上一处保存完好的原始湿地，湖面辽阔芦苇荡漾候鸟云集生态环境极为优良。湿地中水草丰茂鱼虾成群白鹭翩飞野鸭嬉戏构成了一幅原始自然的生态画卷。春日芦芽初露嫩绿如茵夏日荷花盛开满湖碧翠秋日芦花飞雪银装素裹冬日候鸟南归热闹非凡四季皆有不同景致。此处游客极少远离城市喧嚣保持着最原始的湿地风貌，是感受陈应松笔下湿地之美和观赏候鸟生态的珍贵自然去处。', '湖北', 30.058000, 112.229800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/7a/Optics_Valley_Square.jpg"]'),
('《武当山记》', '十堰市丹江口市武当山太子坡遗址', '余秋雨', '现代', '武当山太子坡遗址位于湖北省十堰市丹江口市境内，是当代作家余秋雨创作《武当山记》的历史背景地。余秋雨在文中写下了武当山中国道教的圣地的赞叹，以文化散文的笔法深入探讨了武当山在中国道教史上的崇高地位。太子坡保留着明代建筑和古碑，建筑群依山势递进布局精巧一里四道门九曲黄河墙设计令人叹服。复真观是太子坡的核心建筑殿堂庄严道教文物丰富。太子坡周围松柏苍翠山林清幽云雾时聚时散仙气飘渺。余秋雨以深邃的历史眼光审视武当文化赋予了这座道教圣山新的文化解读。此处游客极少是感受余秋雨文化散文和体验武当道教文化的清幽去处。', '湖北', 32.540700, 111.512900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/3f/Wudangshan_pic_7.jpg"]'),
('《荆州古城记》', '荆州市荆州区荆州古城大北门遗址', '余秋雨', '现代', '荆州古城大北门遗址位于湖北省荆州市荆州区境内，是当代作家余秋雨创作《荆州古城记》的历史背景地。余秋雨在文中写道荆州古城三国文化的见证，以文化散文的视角重新审视了荆州在中国历史上的重要地位。大北门保留着明代修建的城墙和古碑，城墙高大厚实保存完好城门洞深邃幽暗透着千年历史的沧桑。护城河环绕城下水面宽阔碧波荡漾春日杨柳依依秋日红叶映城。从大北门登临城墙远眺荆州古城全貌和远处江汉平原的辽阔景色气象万千。余秋雨以独特的文化视角为荆州古城赋予了新的时代意义。此处游客稀少是感受余秋雨文化散文和了解荆州古城历史的重要文化去处。', '湖北', 30.352400, 112.190100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/19/%E8%8D%86%E5%B7%9E%E5%8F%A4%E5%9F%8E%E5%AE%BE%E9%98%B3%E6%A5%BC.jpg"]');
INSERT INTO works (title, scenic_spot, author, dynasty, description, province, latitude, longitude, category, images) VALUES
('《离骚》', '岳阳市汨罗市屈子祠玉笥山', '屈原', '战国楚', '汨罗市屈子祠玉笥山位于湖南省岳阳市境内，是战国时期伟大爱国诗人屈原创作《离骚》的晚年居住地。屈原被放逐后流落至汨罗江畔在玉笥山上度过了生命中最后的岁月，写下了路漫漫其修远兮吾将上下而求索的千古名篇。玉笥山上保留着屈子祠、独醒亭和骚坛等纪念建筑，屈子祠建筑古朴庄严祠内陈列着屈原生平事迹。独醒亭取自举世皆浊我独清众人皆醉我独醒之意。骚坛是历代文人祭祀屈原吟诵离骚的场所。每年端午节当地都会举办龙舟竞渡和祭祀屈原的盛大活动。山下汨罗江水清澈蜿蜒两岸绿树成荫，是了解屈原爱国精神和端午文化以及感受离骚文学魅力的重要纪念地。', '湖南', 28.806700, 113.066500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e5/Qu_Yuan_Temple%2C_Yueyang%2C_Hunan%2C_China_2022060303.jpg"]'),
('《渔翁》', '永州市零陵区朝阳岩遗址', '柳宗元', '唐代', '朝阳岩遗址位于湖南省永州市零陵区境内，是唐代文学家柳宗元被贬永州时创作《渔翁》的历史遗迹。柳宗元在此写下了欸乃一声山水绿的名句，以渔翁的悠然自在反衬自己贬谪生涯的孤独与释然。遗址保留着唐宋时期的摩崖石刻，石刻内容丰富涵盖柳宗元和后世文人的题记。朝阳岩面临潇水岩壁陡峭洞穴幽深，清晨阳光照射岩壁金光灿烂因此得名朝阳岩。潇水在此清澈见底碧波荡漾两岸青山倒映水中如诗如画。柳宗元在永州十年创作了大量山水散文和诗歌，朝阳岩是他最常游览的地方之一。这里游客稀少保持着唐代的清幽意境，是感受柳宗元永州山水文学和欣赏潇水风光的重要历史遗址。', '湖南', 26.221100, 111.631400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/76/NLC403-312001082774-160567_%E9%BE%8D%E6%B4%A5%E7%B8%A3%E8%AA%8C_1960_%E5%8D%B7%E4%B8%80.pdf"]'),
('《芙蓉楼送辛渐・其二》', '怀化市洪江市黔阳古城芙蓉楼', '王昌龄', '唐代', '黔阳古城芙蓉楼位于湖南省怀化市洪江市境内，是唐代边塞诗人王昌龄被贬龙标时送别好友辛渐的历史遗迹。王昌龄在此写下了洛阳亲友如相问一片冰心在玉壶的千古名句，以冰心玉壶自喻表明了高洁的品格。芙蓉楼保留着唐代碑刻和古代建筑，楼阁飞檐翘角古朴典雅依沅江而建。黔阳古城是湘西最古老的城市之一保留着完整的明清古街巷和古民居。古城中青石板路曲折幽深两旁古屋错落有致，比凤凰古城更为清幽少了商业化的喧嚣。沅江在城旁蜿蜒流过江水清澈两岸青山如画。这里是感受王昌龄贬谪诗中高洁精神和欣赏黔阳古城历史风貌的重要文化遗址。', '湖南', 27.208800, 109.831600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/9a/%E4%B8%AD%E5%9B%BD%E6%88%98%E5%8C%BA%E5%8F%97%E9%99%8D%E5%85%B8%E7%A4%BC%E4%BC%9A%E5%9C%BA%E5%A4%8D%E5%8E%9F.jpg"]'),
('《送柴侍御》', '邵阳市武冈市渠渡晴岚遗址', '王昌龄', '唐代', '渠渡晴岚遗址位于湖南省邵阳市武冈市境内，是唐代边塞诗人王昌龄创作《送柴侍御》的历史遗迹。王昌龄在此写下了青山一道同云雨明月何曾是两乡的千古名句，以山水相连明月共照表达了与友人虽分隔两地却心意相通的深情。遗址保留着唐代渠渡庙和晴岚桥等古建筑，渠渡庙建筑古朴供奉着当地信仰的神祇。晴岚桥横跨溪水之上桥身石砌古朴厚重。武冈古称都梁是王昌龄贬谪时期的居所之一。遗址周围山峦叠翠晴日里岚气蒸腾如纱如幔美不胜收，正应了晴岚之名。这里游客稀少保持着原始的自然风貌，是感受王昌龄送别诗中深厚情谊的清幽去处。', '湖南', 26.726700, 110.631600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/52/%E5%9F%8E%E6%AD%A5%E5%8D%97%E5%B1%B1%E9%A1%B620150927_-_panoramio.jpg"]'),
('《望天门山》', '张家界市永定区天门山云梦仙顶遗址', '李白', '唐代', '天门山云梦仙顶遗址位于湖南省张家界市永定区境内，是唐代诗仙李白创作《望天门山》的最佳观景点。李白在此写下了天门中断楚江开碧水东流至此回的壮丽诗句。遗址保留着唐代古寺遗址和摩崖石刻，石刻内容涵盖历代文人的游览题记。云梦仙顶位于天门山巅海拔一千五百余米视野极为开阔，从此处俯瞰峡谷深邃万丈云雾在脚下翻腾如同置身云端之上。天门洞是天门山的标志性景观巨大的石门洞穿山体蔚为壮观。山顶古寺遗址掩映于苍松翠柏之间环境清幽。这里是感受李白望天门山诗中那种天门中断的壮阔气势和俯瞰张家界山水奇观的绝佳去处。', '湖南', 29.129200, 110.474500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/52/%E4%B8%89%E5%85%83%E6%B4%9E_-_panoramio_-_%E9%99%88%E5%AE%8F%E5%AE%87_%281%29.jpg"]'),
('《与夏十二登岳阳楼》', '岳阳市岳阳楼区岳阳楼仙梅亭遗址', '李白', '唐代', '岳阳楼仙梅亭遗址位于湖南省岳阳市岳阳楼区境内，是唐代诗仙李白创作《与夏十二登岳阳楼》的历史遗迹。李白与友人夏十二登楼赋诗在此留下了醉后凉风起吹人舞袖回的潇洒诗句。遗址保留着明代仙梅石刻和清代碑刻，仙梅石刻上天然形成的梅花纹路栩栩如生令人称奇。从仙梅亭远眺洞庭湖水天一色浩渺无际，远处君山岛如青螺浮于水面若隐若现。亭旁古木参天环境清幽与岳阳楼核心区的喧嚣形成对比。李白一生多次到岳阳楼饮酒赋诗留下了多首脍炙人口的诗篇。这里是感受李白在岳阳楼上的潇洒诗情和欣赏洞庭湖壮美风光的理想去处。', '湖南', 29.356900, 113.129200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/1b/Frontal_view_of_Yueyang_Tower%2C_Hunan%2C_China1.jpg"]'),
('《望洞庭湖赠张丞相》', '岳阳市君山区君山岛湘妃祠遗址', '孟浩然', '唐代', '君山岛湘妃祠遗址位于湖南省岳阳市君山区境内，是唐代田园诗人孟浩然创作《望洞庭湖赠张丞相》的历史遗迹。孟浩然在此写下了气蒸云梦泽波撼岳阳城的千古名句，以洞庭湖的浩渺壮阔自喻胸中抱负。遗址保留着唐代碑刻和千年古柏，碑刻记载了洞庭湖和君山岛的历史传说。湘妃祠供奉着舜帝二妃娥皇女英的神位，传说二妃追寻舜帝泪洒斑竹而殁化为湘水之神。从祠前远眺洞庭湖水天相接烟波浩渺，秋日湖上烟雨蒙蒙更添几分凄美。这里是了解湘妃传说和感受孟浩然洞庭湖诗意以及欣赏君山岛自然风光的重要文化遗址。', '湖南', 29.461100, 113.004300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e7/Xiangfei_Ancestral_Temple%2C_Junshan_Island.jpg"]'),
('《登岳阳楼》', '岳阳市岳阳楼区岳阳楼唐代台基遗址', '杜甫', '唐代', '岳阳楼唐代台基遗址位于湖南省岳阳市岳阳楼区境内，是唐代诗圣杜甫创作《登岳阳楼》的原始建筑基址。杜甫在此写下了昔闻洞庭水今上岳阳楼的深沉诗句，吴楚东南坼乾坤日夜浮更是气势磅礴。遗址保留着唐代夯土台基和历代碑刻，台基厚实坚固可见当年岳阳楼建筑之宏伟。杜甫晚年贫病交加登临岳阳楼时老泪纵横将个人身世之感融入山河壮美之中写下了这首千古绝唱。从台基远眺洞庭湖水天一色八百里洞庭烟波浩渺，远处君山岛如一粒青螺浮于水面。这里是感受杜甫登楼诗中那种忧国忧民情怀和欣赏洞庭湖原始壮美的珍贵历史遗址。', '湖南', 29.356900, 113.129200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/1b/Frontal_view_of_Yueyang_Tower%2C_Hunan%2C_China1.jpg"]'),
('《江南逢李龟年》', '长沙市开福区李龟年故居遗址', '杜甫', '唐代', '李龟年故居遗址位于湖南省长沙市开福区境内，是唐代诗圣杜甫创作《江南逢李龟年》的历史遗迹。杜甫在此与流落江南的宫廷乐师李龟年重逢写下了正是江南好风景落花时节又逢君的千古名句。遗址保留着唐代建筑基址和历代碑刻，建筑基址虽已残破但仍可窥见当年规模。李龟年是唐玄宗时期最杰出的宫廷乐师安史之乱后流落江南在长沙度过了晚年。杜甫与李龟年的重逢承载着盛唐衰落的深重感慨，落花时节四字蕴含了无限的人生沧桑。遗址周围是长沙老城区的传统街巷保留着部分古建筑。这里是感受杜甫落花时节诗中那份沧桑和了解唐代音乐文化的重要历史遗址。', '湖南', 28.256000, 112.985400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/cc/%E7%88%B1%E6%99%9A%E4%BA%AD%EF%BC%88%E7%A7%8B-%E4%BE%A7%E9%9D%A2%EF%BC%89.jpg"]'),
('《秋词・其一》', '常德市武陵区德山孤峰岭遗址', '刘禹锡', '唐代', '德山孤峰岭遗址位于湖南省常德市武陵区境内，是唐代诗人刘禹锡被贬朗州时创作《秋词》的历史遗迹。刘禹锡在此写下了自古逢秋悲寂寥我言秋日胜春朝的豪迈诗句，一反传统悲秋情调以昂扬乐观的心态歌颂秋天之美。遗址保留着唐代古寺遗址和历代碑刻，孤峰岭虽不高大但地势突出四周开阔。刘禹锡被贬朗州长达十年在此期间创作了大量优秀诗文展现了百折不挠的精神。从孤峰岭远眺秋日常德平原金黄的稻田与蔚蓝的天空交相辉映，一鹤排云上便引诗情到碧霄的意境跃然眼前。这里是感受刘禹锡乐观豁达精神和欣赏常德秋日田园风光的重要历史遗址。', '湖南', 29.028800, 111.683300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/71/The_peach_garden_1.jpg"]'),
('《逢雪宿芙蓉山主人》', '长沙市宁乡市大芙蓉山遗址', '刘长卿', '唐代', '大芙蓉山遗址位于湖南省长沙市宁乡市境内，是唐代诗人刘长卿创作《逢雪宿芙蓉山主人》的历史遗迹。刘长卿在此写下了日暮苍山远天寒白屋贫的名句，以简洁的笔墨描绘了一幅风雪夜宿山村的画面。遗址保留着唐代古寺遗址和古驿道遗迹，驿道石板路蜿蜒于山间连接着长沙与湘西的交通要道。大芙蓉山海拔较高冬季常有降雪，雪后山林银装素裹白茫茫一片与诗中天寒白屋贫的意境高度吻合。山中林木茂密溪流清澈鸟鸣幽幽四季景色各异。古驿道上行走仿佛穿越千年回到了唐代旅人投宿山村的场景。这里是感受刘长卿逢雪诗意境和体验湖南山村自然风光的清幽去处。', '湖南', 28.227700, 112.551400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/80/CADAL09001603_%E8%94%A1%E6%9D%BE%E5%9D%A1.djvu"]'),
('《题君山》', '岳阳市君山区君山岛柳毅井遗址', '雍陶', '唐代', '君山岛柳毅井遗址位于湖南省岳阳市君山区境内，是唐代诗人雍陶创作《题君山》的历史遗迹。遗址保留着唐代石刻和古亭建筑，柳毅井相传是唐代传奇小说柳毅传中柳毅入龙宫的入口所在。雍陶登临君山岛被洞庭湖的壮美景色打动写下了题君山诗篇。柳毅井口圆形井壁以青石砌筑井水清澈终年不竭，传说井底通往洞庭龙宫充满了浪漫的神话色彩。君山岛四面环水洞庭湖碧波万顷岛上古木参天竹林苍翠，斑竹林中湘妃泪痕斑斑的传说更增添了几分凄美诗意。这里是了解柳毅传书传奇故事和欣赏君山岛洞庭湖风光的重要文化遗址。', '湖南', 29.461100, 113.004300, '其他', '["https://img0.baidu.com/it/u=1452652323,1971055165&fm=253&fmt=auto&app=138&f=JPEG?w=759&h=500"]'),
('《题衡岳》', '衡阳市南岳区衡山祝融峰观日台遗址', '韩愈', '唐代', '衡山祝融峰观日台遗址位于湖南省衡阳市南岳区境内，是唐代文学家韩愈创作《题衡岳》的历史遗迹。韩愈在此写下了祝融万丈拔地起欲见不见轻烟里的壮丽诗句。遗址保留着唐代古碑和观日亭建筑，祝融峰是衡山最高峰海拔一千三百余米为南岳衡山的绝顶。观日台位于峰顶是观赏衡山日出的最佳地点，清晨登临此处可见东方天际由墨蓝渐变为橘红一轮红日从云海中喷薄而出景色壮丽震撼。韩愈登衡山时被祝融峰的雄伟气势所打动留下了这首传世名篇。峰顶风大常年云雾缭绕晴日时可远眺数百里湘南大地。这里是感受韩愈衡岳诗中雄伟气势和欣赏衡山日出壮观景象的绝佳去处。', '湖南', 27.232300, 112.738800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/90/Zhurong_Hall%2C_Mount_Heng_%28Hunan%29%2C_picture2.jpg"]'),
('《游南岳》', '衡阳市南岳区衡山邺侯书院遗址', '李泌', '唐代', '衡山邺侯书院遗址位于湖南省衡阳市南岳区境内，是唐代名臣李泌的隐居读书之地。李泌是唐代著名宰相曾辅佐四朝天子但性好道家学说多次辞官隐居衡山修道读书。遗址保留着唐代建筑基址和古碑，书院依山而建环境清幽林木繁茂。李泌在此潜心研读经史子集和道家典籍，为后来出山辅政奠定了深厚的学识基础。书院周围古木参天溪流潺潺鸟鸣啾啾，山中云雾时聚时散恍如仙境。邺侯是李泌的封号后人为纪念他在此修建了邺侯书院。从书院远眺衡山群峰连绵起伏气势磅礴。这里是了解李泌传奇人生和感受唐代隐逸文化以及欣赏衡山幽静之美的重要历史遗址。', '湖南', 27.232300, 112.738800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/df/Academy_of_Marquis_Ye%2C_Mount_Heng_%28Hunan%29.jpg"]'),
('《踏莎行・郴州旅舍》', '郴州市苏仙区苏仙岭三绝碑遗址', '秦观', '北宋', '苏仙岭三绝碑遗址位于湖南省郴州市苏仙区境内，是北宋词人秦观被贬郴州时创作《踏莎行·郴州旅舍》的历史遗迹。碑上刻有秦观的词作、苏轼的跋语和米芾的书法三位北宋文艺大师的作品汇集于一碑被誉为天下三绝碑。秦观词中郴江幸自绕郴山为谁流下潇湘去的深沉感慨表达了贬谪之苦和思乡之情。苏轼读后深为感动亲笔题跋，米芾更以其独特的书法风格将词和跋镌刻于碑。苏仙岭山势秀丽林木葱郁登山途中石径蜿蜒鸟语花香。三绝碑矗立于山间亭内古朴厚重令人肃然起敬。这里是了解北宋三大文艺巨匠交汇和感受秦观贬谪词情的珍贵文化遗址。', '湖南', 25.797300, 113.042100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/98/Su_shi.jpg"]'),
('《鹊桥仙・纤云弄巧》', '郴州市苏仙区苏仙岭白鹿洞遗址', '秦观', '北宋', '苏仙岭白鹿洞遗址位于湖南省郴州市苏仙区境内，是北宋词人秦观被贬郴州时创作《鹊桥仙·纤云弄巧》的历史遗迹。秦观在此写下了两情若是久长时又岂在朝朝暮暮的千古名句，以牛郎织女的坚贞爱情表达了超越时空的情感哲理。遗址保留着宋代摩崖石刻和古碑，白鹿洞是秦观被贬郴州时的居所之一洞穴幽深清凉。秦观在郴州度过了人生中最艰难的岁月但他的词作却在这段时期达到了艺术巅峰。白鹿洞周围松柏苍翠山涧清泉叮咚环境幽静。从洞前远眺郴州城郭山水相映风光秀美。这里是感受秦观爱情词中那种超越时空的深情和了解北宋词人贬谪生涯的重要历史遗址。', '湖南', 25.797300, 113.042100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/82/%E5%9B%BD%E5%AE%B6%E5%85%AC%E8%B7%AF%E7%BD%91%E8%A7%84%E5%88%92.pdf"]'),
('《题西林壁》', '衡阳市南岳区衡山方广寺遗址', '苏轼', '北宋', '衡山方广寺遗址位于湖南省衡阳市南岳区境内，是北宋文豪苏轼创作《题西林壁》的历史背景地之一。苏轼在此写下了横看成岭侧成峰远近高低各不同的哲理名句，以山峰的多角度观察揭示了认识事物的辩证方法。遗址保留着宋代建筑和古碑，方广寺始建于南朝是衡山最古老的寺院之一。寺院深藏于衡山深处四周群峰环绕林木蔽日溪流潺潺，是衡山最幽静的禅修之所。寺院建筑古朴典雅殿堂庄严香烟缭绕。从寺院远眺衡山群峰角度不同景致各异正应了横看成岭侧成峰的诗意。这里是感受苏轼哲理诗意境和体验衡山深处禅修清幽之美的绝佳去处。', '湖南', 27.232300, 112.738800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/d1/HengshanMountains.JPG"]'),
('《水调歌头・明月几时有》', '长沙市岳麓区岳麓山云麓宫遗址', '苏轼', '北宋', '岳麓山云麓宫遗址位于湖南省长沙市岳麓区境内，是北宋文豪苏轼创作《水调歌头·明月几时有》的历史背景地之一。苏轼被贬黄州前途经长沙在岳麓山上赏月对月怀人。遗址保留着宋代建筑和古碑，云麓宫位于岳麓山巅是长沙最高的道教宫观。从云麓宫远眺长沙城郭湘江蜿蜒而过橘子洲如一叶扁舟浮于江心，夜晚万家灯火璀璨如繁星。中秋之夜明月高悬月光洒满山巅更能体会苏轼人有悲欢离合月有阴晴圆缺的深沉感慨。云麓宫建筑古朴典雅道教文物丰富。这里是感受苏轼明月几时有词中那份旷达和俯瞰长沙城市风光的重要文化遗址。', '湖南', 28.234800, 112.931300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/5d/Yulu-Moutains2-en.jpg"]'),
('《满江红・写怀》', '岳阳市岳阳楼区岳阳楼景区岳武穆祠遗址', '岳飞', '南宋', '岳阳楼景区岳武穆祠遗址位于湖南省岳阳市岳阳楼区境内，是南宋抗金名将岳飞创作《满江红·写怀》的重要纪念地。岳飞一生精忠报国壮志未酬含冤而死，其怒发冲冠凭栏处潇潇雨歇的词句激荡着千年以来中华儿女的爱国热情。遗址保留着宋代碑刻和岳飞雕像，祠堂建筑庄严肃穆供奉着岳飞塑像和历代纪念碑刻。岳飞雕像高大威武目光炯炯凝望远方展现了一代名将的英武气概。从祠前远眺洞庭湖烟波浩渺气象万千，与岳飞词中三十功名尘与土八千里路云和月的壮阔意境遥相呼应。这里是缅怀岳飞爱国精神和感受满江红豪壮气概的重要纪念地。', '湖南', 29.356900, 113.129200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/1b/Frontal_view_of_Yueyang_Tower%2C_Hunan%2C_China1.jpg"]'),
('《桃花源诗》', '常德市桃源县桃花源秦人村遗址', '陶渊明', '东晋', '桃花源秦人村遗址位于湖南省常德市桃源县境内，是东晋大诗人陶渊明笔下《桃花源诗》的原型地。陶渊明在《桃花源记》中描绘了一个土地平旷屋舍俨然有良田美池桑竹之属的世外桃源，秦人村正是这一理想社会的真实映射。遗址保留着明清古民居和老磨坊，村中房屋依山傍水错落有致保持着传统的农耕生活方式。老磨坊中的石磨还能转动诉说着千年以来不变的乡村生活。村中小路蜿蜒曲折两旁桃树成林春日桃花盛开落英缤纷恍如仙境。村民淳朴热情保留着传统习俗和手工技艺。这里是体验陶渊明桃花源理想和感受湖南乡村田园生活的绝佳去处。', '湖南', 28.902500, 111.488900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/71/The_peach_garden_1.jpg"]'),
('《题岳阳楼》', '岳阳市岳阳楼区岳阳楼景区三醉亭遗址', '白居易', '唐代', '岳阳楼景区三醉亭遗址位于湖南省岳阳市岳阳楼区境内，是唐代诗人白居易创作《题岳阳楼》的历史遗迹。遗址保留着唐代碑刻和吕洞宾雕像，三醉亭得名于道教八仙之一吕洞宾三次醉饮岳阳楼的传说。白居易登临岳阳楼被洞庭湖的壮美景色所打动留下了脍炙人口的题咏。三醉亭建筑古朴典雅飞檐翘角与主楼相呼应。吕洞宾雕像栩栩如生手持拂尘仙风道骨。从亭内远眺洞庭湖波光粼粼帆影点点，晴日时水天一色令人心旷神怡。亭旁古柏苍劲枝叶繁茂见证了千年的岁月沧桑。这里是了解吕洞宾传说和欣赏白居易岳阳楼诗以及品味洞庭湖风光的重要文化遗址。', '湖南', 29.356900, 113.129200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/1b/Frontal_view_of_Yueyang_Tower%2C_Hunan%2C_China1.jpg"]'),
('《山行》', '长沙市岳麓区岳麓山爱晚亭遗址', '杜牧', '唐代', '岳麓山爱晚亭遗址位于湖南省长沙市岳麓区境内，是唐代诗人杜牧创作《山行》的历史遗迹。杜牧在此写下了停车坐爱枫林晚霜叶红于二月花的千古名句，将秋日枫叶之美描绘得淋漓尽致。遗址保留着清代碑刻和古枫树群，爱晚亭因杜牧诗句而得名是中国四大名亭之一。亭子建于清乾隆年间为重檐八柱攒尖顶结构，亭额上爱晚亭三字由毛泽东亲笔题写。深秋时节亭周围枫叶层林尽染红似火焰与亭子的朱红色交相辉映美不胜收。岳麓山是长沙名山山中古树参天清泉石上流。毛泽东青年时代曾在此读书求学留下了许多革命足迹。这里是欣赏杜牧山行诗意和长沙秋日枫叶盛景的绝佳去处。', '湖南', 28.234800, 112.931300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/5d/Yulu-Moutains2-en.jpg"]'),
('《衡岳吟》', '衡阳市南岳区衡山藏经殿遗址', '朱元璋', '明代', '衡山藏经殿遗址位于湖南省衡阳市南岳区境内，是明代开国皇帝朱元璋创作《衡岳吟》的历史遗迹。朱元璋在此写下了衡山苍苍入紫冥的壮丽诗句。遗址保留着明代佛经和古碑，藏经殿始建于南朝陈代因明太祖朱元璋赐大藏经一部而得名。殿堂建筑庄严肃穆藏有大量珍贵佛经典籍。藏经殿深藏于衡山密林之中四周古木参天遮天蔽日，殿前有两棵千年银杏金秋时节满树金黄蔚为壮观。殿旁溪流潺潺鸟鸣啾啾环境极为幽静，是衡山最清静的禅修之所。朱元璋登基后对衡山格外推崇多次遣使祭祀。这里是了解明代皇家与衡山佛教渊源和体验衡山深处禅境之美的重要历史遗址。', '湖南', 27.232300, 112.738800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/d1/HengshanMountains.JPG"]'),
('《岳阳楼》', '岳阳市岳阳楼区岳阳楼景区怀甫亭遗址', '何景明', '明代', '岳阳楼景区怀甫亭遗址位于湖南省岳阳市岳阳楼区境内，是明代诗人何景明创作《岳阳楼》的历史遗迹。何景明在此写下了洞庭天下水岳阳天下楼的千古名句，高度概括了岳阳楼与洞庭湖的天下盛名。遗址保留着明代碑刻和杜甫雕像，怀甫亭是后人为纪念杜甫而建亭名取怀念杜甫之意。杜甫雕像神态忧郁目光深邃展现了诗圣晚年漂泊的沧桑。从怀甫亭远眺洞庭湖水天相接浩渺无边，湖上渔帆点点白鸥翔集。亭旁古柏苍劲枝叶如盖，秋日时落叶纷飞更添一份萧瑟之美。这里是纪念杜甫和何景明两位诗人以及品味洞庭湖壮美风光的重要文化遗址。', '湖南', 29.356900, 113.129200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/1b/Frontal_view_of_Yueyang_Tower%2C_Hunan%2C_China1.jpg"]'),
('《潇湘八景诗・渔村夕照》', '常德市汉寿县西洞庭湖渔村遗址', '米芾', '北宋', '西洞庭湖渔村遗址位于湖南省常德市汉寿县境内，是北宋书画家米芾创作《潇湘八景诗·渔村夕照》的原型地。米芾以洞庭湖畔渔村落日的美景为题材创作了渔村夕照这一经典画境。遗址保留着明清古民居和老渔船，渔村依水而建房屋错落有致青瓦白墙透着湖乡韵味。傍晚时分夕阳西下金色的阳光洒满湖面渔船归港炊烟袅袅，构成了一幅绝美的渔村夕照图。西洞庭湖是洞庭湖的重要组成部分湖面开阔水草丰美是候鸟栖息的天堂。冬季万千候鸟在此越冬蔚为壮观。这里游客稀少保持着原始的湖乡生活气息，是感受米芾潇湘八景画意和欣赏洞庭湖渔村落日风光的绝佳去处。', '湖南', 28.906100, 111.970700, '其他', '["https://img0.baidu.com/it/u=3330723059,18300239&fm=253&fmt=auto&app=138&f=JPEG?w=665&h=500"]'),
('《登壶瓶山》', '常德市石门县壶瓶山主峰遗址', '邹劲松', '当代', '壶瓶山主峰遗址位于湖南省常德市石门县境内，是当代诗人邹劲松创作《登壶瓶山》的历史遗迹。壶瓶山是湖南省最高峰海拔两千零九十九米被誉为湖南屋脊，独立湘天第一峰的赞誉名不虚传。遗址保留着唐代古驿道遗迹，驿道石板路蜿蜒于山间连接着湖南与湖北的交通要道。壶瓶山植被垂直分布明显从山脚到山顶依次分布着亚热带常绿阔叶林、温带落叶阔叶林和高山草甸。山中珍稀动植物众多，有华南虎、云豹等珍稀物种的历史分布记录。登顶远眺群山逶迤云海翻腾气势磅礴。这里是登临湖南最高峰和探索原始自然生态以及感受湘北雄山风光的绝佳去处。', '湖南', 29.584300, 111.379500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/5d/Mount_Heng_003.jpg"]'),
('《龙门出水》', '常德市石门县壶瓶山龙门洞遗址', '邹劲松', '当代', '壶瓶山龙门洞遗址位于湖南省常德市石门县境内，是当代诗人邹劲松创作《龙门出水》的历史遗迹。龙门洞是澧水支流渫水的源头之一，雪浪破空来的诗句生动描绘了泉水从洞中喷涌而出的壮观景象。遗址保留着天然钟乳石群，洞内钟乳石造型奇特千姿百态经过数十万年地质作用形成了令人叹为观止的溶洞奇观。洞口泉水终年不断清澈甘甜，水花飞溅如白龙出洞发出隆隆声响。龙门洞深处幽暗神秘探索其中仿佛进入了另一个世界。洞外山林茂密溪流潺潺空气清新宜人。这里是探索壶瓶山溶洞奇观和欣赏渫水源头壮观泉水以及体验石门山水之美的清幽去处。', '湖南', 29.584300, 111.379500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/31/Paektu-san.jpg"]'),
('《夹山茶禅》', '常德市石门县夹山寺遗址', '邹劲松', '当代', '夹山寺遗址位于湖南省常德市石门县境内，是当代诗人邹劲松创作《夹山茶禅》的历史遗迹。夹山寺是茶禅一味思想的发源地，唐代高僧善会禅师在此首创以茶参禅的修行方式影响深远。遗址保留着唐代建筑和古碑以及传统茶园，寺院建筑古朴庄严殿堂巍峨气势不凡。夹山寺周围茶园连绵起伏茶树嫩绿如毯春日采茶时节茶香弥漫。寺内古碑记载了茶禅一味的历史渊源和传承脉络。传说明末李自成兵败后出家于此法号奉天玉和尚为夹山寺增添了传奇色彩。寺旁古柏参天溪流清澈环境清幽。这里是了解茶禅一味文化源头和品味石门好茶以及感受夹山寺历史传奇的重要文化遗址。', '湖南', 29.584300, 111.379500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/50/Shimen.jpg"]'),
('《渠渡晴岚》', '邵阳市武冈市渠渡庙遗址', '王昌龄', '唐代', '渠渡庙遗址位于湖南省邵阳市武冈市境内，是唐代边塞诗人王昌龄创作《渠渡晴岚》的历史遗迹。王昌龄在此写下了盈盈晓气湿林函的优美诗句，描绘了晨雾中渠渡山水的空灵之美。遗址保留着唐代碑刻和千年古柏，渠渡庙建筑古朴供奉着当地信仰的水神和山神。古柏树干粗壮枝叶如盖见证了千余年的岁月沧桑。渠渡之地山水相依晴日时山岚蒸腾如轻纱缭绕，雨后更是烟雨蒙蒙宛如仙境。武冈古城历史悠久是王昌龄贬谪时期的重要居所。从庙前远眺武冈城郭青山环绕田园如画。这里是感受王昌龄贬谪诗中山水灵气和欣赏武冈晴岚美景的清幽去处。', '湖南', 26.726700, 110.631600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/49/Wugang0947.jpg"]'),
('《湘妃竹》', '岳阳市君山区君山岛斑竹园遗址', '刘禹锡', '唐代', '君山岛斑竹园遗址位于湖南省岳阳市君山区境内，是唐代诗人刘禹锡创作《湘妃竹》的历史遗迹。刘禹锡在此写下了泪痕点点寄相思的深情诗句，以斑竹上的泪痕传达了对湘妃传说的感慨。遗址保留着唐代古碑和大片斑竹林，斑竹又名湘妃竹竹竿上天然分布着紫色斑点状如泪痕。传说舜帝南巡驾崩于苍梧之野其二妃娥皇女英追至君山泪洒斑竹化为湘水之神。斑竹园中竹影婆娑清风拂过竹叶沙沙作响如泣如诉。从竹园远眺洞庭湖水天一色烟波浩渺。君山岛四面环水空气清新是远离喧嚣的世外桃源。这里是了解湘妃传说和欣赏斑竹林美景以及品味君山岛洞庭湖风光的重要文化遗址。', '湖南', 29.461100, 113.004300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/1b/Frontal_view_of_Yueyang_Tower%2C_Hunan%2C_China1.jpg"]'),
('《边城》', '湘西州花垣县边城镇茶峒古镇', '沈从文', '现代', '边城镇茶峒古镇位于湖南省湘西州花垣县境内，是现代文学大师沈从文创作《边城》的核心原型地。小说中翠翠和傩送的凄美爱情故事就发生在这个湘渝黔三省交界的小镇。古镇保留着吊脚楼群、拉拉渡和白塔等标志性建筑，吊脚楼依河而建木柱支撑凌空悬挑于水面之上展现了湘西独特的建筑风格。拉拉渡是小说中翠翠祖父撑渡的原型用粗绳牵引木船来回摆渡极具边城风情。白塔矗立于山头是茶峒古镇的地标。清水江穿城而过水质清澈碧绿，两岸青山对峙古木参天。这里是感受沈从文笔下湘西边城诗意和体验苗族土家族民俗风情的绝佳去处。', '湖南', 28.572000, 109.482000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/a/af/Fenghuang_County%2C_Hunan%2C_China%2C_21_December_2016b.jpg"]'),
('《湘行散记》', '湘西州泸溪县浦市古镇', '沈从文', '现代', '浦市古镇位于湖南省湘西州泸溪县境内，是现代文学大师沈从文创作《湘行散记》的重要取材地。沈从文沿沅水返乡途中在浦市古镇停留留下了大量描绘沅水流域风土人情的优美散文。古镇保留着明清古街和老会馆等历史建筑，古街青石板路蜿蜒曲折两旁古屋鳞次栉比。浦市是沅水流域最大的商贸码头明清时期商贾云集商铺林立极为繁华。老会馆建筑宏伟雕刻精美见证了当年的商业盛况。沅水在此宽阔平缓水面如镜两岸青山倒映水中。古镇中至今保留着传统的手工艺和民俗活动。这里是感受沈从文湘行散记中沅水风情和欣赏湘西古镇历史风貌的重要文化遗址。', '湖南', 28.216300, 110.217800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/a/af/Fenghuang_County%2C_Hunan%2C_China%2C_21_December_2016b.jpg"]'),
('《山乡巨变》', '益阳市赫山区谢林港镇清溪村', '周立波', '现代', '谢林港镇清溪村位于湖南省益阳市赫山区境内，是现代作家周立波创作《山乡巨变》的核心原型地。周立波以家乡清溪村为背景描绘了中国南方农村合作化运动的历史画卷。清溪村被誉为中国文学第一村保留着周立波故居和老茶园等历史遗迹。周立波故居是一座典型的湘中民居青砖黛瓦古朴典雅，屋内陈列着周立波的生平事迹和创作手稿。老茶园中茶树成行翠绿如毯春日采茶时节茶香满村。清溪村依山傍水田园风光秀美，村中小溪清澈见底两岸绿树成荫。如今清溪村已成为乡村文学旅游的典范。这里是了解周立波文学创作和感受湖南乡村田园生活的重要文化遗址。', '湖南', 28.574300, 112.374300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/1d/Former_Residence_of_Zhou_Libo%2C_Picture2.jpg"]'),
('《山南水北》', '岳阳市汨罗市三江镇八景村', '韩少功', '现代', '三江镇八景村位于湖南省岳阳市汨罗市境内，是当代作家韩少功创作《山南水北》的取材地。韩少功从城市迁居至此在乡村生活中获得了丰富的创作灵感写下了这部描绘当代中国乡村变迁的散文巨作。村中保留着韩少功文学馆和八景洞水库等标志性景点。韩少功文学馆展示了作家的创作历程和代表作品。八景洞水库碧波荡漾四周青山环抱湖光山色美不胜收。八景村地处汨罗江流域是典型的湘北丘陵地貌，山不高但起伏连绵水不深但清澈灵动。村中保留着传统的农耕生活方式稻田与菜园交错分布。这里是了解韩少功文学创作和体验当代中国乡村生活以及欣赏汨罗山水风光的理想去处。', '湖南', 28.806700, 113.066500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/6/64/County-level_divsions_of_Hunan.png"]'),
('《漫水》', '怀化市溆浦县卢峰镇漫水村', '王跃文', '现代', '溆浦县卢峰镇漫水村位于湖南省怀化市境内，是当代作家王跃文创作《漫水》的核心原型地。王跃文以家乡漫水村为背景描绘了湘西乡村的日常生活和人情世故。漫水村保留着明清古民居和原始的田园风光，古民居青砖黛瓦马头墙高耸展现了典型的湘西民居风格。村中稻田连绵溪水潺潺四季景色各异，春日油菜花黄秋日稻穗金黄冬日薄雾如纱。漫水村地处雪峰山脉腹地山高林密空气清新。村民淳朴热情保留着传统的民俗和手工技艺。王跃文以细腻的笔触将乡村的温情与沧桑展现得淋漓尽致。这里是感受王跃文漫水小说中乡村温情和体验溆浦田园生活的清幽去处。', '湖南', 27.908200, 110.594000, '其他', '["https://img2.baidu.com/it/u=549783072,832846733&fm=253&fmt=auto&app=138&f=JPEG?w=770&h=500"]'),
('《家山》', '怀化市溆浦县统溪河镇雁鹅界古村落', '王跃文', '现代', '溆浦县统溪河镇雁鹅界古村落位于湖南省怀化市境内，是当代作家王跃文创作《家山》的核心原型地。小说中凉水界的原型就是这个深藏于雪峰山脉中的古老村落。村中保留着二十多栋古木屋和多个非遗工坊，古木屋以杉木建造木质结构精巧飞檐翘角古朴典雅。非遗工坊中传承着古老的竹编、织布和酿酒等传统手工技艺。雁鹅界地处高山之巅云雾缭绕四季景色变幻莫测，清晨云海翻腾如同置身仙境。村中古道蜿蜒连接着山上山下的村落，石板路上青苔斑驳诉说着岁月的沧桑。这里是感受王跃文家山文学意境和探访雪峰山深处古村落以及体验湘西非遗文化的绝佳去处。', '湖南', 27.908200, 110.594000, '其他', '["https://img1.baidu.com/it/u=1409094490,2744752639&fm=253&fmt=auto&app=138&f=JPEG?w=752&h=500"]'),
('《芙蓉镇》', '湘西州永顺县芙蓉镇五里石板街', '古华', '现代', '芙蓉镇五里石板街位于湖南省湘西州永顺县境内，是现代作家古华创作《芙蓉镇》的核心原型地。小说中胡玉音米豆腐摊的故事就发生在这条千年古街上，后被改编为经典同名电影。五里石板街保留着明清吊脚楼和老商铺等历史建筑，吊脚楼依瀑布而建木柱支撑凌空悬挑于水面之上气势恢宏。古街青石板路光可鉴人两旁店铺林立至今仍能品尝到正宗的米豆腐。芙蓉镇瀑布从镇中穿过落差数十米水花飞溅如银练垂挂蔚为壮观。瀑布两侧吊脚楼群层层叠叠灯火阑珊极具湘西风情。酉水在镇旁奔流不息两岸青山对峙。这里是感受古华芙蓉镇小说中那个时代记忆和欣赏湘西吊脚楼瀑布奇观的重要文化遗址。', '湖南', 29.001000, 109.853000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/7f/%E7%BE%8E%E4%B8%BD%E7%9A%84%E5%B1%B1%E6%9D%91-%E6%88%91%E5%8F%AF%E7%88%B1%E7%9A%84%E5%AE%B6%E4%B9%A1_-_panoramio.jpg"]'),
('《永州八记・小石潭记》', '永州市零陵区小石潭遗址', '柳宗元', '唐代', '小石潭遗址位于湖南省永州市零陵区境内，是唐代文学家柳宗元创作《永州八记·小石潭记》的历史遗迹。柳宗元在此写下了潭中鱼可百许头皆若空游无所依的经典描写，将小石潭的清澈见底描绘得如在眼前。遗址保留着唐代摩崖石刻和古亭，石刻内容涵盖柳宗元原文和后世文人的题记。小石潭四周竹林环绕环境幽静水质清澈透明可以看到潭底的石头和游鱼。柳宗元被贬永州期间常常独自游览山水以排遣内心的苦闷写下了永州八记这一系列山水散文名篇。潭旁古亭可以静坐观鱼听竹林风声。这里是感受柳宗元小石潭记中那份清幽寂寞和欣赏永州山水之美的重要历史遗址。', '湖南', 26.221100, 111.631400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/39/CADAL09007737_%E5%9A%B4%E9%99%B5%E9%9B%86.djvu"]'),
('《永州八记・钴鉧潭记》', '永州市零陵区钴鉧潭遗址', '柳宗元', '唐代', '钴鉧潭遗址位于湖南省永州市零陵区境内，是唐代文学家柳宗元创作《永州八记·钴鉧潭记》的历史遗迹。钴鉧即古代熨斗因潭形似熨斗而得名。遗址保留着唐代建筑基址和古碑，潭水清澈碧绿深不见底四周岩石嶙峋形态各异。柳宗元在此写下了对钴鉧潭地形地貌的精确描写，将潭水的深邃和周围山石的奇特刻画得入木三分。钴鉧潭与小石潭相距不远同属于冉溪水系，溪水从上游奔流而下在此汇聚成潭水声潺潺。潭旁古木参天藤萝缠绕阳光透过树冠洒落在水面上斑驳陆离。柳宗元被贬永州后买下了钴鉧潭西面的小丘常在此流连忘返。这里是感受柳宗元永州八记文学意境和欣赏永州山水地质奇观的重要历史遗址。', '湖南', 26.221100, 111.631400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/54/%E6%9F%B3%E5%AE%97%E5%85%83%E8%82%96%E5%83%8F.jpg"]'),
('《岳阳楼记》', '岳阳市岳阳楼区岳阳楼唐代台基遗址', '范仲淹', '北宋', '岳阳楼唐代台基遗址位于湖南省岳阳市岳阳楼区境内，是北宋名臣范仲淹创作《岳阳楼记》的历史背景地。范仲淹虽未亲至岳阳但凭好友滕子京寄来的《洞庭晚秋图》写下了先天下之忧而忧后天下之乐而乐的千古名句。遗址保留着唐代夯土台基和宋代柱础，台基厚重坚实见证了岳阳楼千年的兴废更替。宋代柱础雕刻精美为研究宋代建筑提供了珍贵的实物资料。从台基远眺洞庭湖水天一色八百里洞庭尽收眼底，衔远山吞长江浩浩汤汤的壮阔景象与文中描绘高度吻合。这里是感受范仲淹忧乐精神和了解岳阳楼建筑历史以及欣赏洞庭湖壮美风光的珍贵历史遗址。', '湖南', 29.356900, 113.129200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/1b/Frontal_view_of_Yueyang_Tower%2C_Hunan%2C_China1.jpg"]'),
('《桃花源记》', '常德市桃源县桃花源秦人村遗址', '陶渊明', '东晋', '桃花源秦人村遗址位于湖南省常德市桃源县境内，是东晋大诗人陶渊明笔下《桃花源记》的原型地。陶渊明描绘的芳草鲜美落英缤纷、阡陌交通鸡犬相闻的世外桃源意境在此得到了最真实的呈现。遗址保留着原始的农耕生活方式，村民日出而作日落而息延续着千年以来自给自足的田园生活。村中房屋依山傍水土墙青瓦古朴自然，屋前屋后种满桃树春日桃花盛开落英缤纷恍如仙境。村中水田、菜园和竹林错落分布，黄发垂髫并怡然自乐的景象如同从文章中走出。溪水清澈鱼虾可见山林中鸟鸣不绝。这里是体验陶渊明桃花源记中世外桃源理想和感受中国传统农耕文明的绝佳去处。', '湖南', 28.902500, 111.488900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/71/The_peach_garden_1.jpg"]'),
('《水经注・湘水注》', '永州市零陵区潇水古渡遗址', '郦道元', '北魏', '潇水古渡遗址位于湖南省永州市零陵区境内，是北魏地理学家郦道元在《水经注·湘水注》中详细记载的潇水与湘水交汇之处。郦道元以精准的地理描写记录了潇湘合流的壮观景象，为后世了解湖南水系提供了珍贵的文献资料。遗址保留着明清古码头和老渡船，古码头青石台阶延伸入水经过数百年的江水冲刷已变得光滑圆润。老渡船虽已不再使用但仍停泊在岸边诉说着往昔的繁忙。潇水在此与湘水交汇两水相融形成宽阔的河面，水流平缓碧波荡漾两岸青山如黛。晨曦中薄雾笼罩江面渔船点点极具诗意。这里是了解郦道元水经注地理学成就和欣赏潇湘交汇壮观景象的重要历史遗址。', '湖南', 26.221100, 111.631400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/cc/Gate_of_Liuzi_Temple2_%28cropped%29.jpg"]'),
('《马桥词典》', '岳阳市平江县瓮江镇马桥村', '韩少功', '现代', '瓮江镇马桥村位于湖南省岳阳市平江县境内，是当代作家韩少功创作《马桥词典》的核心原型地。韩少功以独特的词典形式记录了湖南乡村的方言俗语和风土人情，开创了中国文学的新体裁。马桥村保留着明清古民居和老祠堂等历史建筑，古民居青砖黛瓦马头墙高耸展现了典型的湘北民居风格。老祠堂是村中最宏伟的建筑木雕石雕精美绝伦记载着家族的荣耀与传承。村中方言独特词汇丰富至今仍保留着许多古老的语言表达方式。马桥村地处丘陵地带稻田与茶园交错分布四季景色各异。村民淳朴热情保留着传统的民俗活动和手工技艺。这里是了解韩少功文学创作和探索湖南乡村语言文化的重要文化遗址。', '湖南', 28.701900, 113.581600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/1b/Frontal_view_of_Yueyang_Tower%2C_Hunan%2C_China1.jpg"]'),
('《乌龙山剿匪记》', '湘西州龙山县乌龙山乌龙寨遗址', '水运宪', '现代', '乌龙山乌龙寨遗址位于湖南省湘西州龙山县境内，是现代作家水运宪创作《乌龙山剿匪记》的核心原型地。小说描绘了解放初期湘西剿匪的惊心动魄故事后被改编为同名电视剧广为人知。遗址保留着明清古寨墙和吊脚楼等历史建筑，古寨墙以巨石垒筑坚固异常依山势蜿蜒于悬崖峭壁之间。吊脚楼群建于险峻的山崖之上木柱悬空结构精巧展现了湘西先民的建筑智慧。乌龙寨地势险要易守难攻三面临崖仅一条窄道可入，当年土匪盘踞于此负隅顽抗。寨中保留着当年剿匪的历史痕迹和老物件。从寨顶远眺群山连绵峡谷幽深云雾缭绕。这里是了解湘西剿匪历史和探访乌龙山险要地势以及体验湘西民俗风情的重要历史遗址。', '湖南', 29.457900, 109.443300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/b/b9/CADAL09014207_%E5%9C%8B%E9%9A%9B%E5%8F%8D%E4%BE%B5%E7%95%A5%E9%81%8B%E5%8B%95%E5%A4%A7%E6%9C%83%E7%B0%A1%E5%8F%B2.djvu"]'),
('《曾国藩》', '娄底市双峰县荷叶镇富厚堂', '唐浩明', '现代', '荷叶镇富厚堂位于湖南省娄底市双峰县境内，是当代作家唐浩明创作长篇历史小说《曾国藩》的核心背景地。富厚堂是曾国藩的故居也是中国现存规模最大的晚清名人故居之一。故居保留着清代建筑和藏书楼等历史遗迹，建筑群规模宏大布局严谨体现了清代官宦人家的气派。藏书楼中曾收藏曾国藩毕生搜集的数十万卷古籍是当时中国最大的私人藏书楼之一。故居前后四进院落厅堂高大回廊环绕雕梁画栋精美绝伦。荷叶镇地处衡山余脉山清水秀稻田如毯。曾国藩在此度过了童年和青年时代留下了修身齐家的家训传统。这里是了解曾国藩生平和唐浩明文学创作以及感受晚清历史风云的重要文化遗址。', '湖南', 27.457000, 112.175400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/da/Tseng_Kuo-fan%27s_Former_Residence_020.JPG"]'),
('《沧浪之水》', '长沙市岳麓区湖南大学老校区', '阎真', '现代', '湖南大学老校区位于湖南省长沙市岳麓区境内，是当代作家阎真创作《沧浪之水》的重要背景地。小说以一位知识分子的精神蜕变历程深刻揭示了当代社会中理想与现实的冲突。老校区保留着民国建筑和老图书馆等历史建筑，民国建筑风格典雅中西合璧展现了二十世纪初期中国高等教育的历史风貌。老图书馆建筑宏伟藏书丰富是当年学子求知问道的重要场所。湖南大学前身为千年学府岳麓书院惟楚有材于斯为盛的学术传统绵延至今。校区依岳麓山而建古木参天环境清幽。漫步校园可以感受到深厚的学术氛围和历史底蕴。这里是了解阎真文学创作和感受湖南大学百年学府气韵的重要文化遗址。', '湖南', 28.234800, 112.931300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/cc/%E7%88%B1%E6%99%9A%E4%BA%AD%EF%BC%88%E7%A7%8B-%E4%BE%A7%E9%9D%A2%EF%BC%89.jpg"]'),
('《湘西往事》', '湘西州凤凰县山江镇苗人谷', '黄永玉', '现代', '山江镇苗人谷位于湖南省湘西州凤凰县境内，是现代文艺大师黄永玉创作《湘西往事》的取材地。黄永玉以画笔和文字记录了湘西苗族的原始风情和民间传说为世人打开了一扇了解苗族文化的窗口。苗人谷保留着原始苗寨建筑、老水车和古瀑布等自然人文景观。苗寨建筑以木结构为主依山而建层层叠叠与自然融为一体。老水车在溪流旁缓缓转动发出吱呀声响诉说着古老的农耕岁月。古瀑布从山崖飞泻而下水花四溅清凉宜人。苗人谷中苗族居民至今保留着传统的服饰、歌舞和银饰锻造等非遗技艺。比凤凰古城核心区更加原始和清幽。这里是感受黄永玉笔下湘西风情和探访苗族原始文化的绝佳去处。', '湖南', 27.948100, 109.598600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/a/af/Fenghuang_County%2C_Hunan%2C_China%2C_21_December_2016b.jpg"]'),
('《徐霞客游记・楚游日记》', '张家界市武陵源区金鞭溪遗址', '徐霞客', '明代', '金鞭溪遗址位于湖南省张家界市武陵源区境内，是明代大旅行家徐霞客在《徐霞客游记·楚游日记》中详细描绘的自然奇观。徐霞客写下了金鞭溪两岸奇峰林立的经典描述为后世认识张家界的地貌奇观奠定了基础。遗址保留着明代摩崖石刻和古桥，石刻记载了徐霞客的游览路线和见闻。金鞭溪全长约七公里沿溪而行两岸石英砂岩峰林拔地而起形态万千。溪水清澈见底碧绿如翡翠鱼虾在水中嬉戏。古桥横跨溪上石砌古朴与周围的山水浑然一体。金鞭岩是溪旁最壮观的石峰高达三百余米如一根巨大的金鞭插入云天。这里是感受徐霞客游记中张家界奇观和欣赏武陵源峰林溪水之美的重要自然遗址。', '湖南', 29.345800, 110.550700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/f/f0/CADAL06200565_%E5%8F%A4%E6%9C%AC%E5%B0%8F%E8%AA%AA%E9%9B%86%E6%88%90%EF%BC%9A%E9%87%91%E8%93%AE%E4%BB%99%E5%8F%B2.djvu"]'),
('《游岳阳楼记》', '岳阳市君山区君山岛朗吟亭遗址', '袁宏道', '明代', '君山岛朗吟亭遗址位于湖南省岳阳市君山区境内，是明代文学家袁宏道创作《游岳阳楼记》的历史遗迹。袁宏道写下了朗吟亭下洞庭波的优美诗句赞美了从朗吟亭眺望洞庭湖的壮美景色。遗址保留着明代碑刻和千年古柏，碑刻记载了袁宏道游览岳阳楼和君山岛的详细经过。朗吟亭位于君山岛高处视野开阔是眺望洞庭湖全景的最佳位置。从亭内远眺洞庭湖水天一色浩渺无际岳阳楼隐约可见。古柏苍劲挺拔枝叶如盖见证了数百年的岁月沧桑。君山岛四面环水空气清新鸟语花香。袁宏道是明代性灵派文学领袖其游记文笔清新活泼。这里是感受袁宏道游记文学和欣赏洞庭湖君山岛风光的重要文化遗址。', '湖南', 29.461100, 113.004300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/73/Yuanmingyuan_Ruins_of_Dashuifa_20120715.JPG"]'),
('《湖南通志・山川志》', '邵阳市新宁县崀山辣椒峰遗址', '陈宏谋', '清代', '崀山辣椒峰遗址位于湖南省邵阳市新宁县境内，是清代学者陈宏谋在《湖南通志·山川志》中详细记载的丹霞地貌奇观。崀山是中国丹霞地貌的典型代表被列入世界自然遗产名录。遗址保留着清代摩崖石刻和古栈道，石刻记载了崀山的地理特征和历史沿革。辣椒峰是崀山最具标志性的景观一座巨大的红色砂岩石柱拔地而起高达一百八十余米形似一根巨大的辣椒直插云天蔚为壮观。古栈道沿悬崖峭壁而建蜿蜒曲折行走其上可近距离感受丹霞地貌的鬼斧神工。崀山丹霞地貌发育完整类型丰富还有天生桥、天一巷等奇观。这里是欣赏崀山世界遗产级丹霞地貌和感受湘南山水奇观的绝佳去处。', '湖南', 26.433600, 110.856100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/f/f5/Mount_Langshan_in_Hunan%2C_Picture49.jpg"]');
INSERT INTO works (title, scenic_spot, author, dynasty, description, province, latitude, longitude, category, images) VALUES
('《爱莲说》', '永州市道县濂溪故里爱莲池遗址', '周敦颐', '北宋', '濂溪故里爱莲池遗址位于湖南省永州市道县境内，是北宋理学鼻祖周敦颐创作《爱莲说》的历史遗迹。周敦颐在此写下了出淤泥而不染濯清涟而不妖的千古名句，以莲花自喻表达了高洁的品格和独立的人格。遗址保留着宋代建筑和古碑以及爱莲池，池中至今种满荷花夏日花开满池亭亭玉立清香四溢。宋代建筑古朴典雅与荷花相映成趣。古碑上刻着爱莲说全文字迹清晰可辨。周敦颐是道县人也是宋明理学的开创者其太极图说和通书影响深远。濂溪故里还保留着周敦颐的读书台和故居遗址。道县地处湘南山清水秀民风淳朴。这里是了解周敦颐理学思想和感受爱莲说高洁精神以及欣赏荷花之美的重要文化遗址。', '湖南', 25.518000, 111.600500, '其他', '["https://img2.baidu.com/it/u=4167652434,3972223390&fm=253&fmt=auto&app=120&f=JPEG?w=608&h=341"]'),
('《岳麓书院记》', '长沙市岳麓区岳麓书院御书楼遗址', '朱熹', '南宋', '岳麓书院御书楼遗址位于湖南省长沙市岳麓区境内，是南宋理学大师朱熹创作《岳麓书院记》的历史遗迹。朱熹曾在岳麓书院讲学留下了惟楚有材于斯为盛的千古佳话。遗址保留着宋代古籍和古碑，御书楼是岳麓书院的藏书楼始建于宋代曾藏有大量珍贵典籍。岳麓书院是中国四大书院之一自北宋开宝九年建院至今已有千余年历史，是世界上最古老的仍在使用的高等学府之一。书院建筑群以中轴线对称布局讲堂、斋舍、祠庙和御书楼依次排列规制严整。朱熹与张栻在此会讲三日引来数千学子旁听传为佳话。书院内古木参天碑刻林立文化底蕴极为深厚。这里是了解朱熹理学和岳麓书院千年学脉的重要文化遗址。', '湖南', 28.234800, 112.931300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/0/0d/Changsha_Yuelu_Shuyuan_2014.03.04_08-09-37_%28adjusted%29.jpg"]'),
('《石鼓书院记》', '衡阳市石鼓区石鼓书院大观楼遗址', '朱熹', '南宋', '石鼓书院大观楼遗址位于湖南省衡阳市石鼓区境内，是南宋理学大师朱熹创作《石鼓书院记》的历史遗迹。石鼓书院是中国最古老的书院之一始建于唐代位于蒸水与湘水和耒水三江交汇处的石鼓山上。遗址保留着宋代碑刻、古籍和千年古柏，大观楼是书院中最宏伟的建筑可以俯瞰三江交汇的壮观景象。三江在此汇合水流湍急碧波翻涌场面蔚为壮观。宋代碑刻记载了书院的创建历史和历代名师的讲学活动。古柏苍劲挺拔枝叶如盖见证了书院千年的学术传统。朱熹在石鼓书院讲学期间培养了大批理学人才。石鼓山地势突出三面环水风光秀美。这里是了解中国书院文化源流和欣赏衡阳三江交汇壮观景象的重要文化遗址。', '湖南', 26.893300, 112.607600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/1c/%E7%9F%B3%E9%BC%93%E4%B9%A6%E9%99%A2%E6%AD%A3%E9%97%A8.jpg"]'),
('《长沙古物闻见记》', '长沙市芙蓉区马王堆汉墓遗址', '商承祚', '现代', '马王堆汉墓遗址位于湖南省长沙市芙蓉区境内，是现代学者商承祚在《长沙古物闻见记》中记录的重要考古遗址。马王堆汉墓是二十世纪中国最重大的考古发现之一出土了辛追夫人保存完好的千年女尸和素纱襌衣等大量珍贵文物。遗址保留着汉代墓坑和博物馆，墓坑深达数十米结构复杂展现了西汉贵族墓葬的宏大规模。素纱襌衣重仅四十九克是世界上已知最轻的丝织品代表了西汉纺织技术的最高水平。博物馆中陈列着帛书、漆器、丝织品和食品等数千件出土文物，完整呈现了两千多年前西汉贵族的生活面貌。这里是了解西汉历史文化和欣赏中国考古重大发现的重要历史遗址。', '湖南', 28.185100, 113.032000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/75/Mawangduihanmu.jpg"]'),
('《湘妃竹记》', '岳阳市君山区君山岛斑竹园遗址', '柳宗元', '唐代', '君山岛斑竹园遗址位于湖南省岳阳市君山区境内，是唐代文学家柳宗元创作《湘妃竹记》的历史遗迹。柳宗元在此重点记载了湘妃竹的产地和生长特征为后世了解这一珍稀竹种提供了宝贵的文献资料。遗址保留着唐代古碑和大片斑竹林，斑竹竿上天然分布着紫褐色泪痕状斑点传说是舜帝二妃娥皇女英的眼泪所化。竹林中竹影婆娑清风徐来沙沙作响如泣如诉充满了诗意和传奇色彩。柳宗元以科学的态度记录了斑竹的形态特征同时也传承了湘妃泪竹的浪漫传说。君山岛四面环水洞庭湖碧波万顷空气清新。斑竹园是君山岛最具特色的景点之一。这里是了解湘妃竹文化传说和欣赏斑竹林独特风貌以及品味君山岛风光的重要文化遗址。', '湖南', 29.461100, 113.004300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/1b/Frontal_view_of_Yueyang_Tower%2C_Hunan%2C_China1.jpg"]'),
('《湘西苗族调查报告》', '湘西州吉首市德夯苗寨', '凌纯声', '现代', '德夯苗寨位于湖南省湘西州吉首市境内，是现代民族学家凌纯声创作《湘西苗族调查报告》的实地考察地。凌纯声在此进行了深入的田野调查记录了苗族的社会结构、宗教信仰和生活习俗为中国民族学研究奠定了重要基础。苗寨保留着原始的苗族建筑、传统服饰和民间习俗，木结构吊脚楼依山而建层层叠叠与青山绿水融为一体。苗族妇女身着银饰华丽的民族服装在节庆时载歌载舞热闹非凡。德夯大峡谷峡深谷幽流泉飞瀑四季如春。苗寨中至今保留着赶秋、椎牛和苗歌等非物质文化遗产。这里是了解苗族传统文化和探访湘西原始苗寨以及欣赏德夯峡谷自然风光的重要民族文化遗址。', '湖南', 28.262400, 109.698000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/88/NLC403-312001074386-107645_%E8%BE%B0%E5%B7%9E%E5%BA%9C%E5%BF%97_%E6%B8%85%E4%B9%BE%E9%9A%8630%E5%B9%B4%281765%29_%E5%8D%B7%E5%9B%9B%E5%8D%81%E4%B8%89.pdf"]'),
('《长沙城》', '长沙市天心区天心阁古城墙遗址', '黄仁宇', '现代', '天心阁古城墙遗址位于湖南省长沙市天心区境内，是现代历史学家黄仁宇在《长沙城》中详细记录的长沙仅存的明代古城墙。天心阁是长沙古城的标志性建筑始建于明代嘉靖年间位于古城墙最高处。遗址保留着明代城墙、天心阁楼阁和古炮等历史遗迹，城墙以巨型条石和青砖砌筑坚固厚实绵延数百米。天心阁为三层重檐歇山顶建筑飞檐翘角气势宏伟，登阁可俯瞰长沙城全景湘江蜿蜒橘子洲如一叶扁舟。古炮是清代铸造见证了长沙保卫战的烽火岁月。长沙在抗日战争中经历了文夕大火古城几乎毁于一旦，天心阁古城墙是劫后余存的珍贵历史遗迹。这里是了解长沙城市历史和感受古城沧桑变迁的重要历史遗址。', '湖南', 28.112700, 112.989600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/b/b0/Changsha_Tianxin_Pavilion.jpg"]'),
('《太阳照在桑干河上》', '常德市临澧县佘市桥镇蒋家村', '丁玲', '现代', '佘市桥镇蒋家村位于湖南省常德市临澧县境内，是现代作家丁玲的故乡也是其创作《太阳照在桑干河上》的重要背景地。丁玲是中国现代文学史上最杰出的女作家之一该小说描绘了华北农村土地改革的波澜壮阔画卷获得了斯大林文学奖。蒋家村保留着丁玲故居和明清古民居等历史遗迹，丁玲故居是一座典型的湘北民居青砖黛瓦古朴典雅屋内陈列着丁玲的生平事迹和创作手稿。村中明清古民居错落有致保留着传统的建筑风格和生活方式。蒋家村地处澧水流域平原开阔稻田连绵。这里是了解丁玲文学成就和感受湘北乡村田园风光的重要文化遗址。', '湖南', 29.441400, 111.647100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/71/The_peach_garden_1.jpg"]'),
('《暴风骤雨》', '邵阳市邵东县廉桥镇', '周立波', '现代', '廉桥镇位于湖南省邵阳市邵东县境内，是现代作家周立波创作《暴风骤雨》的重要取材地之一。小说描绘了东北农村土地改革的暴风骤雨般的历史进程，深刻反映了中国农村社会的深刻变革。廉桥镇保留着明清古民居和老祠堂等历史建筑，古民居青砖黛瓦马头墙高耸展现了典型的湘南民居风格。老祠堂建筑宏伟木雕石雕精美记载着家族的荣耀与传承。廉桥镇自古以来就是邵阳地区重要的商贸重镇中药材市场闻名全国。镇中街巷纵横老店铺林立保留着浓郁的商贸气息。周立波虽生于益阳但其创作视野遍及全国。这里是了解周立波文学创作和感受湘南古镇商贸文化的重要历史遗址。', '湖南', 27.258400, 111.744400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/f/f5/Mount_Langshan_in_Hunan%2C_Picture49.jpg"]'),
('《致橡树》', '长沙市岳麓区橘子洲头青年毛泽东雕像旁', '舒婷', '现代', '橘子洲头青年毛泽东雕像旁位于湖南省长沙市岳麓区境内，是当代诗人舒婷创作《致橡树》的背景地之一。舒婷以橡树为象征表达了独立平等的爱情观我如果爱你绝不像攀援的凌霄花的宣言震撼了一代人的心灵。橘子洲头矗立着巨大的青年毛泽东雕像雕像高达三十二米展现了青年毛泽东意气风发的英姿。雕像旁保留着古碑和纪念设施。橘子洲是湘江中最大的沙洲全长约五公里两岸青山对峙江水奔腾。毛泽东青年时代在此写下了问苍茫大地谁主沉浮的豪迈诗句。从洲头远眺湘江北去岳麓山苍翠如黛城市天际线壮阔。这里是感受舒婷致橡树中独立精神和欣赏橘子洲头湘江风光的重要文化景点。', '湖南', 28.234800, 112.931300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/17/West_Lake%2C_Hangzhou_2025.jpg"]'),
('《独坐敬亭山》', '宣城市宣州区敬亭山太白独坐楼遗址', '李白', '唐代', '敬亭山太白独坐楼遗址位于安徽省宣城市宣州区境内，是唐代诗仙李白创作《独坐敬亭山》的历史遗迹。李白在此写下了相看两不厌只有敬亭山的千古名句，以人与山的对望表达了知己难寻的深沉孤独。遗址保留着唐代亭基、古碑和千年古松，亭基虽已残破但仍可见当年建筑的规模。古松苍劲挺拔枝叶如盖相传已有千年树龄见证了李白在此独坐的诗意时光。敬亭山海拔不高但山势秀丽林木葱郁历代文人墨客争相登临留下了大量诗篇。从山顶远眺宣城平原沃野千里水敬亭绕城郭。李白一生七次登临敬亭山对此山情有独钟。这里是感受李白独坐诗意和领略敬亭山千年文脉的重要历史遗址。', '安徽', 31.138600, 118.755100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/82/Tianzhu_Peak_%2820170116142019%29.jpg"]'),
('《赠汪伦》', '宣城市泾县桃花潭踏歌古岸', '李白', '唐代', '桃花潭踏歌古岸位于安徽省宣城市泾县境内，是唐代诗仙李白创作《赠汪伦》的历史遗迹。李白在此写下了桃花潭水深千尺不及汪伦送我情的千古名句，成为中国友情诗的巅峰之作。踏歌古岸是汪伦踏歌送别李白的真实地点，古岸以青石铺砌延伸入潭水中经过千年的风雨冲刷依然保持着原貌。桃花潭水深碧绿如翡翠两岸青山倒映水中如同一幅天然的水墨画卷。潭旁保留着唐代码头遗迹和历代碑刻。汪伦是泾县名士热情好客以万家酒店和十里桃花为由邀请李白前来。古岸周围古木参天鸟鸣幽幽环境清幽宜人。这里是感受李白汪伦千古友情和欣赏桃花潭碧水青山的绝佳去处。', '安徽', 30.688300, 118.419700, '其他', '["https://img0.baidu.com/it/u=809479790,3965694701&fm=253&fmt=auto&app=120&f=JPEG?w=800&h=1103"]'),
('《秋浦歌十七首・其十五》', '池州市贵池区秋浦河古栈道遗址', '李白', '唐代', '秋浦河古栈道遗址位于安徽省池州市贵池区境内，是唐代诗仙李白创作《秋浦歌十七首》的历史遗迹。李白在此写下了白发三千丈缘愁似个长的夸张名句，以白发三千丈的奇特意象表达了深重的忧愁。遗址保留着唐代栈孔和摩崖石刻，栈孔凿刻于河岸崖壁之上是当年古栈道的遗迹。摩崖石刻内容丰富涵盖李白诗作和后世文人的题记。秋浦河水质清澈碧绿如玉两岸青山对峙林木葱郁。河中怪石嶙峋水流或急或缓形成了一系列迷人的自然景观。李白在池州期间创作了十七首秋浦歌记录了秋浦河畔的山水风情和人生感悟。这里是感受李白秋浦歌诗意和欣赏秋浦河自然风光的重要历史遗址。', '安徽', 30.657000, 117.491300, '其他', '["https://img1.baidu.com/it/u=2108397813,2650537843&fm=253&fmt=auto&app=138&f=JPEG?w=750&h=500"]'),
('《清明》', '池州市贵池区杏花村古井遗址', '杜牧', '唐代', '杏花村古井遗址位于安徽省池州市贵池区境内，是唐代诗人杜牧创作《清明》的原型地。杜牧在此写下了借问酒家何处有牧童遥指杏花村的千古名句。遗址保留着唐代井栏、古碑和酒坊遗址，古井井栏以青石雕刻花纹精美井水清澈甘甜自古以来就是酿酒的上好水源。酒坊遗址保留着唐代的酿酒作坊格局可以想见当年杏花村酒肆林立的繁华景象。古碑上刻有杜牧清明诗全文字迹清晰。杏花村地处丘陵地带春日杏花盛开满村飘香，细雨纷纷中游人寻酒的意境与诗中描绘高度吻合。这里至今仍延续着传统酿酒技艺所产杏花村酒香醇甘美。这里是感受杜牧清明诗意和品味传统酿酒文化的重要历史遗址。', '安徽', 30.657000, 117.491300, '其他', '["https://img0.baidu.com/it/u=2253309501,2380663988&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《滁州西涧》', '滁州市琅琊区西涧湖古渡口遗址', '韦应物', '唐代', '西涧湖古渡口遗址位于安徽省滁州市琅琊区境内，是唐代诗人韦应物创作《滁州西涧》的历史遗迹。韦应物在此写下了春潮带雨晚来急野渡无人舟自横的千古名句，以野渡孤舟的意象营造了一幅清幽恬淡的春日山水画卷。遗址保留着唐代码头、古碑和古桥，古码头青石台阶延伸入水历经千年依然保存完好。古桥横跨涧上石砌古朴与两岸青山绿树浑然一体。西涧水流清澈春日时涧边野草青翠黄鹂鸣叫于深树之中正合诗中独怜幽草涧边生上有黄鹂深树鸣的意境。韦应物任滁州刺史时常在此流连写下了多首描绘西涧风光的诗篇。这里是感受韦应物滁州西涧诗意和欣赏滁州山水之美的重要历史遗址。', '安徽', 32.294800, 118.305500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/48/Bagong_Mountain_Park_-_Gate.jpg"]'),
('《题乌江亭》', '马鞍山市和县乌江镇霸王祠遗址', '杜牧', '唐代', '乌江镇霸王祠遗址位于安徽省马鞍山市和县境内，是唐代诗人杜牧创作《题乌江亭》的历史遗迹。杜牧在此写下了江东子弟多才俊卷土重来未可知的千古名句为项羽鸣不平。遗址保留着唐代碑刻和霸王墓，霸王祠建于项羽自刎之地祠堂建筑古朴庄严供奉着项羽塑像。霸王墓冢高大封土完整周围古柏环绕肃穆庄严。碑刻记载了项羽垓下之战的经过和乌江自刎的悲壮。乌江渡口是当年项羽拒绝过江的地点江水滔滔东流令人感慨。项羽生当作人杰死亦为鬼雄的英雄气概激励了无数后人。这里是了解楚汉争霸历史和缅怀西楚霸王项羽以及感受杜牧咏史诗意的重要历史遗址。', '安徽', 31.741700, 118.353300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/a/a3/Huayu_Square_cross.jpg"]'),
('《望九华赠青阳韦仲堪》', '池州市青阳县九华山化城寺遗址', '李白', '唐代', '九华山化城寺遗址位于安徽省池州市青阳县境内，是唐代诗仙李白创作《望九华赠青阳韦仲堪》的历史遗迹。李白在此写下了遥望九华峰的名句被九华山的壮美景色深深打动。遗址保留着唐代建筑基址、古碑和佛经，化城寺是九华山的开山祖寺始建于唐代是佛教地藏菩萨道场的核心寺院。寺中保存着大量珍贵佛经和明清佛像。九华山以佛教文化著称山中寺院林立香火鼎盛。从化城寺远眺九华群峰连绵起伏如同莲花盛开蔚为壮观。九华山四季景色各异春日杜鹃映红山谷秋日枫叶层林尽染冬日雪后银装素裹。这里是了解九华山佛教文化和感受李白九华诗意以及欣赏九华山自然风光的重要文化遗址。', '安徽', 30.639200, 117.847400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/95/Jiuhuashan_Tiantai.jpg"]'),
('《秋登宣城谢朓北楼》', '宣城市宣州区谢朓楼遗址', '李白', '唐代', '谢朓楼遗址位于安徽省宣城市宣州区境内，是唐代诗仙李白创作《秋登宣城谢朓北楼》的历史遗迹。李白在此写下了江城如画里山晚望晴空的优美诗句，以如画一词赞美宣城的山水之美。遗址保留着唐代亭基、古碑和谢朓纪念馆，谢朓楼因南朝诗人谢朓而得名。谢朓是李白最崇敬的诗人之一李白多次登临此楼追慕前贤。从楼上远眺宣城山水如画敬亭山苍翠如黛宛溪水清澈如镜。谢朓纪念馆展示了谢朓和李白的生平及诗作。秋日登楼天高气爽视野开阔更添几分诗情画意。宣城自古以来就是文人墨客聚集之地文化底蕴深厚。这里是感受李白和谢朓两位诗人的精神交汇以及欣赏宣城山水之美的重要文化遗址。', '安徽', 31.138600, 118.755100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/18/Xuancheng_City_Skyline.JPG"]'),
('《夜泊牛渚怀古》', '马鞍山市雨山区牛渚矶遗址', '李白', '唐代', '牛渚矶遗址位于安徽省马鞍山市雨山区境内，是唐代诗仙李白创作《夜泊牛渚怀古》的历史遗迹。李白在此写下了牛渚西江夜青天无片云的名句以夜泊牛渚的孤寂怀念知音袁宏。遗址保留着唐代码头、古碑和摩崖石刻，牛渚矶突出于长江之中为长江三矶之一地势险要。摩崖石刻内容丰富涵盖历代文人的题记和诗作。从矶上远眺长江水奔腾东流浩浩荡荡，夜晚月光洒满江面银波粼粼与诗中的意境高度吻合。东晋名士袁宏曾在此夜咏诗被谢尚赏识成就了一段知音佳话。牛渚矶是长江沿线最具文学色彩的名胜之一。这里是感受李白怀古诗意和欣赏长江牛渚矶壮美风光的重要历史遗址。', '安徽', 31.685100, 118.498600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/a/a3/Huayu_Square_cross.jpg"]'),
('《游褒禅山》', '马鞍山市含山县褒禅山华阳洞遗址', '王安石', '北宋', '褒禅山华阳洞遗址位于安徽省马鞍山市含山县境内，是北宋政治家文学家王安石创作《游褒禅山》的历史遗迹。王安石在此写下了世之奇伟瑰怪非常之观常在于险远的哲理名言揭示了探索精神的重要。遗址保留着宋代摩崖石刻和古栈道，华阳洞是一座天然溶洞洞内钟乳石千姿百态经过千万年地质作用形成了奇特的地下景观。王安石与友人游览华阳洞时因前洞平坦而后洞深邃黑暗而半途而返，由此引发了深刻的人生哲理感悟。古栈道沿山势蜿蜒可以体验当年王安石登山探洞的路线。褒禅山林木葱郁山势秀丽。这里是感受王安石游褒禅山哲理和探索华阳洞溶洞奇观的重要历史遗址。', '安徽', 31.735500, 118.101600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/7b/%E5%AE%89%E5%BE%BD%E7%9C%81%E5%B7%A2%E6%B9%96%E5%B8%82%E5%90%AB%E5%B1%B1%E5%8E%BF-%E5%8E%BF%E6%94%BF%E5%BA%9C%E5%8A%9E%E5%85%AC%E6%A5%BC_-_panoramio.jpg"]'),
('《题齐安城楼》', '黄山市歙县齐云山月华街遗址', '杜牧', '唐代', '齐云山月华街遗址位于安徽省黄山市歙县境内，是唐代诗人杜牧创作《题齐安城楼》的历史遗迹。遗址保留着唐代古寺、道观和古民居等建筑，道教文化浓郁。齐云山是中国道教四大名山之一与武当山、龙虎山和青城山齐名。月华街位于齐云山半山腰是道教活动的核心区域，街道依悬崖而建两旁道观和民居错落有致形成了独特的山中古街景观。道观中供奉着众多道教神像香火缭绕。古民居白墙黛瓦典型的徽派建筑风格与道教建筑相映成趣。从月华街远眺群山起伏云海翻腾恍如仙境。齐云山自然风光秀美丹霞地貌发育完整红色山崖与翠绿林木交相辉映。这里是了解道教文化和欣赏齐云山自然风光的重要文化遗址。', '安徽', 29.861100, 118.415400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/2/28/Anhui_Huangshan.jpg"]'),
('《过巢湖》', '合肥市巢湖市中庙寺遗址', '罗隐', '唐代', '中庙寺遗址位于安徽省合肥市巢湖市境内，是唐代诗人罗隐创作《过巢湖》的历史遗迹。遗址保留着唐代建筑基址、古碑和佛像，中庙寺位于巢湖北岸凤凰矶上三面临水一面靠山地势极为险要。寺院建筑古朴庄严依山就势层层叠叠与巢湖水天相映。从寺中远眺巢湖水面开阔浩渺无际是中国五大淡水湖之一，湖上渔帆点点白鸥翔集天水相连蔚为壮观。佛像造型庄严法相端正展现了唐代佛教造像的艺术水平。中庙寺自古以来就是巢湖边最重要的宗教场所香火旺盛。寺旁古碑记载了巢湖的历史传说和地理变迁。这里是了解巢湖历史文化和俯瞰巢湖壮美全景的重要历史遗址。', '安徽', 31.600400, 117.874000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/3f/Chao_Lake_NASA.jpg"]'),
('《采石矶》', '马鞍山市雨山区采石矶太白楼遗址', '白居易', '唐代', '采石矶太白楼遗址位于安徽省马鞍山市雨山区境内，是唐代诗人白居易创作《采石矶》的历史遗迹。白居易在此写下了采石江边李白坟的名句纪念了诗仙李白。遗址保留着唐代碑刻和李白雕像，太白楼是后人为纪念李白而建的楼阁建筑宏伟飞檐翘角气势不凡。李白雕像矗立于楼前衣袂飘飘举杯邀月展现了诗仙的潇洒气概。传说李白醉酒后在采石矶捉月溺水而亡给这里增添了浪漫而悲壮的色彩。采石矶是长江三矶之首矶石突入江中气势雄伟。从太白楼远眺长江水滔滔东流两岸青山如黛。采石矶自古是长江要塞历代兵家必争之地。这里是缅怀诗仙李白和欣赏长江采石矶壮美风光的重要历史遗址。', '安徽', 31.685100, 118.498600, '其他', '["https://img2.baidu.com/it/u=3125576289,625790351&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《题敬亭山》', '宣城市宣州区敬亭山广教寺遗址', '杜牧', '唐代', '敬亭山广教寺遗址位于安徽省宣城市宣州区境内，是唐代诗人杜牧创作《题敬亭山》的历史遗迹。遗址保留着唐代建筑基址、古碑和双塔，周边竹林繁茂环境清幽。广教寺始建于唐代是敬亭山上最重要的佛教寺院。双塔为宋代所建南北对峙塔身精美是宣城古城的标志性建筑。敬亭山自南齐谢朓开始就成为文人雅集的圣地，历代诗人留下了数百首吟咏敬亭山的诗篇。杜牧登临敬亭山时被山上的幽静和秀美所打动留下了这首题咏。山中竹林连绵起伏清风拂过竹叶沙沙作响极具禅意。从山顶远眺宣城平原沃野千里景色壮阔。这里是感受杜牧诗意和了解敬亭山千年文脉的重要文化遗址。', '安徽', 31.138600, 118.755100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/7b/CADAL09012549_%E6%97%85%E8%A1%8C%E9%9B%9C%E5%BF%97.djvu"]'),
('《游九华山》', '池州市青阳县九华山天台峰遗址', '王安石', '北宋', '九华山天台峰遗址位于安徽省池州市青阳县境内，是北宋政治家文学家王安石创作《游九华山》的历史遗迹。王安石在此写下了雄奇此山兼的赞语高度评价了九华山的壮美。遗址保留着宋代摩崖石刻、古寺和观景台，天台峰是九华山的最高峰海拔一千三百余米为九华绝顶。从观景台远眺九华群峰如同莲花瓣层层展开蔚为壮观。天台寺位于峰顶始建于唐代是九华山海拔最高的寺院香火不绝。摩崖石刻遍布峰顶岩壁内容涵盖历代文人的题记和佛教经文。登天台峰需攀登千级石阶沿途风光变幻莫测。九华山是佛教地藏菩萨道场佛教文化底蕴深厚。这里是登临九华绝顶和感受王安石游山诗意以及俯瞰九华群峰的绝佳去处。', '安徽', 30.639200, 117.847400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/95/Jiuhuashan_Tiantai.jpg"]'),
('《新安江》', '黄山市屯溪区屯溪老街北段遗址', '沈约', '南北朝梁', '屯溪老街北段遗址位于安徽省黄山市屯溪区境内，是南北朝梁代诗人沈约创作《新安江》的历史背景地。沈约以新安江为题描绘了皖南山水的清秀之美。遗址保留着明清古民居、老商铺和古码头，北段老街相比南段商业化程度远低保留了更多原始的历史风貌。古民居白墙黛瓦马头墙高耸是典型的徽派建筑风格。老商铺中仍有经营传统笔墨纸砚和徽州特产的百年老店。古码头曾是新安江上重要的商贸渡口见证了徽商的辉煌历史。新安江水清澈碧绿在此穿城而过两岸青山如画。屯溪老街被誉为中国保存最完整的宋代商业街市活化石。这里是了解徽派建筑文化和感受新安江山水之美的重要历史遗址。', '安徽', 29.696000, 118.310700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/b/be/201705_Shuangdunji_Railway_Station.jpg"]'),
('《题桃花潭》', '宣城市泾县桃花潭怀仙阁遗址', '汪伦', '唐代', '桃花潭怀仙阁遗址位于安徽省宣城市泾县境内，是唐代汪伦送别李白后修建的纪念建筑。汪伦是泾县名士与李白建立了深厚的友谊，李白离去后汪伦在桃花潭边修建了怀仙阁以表达对诗仙的思念之情。遗址保留着唐代碑刻和李白雕像，怀仙阁建筑古朴典雅依潭而建与桃花潭水相映成趣。李白雕像矗立于阁前衣袂飘飘目光远眺仿佛仍在欣赏桃花潭的美景。碑刻记载了李白与汪伦交往的详细经过。桃花潭水深碧绿如翡翠两岸青山倒映水中美不胜收。潭旁古木参天鸟鸣啾啾环境极为清幽。这里是了解李白与汪伦千古友情和欣赏桃花潭碧水青山的重要文化遗址。', '安徽', 30.688300, 118.419700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/d3/Jingxian_Zhaji_2017.08.19_17-24-24.jpg"]'),
('《游琅琊山》', '滁州市琅琊区琅琊山琅琊寺遗址', '韦应物', '唐代', '琅琊山琅琊寺遗址位于安徽省滁州市琅琊区境内，是唐代诗人韦应物创作《游琅琊山》的历史遗迹。韦应物在此写下了独怜幽草涧边生上有黄鹂深树鸣的名句描绘了琅琊山的幽静之美。遗址保留着唐代建筑基址、古碑和泉水，琅琊寺始建于唐代是琅琊山上最古老的佛教寺院。寺院建筑依山而建层层叠叠与山林融为一体。泉水从山石间涌出清澈甘甜终年不断。琅琊山是滁州名山因欧阳修的醉翁亭记而闻名天下。山中林木繁茂鸟鸣花香四季景色宜人。从寺院远眺滁州城郭平原开阔。这里是感受韦应物诗意和了解琅琊山佛教文化以及欣赏滁州山水的重要历史遗址。', '安徽', 32.294800, 118.305500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/3f/State_Council_Gazette_-_2019_-_Issue_30.pdf"]'),
('《巢湖春望》', '合肥市巢湖市龟山遗址', '张籍', '唐代', '龟山遗址位于安徽省合肥市巢湖市境内，是唐代诗人张籍创作《巢湖春望》的历史遗迹。遗址保留着唐代古寺遗址、古碑和观景台，龟山突出于巢湖北岸山形如龟因此得名。从观景台远眺巢湖水面辽阔浩渺无际是观赏巢湖全景的最佳位置。春日时湖边柳树吐绿桃花盛开湖上白鸥翔集与张籍巢湖春望的诗意高度吻合。唐代古寺遗址虽已残破但基址犹存可以想见当年寺院的规模。古碑记载了巢湖的历史传说和龟山的地理特征。龟山海拔不高但山势突出三面临水风光秀美。巢湖周围是广阔的平原稻田连绵村落星布。这里是欣赏巢湖春日风光和了解巢湖历史文化的重要历史遗址。', '安徽', 31.600400, 117.874000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/df/%E5%B7%A2%E6%B9%96%E7%81%AB%E8%BD%A6%E7%AB%99%E5%B9%BF%E5%9C%BA%E9%9B%95%E5%A1%91.jpg"]'),
('《齐云山》', '黄山市休宁县齐云山真仙洞府遗址', '唐寅', '明代', '齐云山真仙洞府遗址位于安徽省黄山市休宁县境内，是明代才子唐寅创作《齐云山》的历史遗迹。唐寅在此写下了齐云山与碧云齐的赞语高度评价了齐云山的秀美。遗址保留着明代摩崖石刻、道观和泉水，真仙洞府是齐云山道教活动的核心场所洞穴群沿悬崖峭壁分布。摩崖石刻遍布崖壁内容涵盖道教经文和历代文人题记，是中国道教摩崖石刻最为集中的地方之一。道观建于洞穴之中依山就势与自然融为一体。泉水从岩石缝隙中涌出清澈甘甜。齐云山丹霞地貌发育完整红色山崖与翠绿林木交相辉映。从真仙洞府远眺群山起伏云海翻腾。这里是了解齐云山道教文化和欣赏丹霞地貌自然风光的重要文化遗址。', '安徽', 29.785600, 118.181300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/2/28/Anhui_Huangshan.jpg"]'),
('《姥山岛》', '合肥市巢湖市姥山岛文峰塔遗址', '李鸿章', '清代', '姥山岛文峰塔遗址位于安徽省合肥市巢湖市境内，是清代重臣李鸿章与巢湖结缘的历史遗迹。遗址保留着清代碑刻和佛像，文峰塔是姥山岛上最显著的标志性建筑始建于明代后经李鸿章出资修缮。文峰塔为七层八角楼阁式砖塔高约五十余米塔身挺拔秀丽可以登临远眺。从塔顶俯瞰巢湖水面辽阔浩渺无际八百里巢湖尽收眼底蔚为壮观。姥山岛是巢湖中最大的岛屿四面环水林木葱郁鸟语花香。岛上保留着古寺和石刻等历史遗迹。佛像造型庄严法相端正展现了清代佛教造像的艺术水平。碑刻记载了文峰塔的修建历史和李鸿章的事迹。这里是俯瞰巢湖壮美全景和了解姥山岛历史文化的重要历史遗址。', '安徽', 31.600400, 117.874000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/3f/Chao_Lake_NASA.jpg"]'),
('《宣州谢朓楼饯别校书叔云》', '宣城市宣州区谢朓楼饯别亭遗址', '李白', '唐代', '谢朓楼饯别亭遗址位于安徽省宣城市宣州区境内，是唐代诗仙李白创作《宣州谢朓楼饯别校书叔云》的历史遗迹。李白在此写下了抽刀断水水更流举杯消愁愁更愁的千古名句，以形象的比喻表达了壮志难酬的深重愁绪。遗址保留着唐代碑刻和千年古柏，碑刻上刻有李白诗作全文字迹清晰。古柏苍劲挺拔枝叶如盖相传已有千年树龄。李白在谢朓楼上设宴为族叔李云饯行酒酣耳热之际诗兴大发写下了这首气势磅礴的名篇。从楼上远眺宣城山水如画敬亭山苍翠如黛。这首诗融合了激愤和豪放表达了诗仙复杂的内心世界。这里是感受李白抽刀断水诗意和领略宣城谢朓楼历史文脉的重要文化遗址。', '安徽', 31.138600, 118.755100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/16/Xie_Tiao_Tower_01_2021-03.jpg"]'),
('《游齐云岩》', '黄山市休宁县齐云山方腊寨遗址', '朱熹', '南宋', '齐云山方腊寨遗址位于安徽省黄山市休宁县境内，是南宋理学大师朱熹创作《游齐云岩》的历史遗迹。遗址保留着宋代寨墙、古炮台和摩崖石刻，方腊寨是北宋末年农民起义领袖方腊屯兵之地。寨墙以巨石垒筑坚固异常沿山势蜿蜒于悬崖峭壁之间居高临下易守难攻。古炮台是方腊起义军的防御工事可以想见当年战事的激烈。摩崖石刻记载了方腊起义的历史和后世文人的题记。朱熹登临齐云山时被山势的险峻和历史的沧桑所打动留下了游齐云岩的记述。从方腊寨远眺群山连绵云海翻腾皖南山水尽收眼底。这里是了解方腊起义历史和感受朱熹游山诗意以及欣赏齐云山险峻风光的重要历史遗址。', '安徽', 29.785600, 118.181300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/2/28/Anhui_Huangshan.jpg"]'),
('《新安江山水画廊》', '黄山市歙县深渡镇凤凰岛遗址', '孟浩然', '唐代', '深渡镇凤凰岛遗址位于安徽省黄山市歙县境内，是唐代诗人孟浩然创作《新安江山水画廊》的背景地。孟浩然写下了江入新安清的优美诗句赞美了新安江水的清澈。遗址保留着唐代古寺遗址、古碑和茶园，凤凰岛是新安江中一座形似凤凰的小岛岛上绿树成荫花草繁茂。新安江山水画廊是一段长达数十公里的江段两岸青山对峙村落点缀其间如同一幅徐徐展开的水墨画卷。茶园连绵起伏春日茶芽嫩绿采茶时节茶香弥漫。古碑记载了新安江的历史沿革和沿岸村落的故事。新安江水清澈碧绿是黄山市最重要的水系。这里是欣赏新安江山水画廊壮美风光和品味徽州茶文化的重要自然文化遗址。', '安徽', 29.861100, 118.415400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/2/28/Anhui_Huangshan.jpg"]'),
('《送温处士归黄山白鹅峰旧居》', '黄山市黄山区黄山白鹅岭遗址', '李白', '唐代', '黄山白鹅岭遗址位于安徽省黄山市黄山区境内，是唐代诗仙李白创作《送温处士归黄山白鹅峰旧居》的历史遗迹。李白在此写下了黄山四千仞三十二莲峰的壮丽诗句，首次将黄山的雄伟气势写入诗歌。遗址保留着唐代古驿道、摩崖石刻和古松，古驿道以青石铺砌蜿蜒于黄山峰林之间是古代登山的主要路线。摩崖石刻内容丰富涵盖历代文人的游记和题咏。白鹅岭是黄山前后山的分界线地势开阔视野壮观。从此处远眺黄山群峰连绵如同三十二朵莲花盛开于天际蔚为壮观。古松苍劲挺拔姿态各异展现了黄山松的独特魅力。这里是感受李白黄山诗意和欣赏黄山峰林云海壮观景象的重要历史遗址。', '安徽', 30.272900, 118.141600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/0/03/CADAL09014144_%E4%B8%AD%E5%9C%8B%E8%BE%B2%E6%B0%91%E7%B6%93%E6%BF%9F%E7%A0%94%E7%A9%B6%E6%9C%83%E6%A6%82%E8%A6%BD.djvu"]'),
('《望天门山》', '芜湖市鸠江区天门山楚江古渡', '李白', '唐代', '天门山楚江古渡位于安徽省芜湖市鸠江区境内，是唐代诗仙李白创作《望天门山》的又一观景点。李白在此写下了天门中断楚江开碧水东流至此回的壮丽诗句。古渡保留着唐代码头、古碑和摩崖石刻，天门山由东西两山对峙于长江两岸形成一道天然门户气势雄伟。长江在此受天门山夹峙水流湍急碧波翻涌形成了壮观的江流景象。从古渡远眺两山对峙如同一扇巨门被大江劈开蔚为壮观。碧水在此回旋折转正合诗中碧水东流至此回的描绘。古码头青石台阶延伸入江历经千年依然保存完好。这里是感受李白望天门山诗中壮阔气势和近距离欣赏天门山长江奇观的重要历史遗址。', '安徽', 31.369000, 118.392000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/52/%E4%B8%89%E5%85%83%E6%B4%9E_-_panoramio_-_%E9%99%88%E5%AE%8F%E5%AE%87_%281%29.jpg"]'),
('《醉翁亭》', '滁州市琅琊山醉翁亭古梅亭遗址', '欧阳修', '北宋', '琅琊山醉翁亭古梅亭遗址位于安徽省滁州市琅琊区境内，是北宋文学家欧阳修常游之地。欧阳修被贬滁州时写下了醉翁之意不在酒在乎山水之间也的千古名句。遗址保留着宋代古梅、古碑和泉水，古梅亭因亭旁一株宋代古梅而得名古梅虽历经千年仍能在寒冬绽放暗香浮动。醉翁亭是中国四大名亭之一建筑古朴典雅与山林浑然一体。泉水从山石间涌出清澈甘甜被称为让泉欧阳修常以此泉水酿酒。琅琊山林木葱郁鸟鸣花香山中小径曲折幽深。欧阳修在滁州期间与民同乐寄情山水写下了不朽的醉翁亭记。这里是感受欧阳修醉翁精神和欣赏琅琊山四季山水之美的重要文化遗址。', '安徽', 32.294800, 118.305500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/df/Langyashan.jpg"]'),
('《题西林壁》', '黄山市黄山区黄山始信峰遗址', '苏轼', '北宋', '黄山始信峰遗址位于安徽省黄山市黄山区境内，是北宋文豪苏轼创作《题西林壁》的灵感来源地之一。苏轼写下了不识庐山真面目只缘身在此山中的哲理名句。遗址保留着宋代摩崖石刻和古松，始信峰因明代旅行家徐霞客始信黄山天下奇而得名。峰顶怪石嶙峋古松盘曲姿态万千，黑虎松、连理松、探海松等名松各具风姿令人叹为观止。从始信峰远眺黄山群峰云海翻腾松涛阵阵如入仙境。摩崖石刻遍布峰顶岩壁记载了历代文人的游览感悟。始信峰是黄山观赏奇松怪石的最佳位置之一。黄山以奇松怪石云海温泉四绝著称于世。这里是欣赏黄山奇松怪石和感受苏轼哲理诗意的绝佳去处。', '安徽', 30.272900, 118.141600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/3f/State_Council_Gazette_-_2019_-_Issue_30.pdf"]'),
('《寄扬州韩绰判官》', '黄山市歙县徽州古城渔梁坝遗址', '杜牧', '唐代', '徽州古城渔梁坝遗址位于安徽省黄山市歙县境内，是唐代诗人杜牧创作《寄扬州韩绰判官》的历史背景地。渔梁坝是徽州古代水利工程的杰作被誉为江南都江堰。遗址保留着唐代石砌结构和古码头，渔梁坝全长约一百四十余米以巨型花岗岩砌筑横跨练江坝体坚固历经千年不毁。古码头曾是徽商出发远行的起点徽州的茶叶、丝绸和木材从这里装船沿新安江运往杭州和扬州。坝下水流湍急碧波翻涌形成壮观的人工瀑布。坝上游水面平静如镜两岸徽派古民居白墙黛瓦倒映水中。渔梁坝是中国古代水利工程的珍贵遗存。这里是了解徽州古代水利文明和感受徽商文化源头的重要历史遗址。', '安徽', 29.861100, 118.415400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/3f/State_Council_Gazette_-_2019_-_Issue_30.pdf"]'),
('《游黄山》', '黄山市黄山区黄山莲花峰遗址', '徐霞客', '明代', '黄山莲花峰遗址位于安徽省黄山市黄山区境内，是明代大旅行家徐霞客创作《游黄山》的历史遗迹。徐霞客在此写下了登黄山天下无山观止矣的千古赞语奠定了黄山在中国名山中的至高地位。遗址保留着明代摩崖石刻和古栈道，莲花峰是黄山最高峰海拔一千八百六十四米为华东地区第一高峰。从峰顶俯瞰黄山群峰林立云海翻腾万里河山尽收眼底气势磅礴。古栈道沿悬崖峭壁而建窄处仅容一人通过行走其上惊险刺激。摩崖石刻遍布峰顶岩壁记载了徐霞客和历代文人的登峰感悟。莲花峰因峰顶岩石形似莲花瓣而得名。这里是登临黄山绝顶和感受徐霞客登黄山天下无山壮志的绝佳去处。', '安徽', 30.272900, 118.141600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/1d/Huangshan_pic_4.jpg"]'),
('《儒林外史》', '滁州市全椒县吴敬梓故居遗址', '吴敬梓', '清代', '吴敬梓故居遗址坐落于安徽省滁州市全椒县，是清代伟大讽刺小说《儒林外史》的诞生之地。吴敬梓在此目睹科举制度下文人的百态人生，以辛辣笔触描绘了范进中举、周进撞号板等经典场景。故居保留了清代建筑风格的正厅、书房与藏书楼，院内古碑记载着吴敬梓的生平事迹。漫步其间，仿佛穿越回那个八股取士的年代，感受文人在功名利禄与独立人格之间的挣扎与抉择，是了解中国古代知识分子精神世界的重要文化遗存。', '安徽', 32.091200, 118.271700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/0/02/Xuguoshifang_5225.jpg"]'),
('《醉翁亭记》', '滁州市琅琊山醉翁亭遗址', '欧阳修', '北宋', '醉翁亭位于安徽省滁州市琅琊山中，因北宋文学家欧阳修所作《醉翁亭记》而名扬天下。"醉翁之意不在酒，在乎山水之间也"的千古名句即诞生于此。亭旁保留有宋代碑刻，刻有欧阳修手书原文，字迹苍劲有力。周围古梅苍翠，泉水叮咚，山色秀丽。春日梅花绽放，夏日绿荫蔽日，秋日层林尽染，冬日银装素裹，四季皆有独特韵味。此处游客较少，环境清幽，是感受北宋文人山水情怀的绝佳之地。', '安徽', 32.294800, 118.305500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/98/NLC416-12jh000473-82645_%E8%98%87%E6%9D%B1%E5%9D%A1%E9%9B%86.pdf"]'),
('《游褒禅山记》', '马鞍山市含山县褒禅山华阳洞遗址', '王安石', '北宋', '褒禅山华阳洞位于安徽省马鞍山市含山县，因王安石《游褒禅山记》而闻名。文中"尽吾志也而不能至者，可以无悔矣"的哲理深刻影响了后世。华阳洞内钟乳石千姿百态，洞壁保留有宋代至明代摩崖石刻数十处，记录了历代文人游览的感悟。洞外山势峻峭，古木参天，溪水潺潺。沿着王安石当年探洞的路径前行，既能欣赏喀斯特地貌的鬼斧神工，又能体悟"世之奇伟瑰怪非常之观常在险远"的深刻哲理。', '安徽', 31.735500, 118.101600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/7b/%E5%AE%89%E5%BE%BD%E7%9C%81%E5%B7%A2%E6%B9%96%E5%B8%82%E5%90%AB%E5%B1%B1%E5%8E%BF-%E5%8E%BF%E6%94%BF%E5%BA%9C%E5%8A%9E%E5%85%AC%E6%A5%BC_-_panoramio.jpg"]'),
('《徐霞客游记・游黄山记》', '黄山市黄山区黄山西海大峡谷遗址', '徐霞客', '明代', '黄山西海大峡谷位于安徽省黄山市黄山区，是徐霞客笔下"黄山之奇，奇在西海"的核心所在。大峡谷深邃幽静，云海翻涌时如入仙境，奇松怪石遍布两侧崖壁。明代古驿道蜿蜒其间，石阶陡峭，沿途可见历代文人留下的摩崖石刻。清晨日出时分，金色阳光穿透云层照射在花岗岩峰林上，景象极为壮观。此处远离黄山主景区的喧闹，保留了原始的自然风貌，是真正体验黄山幽深之美的秘境。', '安徽', 30.272900, 118.141600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/1d/Huangshan_pic_4.jpg"]'),
('《孔雀东南飞》', '安庆市怀宁县小市镇孔雀台遗址', '无名氏', '汉代', '孔雀台遗址位于安徽省安庆市怀宁县小市镇，是中国古代最长叙事诗《孔雀东南飞》故事的发生地。诗中刘兰芝与焦仲卿的爱情悲剧千古流传，感动了无数后人。遗址保留有汉代建筑基址、古碑与传说中的孔雀坟，周围田园风光秀美，潜水河蜿蜒流过。当地至今保留着与这段爱情故事相关的民俗传统，每年举办纪念活动。漫步于此，仿佛能听到"孔雀东南飞，五里一徘徊"的哀婉吟唱，是感受汉代民间文学魅力的珍贵遗存。', '安徽', 30.733600, 116.829600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/8a/ChinaAnqingHuaining.png"]'),
('《新安家族》', '黄山市歙县徽商大宅院遗址', '季宇', '现代', '徽商大宅院位于安徽省黄山市歙县，是季宇小说《新安家族》中描绘的徽商三百年兴衰史的重要背景地。院内汇集了明清时期精美的木雕、砖雕与石雕，雕工细腻，题材丰富，展现了徽州工匠的卓越技艺。高墙深院、天井回廊、马头墙错落有致，体现了典型的徽派建筑美学。院内古井、石板路、花窗格栅保存完好，每一处细节都诉说着徽商"贾而好儒"的文化传统与"徽骆驼"的坚韧精神，是了解徽州商业文明的重要窗口。', '安徽', 29.861100, 118.415400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/55/%E5%9B%BD%E5%8A%A1%E9%99%A2%E5%85%B3%E4%BA%8E%E6%A0%B8%E5%AE%9A%E5%B9%B6%E5%85%AC%E5%B8%83%E7%AC%AC%E5%85%AB%E6%89%B9%E5%85%A8%E5%9B%BD%E9%87%8D%E7%82%B9%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E7%9A%84%E9%80%9A%E7%9F%A5%EF%BC%88%E5%9B%BD%E5%8F%91%E3%80%942019%E3%80%9522%E5%8F%B7%EF%BC%89.pdf"]'),
('《天云山传奇》', '池州市青阳县九华山天台山遗址', '鲁彦周', '现代', '九华山天台山位于安徽省池州市青阳县，是鲁彦周小说《天云山传奇》中知识分子命运沉浮的精神背景地。天台峰海拔一千三百余米，登顶可俯瞰九华山全貌。山间保留有唐代古寺遗迹，青砖灰瓦掩映在苍松翠柏之间。古驿道石阶陡峭蜿蜒，沿途可见历代高僧修行的石洞与摩崖题刻。清晨云海翻涌，日出时金光万丈，宛如佛光普照。此处远离九华山核心景区的香火喧嚣，保留了宗教圣地的清净与庄严。', '安徽', 30.639200, 117.847400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/95/Jiuhuashan_Tiantai.jpg"]'),
('《历史的天空》', '六安市金寨县天堂寨白马大峡谷遗址', '徐贵祥', '现代', '天堂寨白马大峡谷位于安徽省六安市金寨县，是徐贵祥小说《历史的天空》中大别山抗日战争的核心背景地。峡谷深幽，瀑布飞泻，古栈道沿崖壁蜿蜒数公里。山中保留有红军指挥部旧址、战壕遗迹与红色标语，诉说着革命年代的峥嵘岁月。峡谷两侧原始森林茂密，珍稀植物众多，负氧离子含量极高。春日杜鹃花海绵延，夏日清凉避暑，秋日红叶层叠，是集红色文化、自然风光与历史遗迹于一体的深度体验之地。', '安徽', 31.727600, 115.934800, '其他', '["https://img1.baidu.com/it/u=3561383827,2239172867&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=656"]'),
('《徽州女人》', '黄山市黟县宏村承志堂遗址', '金海涛', '现代', '宏村承志堂位于安徽省黄山市黟县宏村，是金海涛笔下《徽州女人》命运悲欢的重要背景地。承志堂建于清末，以精美绝伦的木雕闻名于世，"百子闹元宵"等雕刻栩栩如生，被誉为"民间故宫"。厅堂布局严谨，天井采光通风，体现了徽派建筑的高超智慧。砖雕门楼、石雕栏杆与木雕梁枋交相辉映，每一处细节都展现了徽州女人在深宅大院中等待丈夫归来的寂寞岁月与坚韧品格，是感受徽州建筑与女性文化的绝佳之地。', '安徽', 29.924600, 117.938400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/50/Yixian_Hongcun_2016.09.09_18-17-55.jpg"]'),
('《天仙配》', '安庆市宜秀区五横乡董永故里遗址', '无名氏', '汉代', '董永故里位于安徽省安庆市宜秀区五横乡，是民间传说《天仙配》的原型发生地，讲述了董永卖身葬父、感动天女下凡的动人故事。遗址保留有汉代董永墓、古碑与传说中的千年槐荫树，树冠如盖，枝繁叶茂。周边田园风光秀丽，水塘映照着蓝天白云，保留了皖西南乡村的质朴风貌。每年七夕前后，当地会举办天仙配文化节，演出黄梅戏经典剧目。漫步其间，能深切感受到中国民间爱情传说的浪漫与孝道文化的深厚根基。', '安徽', 30.613000, 116.987200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/9b/%E5%8D%97%E9%98%B3%E7%9F%A5%E5%BA%9C%E8%A1%99%E9%97%A8_2025-06-02_02.jpg"]');
INSERT INTO works (title, scenic_spot, author, dynasty, description, province, latitude, longitude, category, images) VALUES
('《水经注・江水注》', '安庆市迎江区振风塔遗址', '郦道元', '北魏', '安庆振风塔矗立于安徽省安庆市迎江区长江北岸，是郦道元《水经注·江水注》中所记载的长江沿岸重要地标。振风塔始建于明代，高约六十余米，七层八角，是长江沿岸最高的古塔之一。"塔影横江"为安庆传统八景之首，夕阳西下时塔影倒映江面，景象极为壮美。塔内保留有明代石刻、佛像与碑文，登顶可俯瞰长江东去、远山连绵的壮阔景致。此处游客不多，江风习习，是感受长江文化与古代建筑智慧的清幽之地。', '安徽', 30.511300, 117.091700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/7b/Bridge_on_the_Yangtze_River_in_Anqing_Anhui_China.jpg"]'),
('《徽州府志》', '黄山市黟县西递古村敬爱堂遗址', '何歆', '明代', '西递古村敬爱堂位于安徽省黄山市黟县，是何歆《徽州府志》中记载的徽派祠堂建筑典范。敬爱堂始建于明代万历年间，为胡氏宗族祠堂，堂内"敬爱"二字匾额庄严肃穆。木雕梁枋刻有人物故事、花鸟鱼虫，刀法精湛细腻；砖雕门楼层层叠叠，古碑记载着宗族数百年的兴衰变迁。堂内天井方正，光线柔和，体现了徽州人"聚族而居、敬祖收族"的宗法理念。漫步其间，能深切感受到徽州宗族文化的厚重与建筑美学的精妙。', '安徽', 29.924600, 117.938400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/5a/Xidi1024x1360.jpg"]'),
('《红楼梦》', '黄山市歙县棠樾牌坊群遗址', '曹雪芹', '清代', '棠樾牌坊群位于安徽省黄山市歙县，相传与曹雪芹《红楼梦》中大观园的牌坊意象有所关联。牌坊群由明清两代七座石坊组成，跨越三百余年历史，分别表彰忠孝节义。每座牌坊造型各异，石雕精美绝伦，龙凤呈祥、麒麟送子等图案栩栩如生。牌坊两侧田野开阔，远处青山如黛，油菜花盛开时金黄一片。这组牌坊群完整呈现了封建社会的道德标准与家族荣耀观念，是研究徽州社会制度与石雕艺术的珍贵实物遗存。', '安徽', 29.861100, 118.415400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/17/Tangyue_5328.jpg"]'),
('《皖南事变》', '宣城市泾县云岭新四军军部旧址', '黎汝清', '现代', '云岭新四军军部旧址位于安徽省宣城市泾县，是黎汝清小说《皖南事变》的核心历史背景地。旧址群包括军部大会堂、政治部、叶挺将军旧居等数十处建筑，保留了抗战时期的原始风貌。青砖灰瓦的皖南民居内陈列着大量珍贵的历史照片、文件与实物，再现了新四军英勇抗日的峥嵘岁月。旧址周围群山环抱，溪水潺潺，竹林茂密，自然环境清幽。此处是缅怀革命先烈、了解皖南事变历史真相的重要红色教育基地。', '安徽', 30.688300, 118.419700, '其他', '["https://img2.baidu.com/it/u=3858272773,3026225452&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《李鸿章》', '合肥市肥东县李鸿章故居遗址', '唐浩明', '现代', '李鸿章故居位于安徽省合肥市肥东县（另有合肥市区故居），是唐浩明小说《李鸿章》的核心创作背景地。故居保留了清代晚期的建筑风格，正厅、书房、后花园布局严整，院内古碑记载着李鸿章的生平事迹。藏书楼内曾收藏大量典籍文献，展现了这位晚清重臣"少年科第、壮年戎马、中年封疆、晚年洋务"的传奇人生。漫步其间，能感受到那个风云激荡的时代中，一位复杂历史人物的多面人生与家国情怀。', '安徽', 31.887900, 117.469300, '其他', '["https://img2.baidu.com/it/u=3065762356,2846198321&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1464"]'),
('《陈独秀》', '安庆市迎江区陈独秀故居遗址', '石楠', '现代', '陈独秀故居位于安徽省安庆市迎江区，是石楠小说《陈独秀》的核心创作背景地。故居为清代建筑，青砖小瓦，木质门窗，保留了典型的皖南民居风格。室内陈列着陈独秀早年的生活用品、书信手稿与生平资料，再现了这位新文化运动旗手的成长环境。故居附近便是长江岸边，江风浩荡，与少年陈独秀"国家兴亡匹夫有责"的壮志豪情相呼应。此处游客稀少，环境清幽，是了解中国近代思想启蒙历程的重要文化遗址。', '安徽', 30.511300, 117.091700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/7b/Bridge_on_the_Yangtze_River_in_Anqing_Anhui_China.jpg"]'),
('《胡适》', '宣城市绩溪县胡适故居遗址', '易竹贤', '现代', '胡适故居位于安徽省宣城市绩溪县上庄村，是易竹贤传记《胡适》的核心创作背景地。故居为清代徽派建筑，白墙灰瓦、天井回廊，保留了胡适幼年读书的书房与家族祠堂。室内陈列着胡适的早期著作、家书与生活用品，古碑记载着胡氏家族在绩溪的数百年传承。故居所在的上庄村群山环抱，溪水潺潺，徽派民居错落有致，保留了皖南乡村的原始质朴。漫步其间，能感受到这位"但开风气不为师"的学者与故乡之间的深厚羁绊。', '安徽', 30.070400, 118.596700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/2/2a/The_Memorial_Temple_for_the_Family_of_Zhou_in_Jixi_County_20_2015-01.JPG"]'),
('《徽州文化》', '黄山市歙县呈坎古村宝纶阁遗址', '叶显恩', '现代', '呈坎古村宝纶阁位于安徽省黄山市歙县（实为徽州区呈坎），是叶显恩《徽州文化》中记述的徽派建筑代表之作。宝纶阁始建于明代嘉靖年间，为罗氏宗族祠堂，三进五开间的宏大规模在徽州祠堂中首屈一指。堂内木雕精美绝伦，梁枋上的人物故事、花卉瑞兽雕刻细腻入微。砖雕门楼层层递进，古碑记录着宗族荣耀。呈坎八卦布局的村落格局至今保存完好，是研究徽州建筑艺术与宗族文化的活标本。', '安徽', 29.861100, 118.415400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/8a/Chengkan_5456.jpg"]'),
('《游敬亭山记》', '宣城市宣州区敬亭山翠云庵遗址', '袁宏道', '明代', '敬亭山翠云庵遗址位于安徽省宣城市宣州区敬亭山中，是明代文学家袁宏道《游敬亭山记》中描绘的幽静胜地。敬亭山自李白"相看两不厌，只有敬亭山"后便成为文人圣地，历代名家纷纷登临吟咏。翠云庵遗址保留有明代建筑基址、古碑与天然泉眼，泉水甘冽清凉。山间古木参天，竹林幽深，鸟鸣啾啾，远离城市喧嚣。春日山花烂漫，秋日层林尽染，是文人雅士寄情山水、修身养性的理想之地。', '安徽', 31.138600, 118.755100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/43/2016%E5%B9%B4%E5%BA%A6%E5%85%A8%E5%9B%BD%E5%8D%9A%E7%89%A9%E9%A6%86%E5%90%8D%E5%BD%95.pdf"]'),
('《采石矶记》', '马鞍山市雨山区采石矶三元洞遗址', '王守仁', '明代', '采石矶三元洞位于安徽省马鞍山市雨山区长江南岸，是明代思想家王守仁《采石矶记》中描绘的胜景。三元洞天然形成于悬崖之中，洞口面向长江，凭栏可俯瞰大江东去的壮阔景象。洞内保留有明代碑刻与佛像，石壁上历代文人的题刻斑驳可辨。采石矶自古为兵家必争之地，李白醉酒捉月的传说更增添了浪漫色彩。江风猎猎，涛声阵阵，站在洞口极目远眺，天际线处水天一色，是感受长江雄浑气象的绝佳观赏点。', '安徽', 31.685100, 118.498600, '其他', '["https://img2.baidu.com/it/u=4104126068,2214035990&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=741"]'),
('《巢湖志》', '合肥市巢湖市姥山岛中庙寺遗址', '李恩绶', '清代', '姥山岛中庙寺位于安徽省合肥市巢湖市，是李恩绶《巢湖志》中记载的巢湖名胜。中庙寺始建于唐代，历经多次重建，保留有唐代建筑基址、古碑与佛像。寺庙矗立于湖岸高处，登临可俯瞰巢湖八百里烟波浩渺的壮阔全景。姥山岛孤峙湖中，岛上文峰塔高耸，与中庙寺遥遥相望。春日湖面碧波荡漾，夏日荷花映日，秋日渔舟唱晚，冬日候鸟翔集。此处远离都市喧嚣，是感受皖中湖光山色与佛教文化的清幽胜地。', '安徽', 31.600400, 117.874000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/3f/Chao_Lake_NASA.jpg"]'),
('《九华山志》', '池州市青阳县九华山肉身宝殿遗址', '喻成龙', '清代', '九华山肉身宝殿位于安徽省池州市青阳县九华山上，是喻成龙《九华山志》中详细记载的佛教圣迹。宝殿供奉唐代高僧金地藏（金乔觉）的肉身法体，是九华山佛教信仰的核心所在。殿宇依山而建，红墙金瓦，气势庄严。殿内保留有唐代建筑基址、历代古碑与珍贵佛经。每逢地藏菩萨圣诞，信众云集，梵音缭绕。殿外古松挺拔，云雾缥缈，远处群峰如莲花瓣般环绕，营造出"莲花佛国"的神圣氛围，是佛教朝圣与文化研究的重要圣地。', '安徽', 30.639200, 117.847400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/1a/Roushen_Temple.jpg"]'),
('《皖西大别山》', '六安市霍山县白马尖遗址', '徐刚', '现代', '白马尖位于安徽省六安市霍山县大别山腹地，是徐刚《皖西大别山》中描绘的大别山最高峰，海拔一千七百七十七米。山间保留有唐代古寺遗址、蜿蜒的古驿道与珍贵的摩崖石刻。登顶之路穿越原始森林，古木参天，藤蔓缠绕，珍稀动植物种类繁多。峰顶视野开阔，可远眺皖鄂交界的连绵群山。春日杜鹃花海如火如荼，夏日清凉宜人，秋日红叶满山，冬日雾凇晶莹。此处开发程度极低，保留了大别山最原始的自然风貌与生态环境。', '安徽', 31.392400, 116.333000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/4a/Panoramic_view_of_a_residential_area_in_Lu%27an_City%2C_Anhui_Province.jpg"]'),
('《新安江山水画廊游记》', '黄山市歙县深渡镇漳潭古村遗址', '陈从周', '现代', '深渡镇漳潭古村位于安徽省黄山市歙县新安江畔，是陈从周《新安江山水画廊游记》中描绘的如画之地。村中保留有千年古樟树，树冠遮天蔽日，枝干苍劲有力，是新安江沿岸的标志性景观。明清古民居沿江而建，白墙灰瓦倒映碧水之中，宛如水墨画卷。古码头石阶斑驳，曾是徽商水路运输的重要起点。春日两岸桃花灼灼，油菜花金黄，与粉墙黛瓦交相辉映，乘船顺流而下，移步换景，是体验新安江山水画廊精华的最佳段落。', '安徽', 29.861100, 118.415400, '其他', '["https://img1.baidu.com/it/u=3661596894,2078721043&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1202"]'),
('《皖江游记》', '安庆市潜山市天柱山炼丹湖遗址', '方苞', '清代', '天柱山炼丹湖位于安徽省安庆市潜山市天柱山上，是方苞《皖江游记》中描绘的高山湖泊胜景。炼丹湖海拔约一千一百米，是中国第三大高山人工湖，传说为汉代左慈炼丹之所。湖水碧绿如玉，清澈见底，四周群山环抱，奇松怪石遍布湖岸。晨曦时分湖面雾气氤氲，如入仙境；夕阳西下时金光洒满水面，美不胜收。此处远离天柱山主景区的游客潮流，环境极为静谧，是感受皖西南高山湖泊独特魅力的绝佳之地。', '安徽', 30.630800, 116.551300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/82/Tianzhu_Peak_%2820170116142019%29.jpg"]'),
('《游齐云山记》', '黄山市休宁县齐云山太素宫遗址', '袁枚', '清代', '齐云山太素宫位于安徽省黄山市休宁县齐云山上，是袁枚《游齐云山记》中描绘的道教圣地。太素宫始建于明代，为齐云山最重要的道教宫观，供奉真武大帝。宫内保留有明代建筑构件、历代古碑与道教神像，壁画色彩斑斓。齐云山以丹霞地貌著称，红色岩壁与绿色植被交相辉映，山间云雾缭绕，宛如仙境。道教"天人合一"的理念在此处的山水建筑中得到完美体现。此处游客远少于黄山，是感受道教文化与丹霞风光的清幽之地。', '安徽', 29.785600, 118.181300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/b/b9/%E6%91%9B%E8%97%BB%E5%A0%82%E5%9B%9B%E5%BA%AB%E5%85%A8%E6%9B%B8%E8%96%88%E8%A6%81.%E7%AC%AC426%E5%86%8A.%E9%9B%86%E9%83%A8079%E5%86%8A.djvu"]'),
('《安徽通志》', '六安市寿县寿州古城墙遗址', '邓廷桢', '清代', '寿州古城墙位于安徽省六安市寿县，是邓廷桢《安徽通志》中记载的重要军事防御遗存。古城墙始建于宋代，是中国保存最完整的宋代城防体系之一。城墙周长约七公里，高约十米，保留有四座城门、瓮城与角楼。城墙上古炮威武矗立，城门洞石刻斑驳，诉说着淝水之战等无数历史风云。护城河碧水环绕，岸柳依依，城内老街巷保留着皖北古镇的质朴风貌。登上城墙远眺，可感受到这座千年古城"铁打寿州城"的雄浑气势。', '安徽', 32.545000, 116.787900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/d1/%E5%AE%89%E5%BE%BD%E7%9C%81%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E8%BF%9B%E4%B8%80%E6%AD%A5%E5%8A%A0%E5%BC%BA%E6%96%87%E7%89%A9%E5%B7%A5%E4%BD%9C%E7%9A%84%E5%AE%9E%E6%96%BD%E6%84%8F%E8%A7%81.pdf"]'),
('《游黄山记》', '黄山市黄山区黄山光明顶遗址', '钱谦益', '清代', '黄山光明顶位于安徽省黄山市黄山区，是钱谦益《游黄山记》中描绘的黄山第二高峰，海拔一千八百六十米。顶上地势平坦开阔，是观赏黄山日出日落和云海的最佳位置之一。保留有明代摩崖石刻，记录了历代文人登临的感悟。站在光明顶极目远眺，前山后山尽收眼底，奇松、怪石、云海、温泉四绝一览无余。清晨云海翻涌时，峰尖如岛屿般浮于云上，景象壮观至极。此处虽非黄山最高峰，却因视野最为开阔而深受摄影爱好者青睐。', '安徽', 30.272900, 118.141600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/37/%E5%85%A8%E5%9B%BD%E9%87%8D%E7%82%B9%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E4%B8%B9%E9%9C%9E%E5%B1%B1%E6%91%A9%E5%B4%96%E7%9F%B3%E5%88%BB%E4%BF%9D%E6%8A%A4%E8%A7%84%E5%88%92-%E7%AC%AC%E4%B8%89%E9%83%A8%E5%88%86_%E8%A7%84%E5%88%92%E8%AF%B4%E6%98%8E.pdf"]'),
('《桐城派文选》', '安庆市桐城市桐城文庙遗址', '方苞', '清代', '桐城文庙位于安徽省安庆市桐城市中心，是方苞等桐城派文人的精神家园，也是桐城派文学运动的核心发源地。文庙始建于元代，现存建筑以清代风格为主，大成殿、明伦堂、棂星门庄严肃穆。古碑林立其间，记载着桐城派"义法"文论的精髓与历代名人的传承脉络。文庙内设有桐城派名人陈列馆，展示了方苞、刘大櫆、姚鼐等文学大家的手稿与著作。漫步于此，能深刻感受到"天下文章出桐城"的深厚文化底蕴与清代散文艺术的至高成就。', '安徽', 31.035400, 116.956500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/90/201705_A_Church_in_Tongcheng.jpg"]'),
('《小岗村纪事》', '滁州市凤阳县小岗村大包干纪念馆遗址', '陈桂棣', '现代', '小岗村位于安徽省滁州市凤阳县，是陈桂棣《小岗村纪事》的核心叙述地，也是中国农村改革的历史性起点。一九七八年十八位农民冒着风险按下红手印、实行"大包干"的壮举在此发生。大包干纪念馆内保留着当年的茅草屋、生产队队部、红手印契约复制件等珍贵实物，真实再现了那个改变中国农村命运的历史瞬间。村内沈浩同志先进事迹陈列馆同样令人动容。此处是了解中国改革开放史与"敢为天下先"精神的重要教育基地。', '安徽', 32.874900, 117.531600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/83/20240807_Fengyang_Gulou.jpg"]'),
('《登金陵凤凰台》', '南京市秦淮区凤凰台遗址', '李白', '唐代', '凤凰台遗址位于南京市秦淮区，是李白《登金陵凤凰台》的创作之地。"凤凰台上凤凰游，凤去台空江自流"的千古名句即诞生于此。遗址保留有唐代夯土台基与宋代碑刻，记录了历代文人登台怀古的感悟。站在台基之上，可远眺长江东去、秦淮水系蜿蜒入江的壮阔景象。李白在此感怀六朝兴亡更替，以磅礴气势抒发了对历史变迁的深沉思考。此处远离秦淮河商业区的喧闹，是感受金陵帝王气象与唐诗豪放之美的清幽之地。', '江苏', 32.039300, 118.794400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/3f/State_Council_Gazette_-_2019_-_Issue_30.pdf"]'),
('《泊秦淮》', '南京市秦淮区秦淮河古渡口遗址', '杜牧', '唐代', '秦淮河古渡口位于南京市秦淮区，是杜牧《泊秦淮》"烟笼寒水月笼沙，夜泊秦淮近酒家"的真实描绘地。古渡口保留有明清时期的石砌码头与青石板路，斑驳的石阶见证了千年来商旅往来的繁华。渡口两岸曾是秦淮歌舞升平之地，"商女不知亡国恨，隔江犹唱后庭花"的感慨至今令人深思。夜晚灯火初上时，河面波光粼粼，古码头的轮廓在月色中若隐若现，再现了晚唐诗人泊船秦淮时所见的那份繁华与苍凉交织的独特意境。', '江苏', 32.039300, 118.794400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/91/Qinhuai_River_along_Fuzimiao_2008.jpg"]'),
('《乌衣巷》', '南京市秦淮区乌衣巷王谢故居遗址', '刘禹锡', '唐代', '乌衣巷位于南京市秦淮区，是刘禹锡《乌衣巷》"旧时王谢堂前燕，飞入寻常百姓家"的原型地。这里曾是东晋豪门王导、谢安的府邸所在，门庭若市、冠盖如云。遗址保留有东晋建筑基址、古碑与古井，诉说着六朝世家的煊赫与没落。狭窄的巷道两侧青砖灰瓦，石板路光滑如镜，岁月的痕迹无处不在。如今的乌衣巷已不见昔日的钟鸣鼎食，但那份"朱雀桥边野草花"的历史沧桑感仍深深打动每一位来访者，是感悟历史兴亡的绝佳之地。', '江苏', 32.039300, 118.794400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/%E5%8D%97%E4%BA%AC%E4%B9%8C%E8%A1%A3%E5%B7%B7%2C_2009-01-26_01.jpg/1280px-%E5%8D%97%E4%BA%AC%E4%B9%8C%E8%A1%A3%E5%B7%B7%2C_2009-01-26_01.jpg"]'),
('《枫桥夜泊》', '苏州市姑苏区枫桥夜泊古码头遗址', '张继', '唐代', '枫桥古码头位于苏州市姑苏区，是张继《枫桥夜泊》"姑苏城外寒山寺，夜半钟声到客船"的诞生地。古码头保留有唐代石砌泊位、枫桥古桥与历代碑刻，记录了这首千古名诗的流传与影响。运河水缓缓流淌，古桥倒映水中，两岸枫树在深秋时节红叶如火。夜幕降临时，寒山寺的钟声穿越千年依然悠扬回荡，与运河上的渔火交相辉映。此处虽紧邻寒山寺景区，但古码头区域保留了原始的运河风貌，是体验唐诗意境最为真切的地方。', '江苏', 31.311400, 120.617400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e7/%E6%97%A0%E9%94%A1%E4%B8%89%E9%98%B3%E5%B9%BF%E5%9C%BA.jpg"]'),
('《题破山寺后禅院》', '苏州市常熟市兴福寺空心潭遗址', '常建', '唐代', '兴福寺空心潭位于苏州市常熟市虞山北麓，是常建《题破山寺后禅院》"曲径通幽处，禅房花木深"的核心取景地。兴福寺始建于南齐，唐代达到鼎盛。寺后竹林幽深，古亭掩映其间，空心潭水清见底，游鱼可数。唐代摩崖石刻散布于山石之间，字迹苍劲有力。清晨薄雾中，竹叶上的露珠晶莹剔透，鸟鸣声回荡在空谷之中，"万籁此都寂，但余钟磬音"的禅意扑面而来。此处是江南古刹中难得的清幽之地，完美呈现了唐诗中的禅院美学。', '江苏', 31.653900, 120.752200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/49/Xingfu_Temple_in_Changshu_11_2014-10.jpg"]'),
('《寄扬州韩绰判官》', '扬州市邗江区瘦西湖二十四桥遗址', '杜牧', '唐代', '瘦西湖二十四桥遗址位于扬州市邗江区，是杜牧《寄扬州韩绰判官》"二十四桥明月夜，玉人何处教吹箫"的描绘之地。遗址保留有宋代桥基、古碑与亭台楼阁，桥身洁白如玉，桥长二十四米，宽二点四米，与诗中意象完美呼应。桥下碧波荡漾，荷叶田田，两岸垂柳依依。月夜时分，桥影倒映水中，银辉洒满湖面，箫声仿佛从千年前飘然而至。此处是扬州瘦西湖最具诗意的景致，完美再现了晚唐扬州"十里春风"的繁华与浪漫。', '江苏', 32.376900, 119.398000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/West_Lake%2C_Hangzhou_2025.jpg/1280px-West_Lake%2C_Hangzhou_2025.jpg"]'),
('《扬州慢・淮左名都》', '扬州市广陵区宋夹城遗址', '姜夔', '南宋', '宋夹城遗址位于扬州市广陵区瘦西湖东侧，是姜夔《扬州慢》"过春风十里，尽荠麦青青"的创作背景地。南宋词人姜夔路过扬州时，目睹金兵南侵后的萧条景象，悲愤之下写就此词。遗址保留有宋代夯土城墙、护城河与城门基址，城墙蜿蜒数百米，诉说着那段兵燹之后的苍凉岁月。如今护城河畔绿树成荫，城墙遗址上野花丛生，历史的伤痕在自然的修复中渐渐抚平。此处是感受南宋文人忧国之思与扬州千年沧桑巨变的重要历史遗存。', '江苏', 32.394600, 119.431800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/f/f8/Site_of_Tongsi_Gate_of_Yangzhou_in_the_Song_Dynasty_02_2013-03.jpg"]'),
('《泊船瓜洲》', '镇江市京口区瓜洲古渡遗址', '王安石', '北宋', '瓜洲古渡位于镇江市京口区长江边，是王安石《泊船瓜洲》"春风又绿江南岸，明月何时照我还"的创作之地。古渡保留有宋代石砌码头、古碑与瓜洲闸遗址，曾是长江南北交通的重要枢纽。站在渡口远眺，长江浩荡东去，对岸便是"京口瓜洲一水间"的金山。春日江风和煦，两岸绿意盎然，与诗中"春风又绿江南岸"的意境完美契合。此处虽不再有渡船往来，但古码头的石阶与斑驳碑文仍在诉说着千年来无数旅人在此渡江的离愁别绪。', '江苏', 32.198000, 119.469800, '其他', '["https://img1.baidu.com/it/u=1419664587,3201714674&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=652"]'),
('《次北固山下》', '镇江市丹徒区北固山甘露寺遗址', '王湾', '唐代', '北固山甘露寺位于镇江市丹徒区，是王湾《次北固山下》"潮平两岸阔，风正一帆悬"的描绘之地，也是三国刘备招亲的传说发生地。甘露寺始建于东吴，保留有唐代建筑基址、古碑与多景楼。登临北固山顶，长江在脚下奔腾，视野极为开阔，"海日生残夜，江春入旧年"的壮阔意境扑面而来。寺内古柏苍翠，殿宇庄严，"天下第一江山"石刻雄浑有力。此处文学典故、三国传说与长江胜景交织，是镇江最具历史文化底蕴的名胜。', '江苏', 32.131900, 119.433400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/d9/%E5%A4%A7%E5%B8%82%E5%8F%A3%E9%A3%8E%E5%85%89.jpg"]'),
('《永遇乐・京口北固亭怀古》', '镇江市京口区北固亭遗址', '辛弃疾', '南宋', '北固亭遗址位于镇江市京口区北固山上，是辛弃疾《永遇乐·京口北固亭怀古》"金戈铁马，气吞万里如虎"的创作之地。遗址保留有宋代亭基、古碑与摩崖石刻，记录了南宋爱国词人的慷慨悲歌。登亭远望，长江如带，"千古兴亡多少事，悠悠，不尽长江滚滚流"的感慨油然而生。辛弃疾在此凭吊孙权、刘裕等英雄人物，抒发北伐中原的壮志未酬之叹。此处山势险要，江风猎猎，是感受南宋爱国词人豪放悲壮情怀的最佳历史现场。', '江苏', 32.198000, 119.469800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/d9/%E5%A4%A7%E5%B8%82%E5%8F%A3%E9%A3%8E%E5%85%89.jpg"]'),
('《惠山谒钱道人烹小龙团登绝顶望太湖》', '无锡市滨湖区惠山天下第二泉遗址', '苏轼', '北宋', '惠山天下第二泉位于无锡市滨湖区惠山脚下，是苏轼《惠山谒钱道人烹小龙团登绝顶望太湖》的创作之地。泉眼源自唐代，被茶圣陆羽评为天下第二，泉水甘冽清凉，至今涌流不息。泉旁保留有唐代泉池、宋代碑刻与古亭，记录了历代文人品茗赏泉的雅趣。苏轼在此以小龙团茶烹煮二泉水，留下了"独携天上小团月，来试人间第二泉"的佳句。周围古木参天，竹林幽深，泉声与鸟鸣交织，是体验宋代文人雅致生活与无锡茶泉文化的绝佳之地。', '江苏', 31.527900, 120.285800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e7/%E6%97%A0%E9%94%A1%E4%B8%89%E9%98%B3%E5%B9%BF%E5%9C%BA.jpg"]'),
('《西塞山怀古》', '南京市雨花台区西塞山遗址', '刘禹锡', '唐代', '西塞山遗址位于南京市雨花台区（一说黄石），是刘禹锡《西塞山怀古》"王濬楼船下益州，金陵王气黯然收"的创作之地。此处曾是西晋灭吴之战的古战场，保留有晋代古战场遗迹、摩崖石刻与古碑。山势临江而立，俯瞰长江滔滔东去，当年千帆竞发、铁锁横江的战争场景仿佛历历在目。刘禹锡借此感慨"人世几回伤往事，山形依旧枕寒流"的历史兴亡。此处游客极少，江风浩荡，是凭吊六朝风云、感受唐诗怀古情怀的幽静之地。', '江苏', 31.991800, 118.779900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/f/fd/%E5%8D%97%E4%BA%AC%E6%80%BB%E7%BB%9F%E5%BA%9C%E8%A5%BF%E8%8A%B1%E5%8E%852024.3.jpg"]'),
('《金陵酒肆留别》', '南京市秦淮区金陵酒肆遗址', '李白', '唐代', '金陵酒肆遗址位于南京市秦淮区，是李白《金陵酒肆留别》"吴姬压酒唤客尝，金陵子弟来相送"的创作之地。遗址保留有明清时期的酒肆建筑、古碑与酿酒作坊，青砖灰瓦间弥漫着历史的酒香。李白在金陵期间常与友人豪饮于此，"风吹柳花满店香"的盛唐风流在字里行间跃然而出。秦淮河畔的古酒肆曾是文人雅集、商旅歇脚的重要场所。漫步其间，想象盛唐时节金陵城的繁华热闹与诗酒风流，能深切感受到李白笔下那个自由奔放的黄金时代。', '江苏', 32.039300, 118.794400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/f/fd/%E5%8D%97%E4%BA%AC%E6%80%BB%E7%BB%9F%E5%BA%9C%E8%A5%BF%E8%8A%B1%E5%8E%852024.3.jpg"]'),
('《送孟浩然之广陵》', '扬州市广陵区茱萸湾古渡遗址', '李白', '唐代', '茱萸湾古渡位于扬州市广陵区，是李白《送孟浩然之广陵》"故人西辞黄鹤楼，烟花三月下扬州"的送别目的地。古渡保留有唐代石砌码头、古碑与古寺遗迹，曾是唐代扬州水路交通的重要门户。春日三月，两岸桃花灼灼，柳絮飞扬，运河上舟楫往来，再现了盛唐扬州的繁华景象。"孤帆远影碧空尽，唯见长江天际流"的离别意境在此处尤为真切。古渡周围环境清幽，远离扬州老城区的喧嚣，是感受唐代送别文化与扬州水路历史的宁静之地。', '江苏', 32.394600, 119.431800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/2/2c/Five_Pavilion_Bridge_and_White_Pagoda_2017.jpg"]'),
('《忆江南》', '苏州市吴江区同里古镇三桥遗址', '白居易', '唐代', '同里古镇三桥位于苏州市吴江区，是白居易《忆江南》"江南好，风景旧曾谙"所描绘的水乡意象代表。三桥由太平桥、吉利桥、长庆桥组成，横跨三条水巷交汇处，构成了江南水乡最经典的画面。桥下碧水悠悠，乌篷船缓缓穿行，两岸明清古民居粉墙黛瓦倒映水中。古码头石阶上青苔斑驳，老妪在河边浣衣，渔翁在桥头垂钓，保留着最原汁原味的江南水乡生活。春日油菜花开，秋日桂花飘香，四时风光各异，是体验白居易笔下"日出江花红胜火，春来江水绿如蓝"之美的绝佳之地。', '江苏', 31.159300, 120.645100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/2/2d/ANNIVERSARY_OF_THE_CITY_1.pdf"]'),
('《渔歌子》', '苏州市昆山市周庄镇南湖遗址', '张志和', '唐代', '周庄南湖位于苏州市昆山市周庄镇南侧，是张志和《渔歌子》"西塞山前白鹭飞，桃花流水鳜鱼肥"的原型地之一。南湖水域开阔，保留着原始的水乡风貌，古渡口石阶延伸入水，渔船三两只泊于岸边。湖面波光粼粼，白鹭翩翩起舞，芦苇丛中偶有渔翁撒网。春日桃花盛开时，花瓣随水流漂散，"斜风细雨不须归"的隐逸意境在此处得到最真实的呈现。南湖远离周庄古镇核心商业区，保留了江南水乡最质朴的渔耕生活场景。', '江苏', 31.385300, 120.981000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/95/Zhouzhuang1.jpg"]'),
('《台城》', '南京市玄武区台城遗址', '韦庄', '唐代', '台城遗址位于南京市玄武区鸡鸣寺北侧，是韦庄《台城》"江雨霏霏江草齐，六朝如梦鸟空啼"的创作之地。台城曾是六朝皇宫所在，见证了东吴、东晋、宋齐梁陈的兴衰更替。遗址保留有明代城墙与护城河，古碑记载着六朝的辉煌与覆亡。春日城墙上樱花烂漫，夏日绿荫蔽城，秋日银杏金黄，冬日梅花暗香。登上城墙远眺，玄武湖碧波万顷，紫金山青翠如黛，"无情最是台城柳，依旧烟笼十里堤"的历史苍凉感扑面而来，是感悟六朝兴亡的最佳历史现场。', '江苏', 32.048600, 118.797400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/74/%E7%BB%9F%E8%AE%A1%E7%94%A8%E5%8C%BA%E5%88%92%E4%BB%A3%E7%A0%81%E5%92%8C%E5%9F%8E%E4%B9%A1%E5%88%92%E5%88%86%E4%BB%A3%E7%A0%81_%E6%B1%9F%E8%8B%8F.pdf"]'),
('《桂枝香・金陵怀古》', '南京市玄武区玄武湖览胜楼遗址', '王安石', '北宋', '玄武湖览胜楼遗址位于南京市玄武区，是王安石《桂枝香·金陵怀古》"登临送目，正故国晚秋，天气初肃"的创作之地。遗址保留有宋代建筑基址、古碑与苍劲古柏。登临此处，玄武湖烟波浩渺尽收眼底，远处钟山龙蟠、石城虎踞的金陵形胜一览无余。"千里澄江似练，翠峰如簇"的壮丽景象在晚秋时节尤为动人。王安石在此感怀"六朝旧事随流水，但寒烟衰草凝绿"，将个人抱负与家国命运融为一体。此处是感受北宋政治家诗人胸襟与金陵山水气象的绝佳之地。', '江苏', 32.048600, 118.797400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/7a/Xuanwuhu.jpg"]'),
('《青玉案・元夕》', '南京市秦淮区老门东花灯巷遗址', '辛弃疾', '南宋', '老门东花灯巷遗址位于南京市秦淮区，是辛弃疾《青玉案·元夕》"众里寻他千百度，蓦然回首，那人却在灯火阑珊处"的创作背景地。老门东保留有明清古民居、老店铺与青石板古巷，曾是南京最热闹的元宵灯会举办地。花灯巷中灯笼高挂，烛光摇曳，投射出温暖的橘红色光芒。正月十五夜，秦淮河畔花灯如昼，人潮涌动，"宝马雕车香满路，凤箫声动，玉壶光转"的盛况仿佛重现。此处是体验南宋词人笔下元宵佳节繁华景象的最佳历史街区。', '江苏', 32.039300, 118.794400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/f/fd/%E5%8D%97%E4%BA%AC%E6%80%BB%E7%BB%9F%E5%BA%9C%E8%A5%BF%E8%8A%B1%E5%8E%852024.3.jpg"]'),
('《题惠崇春江晚景》', '无锡市江阴市鹅鼻嘴公园遗址', '苏轼', '北宋', '鹅鼻嘴公园遗址位于无锡市江阴市长江南岸，是苏轼《题惠崇春江晚景》"竹外桃花三两枝，春江水暖鸭先知"的描绘之地。公园地处长江要塞，保留有宋代古渡遗迹、摩崖石刻与近代古炮台，见证了长江防线的千年沧桑。春日桃花盛开时，江水渐暖，野鸭戏水于江滩之上，与诗中意境完美吻合。站在崖头俯瞰，长江浩荡东去，对岸靖江隐约可见。江风猎猎，涛声阵阵，是同时感受宋诗生活情趣与长江雄浑气象的独特之地。', '江苏', 31.920700, 120.285700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/b/b1/Jiangyin_Yangtze_River_bridge-2.jpeg"]'),
('《四时田园杂兴・其二十五》', '苏州市吴中区石湖渔庄遗址', '范成大', '南宋', '石湖渔庄遗址位于苏州市吴中区石湖之滨，是范成大《四时田园杂兴》"梅子金黄杏子肥，麦花雪白菜花稀"的创作之地。范成大晚年退隐石湖，以田园诗记录了江南四季的农耕生活。遗址保留有宋代建筑基址、古碑与田园风光，石湖水波潋滟，渔舟唱晚。春日油菜花金黄，夏日荷叶田田，秋日稻穗金黄，冬日腊梅暗香，四时景色各异。周围乡村保留着传统的耕作方式，"昼出耘田夜绩麻"的田园生活场景至今可见，是体验南宋田园诗意的最佳之地。', '江苏', 31.262700, 120.632000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e5/Taihu_Lake_Suzhou.jpg"]'),
('《过扬子江》', '镇江市京口区扬子江古渡遗址', '杨万里', '南宋', '扬子江古渡遗址位于镇江市京口区长江边，是杨万里《过扬子江》"天将天堑护吴天"的创作之地。古渡保留有宋代石砌码头、古碑与近代古炮台，曾是长江南北交通的咽喉要地。站在渡口远眺，长江浩浩荡荡，"携瓶自汲江心水"的宋人生活情趣仿佛就在眼前。两岸山色青翠，"正堪愁蹙翠眉尖"的江南秀色令人沉醉。此处见证了无数历史风云，从六朝到宋元，长江天堑在此守护着江南大地。古渡周围环境清幽，是感受长江天堑文化与宋诗写实之美的历史遗存。', '江苏', 32.198000, 119.469800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/f/f5/Humble_Administrator%27s_Garden_Suzhou_November_2017_005.jpg"]'),
('《八声甘州・灵岩陪庾幕诸公游》', '苏州市吴中区灵岩山馆娃宫遗址', '吴文英', '南宋', '灵岩山馆娃宫遗址位于苏州市吴中区灵岩山顶，是吴文英《八声甘州》词中追忆的春秋吴宫遗迹。馆娃宫为吴王夫差为西施所建，是中国历史上最早的皇家园林之一。遗址保留有春秋时期的建筑基址、古碑与吴王古井，井水至今清澈。山顶视野开阔，可俯瞰太湖与苏州平原。"渐吹尽枝头香絮，是处人家绿深门户"的词境在春日尤为动人。此处远离苏州城区的喧嚣，松涛阵阵，古木参天，是凭吊吴越春秋风云与感受宋词婉约之美的幽静胜地。', '江苏', 31.262700, 120.632000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/c9/%E7%81%B5%E5%B2%A9%E5%B1%B1%E5%AF%BA.jpg"]'),
('《长干行・其一》', '南京市秦淮区长干里遗址', '李白', '唐代', '长干里遗址位于南京市秦淮区中华门外，是李白《长干行》"郎骑竹马来，绕床弄青梅"的创作之地。长干里自六朝以来便是金陵重要的居民聚居区与商业中心。遗址保留有明清古民居、幽深古巷与百年古井，青石板路光滑如镜。"同居长干里，两小无嫌猜"的纯真爱情故事就发生在这些窄巷深院之中。李白以细腻笔触描绘了长干里少女从青梅竹马到送别丈夫远行的情感历程。漫步其间，感受到的不仅是盛唐的市井烟火，更是跨越千年的人间真情。', '江苏', 32.039300, 118.794400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/3f/State_Council_Gazette_-_2019_-_Issue_30.pdf"]'),
('《登金陵雨花台望大江》', '南京市雨花台区雨花台遗址', '高启', '明代', '雨花台遗址位于南京市雨花台区，是明代诗人高启《登金陵雨花台望大江》"大江来从万山中，山势尽与江流东"的创作之地。雨花台地势高敞，保留有明代古碑、摩崖石刻与古寺遗迹。登台远望，长江如银带蜿蜒，钟山紫金色的山峦连绵起伏。高启在此以豪迈笔触描绘了金陵山水的壮阔气势，"我怀郁塞何由开，酒酣走上城南台"的慷慨之情跃然纸上。此处既是明代文学胜地，也是近代革命烈士纪念地，历史层叠，是感受金陵古今风云的重要文化地标。', '江苏', 31.991800, 118.779900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/47/%E5%8D%97%E4%BA%AC%E5%B8%82%E9%9B%A8%E8%8A%B1%E5%8F%B0%E5%8C%BA%E6%A5%9A%E7%BF%98%E5%9F%8E.jpg"]'),
('《桃花庵歌》', '苏州市姑苏区桃花坞唐寅故居遗址', '唐寅', '明代', '桃花坞唐寅故居遗址位于苏州市姑苏区，是唐寅《桃花庵歌》"桃花坞里桃花庵，桃花庵下桃花仙"的诞生之地。唐寅科场案后归隐于此，以诗酒书画自娱，开创了"别人笑我太疯癫，我笑他人看不穿"的旷达人生。遗址保留有明代建筑遗迹、古碑与桃花林，春日桃花绽放时粉霞满园，落英缤纷。故居周围老巷幽深，石桥流水，保留着姑苏古城的原始韵味。漫步其间，能深切感受到这位才子佳人在困境中依然潇洒自如的人生态度与明代文人画的艺术魅力。', '江苏', 31.311400, 120.617400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/81/%E5%AF%85%E6%A2%A62025.jpg"]'),
('《己亥杂诗・其二百二十》', '苏州市昆山市千灯镇顾炎武故居遗址', '龚自珍', '清代', '千灯镇顾炎武故居位于苏州市昆山市，是龚自珍《己亥杂诗》"我劝天公重抖擞，不拘一格降人才"的精神共鸣之地。顾炎武"天下兴亡，匹夫有责"的思想与龚自珍的变革精神一脉相承。故居保留有明清建筑、古碑与藏书楼，庭院幽深，书香弥漫。千灯古镇石板街蜿蜒数里，小桥流水，明清民居错落有致。故居内陈列着顾炎武的著作手稿与生平事迹，展现了这位伟大思想家"经世致用"的学术理念。此处是了解明清之际思想变革与江南学术传统的重要文化遗存。', '江苏', 31.385300, 120.981000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/b/bd/%E5%8D%83%E7%81%AF%E5%8F%A4%E9%95%87%E9%A1%BE%E7%82%8E%E6%AD%A6%E5%A2%932020.jpg"]'),
('《题扬州禅智寺》', '扬州市邗江区禅智寺遗址', '杜牧', '唐代', '禅智寺遗址位于扬州市邗江区，是杜牧《题扬州禅智寺》"雨过一蝉噪，飘萧松桂秋"的描绘之地。禅智寺始建于唐代，曾是扬州重要的佛教寺院。遗址保留有唐代建筑基址、古碑与天然泉眼，泉水甘甜清冽。寺院周围松柏苍翠，桂花飘香，秋雨过后蝉鸣阵阵，与杜牧诗中的意境完美吻合。"暮霭生深树，斜阳下小楼"的幽静氛围至今未改。此处远离扬州主要景区的游客喧嚣，是感受晚唐诗人在扬州寓居时那份清寂孤独与禅意栖息的宁静之地。', '江苏', 32.376900, 119.398000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/cc/Nanhua_Temple_gate.JPG"]'),
('《游金山寺》', '镇江市润州区金山寺慈寿塔遗址', '苏轼', '北宋', '金山寺慈寿塔位于镇江市润州区金山之巅，是苏轼《游金山寺》"宦游直送江入海"的创作之地。金山寺始建于东晋，"寺裹山"的独特布局使整座金山宛如一座浮在江上的佛寺。慈寿塔保留有宋代塔基、古碑与佛像，登塔可俯瞰长江与镇江古城的壮阔全景。苏轼在此夜宿时见"江心似有炬火明"，写下了这首融现实与奇幻于一体的名篇。白蛇传中法海收蛇的传说也发生于此。此处佛教文化、文学典故与长江胜景交融，是镇江最具传奇色彩的文化名胜。', '江苏', 32.195200, 119.411300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/d9/%E5%A4%A7%E5%B8%82%E5%8F%A3%E9%A3%8E%E5%85%89.jpg"]'),
('《淮上与友人别》', '扬州市广陵区扬子津古渡遗址', '郑谷', '唐代', '扬子津古渡遗址位于扬州市广陵区，是郑谷《淮上与友人别》"杨花愁杀渡江人"的送别之地。古渡保留有唐代石砌码头、古碑与古亭，曾是唐代扬州南来北往的重要水路枢纽。渡口两岸杨柳依依，春日柳絮飘飞如雪，"扬子江头杨柳春，杨花愁杀渡江人"的离愁别绪在此处尤为真切。唐代文人常在此处饮酒话别，"数声风笛离亭晚，君向潇湘我向秦"的诗句道尽了天各一方的惆怅。此处古渡周围环境清幽，是感受唐代送别文化与扬州水路历史的宁静之地。', '江苏', 32.394600, 119.431800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/2/2c/Five_Pavilion_Bridge_and_White_Pagoda_2017.jpg"]');
INSERT INTO works (title, scenic_spot, author, dynasty, description, province, latitude, longitude, category, images) VALUES
('《红楼梦》', '南京市玄武区江宁织造府遗址', '曹雪芹', '清代', '江宁织造府遗址位于南京市玄武区，是曹雪芹的出生地，也是《红楼梦》中荣国府的重要原型。曹家在此担任江宁织造长达六十余年，"烈火烹油、鲜花着锦"的家族盛况为曹雪芹日后创作提供了丰富素材。遗址保留有清代建筑基址、古碑与织造作坊遗迹，展示了清代皇家丝织业的精湛工艺。院内假山叠石、亭台楼阁的布局与小说中大观园的描写颇有相似之处。漫步其间，仿佛能窥见那个"贾不假，白玉为堂金作马"的钟鸣鼎食之家，是红学研究与清代文化的重要实物遗存。', '江苏', 32.048600, 118.797400, '其他', '["https://img0.baidu.com/it/u=3624272384,3232331986&fm=253&fmt=auto&app=138&f=JPEG?w=681&h=500"]'),
('《背影》', '南京市浦口区浦口火车站旧址', '朱自清', '现代', '浦口火车站位于南京市浦口区长江北岸，是朱自清散文名篇《背影》中父亲攀爬月台买橘子的真实发生地。火车站建于民国初年，保留有英式风格的候车厅、月台与铁轨，是中国近代铁路建筑的珍贵遗存。站台上的石阶斑驳，月台边缘的栏杆锈迹斑斑，岁月的痕迹无处不在。"他蹒跚地走到铁道边，慢慢探身下去"的画面在此处尤为真切动人。车站周围环境宁静，远离城市喧嚣，老式铁轨延伸至远方，是感受民国风情与父子亲情的独特文化地标。', '江苏', 32.058300, 118.628100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/4f/%E5%8D%97%E4%BA%AC%E5%B8%82%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E7%AC%AC%E4%BA%94%E6%89%B9%E5%B8%82%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E7%9A%84%E9%80%9A%E7%9F%A5.pdf"]'),
('《受戒》', '扬州市高邮市界首镇芦苇荡', '汪曾祺', '现代', '界首镇芦苇荡位于扬州市高邮市，是汪曾祺小说《受戒》中明海与小英子纯真爱情的发生地。芦苇荡连绵数里，水道纵横交错，保留着原始的里下河水乡风貌。古渡口石阶延伸入水，渔船三两只静泊岸边，偶有渔翁撒网捕鱼。春日芦芽初绿，夏日芦花飞扬，秋日金黄一片，冬日白雪覆盖。"英子跳到船上，解开缆绳"的纯真画面仿佛就在眼前。此处远离旅游开发，保留了汪曾祺笔下那个"桃花源"般质朴美好的水乡世界。', '江苏', 32.781500, 119.459300, '其他', '["https://img0.baidu.com/it/u=2863629496,4069278414&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《大淖记事》', '扬州市高邮市大淖河遗址', '汪曾祺', '现代', '大淖河遗址位于扬州市高邮市，是汪曾祺小说《大淖记事》的核心原型地。大淖原为一片开阔水面，周围聚居着渔民、挑夫与手艺人，是高邮最具市井烟火气的地方。遗址保留有明清古码头、老民居与老店铺，青砖灰瓦间弥漫着水乡的潮湿气息。汪曾祺以温润的笔触描绘了大淖人家的日常生活与纯真爱情，"那里的人粗犷而又温柔"。码头石阶上青苔斑驳，老店铺的木质门板散发着岁月的幽香，是体验高邮水乡民俗与汪曾祺文学世界的珍贵之地。', '江苏', 32.781500, 119.459300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/d2/%E5%9F%8E%E9%95%87%E5%8C%96%E5%9C%B0%E5%8C%BA%E7%BB%BC%E5%90%88%E4%BA%A4%E9%80%9A%E7%BD%91%E8%A7%84%E5%88%92.pdf"]'),
('《西游记》', '连云港市海州区花果山水帘洞遗址', '吴承恩', '明代', '花果山水帘洞位于连云港市海州区，是吴承恩《西游记》中孙悟空洞府"花果山福地，水帘洞洞天"的原型所在。水帘洞天然形成于花岗岩崖壁之间，洞口瀑布飞泻如帘，洞内石壁光滑，空间宽敞。山间保留有明代摩崖石刻、古碑与泉眼，"神圣根本洞天" "高山第一仙洞"等题刻清晰可辨。花果山猕猴成群，在山林间嬉戏跳跃，与小说描写高度吻合。登顶可远眺大海，"海外有一国土，名曰傲来国"的神话意境扑面而来。此处是中国四大名著文化体验中最具奇幻色彩的景点。', '江苏', 34.569400, 119.163500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/75/Xiyou.PNG"]'),
('《儒林外史》', '南京市秦淮区秦淮河畔老茶馆遗址', '吴敬梓', '清代', '秦淮河畔老茶馆遗址位于南京市秦淮区，是吴敬梓创作《儒林外史》期间常去的地方。吴敬梓移居南京后，常在秦淮河畔的茶馆中观察世态人情，将科举士子的种种丑态融入笔端。遗址保留有明清茶馆建筑、古碑与老式茶桌，青砖墙面上挂着发黄的对联。秦淮河水缓缓流过窗前，对岸的明清建筑倒映水中，正是"儒林"众生相的真实舞台。茶馆内光线昏暗，老式茶炉上青烟袅袅，仿佛还能看到那些"一个个本该做学问却只知钻营功名"的文人身影。', '江苏', 32.039300, 118.794400, '其他', '["https://img0.baidu.com/it/u=3090291877,1928659151&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《倪焕之》', '苏州市吴江区甪直古镇保圣寺遗址', '叶圣陶', '现代', '甪直古镇保圣寺位于苏州市吴江区，是叶圣陶小说《倪焕之》中主人公任教地的原型。保圣寺始建于梁代，以唐代罗汉塑像闻名于世，泥塑造型生动传神，被誉为"江南雕塑瑰宝"。寺内保留有宋代碑刻与古建筑，古朴庄严。叶圣陶曾在甪直执教数年，对古镇的水乡风情与民众生活有着深刻体验。寺外小桥流水，古镇老街青石铺地，民居粉墙黛瓦，河道纵横交错。此处远离旅游喧嚣，保留了江南水乡古镇最本真的质朴风貌与教育文化传统。', '江苏', 31.159300, 120.645100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/55/A_street_scene_of_Luzhi.jpg"]'),
('《多收了三五斗》', '苏州市吴江区甪直古镇万盛米行遗址', '叶圣陶', '现代', '甪直古镇万盛米行遗址位于苏州市吴江区，是叶圣陶短篇小说《多收了三五斗》的原型地。万盛米行始建于明代，是当年甪直镇上最大的粮食交易场所。遗址保留有明清米行建筑、古碑与传统农具，柜台、米斗、大秤等实物展现了民国时期粮食贸易的真实面貌。叶圣陶通过米行里农民与粮商的价格博弈，揭示了旧中国农村经济的深层矛盾。米行门前的河道上曾停满运粮船只，如今碧水依旧，只是往昔的喧闹已归于宁静，是了解中国近代农村经济史的重要文化遗存。', '江苏', 31.159300, 120.645100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/55/A_street_scene_of_Luzhi.jpg"]'),
('《围城》', '无锡市滨湖区钱钟书故居遗址', '钱钟书', '现代', '钱钟书故居位于无锡市滨湖区，是《围城》作者钱钟书的出生地与少年成长地。故居为清代江南传统民居，粉墙黛瓦，庭院幽深，保留有钱钟书幼年读书的书房、家族藏书楼与古碑。院内老井苔藓斑驳，天井中一株百年桂花树枝繁叶茂。钱钟书在此度过了求知若渴的少年时光，"书架上的灰尘比书还多"的幽默气质或许就源于这座充满书香的庭院。故居周围老巷幽静，远离无锡城区的现代喧嚣，是感受一代学术大师成长环境与民国知识分子家庭氛围的珍贵之地。', '江苏', 31.527900, 120.285800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e7/%E6%97%A0%E9%94%A1%E4%B8%89%E9%98%B3%E5%B9%BF%E5%9C%BA.jpg"]'),
('《洗澡》', '南京市玄武区东南大学老校区遗址', '杨绛', '现代', '东南大学老校区位于南京市玄武区，是杨绛小说《洗澡》中描绘知识分子精神洗礼的重要背景地。校区保留有民国时期的教学楼、老图书馆与参天古樟树，红砖建筑典雅庄重，梧桐大道浓荫蔽日。杨绛以细腻冷静的笔触描写了知识分子在特殊年代的思想改造历程，"洗澡"即精神上的自我革新。漫步在古朴的校园中，老式路灯、斑驳的墙面与悠长的走廊仿佛还回荡着那个年代的辩论声。此处是感受民国大学氛围与中国现代知识分子精神历程的独特文化空间。', '江苏', 32.048600, 118.797400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/f/fc/Xuanwulake_willows.jpg"]'),
('《林家铺子》', '苏州市吴江区震泽古镇林家铺子遗址', '茅盾', '现代', '震泽古镇林家铺子遗址位于苏州市吴江区，是茅盾小说《林家铺子》的原型地之一。遗址保留有明清商铺建筑、古碑与老式柜台，木质门板散发着岁月的幽香。茅盾笔下林家铺子的困境——大商家挤压、洋货冲击、苛捐杂税，正是中国近代小商人命运的缩影。铺面不大，货架整齐，账本泛黄，再现了民国时期江南小镇商业的真实面貌。古镇水巷幽深，石桥横跨，蚕丝文化源远流长。此处远离旅游热点，是了解中国近代民族工商业兴衰与江南蚕桑文化的安静之地。', '江苏', 31.159300, 120.645100, '其他', '["https://img0.baidu.com/it/u=611881308,69536227&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1739"]'),
('《妻妾成群》', '扬州市广陵区个园四季假山遗址', '苏童', '现代', '个园四季假山位于扬州市广陵区，是苏童小说《妻妾成群》中陈家大院的重要原型之一。个园以竹闻名，"竹"字一半即为"个"，园中四季假山用不同石料叠成春夏秋冬四景，构思精妙绝伦。苏童笔下深宅大院中妻妾们的明争暗斗，与个园层层递进的院落空间形成了隐喻式的对应。清代古民居高墙深院，天井中光影变幻，廊道幽暗曲折。假山间的洞穴与小径仿佛暗藏着旧时代女性的无声叹息。此处是感受清代扬州盐商奢华生活与苏童文学世界的独特园林空间。', '江苏', 32.394600, 119.431800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/87/Bamb_Garden_in_Yangzhou.JPG"]'),
('《黄雀记》', '南京市秦淮区老门东遗址', '苏童', '现代', '老门东遗址位于南京市秦淮区中华门以东，是苏童小说《黄雀记》的核心背景地。老门东保留有明清古民居、幽深老巷与古码头，青石板路蜿蜒曲折，两侧高墙窄巷投射出斑驳的光影。苏童以冷峻笔触描绘了"香椿树街"上几个年轻人纠缠半生的命运，而老门东的巷陌深处正是这些故事的原型舞台。老式门楼、石库门、天井院落保存完好，岁月在墙壁上留下了层层叠叠的痕迹。此处虽经修缮，但仍保留着老南京的市井肌理与生活气息，是体验苏童小说中南京底层叙事的真实场域。', '江苏', 32.039300, 118.794400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/4f/%E5%8D%97%E4%BA%AC%E5%B8%82%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E7%AC%AC%E4%BA%94%E6%89%B9%E5%B8%82%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E7%9A%84%E9%80%9A%E7%9F%A5.pdf"]'),
('《推拿》', '南京市鼓楼区盲人按摩一条街遗址', '毕飞宇', '现代', '盲人按摩一条街位于南京市鼓楼区，是毕飞宇小说《推拿》的核心原型地。毕飞宇以极其细腻的笔触描绘了盲人推拿师们的日常生活、情感世界与精神追求。老街保留有小型店铺、幽深古巷与民国民居，店内灯光柔和，按摩床整齐排列。"在黑暗中寻找光明"是小说的精神主题，也是这条街上每一位推拿师的真实人生写照。街巷狭窄幽静，远离繁华商圈的喧嚣，保留着老南京的市井温度。此处是了解中国当代底层叙事文学与感受特殊群体生命尊严的独特文化空间。', '江苏', 32.066600, 118.769700, '其他', '["https://img2.baidu.com/it/u=2137685946,562470740&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=589"]'),
('《玉米》', '扬州市宝应县射阳湖镇遗址', '毕飞宇', '现代', '射阳湖镇位于扬州市宝应县，是毕飞宇小说《玉米》的核心原型地。小说以苏北平原上的乡村为背景，描绘了玉米、玉秀、玉秧三姐妹在时代洪流中的命运沉浮。遗址保留有明清古民居、老码头与广袤的稻田，大运河支流从镇中缓缓流过。射阳湖水域开阔，芦苇丛生，白鹭翩飞，保留了里下河地区最原始的水乡田园风貌。砖墙瓦舍、泥路阡陌、晒场稻垛构成了苏北乡村的典型画面。此处远离旅游开发，是体验毕飞宇笔下苏北农村质朴生活与女性命运抗争的真实之地。', '江苏', 33.240300, 119.309300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/a/a9/Verticle_Table_Garden_Conidor.jpg"]'),
('《水经注・江水注》', '扬州市邗江区瓜洲古渡遗址', '郦道元', '北魏', '瓜洲古渡遗址位于扬州市邗江区长江北岸，是郦道元《水经注·江水注》中重点记载的长江古渡口。瓜洲自晋代以来便是长江南北交通的咽喉要地，历经千年沧桑。遗址保留有晋代至明清各时期的码头遗迹、古碑与闸坝结构，层层叠压的地层记录了古渡口的演变历程。"汴水流，泗水流，流到瓜洲古渡头"的词句道尽了此处作为水路枢纽的重要地位。渡口江面开阔，水流湍急，对岸镇江金山寺隐约可见。此处是研究中国古代水运交通史与长江地理变迁的珍贵实物遗存。', '江苏', 32.376900, 119.398000, '其他', '["https://img1.baidu.com/it/u=1419664587,3201714674&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=652"]'),
('《游太湖记》', '无锡市滨湖区鼋头渚鹿顶山遗址', '徐霞客', '明代', '鼋头渚鹿顶山位于无锡市滨湖区太湖之畔，是徐霞客游记中"太湖佳绝处，毕竟在鼋头"的源头之地。鹿顶山保留有明代摩崖石刻与古亭，登顶可三面环望太湖，湖水浩渺无际，远处岛屿若隐若现。春日樱花烂漫时，粉白花瓣随风飘入太湖，美不胜收；秋日天高云淡，湖面波光粼粼，渔帆点点。徐霞客当年从此处眺望太湖全貌，留下了对太湖风光的最高赞誉。此处虽为著名景区，但鹿顶山顶部游客稀少，是静观太湖日出日落的最佳高点。', '江苏', 31.527900, 120.285800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/a/ac/Wuxi_Taihu_lake_Changchun_bridge.jpg"]'),
('《项脊轩志》', '苏州市昆山市震川园项脊轩遗址', '归有光', '明代', '震川园项脊轩遗址位于苏州市昆山市，是明代散文家归有光《项脊轩志》的创作之地。"项脊轩，旧南阁子也，室仅方丈"，归有光在此苦读成才，也在此经历了祖母、母亲与妻子的生离死别。遗址保留有明代建筑、古碑与庭院，庭中"枇杷树，吾妻死之年所手植也，今已亭亭如盖矣"的感伤至今读来令人泪目。小轩幽暗，阳光透过窗棂洒在书案上，斑驳的光影仿佛诉说着四百年前的人间真情。此处是感受明代散文至情至性之美与昆山人文传统的珍贵文化遗存。', '江苏', 31.385300, 120.981000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/14/Gui_Youguang.jpg"]'),
('《沧浪亭记》', '苏州市姑苏区沧浪亭遗址', '苏舜钦', '北宋', '沧浪亭位于苏州市姑苏区，是北宋诗人苏舜钦《沧浪亭记》的创作之地，也是苏州现存最古老的园林。苏舜钦被贬后以四万钱购得此园，取"沧浪之水清兮可以濯我缨"之意命名。园内以竹林、假山与流水为主景，竹径通幽，古木参天。宋代碑刻嵌于回廊之中，记载了历代文人的雅集轶事。"清风明月本无价，近水远山皆有情"的楹联道尽了文人隐逸的审美理想。此处是苏州园林中最具文人气质的一座，游客远少于拙政园与留园，是感受宋代文人园林美学的清幽之地。', '江苏', 31.311400, 120.617400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/8f/%E4%B8%9C%E6%96%B9%E4%B9%8B%E9%97%A81.jpg"]'),
('《拙政园记》', '苏州市姑苏区拙政园兰雪堂遗址', '文徵明', '明代', '拙政园兰雪堂位于苏州市姑苏区，是文徵明在《拙政园记》中重点描绘的景点。拙政园始建于明代正德年间，兰雪堂为园中第一厅，堂名取自李白"独立天地间，清风洒兰雪"之意。堂内保留有明代建筑构件、古碑与一幅描绘全园景致的巨型漆雕。文徵明以画入园，将其绘画美学融入园林设计，使拙政园成为中国文人写意山水园林的巅峰之作。兰雪堂前水面开阔，荷叶田田，远处亭台楼阁错落有致，"虽由人作，宛自天开"的造园理念在此得到完美体现。', '江苏', 31.311400, 120.617400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/2/27/Humble_Administrator%27s_Garden_Suzhou_November_2017_008.jpg"]'),
('《扬州画舫录》', '扬州市广陵区东关街北段遗址', '李斗', '清代', '东关街北段位于扬州市广陵区，是李斗《扬州画舫录》中重点记载的明清扬州商业核心街区。东关街自唐代以来便是扬州最繁华的商业中心，盐商巨贾、文人墨客云集于此。北段保留有明清古民居、老字号店铺与古码头，青石板路光滑如镜，两侧建筑飞檐翘角。"十里长街市井连"的盛况虽已远去，但老店铺的牌匾、木质柜台与斑驳墙面仍诉说着扬州"腰缠十万贯，骑鹤上扬州"的往昔繁华。此处是感受清代扬州盐商文化与市井风情的最佳历史街区。', '江苏', 32.394600, 119.431800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/d2/%E5%9F%8E%E9%95%87%E5%8C%96%E5%9C%B0%E5%8C%BA%E7%BB%BC%E5%90%88%E4%BA%A4%E9%80%9A%E7%BD%91%E8%A7%84%E5%88%92.pdf"]'),
('《陶庵梦忆・金山夜戏》', '镇江市润州区金山寺藏经楼遗址', '张岱', '明代', '金山寺藏经楼位于镇江市润州区金山之上，是张岱《陶庵梦忆·金山夜戏》中描绘的核心场景地。张岱深夜乘船至金山寺，于藏经楼前演出昆曲，"锣鼓喧天，一寺皆惊"的奇异经历成为明末文人风雅的绝妙缩影。藏经楼保留有明代建筑遗迹、古碑与珍贵佛经。楼阁高耸于金山之巅，夜色中灯火辉映长江，"月光倒囊入水，江涛吞吐"的奇幻意境令人神往。此处白天游客众多，但若能如张岱般月夜造访，便能体验到明代文人"痴人说梦"般的浪漫与风雅。', '江苏', 32.195200, 119.411300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/d9/%E5%A4%A7%E5%B8%82%E5%8F%A3%E9%A3%8E%E5%85%89.jpg"]'),
('《钟山》', '南京市玄武区明孝陵石象路遗址', '张岱', '明代', '明孝陵石象路位于南京市玄武区钟山南麓，是张岱《钟山》中重点描绘的景点。石象路是明孝陵神道的精华段落，路两侧依次排列着石象、石骆驼、石马、石麒麟等十二对石刻，体量巨大，雕工精湛，展现了明代皇家陵寝的恢宏气势。石刻历经六百余年风雨依然完好，苔藓斑驳，古朴庄严。深秋时节，道旁银杏、枫树、乌桕等色叶树种交替变色，金黄、火红、暗紫层层叠叠，形成南京最美的秋色走廊。此处是感受明代帝王气象与金陵秋韵的绝佳之地。', '江苏', 32.048600, 118.797400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/74/%E7%BB%9F%E8%AE%A1%E7%94%A8%E5%8C%BA%E5%88%92%E4%BB%A3%E7%A0%81%E5%92%8C%E5%9F%8E%E4%B9%A1%E5%88%92%E5%88%86%E4%BB%A3%E7%A0%81_%E6%B1%9F%E8%8B%8F.pdf"]'),
('《老残游记》', '扬州市邗江区大明寺平山堂遗址', '刘鹗', '清代', '大明寺平山堂位于扬州市邗江区蜀冈之上，是刘鹗《老残游记》中重点描绘的扬州名胜。平山堂为北宋欧阳修任扬州知府时所建，"远山来与此堂平"的意境至今犹存。堂内保留有宋代建筑风格、古碑与苍劲古柏，登临远眺，江南诸山如屏风般横列于前，大运河蜿蜒如带。春日满目翠绿，秋日天高云淡，"春风阁上春风起，春日栏杆春日低"的诗意盎然。此处虽位于大明寺景区内，但平山堂后部的谷林堂等区域游客稀少，是感受宋代文人政治家风范的清幽之地。', '江苏', 32.376900, 119.398000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/2/2c/Five_Pavilion_Bridge_and_White_Pagoda_2017.jpg"]'),
('《孽海花》', '苏州市姑苏区寒山寺钟楼遗址', '曾朴', '清代', '寒山寺钟楼位于苏州市姑苏区，是曾朴小说《孽海花》中多次描绘的景点。寒山寺因张继"姑苏城外寒山寺，夜半钟声到客船"而名扬天下，钟楼中悬挂的铜钟更是苏州的文化象征。钟楼保留有唐代钟基、古碑与巨型铜钟，每逢除夕夜寒山寺敲钟一百零八下，祈福迎新。曾朴在《孽海花》中以寒山寺为背景，描绘了晚清社会的光怪陆离。钟声悠远深沉，穿越运河上的雾气回荡在姑苏古城上空。此处是感受唐诗意境与苏州千年佛教文化的标志性名胜。', '江苏', 31.311400, 120.617400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/8f/%E4%B8%9C%E6%96%B9%E4%B9%8B%E9%97%A81.jpg"]'),
('《官场现形记》', '南京市秦淮区江南贡院号舍遗址', '李宝嘉', '清代', '江南贡院号舍遗址位于南京市秦淮区秦淮河畔，是李宝嘉《官场现形记》中重点描绘的科举考场。江南贡院始建于宋代，至清代成为中国最大的科举考场，号舍多达两万余间。遗址保留有明代考棚、古碑与桌椅，狭小的号舍仅容一人坐卧，考生需在此度过数日完成科举考试。李宝嘉以辛辣笔触描绘了官场的贪腐丑态，而这些号舍正是无数文人"十年寒窗"梦想的起点与终点。此处是了解中国科举制度千年兴衰与晚清社会风貌的重要历史遗存。', '江苏', 32.039300, 118.794400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/8d/%E4%B8%AD%E6%96%87%E7%BB%B4%E5%9F%BA%E7%99%BE%E7%A7%91%E6%9C%88%E5%88%8A%E7%AC%AC%E5%8D%81%E6%9C%9F%EF%BC%88%E7%AE%80%E4%BD%93%E7%89%88%EF%BC%89.pdf"]'),
('《铁道游击队》', '徐州市贾汪区微山湖铁道游击队旧址', '刘知侠', '现代', '微山湖铁道游击队旧址位于江苏省徐州市贾汪区（紧邻山东微山湖），是刘知侠小说《铁道游击队》的核心背景地。抗日战争期间，铁道游击队活跃于津浦铁路沿线与微山湖区域，以游击战术打击日寇。旧址保留有抗日指挥部、古码头与连绵芦苇荡，芦苇荡内水道纵横，曾是游击队员隐蔽转移的天然屏障。"西边的太阳快要落山了，微山湖上静悄悄"的歌声至今回荡。此处是缅怀抗日英雄、了解敌后游击战争历史的重要红色教育基地。', '江苏', 34.435500, 117.449900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e7/%E6%97%A0%E9%94%A1%E4%B8%89%E9%98%B3%E5%B9%BF%E5%9C%BA.jpg"]'),
('《红日》', '连云港市赣榆区抗日山烈士陵园', '吴强', '现代', '抗日山烈士陵园位于连云港市赣榆区，是吴强小说《红日》的核心背景地之一。陵园依山而建，安葬着数千名在抗日战争与解放战争中牺牲的烈士。山上保留有烈士墓群、纪念碑与纪念馆，记录了苏北鲁南地区军民浴血奋战的英勇事迹。吴强在《红日》中以磅礴气势描绘了孟良崮战役等经典战斗，而抗日山的烈士正是这些战斗的真实参与者。松柏苍翠，庄严肃穆，登上山顶可远眺大海与平原。此处是接受革命传统教育、缅怀先烈英魂的重要红色文化圣地。', '江苏', 34.841300, 119.173100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/53/Gan-Yu_Old_Town.jpg"]'),
('《草房子》', '盐城市盐都区秦南镇草房子乐园', '曹文轩', '现代', '草房子乐园位于盐城市盐都区秦南镇，是曹文轩小说《草房子》中桑桑、纸月、秃鹤等少年故事的发生地。乐园按照小说场景复原了茅草屋、老学校与金色稻田，再现了苏北水乡少年的纯真岁月。茅草屋顶在阳光下闪着金色光芒，教室里的木质课桌排列整齐，操场上的旗杆孤独矗立。周围大片稻田随风起伏如金色海浪，河道中野鸭戏水，芦苇丛中蜻蜓纷飞。此处完美呈现了曹文轩笔下"油麻地"的诗意与忧伤，是感受中国乡村少年文学之美的独特体验地。', '江苏', 33.338700, 120.153800, '其他', '["https://img1.baidu.com/it/u=3708628125,1501540596&fm=253&fmt=auto&app=138&f=JPEG?w=914&h=500"]'),
('《浮生六记》', '苏州市姑苏区沧浪亭遗址', '沈复', '清代', '沧浪亭位于苏州市姑苏区，是沈复《浮生六记》中与妻子芸娘常游之地。沈复在书中深情回忆了夫妻二人"布衣蔬食"却琴瑟和谐的日常生活，而沧浪亭正是他们最钟爱的散步之所。清代园林保留完好，竹林幽深，古碑遍布回廊。"沧浪之水清兮"的隐逸意境与沈复芸娘"闲中趣味"的生活美学完美交融。园内竹影婆娑，花窗透景，石径蜿蜒，处处体现着清代苏州文人的雅致品味。此处是感受《浮生六记》中"人间烟火与诗意栖居"完美结合的最佳之地。', '江苏', 31.311400, 120.617400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/8f/%E4%B8%9C%E6%96%B9%E4%B9%8B%E9%97%A81.jpg"]'),
('《咏柳》', '杭州市萧山区贺知章故里柳园', '贺知章', '唐代', '贺知章故里柳园位于杭州市萧山区，是唐代诗人贺知章《咏柳》"碧玉妆成一树高，万条垂下绿丝绦"的创作原型地。园内保留有唐代古柳数株，枝条低垂如丝，春风拂过时随风摇曳，宛如诗中描绘的绿色丝带。贺知章祠堂庄严古朴，古碑记载着这位"四明狂客"的传奇生平。柳园水系环绕，亭台掩映于柳荫之中，"不知细叶谁裁出，二月春风似剪刀"的奇思妙想在此处得到最生动的注解。此处游客稀少，是感受唐诗天真烂漫之美与越地文人风骨的清幽之地。', '浙江', 30.183100, 120.264200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/17/West_Lake%2C_Hangzhou_2025.jpg"]'),
('《回乡偶书二首・其一》', '杭州市萧山区贺知章故里鉴湖古渡', '贺知章', '唐代', '鉴湖古渡位于杭州市萧山区贺知章故里，是贺知章晚年回乡登岸之处，也是《回乡偶书》"少小离家老大回，乡音无改鬓毛衰"的诞生地。古渡保留有唐代石砌码头，石阶斑驳苔藓丛生，诉说着一千三百年前那位八旬老人的归乡之路。鉴湖水波潋滟，远山如黛，渡口两岸垂柳依依。"儿童相见不相识，笑问客从何处来"的场景至今读来令人动容。此处远离城市喧嚣，保留了越地水乡的原始风貌，是体验唐诗中最朴素乡愁情感的真实历史现场。', '浙江', 30.183100, 120.264200, '其他', '["https://img2.baidu.com/it/u=1715148448,1729733461&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1778"]'),
('《梦游天姥吟留别》', '绍兴市新昌县天姥山太白梦游处遗址', '李白', '唐代', '天姥山位于绍兴市新昌县，是李白《梦游天姥吟留别》"势拔五岳掩赤城"的创作灵感地。天姥山虽非名山大川，却因李白的瑰丽想象而名震文坛。"半壁见海日，空中闻天鸡"的奇幻意境至今吸引着无数文学爱好者前来朝圣。山间保留有唐代摩崖石刻，记录了历代诗人追寻李白足迹的感悟。古驿道蜿蜒于山林之间，云雾缭绕时山峰若隐若现，恰似梦中仙境。此处开发程度极低，保留了浙东山水的原始质朴，是感受盛唐浪漫主义诗歌精神的最佳自然课堂。', '浙江', 29.499700, 120.903700, '其他', '["https://img1.baidu.com/it/u=985728774,4052194927&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1068"]'),
('《早发白帝城》', '杭州市富阳区鹳山古渡', '李白', '唐代', '鹳山古渡位于杭州市富阳区富春江畔，相传李白出蜀东下时曾途经此地，"千里江陵一日还"的豪迈之情在此升腾。古渡保留有唐代石砌码头与李白雕像，江面开阔，水流湍急，远处青山如画。富春江在此处形成优美的弯道，两岸翠竹苍翠，渔舟点点。"朝辞白帝彩云间，千里江陵一日还"的畅快之感在此处尤为应景。古渡周围环境清幽，春日江花似火，秋日江水碧澄，是感受唐诗中"轻舟已过万重山"的豁达心境与富春江山水之美的宁静之地。', '浙江', 30.048500, 119.960300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/a/aa/Shouxiang_Memorial_Hall_-_Court_of_the_Entrance.jpg"]'),
('《饮湖上初晴后雨二首・其二》', '杭州市西湖区西湖孤山放鹤亭遗址', '苏轼', '北宋', '西湖孤山放鹤亭位于杭州市西湖区，是苏轼《饮湖上初晴后雨》"欲把西湖比西子，淡妆浓抹总相宜"的最佳观景点。孤山三面环湖，独处于西湖之中，放鹤亭保留有宋代亭基、古碑与梅林。站在亭中远眺，西湖水光潋滟、山色空蒙的美景尽收眼底，晴日湖面如镜，雨后烟岚笼罩，恰如苏轼诗中所写。亭旁梅花冬日绽放，暗香浮动，正是林和靖"梅妻鹤子"的隐居之地。此处是西湖景区中最具文人气质的角落，是同时体验苏轼诗意与宋代隐逸文化的绝佳之地。', '浙江', 30.259200, 120.129900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/West_Lake%2C_Hangzhou_2025.jpg/1280px-West_Lake%2C_Hangzhou_2025.jpg"]'),
('《题西林壁》', '杭州市临安区天目山开山老殿遗址', '苏轼', '北宋', '天目山开山老殿位于杭州市临安区天目山上，相传为苏轼《题西林壁》"不识庐山真面目，只缘身在此山中"的创作地之一。开山老殿始建于唐代，是天目山最古老的佛教建筑。殿旁保留有宋代建筑基址、古碑与千年古银杏，树冠如盖，金秋时节满地金黄。天目山以原始森林著称，古木参天，藤蔓缠绕，"大树华盖闻九州"的美誉名不虚传。山中云雾变幻莫测，"横看成岭侧成峰"的哲理在此处得到最直观的体现。此处游客远少于莫干山，是感受浙西山林禅意与宋诗哲思的幽静胜地。', '浙江', 30.233900, 119.724800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/0/0c/Main_gate_of_Jingshan_Temple_1.jpg"]'),
('《示儿》', '绍兴市越城区陆游故居遗址', '陆游', '南宋', '陆游故居位于绍兴市越城区，是南宋爱国诗人陆游写下绝笔《示儿》"王师北定中原日，家祭无忘告乃翁"的终老之地。故居保留有宋代建筑基址与古碑，记载着陆游八十五年波澜壮阔的人生。陆游一生主张北伐抗金，却屡遭排斥，最终在这座故居中抱憾而终。故居周围水巷幽深，石桥横跨，保留了宋代绍兴的城市肌理。"死去元知万事空，但悲不见九州同"的悲壮情怀至今令人潸然泪下。此处是了解南宋爱国诗人壮志未酬之人生悲剧与绍兴古城历史的重要文化遗存。', '浙江', 29.988500, 120.575300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/b/ba/Shen_Garden_in_Shaoxing_2012-07.JPG"]'),
('《钗头凤・红酥手》', '绍兴市越城区沈园钗头凤碑遗址', '陆游', '南宋', '沈园位于绍兴市越城区，是陆游与前妻唐琬重逢并写下《钗头凤》"红酥手，黄縢酒，满城春色宫墙柳"的伤心之地。沈园保留有宋代碑刻，陆游手书的《钗头凤》刻于古壁之上，字迹苍凉悲怆。园中古亭临水而建，垂柳依依，荷花映日。陆游与唐琬"错错错""莫莫莫"的爱情悲剧是中国文学史上最动人的篇章之一。每年春日，沈园桃花灼灼、柳絮飘飞，"春如旧，人空瘦，泪痕红浥鲛绡透"的哀婉之情弥漫在园中的每一个角落，是感受宋词至情至性之美的绝佳之地。', '浙江', 29.988500, 120.575300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/b/ba/Shen_Garden_in_Shaoxing_2012-07.JPG"]'),
('《十一月四日风雨大作二首・其二》', '绍兴市越城区陆游故居听雨轩遗址', '陆游', '南宋', '陆游故居听雨轩位于绍兴市越城区，是陆游晚年在风雨之夜写下《十一月四日风雨大作》"夜阑卧听风吹雨，铁马冰河入梦来"的创作之地。听雨轩保留有宋代建筑基址，轩前芭蕉修竹，雨打屋瓦的声音清脆入耳。陆游晚年贫病交加，却仍梦想着金戈铁马、北伐中原的壮志豪情。深秋的绍兴阴雨连绵，卧听风雨之声，仿佛能穿越时空感受到那位八旬老人"僵卧孤村不自哀，尚思为国戍轮台"的赤子之心。此处是体验南宋爱国诗人晚年心境的最具感染力的历史现场。', '浙江', 29.988500, 120.575300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e7/Salt_Museum_in_Zigong.jpg"]'),
('《声声慢・寻寻觅觅》', '金华市婺城区李清照故居遗址', '李清照', '南宋', '李清照故居位于金华市婺城区，是南宋女词人李清照晚年流寓金华时的居所，也是《声声慢》"寻寻觅觅，冷冷清清，凄凄惨惨戚戚"的创作之地。故居保留有宋代建筑基址，庭院幽深，秋风萧瑟。李清照在此度过了人生最孤独的岁月——丈夫亡故、珍藏散失、颠沛流离。"满地黄花堆积，憔悴损，如今有谁堪摘"的凄凉意境在深秋时节尤为真切。故居周围老巷幽静，溪水潺潺，保留了宋代金华古城的生活气息。此处是感受婉约词巅峰之作与一代才女命运悲剧的重要文化遗址。', '浙江', 29.087200, 119.571200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e3/Bayonglou_7758.jpg"]'),
('《题临安邸》', '杭州市上城区南宋皇城遗址', '林升', '南宋', '南宋皇城遗址位于杭州市上城区凤凰山脚下，是林升《题临安邸》"山外青山楼外楼，西湖歌舞几时休"的描绘之地。遗址保留有宋代夯土城墙与宫殿基址，曾是南宋偏安一隅的政治中心。"暖风熏得游人醉，直把杭州作汴州"的辛辣讽刺至今振聋发聩。城墙遗址上荒草萋萋，宫殿基址只余夯土残痕，昔日"东南形胜"的煊赫已化为历史尘埃。周围山色青翠，西湖烟波依旧，"几时休"的追问仿佛穿越八百年回荡在这片土地上。此处是反思南宋历史与感受忧国诗人拳拳之心的重要遗址。', '浙江', 30.242300, 120.169400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/6/6a/%E6%B5%99%E6%B1%9F%E7%9C%81%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E7%AC%AC%E4%B8%83%E6%89%B9%E7%9C%81%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E7%9A%84%E9%80%9A%E7%9F%A5.pdf"]'),
('《晓出净慈寺送林子方》', '杭州市西湖区净慈寺南屏晚钟遗址', '杨万里', '南宋', '净慈寺南屏晚钟位于杭州市西湖区南屏山麓，是杨万里《晓出净慈寺送林子方》"毕竟西湖六月中，风光不与四时同"的创作之地。净慈寺始建于五代，南屏晚钟为西湖十景之一。寺内保留有宋代钟基、古碑与荷花池，六月荷花盛开时"接天莲叶无穷碧，映日荷花别样红"的壮丽景象在此完美呈现。清晨从寺门出发，荷花带着露珠在朝阳下绽放，粉红与碧绿交织成一幅天然画卷。暮色降临时钟声回荡在南屏山间，余音袅袅，是同时体验宋诗写景之精与西湖佛寺文化的经典之地。', '浙江', 30.259200, 120.129900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/West_Lake%2C_Hangzhou_2025.jpg/1280px-West_Lake%2C_Hangzhou_2025.jpg"]'),
('《宿建德江》', '杭州市建德市建德江古渡', '孟浩然', '唐代', '建德江古渡位于杭州市建德市新安江畔，是孟浩然《宿建德江》"野旷天低树，江清月近人"的创作之地。古渡保留有唐代石砌码头、古碑与老渡船，新安江水清澈见底，号称"天下第一秀水"。入夜后江面宁静如镜，明月倒映水中，仿佛触手可及，与诗中"江清月近人"的意境完美吻合。两岸青山叠翠，白雾在江面缓缓升腾，"移舟泊烟渚，日暮客愁新"的羁旅愁思在此处尤为动人。此处远离旅游热点，保留了新安江最原始的自然风貌，是体验唐诗山水意境的绝佳之地。', '浙江', 29.474800, 119.281600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/76/%E6%A2%85%E5%9F%8E%E5%8D%97%E5%B3%B0%E5%A1%94_01.jpg"]'),
('《过故人庄》', '杭州市桐庐县富春江镇严子陵钓台遗址', '孟浩然', '唐代', '严子陵钓台位于杭州市桐庐县富春江畔，相传也是孟浩然《过故人庄》原型地之一。钓台为东汉隐士严子陵垂钓之所，山石嶙峋，古亭凌空。唐代摩崖石刻遍布崖壁，记录了历代文人登临的感悟。"开轩面场圃，把酒话桑麻"的田园意境在此处的山水之间自然流露。富春江水碧绿如玉，两岸翠竹成林，渔舟点点穿行于山峡之间。登上钓台远眺，"绿水逶迤去，青山相向开"的壮美景象尽收眼底。此处是感受东汉隐逸文化、唐诗田园情怀与富春江山水之美的综合性文化胜地。', '浙江', 29.793400, 119.691400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/5f/201806_Tonglu%2C_Hangzhou.jpg"]'),
('《渔翁》', '杭州市富阳区富春江七里泷遗址', '柳宗元', '唐代', '富春江七里泷位于杭州市富阳区至桐庐段，是柳宗元《渔翁》"欸乃一声山水绿"的描绘之地。七里泷峡谷幽深，两岸山峰壁立，江水碧绿如翡翠。唐代古渡石阶延伸入水，摩崖石刻散布于崖壁之间，记录了千年来文人舟行至此的赞叹。"渔翁夜傍西岩宿，晓汲清湘燃楚竹"的原始渔耕生活至今可见，渔翁驾扁舟穿行于峡谷之中，桨声回荡在山谷。古寺隐于山林深处，钟声悠远。此处是富春江最幽静的段落，保留了唐诗中"烟销日出不见人，欸乃一声山水绿"的纯净意境。', '浙江', 30.048500, 119.960300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/0/0d/Qiantang_River_Bridge_DJI_0575_%282%29.jpg"]'),
('《望海潮・东南形胜》', '杭州市上城区钱塘江大潮观潮台遗址', '柳永', '北宋', '钱塘江观潮台遗址位于杭州市上城区，是柳永《望海潮》"三秋桂子，十里荷花"的描绘之地。钱塘江大潮天下闻名，每年八月十八潮水最为壮观，白浪排空，声如雷鸣。遗址保留有宋代观潮台基址与古碑，记载了历代帝王将相、文人墨客观潮的盛况。柳永以华丽笔触描绘了杭州"东南形胜，三吴都会"的繁华景象，相传金主完颜亮读后起了"投鞭断流"的南侵之心。站在古台基上感受钱塘潮涌的磅礴气势，"怒涛卷霜雪，天堑无涯"的壮观令人心潮澎湃。', '浙江', 30.242300, 120.169400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/0/0d/Qiantang_River_Bridge_DJI_0575_%282%29.jpg"]'),
('《八声甘州・对潇潇暮雨洒江天》', '杭州市富阳区鹳山望江亭遗址', '柳永', '北宋', '鹳山望江亭遗址位于杭州市富阳区富春江畔，是柳永《八声甘州》"对潇潇暮雨洒江天，一番洗清秋"的创作之地。亭基保留有宋代遗迹与古碑，登亭远眺可见富春江蜿蜒东去，两岸青山如屏。"残照当楼"的苍凉意境在夕阳西下时尤为动人，金色余晖洒在江面上，波光粼粼。柳永在此以深沉笔触抒发了"误几回天际识归舟"的羁旅乡愁。亭旁古柏苍劲，枝干虬曲，历经千年风雨。此处远离热门景区，是感受宋词婉约之美与富春江暮秋景色的清幽所在。', '浙江', 30.048500, 119.960300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/89/Guan_Hill_in_Fuyang_01_2015-05.JPG"]'),
('《登飞来峰》', '杭州市西湖区飞来峰千寻塔遗址', '王安石', '北宋', '飞来峰位于杭州市西湖区灵隐寺前，是王安石《登飞来峰》"不畏浮云遮望眼，自缘身在最高层"的创作之地。飞来峰怪石嶙峋，石壁上保留有五代至宋代的摩崖造像数百尊，造型精美绝伦。宋代塔基与古碑散布于山间，记录了这座"武林山"的千年传奇。登上峰顶，西湖群山尽收眼底，"飞来山上千寻塔，闻说鸡鸣见日升"的壮阔意境真实可感。此处虽紧邻灵隐寺景区，但飞来峰的高处游客稀少，是体验王安石改革家胸襟与西湖山水气象的独特高点。', '浙江', 30.259200, 120.129900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/West_Lake%2C_Hangzhou_2025.jpg/1280px-West_Lake%2C_Hangzhou_2025.jpg"]'),
('《书愤五首・其一》', '绍兴市越城区陆游故居书愤亭遗址', '陆游', '南宋', '陆游故居书愤亭遗址位于绍兴市越城区，是陆游写下《书愤》"楼船夜雪瓜洲渡，铁马秋风大散关"的创作之地。亭基保留有宋代遗迹，陆游在此追忆当年从军抗金的壮烈岁月。"早岁那知世事艰，中原北望气如山"的豪迈之气与"出师一表真名世，千载谁堪伯仲间"的壮志未酬之叹交织于此。亭旁水巷幽深，石桥古朴，绍兴老城的市井烟火与诗人的家国情怀形成了鲜明对比。此处是深入了解陆游从意气风发到壮志成空的人生转折与南宋爱国词章的重要文化遗址。', '浙江', 29.988500, 120.575300, '其他', '["https://img2.baidu.com/it/u=3486625018,2490991757&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《临安春雨初霁》', '杭州市上城区南宋御街北段遗址', '陆游', '南宋', '南宋御街北段位于杭州市上城区，是陆游《临安春雨初霁》"小楼一夜听春雨，深巷明朝卖杏花"的描绘之地。御街保留有宋代石板路、古民居与古商铺，是南宋临安城最繁华的中轴线。春雨过后，石板路上水光潋滟，老巷深处传来卖花声，与诗中意境完美吻合。陆游虽在此写下了看似闲适的诗句，实则"世味年来薄似纱"的失意与"矮纸斜行闲作草"的消沉充满了政治壮志难酬的苦闷。此处是感受南宋临安城市井风情与陆游内心矛盾的独特历史街区。', '浙江', 30.242300, 120.169400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/f/ff/Linping_Theater.jpg"]');
INSERT INTO works (title, scenic_spot, author, dynasty, description, province, latitude, longitude, category, images) VALUES
('《题龙阳县青草湖》', '嘉兴市嘉善县西塘古镇烟雨长廊遗址', '唐温如', '唐代', '西塘古镇烟雨长廊位于嘉兴市嘉善县，是唐温如《题龙阳县青草湖》"满船清梦压星河"的原型地之一。烟雨长廊沿河而建，保留有明清时期的廊棚与古码头，青石板路在廊檐下蜿蜒延伸数百米。雨天时雨水沿瓦檐滴落，形成珠帘般的水幕，行人在廊下漫步不沾雨滴。河面上乌篷船缓缓穿行，两岸民居粉墙黛瓦倒映水中。夜晚灯笼亮起，红光映照在水面上，恍如"满船清梦"的星河幻境。此处是江南水乡中最具诗意的廊棚景观，完美呈现了唐诗中烟雨江南的朦胧之美。', '浙江', 30.830900, 120.926100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/32/%E8%A5%BF%E5%A1%98%E6%B8%B8%E8%88%B9%E7%A0%81%E5%A4%B4%E5%92%8C%E9%80%81%E5%AD%90%E6%9D%A5%E5%87%A4%E6%A1%A5.jpg"]'),
('《山园小梅二首・其一》', '杭州市西湖区孤山放鹤亭遗址', '林逋', '北宋', '孤山放鹤亭位于杭州市西湖区孤山之上，是北宋隐士林逋"梅妻鹤子"隐居之地，也是《山园小梅》"疏影横斜水清浅，暗香浮动月黄昏"的创作之地。放鹤亭保留有宋代亭基，亭旁梅林数百株，冬末春初梅花绽放时暗香盈袖，花枝疏影横斜映在西湖水面上。林逋终身不仕不娶，以梅为妻、以鹤为子，在孤山上度过了二十余年清寂而自由的隐居生活。月夜时分梅花在银辉中若隐若现，"众芳摇落独暄妍"的高洁之美令人心驰神往。此处是感受宋代文人隐逸美学的至高境界。', '浙江', 30.259200, 120.129900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/West_Lake%2C_Hangzhou_2025.jpg/1280px-West_Lake%2C_Hangzhou_2025.jpg"]'),
('《枫桥夜泊》', '嘉兴市嘉善县西塘古镇卧龙桥遗址', '张继', '唐代', '西塘古镇卧龙桥位于嘉兴市嘉善县，相传也是张继《枫桥夜泊》意境的原型地之一。卧龙桥始建于明代，石拱高耸如龙卧波，是西塘最古老的石桥之一。桥下水巷幽深，古码头石阶延伸入水，明清古民居沿河而建。"月落乌啼霜满天"的夜泊意境在此处的水乡夜色中格外真切——乌篷船泊于桥下，灯火摇曳，远处隐约传来犬吠声。古镇清晨薄雾笼罩，炊烟袅袅，保留了江南水乡最原始的生活节奏。此处是体验唐诗夜泊意境与明代水乡建筑之美的宁静角落。', '浙江', 30.830900, 120.926100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/55/%E5%9B%BD%E5%8A%A1%E9%99%A2%E5%85%B3%E4%BA%8E%E6%A0%B8%E5%AE%9A%E5%B9%B6%E5%85%AC%E5%B8%83%E7%AC%AC%E5%85%AB%E6%89%B9%E5%85%A8%E5%9B%BD%E9%87%8D%E7%82%B9%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E7%9A%84%E9%80%9A%E7%9F%A5%EF%BC%88%E5%9B%BD%E5%8F%91%E3%80%942019%E3%80%9522%E5%8F%B7%EF%BC%89.pdf"]'),
('《送杜少府之任蜀州》', '杭州市富阳区鹳山古渡', '王勃', '唐代', '鹳山古渡位于杭州市富阳区富春江畔，相传也是王勃送别友人之处，"海内存知己，天涯若比邻"的豁达情怀在此升腾。古渡保留有唐代石砌码头与王勃雕像，富春江水在此处波澜壮阔，远山叠翠如画。唐代文人常在此处饮酒话别，江面上帆影点点，离愁别绪随江水东流。"无为在歧路，儿女共沾巾"的旷达胸襟超越了一般送别诗的凄婉缠绵。古渡周围环境清幽，春日江花似火，秋日枫叶如丹，是感受初唐诗歌豪迈乐观精神与富春江山水之美的送别文化之地。', '浙江', 30.048500, 119.960300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/a/aa/Shouxiang_Memorial_Hall_-_Court_of_the_Entrance.jpg"]'),
('《登鹳雀楼》', '杭州市萧山区湘湖越王城遗址', '王之涣', '唐代', '湘湖越王城遗址位于杭州市萧山区，相传也与王之涣《登鹳雀楼》"白日依山尽，黄河入海流"的创作有所关联。遗址保留有春秋时期的夯土城墙、古碑与古亭，是越王勾践"卧薪尝胆"的重要军事据点。城墙依山而建，居高临下，可俯瞰湘湖全貌与萧山平原。"欲穷千里目，更上一层楼"的进取精神与越王勾践的奋发图强一脉相承。湘湖水面开阔，湖光山色秀美，远处钱塘江隐约可见。此处是感受春秋吴越争霸历史与唐诗进取精神的综合性文化遗址。', '浙江', 30.183100, 120.264200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e4/Xiaoshan_Farm_CBD.jpg"]'),
('《凉州词二首・其一》', '杭州市西湖区西湖苏堤春晓南段遗址', '王翰', '唐代', '西湖苏堤春晓南段位于杭州市西湖区，相传也与王翰《凉州词》的创作背景有所关联。苏堤为苏轼任杭州知州时主持修建，堤上六桥横跨西湖，两侧垂柳如丝、桃花灼灼。南段保留有宋代古堤基址与古桥，春日晨曦中堤上花红柳绿，湖面薄雾缭绕，"苏堤春晓"位列西湖十景之首。漫步苏堤，左为外湖浩渺，右为里湖宁静，"水光潋滟晴方好"的美景在此处最为集中。此处虽为西湖核心景区，但清晨时分游客稀少，是体验宋代造园智慧与西湖极致之美的最佳时段。', '浙江', 30.259200, 120.129900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/West_Lake%2C_Hangzhou_2025.jpg/1280px-West_Lake%2C_Hangzhou_2025.jpg"]'),
('《出塞二首・其一》', '宁波市镇海区招宝山古炮台遗址', '王昌龄', '唐代', '招宝山古炮台位于宁波市镇海区甬江入海口，相传也与王昌龄《出塞》"但使龙城飞将在，不教胡马度阴山"的边塞豪情有所共鸣。古炮台始建于明代抗倭时期，保留有明清古炮、城墙与碑刻，是中国东南沿海最重要的海防要塞之一。登上炮台远眺，甬江奔腾入海，波涛翻涌。鸦片战争期间，镇海军民在此浴血抗击英军，留下了可歌可泣的英雄事迹。"秦时明月汉时关"的历史纵深感在此处与近代海防记忆交织，是感受中华民族保家卫国精神的重要军事文化遗存。', '浙江', 29.949500, 121.716400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/4c/Ningbo_Zhenhai_Montage.jpg"]'),
('《芙蓉楼送辛渐二首・其一》', '温州市永嘉县楠溪江芙蓉古村遗址', '王昌龄', '唐代', '楠溪江芙蓉古村位于温州市永嘉县，相传也是王昌龄《芙蓉楼送辛渐》"一片冰心在玉壶"的原型地之一。芙蓉古村始建于唐代，以芙蓉三峰为背景，村落布局暗含"七星八斗"天文格局。保留有宋代古民居、祠堂与古码头，青石板路蜿蜒穿行于白墙灰瓦之间。楠溪江水清澈见底，卵石滩上清流潺潺，两岸青山倒映水中。"洛阳亲友如相问，一片冰心在玉壶"的高洁品格与这座古村千年不变的质朴风貌相得益彰。此处是体验唐诗冰清玉洁之美与永嘉耕读文化的珍贵古村落。', '浙江', 28.153600, 120.692000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/7a/The_Memorial_Temple_for_the_Family_of_Chen_in_Furong_Village_03_2016-06.jpg"]'),
('《题破山寺后禅院》', '宁波市鄞州区阿育王寺遗址', '常建', '唐代', '阿育王寺位于宁波市鄞州区，相传也是常建《题破山寺后禅院》"曲径通幽处，禅房花木深"的创作灵感地之一。阿育王寺始建于西晋，是中国现存唯一以印度阿育王命名的千年古刹，寺内供奉释迦牟尼真身舍利。保留有唐代建筑基址、古碑与天然古泉，泉水甘冽清凉。寺院深处竹林幽深，禅房掩映其间，鸟鸣声与诵经声交织。此处远离宁波城区的喧嚣，保留了佛教圣地的庄严与清净，是体验"万籁此都寂，但余钟磬音"的禅意美学与浙东佛教文化的重要古刹。', '浙江', 29.816900, 121.546600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/6/68/Ningbo_Ayuwang_Si_2013.07.28_13-58-52.jpg"]'),
('《游山西村》', '绍兴市柯桥区柯岩风景区鲁镇遗址', '陆游', '南宋', '柯岩风景区鲁镇位于绍兴市柯桥区，相传也是陆游《游山西村》"山重水复疑无路，柳暗花明又一村"的原型地之一。鲁镇按照鲁迅小说中的场景复原了明清古民居、古码头与古戏台，再现了绍兴水乡古镇的风土人情。戏台上越剧婉转悠扬，社戏锣鼓声声，河面上乌篷船往来穿梭。周围群山环抱，水道纵横交错，"莫笑农家腊酒浑，丰年留客足鸡豚"的乡村盛情在此处得到生动再现。此处将陆游的田园诗意与鲁迅笔下的绍兴风情完美融合，是体验浙东文学与水乡民俗的综合性文化景区。', '浙江', 30.081500, 120.495800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/c3/%E6%B5%99%E6%B1%9F%E7%9C%81%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%85%AC%E6%8A%A52019%E5%B9%B4%E7%AC%AC3%E6%9C%9F.pdf"]'),
('《阿 Q 正传》', '绍兴市越城区东浦镇阿 Q 原型村', '鲁迅', '现代', '东浦镇阿Q原型村位于绍兴市越城区，是鲁迅小说《阿Q正传》中阿Q生活的"未庄"原型地。村中保留有清末民初的绍兴民居、老茶馆与古戏台，青石板路蜿蜒穿行于白墙灰瓦之间。"土谷祠"式的破旧祠堂、嘈杂的酒店柜台、喧闹的赌场后院，构成了鲁迅笔下那个愚昧与麻木并存的旧中国乡村缩影。阿Q"精神胜利法"的荒诞与悲剧至今发人深省。漫步村中，仿佛能听到阿Q"我们先前比你阔多了"的自欺之语，是感受鲁迅批判现实主义文学力量的重要文化遗存。', '浙江', 29.988500, 120.575300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/2/24/Canton_Tower_20241027.jpg"]'),
('《祝福》', '绍兴市柯桥区安昌古镇腊月风情节遗址', '鲁迅', '现代', '安昌古镇位于绍兴市柯桥区，是鲁迅小说《祝福》中祥林嫂故事的原型地。每年腊月，古镇举办传统风情节，家家户户制作酱鸭、腊肠，再现了"祝福"场景中绍兴年末的热闹景象。古镇保留有明清古街、老作坊与古码头，河道纵横，乌篷船穿行其间。酒坊飘出阵阵酒香，酱园内一缸缸酱油在阳光下发酵。"祥林嫂"的悲剧命运与古镇的热闹祝福形成了强烈对比，揭示了旧社会对底层女性的残酷压迫。此处是体验绍兴传统民俗与鲁迅文学世界的最佳水乡古镇。', '浙江', 30.081500, 120.495800, '其他', '["https://img2.baidu.com/it/u=3853935764,4076292002&fm=253&fmt=auto&app=138&f=JPEG?w=750&h=500"]'),
('《孔乙己》', '绍兴市越城区咸亨酒店旧址', '鲁迅', '现代', '咸亨酒店旧址位于绍兴市越城区鲁迅故里，是鲁迅小说《孔乙己》中孔乙己"排出九文大钱"喝酒的地方。酒店保留有清末民初的建筑风格、古木柜台与陈年酒坛，曲尺形柜台外站着喝酒的"短衣帮"仿佛历历在目。"温两碗酒，要一碟茴香豆"的经典场景在此处得到最真实的还原。孔乙己"窃书不能算偷"的迂腐与"他确实已经死了"的悲凉结局，折射出科举制度末期底层读书人的精神困境。此处是体验鲁迅短篇小说精妙与绍兴酒文化的标志性文学地标。', '浙江', 29.988500, 120.575300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/99/Guazhu_Hu.jpg"]'),
('《从百草园到三味书屋》', '绍兴市越城区鲁迅故里百草园后园', '鲁迅', '现代', '百草园后园位于绍兴市越城区鲁迅故里，是鲁迅散文《从百草园到三味书屋》中"碧绿的菜畦、光滑的石井栏"的真实描绘地。后园保留有清代菜畦、石井栏、泥墙根与高大的皂荚树，鲁迅童年在此"翻断砖、按斑蝥、拔何首乌"的欢乐时光至今可以想象。"不必说碧绿的菜畦，光滑的石井栏，高大的皂荚树，紫红的桑椹"的经典开头在此处有了最具象的注解。园内四季分明，春日菜花金黄，夏日蝉鸣阵阵，是体验鲁迅童年记忆与绍兴传统民居生活的珍贵文化空间。', '浙江', 29.988500, 120.575300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/b/b5/%E7%BB%8D%E5%85%B4%E9%B2%81%E8%BF%85%E6%95%85%E5%B1%85%E5%9B%BD%E4%BF%9D%E7%A2%91%2C_2020-09-26_04.jpg"]'),
('《社戏》', '绍兴市柯桥区孙端镇皇甫庄戏台遗址', '鲁迅', '现代', '皇甫庄戏台遗址位于绍兴市柯桥区孙端镇，是鲁迅散文《社戏》中童年看社戏的原型地。古戏台保留有清代建筑遗迹，台前水面开阔，当年"两岸的豆麦和河底的水草所发散出来的清香"仿佛仍在夜风中飘荡。古码头石阶延伸入水，乌篷船曾载着少年鲁迅与小伙伴们在月夜中驶向戏台。"真的，一直到现在，我实在再没有吃到那夜似的好豆"的怀念之情跨越百年。此处保留了绍兴水乡社戏文化的原始场景，是感受鲁迅少年时代纯真岁月的宁静之地。', '浙江', 30.081500, 120.495800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e8/Grand_Canal_Gongchen_Hangzhou.webm"]'),
('《故乡》', '绍兴市越城区斗门镇斗门老街', '鲁迅', '现代', '斗门老街位于绍兴市越城区斗门镇，是鲁迅小说《故乡》中闰土故乡的原型地。老街保留有清末民初的绍兴民居、老商铺与古码头，"深蓝的天空中挂着一轮金黄的圆月，下面是海边的沙地"的故乡意象从这里生发。少年闰土"项带银圈，手捏一柄钢叉"的英姿与中年闰土"脸上虽然刻着许多皱纹"的沧桑对比，折射出旧中国农村的凋敝。老街巷陌幽深，石桥横跨水巷，保留着绍兴水乡最质朴的生活气息。此处是感受鲁迅笔下"故乡"情结与旧中国农村社会变迁的重要文化遗存。', '浙江', 29.988500, 120.575300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/35/Dongpu_View_from_Huanxi_Road_2015-04.JPG"]'),
('《藤野先生》', '绍兴市越城区鲁迅故居藤野先生纪念室', '鲁迅', '现代', '鲁迅故居藤野先生纪念室位于绍兴市越城区，是鲁迅散文《藤野先生》中怀念恩师的纪念空间。室内保留有鲁迅留日时期的课本、与藤野先生的合影照片及往来书信，真实再现了这段跨越国界的师生情谊。"每当夜间疲倦，正想偷懒时，仰面在灯光中瞥见他黑瘦的面貌，便使我忽又良心发现"的深情至今令人动容。纪念室虽不大，但每一件展品都承载着鲁迅从"学医救国"到"弃医从文"的人生转折。此处是了解鲁迅精神成长历程与中日文化交流史的重要文化空间。', '浙江', 29.988500, 120.575300, '其他', '["https://img2.baidu.com/it/u=3792693542,71953964&fm=253&fmt=auto&app=138&f=JPEG?w=750&h=500"]'),
('《野草》', '绍兴市越城区鲁迅故居百草园野草园', '鲁迅', '现代', '百草园野草园位于绍兴市越城区鲁迅故居内，是鲁迅散文诗集《野草》的创作灵感来源地。园内保留有各种野生植物——蓬蒿、芦苇、野菊、苔藓，在四季中自然生长凋零。"当我沉默着的时候，我觉得充实；我将开口，同时感到空虚"的深沉思索或许就孕育于这片看似荒芜实则生机勃勃的园地。古碑与古亭掩映在杂草丛中，落叶覆盖小径。《野草》是鲁迅最具哲学深度的作品，"绝望之为虚妄，正与希望相同"的辩证思维在此处的荒野意象中得到了最原始的呈现。', '浙江', 29.988500, 120.575300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/17/%E9%B2%81%E8%BF%85_1933%E5%B9%B45%E6%9C%8826%E6%97%A5%E6%91%84%E4%BA%8E%E4%B8%8A%E6%B5%B7.jpg"]'),
('《活着》', '嘉兴市海盐县沈荡老街', '余华', '现代', '沈荡老街位于嘉兴市海盐县，是余华小说《活着》中福贵故乡的原型地。老街保留有清末民初的江南民居、老茶馆与酱园，青石板路蜿蜒在粉墙黛瓦之间。余华在此度过了童年与少年时代，对小镇生活的深切观察融入了《活着》中福贵从富家少爷到孤苦老人的一生悲欢。老茶馆中依然有老人们围坐品茶的场景，酱园内酱缸排列整齐，弥漫着浓郁的酱香。此处远离旅游开发，保留了浙北小镇最质朴的生活面貌，是感受余华文学世界中"活着"的力量与温度的真实之地。', '浙江', 30.526300, 120.945500, '其他', '["https://img2.baidu.com/it/u=450004470,2508135758&fm=253&fmt=auto&app=138&f=JPEG?w=1067&h=800"]'),
('《许三观卖血记》', '嘉兴市海盐县沈荡镇老医院遗址', '余华', '现代', '沈荡镇老医院遗址位于嘉兴市海盐县，是余华小说《许三观卖血记》中许三观多次卖血的原型地。遗址保留有上世纪五六十年代的医院建筑与老病房，红砖墙面斑驳，铁窗锈迹斑斑。余华的父亲曾是海盐县医院的外科医生，童年在医院长大的经历为他的创作提供了丰富素材。许三观用自己的血一次次换来家人的生存与尊严，"一碗黄酒、一盘炒猪肝"是他每次卖血后的犒赏。此处虽已不再作为医院使用，但那个年代的建筑与氛围仍在，是了解余华文学根源与中国底层民众生存韧性的独特文化遗址。', '浙江', 30.526300, 120.945500, '其他', '["https://img1.baidu.com/it/u=4167840947,2462192649&fm=253&fmt=auto&app=120&f=JPEG?w=654&h=437"]'),
('《子夜》', '嘉兴市桐乡市乌镇东栅茅盾故居', '茅盾', '现代', '乌镇东栅茅盾故居位于嘉兴市桐乡市，是茅盾小说《子夜》的重要创作背景地。故居为清代水乡民居，粉墙黛瓦，临河而建，保留有茅盾少年时期的书房、卧室与家族藏书楼。茅盾在此度过了启蒙教育时期，水乡的蚕桑文化、商业传统与市井人情深深影响了他的创作。故居内古碑记载着茅盾的生平事迹与文学成就。东栅河道幽静，石桥横跨，与西栅的商业化形成鲜明对比。此处是了解茅盾从水乡少年成长为文学巨匠历程的重要文化遗存，也是体验原汁原味乌镇水乡生活的最佳之地。', '浙江', 30.630200, 120.565300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/91/%E8%8C%85%E7%9B%BE%E7%BA%AA%E5%BF%B5%E9%A6%861.jpg"]'),
('《林家铺子》', '嘉兴市桐乡市乌镇东栅林家铺子旧址', '茅盾', '现代', '乌镇东栅林家铺子旧址位于嘉兴市桐乡市，是茅盾小说《林家铺子》的原型地。旧址保留有明清时期的商铺建筑，古木柜台、老货架与泛黄的账本再现了民国时期江南小镇商业的真实面貌。茅盾以林老板的小铺子为缩影，揭示了帝国主义经济侵略与国内战乱对民族工商业的双重打击。铺面朝街而开，后院连通水巷，便于货物装卸。"日货横行"的时代背景与小商人"左右为难"的生存困境在此处有了最具象的呈现。此处是了解茅盾现实主义文学与中国近代民族经济史的生动课堂。', '浙江', 30.630200, 120.565300, '其他', '["https://img0.baidu.com/it/u=38981388,3987004924&fm=253&fmt=auto&app=138&f=JPEG?w=667&h=500"]'),
('《春蚕》', '嘉兴市桐乡市石门镇养蚕基地', '茅盾', '现代', '石门镇养蚕基地位于嘉兴市桐乡市，是茅盾小说《春蚕》的核心原型地。桐乡自古以来便是中国蚕桑文化的核心区域，"春蚕到死丝方尽"的传统在此延续了数千年。基地保留有传统老蚕房、老农具与桑林，每年春季蚕农仍按照古法养蚕缫丝。茅盾在《春蚕》中描绘了老通宝一家"春蚕丰收却血本无归"的悲剧，揭示了旧中国农村经济被帝国主义和买办阶层层层盘剥的残酷现实。漫步桑林之间，蚕宝宝在簸箕中沙沙进食，是体验中国蚕桑文化与茅盾乡土文学的独特之地。', '浙江', 30.630200, 120.565300, '其他', '["https://img2.baidu.com/it/u=645746552,3943682295&fm=253&fmt=auto&app=138&f=JPEG?w=342&h=456"]'),
('《沉沦》', '杭州市富阳区鹳山郁达夫故居', '郁达夫', '现代', '郁达夫故居位于杭州市富阳区鹳山之畔，是郁达夫早期代表作《沉沦》的重要创作背景地。故居为民国时期建筑，青砖黛瓦，庭院幽深，保留有郁达夫的书房、手稿与纪念馆。富春江水在窗外缓缓流过，远山如黛，正是孕育这位"生于忧患"的浪漫主义作家的山水环境。郁达夫在《沉沦》中以大胆的自我剖白震惊文坛，"祖国啊祖国！我的死是你害我的"的呐喊至今震撼人心。故居内古碑记载着郁达夫从留日青年到抗日烈士的传奇一生，是了解五四文学精神与富阳人文传统的重要文化遗址。', '浙江', 30.048500, 119.960300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e4/%E9%83%81%E9%81%94%E5%A4%AB-1.jpg"]'),
('《故都的秋》', '杭州市富阳区郁达夫故居秋园', '郁达夫', '现代', '郁达夫故居秋园位于杭州市富阳区，是郁达夫散文名篇《故都的秋》中怀念北平秋天的情感寄托地。秋园保留有民国时期的园林建筑、古亭与苍劲古柏，深秋时节枫叶如火、银杏金黄，色彩斑斓。郁达夫"不远千里"要"饱尝"故都之秋的执念，折射出这位漂泊文人对精神故乡的深切眷恋。"北国的秋，却特别地来得清、来得静、来得悲凉"的感伤情怀在此处的秋色中引起共鸣。园内清幽安静，是感受郁达夫散文中那份"清净悲凉"美学与富春江畔秋日风光的宁静之地。', '浙江', 30.048500, 119.960300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e4/%E9%83%81%E9%81%94%E5%A4%AB-1.jpg"]'),
('《缘缘堂随笔》', '嘉兴市桐乡市石门镇缘缘堂旧址', '丰子恺', '现代', '缘缘堂旧址位于嘉兴市桐乡市石门镇，是丰子恺《缘缘堂随笔》的创作之地。缘缘堂为丰子恺自行设计建造的居所，建筑简朴雅致，体现了"有缘即住无缘去"的佛学理念。旧址保留有民国时期建筑风格、丰子恺手绘漫画原作与古碑，院内竹影婆娑，花木扶疏。丰子恺以温暖细腻的笔触描绘了日常生活中的诗意与禅趣——"人散后，一钩新月天如水"的意境至今打动人心。抗战中缘缘堂毁于日军炮火，后经重建。此处是感受丰子恺"童心与佛心"艺术精神的重要文化遗存。', '浙江', 30.630200, 120.565300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/cc/%E7%88%B1%E6%99%9A%E4%BA%AD%EF%BC%88%E7%A7%8B-%E4%BE%A7%E9%9D%A2%EF%BC%89.jpg"]'),
('《西湖梦寻》', '杭州市西湖区西湖孤山西泠印社遗址', '张岱', '明代', '西泠印社位于杭州市西湖区孤山之上，是张岱《西湖梦寻》中重点描绘的景点。西泠印社创建于清光绪年间，是中国研究金石篆刻的百年学术社团。社址依山而建，保留有明代以来的建筑、古碑与摩崖石刻，亭台楼阁错落于山石古木之间。张岱在明末动荡中以梦忆西湖往事，而西泠印社正处于他笔下孤山最清雅的区域。"四照阁下看松、赏月、观雪"的文人雅趣在此处延续至今。此处是西湖景区中文化底蕴最为深厚的角落，是感受中国金石文化与明清文人西湖情结的至高之地。', '浙江', 30.259200, 120.129900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/West_Lake%2C_Hangzhou_2025.jpg/1280px-West_Lake%2C_Hangzhou_2025.jpg"]'),
('《陶庵梦忆》', '杭州市西湖区西湖湖心亭遗址', '张岱', '明代', '西湖湖心亭位于杭州市西湖区西湖中心，是张岱《陶庵梦忆》中"湖心亭看雪"的发生地。"大雪三日，湖中人鸟声俱绝"，张岱独往湖心亭看雪的名篇被誉为中国散文史上的绝妙小品。亭基保留有明代遗迹与古碑，四面环水，孤处湖中。冬日大雪纷飞时，"天与云与山与水，上下一白"的奇观在此处最为震撼。春日湖面碧波荡漾，夏日荷花围绕，秋日桂香飘来。此处是西湖中最具文学意境的一处景观，完美呈现了张岱"痴人"性格中的孤独、高洁与对往昔繁华的无限追忆。', '浙江', 30.259200, 120.129900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/West_Lake%2C_Hangzhou_2025.jpg/1280px-West_Lake%2C_Hangzhou_2025.jpg"]'),
('《兰亭集序》', '绍兴市柯桥区兰亭景区曲水流觞遗址', '王羲之', '东晋', '兰亭位于绍兴市柯桥区兰亭景区内，是王羲之《兰亭集序》"此地有崇山峻岭，茂林修竹"的创作之地。东晋永和九年暮春，王羲之与四十余位名士在此举行"曲水流觞"雅集，饮酒赋诗，留下了"天下第一行书"的千古杰作。遗址保留有晋代曲水遗迹与古亭，清溪弯曲流淌，两岸修竹苍翠。"仰观宇宙之大，俯察品类之盛"的哲思在此处的山水之间自然流露。每年三月三日，兰亭仍举办曲水流觞的传统雅集活动。此处是感受东晋文人雅集文化与王羲之书法艺术的圣地。', '浙江', 30.081500, 120.495800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/4c/20240130_%E8%98%AD%E4%BA%AD.jpg"]'),
('《岳阳楼记》', '杭州市西湖区西湖范文正公祠遗址', '范仲淹', '北宋', '范文正公祠位于杭州市西湖区西湖畔，是范仲淹"先天下之忧而忧，后天下之乐而乐"思想的重要传播地。范仲淹虽在岳阳楼记中描绘的是洞庭湖景色，但其政治理想与人格精神在杭州也有深远影响——他曾知杭州，兴修水利，造福百姓。祠堂保留有宋代建筑基址、古碑与苍劲古柏，记载了范仲淹"居庙堂之高则忧其民，处江湖之远则忧其君"的高尚情操。西湖碧波在祠前荡漾，"不以物喜，不以己悲"的胸襟在此处的湖光山色中得到最好的诠释。', '浙江', 30.259200, 120.129900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/West_Lake%2C_Hangzhou_2025.jpg/1280px-West_Lake%2C_Hangzhou_2025.jpg"]'),
('《醉翁亭记》', '杭州市西湖区西湖六一泉遗址', '欧阳修', '北宋', '六一泉遗址位于杭州市西湖区西湖畔，是北宋文学家欧阳修与友人雅集之地。欧阳修自号"六一居士"，取一万卷书、一千卷金石文、一张琴、一局棋、一壶酒加自身为"六一"。泉眼保留有宋代遗迹、古亭与古碑，泉水至今清冽不竭。欧阳修在杭州任职期间常与友人在此品茗论文，《醉翁亭记》的旷达情怀与此处的清幽环境一脉相承。泉旁古木参天，竹影婆娑，鸟鸣啾啾。此处是感受北宋文坛领袖风范与杭州文人雅集传统的宁静之地，西湖的诗意在泉声中更显悠远。', '浙江', 30.259200, 120.129900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/West_Lake%2C_Hangzhou_2025.jpg/1280px-West_Lake%2C_Hangzhou_2025.jpg"]'),
('《徐霞客游记・游雁荡山记》', '温州市乐清市雁荡山灵峰夜景遗址', '徐霞客', '明代', '雁荡山灵峰夜景位于温州市乐清市，是徐霞客《游雁荡山记》中重点描绘的奇观。灵峰以"日景耐看，夜景更奇"著称——白天峰峦叠嶂，夜晚在月光映照下，奇峰怪石呈现出各种栩栩如生的人物动物形态。徐霞客在此"仰见峰顶如剑插天"，留下了对雁荡山地貌的精准记录。明代摩崖石刻散布于石壁之间，古驿道蜿蜒穿行于峡谷之中。春日杜鹃花开满山，秋日红叶如火。此处是感受中国火山岩地貌奇观与明代游记文学写实精神的绝佳之地。', '浙江', 28.113800, 120.983200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/14/The_East_Pagoda_in_Mid_River_Islet_05_2018-10.jpg"]'),
('《水经注・渐江水注》', '杭州市富阳区富春江严子陵钓台遗址', '郦道元', '北魏', '富春江严子陵钓台位于杭州市富阳区至桐庐段的富春江畔，是郦道元《水经注·渐江水注》中重点记载的名胜。严子陵为东汉光武帝刘秀的同窗好友，拒绝出仕后隐居于此垂钓终老。钓台保留有汉代石刻遗迹、唐代摩崖石刻与古亭，崖壁陡峭，面朝碧波荡漾的富春江。"江上一峰青，潭影照云深"的意境在晴日尤为动人。郦道元以严谨的笔触记录了渐江（富春江）的水文地理，为后世研究提供了珍贵资料。此处是感受东汉隐逸文化与北魏地理学成就的综合性文化名胜。', '浙江', 30.048500, 119.960300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/0/0d/Qiantang_River_Bridge_DJI_0575_%282%29.jpg"]'),
('《朝花夕拾》', '绍兴市越城区鲁迅故里三味书屋后院', '鲁迅', '现代', '三味书屋后院位于绍兴市越城区鲁迅故里，是鲁迅散文集《朝花夕拾》中"从百草园到三味书屋"的重要场景。后院保留有清代书桌、椅子与古碑，鲁迅少年时的"早"字刻桌至今犹存。寿镜吾先生"读书要专心"的谆谆教导与鲁迅偷偷溜到后院玩耍的调皮回忆交织于此。"出门向东，不上半里，走过一道石桥，便是我的先生的家了"的描写在此处一一对应。后院虽小，但古木参天，花草繁茂，是少年鲁迅在严格私塾教育中寻找自由的小天地。此处是感受清末绍兴私塾教育与鲁迅童年记忆的珍贵文化空间。', '浙江', 29.988500, 120.575300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/b/b5/%E7%BB%8D%E5%85%B4%E9%B2%81%E8%BF%85%E6%95%85%E5%B1%85%E5%9B%BD%E4%BF%9D%E7%A2%91%2C_2020-09-26_04.jpg"]'),
('《彷徨》', '绍兴市越城区鲁迅故居彷徨园', '鲁迅', '现代', '彷徨园位于绍兴市越城区鲁迅故居内，是鲁迅小说集《彷徨》的创作灵感来源地。园内保留有民国时期的园林建筑、古亭与苍劲古柏，曲径通幽，石径蜿蜒。鲁迅在"新文化运动"退潮后深感"荷戟独彷徨"的孤独，《祝福》《在酒楼上》《伤逝》等名篇中的迷茫与挣扎或许就在这样的园中踱步时酝酿。深秋时节，落叶铺满石径，古柏在风中发出低沉的呜咽，"路漫漫其修远兮"的沉重感弥漫在园中的每一个角落。此处是感受鲁迅"彷徨"时期精神世界的独特文化空间。', '浙江', 29.988500, 120.575300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/17/%E9%B2%81%E8%BF%85_1933%E5%B9%B45%E6%9C%8826%E6%97%A5%E6%91%84%E4%BA%8E%E4%B8%8A%E6%B5%B7.jpg"]'),
('《呐喊》', '绍兴市越城区鲁迅故居呐喊台', '鲁迅', '现代', '呐喊台位于绍兴市越城区鲁迅故居内，是鲁迅小说集《呐喊》精神内涵的象征性纪念地。鲁迅在《呐喊·自序》中写道："假如一间铁屋子，是绝无窗户而万难破毁的，里面有许多熟睡的人们"，这声"呐喊"正是要唤醒沉睡的国民。纪念地保留有民国建筑、古碑与鲁迅雕像，雕像神情坚毅，目光深邃。《狂人日记》《阿Q正传》《孔乙己》《药》等名篇的批判锋芒至今犹如利刃。此处浓缩了鲁迅"弃医从文"后以笔为武器、唤醒民众的伟大精神，是感受中国现代文学革命力量的重要文化地标。', '浙江', 29.988500, 120.575300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/17/%E9%B2%81%E8%BF%85_1933%E5%B9%B45%E6%9C%8826%E6%97%A5%E6%91%84%E4%BA%8E%E4%B8%8A%E6%B5%B7.jpg"]'),
('《红高粱家族》', '宁波市余姚市四明山革命根据地遗址', '莫言', '现代', '四明山革命根据地位于宁波市余姚市，是莫言小说《红高粱家族》中抗日故事的背景地之一。四明山地势险峻，丛林密布，抗战时期曾是浙东抗日根据地的核心区域。旧址保留有抗日指挥部、古驿道与古寺遗迹，山间石刻记录着浴血奋战的革命历程。"高粱地里的游击战"虽以山东为主要背景，但四明山的抗日斗争同样英勇壮烈。山中云雾缭绕，溪水潺潺，红色遗址与自然风光交相辉映。此处是缅怀浙东抗日英雄、感受革命文学精神的重要红色文化遗址。', '浙江', 30.037300, 121.154600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/44/Ningbo_City_God_Temple%2C_2021-10-23_06.jpg"]'),
('《妻妾成群》', '杭州市西湖区郭庄遗址', '苏童', '现代', '郭庄位于杭州市西湖区西湖畔，是苏童小说《妻妾成群》中陈家大院的原型地之一。郭庄始建于清代光绪年间，为杭州丝绸商郭氏别墅，园内亭台水榭、假山曲桥、花窗漏窗布局精巧。苏童笔下深宅大院中女性的悲剧命运，与郭庄幽深封闭的空间格局形成了隐喻式的对应——高墙之内的繁花似锦掩藏不住人性的孤独与绝望。园中荷池映月，古木参天，西湖波光从花窗中透入。此处是西湖边最为私密幽静的古典园林之一，是感受清代杭州富商生活与苏童文学世界的独特空间。', '浙江', 30.259200, 120.129900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/West_Lake%2C_Hangzhou_2025.jpg/1280px-West_Lake%2C_Hangzhou_2025.jpg"]'),
('《推拿》', '杭州市拱墅区小河直街盲人按摩店遗址', '毕飞宇', '现代', '小河直街盲人按摩店遗址位于杭州市拱墅区，是毕飞宇小说《推拿》的原型地之一。小河直街保留有清末民初的江南民居，白墙灰瓦，河道两岸老店铺鳞次栉比。毕飞宇以温暖而克制的笔触描绘了盲人推拿师们在黑暗中寻找尊严与爱情的日常生活。老巷幽深静谧，石板路上行人稀少，运河水缓缓流过门前。"看不见光明的人，却比明眼人更懂得生活的质感"——这种充满人文关怀的叙事在此处的市井氛围中显得格外真切。此处是了解杭州运河文化与中国当代人文主义文学的安静之地。', '浙江', 30.319700, 120.141500, '其他', '["https://img0.baidu.com/it/u=3243531829,2432824780&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《浮生六记》', '杭州市西湖区西湖苏堤春晓遗址', '沈复', '清代', '西湖苏堤春晓位于杭州市西湖区，是沈复《浮生六记》中与妻子芸娘漫游西湖的常去之地。苏堤为苏轼知杭时修建，长近三公里，堤上六桥横跨西湖南北。沈复与芸娘"携手同游"的温馨画面在苏堤的春日晨曦中最为动人——两侧桃红柳绿，湖面薄雾缭绕，"苏堤春晓"位列西湖十景之首。保留有宋代古堤基址与古桥，垂柳在微风中轻拂水面。"布衣蔬食，可乐终身"的生活理想与苏堤的诗意风光完美契合。此处是感受《浮生六记》中夫妻情深与西湖极致春色的浪漫之地。', '浙江', 30.259200, 120.129900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/West_Lake%2C_Hangzhou_2025.jpg/1280px-West_Lake%2C_Hangzhou_2025.jpg"]'),
('《过华亭》', '松江区醉白池池上草堂遗址', '白居易', '唐代', '醉白池位于上海市松江区，是白居易《过华亭》"地胜人堪隐"的创作之地。醉白池始建于宋代，是上海地区最古老的园林之一，以清幽雅致著称。池上草堂保留有宋代建筑基址、古碑与碧波荡漾的荷花池，夏日荷香四溢。园内古木参天，竹林幽深，亭台楼阁临水而建，白居易的隐逸情怀在此处的山水之间自然流露。此处远离上海都市的繁华喧嚣，保留了松江府千年文脉的清雅气韵，是感受唐诗隐逸美学与上海古典园林文化的宁静之地。', '上海', 31.032600, 121.227800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/f/f2/Qiuxiapu_Garden%2C_Shanghai.jpg"]'),
('《题松江驿》', '松江区松江驿古码头遗址', '苏轼', '北宋', '松江驿古码头遗址位于上海市松江区，是苏轼《题松江驿》"烟雨濛濛湿葛巾"的描绘之地。古码头保留有宋代夯土基址与明清碑刻，石阶斑驳苔藓丛生，诉说着千年来舟楫往来的繁忙景象。苏轼曾在此驿站歇脚，目睹松江烟雨朦胧的水乡风情而写就此诗。运河水缓缓流过码头，两岸民居白墙灰瓦，远处松江城楼隐约可见。此处虽已不再承担驿站功能，但古码头的石基与碑文仍在，是了解宋代水路驿站制度与松江古城千年变迁的珍贵历史遗存。', '上海', 31.032600, 121.227800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/33/%E4%B8%8A%E6%B5%B7%C2%B7%E4%B8%8A%E6%B5%B7%E5%B8%82%C2%B7%EF%BC%88%E4%BF%AF%E6%8B%8D%EF%BC%89.jpg"]'),
('《舟过吴淞江》', '青浦区朱家角镇放生桥遗址', '陆游', '南宋', '朱家角放生桥位于上海市青浦区朱家角镇，是陆游《舟过吴淞江》"扁舟夜泊待天明"的观景之地。放生桥始建于明代，为五孔石拱桥，是上海地区最大的古代石桥，气势雄伟。桥下漕港河水缓缓流过，古码头石阶延伸入水，乌篷船穿行于桥洞之间。站在桥顶远眺，朱家角古镇粉墙黛瓦连绵成片，河道纵横如织。每年佛诞日，信众在桥下放生鱼鳖，延续着数百年的民间传统。此处是体验江南水乡古桥文化与陆游舟行吴淞意境的最佳之地。', '上海', 31.150000, 121.124400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/4e/CADAL02047686_%E8%81%96%E6%94%BF%E8%A8%98%EF%BC%88%E4%B8%89%EF%BC%89.djvu"]'),
('《淀山湖》', '青浦区淀山湖大观园稻香村遗址', '杨万里', '南宋', '淀山湖大观园稻香村位于上海市青浦区淀山湖畔，是杨万里《淀山湖》"荷叶荷花香满船"的创作之地。大观园按照《红楼梦》场景建造，稻香村是其中最具田园诗意的景点。保留有宋代园林基址、古碑与百亩荷塘，夏日荷花盛开时满湖粉红，"接天莲叶无穷碧"的壮观景象在此完美呈现。淀山湖水域开阔，波光粼粼，远处青山隐约。稻香村内茅屋竹篱，菜畦纵横，桑榆成行，既有杨万里笔下的荷塘之美，又有《红楼梦》中李纨居所的田园清趣。此处是上海近郊感受古典文学与自然风光的独特之地。', '上海', 31.150000, 121.124400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/0/0c/Shanghaidaguanyuan.jpg"]'),
('《过嘉定》', '嘉定区古猗园缺角亭遗址', '范成大', '南宋', '古猗园缺角亭位于上海市嘉定区南翔镇，相传也与范成大《过嘉定》"嘉定城外暮云平"的描绘有所关联。古猗园始建于明代嘉靖年间，以竹闻名，园中竹林幽深，品种多达数十种。缺角亭寓意不忘国耻，建筑独特。保留有明代假山叠石、古碑与精美的石刻。园内亭台楼阁依水而建，曲桥回廊连接各景，体现了明代江南私家园林的高超造园技艺。此处是上海地区保存最完好的古典园林之一，远离都市喧嚣，是感受明代园林竹文化与嘉定人文传统的清幽之地。', '上海', 31.374700, 121.265400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/8b/The_Names_of_Tomatoes_in_Chinese_Dialects.pdf"]'),
('《秋霞圃》', '嘉定区秋霞圃凝霞阁遗址', '唐寅', '明代', '秋霞圃凝霞阁位于上海市嘉定区，相传与唐寅"枫叶红于二月花"的意境有所关联。秋霞圃始建于明代正德年间，是上海地区五大古典园林之一。凝霞阁保留有明代假山、古碑与红叶林，深秋时节枫叶如火，满园"秋霞"名副其实。园内以假山石径为骨架，亭台水榭错落有致，"城市山林"的造园理念在此完美体现。桃花潭水清如镜，凝霞阁上可俯瞰全园秋色。此处虽在嘉定老城区中心，却闹中取静，是体验明代文人审美与上海深秋极致色彩的古典园林精品。', '上海', 31.374700, 121.265400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/7d/CADAL09001567_%E9%99%B8%E8%BB%8D%E5%BF%A0%E5%8B%87%E6%95%85%E4%BA%8B%E9%9B%86.djvu"]'),
('《龙华寺》', '徐汇区龙华寺龙华塔唐代塔基遗址', '王守仁', '明代', '龙华寺龙华塔位于上海市徐汇区，是王守仁《龙华寺》"龙华寺里暮钟声"描绘的千年古刹。龙华塔始建于唐代，现存塔身为宋代建筑，七层八角，砖木结构，是上海地区最古老的地面建筑。唐代夯土塔基至今保存完好，诉说着一千余年的沧桑岁月。暮色降临时塔上灯火辉映，钟声悠远回荡在龙华地区上空。每年春季龙华桃花盛开，"龙华晚钟"曾为沪上八景之一。此处佛教文化深厚，古寺庄严，是在上海繁华都市中感受唐宋古塔建筑之美与佛寺暮鼓晨钟意境的珍贵遗存。', '上海', 31.188300, 121.436500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/ec/Square_Tower_of_Songjiang.jpg"]'),
('《静安寺》', '静安区静安寺涌泉遗址', '文徵明', '明代', '静安寺涌泉遗址位于上海市静安区，是文徵明《静安寺》"日夜潺湲听不尽"的创作之地。涌泉为静安寺古八景之一，泉水自宋代以来涌流不息。遗址保留有宋代泉眼、明代古亭与碑刻，记载了静安寺从吴淞江畔迁至现址的千年历程。文徵明以诗画兼擅的才华描绘了泉水日夜流淌的静谧之美。虽然如今静安寺周围已是上海最繁华的商业中心，但寺内古泉依然清冽，钟磬之声在高楼大厦间回荡，形成了千年古刹与现代都市的独特共存景观。', '上海', 31.228600, 121.448400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/6/6e/%E4%B8%8A%E6%B5%B7%E9%9D%99%E5%AE%89%E5%8F%A4%E5%AF%BA2%E5%8F%B7.JPG"]'),
('《豫园》', '黄浦区豫园湖心亭遗址', '徐渭', '明代', '豫园湖心亭位于上海市黄浦区，相传与徐渭《豫园》"楼阁参差映翠微"的描绘有所关联。豫园始建于明代嘉靖年间，是上海最著名的古典园林。湖心亭建于清代，坐落于九曲桥畔的荷花池中央，保留有明代建筑遗迹、古碑与四季荷花。亭内品茶观景，窗外九曲桥上游人如织，池中锦鲤嬉戏，远处假山叠石巍然。春日桃红柳绿，夏日荷花映日，秋日桂香飘来，冬日腊梅暗香。此处是上海老城厢中保留明代文人造园精神的核心所在，是感受海上繁华中古典雅韵的独特空间。', '上海', 31.231900, 121.484600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/f/fa/%E8%B1%AB%E5%9B%AD%E6%B9%96%E5%BF%83%E4%BA%AD2024.5_%282%29.jpg"]'),
('《吴淞口》', '宝山区吴淞口西炮台遗址', '陈子龙', '明代', '吴淞口西炮台位于上海市宝山区长江与黄浦江交汇处，是陈子龙《吴淞口》"战舰横空去不还"的创作之地。西炮台始建于清代，是守卫上海的重要海防要塞。保留有清代古炮台、大口径古炮与战壕遗迹，记录了鸦片战争中吴淞军民浴血抗英的英勇历史。陈子龙作为明末抗清志士，其诗中的悲壮之情与此处的军事历史遥相呼应。站在炮台上远眺，长江浩荡入海，船舶往来如梭。此处是了解上海近代海防史与明清爱国文人精神的重要军事文化遗存。', '上海', 31.405400, 121.489300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/35/%E4%B8%8A%E6%B5%B7%E5%B8%82%E5%AE%9D%E5%B1%B1%E5%8C%BA%E7%82%AE%E5%8F%B0%E5%B1%B1%E5%85%AC%E5%9B%AD_-_panoramio_%281%29.jpg"]');
INSERT INTO works (title, scenic_spot, author, dynasty, description, province, latitude, longitude, category, images) VALUES
('《崇明岛》', '崇明区东平国家森林公园古银杏林', '钱谦益', '清代', '东平国家森林公园古银杏林位于上海市崇明区，是钱谦益《崇明岛》"万顷烟波入渺然"的描绘之地。崇明岛为中国第三大岛，东平森林公园保留有千年古银杏树群，金秋时节满地金黄，蔚为壮观。原始森林内古木参天，鸟鸣啾啾，负氧离子含量极高。公园内湿地水系丰富，候鸟季节万鸟翔集。长江在岛外奔腾入海，"万顷烟波"的壮阔景象在此处确实可感。此处远离上海主城区的繁华，保留了长江入海口最原始的自然生态，是上海近郊感受森林野趣与长江入海气象的绝佳之地。', '上海', 31.622800, 121.397300, '其他', '["https://img1.baidu.com/it/u=473869181,1777083647&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=659"]'),
('《七宝古镇》', '闵行区七宝古镇老北街遗址', '王士祯', '清代', '七宝古镇老北街位于上海市闵行区，是王士祯《七宝古镇》"青石板路映斜阳"的描绘之地。七宝古镇始建于北宋，老北街保留有明清古民居、老商铺与古桥，青石板路蜿蜒在白墙灰瓦之间。蒲汇塘河穿镇而过，两岸酒旗飘扬，老字号糕点铺、棉纺坊飘出阵阵香气。"七件宝"——飞来佛、氽来钟、金字莲花经等传说为古镇增添了神秘色彩。夕阳西下时，斜阳照在青石板上泛出温暖的金色光芒，再现了清代文人笔下的水乡古镇风情。此处是上海中心城区内体验江南古镇市井生活的便捷之地。', '上海', 31.112800, 121.381000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/d7/Chunshen_Lake%2C_Minhang_%2820191111161524%29.jpg"]'),
('《枫泾古镇》', '金山区枫泾古镇致和桥遗址', '袁枚', '清代', '枫泾古镇致和桥位于上海市金山区，是袁枚《枫泾古镇》"两岸人家尽枕流"的描绘之地。致和桥始建于元代至元年间，为单孔石拱桥，是上海地区现存最古老的石桥之一。桥身石刻精美，拱形优雅，倒映在碧水之中形成完美圆环。枫泾古镇横跨吴越两地，自古有"吴越名镇"之称。古码头石阶延伸入水，临水民居粉墙黛瓦，河道狭窄幽深。此处远离上海市区的现代喧嚣，保留了沪郊水乡古镇最质朴的原始风貌，是感受元代桥梁建筑之美与吴越文化交融的宁静之地。', '上海', 30.741600, 121.341600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/0/0b/Fengjing_Sanqiao.JPG"]'),
('《朱家角》', '青浦区朱家角镇课植园遗址', '郑板桥', '清代', '朱家角课植园位于上海市青浦区朱家角镇，相传与郑板桥"读书耕田乐逍遥"的理念有所呼应。课植园取"课读之余不忘耕植"之意，建于民国初年，融合了中西建筑风格。保留有民国时期的园林建筑、古碑与藏书楼，假山池塘、亭台水榭布局精巧。园中既有中式园林的曲径通幽，又有西式建筑的敞亮开阔。藏书楼中曾珍藏大量典籍，体现了"耕读传家"的传统文化理念。此处是朱家角古镇中最具文化底蕴的私家园林，是感受民国时期江南士绅生活方式与中西文化交融的独特空间。', '上海', 31.150000, 121.124400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/82/Kezhiyuan.jpg"]'),
('《南翔古镇》', '嘉定区南翔古镇云翔寺遗址', '龚自珍', '清代', '南翔古镇云翔寺位于上海市嘉定区，相传也与龚自珍"曲径通幽花木繁"的描绘有所关联。云翔寺始建于唐代，因"白鹤南翔"的传说而得名，也是南翔镇地名的由来。遗址保留有唐代寺基、宋代碑刻与千年古银杏树，枝干苍劲如虬龙盘旋。寺院经历代重建，仍保留着唐代佛教建筑的庄严气象。古银杏树在深秋时节金黄灿烂，落叶铺满禅院。此处紧邻南翔老街，小笼包的蒸汽与古寺的香火在空气中交融，是在上海感受唐代佛教文化与江南市井烟火共存的独特之地。', '上海', 31.374700, 121.265400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/6/68/CADAL09014334_%E6%A1%AF%E5%8F%B2%C2%B7%EF%BC%88%E4%B8%80%EF%BC%89.djvu"]'),
('《周浦古镇》', '浦东新区周浦镇老西街遗址', '高启', '明代', '周浦老西街位于上海市浦东新区周浦镇，相传与高启"烟火人间岁月沉"的描绘有所关联。周浦古称"周浦塘"，老西街保留有明清古民居、老商铺与古桥，青石板路蜿蜒幽深。周浦自明代以来便是浦东地区重要的商贸重镇，"小上海"的美誉名不虚传。老街两侧的百年老店、中药铺、茶馆保留着昔日的经营格局。河道穿镇而过，石桥横跨，倒映着两岸的粉墙黛瓦。此处虽在浦东新区的现代化浪潮中保留不多，但老西街的历史肌理仍可辨识，是了解浦东古镇商业文化的珍贵遗存。', '上海', 31.221400, 121.544700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/74/%E7%BB%9F%E8%AE%A1%E7%94%A8%E5%8C%BA%E5%88%92%E4%BB%A3%E7%A0%81%E5%92%8C%E5%9F%8E%E4%B9%A1%E5%88%92%E5%88%86%E4%BB%A3%E7%A0%81_%E6%B1%9F%E8%8B%8F.pdf"]'),
('《新场古镇》', '浦东新区新场镇洪东街遗址', '杨慎', '明代', '新场古镇洪东街位于上海市浦东新区，相传与杨慎"十里桃花映日红"的描绘有所关联。新场古镇始建于宋代，因盐业而兴盛，是浦东地区保存最完好的古镇之一。洪东街保留有明清古民居、老商铺与古码头，建筑风格兼具徽派与本地特色。河道纵横，石桥古朴，沿河的廊棚遮风挡雨。春日桃花盛开时，两岸粉红如霞，与粉墙黛瓦交相辉映。新场曾是电影《色戒》的取景地，古镇的幽深与神秘在此完美呈现。此处远离旅游商业化，保留了浦东古镇最真实的历史风貌。', '上海', 31.221400, 121.544700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/74/%E7%BB%9F%E8%AE%A1%E7%94%A8%E5%8C%BA%E5%88%92%E4%BB%A3%E7%A0%81%E5%92%8C%E5%9F%8E%E4%B9%A1%E5%88%92%E5%88%86%E4%BB%A3%E7%A0%81_%E6%B1%9F%E8%8B%8F.pdf"]'),
('《召稼楼》', '闵行区召稼楼古镇礼园遗址', '归有光', '明代', '召稼楼古镇礼园位于上海市闵行区浦江镇，相传与归有光"礼园深处鸟啼鸣"的描绘有所关联。召稼楼因明代工部右侍郎谈伦在此"召稼"（召集农民耕种）而得名。礼园保留有清代园林建筑、古碑与名人故居，园内假山池塘，花木扶疏。召稼楼是上海城隍秦裕伯的故乡，也是上海浦东垦荒文化的发源地。古镇内河道蜿蜒，石桥横跨，明清建筑错落有致。此处既有江南水乡的温婉，又有浦东拓荒的坚韧精神，是了解上海城市发展根源与明代农耕文化的重要文化遗存。', '上海', 31.112800, 121.381000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/d7/Chunshen_Lake%2C_Minhang_%2820191111161524%29.jpg"]'),
('《罗店古镇》', '宝山区罗店镇老西街遗址', '李东阳', '明代', '罗店老西街位于上海市宝山区罗店镇，相传与李东阳"青石板路映斜阳"的描绘有所关联。罗店古镇始建于元代，明清时期因棉布贸易而繁荣，有"金罗店"之美誉。老西街保留有明清古民居、老商铺与古桥，青石板路在夕阳下泛出温暖的光泽。罗店龙船文化源远流长，每年端午节的龙船竞渡是上海地区最具特色的民俗活动之一。河道穿镇而过，两岸建筑飞檐翘角，保留了宝山地区古镇的原始风貌。此处是了解上海北部古镇商业文化与龙船民俗传统的宁静之地。', '上海', 31.405400, 121.489300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/86/%E9%99%95%E8%A5%BF%E7%9C%81%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E9%99%95%E8%A5%BF%E7%9C%81%E7%AC%AC%E4%B8%89%E6%89%B9%E9%87%8D%E7%82%B9%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E5%8F%8A%E6%92%A4%E9%94%80%E9%99%95%E8%A5%BF%E7%9C%81%E7%AC%AC%E4%B8%80%E3%80%81%E4%BA%8C%E6%89%B9%E9%83%A8%E5%88%86%E9%87%8D%E7%82%B9%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E7%9A%84%E9%80%9A%E7%9F%A5%EF%BC%88%E9%99%95%E6%94%BF%E5%8F%91%E3%80%941992%E3%80%9534%E5%8F%B7%EF%BC%89.pdf"]'),
('《高桥古镇》', '浦东新区高桥镇老东街遗址', '袁宏道', '明代', '高桥老东街位于上海市浦东新区高桥镇，相传与袁宏道"两岸人家尽枕流"的描绘有所关联。高桥古镇历史悠久，老东街保留有明清古民居、老商铺与古码头，建筑沿河而建，临水而居。高桥是著名的"高桥松饼"发源地，百年老字号糕点铺的甜香弥漫在古街之中。河道狭窄幽深，石板路连通各家各户，保留了浦东传统水乡的生活格局。此处虽距离陆家嘴仅数公里，但老街的时光仿佛静止在百年前。是在上海感受浦东古镇质朴生活与传统美食文化的独特之地。', '上海', 31.221400, 121.544700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/74/%E7%BB%9F%E8%AE%A1%E7%94%A8%E5%8C%BA%E5%88%92%E4%BB%A3%E7%A0%81%E5%92%8C%E5%9F%8E%E4%B9%A1%E5%88%92%E5%88%86%E4%BB%A3%E7%A0%81_%E6%B1%9F%E8%8B%8F.pdf"]'),
('《川沙古镇》', '浦东新区川沙镇内史第遗址', '徐霞客', '明代', '川沙内史第位于上海市浦东新区川沙镇，相传与徐霞客"江南名宅数第一"的描绘有所关联。内史第始建于清代，是一座典型的江南官宦府邸，曾走出黄炎培、宋庆龄家族等近代名人。保留有清代建筑、古碑与名人故居，庭院深深，雕梁画栋。黄炎培在此创办了中国职业教育的先河，宋氏三姐妹的外祖父也曾居住于此。此处集中了近代中国多位风云人物的家族记忆，是浦东地区最具历史文化价值的名宅。漫步其间，能感受到清末民初中国社会变革的历史脉动。', '上海', 31.221400, 121.544700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/cb/%E4%B8%8A%E6%B5%B7%E5%B8%82%E5%9F%8E%E5%B8%82%E6%80%BB%E4%BD%93%E8%A7%84%E5%88%92%EF%BC%882017-2035%E5%B9%B4%EF%BC%89_%E6%96%87%E6%9C%AC.pdf"]'),
('《松江府》', '松江区松江府城隍庙遗址', '张岱', '明代', '松江府城隍庙位于上海市松江区，是张岱《松江府》"香火盛千年"描绘的古老庙宇。城隍庙始建于明代，保留有明代建筑构件、古碑与古戏台，殿宇庄严肃穆。松江府自古为"上海之根"，城隍庙曾是松江地区最重要的民间信仰中心。古戏台上曾演出昆曲、评弹等传统戏曲，台下观众如云。张岱以"痴"著称，对各地庙会民俗有着细腻入微的记录。此处保留了松江古城的宗教文化与市井风情，是了解上海文化根源与明清民间信仰的重要遗存。', '上海', 31.032600, 121.227800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/a/a9/%E4%B8%9C%E6%96%B9%E6%9E%A2%E7%BA%BD%E5%8F%8A%E5%91%A8%E8%BE%B9%E5%9C%B0%E5%8C%BA%E4%B8%93%E9%A1%B9%E8%A7%84%E5%88%92%EF%BC%882025-2035%E5%B9%B4%EF%BC%89.pdf"]'),
('《青浦县》', '青浦区青浦县城隍庙遗址', '李斗', '清代', '青浦城隍庙位于上海市青浦区，是李斗《青浦县》"古木参天遮"描绘的古老庙宇。城隍庙保留有清代建筑、古碑与古戏台，院内古木参天，枝叶遮天蔽日，营造出幽深肃穆的氛围。青浦自古以来便是上海西部的重要水乡城镇，城隍庙是当地民众祈福求安的精神寄托。庙内壁画色彩斑斓，描绘了城隍巡游的热闹场景。古戏台上演出的传统戏曲回荡在庙院上空。此处虽规模不大，但保留了清代江南小城庙宇的原始风貌，是感受上海青浦地区传统民间信仰文化的安静之地。', '上海', 31.150000, 121.124400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/2/24/Qingpuchenghuangmiao_Toumen%2C_xitai_he_niangniangdian.jpg"]'),
('《嘉定县》', '嘉定区嘉定县孔庙遗址', '钱大昕', '清代', '嘉定孔庙位于上海市嘉定区，是钱大昕《嘉定县》"文风盛千年"描绘的文教圣地。嘉定孔庙始建于南宋嘉定十二年，是目前上海地区保存最完好的孔庙建筑群。保留有宋代建筑基址与大量古碑，碑廊中七十二块碑刻记载了嘉定八百年的科举文化与教育传统。大成殿庄严肃穆，古柏苍翠挺拔，与"教化嘉定"的文化传统一脉相承。嘉定自古有"教化之城"美誉，科举人才辈出。此处是上海地区了解中国科举制度与儒学教育传统最为集中的文化遗存。', '上海', 31.374700, 121.265400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/84/%E5%98%89%E5%AE%9A%E5%9B%BE%E4%B9%A6%E9%A6%86%E5%92%8C%E4%BF%9D%E5%88%A9%E5%9B%BD%E9%99%85%E5%B9%BF%E5%9C%BA.jpg"]'),
('《金山卫》', '金山区金山卫古城墙遗址', '顾炎武', '清代', '金山卫古城墙遗址位于上海市金山区，是顾炎武《金山卫》"雄踞东海旁"描绘的海防要塞。金山卫始建于明代洪武年间，是明清时期防御倭寇的重要军事设施。保留有明代城墙残段、古炮与古碑，城墙夯土坚实，历经六百余年风雨。金山卫抗倭保卫战是上海地区最英勇的军事历史之一。顾炎武"天下兴亡，匹夫有责"的精神在此处的海防遗迹中得到最直观的体现。站在城墙遗址上远眺杭州湾，海风凛冽，波涛拍岸，是了解上海海防历史与明清抗倭文化的重要军事遗存。', '上海', 30.741600, 121.341600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/3f/State_Council_Gazette_-_2019_-_Issue_30.pdf"]'),
('《奉贤》', '奉贤区庄行古镇老街遗址', '朱彝尊', '清代', '庄行古镇老街位于上海市奉贤区，相传与朱彝尊"油菜花黄满地金"的描绘有所关联。庄行古镇保留有明清古民居、老商铺与古桥，青石板路蜿蜒在粉墙黛瓦之间。每年春季，古镇周围万亩油菜花田金黄灿烂，"满地金"的壮观景象名不虚传。庄行自古以来便是奉贤地区重要的农贸集镇，老街上的羊肉馆、米酒坊飘出诱人香气。河道穿镇而过，两岸民居临水而建，保留了沪南乡村古镇的质朴风貌。此处是上海近郊体验春日油菜花海与江南古镇市井生活的绝佳之地。', '上海', 30.917900, 121.474000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/6/63/%E7%AC%AC%E5%85%AD%E6%89%B9%E6%B1%9F%E8%A5%BF%E7%9C%81%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E4%BF%9D%E6%8A%A4%E8%8C%83%E5%9B%B4%E4%B8%80%E8%A7%88%E8%A1%A8.pdf"]'),
('《南汇》', '浦东新区新场镇南山寺遗址', '查慎行', '清代', '新场南山寺遗址位于上海市浦东新区新场镇，是查慎行《南汇》"南山寺里钟声远"描绘的古刹遗迹。南山寺始建于明代，保留有明代古寺建筑基址、古碑与苍劲古柏，寺院幽静深远。查慎行在清初游历江南时，对南汇一带的水乡风情与佛教古刹留下了深刻印象。古柏枝干虬曲，苍翠如盖，钟声在寺院中回荡，余音袅袅。此处虽在浦东新区的快速发展中渐趋边缘，但古寺的宁静与庄严未改，是在上海浦东感受明代佛教文化与清代文人游历足迹的安静之地。', '上海', 31.221400, 121.544700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/a/a9/%E4%B8%9C%E6%96%B9%E6%9E%A2%E7%BA%BD%E5%8F%8A%E5%91%A8%E8%BE%B9%E5%9C%B0%E5%8C%BA%E4%B8%93%E9%A1%B9%E8%A7%84%E5%88%92%EF%BC%882025-2035%E5%B9%B4%EF%BC%89.pdf"]'),
('《上海县》', '黄浦区上海县老城厢遗址', '陈维崧', '清代', '老城厢遗址位于上海市黄浦区，是陈维崧《上海县》"烟火万家稠"描绘的上海老城区核心地带。老城厢是上海开埠前的城市中心，保留有明清古民居、老商铺与古桥，城隍庙、文庙等文化地标坐落其中。陈维崧笔下"烟火万家"的繁忙景象在清代上海县城中真实可感——商铺鳞次栉比，叫卖声此起彼伏，河道中舟楫往来。虽然如今老城厢大部分已拆建，但残存的石库门、老弄堂仍诉说着上海从小渔村到大都会的沧桑巨变。此处是了解上海城市发展根源与清代江南城镇面貌的重要历史遗存。', '上海', 31.231900, 121.484600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/86/Old_City_of_Shanghai_will_walls_and_seafront.jpg"]'),
('《黄浦江》', '杨浦区杨浦大桥下老码头遗址', '郑燮', '清代', '杨浦大桥下老码头位于上海市杨浦区黄浦江畔，相传与郑燮"千帆竞渡去如烟"的描绘有所关联。老码头保留有清末民初的码头建筑与老仓库，红砖墙面斑驳，铁制吊臂锈迹斑斑，见证了上海近代航运业的兴衰。黄浦江水在此处水面开阔，潮涨潮落，曾经千帆竞发的繁忙景象已成历史。如今老仓库经改造成为滨江文化空间，工业遗产与现代艺术在此交融。站在江边远眺陆家嘴天际线，百年沧桑与现代繁华形成强烈对比，是感受上海工业码头文化与城市变迁的独特滨江空间。', '上海', 31.259800, 121.526100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/9b/Yangpu_Bridge2.JPG"]'),
('《苏州河》', '普陀区苏州河梦清园遗址', '袁枚', '清代', '苏州河梦清园位于上海市普陀区苏州河畔，相传与袁枚"两岸垂杨映碧天"的描绘有所关联。梦清园建于原苏州河水质净化工程遗址之上，保留有清代古码头遗迹与工业老厂房，经生态修复后成为滨河湿地公园。苏州河曾是上海近代工业的生命线，两岸工厂林立、船运繁忙。如今河水重新变清，垂柳在岸边随风摇曳，湿地中芦苇摇曳、鸟鸣啾啾，"两岸垂杨映碧天"的诗意景象逐渐重现。此处是上海城市生态修复的典范，也是感受苏州河从工业河到生态河华丽转身的最佳观察点。', '上海', 31.249500, 121.397000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/3d/View_with_Global_Harbor_towers%2C_Shanghai.JPG"]'),
('《子夜》', '黄浦区苏州河四行仓库老码头', '茅盾', '现代', '四行仓库老码头位于上海市黄浦区苏州河畔，是茅盾《子夜》中吴荪甫丝厂原料码头的原型地。四行仓库始建于1931年，因中国、交通、中南、大陆四家银行共同出资而得名。保留有清末民初码头建筑、老仓库与铁制起重设备，红砖外墙弹痕累累，见证了1937年淞沪会战中谢晋元率八百壮士浴血奋战的英雄事迹。茅盾在《子夜》中将此处描绘为民族资本家苦心经营的工业码头，反映了上海近代工业的兴衰。苏州河水在仓库前缓缓流过，码头石阶斑驳，是了解上海近代工业史与抗战记忆的重要文化地标。', '上海', 31.231900, 121.484600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e5/A_picture_from_China_every_day_101.jpg"]'),
('《子夜》', '静安区愚园路 1136 弄老洋房群', '茅盾', '现代', '愚园路1136弄老洋房群位于上海市静安区，是茅盾《子夜》中赵伯韬等买办资本家居所的原型地。这片建于民国时期的欧式洋房群保留有精美的建筑立面、铸铁阳台栏杆与老花园，建筑风格融合了法式与西班牙式元素。高大的梧桐树在弄堂上方形成绿色穹顶，斑驳的阳光洒在红砖小径上。茅盾以犀利的笔触描绘了上海买办阶层纸醉金迷的生活，而这些洋房正是那个时代的空间载体。弄堂深处偶有老住户进出，时光仿佛凝固在民国的旧时光里，是感受上海租界时期建筑风貌与文学想象的独特空间。', '上海', 31.228600, 121.448400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/8f/Yuyuan_Rd._Shanghai.JPG"]'),
('《子夜》', '黄浦区南京路步行街北段老商铺', '茅盾', '现代', '南京路步行街北段老商铺位于上海市黄浦区，是茅盾《子夜》中上海商业繁华的原型地。南京路自晚清以来便是上海最繁华的商业街道，北段保留有清末民初的商铺建筑、老柜台与招牌，红漆木门、铜制把手诉说着百年商业传奇。茅盾在《子夜》中多次描绘南京路的车水马龙与霓虹闪烁，将之作为上海资本主义繁荣的象征。老商铺的建筑细节——雕花门楣、彩色玻璃窗、西式壁柱——展现了中西商业文化交融的独特风貌。此处虽已高度商业化，但北段部分老建筑仍保留着清末民初的历史痕迹。', '上海', 31.231900, 121.484600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e5/A_picture_from_China_every_day_101.jpg"]'),
('《阿 Q 正传》', '虹口区山阴路 132 弄 9 号鲁迅故居', '鲁迅', '现代', '山阴路132弄9号鲁迅故居位于上海市虹口区，是鲁迅创作《阿Q正传》等重要作品的居所。这栋三层砖木结构的石库门建筑保留有鲁迅的书房、卧室与会客室，家具陈设按鲁迅生前原样布置。书桌上的台灯、砚台与毛笔仿佛主人刚刚离去。鲁迅在此度过了生命中最后的十年，写下了大量杂文与小说，与许广平、周海婴在此共同生活。故居所在的山阴路是一条安静的梧桐小道，两旁建筑保留着民国时期的风貌。此处是了解鲁迅晚年创作生涯与上海左翼文化运动的最重要文学故居。', '上海', 31.264700, 121.505000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/5b/Shanyin_Road_Shanghai_8-6-2012.jpg"]'),
('《祝福》', '虹口区鲁迅公园鲁迅纪念馆手稿厅', '鲁迅', '现代', '鲁迅公园鲁迅纪念馆手稿厅位于上海市虹口区，收藏有《祝福》原始手稿等珍贵文献。纪念馆保留有鲁迅手稿、照片、书信与生活用品，手稿厅中《祝福》的原始手稿展示了鲁迅严谨的创作过程——修改痕迹清晰可见，字迹刚劲有力。纪念馆建筑庄严肃穆，展厅以时间线串联鲁迅的文学生涯，从绍兴到北京、广州再到上海。鲁迅公园内古木参天，鲁迅墓庄严肃立，每年祭日仍有大量民众前来缅怀。此处是研究鲁迅文学创作手迹与了解中国现代文学发展历程的最权威文化殿堂。', '上海', 31.264700, 121.505000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/b/be/%E4%B8%8A%E6%B5%B7%E9%B2%81%E8%BF%85%E7%BA%AA%E5%BF%B5%E9%A6%86.jpg"]'),
('《从百草园到三味书屋》', '虹口区四川北路 2050 号内山书店旧址', '鲁迅', '现代', '四川北路2050号内山书店旧址位于上海市虹口区，是鲁迅晚年常去的书店，与《从百草园到三味书屋》的创作背景密切相关。内山书店由日本友人内山完造创办于1917年，保留有民国建筑、老书架与部分老书籍。鲁迅几乎每天都来此购书、会友、避难，书店成为鲁迅与进步文化人士的重要联络点。老书架上仍陈列着民国时期的书籍样本，木质地板因无数文人的脚步而光滑如镜。此处是虹口文化街区中最具文学纪念意义的地标，也是了解鲁迅在上海时期社交网络与左翼文化运动的珍贵历史遗存。', '上海', 31.264700, 121.505000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/76/DSC00371%E4%B8%8A%E6%B5%B7%E8%80%81%E5%BB%BA%E7%AD%91.jpg"]'),
('《倾城之恋》', '静安区常德路 195 号常德公寓旧址', '张爱玲', '现代', '常德路195号常德公寓旧址位于上海市静安区，是张爱玲故居，也是《倾城之恋》中白流苏居所的原型地。常德公寓建于1936年，意大利文艺复兴风格，张爱玲在此居住了六年（1939-1947年），写下了《倾城之恋》《金锁记》《红玫瑰与白玫瑰》等经典作品。公寓保留有民国电梯、铸铁栏杆与水磨石地面，六楼的张爱玲旧居窗户朝向常德路，透过窗帘可以看到街道上的梧桐树影。张爱玲笔下"上海苍凉的手势"在这栋公寓的每一个角落都能感受到。此处是上海文学朝圣者必访之地。', '上海', 31.228600, 121.448400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/8e/West_Nanjing_Road_from_29_July%2C_2022.jpg"]'),
('《金锁记》', '徐汇区武康路 113 号老洋房', '张爱玲', '现代', '武康路113号老洋房位于上海市徐汇区，是张爱玲《金锁记》中姜公馆的原型地。这栋建于民国时期的欧式洋房保留有精美的建筑立面、老花园与曲折的古巷，高大的围墙内庭院深深，梧桐枝叶探出墙头。武康路被誉为"上海最美马路"，两旁梧桐树形成绿色隧道，老洋房星罗棋布。张爱玲以冷峻的笔调描绘了姜公馆内曹七巧被封建礼教与黄金枷锁禁锢一生的悲剧，这些深宅大院正是那种压抑窒息氛围的完美空间载体。此处是感受张爱玲文学世界中上海旧式家族生活与武康路百年建筑之美的独特之地。', '上海', 31.188300, 121.436500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/cb/Wukang_Road_near_Huaihai_Road%2C_Shanghai.jpg"]'),
('《半生缘》', '黄浦区外滩源圆明园路老建筑群', '张爱玲', '现代', '外滩源圆明园路老建筑群位于上海市黄浦区，是张爱玲《半生缘》中顾曼桢与沈世钧相遇地的原型。圆明园路保留有清末民初的欧式建筑群，真光大楼、兰心大戏院等历史建筑错落排列，砖红色外墙与拱形窗户展现了殖民时期的建筑美学。张爱玲以细腻的笔触描绘了顾曼桢在外滩附近的办公与生活，那个时代的上海滩风情在此处的每一栋老建筑中凝固。黄浦江风从外滩吹来，老建筑在暮色中投下长长的影子。此处是感受张爱玲笔下"半生缘"中上海滩旧时光与外滩源历史建筑之美的浪漫之地。', '上海', 31.231900, 121.484600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/82/Yuanmingyuan_Apartments_Rockbund_Shanghai.JPG"]'),
('《长恨歌》', '静安区静安寺街道愚园路弄堂', '王安忆', '现代', '愚园路弄堂位于上海市静安区静安寺街道，是王安忆《长恨歌》中王琦瑶居所的原型地。弄堂保留有上海传统石库门建筑与老民居，红砖外墙、乌漆大门、天井晒台构成了最典型的上海弄堂空间。王安忆以王琦瑶的一生映射上海数十年的变迁，弄堂是她笔下最核心的空间意象——"上海的弄堂是壮观的景象"。清晨倒马桶的声响、午后晾衣竿上的旗袍、黄昏弄堂口的闲话，构成了上海市民生活的细密肌理。此处是了解上海弄堂文化与《长恨歌》中那个"有血有肉的上海"的最佳体验之地。', '上海', 31.228600, 121.448400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/8f/Yuyuan_Rd._Shanghai.JPG"]'),
('《长恨歌》', '黄浦区新天地石库门建筑群', '王安忆', '现代', '新天地石库门建筑群位于上海市黄浦区，是王安忆《长恨歌》中上海弄堂风情的另一原型地。新天地保留有清末民初的石库门建筑外观，红砖黑瓦、拱形门洞、雕花门楣展现了上海石库门建筑的精华。石库门是上海最具标志性的民居形式，融合了中式庭院与西式联排住宅的特点。王安忆在《长恨歌》中反复描绘的"上海的屋顶""上海的弄堂"在此处可以直观感受。虽然新天地已经过商业化改造，但石库门的建筑形态与空间格局基本保留，是了解上海石库门建筑历史与城市更新进程的标志性文化地标。', '上海', 31.231900, 121.484600, '其他', '["https://img1.baidu.com/it/u=1312437595,1249117367&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1422"]'),
('《繁花》', '静安区曹家渡街道长寿路弄堂', '金宇澄', '现代', '曹家渡街道长寿路弄堂位于上海市静安区，是金宇澄《繁花》中阿宝、沪生等人生活的原型地。弄堂保留有上海传统石库门建筑，亭子间、灶披间、晒台构成了《繁花》中人物活动的主要空间。金宇澄以沪语写就的《繁花》被誉为"上海的《清明上河图》"，曹家渡一带正是书中最重要的生活场景之一。弄堂里的小菜场、理发店、烟纸店飘出市井生活的烟火气。清晨买菜的阿姨、午后搓麻将的老人、黄昏遛狗的邻居构成了上海弄堂最真实的日常。此处是感受《繁花》中上海市民社会肌理的原生之地。', '上海', 31.228600, 121.448400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/df/Pudong_Shanghai_November_2017_panorama.jpg"]'),
('《繁花》', '黄浦区南京路步行街中段老商铺', '金宇澄', '现代', '南京路步行街中段老商铺位于上海市黄浦区，是金宇澄《繁花》中上海商业繁华的原型地。南京路中段保留有清末民初的商铺建筑与老柜台，永安公司、先施公司等百年老店的建筑立面见证了上海商业的黄金时代。金宇澄在《繁花》中多次描绘南京路的霓虹灯、橱窗与人流，将之作为上海物质文化的缩影。老商铺内的红木柜台、铜制秤砣、手写价签保留着民国时期的经营痕迹。此处是上海最具商业历史纵深感的街道，也是了解《繁花》中上海消费文化与城市记忆的重要地标。', '上海', 31.231900, 121.484600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/9f/East_Nanjing_Road_2020_%2850361842166%29.jpg"]'),
('《文化苦旅・上海人》', '黄浦区外滩万国建筑博览群北段', '余秋雨', '现代', '外滩万国建筑博览群北段位于上海市黄浦区，是余秋雨《文化苦旅·上海人》中上海历史的见证地。北段保留有清末民初的欧式建筑群，外滩信号台、俄罗斯领事馆等建筑展现了巴洛克、哥特式、新古典主义等多种风格。余秋雨以"上海人"为题探讨了上海城市性格的形成，而外滩正是这种开放、务实、精致性格的空间起点。黄浦江上汽笛长鸣，对岸陆家嘴天际线与此处的百年建筑遥相对望。此处是感受上海百年开埠史与中西文化交融的最经典地标，也是理解余秋雨笔下"上海文明"的最佳观察点。', '上海', 31.231900, 121.484600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e5/A_picture_from_China_every_day_101.jpg"]'),
('《上海的早晨》', '杨浦区杨树浦路 2800 号杨浦发电厂旧址', '周而复', '现代', '杨树浦路2800号杨浦发电厂旧址位于上海市杨浦区，是周而复《上海的早晨》中上海工业的原型地。杨浦发电厂建于1913年，是上海近代工业的标志性企业之一。保留有上世纪五十年代的厂房建筑、烟囱与发电机器设备，红砖厂房高大宏伟，工业管道纵横交错。周而复在《上海的早晨》中描绘了解放初期上海资本家与工人阶级之间的矛盾与改造，杨浦工业区正是那个火热年代的生产前线。此处如今已改造为杨浦滨江工业遗址公园，是了解上海近代工业史与社会主义改造历程的重要工业文化遗产。', '上海', 31.259800, 121.526100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/18/%E6%9D%A8%E6%A0%91%E6%B5%A6%E6%B0%B4%E5%8E%82.jpg"]'),
('《围城》', '徐汇区华山路 1954 号上海交通大学老校区', '钱钟书', '现代', '华山路1954号上海交通大学老校区位于上海市徐汇区，是钱钟书《围城》中三闾大学的原型地之一。老校区保留有民国时期的建筑群，包括老图书馆、执信西斋等历史建筑，红砖灰瓦，古樟树绿荫如盖。钱钟书以辛辣的讽刺笔法描绘了方鸿渐在三闾大学的荒诞经历，上海交大的民国校园氛围为小说提供了重要的空间想象。老图书馆内的木质书架、彩色玻璃窗与铜制台灯保留着学术殿堂的庄严感。此处是上海最具民国大学校园风貌的历史建筑群，也是感受《围城》中知识分子精神困境的文学地标。', '上海', 31.188300, 121.436500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/a/a6/SJTU_Xuhui_Campus_Gate.JPG"]'),
('《洗澡》', '杨浦区邯郸路 220 号复旦大学老校区', '杨绛', '现代', '邯郸路220号复旦大学老校区位于上海市杨浦区，是杨绛《洗澡》中知识分子生活的原型地。老校区保留有民国时期的建筑群，老图书馆、相辉堂等历史建筑掩映在古樟树与法国梧桐之间。杨绛在《洗澡》中以温婉而犀利的笔触描绘了知识分子在思想改造运动中的众生相，高校校园是其中最重要的叙事空间。老图书馆的阅览室里阳光透过高窗洒在长桌上，古樟树的清香飘入窗内。此处弥漫着深厚的学术气息，是了解中国知识分子精神史与上海高校百年历史的重要文化空间。', '上海', 31.259800, 121.526100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/5f/FuDanUni.jpg"]'),
('《青春之歌》', '杨浦区四平路 1239 号同济大学老校区', '杨沫', '现代', '四平路1239号同济大学老校区位于上海市杨浦区，是杨沫《青春之歌》中林道静参加革命的原型地之一。老校区保留有民国建筑、老礼堂与百年古樟树，建筑风格融合了德式严谨与中式雅致。杨沫在《青春之歌》中描绘了林道静从苦闷彷徨到投身革命的成长历程，大学校园是她思想觉醒的重要场所。老礼堂高大庄严，曾是学生运动集会的地方，墙上仍保留有革命标语的痕迹。古樟树下的林荫道曾见证了无数热血青年的激情岁月。此处是感受民国时期青年学生革命精神与上海高校历史的珍贵文化空间。', '上海', 31.259800, 121.526100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/2/26/Tongji_huabiao.jpg"]'),
('《上海屋檐下》', '静安区南京西路街道石库门弄堂', '夏衍', '现代', '南京西路街道石库门弄堂位于上海市静安区，是夏衍《上海屋檐下》中上海底层百姓生活的原型地。弄堂保留有上海传统石库门建筑，过街楼、天井、亭子间构成了最典型的上海市民居住空间。夏衍以一个屋檐下五户人家的故事，展现了抗战前夕上海底层市民的苦难与挣扎。弄堂里的水龙头前排队洗衣的妇女、天井里晾晒的被褥、灶披间飘出的油烟构成了最真实的上海市井画卷。此处虽然随着城市更新而逐渐减少，但残存的石库门弄堂仍是理解《上海屋檐下》中那个艰辛年代上海底层生活的最直接空间。', '上海', 31.228600, 121.448400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/df/Pudong_Shanghai_November_2017_panorama.jpg"]'),
('《雷雨》', '黄浦区外滩中山东一路 1 号老洋房', '曹禺', '现代', '中山东一路1号老洋房位于上海市黄浦区外滩，是曹禺《雷雨》中周朴园公馆的原型地。这栋清末民初的欧式洋房保留有精美的建筑立面、老花园与铸铁大门，巴洛克风格的雕饰华丽而庄重。曹禺以《雷雨》揭示了封建大家庭的虚伪与罪恶，周朴园的公馆是压迫与伪善的空间象征。洋房内高挑的天花板、水晶吊灯与暗色木饰营造出阴郁而压抑的氛围。外滩的黄浦江风从窗户吹入，汽笛声远远传来。此处是感受曹禺戏剧艺术中家族悲剧氛围与外滩百年建筑之美的独特文学地标。', '上海', 31.231900, 121.484600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/df/Pudong_Shanghai_November_2017_panorama.jpg"]'),
('《日出》', '静安区南京西路 1266 号老舞厅旧址', '曹禺', '现代', '南京西路1266号老舞厅旧址位于上海市静安区，是曹禺《日出》中陈白露生活的原型地。老舞厅保留有民国舞厅建筑、老舞池与老钢琴，水磨石地面光滑如镜，穹顶上的装饰画色彩斑斓。曹禺以《日出》揭示了上海十里洋场中交际花们光鲜背后的空虚与绝望，舞厅是那个纸醉金迷时代的典型空间。老钢琴的琴键泛黄，仿佛还能弹奏出爵士乐的旋律。民国时期的上海舞厅是名流社交的核心场所，霓虹灯下的舞步掩盖着一个时代的焦虑。此处是了解曹禺戏剧艺术与民国上海都市文化的珍贵历史遗存。', '上海', 31.228600, 121.448400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/8e/West_Nanjing_Road_from_29_July%2C_2022.jpg"]'),
('《林家铺子》', '黄浦区豫园老街老商铺', '茅盾', '现代', '豫园老街老商铺位于上海市黄浦区，是茅盾《林家铺子》中林老板商铺的原型地之一。老街保留有明清古商铺建筑、老柜台与传统招牌，飞檐翘角的建筑风格展现了上海老城厢的商业传统。茅盾在《林家铺子》中描绘了小商人在时代洪流中挣扎求存的悲剧命运，豫园老街的商铺格局正是那个时代小本经营的缩影。老柜台上的算盘、秤砣与账簿保留着传统经营的痕迹。此处虽已高度商业化，但部分老商铺的建筑形态与空间格局仍可辨识，是了解茅盾笔下小商人命运与上海老城厢商业文化的重要地标。', '上海', 31.231900, 121.484600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/df/Pudong_Shanghai_November_2017_panorama.jpg"]'),
('《春蚕》', '青浦区朱家角镇养蚕基地', '茅盾', '现代', '朱家角镇养蚕基地位于上海市青浦区，是茅盾《春蚕》中老通宝养蚕的原型地之一。基地保留有传统养蚕技艺与老蚕房，木质蚕架整齐排列，桑叶的清香弥漫在蚕房之中。茅盾在《春蚕》中描绘了农村蚕农辛勤劳作却最终破产的悲剧，揭示了帝国主义经济侵略对中国农村的深重影响。蚕房内蚕宝宝沙沙食桑的声音与窗外桑田的翠绿构成了江南水乡最质朴的农耕画面。朱家角古镇的水乡风情与传统养蚕技艺相得益彰，是了解中国传统蚕桑文化与茅盾农村三部曲历史背景的独特体验之地。', '上海', 31.150000, 121.124400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/9a/CADAL16051020_%E9%80%9A%E5%95%8F%E5%A0%B1.djvu"]'),
('《缘缘堂随笔》', '黄浦区陕西南路 39 弄 93 号丰子恺旧居', '丰子恺', '现代', '陕西南路39弄93号丰子恺旧居位于上海市黄浦区，是丰子恺创作《缘缘堂随笔》的居所。旧居保留有民国建筑、丰子恺漫画原作与古碑，小楼二层，庭院中种有丰子恺钟爱的芭蕉与杨柳。丰子恺以"人间情味"著称，他的漫画以简洁的线条勾勒出世间的温暖与善意。书房内的画案上仍陈列着毛笔与墨汁，墙上挂着他的代表作品复制品。旧居所在的陕西南路是一条安静的法租界老马路，梧桐树影婆娑。此处是感受丰子恺"不宠无惊过一生"的生活哲学与上海法租界文人生活氛围的温馨之地。', '上海', 31.231900, 121.484600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/4f/South_Shanxi_Rd._Shanghai.JPG"]'),
('《陶庵梦忆・城隍庙》', '松江区松江府城隍庙遗址', '张岱', '明代', '松江府城隍庙遗址位于上海市松江区，是张岱《陶庵梦忆·城隍庙》中描绘的民俗场景地。城隍庙保留有明代建筑构件、古碑与古戏台，殿宇中城隍像庄严端坐，香烟袅袅。张岱以精致的文笔记录了明代城隍庙会的盛况——戏台上锣鼓喧天，台下人山人海，小贩叫卖声不绝于耳。庙会是明代市民文化生活的重要组成部分，集宗教、娱乐、商业于一体。古戏台上的木雕精美绝伦，记载着数百年来梨园子弟的精彩演出。此处是了解明代江南城隍信仰与庙会民俗文化的重要遗存，也是走进张岱"繁华旧梦"的时光之门。', '上海', 31.032600, 121.227800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/a/a9/%E4%B8%9C%E6%96%B9%E6%9E%A2%E7%BA%BD%E5%8F%8A%E5%91%A8%E8%BE%B9%E5%9C%B0%E5%8C%BA%E4%B8%93%E9%A1%B9%E8%A7%84%E5%88%92%EF%BC%882025-2035%E5%B9%B4%EF%BC%89.pdf"]'),
('《西湖梦寻・湖心亭》', '黄浦区豫园湖心亭', '张岱', '明代', '豫园湖心亭位于上海市黄浦区，是张岱《西湖梦寻·湖心亭》描绘的园林意境在上海的映射之地。湖心亭保留有明代建筑遗迹、古碑与四季荷花池，九曲桥蜿蜒通向亭中。张岱在《湖心亭看雪》中描绘了雪夜独往湖心亭的孤绝之美，虽原文写的是西湖，但豫园湖心亭的意境与之遥相呼应。亭内品茗观景，窗外荷花池中锦鲤游弋，远处假山叠石巍然。四季景致各有韵味——春荷新绿、夏荷盛放、秋荷残叶、冬雪覆亭。此处是在上海感受张岱文人审美与明代园林意境的最佳之地。', '上海', 31.231900, 121.484600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/f/fa/%E8%B1%AB%E5%9B%AD%E6%B9%96%E5%BF%83%E4%BA%AD2024.5_%282%29.jpg"]'),
('《铁道游击队》', '宝山区淞沪抗战纪念馆', '刘知侠', '现代', '宝山区淞沪抗战纪念馆位于上海市宝山区，是刘知侠《铁道游击队》中上海抗日故事的背景地之一。纪念馆保留有抗日旧址、老照片、老武器与战争文物，展厅按照淞沪会战的时间线布展，再现了1932年一二八事变与1937年八一三抗战的惨烈场景。刘知侠虽以山东铁道游击队为主要叙事，但上海作为全面抗战的重要战场在书中多有涉及。纪念馆外的抗战纪念碑巍然矗立，碑文铭记着无数抗日将士的英名。此处是了解上海淞沪抗战史与中国人民抗日精神的庄严纪念地。', '上海', 31.405400, 121.489300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/b/b2/Shanghai_Memorial_Hall_for_Songhu_Battle.jpg"]'),
('《红日》', '宝山区吴淞口西炮台遗址', '吴强', '现代', '吴淞口西炮台遗址位于上海市宝山区，是吴强《红日》中上海抗日故事的背景地之一。西炮台始建于清代，保留有古炮台、大口径古炮与战壕遗迹，军事设施沿黄浦江入海口一字排开。吴强在《红日》中描绘了解放军英勇作战的壮阔场景，吴淞口作为上海的海上门户，自鸦片战争以来便是兵家必争之地。炮台上的古炮锈迹斑斑，炮口仍对准江面，无声诉说着百年海防的沧桑。站在炮台上远眺，长江浩荡入海，杂货船与巨型集装箱船穿行不息。此处是了解上海近代海防史与军事文化的重要遗存。', '上海', 31.405400, 121.489300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/35/%E4%B8%8A%E6%B5%B7%E5%B8%82%E5%AE%9D%E5%B1%B1%E5%8C%BA%E7%82%AE%E5%8F%B0%E5%B1%B1%E5%85%AC%E5%9B%AD_-_panoramio_%281%29.jpg"]'),
('《红旗谱》', '普陀区沪西工人文化宫旧址', '梁斌', '现代', '沪西工人文化宫旧址位于上海市普陀区，是梁斌《红旗谱》中上海工人运动的原型地。旧址保留有上世纪五十年代的建筑、老礼堂与工人活动场所，建筑风格体现了苏联援华时期的影响。梁斌在《红旗谱》中虽以河北保定为主要背景，但上海工人阶级的斗争精神在书中多有呼应。老礼堂内的木质座椅排列整齐，舞台上的红色帷幕已经褪色但仍庄严。墙上保留有上世纪五十年代的宣传画与工人运动的历史照片。此处是了解上海工人运动史与社会主义建设初期工人文化生活的重要历史遗存。', '上海', 31.249500, 121.397000, '其他', '["https://img2.baidu.com/it/u=4147723781,2635148895&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《上海掌故》', '黄浦区老城厢小南门遗址', '徐明庭', '现代', '老城厢小南门遗址位于上海市黄浦区，是徐明庭《上海掌故》中描绘的上海老城历史见证地。小南门是上海老城厢六座城门之一，保留有明代城墙残段、古炮与古碑，城砖上"大明洪武"的字样依稀可辨。徐明庭以掌故笔法记录了上海老城的街巷沿革、风俗掌故与名人轶事，小南门一带正是老上海市民生活的核心区域。城墙内外的生活差异曾是清末民初上海"华界"与"租界"之别的缩影。此处虽已大部分拆建，但残存的城墙与碑刻仍诉说着上海从县城到都会的六百年沧桑巨变，是了解上海城市根源的重要历史遗存。', '上海', 31.231900, 121.484600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/c1/%E5%85%89%E9%99%86%E5%A4%A7%E6%A5%BC%E5%8F%8A%E9%99%86%E5%AE%B6%E5%98%B4%C2%B7%E8%88%AA%E6%8B%8D.jpg"]');
INSERT INTO works (title, scenic_spot, author, dynasty, description, province, latitude, longitude, category, images) VALUES
('《望岳》', '泰安市泰山区泰山经石峪遗址', '杜甫', '唐代', '泰山经石峪遗址位于山东省泰安市泰山区，是杜甫《望岳》"会当凌绝顶，一览众山小"的核心取景地。经石峪保留有北齐时期刻于巨石之上的《金刚般若波罗蜜经》，字径五十厘米，为中国现存规模最大的摩崖石刻佛经。唐代文人墨客在此留下大量摩崖题刻，笔力遒劲。经石峪溪水潺潺流过刻经石面，"水石交融"的奇观令人叹为观止。杜甫青年时期登临泰山，写下千古名篇，那份"齐鲁青未了"的壮阔胸襟与豪迈气概在此处的巍峨山势中自然流露。此处是感受泰山石刻文化与唐诗壮美意境的绝佳之地。', '山东', 36.194900, 117.129000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/84/%E5%B1%B1%E4%B8%9C%E7%9C%81%E7%AC%AC%E5%9B%9B%E6%89%B9%E7%9C%81%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E5%90%8D%E5%8D%95%EF%BC%88%E5%85%B1%E8%AE%A1606%E5%A4%84%EF%BC%89.pdf"]'),
('《水调歌头・明月几时有》', '潍坊市诸城市超然台遗址', '苏轼', '北宋', '超然台遗址位于山东省潍坊市诸城市，是苏轼《水调歌头·明月几时有》"但愿人长久，千里共婵娟"的诞生地。超然台始建于北宋熙宁八年，苏轼任密州知州期间在此中秋饮酒赏月，思念弟弟苏辙而写下千古绝唱。遗址保留有宋代夯土台基与苏轼手书碑刻，台基高数米，登台可远眺诸城全城。"明月几时有，把酒问青天"的旷达情怀在此处的秋月之下格外动人。超然台之名取自老子"虽有荣观，燕处超然"，体现了苏轼超脱物外的人生哲学。此处是感受苏轼词作意境与宋代文人风骨的重要文学地标。', '山东', 35.996600, 119.410100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/b/b2/Zhucheng_tyrannosaurus_hall_2011_07_16.jpg"]'),
('《江城子・密州出猎》', '潍坊市诸城市常山狩猎台遗址', '苏轼', '北宋', '常山狩猎台遗址位于山东省潍坊市诸城市，是苏轼《江城子·密州出猎》"老夫聊发少年狂"的真实发生地。苏轼任密州知州时在常山组织围猎，"左牵黄，右擎苍"的豪迈场景便诞生于此。遗址保留有宋代夯土台基与古碑，台基宽阔平坦，四周山林环绕，适宜骑射狩猎。"持节云中，何日遣冯唐"既是苏轼的个人抱负，也是对国家命运的深切关怀。秋日登台远眺，山色苍翠，旷野辽阔，苏轼那份壮志豪情仿佛仍回荡在猎猎风中。此处是感受苏轼豪放词风与宋代文人武事情怀的独特历史遗存。', '山东', 35.996600, 119.410100, '其他', '["https://img0.baidu.com/it/u=1016649129,1443644664&fm=253&fmt=auto&app=120&f=JPEG?w=667&h=500"]'),
('《声声慢・寻寻觅觅》', '济南市章丘区百脉泉漱玉泉遗址', '李清照', '宋代', '百脉泉漱玉泉遗址位于山东省济南市章丘区，是李清照《声声慢·寻寻觅觅》的创作灵感之源。漱玉泉因李清照《漱玉集》而得名，泉水清澈甘冽，四季涌流不息。遗址保留有宋代泉眼、李清照故居与古碑，泉边垂柳拂水，荷花亭亭。李清照少年时期常在泉边洗笔研墨，"寻寻觅觅，冷冷清清"的千古名句蕴含了她晚年颠沛流离的深沉哀愁。泉水叮咚作响，仿佛在低吟这位千古才女的婉约词章。此处是了解李清照早年生活环境与"婉约派"词风源流的最重要文学故地。', '山东', 36.681300, 117.526300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/6/6c/%E6%BF%9F%E5%8D%97%E7%AB%A0%E4%B8%98%E7%99%BE%E8%84%88%E6%B3%89_2.jpg"]'),
('《如梦令・常记溪亭日暮》', '济南市章丘区百脉泉溪亭遗址', '李清照', '宋代', '百脉泉溪亭遗址位于山东省济南市章丘区，是李清照《如梦令·常记溪亭日暮》"沉醉不知归路"的描绘地。溪亭临水而建，保留有宋代亭基、古碑与荷花池，夏日荷花盛开时满池粉红。李清照少女时期与友人在溪亭饮酒赏花，"争渡争渡，惊起一滩鸥鹭"的欢快场景便发生于此。亭基石础尚存，周围溪水环绕，鸥鹭在芦苇丛中栖息。黄昏时分晚霞映照在荷塘水面，再现了词中"兴尽晚回舟"的诗意画面。此处是感受李清照少女时代天真烂漫与济南泉水文化的温馨之地。', '山东', 36.681300, 117.526300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/6/6c/%E6%BF%9F%E5%8D%97%E7%AB%A0%E4%B8%98%E7%99%BE%E8%84%88%E6%B3%89_2.jpg"]'),
('《破阵子・为陈同甫赋壮词以寄之》', '济南市历城区辛弃疾故居练兵场遗址', '辛弃疾', '宋代', '辛弃疾故居练兵场遗址位于山东省济南市历城区，是辛弃疾《破阵子·为陈同甫赋壮词以寄之》"醉里挑灯看剑"的原型地。辛弃疾少年时期在家乡练武习兵，保留有宋代夯土台基与古兵器陈列，练兵场宽阔平坦。"八百里分麾下炙，五十弦翻塞外声"的壮阔军旅想象源自辛弃疾年轻时率军南归的真实经历。遗址中陈列有宋代刀剑弓弩的复制品，墙上辛弃疾的生平介绍展现了这位"词中之龙"文武双全的传奇一生。此处是了解辛弃疾军事生涯与豪放词风的重要历史遗存。', '山东', 36.680000, 117.065200, '其他', '["https://img0.baidu.com/it/u=2926010766,839682947&fm=253&fmt=auto&app=120&f=JPEG?w=800&h=1067"]'),
('《永遇乐・京口北固亭怀古》', '济南市历城区辛弃疾纪念馆剑亭遗址', '辛弃疾', '宋代', '辛弃疾纪念馆剑亭遗址位于山东省济南市历城区，是辛弃疾《永遇乐·京口北固亭怀古》"想当年，金戈铁马，气吞万里如虎"有感而发之地。纪念馆保留有宋代古碑与辛弃疾雕像，剑亭中陈列有辛弃疾生平事迹与词作手迹。辛弃疾一生力主北伐收复中原，却壮志难酬，"廉颇老矣，尚能饭否"的悲愤在晚年愈发深沉。雕像中的辛弃疾持剑远望，目光坚定而苍凉。纪念馆四周古柏苍翠，肃穆庄严。此处是缅怀辛弃疾爱国精神与了解南宋抗金历史的重要文化场所。', '山东', 36.680000, 117.065200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/6/64/The_statue_of_Xin_Qiji.JPG"]'),
('《登兖州城楼》', '济宁市兖州区兖州城楼遗址', '杜甫', '唐代', '兖州城楼遗址位于山东省济宁市兖州区，是杜甫《登兖州城楼》"南楼纵目初"的创作地。城楼保留有明代建筑与古碑，登楼可远眺兖州古城全貌与护城河。杜甫青年时期"放荡齐赵间"，曾登临兖州城楼远望，写下"东郡趋庭日，南楼纵目初"的名句。护城河水波平如镜，倒映着城楼飞檐翘角的倩影。兖州自古为鲁南重镇，地处泗水之滨，交通要冲。城楼上俯瞰古城，街巷纵横，烟火人间，可感受杜甫早期诗作中的明朗开阔与青年意气。此处是了解杜甫早期游历与兖州古城历史的重要文学遗存。', '山东', 35.553100, 116.783700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e0/%E5%B1%B1%E4%B8%9C%E7%9C%81%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E7%AC%AC%E4%B8%89%E6%89%B9%E7%9C%81%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E5%90%8D%E5%8D%95%E7%9A%84%E9%80%9A%E7%9F%A5.pdf"]'),
('《沙丘城下寄杜甫》', '东营市广饶县沙丘城遗址', '李白', '唐代', '沙丘城遗址位于山东省东营市广饶县，是李白《沙丘城下寄杜甫》"高卧沙丘城"的居住之地。沙丘城保留有商周时期的夯土城墙与宫殿基址，城墙高大厚实，历经三千余年仍巍然屹立。李白与杜甫在此相聚后分别，"思君若汶水，浩荡寄南征"的深厚友情令人动容。古城遗址周围平原辽阔，汶水在远方缓缓南流。商周时期的陶片、青铜器残件散落在城址之中，见证了此地三千年文明史。此处既是李白杜甫"诗仙诗圣"友谊的见证地，也是研究商周时期齐地城邑制度的重要考古遗址。', '山东', 37.053600, 118.407100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e4/Xingtai_lying_cow_sculpture.jpg"]'),
('《鲁郡东石门送杜二甫》', '济宁市曲阜市石门山遗址', '李白', '唐代', '石门山遗址位于山东省济宁市曲阜市，是李白《鲁郡东石门送杜二甫》"飞蓬各自远，且尽手中杯"的惜别之地。石门山保留有唐代古寺与摩崖石刻，山势如门，两峰对峙。天宝四年秋，李白与杜甫在此饮酒话别，从此天各一方，再未相见。古寺钟声悠远，松柏苍翠，秋日红叶满山。摩崖石刻记载了历代文人到此凭吊"李杜惜别"的感怀之作。石门山距曲阜孔庙不远，儒风浸润之地更添文化厚度。此处是中国文学史上最令人感伤的告别之地，也是感受李白杜甫伟大友谊的永恒文学地标。', '山东', 35.580000, 116.986400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/84/%E5%B1%B1%E4%B8%9C%E7%9C%81%E7%AC%AC%E5%9B%9B%E6%89%B9%E7%9C%81%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E5%90%8D%E5%8D%95%EF%BC%88%E5%85%B1%E8%AE%A1606%E5%A4%84%EF%BC%89.pdf"]'),
('《登州海市》', '烟台市蓬莱区蓬莱阁观澜亭遗址', '苏轼', '北宋', '蓬莱阁观澜亭遗址位于山东省烟台市蓬莱区，是苏轼《登州海市》"群仙出没空明中"的描绘地。观澜亭是蓬莱阁中观海市蜃楼的最佳位置，保留有宋代亭基与历代碑刻。蓬莱阁自古有"仙境"之称，"八仙过海"的传说便源于此。苏轼任登州知府虽仅五日，却亲眼目睹海市蜃楼的奇观而写下此诗。亭上远眺渤海，碧波万顷，天际线处偶有幻影浮现。海风凛冽，波涛拍岸，丹崖绝壁下浪花飞溅。此处是中国海洋文化与仙道文化的重要象征地，也是感受苏轼笔下蓬莱仙境的最佳观景之所。', '山东', 37.810900, 120.758000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e0/%E5%B1%B1%E4%B8%9C%E7%9C%81%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E7%AC%AC%E4%B8%89%E6%89%B9%E7%9C%81%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E5%90%8D%E5%8D%95%E7%9A%84%E9%80%9A%E7%9F%A5.pdf"]'),
('《秋柳诗四首》', '济南市历下区大明湖秋柳园遗址', '王士祯', '清代', '大明湖秋柳园遗址位于山东省济南市历下区，是王士祯《秋柳诗四首》"残照西风白下门"的创作地。秋柳园保留有清代园林建筑、古碑与柳林，园内垂柳依依，秋风起时柳叶飘零。王士祯在此以"秋柳"为题写下四首七律，开创了清代"神韵说"诗学流派。大明湖水波粼粼，湖中荷叶残枝与岸边秋柳相映成趣。园中古碑刻有王士祯手书诗文，字体潇洒飘逸。济南自古有"泉城"之称，大明湖是泉水汇聚之地。此处是了解清代诗学流变与济南湖光秋色的重要文学园林。', '山东', 36.666400, 117.076800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/84/%E5%B1%B1%E4%B8%9C%E7%9C%81%E7%AC%AC%E5%9B%9B%E6%89%B9%E7%9C%81%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E5%90%8D%E5%8D%95%EF%BC%88%E5%85%B1%E8%AE%A1606%E5%A4%84%EF%BC%89.pdf"]'),
('《过历下亭》', '济南市历下区大明湖历下亭遗址', '孔尚任', '清代', '大明湖历下亭遗址位于山东省济南市历下区，是孔尚任《过历下亭》"济南名士多"的描绘地。历下亭保留有唐代亭基与清代碑刻，古柏苍翠环绕。历下亭始建于北魏，唐代杜甫曾在此与李邕宴饮，写下"海右此亭古，济南名士多"的千古名句。孔尚任在清初游历济南时重访历下亭，感慨济南文脉千年不绝。亭中陈列有历代名士题咏，碑刻林立。大明湖水从亭前缓缓流过，湖光山色尽收眼底。此处是济南文化史的浓缩之地，也是了解从杜甫到孔尚任千年文脉传承的重要文学地标。', '山东', 36.666400, 117.076800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/84/%E5%B1%B1%E4%B8%9C%E7%9C%81%E7%AC%AC%E5%9B%9B%E6%89%B9%E7%9C%81%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E5%90%8D%E5%8D%95%EF%BC%88%E5%85%B1%E8%AE%A1606%E5%A4%84%EF%BC%89.pdf"]'),
('《崂山观海》', '青岛市崂山区太清宫观海台遗址', '蒲松龄', '清代', '太清宫观海台遗址位于山东省青岛市崂山区，是蒲松龄《崂山观海》"忽闻海上有仙山"的创作地。太清宫保留有明代道观建筑、古碑与摩崖石刻，观海台建于悬崖之上，三面临海。蒲松龄曾在崂山道观借住数月，搜集民间故事素材，《聊斋志异》中的"崂山道士"等篇章便诞生于此。站在观海台上，东海碧波万顷，海天一色，仙山缥缈之感油然而生。太清宫内古松盘虬，香烟袅袅，道教仙风与海洋气象在此交融。此处是感受蒲松龄《聊斋》仙怪美学与崂山海天奇观的绝佳之地。', '山东', 36.107400, 120.469300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/3d/Entrance_-_panoramio_%2814%29.jpg"]'),
('《题柳泉》', '淄博市淄川区蒲松龄故居柳泉遗址', '蒲松龄', '清代', '蒲松龄故居柳泉遗址位于山东省淄博市淄川区，是蒲松龄"聊斋先生"雅号的由来之地。柳泉保留有清代泉眼、古碑与蒲松龄故居，泉边古柳垂荫，泉水清冽甘甜。蒲松龄常年在柳泉边摆茶摊，以茶换故事，搜集各地奇闻异事，最终写就旷世名著《聊斋志异》。故居为典型的鲁中民居，正房三间，书房中的桌椅笔砚保留着蒲松龄当年的创作场景。"写鬼写妖高人一等，刺贪刺虐入骨三分"的对联悬于堂上。此处是了解蒲松龄一生清贫而伟大的文学创作历程的最核心文学故地。', '山东', 36.643400, 117.966600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/a/a9/Pu_Songling.jpg"]'),
('《登泰山》', '泰安市泰山区泰山后石坞遗址', '姚鼐', '清代', '泰山后石坞遗址位于山东省泰安市泰山区，是姚鼐《登泰山》"苍山负雪，明烛天南"的核心取景地。后石坞保留有明代古寺与摩崖石刻，位于泰山后山幽深处，游客稀少。姚鼐在大雪初霁时登临泰山，看到"苍山负雪，明烛天南"的壮丽雪景而写下这篇桐城派散文名篇。冬日清晨站在后石坞远望，泰山积雪皑皑，日出时金光万道照彻南方天际。松柏在雪中苍翠挺拔，石壁上的摩崖石刻被白雪半掩。此处是感受姚鼐散文中泰山雪景之壮美与桐城派"义理考据辞章"文学理念的幽静之地。', '山东', 36.194900, 117.129000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/f/ff/%E5%B1%B1%E4%B8%9C%E7%9C%81%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E7%AC%AC%E5%85%AD%E6%89%B9%E7%9C%81%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E3%80%81%E7%AC%AC%E4%B8%80%E6%89%B9%E6%B0%B4%E4%B8%8B%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8C%BA%E7%9A%84%E9%80%9A%E7%9F%A5%EF%BC%88%E9%B2%81%E6%94%BF%E5%AD%97%E3%80%942022%E3%80%9518%E5%8F%B7%EF%BC%89.pdf"]'),
('《观沧海》', '滨州市无棣县碣石山遗址', '曹操', '东汉', '碣石山遗址位于山东省滨州市无棣县，是曹操《观沧海》"东临碣石，以观沧海"的创作地。碣石山保留有汉代夯土台基与古碑，山虽不高但气势雄浑，是曹操北征乌桓大胜后班师途中登临之地。"日月之行，若出其中；星汉灿烂，若出其里"展现了曹操吞吐天地的宏大气魄。山顶远眺渤海，海天苍茫无际。汉代夯土台基历经两千年风雨仍清晰可辨，见证了建安时代的金戈铁马。此处是感受曹操帝王气概与建安风骨的最重要文学遗迹，也是中国文学史上山海意象的经典发源地。', '山东', 37.770300, 117.625700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e1/%E6%BB%A8%E5%B7%9E%E5%B8%82.jpg"]'),
('《蒿里行》', '济宁市兖州区兖州古城遗址', '曹操', '东汉', '兖州古城遗址位于山东省济宁市兖州区，是曹操《蒿里行》"白骨露于野，千里无鸡鸣"的描绘地。古城保留有汉代夯土城墙与宫殿基址，城墙残高数米，夯土层次分明。曹操以《蒿里行》描写了东汉末年军阀混战导致的惨烈民生，兖州作为曹操早期根据地，见证了那个战火纷飞的年代。古城遗址周围平原辽阔，秋风萧瑟时"白骨露于野"的惨状仿佛仍在眼前。遗址中出土有汉代铁器、陶罐等文物。此处是了解东汉末年战乱历史与曹操早期军事生涯的重要考古遗址。', '山东', 35.553100, 116.783700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/84/%E5%B1%B1%E4%B8%9C%E7%9C%81%E7%AC%AC%E5%9B%9B%E6%89%B9%E7%9C%81%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E5%90%8D%E5%8D%95%EF%BC%88%E5%85%B1%E8%AE%A1606%E5%A4%84%EF%BC%89.pdf"]'),
('《九月九日忆山东兄弟》', '济南市历下区千佛山重阳阁遗址', '王维', '唐代', '千佛山重阳阁遗址位于山东省济南市历下区，是王维《九月九日忆山东兄弟》创作的背景地。重阳阁保留有唐代阁基、古碑与古柏，登阁可远眺济南全城与大明湖。王维在长安思念家乡时写下"每逢佳节倍思亲"的千古名句，千佛山正是他故乡记忆中的重要意象。重阳节登高远望是中国传统习俗，千佛山上遍植茱萸，秋日红遍山坡。古柏苍翠挺拔，阁基石础尚存，诉说着千年前游子思乡的深情。此处是感受王维思乡之情与济南秋日登高文化的重要文学遗存。', '山东', 36.666400, 117.076800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/4b/China_Jinan_5196975.jpg"]'),
('《别董大・其一》', '济南市历下区大明湖历下亭遗址', '高适', '唐代', '大明湖历下亭遗址也是高适《别董大·其一》"莫愁前路无知己，天下谁人不识君"的送别之地。高适在济南送别琴师董庭兰，以豪迈的笔调写下这首千古送别诗。历下亭保留有唐代亭基与清代碑刻，亭前大明湖水波浩渺。与一般送别诗的凄凉不同，高适以"天下谁人不识君"的豪情壮语鼓励友人，展现了盛唐文人的开阔胸襟。大明湖畔秋风起时，湖水拍岸，柳叶纷飞，那份送别的洒脱与深情在湖光山色中历久弥新。此处是感受盛唐送别文化与高适豪放诗风的重要文学地标。', '山东', 36.666400, 117.076800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/84/%E5%B1%B1%E4%B8%9C%E7%9C%81%E7%AC%AC%E5%9B%9B%E6%89%B9%E7%9C%81%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E5%90%8D%E5%8D%95%EF%BC%88%E5%85%B1%E8%AE%A1606%E5%A4%84%EF%BC%89.pdf"]'),
('《望洞庭湖赠张丞相》', '济宁市微山县微山湖微山岛遗址', '孟浩然', '唐代', '微山湖微山岛遗址位于山东省济宁市微山县，是孟浩然《望洞庭湖赠张丞相》的原型地之一。微山岛保留有汉代古墓葬、古碑与古码头，岛上古木参天，四面环水。微山湖为中国北方最大的淡水湖之一，"气蒸云梦泽，波撼岳阳城"的壮阔虽写洞庭，但微山湖的浩渺水面同样能引发孟浩然的湖海之思。湖面芦苇荡漾，渔舟唱晚，候鸟季节万鸟齐飞。岛上汉代古墓出土有精美的画像石。此处是感受北方湖泊壮美与孟浩然田园山水诗意的独特之地。', '山东', 34.806600, 117.128800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/84/%E5%B1%B1%E4%B8%9C%E7%9C%81%E7%AC%AC%E5%9B%9B%E6%89%B9%E7%9C%81%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E5%90%8D%E5%8D%95%EF%BC%88%E5%85%B1%E8%AE%A1606%E5%A4%84%EF%BC%89.pdf"]'),
('《送杜十四之江南》', '济宁市任城区运河古渡遗址', '孟浩然', '唐代', '运河古渡遗址位于山东省济宁市任城区，是孟浩然《送杜十四之江南》"君去春江正淼茫"的送别地。古渡保留有明清古码头与古碑，石阶延伸入运河水中，码头建筑斑驳苍老。京杭大运河在济宁段水面开阔，自古为南北交通要道。孟浩然在此送别友人南下江南，"日暮征帆何处泊，天涯一望断人肠"的离愁在运河的浩荡水面上弥漫开来。春日运河两岸柳绿桃红，舟楫往来不绝。此处是感受唐代运河送别文化与济宁段运河千年漕运历史的重要文学遗存。', '山东', 35.414400, 116.595600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/eb/Jining_Railway_Station_2015.08.13_18-47-54.jpg"]'),
('《登常山绝顶广丽亭》', '潍坊市诸城市常山广丽亭遗址', '苏轼', '北宋', '常山广丽亭遗址位于山东省潍坊市诸城市，是苏轼《登常山绝顶广丽亭》"西望穆陵关"的观景点。广丽亭保留有宋代亭基、古碑与古柏，位于常山之巅，视野辽阔。苏轼任密州知州时常登常山远望，"一山奔来西北骛，万马回旋不可御"的壮丽山势令他豪兴大发。亭上西望穆陵关方向，山峦起伏如万马奔腾。苏轼在密州期间政绩卓著，治蝗救灾，深受百姓爱戴。常山虽不高大，却因苏轼的登临而名垂千古。此处是感受苏轼密州时期壮怀激烈与诸城山水之美的重要文学遗存。', '山东', 35.996600, 119.410100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e8/Quzhou_chengqiang_9499.jpg"]'),
('《醉花阴・薄雾浓云愁永昼》', '济南市章丘区百脉泉李清照故居', '李清照', '宋代', '百脉泉李清照故居位于山东省济南市章丘区，是李清照《醉花阴·薄雾浓云愁永昼》"人比黄花瘦"的创作地。故居保留有宋代建筑风格的纪念馆、古碑与生平陈列，展示了李清照从章丘才女到流落江南的传奇一生。"东篱把酒黄昏后，有暗香盈袖"描绘了重阳节独自赏菊的寂寞与相思。故居内菊花园每到秋季金黄灿烂，百脉泉水从园边潺潺流过。李清照被誉为"千古第一才女"，其词作兼具婉约之美与家国之愁。此处是全面了解李清照生平与词作艺术的最重要纪念场所。', '山东', 36.681300, 117.526300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/4b/China_Jinan_5196975.jpg"]'),
('《少陵台》', '济宁市兖州区少陵台遗址', '杜甫', '唐代', '少陵台遗址位于山东省济宁市兖州区，是杜甫"少陵野老"别号的渊源之地。少陵台保留有唐代夯土台基、古碑与杜甫纪念馆，"浮云连海岱，平野入青徐"的壮阔景象从台上可以感受。杜甫青年时期在兖州居住多年，其父杜闲曾任兖州司马，少陵台是杜甫登高远望的常去之地。台基高耸，四望开阔，鲁南平原一望无际。纪念馆中陈列有杜甫在兖州时期的诗作与生平事迹。此处是了解杜甫早年生活与"少陵"别号由来的重要文学遗存，也是追寻"诗圣"青年足迹的起点。', '山东', 35.553100, 116.783700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e3/%E5%B1%B1%E4%B8%9C%E7%9C%81%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E7%AC%AC%E4%BA%94%E6%89%B9%E7%9C%81%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E7%9A%84%E9%80%9A%E7%9F%A5%EF%BC%88%E9%B2%81%E6%94%BF%E5%AD%97%E3%80%942015%E3%80%95142%E5%8F%B7%EF%BC%89.pdf"]'),
('《鲁台》', '泰安市泰山区泰山鲁台遗址', '李白', '唐代', '泰山鲁台遗址位于山东省泰安市泰山区，是李白"疑是白波涨东海"的描绘地。鲁台保留有唐代夯土台基、古碑与摩崖石刻，位于泰山山腰处，视野开阔。李白曾多次游历泰山，在鲁台上远眺东方，云海翻涌如白浪滔天，"疑是白波涨东海"的壮观景象由此而来。台基石础上刻有唐代文人题记，笔力雄健。清晨日出时分，金光穿透云层洒在鲁台之上，泰山"五岳之首"的雄浑气魄尽显无遗。此处是感受李白浪漫诗风与泰山云海奇观的独特观景之地。', '山东', 36.194900, 117.129000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/f/ff/%E5%B1%B1%E4%B8%9C%E7%9C%81%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E7%AC%AC%E5%85%AD%E6%89%B9%E7%9C%81%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E3%80%81%E7%AC%AC%E4%B8%80%E6%89%B9%E6%B0%B4%E4%B8%8B%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8C%BA%E7%9A%84%E9%80%9A%E7%9F%A5%EF%BC%88%E9%B2%81%E6%94%BF%E5%AD%97%E3%80%942022%E3%80%9518%E5%8F%B7%EF%BC%89.pdf"]'),
('《有的人》', '潍坊市诸城市臧克家故居遗址', '臧克家', '现代', '臧克家故居遗址位于山东省潍坊市诸城市，是臧克家创作《有的人》的背景地。故居保留有清代建筑、古碑与臧克家生平陈列，院落典雅，古朴幽静。臧克家以"有的人活着，他已经死了；有的人死了，他还活着"的诗句纪念鲁迅，成为中国现代诗歌中最脍炙人口的名篇。故居中陈列有臧克家的手稿、照片与书信，展示了这位"农民诗人"从诸城走向全国文坛的历程。院中古树参天，石径通幽。此处是了解臧克家文学创作与诸城人文传统的重要文学故居。', '山东', 35.996600, 119.410100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/ee/%E5%B1%B1%E4%B8%9C%E7%9C%81%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E7%AC%AC%E5%9B%9B%E6%89%B9%E7%9C%81%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E7%9A%84%E9%80%9A%E7%9F%A5%EF%BC%88%E9%B2%81%E6%94%BF%E5%AD%97%E3%80%942013%E3%80%95204%E5%8F%B7%EF%BC%89.pdf"]'),
('《老马》', '潍坊市诸城市臧克家故居老院遗址', '臧克家', '现代', '臧克家故居老院遗址位于山东省潍坊市诸城市，是臧克家《老马》的创作原型地。老院保留有清代民居建筑、老农具与古碑，院中石磨、水井、谷仓保留着鲁东南农村的原始生活场景。"总得叫大车装个够，它横竖不说一句话"——臧克家以老马比喻旧社会被压迫的中国农民，沉重而深刻。老院周围的田野在秋收时节金黄一片，农民辛勤劳作的身影与诗中的意象高度吻合。故居老院与前方的臧克家故居遥相呼应，共同构成了了解这位"农民诗人"创作根源的文化空间。', '山东', 35.996600, 119.410100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/ee/%E5%B1%B1%E4%B8%9C%E7%9C%81%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E7%AC%AC%E5%9B%9B%E6%89%B9%E7%9C%81%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E7%9A%84%E9%80%9A%E7%9F%A5%EF%BC%88%E9%B2%81%E6%94%BF%E5%AD%97%E3%80%942013%E3%80%95204%E5%8F%B7%EF%BC%89.pdf"]'),
('《咏柳》', '济南市历下区大明湖柳岸遗址', '贺知章', '唐代', '大明湖柳岸遗址位于山东省济南市历下区，是贺知章《咏柳》创作的原型地。柳岸保留有唐代古柳遗存、古碑与古桥，大明湖畔垂柳千株，春日新柳如烟似雾。"碧玉妆成一树高，万条垂下绿丝绦"的优美意象在此处完美呈现。春风拂过湖面，柳条随风摇曳如舞蹈，"不知细叶谁裁出，二月春风似剪刀"的精妙比喻令人拍案叫绝。大明湖水碧波荡漾，柳影婆娑倒映水中。济南自古有"四面荷花三面柳"的美誉，柳岸正是这一美景的集中体现。此处是感受贺知章咏物诗艺术与济南春日柳色之美的经典之地。', '山东', 36.666400, 117.076800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/74/%E6%B5%8E%E5%8D%97%E5%A4%A7%E6%98%8E%E6%B9%96%E7%89%8C%E5%8C%BE%E5%A4%9C%E6%99%AF.jpg"]'),
('《春晓》', '青岛市崂山区仰口春晓遗址', '孟浩然', '唐代', '崂山仰口春晓遗址位于山东省青岛市崂山区，是孟浩然《春晓》"春眠不觉晓"的意境映射之地。仰口保留有明代古寺、古碑与观海亭，面朝黄海，春日晨曦温柔地照进山谷。"处处闻啼鸟"的场景在此完美呈现——山林中百鸟争鸣，海风送来花香与潮声。"夜来风雨声，花知多少"的春日感伤在崂山的山花烂漫中更添诗意。观海亭上远眺东海，水天一色，帆影点点。仰口湾的海水碧蓝如洗，礁石上海浪拍击。此处将崂山的山海之美与孟浩然田园诗的清新意境完美融合，是春日海滨踏青的绝佳之地。', '山东', 36.107400, 120.469300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/91/%E5%A4%A7%E9%81%8B%E6%B2%B3.png"]'),
('《红高粱家族》', '潍坊市高密市东北乡孙家口伏击战遗址', '莫言', '现代', '孙家口伏击战遗址位于山东省潍坊市高密市东北乡，是莫言《红高粱家族》中"高粱地伏击战"的真实原型地。1938年抗日武装在孙家口伏击日军车队，这场战斗成为《红高粱》中最壮烈的场景。遗址保留有抗日战争时期的公路与古桥，公路两侧是一望无际的高粱地。莫言以魔幻现实主义手法将这场战斗升华为民族精神的象征——"我奶奶"与"我爷爷"在高粱地中的生死爱情与抗日壮举惊天动地。秋日高粱红遍原野时，站在古桥上远望，莫言笔下"红高粱"的壮烈与浪漫扑面而来。此处是感受莫言文学世界与高密东北乡抗日精神的核心之地。', '山东', 36.382900, 119.752600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e3/%E5%B1%B1%E4%B8%9C%E7%9C%81%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E7%AC%AC%E4%BA%94%E6%89%B9%E7%9C%81%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E7%9A%84%E9%80%9A%E7%9F%A5%EF%BC%88%E9%B2%81%E6%94%BF%E5%AD%97%E3%80%942015%E3%80%95142%E5%8F%B7%EF%BC%89.pdf"]'),
('《红高粱家族》', '潍坊市高密市东北乡单家大院遗址', '莫言', '现代', '单家大院遗址位于山东省潍坊市高密市东北乡，是莫言《红高粱家族》中九儿与余占鳌生活的原型地。大院保留有清末民初的鲁东南民居建筑与老作坊，四合院格局方正，青砖灰瓦，屋脊上的兽头雕刻精美。莫言以九儿的传奇一生为主线，将高密东北乡塑造为一片充满野性与生命力的热土。老作坊中的酿酒器具、石磨与大缸保留着传统手工酿酒的痕迹，"十八里红"高粱酒的故事便源于此。院落周围高粱田在秋风中摇曳如火海。此处是了解莫言文学原乡与鲁东南乡村生活的重要文学遗存。', '山东', 36.382900, 119.752600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/84/%E5%B1%B1%E4%B8%9C%E7%9C%81%E7%AC%AC%E5%9B%9B%E6%89%B9%E7%9C%81%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E5%90%8D%E5%8D%95%EF%BC%88%E5%85%B1%E8%AE%A1606%E5%A4%84%EF%BC%89.pdf"]'),
('《檀香刑》', '潍坊市高密市东北乡茂腔大剧院遗址', '莫言', '现代', '茂腔大剧院遗址位于山东省潍坊市高密市东北乡，是莫言《檀香刑》中猫腔戏班的原型地。遗址保留有清代戏台、老戏服与古碑，戏台飞檐翘角，台面青砖铺就。莫言在《檀香刑》中将高密茂腔这一地方戏曲融入小说叙事，"猫腔"的凄厉唱腔成为全书的灵魂。茂腔源自清代，以其独特的哭腔著称，被称为"拴老婆橛子"，深受高密妇女喜爱。老戏服色彩斑斓但已褪色，见证了茂腔艺术百年来的兴衰。此处是了解莫言戏曲叙事艺术与高密茂腔非物质文化遗产的独特文学场所。', '山东', 36.382900, 119.752600, '其他', '["https://img1.baidu.com/it/u=2230917090,1398501758&fm=253&fmt=auto&app=138&f=JPEG?w=750&h=500"]'),
('《生死疲劳》', '潍坊市高密市东北乡蓝脸故居遗址', '莫言', '现代', '蓝脸故居遗址位于山东省潍坊市高密市东北乡，是莫言《生死疲劳》中蓝脸单干户的原型地。故居保留有清末民初的鲁东南民居、老农具与古碑，院中石磨、犁耙、风车保留着中国传统农耕的原始场景。莫言以六道轮回的魔幻结构讲述了蓝脸一家与中国农村半个世纪的纠缠——从土地改革到人民公社再到改革开放。蓝脸是全村唯一坚持单干的农民，这份固执与坚守成为莫言笔下中国农民精神的缩影。此处是了解莫言"高密东北乡"文学版图与中国农村变迁史的重要文学遗存。', '山东', 36.382900, 119.752600, '其他', '["https://img2.baidu.com/it/u=1406530723,2832694999&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1423"]'),
('《聊斋志异》', '淄博市淄川区蒲松龄故居柳泉遗址', '蒲松龄', '清代', '蒲松龄故居柳泉遗址也是《聊斋志异》整部作品的核心创作地。蒲松龄在柳泉边设茶摊数十年，"写鬼写妖高人一等，刺贪刺虐入骨三分"的文学精神在此孕育。故居保留有清代建筑、蒲松龄书房与柳泉泉眼，书房中的笔砚纸墨仿佛主人刚刚搁笔。蒲松龄一生科举不第，却将满腹才华倾注于民间故事的搜集与创作，最终成就了中国文言小说的巅峰之作。柳泉水清冽甘甜，古柳垂荫，蒲松龄当年在此"以茶换故事"的场景仿佛历历在目。此处是中国文言小说史上最重要的创作圣地。', '山东', 36.643400, 117.966600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/a/a9/Pu_Songling.jpg"]'),
('《聊斋志异・崂山道士》', '青岛市崂山区太清宫三皇殿遗址', '蒲松龄', '清代', '太清宫三皇殿遗址位于山东省青岛市崂山区，是蒲松龄《聊斋志异·崂山道士》中王七学道的原型地。三皇殿保留有明代道观建筑、古碑与摩崖石刻，殿宇依山而建，面朝东海。蒲松龄在崂山借住期间听闻道士穿墙而过的传说，写就了这篇脍炙人口的故事。"穿墙术"寓意世人心术不正则法术不灵，讽刺深刻。殿内供奉伏羲、神农、黄帝三皇像，道教香火千年不绝。殿外古松盘虬卧龙，海风吹来松涛阵阵，仙气飘渺。此处是感受蒲松龄仙怪文学想象力与崂山道教文化的绝佳之地。', '山东', 36.107400, 120.469300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e3/%E5%B1%B1%E4%B8%9C%E7%9C%81%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E7%AC%AC%E4%BA%94%E6%89%B9%E7%9C%81%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E7%9A%84%E9%80%9A%E7%9F%A5%EF%BC%88%E9%B2%81%E6%94%BF%E5%AD%97%E3%80%942015%E3%80%95142%E5%8F%B7%EF%BC%89.pdf"]'),
('《聊斋志异・婴宁》', '淄博市淄川区聊斋园狐仙园遗址', '蒲松龄', '清代', '聊斋园狐仙园遗址位于山东省淄博市淄川区，是蒲松龄《聊斋志异·婴宁》中狐仙居住之地的文学映射。园中保留有清代园林建筑、古碑与狐仙雕塑，假山洞穴、花木扶疏，营造出亦真亦幻的聊斋意境。婴宁是《聊斋》中最动人的女性形象——天真烂漫，爱笑如花，她居住的"小桃源"在聊斋园中得到了生动再现。园内遍植桃花与芍药，春日花开时满园芬芳，"笑声"仿佛在花丛中回荡。蒲松龄以"异史氏"的笔法赋予狐仙以人的情感与美德。此处是走进蒲松龄奇幻文学世界的沉浸式体验空间。', '山东', 36.643400, 117.966600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/a/a9/Pu_Songling.jpg"]'),
('《水浒传》', '聊城市阳谷县景阳冈山神庙遗址', '施耐庵', '明代', '景阳冈山神庙遗址位于山东省聊城市阳谷县，是施耐庵《水浒传》中武松打虎的核心场景地。遗址保留有宋代庙基、古碑与"武松打虎处"石碑，山神庙前的老松树虬枝苍劲。武松在景阳冈酒店"三碗不过冈"后醉酒上山，在山神庙前与猛虎搏斗的情节是《水浒传》中最惊心动魄的场景之一。冈上林木茂密，秋日落叶铺满小径。"武松打虎"已成为中国文化中英雄主义的经典象征。此处虽已无猛虎出没，但山冈的苍莽气势与古碑的斑驳字迹仍能唤起"打虎英雄"的豪迈气概。', '山东', 36.114300, 115.791500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/4b/China_Jinan_5196975.jpg"]'),
('《水浒传》', '济宁市梁山县梁山寨断金亭遗址', '施耐庵', '明代', '梁山寨断金亭遗址位于山东省济宁市梁山县，是施耐庵《水浒传》中林冲火并王伦的场景地。断金亭保留有宋代亭基、古碑与摩崖石刻，位于梁山之巅，俯瞰八百里水泊。"火并王伦"是梁山泊从草寇小寨发展为替天行道聚义之地的关键转折。梁山虽然海拔不高，但山势陡峭，易守难攻，"水浒"之名便源于山下广袤的水泊。登顶远望，鲁西平原一望无际，当年八百里水泊虽已缩小，但水光潋滟仍可感受。此处是中国古典文学中"绿林好汉"精神的象征之地。', '山东', 35.802400, 116.096100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/56/File-The_Temple_of_Duke_Zhou2.jpg"]'),
('《水浒传》', '泰安市东平县东平湖聚义岛遗址', '施耐庵', '明代', '东平湖聚义岛遗址位于山东省泰安市东平县，是施耐庵《水浒传》中梁山好汉聚义的场景地。聚义岛保留有宋代夯土台基、古碑与聚义厅遗址，岛上古木参天，四面环水。东平湖是古代梁山泊的残留水面，"八百里水泊梁山"的壮阔在此仍可想见。一百零八位好汉在聚义厅中"替天行道"的壮举是中国文学史上最壮观的群英会。湖面烟波浩渺，渔舟点点，芦苇荡随风摇曳。春日湖上薄雾缭绕，秋日湖面金波荡漾。此处是感受《水浒传》豪杰义气与水泊梁山千年传奇的最佳实地体验之所。', '山东', 35.940000, 116.470000, '其他', '["https://img0.baidu.com/it/u=2089697815,314445193&fm=253&fmt=auto&app=138&f=JPEG?w=655&h=427"]'),
('《古船》', '烟台市龙口市屺姆岛老码头遗址', '张炜', '现代', '屺姆岛老码头遗址位于山东省烟台市龙口市，是张炜《古船》中隋抱朴家族兴衰故事的背景地。老码头保留有清末民初的码头建筑与老仓库，石阶延伸入海，铁制缆桩锈迹斑斑。张炜在《古船》中以胶东海边小镇的粉丝作坊为背景，讲述了隋、赵、李三大家族半个世纪的恩怨纠葛。"古船"既是实物，也是中国乡村文明在时代洪流中漂泊的隐喻。码头上远眺渤海，海天一色，渔船往来。老仓库中的粉丝晾晒架见证了胶东传统手工业的辉煌。此处是了解张炜文学世界与胶东海洋文化的重要文学遗存。', '山东', 37.646100, 120.477800, '其他', '["https://img1.baidu.com/it/u=98381974,305988406&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《你在高原》', '烟台市栖霞市牙山国家森林公园遗址', '张炜', '现代', '牙山国家森林公园遗址位于山东省烟台市栖霞市，是张炜《你在高原》中宁伽生活的背景地。森林公园保留有清代古寺、古驿道与革命旧址，山势巍峨，林木葱郁。张炜耗时二十余年写就的《你在高原》是中国当代文学史上最长的长篇小说，宁伽在胶东高原上的行走与思考贯穿全书。古驿道蜿蜒在山脊之上，两侧古松如卫兵列阵。森林中负氧离子含量极高，溪流潺潺，鸟鸣啾啾。革命旧址记载了胶东红色革命的历史。此处是感受张炜文学中"高原精神"与胶东山林自然之美的幽静之地。', '山东', 37.307100, 120.849700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/c7/Wugongshan_8350.jpg"]'),
('《苦菜花》', '威海市乳山市昆嵛山无染寺遗址', '冯德英', '现代', '昆嵛山无染寺遗址位于山东省威海市乳山市，是冯德英《苦菜花》中抗日故事的核心背景地。无染寺始建于唐代，保留有唐代古寺建筑遗迹、革命旧址与飞瀑流泉。冯德英以昆嵛山区为背景，讲述了抗日战争时期胶东农村母亲带领子女与日寇斗争的壮烈故事。"苦菜花"象征着中国农村妇女在苦难中绽放的坚韧生命力。寺院幽深静谧，瀑布从山崖飞泻而下，水声轰鸣。昆嵛山是胶东革命的摇篮，红色基因与千年古刹在此交融。此处是感受胶东抗日精神与昆嵛山水之美的重要红色文学遗存。', '山东', 36.919500, 121.539500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e3/%E5%B1%B1%E4%B8%9C%E7%9C%81%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E7%AC%AC%E4%BA%94%E6%89%B9%E7%9C%81%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E7%9A%84%E9%80%9A%E7%9F%A5%EF%BC%88%E9%B2%81%E6%94%BF%E5%AD%97%E3%80%942015%E3%80%95142%E5%8F%B7%EF%BC%89.pdf"]'),
('《迎春花》', '威海市乳山市昆嵛山烟霞洞遗址', '冯德英', '现代', '昆嵛山烟霞洞遗址位于山东省威海市乳山市，是冯德英《迎春花》中共产党员秘密活动的场景地。烟霞洞保留有唐代石窟、革命旧址与古碑，洞窟深邃，石壁上刻有唐代佛教造像。冯德英在《迎春花》中描绘了解放战争时期胶东农村的土地改革与阶级斗争，烟霞洞是地下党员秘密接头的隐蔽之所。洞内常年云雾缭绕，"烟霞"之名由此而来。洞外古柏苍翠，山路崎岖，适宜隐蔽。此处既是唐代佛教石窟艺术的珍贵遗存，也是胶东革命历史的重要见证，红色文化与佛教文化在此独特交汇。', '山东', 36.919500, 121.539500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/84/%E5%B1%B1%E4%B8%9C%E7%9C%81%E7%AC%AC%E5%9B%9B%E6%89%B9%E7%9C%81%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E5%90%8D%E5%8D%95%EF%BC%88%E5%85%B1%E8%AE%A1606%E5%A4%84%EF%BC%89.pdf"]'),
('《山雨》', '青岛市崂山区北九水遗址', '王统照', '现代', '崂山北九水遗址位于山东省青岛市崂山区，是王统照《山雨》中奚大有生活的背景地。北九水保留有明代古桥、古寺与飞瀑流泉，溪水自崂山深处蜿蜒而下，经九次曲折形成"九水"奇观。王统照在《山雨》中描绘了农村破产的悲惨现实，崂山的山雨如泣如诉，象征着底层农民的苦难命运。北九水两岸怪石嶙峋，古松挺拔，瀑布飞珠溅玉。每逢山雨初歇，溪水暴涨，水声轰鸣回荡在峡谷之间。此处是崂山最具山水灵气的景区之一，也是感受王统照现实主义文学与崂山溪谷之美的独特之地。', '山东', 36.107400, 120.469300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/84/%E5%B1%B1%E4%B8%9C%E7%9C%81%E7%AC%AC%E5%9B%9B%E6%89%B9%E7%9C%81%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E5%90%8D%E5%8D%95%EF%BC%88%E5%85%B1%E8%AE%A1606%E5%A4%84%EF%BC%89.pdf"]'),
('《黎明的河边》', '潍坊市昌邑市潍河古渡遗址', '峻青', '现代', '潍河古渡遗址位于山东省潍坊市昌邑市，是峻青《黎明的河边》中小陈牺牲的背景地。古渡保留有明清古码头、古碑与革命旧址，石阶在岁月侵蚀下已残破不堪。峻青以胶东解放战争为背景，描绘了年轻战士小陈在黎明前夕为掩护战友渡河而壮烈牺牲的动人故事。潍河水面宽阔，黎明时分薄雾弥漫，河水在晨光中泛出银色光芒。古码头上的石碑铭记着革命烈士的英名。此处是了解胶东解放战争历史与峻青红色文学创作的重要革命文学遗存。', '山东', 36.860100, 119.397800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/18/Confucius_Temple_of_Linyi.jpg"]'),
('《老哥哥》', '潍坊市诸城市臧克家故居老院遗址', '臧克家', '现代', '臧克家故居老院遗址也是臧克家《老哥哥》中老哥哥生活的原型地。老院保留有清代民居、老农具与古碑，院中的石磨与老井诉说着鲁东南农村的质朴生活。臧克家以"老哥哥"为题，描绘了一位善良淳朴的鲁南老农民形象，饱含对底层劳动人民的深切同情。老院周围的田野在四季中变换着色彩——春日麦苗青青，夏日高粱拔节，秋日玉米金黄，冬日白雪覆盖。臧克家从小在这样的乡村环境中长大，农村生活经验成为他诗歌创作的永恒源泉。此处是感受臧克家"农民诗人"情怀的原生之地。', '山东', 35.996600, 119.410100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/ee/%E5%B1%B1%E4%B8%9C%E7%9C%81%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E7%AC%AC%E5%9B%9B%E6%89%B9%E7%9C%81%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E7%9A%84%E9%80%9A%E7%9F%A5%EF%BC%88%E9%B2%81%E6%94%BF%E5%AD%97%E3%80%942013%E3%80%95204%E5%8F%B7%EF%BC%89.pdf"]'),
('《清塘荷韵》', '聊城市临清市季羡林故居清塘遗址', '季羡林', '现代', '季羡林故居清塘遗址位于山东省聊城市临清市，是季羡林《清塘荷韵》"池花对影落"的描绘地。清塘保留有清代池塘、古碑与季羡林故居，池中荷花在夏日盛放，粉红白色交映成趣。季羡林晚年常回忆故乡清塘的荷花，"天地萌生万物，对包括人在内的动植物等有生命的东西，总是赋予一种极其惊人的求生存的力量和极其惊人的扩展蔓延的力量"。故居为典型的鲁西民居，青砖灰瓦，简朴典雅。此处是了解季羡林乡愁情怀与散文美学的重要文学故地，也是感受鲁西水乡荷塘之美的宁静之地。', '山东', 36.838100, 115.713800, '其他', '["https://img0.baidu.com/it/u=1002663265,2641972933&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1502"]'),
('《雅舍小品》', '青岛市市南区鱼山路 33 号梁实秋故居', '梁实秋', '现代', '鱼山路33号梁实秋故居位于山东省青岛市市南区，是梁实秋创作《雅舍小品》的居所之一。故居保留有民国建筑与梁实秋生平陈列，小楼掩映在绿树丛中，面朝大海。梁实秋在青岛居住四年间，常在此品茶读书，"雅舍"虽名为重庆时期的居所，但青岛时期的闲适生活深深影响了他的散文风格。故居所在的鱼山路是青岛最美的小路之一，红瓦绿树，碧海蓝天。梁实秋以幽默优雅的笔触描绘日常生活的趣味，被誉为"闲适散文"的代表。此处是感受梁实秋文学品味与青岛老城区欧式建筑之美的文学故居。', '山东', 36.066900, 120.387000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/9e/%E9%9D%92%E5%B2%9B%E6%A2%81%E5%AE%9E%E7%A7%8B%E6%95%85%E5%B1%85_2017-08-11.jpg"]'),
('《最后一次的讲演》', '青岛市市南区鱼山路 5 号闻一多故居', '闻一多', '现代', '鱼山路5号闻一多故居位于山东省青岛市市南区，是闻一多创作灵感的重要来源地。故居保留有民国建筑与闻一多生平陈列，红色小楼面朝大海，院中花木葱茏。闻一多在青岛国立山东大学任教期间，致力于中国古典文学研究与新诗创作。"最后一次的讲演"虽发生在昆明，但闻一多在青岛时期形成的学术思想与爱国情怀是其精神的重要基础。故居窗外可远眺汇泉湾碧蓝海面，海风送来阵阵涛声。此处是了解闻一多学术生涯与爱国精神的重要文学故居，也是青岛"名人故居群"的重要组成部分。', '山东', 36.066900, 120.387000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/cc/%E9%9D%92%E5%B2%9B%E9%97%BB%E4%B8%80%E5%A4%9A%E6%95%85%E5%B1%85.jpg"]');
INSERT INTO works (title, scenic_spot, author, dynasty, description, province, latitude, longitude, category, images) VALUES
('《济南的冬天》', '济南市历下区佛慧山遗址', '老舍', '现代', '佛慧山遗址位于山东省济南市历下区，是老舍《济南的冬天》"济南的冬天是响晴的"核心取景地。佛慧山保留有唐代摩崖石刻与古寺遗迹，山势舒缓，冬日阳光温暖地照在山坡上。老舍以深情的笔触描绘了济南冬天的温晴之美——"小山整把济南围了个圈儿，只有北边缺着点口儿"。佛慧山正是环绕济南的南部山系之一，冬日积雪覆盖山顶时"给蓝天镶上一道银边"的美景在此完美呈现。山中唐代石刻佛像慈祥端庄，古寺遗址幽静深远。此处是感受老舍散文中济南冬日温情与佛慧山千年石刻之美的经典文学取景地。', '山东', 36.666400, 117.076800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/32/%E4%BD%9B%E6%85%A7%E5%B1%B1%E5%85%A5%E5%8F%A3_20251108.jpg"]'),
('《齐鲁大地》', '济宁市曲阜市孔林子贡手植柏遗址', '余秋雨', '现代', '孔林子贡手植柏遗址位于山东省济宁市曲阜市，是余秋雨《齐鲁大地》中重点描绘的景点。子贡手植柏保留有春秋时期的古柏残根、古碑与孔子墓，孔林是世界上延续时间最长的家族墓地。子贡为孔子守墓六年，亲手种植的柏树虽已枯死但残根犹存，见证了两千五百年的师生情谊。余秋雨以文化散文的笔法探寻齐鲁大地的文化根脉，孔林是其中最厚重的一站。墓园内古柏参天，碑碣林立，肃穆庄严。此处是感受中国儒家文化源头与"万世师表"精神的最神圣之地。', '山东', 35.580000, 116.986400, '其他', '["https://img2.baidu.com/it/u=2354175902,2343661331&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1174"]'),
('《侍坐》', '济宁市曲阜市洙泗书院遗址', '孔子', '春秋', '洙泗书院遗址位于山东省济宁市曲阜市，是孔子《侍坐》中与弟子言志的场景地。书院保留有明代建筑、古碑与古柏，殿堂中孔子塑像端坐讲学。"莫春者，春服既成，冠者五六人，童子六七人，浴乎沂，风乎舞雩，咏而归"——曾皙描绘的理想生活境界成为中国文人千年追求的精神乌托邦。洙泗二水在书院附近交汇，"洙泗之间"自古为儒学圣地。院内古柏苍翠，石径通幽，春日杏花盛开。此处是感受孔子教育思想与先秦文人理想生活的最重要儒学遗址。', '山东', 35.580000, 116.986400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e0/%E5%B1%B1%E4%B8%9C%E7%9C%81%E4%BA%BA%E6%B0%91%E6%94%BF%E5%BA%9C%E5%85%B3%E4%BA%8E%E5%85%AC%E5%B8%83%E7%AC%AC%E4%B8%89%E6%89%B9%E7%9C%81%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E5%90%8D%E5%8D%95%E7%9A%84%E9%80%9A%E7%9F%A5.pdf"]'),
('《得道多助，失道寡助》', '济宁市邹城市孟庙亚圣殿遗址', '孟子', '战国', '孟庙亚圣殿遗址位于山东省济宁市邹城市，是孟子"天时不如地利，地利不如人和"思想的传播地。孟庙保留有宋代建筑、古碑与古柏，亚圣殿庄严肃穆，殿内孟子塑像端坐讲学。孟子继承发展了孔子的仁政学说，"民为贵，社稷次之，君为轻"的民本思想影响了中国两千余年的政治文化。庙内古柏苍翠挺拔，碑廊中历代碑刻记录了孟子学说的传播与影响。春日庙中杏花盛开，秋日银杏金黄。此处是了解孟子仁政思想与中国儒学发展史的重要文化圣地。', '山东', 35.405300, 117.007300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/f/f6/Temple_of_Mencius_-_Yasheng_Hall_-_P1050910.JPG"]'),
('《逍遥游》', '菏泽市东明县庄子观遗址', '庄子', '战国', '庄子观遗址位于山东省菏泽市东明县，是庄子《逍遥游》的创作背景地。遗址保留有清代建筑、古碑与庄子墓，殿堂中庄子塑像超然飘逸。"北冥有鱼，其名为鲲。鲲之大，不知其几千里也"——庄子以恢宏的想象力构建了中国哲学中最自由奔放的精神世界。庄子观四周平原辽阔，天高地远，"逍遥游"的自由境界在此旷野中自然可感。庄子墓前古柏苍劲，石碑斑驳。东明自古为庄子故里，道家文化在此源远流长。此处是了解庄子哲学思想与道家文化精髓的重要遗存。', '山东', 35.289400, 115.089800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/84/%E5%B1%B1%E4%B8%9C%E7%9C%81%E7%AC%AC%E5%9B%9B%E6%89%B9%E7%9C%81%E7%BA%A7%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E5%90%8D%E5%8D%95%EF%BC%88%E5%85%B1%E8%AE%A1606%E5%A4%84%EF%BC%89.pdf"]'),
('《史记・孔子世家》', '济宁市曲阜市尼山孔子出生地遗址', '司马迁', '西汉', '尼山孔子出生地遗址位于山东省济宁市曲阜市，是司马迁《史记·孔子世家》中重点记载的圣迹。遗址保留有春秋时期的夫子洞、古碑与尼山书院，夫子洞相传为孔子出生之地，洞口石壁上"夫子洞"三字苍劲有力。尼山书院始建于宋代，历代儒者在此讲学传道。司马迁在《孔子世家》中以"高山仰止，景行行止"赞颂孔子，这份崇敬在尼山的一草一木中都能感受到。山上古柏参天，山下沂水潺潺，"智者乐水，仁者乐山"的儒学意境在此完美呈现。此处是朝拜孔子诞生地与体验儒学圣地氛围的最神圣之地。', '山东', 35.580000, 116.986400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/d8/Qufu_Confucian_Temple_49112-Qufu_%2849055132633%29.jpg"]'),
('《水经注・济水注》', '济南市历下区黑虎泉玛瑙泉遗址', '郦道元', '北魏', '黑虎泉玛瑙泉遗址位于山东省济南市历下区，是郦道元《水经注·济水注》中重点记载的名泉。玛瑙泉保留有宋代泉眼、古碑与护城河，泉水从石缝中涌出，水珠晶莹如玛瑙。郦道元在《水经注》中以精细的地理笔法记录了济南诸泉的位置与形态，为后世泉水研究提供了珍贵的历史文献。黑虎泉群是济南四大泉群之一，泉水从三个虎头石雕中喷涌而出，水声如虎啸。护城河水碧波荡漾，两岸垂柳拂水。此处是感受济南"泉城"文化与北魏地理文学的重要历史遗存。', '山东', 36.666400, 117.076800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/c9/Black_Tiger_Spring_20250301.jpg"]'),
('《徐霞客游记・游泰山记》', '泰安市泰山区泰山日观峰遗址', '徐霞客', '明代', '泰山日观峰遗址位于山东省泰安市泰山区，是徐霞客《徐霞客游记·游泰山记》中"泰山日出，天下奇观"的描绘地。日观峰保留有明代摩崖石刻与古碑，是观赏泰山日出的最佳位置。徐霞客以"游圣"之名走遍中国山川，泰山日出在其游记中占有重要篇幅。清晨站在日观峰上，东方天际由暗转明，一轮红日从云海中喷薄而出，金光万道照彻齐鲁大地。"旭日东升"的壮观景象吸引了历代帝王与文人争相登临。此处是感受泰山"五岳之首"气象与徐霞客游历精神的经典观景之地。', '山东', 36.194900, 117.129000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/6/6c/%E5%B1%B1%E4%B8%9C%E7%9C%81%E7%AC%AC%E4%B8%80%E8%87%B3%E5%85%AB%E6%89%B9%E5%85%A8%E5%9B%BD%E9%87%8D%E7%82%B9%E6%96%87%E7%89%A9%E4%BF%9D%E6%8A%A4%E5%8D%95%E4%BD%8D%E4%BF%9D%E6%8A%A4%E8%8C%83%E5%9B%B4%E5%92%8C%E5%BB%BA%E8%AE%BE%E6%8E%A7%E5%88%B6%E5%9C%B0%E5%B8%A6.pdf"]'),
('《登泰山记》', '泰安市泰山区泰山玉皇顶遗址', '姚鼐', '清代', '泰山玉皇顶遗址位于山东省泰安市泰山区，是姚鼐《登泰山记》中"极天云一线异色"观日出的最佳点。玉皇顶保留有清代碑刻与古亭，为泰山最高峰，海拔1545米。姚鼐在除夕之夜冒雪登顶，次日凌晨目睹"极天云一线异色，须臾成五彩"的壮丽日出，写下桐城派散文经典。玉皇顶上"五岳独尊"石刻是泰山的标志。站在顶峰，"一览众山小"的壮阔尽收眼底，齐鲁大地山河壮美。清代碑刻林立，记录了历代帝王封禅与文人登临的盛事。此处是泰山文化的最高点，也是感受姚鼐散文艺术与泰山极顶气象的终极之地。', '山东', 36.194900, 117.129000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/80/Pano_%E5%B1%B1%E6%9D%B1%E6%B3%B0%E5%B1%B1%E7%BA%9C%E8%BB%8A%E6%97%85%E9%81%8A%E4%BA%BA%E6%B5%81_%E5%B1%B1%E4%B8%9C%E6%B3%B0%E5%B1%B1%E7%BC%86%E8%BD%A6%E6%97%85%E6%B8%B8%E4%BA%BA%E6%B5%81_Shandong_Province_Mount_Tai_Cable_Car_Tourism_Human_Logistics_%E4%B8%AD%E5%9C%8B%E6%97%85%E9%81%8A_%E4%B8%AD%E5%9B%BD%E6%97%85%E6%B8%B8_China_Tourism_SML.20121011.7D.09508-09509.Pano_%288372527765%29.jpg"]'),
('《桃花扇》', '济宁市曲阜市孔尚任故居遗址', '孔尚任', '清代', '孔尚任故居遗址位于山东省济宁市曲阜市，是孔尚任创作《桃花扇》的居所。故居保留有清代建筑、古碑与《桃花扇》手稿陈列，院落典雅清幽。孔尚任为孔子六十四代孙，以南明兴亡为背景创作了传奇剧作《桃花扇》，"借离合之情，写兴亡之感"。故居中陈列有《桃花扇》的版本沿革、创作手稿与演出剧照，展示了这部戏曲经典的诞生过程。院中桃花树在春日粉红灿烂，"桃花扇底送南朝"的兴亡感慨在故居的一砖一瓦中回荡。此处是了解孔尚任戏曲艺术与清代文学史的重要文学故居。', '山东', 35.580000, 116.986400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/96/Kong_Family_Mansion_49273-Qufu_%2849055868867%29.jpg"]'),
('《登幽州台歌》', '大兴区黄村镇幽州台遗址', '陈子昂', '唐代', '幽州台遗址位于北京市大兴区黄村镇，是陈子昂《登幽州台歌》"前不见古人，后不见来者"的诞生地。幽州台又称蓟北楼，始建于战国时期燕昭王时代，为招揽天下贤士而筑。遗址保留有唐代夯土台基、古碑与蓟门烟树残迹，台基虽已残破但仍可感受当年的规模。陈子昂随军北征契丹，登台远望，感怀身世而写下这首千古绝唱，"念天地之悠悠，独怆然而涕下"的苍凉悲壮感动了无数后人。此处是中国文学史上最具生命哲思的诗歌诞生地，也是感受唐代文人孤独与壮志的重要文学遗存。', '北京', 39.726800, 116.341600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/c7/Glass_bridge_at_Tianyun_Mountain.jpg"]'),
('《正气歌》', '东城区交道口文天祥祠遗址', '文天祥', '南宋', '文天祥祠遗址位于北京市东城区交道口，是文天祥被囚大都三年期间写下《正气歌》的地方。祠堂保留有宋代碑刻与文天祥手书墨迹，正堂中文天祥塑像面南而立，神态刚毅。"天地有正气，杂然赋流形"开篇即震撼人心，文天祥以身殉国的气节成为中华民族精神的永恒象征。祠内古柏"指南树"向南倾斜生长，寓意文天祥"臣心一片磁针石，不指南方不肯休"的忠贞。院中幽静肃穆，石碑铭刻着文天祥的生平事迹。此处是缅怀民族英雄与感受"浩然正气"精神的庄严之地。', '北京', 39.928600, 116.416600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/43/2016%E5%B9%B4%E5%BA%A6%E5%85%A8%E5%9B%BD%E5%8D%9A%E7%89%A9%E9%A6%86%E5%90%8D%E5%BD%95.pdf"]'),
('《天净沙・秋思》', '门头沟区王平镇马致远故居', '马致远', '元代', '马致远故居位于北京市门头沟区王平镇，是马致远《天净沙·秋思》"枯藤老树昏鸦，小桥流水人家"的原型地。故居保留有元代民居建筑风格的院落、古桥与古井，门前小溪流水潺潺，老树虬枝苍劲。马致远被誉为"秋思之祖"，这首仅二十八字的小令以六组意象勾勒出中国文学史上最凄美的秋日旅途画面。"夕阳西下，断肠人在天涯"的游子乡愁在此处的山村暮色中格外动人。古桥流水、老院炊烟、昏鸦归巢，元曲中的意境在这座京西古村落中完美还原。此处是感受元曲之美与京郊古村落风情的经典文学故地。', '北京', 39.940500, 116.101800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/14/House%2C_Former_Residence_of_Ma_Zhiyuan.jpg"]'),
('《长相思・山一程》', '海淀区上庄镇纳兰性德故居', '纳兰性德', '清代', '纳兰性德故居位于北京市海淀区上庄镇，是纳兰性德《长相思·山一程》出使途中记录艰辛之作的创作背景地。故居保留有清代园林遗迹、古碑与手稿陈列，"渌水亭"遗址掩映在古木丛中。"山一程，水一程，身向榆关那畔行，夜深千帐灯"描绘了出塞途中的壮阔与孤寂。纳兰性德虽出身满洲贵族，词作却以真挚深情著称，被誉为"清代第一词人"。故居周围田园宁静，与"人生若只如初见"的感伤情调相得益彰。此处是了解纳兰性德传奇人生与清代词学成就的重要文学故居。', '北京', 39.959300, 116.298200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/43/2016%E5%B9%B4%E5%BA%A6%E5%85%A8%E5%9B%BD%E5%8D%9A%E7%89%A9%E9%A6%86%E5%90%8D%E5%BD%95.pdf"]'),
('《题芹溪居士》', '海淀区四季青镇曹雪芹故居正白旗村', '曹雪芹', '清代', '曹雪芹故居正白旗村位于北京市海淀区四季青镇，是曹雪芹创作《红楼梦》的居所。故居保留有清代民居建筑、古碑与曹雪芹纪念馆，院落简朴，与曹雪芹晚年"举家食粥酒常赊"的困顿生活相符。曹雪芹在此"批阅十载，增删五次"，完成了中国文学史上最伟大的长篇小说。"满纸荒唐言，一把辛酸泪"凝聚了他对人生与社会的深刻洞察。纪念馆中陈列有《红楼梦》的版本沿革与曹雪芹生平事迹。香山脚下的西山红叶与故居的萧瑟秋景相映，此处是中国文学史上最伟大作品的诞生圣地。', '北京', 39.959300, 116.298200, '其他', '["https://img0.baidu.com/it/u=3329033203,70328571&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《陶然亭》', '西城区陶然亭公园慈悲庵遗址', '白居易', '唐代', '陶然亭公园慈悲庵遗址位于北京市西城区，是白居易"共君一醉一陶然"诗句的命名之源。慈悲庵保留有唐代建筑基址与宋代碑刻，清代江藻在此建亭并取白居易诗意命名为"陶然亭"。"更待菊黄家酿熟，共君一醉一陶然"描绘了秋日饮酒赏菊的闲适之乐。庵内古碑林立，记载了历代文人雅集的盛况。陶然亭后来成为近代革命志士聚会之地，李大钊、毛泽东等都曾在此活动。此处既是唐代诗歌文化的延续，也是近代革命历史的见证，是北京城中兼具文学与革命意义的独特文化空间。', '北京', 39.912500, 116.365900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/2/26/%E9%99%B6%E7%84%B6%E4%BA%AD_-_Joyful_Pavilion_-_2011.11_-_panoramio_%281%29.jpg"]'),
('《登蓟丘楼送贾兵曹入都》', '西城区蓟门烟树元大都城墙遗址', '陈子昂', '唐代', '蓟门烟树元大都城墙遗址位于北京市西城区，是陈子昂《登蓟丘楼送贾兵曹入都》"悠悠吾思生"的描绘地。遗址保留有元代夯土城墙与乾隆御碑，城墙残段高数米，夯土层次分明。蓟门是古代北京城的北门，"蓟门烟树"曾为"燕京八景"之一。陈子昂在此送别友人南下，"吾将以万古长夜看大荒"的孤独感弥漫在苍茫暮色中。古城墙上古柏苍翠，乾隆御碑"蓟门烟树"四字遒劲有力。春日烟柳朦胧，秋日落叶纷飞。此处是了解北京古城格局与唐代送别文化的重要历史遗存。', '北京', 39.912500, 116.365900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/86/%E5%85%83%E5%A4%A7%E9%83%BD%E9%81%97%E5%9D%80%E5%85%AC%E5%9B%AD_-_panoramio.jpg"]'),
('《居庸叠翠》', '昌平区居庸关长城南段遗址', '乾隆', '清代', '居庸关长城南段遗址位于北京市昌平区，是乾隆"燕京八景"之"居庸叠翠"的核心取景地。南段长城保留有明代长城墙体与古碑，长城沿山脊蜿蜒而上，两侧山峰叠翠如屏。居庸关自古为"天下九塞"之一，是守卫北京的咽喉要隘。"居庸叠翠"描绘了春夏之际关沟两侧山林层层叠翠的壮美景象。长城敌楼巍然耸立，箭孔与瞭望窗保存完好。此段游客较八达岭稀少，可以安静地感受长城的雄浑气势。此处是体验明代长城军事建筑之美与"居庸叠翠"古典意境的绝佳之地。', '北京', 40.220700, 116.231200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/0/06/%E5%85%B3%E4%BA%8E%E5%8D%B0%E5%8F%912015%E5%B9%B4%E5%BA%A6%E5%85%A8%E5%9B%BD%E5%8D%9A%E7%89%A9%E9%A6%86%E5%90%8D%E5%BD%95%E7%9A%84%E9%80%9A%E7%9F%A5%EF%BC%88%E6%96%87%E7%89%A9%E5%8D%9A%E5%8F%91%E3%80%942016%E3%80%9518%E5%8F%B7%EF%BC%89.pdf"]'),
('《卢沟晓月》', '丰台区卢沟桥宛平城西门遗址', '乾隆', '清代', '卢沟桥宛平城西门遗址位于北京市丰台区，是乾隆"燕京八景"之"卢沟晓月"的最佳观景点。西门保留有明代城墙、古炮与清代碑刻，宛平城始建于明崇祯年间，是北京仅存的两座明代卫城之一。"卢沟晓月"描绘了拂晓时分永定河上月色朦胧的绝美景象。卢沟桥上485只石狮子形态各异，"卢沟桥的狮子数不清"是北京最著名的歇后语。1937年七七事变在此爆发，卢沟桥成为中华民族全面抗战的起点。此处既是感受古典"晓月"意境的诗意之地，也是铭记抗战历史的庄严纪念场所。', '北京', 39.858500, 116.286900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/7a/Lugouqiao2.jpg"]'),
('《琼岛春阴》', '西城区北海公园琼华岛悦心殿遗址', '乾隆', '清代', '琼华岛悦心殿遗址位于北京市西城区北海公园，是乾隆"燕京八景"之"琼岛春阴"的核心取景地。悦心殿保留有清代建筑、乾隆御碑与太湖石假山，殿宇依山而建，面朝太液池。"琼岛春阴"描绘了早春时节琼华岛上烟雨朦胧、杨柳吐绿的诗意景象。乾隆御碑"琼岛春阴"四字端庄秀丽。白塔矗立在琼华岛之巅，是北京城最具标志性的古建筑之一。春日岛上桃花杏花竞相开放，太液池水碧波荡漾。此处是感受皇家园林春色之美与清代帝王审美情趣的经典之地。', '北京', 39.912500, 116.365900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/9c/%E5%8C%97%E4%BA%AC%E5%8C%97%E6%B5%B7%E5%85%AC%E5%9B%AD%E6%82%A6%E5%BF%83%E6%AE%BF2023.3.jpg"]'),
('《太液秋风》', '西城区北海公园太液池五龙亭遗址', '乾隆', '清代', '太液池五龙亭遗址位于北京市西城区北海公园，是乾隆"燕京八景"之"太液秋风"的观景点。五龙亭保留有明代建筑、古碑与荷花池，五座亭阁以曲桥相连，如游龙戏水。"太液秋风"描绘了秋日太液池上清风徐来、荷叶飘摇的幽美意境。亭上远眺北海全景，白塔倒映碧波之中，远处故宫角楼隐约可见。秋日荷叶残枯，别有一番萧瑟之美。五龙亭始建于明代万历年间，是北海公园中最具建筑美感的景点之一。此处是感受皇家园林秋色与明清建筑精华的宁静之地。', '北京', 39.912500, 116.365900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/32/Beihai_Park_65414.jpg"]'),
('《玉泉趵突》', '海淀区玉泉山静明园泉眼遗址', '乾隆', '清代', '玉泉山静明园泉眼遗址位于北京市海淀区，是乾隆"燕京八景"之"玉泉趵突"的核心所在。泉眼保留有清代泉池、乾隆御碑与园林遗迹，玉泉水质清冽甘甜，曾被乾隆评为"天下第一泉"。"玉泉趵突"描绘了泉水从山石间喷涌而出如珍珠迸溅的壮观景象。静明园为清代皇家园林"三山五园"之一，园内山水相映，松柏苍翠。玉泉山远眺如一尊卧佛，山形秀美。泉水汇入昆明湖，最终注入北京城中。此处是了解北京城水系源头与清代皇家园林文化的重要历史遗存。', '北京', 39.959300, 116.298200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/0/02/Yuyuantan_Park_2010.jpg"]'),
('《西山晴雪》', '海淀区香山公园香炉峰半山亭遗址', '乾隆', '清代', '香山公园香炉峰半山亭遗址位于北京市海淀区，是乾隆"燕京八景"之"西山晴雪"的最佳观景点。半山亭保留有清代古碑与观景台，古松苍劲挺拔。"西山晴雪"描绘了雪后初晴时西山银装素裹、阳光照射下雪光璀璨的壮美景象。香山自古以红叶闻名，但冬日雪后的香山更具清绝之美——白雪覆盖在红黄交错的残叶之上，阳光穿透云层照亮山峦。乾隆御碑"西山晴雪"四字苍劲有力。香炉峰为香山最高点，登顶可俯瞰北京西郊全景。此处是感受北京冬日雪景之壮美与皇家御题文化的经典之地。', '北京', 39.959300, 116.298200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/f/fe/Xishan_Qingxue_monument_at_Fragrant_Hills.jpg"]'),
('《金台夕照》', '朝阳区金台路金台遗址', '乾隆', '清代', '金台遗址位于北京市朝阳区金台路，是乾隆"燕京八景"之"金台夕照"的核心所在。遗址保留有清代夯土台基、乾隆御碑与古柏，台基为燕昭王筑黄金台招贤纳士的传说之地。"金台夕照"描绘了夕阳余晖洒在金台之上的壮美景象，寓意求贤若渴的政治理想。"千金市骨"的典故使金台成为中国文化中礼贤下士的永恒象征。乾隆御碑"金台夕照"四字端庄厚重。如今金台遗址周围已是现代化的CBD商务区，古台与高楼的对比颇具时空穿越之感。此处是了解燕国历史与北京古都文化的重要遗存。', '北京', 39.921000, 116.486400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/6/62/%E5%8C%97%E4%BA%AC%E5%9F%8E%E5%B8%82%E5%89%AF%E4%B8%AD%E5%BF%83%E6%8E%A7%E5%88%B6%E6%80%A7%E8%AF%A6%E7%BB%86%E8%A7%84%E5%88%92%EF%BC%88%E8%A1%97%E5%8C%BA%E5%B1%82%E9%9D%A2%EF%BC%89%EF%BC%882016%E5%B9%B4-2035%E5%B9%B4%EF%BC%89.pdf"]'),
('《过居庸关》', '昌平区居庸关云台遗址', '马致远', '元代', '居庸关云台遗址位于北京市昌平区，是马致远"飞鸟不度山石裂"的描绘地。云台始建于元代，保留有精美的石刻佛像、梵文经咒与古碑，是元代石雕艺术的杰作。云台上的多语种石刻（梵文、藏文、八思巴文、维吾尔文、汉文、西夏文）展现了元代多民族文化交融的盛况。马致远以雄浑的笔触描绘了居庸关的险要——山石嶙峋，飞鸟难越，长城蜿蜒于山脊之上。云台券洞内的浮雕佛像栩栩如生，天王力士威严端庄。此处是感受元代石刻艺术与居庸关军事险要的珍贵历史遗存。', '北京', 40.220700, 116.231200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/43/2016%E5%B9%B4%E5%BA%A6%E5%85%A8%E5%9B%BD%E5%8D%9A%E7%89%A9%E9%A6%86%E5%90%8D%E5%BD%95.pdf"]'),
('《香山》', '海淀区香山公园双清别墅遗址', '乾隆', '清代', '香山公园双清别墅遗址位于北京市海淀区，是乾隆"万壑千峰锁翠云"描绘的香山景致核心。双清别墅保留有清代园林建筑、古碑与泉水，"双清"指院中两股清泉汇聚。更为重要的是，1949年毛泽东在此指挥了渡江战役，使双清别墅成为新中国诞生的历史见证地。乾隆时期的皇家御题赋予此处文化底蕴，革命历史则赋予其政治意义。院内古木参天，泉声潺潺，红叶季节满山如火。此处既是清代皇家园林文化的遗存，也是中国革命历史的重要纪念地，文化与革命在此独特交汇。', '北京', 39.959300, 116.298200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/43/2016%E5%B9%B4%E5%BA%A6%E5%85%A8%E5%9B%BD%E5%8D%9A%E7%89%A9%E9%A6%86%E5%90%8D%E5%BD%95.pdf"]'),
('《颐和园》', '海淀区颐和园谐趣园知春亭遗址', '乾隆', '清代', '颐和园谐趣园知春亭遗址位于北京市海淀区，是乾隆"春到人间草木知"描绘的皇家园林春色核心。知春亭保留有清代建筑、古碑与荷花池，亭名取自苏轼"春江水暖鸭先知"的诗意。谐趣园仿无锡寄畅园而建，是颐和园中最精巧的"园中园"。池中荷花在夏日盛放，锦鲤游弋；春日杨柳吐绿，桃花映水。知春亭是颐和园中最早感受到春天气息的地方——冰雪初融时亭前柳丝最先泛绿。此处是感受皇家园林四季之美与清代造园艺术精髓的典雅之地。', '北京', 39.959300, 116.298200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/0/06/%E9%A2%90%E5%92%8C%E5%9B%AD%E4%B8%87%E5%AF%BF%E5%B1%B1%E4%BD%9B%E9%A6%99%E9%98%81.jpg"]'),
('《圆明园》', '海淀区圆明园九州清晏遗址', '乾隆', '清代', '圆明园九州清晏遗址位于北京市海淀区，是乾隆"四海无波五谷登"描绘的皇家园林核心景区。九州清晏保留有清代建筑基址、古碑与太湖石，是圆明园最重要的理政与居住区域。"九州清晏"寓意天下太平、五谷丰登。1860年英法联军火烧圆明园，这座"万园之园"化为废墟。如今遗址中残存的石柱、石础与太湖石在荒草中静默，断壁残垣诉说着一个帝国的荣耀与屈辱。遗址周围湖水依旧，垂柳依依，只是昔日的琼楼玉宇已成追忆。此处是铭记历史屈辱与反思文明兴衰的最深刻教育之地。', '北京', 39.959300, 116.298200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/73/Yuanmingyuan_Ruins_of_Dashuifa_20120715.JPG"]'),
('《畅春园》', '海淀区畅春园恩佑寺遗址', '康熙', '清代', '畅春园恩佑寺遗址位于北京市海淀区，是康熙"曲水回廊绕碧流"描绘的皇家园林遗迹。恩佑寺保留有清代山门、古碑与古柏，是畅春园仅存的地面建筑。畅春园始建于康熙年间，是清代最早的皇家御园，康熙帝晚年常驻此园理政。"曲水回廊"的园林布局体现了康熙帝崇尚自然的审美理念。恩佑寺山门古朴庄严，门前古柏树冠如盖。畅春园大部分已湮没于北京大学校园之下，恩佑寺成为追忆这座皇家御园的唯一地标。此处是了解清代早期皇家园林文化与康熙帝文化品味的珍贵遗存。', '北京', 39.959300, 116.298200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/5e/Beijing_Changchunyuan02.JPG"]'),
('《潭柘寺》', '门头沟区潭柘寺流杯亭遗址', '乾隆', '清代', '潭柘寺流杯亭遗址位于北京市门头沟区，是乾隆"兰亭雅集至今传"描绘的佛教古刹景致。流杯亭保留有明代建筑、古碑与流杯渠，亭内石渠蜿蜒如龙，仿王羲之兰亭曲水流觞之雅趣。潭柘寺始建于西晋，有"先有潭柘寺，后有北京城"之说，是北京地区最古老的佛教寺院。寺内古木参天，千年银杏"帝王树"高达四十余米。乾隆帝曾九次驾临潭柘寺，对流杯亭的文人雅趣尤为钟爱。山寺云雾缭绕，钟声悠远。此处是感受北京最古老佛教寺院的深厚底蕴与文人雅集传统的清幽之地。', '北京', 39.940500, 116.101800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e7/Tanzhe_Si.jpg"]'),
('《戒台寺》', '门头沟区戒台寺戒坛遗址', '乾隆', '清代', '戒台寺戒坛遗址位于北京市门头沟区，是乾隆"千佛庄严拥翠鬟"描绘的佛教圣地。戒坛保留有辽代建筑与古碑，为中国现存最大的佛教戒坛，分三层共113尊戒神雕像。戒台寺始建于唐代，"戒坛"为僧人受戒之地，在佛教中地位崇高。寺内千年古松形态各异——"卧龙松""九龙松""抱塔松"各具神态，被誉为"活的古松博物馆"。乾隆帝曾多次驾临并题诗赞叹。寺院依山而建，松涛阵阵，佛殿庄严。此处是感受辽代佛教建筑艺术与千年古松奇观的重要宗教文化遗存。', '北京', 39.940500, 116.101800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/ed/Jietai_Temple_%2820150117134744%29.JPG"]'),
('《云居寺》', '房山区云居寺石经山雷音洞遗址', '乾隆', '清代', '云居寺石经山雷音洞遗址位于北京市房山区，是乾隆"千古流传永不刊"描绘的佛教石经圣地。雷音洞保留有隋代石经板、古碑与石窟，洞内石壁镶嵌的隋代石经板是世界上现存最早的石刻佛经。云居寺自隋代起历时千余年刻经14278块，被誉为"石刻版的百科全书"。僧人们以"以石为纸，以刀为笔"的毅力完成了这项浩瀚的文化工程。石经山上洞窟幽深，松柏苍翠，佛教的虔诚与坚韧在每一块石经上都能感受到。此处是中国佛教石刻文化的最高成就之地。', '北京', 39.748700, 116.143300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/a/a1/Entrance_to_Yunju_Temple_%2820150223134448%29.JPG"]'),
('《十渡》', '房山区十渡风景区孤山寨遗址', '乾隆', '清代', '十渡风景区孤山寨遗址位于北京市房山区，是乾隆"奇峰秀水冠燕南"描绘的京郊山水胜地。孤山寨保留有明代古桥、古碑与飞瀑流泉，峡谷蜿蜒幽深，两岸奇峰壁立。拒马河从十渡穿行而过，"十渡"之名因古人渡河十次才能通过而得名。河水碧绿清澈，两岸山峰倒映水中，形成"北方小桂林"的壮丽景观。孤山寨中一线天、千年古藤等自然奇观令人叹为观止。乾隆帝曾在此驻跸游览并题诗赞美。此处是北京近郊感受喀斯特地貌与山水之美的最佳之地。', '北京', 39.748700, 116.143300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/2/24/Skyline_of_Chengbei_Subdistrict_Changping_District.jpg"]'),
('《慕田峪长城》', '怀柔区慕田峪长城西段遗址', '徐渭', '明代', '慕田峪长城西段遗址位于北京市怀柔区，是徐渭"纵目凭高更上楼"描绘的长城景观。西段长城保留有明代长城墙体、古碑与敌楼，长城沿山脊蜿蜒起伏如巨龙腾飞。慕田峪长城始建于北齐，明代重修后成为守卫京师的重要防线。西段游客稀少，可以独享长城的壮美与宁静。敌楼中箭孔与了望窗保存完好，垛口上的射击口展示了明代军事防御的精密设计。春日山花烂漫，秋日红叶漫山，长城在四季更替中展现不同的壮美。此处是远离人群、静心感受长城雄浑之美的绝佳之地。', '北京', 40.316100, 116.637700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/9f/Great_Wall_of_China%2C_Mutianyu%2C_Huairou_County%2C_China-10June2009.jpg"]'),
('《司马台长城》', '密云区司马台长城单边墙遗址', '戚继光', '明代', '司马台长城单边墙遗址位于北京市密云区，是戚继光"古戍盘雕大漠风"描绘的险要长城。单边墙保留有明代长城墙体、古碑与敌楼，因墙体仅一面修筑而得名，是长城建筑中最为险要的段落。司马台长城以"险"著称，部分段落修筑在刀刃般的山脊之上，两侧悬崖峭壁。戚继光作为明代抗倭名将与长城防线总设计师，以"古戍盘雕"描绘了长城苍凉壮美的军事景观。夜晚星空璀璨，长城在月色下如银蛇蜿蜒。此处是中国长城中最具原始野性之美的段落，也是感受戚继光军事智慧的最佳之地。', '北京', 40.376800, 116.843400, '其他', '["https://img2.baidu.com/it/u=2921502371,3896452204&fm=253&fmt=auto&app=138&f=JPEG?w=750&h=500"]'),
('《古北口长城》', '密云区古北口长城卧虎山遗址', '康熙', '清代', '古北口长城卧虎山遗址位于北京市密云区，是康熙"长城万里界金汤"描绘的边关要塞。卧虎山长城保留有明代长城墙体、古碑与敌楼，长城沿山势起伏如卧虎盘踞。古北口自古为京师北方门户，"一夫当关，万夫莫开"的险要地势使之成为兵家必争之地。康熙帝多次巡幸古北口，对长城的军事防御功能极为重视。卧虎山段长城未经大规模修缮，保留了明代长城最原始的面貌——残破的垛口、风化的砖石诉说着数百年的边关烽火。此处是感受长城原始风貌与古北口边关军事文化的珍贵遗存。', '北京', 40.376800, 116.843400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/9c/Great_Wall_of_China_at_Jinshanling_5.jpg"]'),
('《雁栖湖》', '怀柔区雁栖湖湖心岛遗址', '乾隆', '清代', '雁栖湖湖心岛遗址位于北京市怀柔区，是乾隆"荷叶荷花香满船"描绘的京郊湖泊风光。湖心岛保留有清代园林基址、古碑与荷花池，夏日荷花盛开时满湖粉红。雁栖湖因每年秋季大雁在此栖息而得名，湖面水域宽阔，三面环山，水质清澈。湖畔的APEC会议中心使雁栖湖成为国际瞩目的地标。乾隆时期此处为皇家猎苑的一部分，帝王常在湖畔赏荷泛舟。秋日大雁南飞时在湖面上空列队飞过，场面壮观。此处是北京近郊感受湖光山色与皇家园林遗韵的优美之地。', '北京', 40.316100, 116.637700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/6/62/Sunrise_Kempinski_Hotel_Beijing_%2820190915161213%29.jpg"]'),
('《红螺寺》', '怀柔区红螺寺大雄宝殿遗址', '乾隆', '清代', '红螺寺大雄宝殿遗址位于北京市怀柔区，是乾隆"古寺深藏万壑云"描绘的佛教古刹。大雄宝殿保留有明代建筑、古碑与千年古松，殿宇庄严肃穆。红螺寺始建于东晋，因"红螺"传说而得名，是京北地区最具影响力的佛教寺院。寺内"紫藤寄松""御竹林"等奇观令人赞叹——千年紫藤攀附在古松之上，形成"藤缠松"的自然奇观。乾隆帝曾驾临红螺寺并题诗赞美。寺院掩映在深山密林之中，云雾缭绕，钟声悠远。此处是感受北京深山古刹的清幽意境与明代佛教建筑之美的禅修胜地。', '北京', 40.316100, 116.637700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/c9/%E5%8C%97%E4%BA%AC%E7%BA%A2%E8%9E%BA%E5%AF%BA.JPG"]'),
('《上方山》', '房山区上方山云水洞遗址', '乾隆', '清代', '上方山云水洞遗址位于北京市房山区，是乾隆"天然钟乳自天成"描绘的喀斯特溶洞奇观。云水洞保留有明代摩崖石刻、古碑与千姿百态的钟乳石，洞内石笋石柱如林，石幔石花如画。上方山自古为佛教名山，"南有苏杭，北有上方"的美誉流传已久。乾隆帝曾驾临上方山并对云水洞的天然造化赞叹不已。洞内温度常年恒定，滴水声回荡在幽深的洞穴中。洞外古寺掩映在山林之中，摩崖石刻记录了历代文人的游览感怀。此处是北京地区感受喀斯特地貌奇观与佛教名山文化的独特之地。', '北京', 39.748700, 116.143300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/c0/%E4%B8%8A%E6%96%B9%E5%B1%B1%E4%BA%91%E6%B0%B4%E6%B4%9E.jpg"]'),
('《百花山》', '门头沟区百花山百草畔遗址', '老舍', '现代', '百花山百草畔遗址位于北京市门头沟区，是老舍"万紫千红次第来"描绘的京郊高山草甸。百草畔保留有原始森林、亚高山草甸与古碑，海拔两千余米，是北京地区最高的山峰之一。夏季草甸上野花遍地——金莲花、胭脂花、野罂粟竞相开放，"万紫千红"的壮观景象名不虚传。老舍对北京郊区的自然风光有着深厚的感情，百花山的高山草甸是他笔下最绚丽的自然画卷。山顶云雾缭绕，远眺华北平原一望无际。此处是北京近郊感受高山草甸野花之美与原始森林生态的避暑胜地。', '北京', 39.940500, 116.101800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/f/f9/CADAL04601973_%E5%BA%9C%E7%A9%80%E7%B8%A3%E8%AA%8C%E5%8D%81%E5%8D%B7%EF%BC%9A%E5%8D%B7%E4%B8%80.djvu"]'),
('《骆驼祥子》', '西城区新街口南大街骆驼祥子博物馆', '老舍', '现代', '骆驼祥子博物馆位于北京市西城区新街口南大街，是老舍《骆驼祥子》的核心原型地。博物馆保留有老舍手稿、祥子的黄包车复原品与老北京生活用品，展厅以祥子的人生轨迹为主线，再现了旧北京人力车夫的悲惨命运。"祥子"从满怀希望到三起三落最终沉沦的故事，是中国现代文学中最深刻的底层叙事。博物馆中的民国时期老北京街景还原——胡同口的茶摊、烟馆、洋车行构成了那个时代的生活图景。此处是了解老舍现实主义文学成就与旧北京底层市民生活的最重要文学纪念馆。', '北京', 39.912500, 116.365900, '其他', '["https://img2.baidu.com/it/u=1012228015,706423941&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=711"]'),
('《骆驼祥子》', '东城区东四北大街六条胡同', '老舍', '现代', '东四北大街六条胡同位于北京市东城区，是老舍《骆驼祥子》中祥子拉车的主要路线。胡同保留有清末民初四合院、老门楼与古槐树，青砖灰瓦的院墙蜿蜒在胡同两侧。祥子拉着黄包车穿行在这样的胡同中，从东四到西四，从鼓楼到前门，北京城的每一条街道都留下了他奔波的脚印。胡同中的古槐树冠如华盖，夏日树荫下的凉意曾是车夫歇脚的慰藉。老门楼上的砖雕虽已风化但仍精美可辨。此处是感受老舍笔下旧北京胡同生活气息与《骆驼祥子》文学场景的原生之地。', '北京', 39.928600, 116.416600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/43/2016%E5%B9%B4%E5%BA%A6%E5%85%A8%E5%9B%BD%E5%8D%9A%E7%89%A9%E9%A6%86%E5%90%8D%E5%BD%95.pdf"]'),
('《四世同堂》', '西城区新街口街道小杨家胡同遗址', '老舍', '现代', '小杨家胡同遗址位于北京市西城区新街口街道，是老舍《四世同堂》中祁家大院的原型地。遗址保留有清末民初四合院、老门楼与古槐树，院落方正，门楼上的砖雕精美。老舍以"小羊圈胡同"（小杨家胡同的谐音）为舞台，描绘了抗日战争时期北京一个胡同中四世同堂的祁家与众邻居在日寇铁蹄下的苦难与抗争。胡同窄而深，两侧院墙高耸，抬头只见一线天空。古槐树在院墙上方伸展枝叶，见证了八年抗战的岁月沧桑。此处是了解老舍抗战文学与老北京胡同生活的最重要文学故地。', '北京', 39.912500, 116.365900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/e/e1/%E5%8C%97%E4%BA%AC%E6%8A%A5%E5%9B%BD%E5%AF%BA%E5%A4%A7%E6%AE%BF_%E6%AD%A3%E9%9D%A2.jpg"]'),
('《四世同堂》', '东城区王府井大街北段老商铺', '老舍', '现代', '王府井大街北段老商铺位于北京市东城区，是老舍《四世同堂》中北京商业繁华的原型地。北段保留有清末民初的商铺建筑与老柜台，盛锡福帽店、瑞蚨祥绸缎庄等老字号的建筑立面展现了民国时期北京商业的辉煌。老舍在《四世同堂》中描绘了日伪统治下北京商业的萧条与商人的无奈——物价飞涨、货源断绝、被迫悬挂日本旗帜。老商铺的红木柜台、铜制秤砣保留着传统经营的痕迹。此处是了解老舍笔下抗战时期北京商业文化与王府井百年商业历史的重要地标。', '北京', 39.928600, 116.416600, '其他', '["https://img0.baidu.com/it/u=730961189,2327301317&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《龙须沟》', '东城区天坛街道龙须沟遗址', '老舍', '现代', '龙须沟遗址位于北京市东城区天坛街道，是老舍《龙须沟》中程疯子等底层市民生活的背景地。遗址保留有清代排水沟遗迹、老民居与纪念馆，展示了解放前龙须沟臭水横流、蚊蝇滋生的恶劣环境。老舍以龙须沟的改造为主题，歌颂了新中国成立后北京城市建设的巨大成就。"程疯子"从疯癫到清醒的转变象征着底层百姓命运的根本改变。纪念馆中的老照片对比了改造前后的巨大变化。此处是了解老舍戏剧艺术与新中国城市建设历程的重要红色文学遗存。', '北京', 39.928600, 116.416600, '其他', '["https://img1.baidu.com/it/u=3536775955,1996588919&fm=253&fmt=auto&app=138&f=JPEG?w=667&h=500"]'),
('《茶馆》', '西城区大栅栏街道广德楼旧址', '老舍', '现代', '广德楼旧址位于北京市西城区大栅栏街道，是老舍《茶馆》中裕泰茶馆的原型地之一。广德楼保留有清末民初的茶馆建筑与老茶桌，是北京现存最古老的戏园子之一。老舍以裕泰茶馆为舞台，通过三幕戏展现了晚清至解放前夕中国社会的沧桑巨变。"莫谈国事"的纸条高悬在墙上，茶客们的命运随时代沉浮。老茶桌上的茶渍已深入木纹，盖碗茶的清香弥漫在古老的戏园子中。此处是感受老舍戏剧艺术巅峰之作与老北京茶馆文化的经典文学场所。', '北京', 39.912500, 116.365900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/a/a6/%E3%80%8A%E5%B9%BF%E5%B7%9E%E5%B8%82%E8%8D%94%E6%B9%BE%E5%8C%BA%E4%BC%A0%E7%BB%9F%E9%A3%8E%E8%B2%8C%E5%BB%BA%E7%AD%91%E4%BF%9D%E6%8A%A4%E5%9B%BE%E5%88%99%E3%80%8B%EF%BC%88%E7%AC%AC%E4%B8%80%E6%89%B9177%E5%A4%84%EF%BC%89%EF%BC%88%E5%85%AC%E7%A4%BA%E7%A8%BF%EF%BC%89.pdf"]'),
('《我与地坛》', '东城区安定门街道地坛公园方泽坛遗址', '史铁生', '现代', '地坛公园方泽坛遗址位于北京市东城区安定门街道，是史铁生《我与地坛》"逃避一个世界的另一个世界"的核心取景地。方泽坛保留有明代建筑与古碑，是明清帝王祭地之所。史铁生在最绝望的年华里独自来到地坛，在这座"荒芜但并不衰败"的古园中思考生死、命运与母爱。"十五年了，我还是总得到那古园里去"——地坛成为他精神的避难所与重生之地。古柏苍翠，石径幽深，残垣断壁在夕阳中投下长长的影子。此处是中国当代文学中最具精神深度的写作之地，也是感受史铁生生命哲学的朝圣之所。', '北京', 39.928600, 116.416600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/c7/%E5%9C%B0%E5%9D%9B%E5%85%AC%E5%9B%AD_1231.jpg"]'),
('《我与地坛》', '东城区安定门街道地坛公园银杏大道', '史铁生', '现代', '地坛公园银杏大道位于北京市东城区安定门街道，是史铁生《我与地坛》中地坛秋日最美的场景。银杏大道保留有明代古银杏树与石板路，深秋时节金黄的银杏叶铺满大道，如同铺了一条黄金地毯。史铁生在轮椅上无数次穿过这条大道，看着叶子从嫩绿到金黄再到飘落，感悟生命的四季轮回。"我在好几篇小说中都提到过一座废弃的古园"——银杏大道正是这座古园中最具季节感的景致。阳光穿过银杏树冠洒下金色光斑。此处是北京最美的秋景之一，也是感受史铁生散文中"生命的季节"意象的诗意空间。', '北京', 39.928600, 116.416600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/74/%E9%9B%AA%E5%B1%B1%E4%B8%8B%E7%9A%84%E6%88%90%E9%83%BD%E5%B8%82%E5%A4%A9%E9%99%85%E7%BA%BF_Chengdu_skyline_with_snow_capped_mountains.jpg"]'),
('《城南旧事》', '西城区椿树街道椿树胡同遗址', '林海音', '现代', '椿树胡同遗址位于北京市西城区椿树街道，是林海音《城南旧事》中英子生活的背景地。遗址保留有清末民初四合院、老门楼与古槐树，胡同蜿蜒幽深，两侧院墙斑驳。林海音以小英子的纯真视角回忆了童年在北京城南的生活——惠安馆的"疯女人"秀贞、被迫做贼的小偷、兰姨娘的故事串联起一幅老北京的市井画卷。"长亭外，古道边，芳草碧连天"的离别旋律贯穿全书。胡同口的小卖部、四合院中的石榴树构成了最温暖的童年记忆。此处是感受《城南旧事》中纯真童年与老北京胡同生活的温情之地。', '北京', 39.912500, 116.365900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/6/6a/%E4%B8%AD%E5%8D%97%E6%B5%B7_%E5%82%8D%E6%99%9A_%E4%B8%9C%E5%8D%97%E4%BE%A7.jpg"]'),
('《城南旧事》', '西城区琉璃厂西街荣宝斋旧址', '林海音', '现代', '琉璃厂西街荣宝斋旧址位于北京市西城区，是林海音《城南旧事》中英子父亲常去的文化街。荣宝斋保留有明清古商铺建筑、老柜台与文房四宝，是中国最著名的书画店之一。琉璃厂自清代以来便是北京文人墨客聚集之地，古玩书画店鳞次栉比。英子的父亲是一位文雅的知识分子，常带英子来琉璃厂购买笔墨纸砚。老柜台上的宣纸、徽墨、湖笔散发着文房的清香。此处是北京文化商业的最高代表，也是了解《城南旧事》中文人家庭生活与琉璃厂百年文化传统的重要地标。', '北京', 39.912500, 116.365900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/75/%E8%8C%B6%E9%A9%AC%E5%8F%A4%E9%81%93%E9%82%9B%E5%B4%83%E5%A4%B9%E5%85%B3%E5%9B%BD%E4%BF%9D%E7%A2%91.jpg"]');
INSERT INTO works (title, scenic_spot, author, dynasty, description, province, latitude, longitude, category, images) VALUES
('《动物凶猛》', '西城区什刹海街道鸦儿胡同', '王朔', '现代', '鸦儿胡同位于北京市西城区什刹海街道，是王朔《动物凶猛》中马小军等人玩耍的背景地。胡同保留有清末民初四合院、老门楼与古槐树，紧邻什刹海后海，是北京最具老城风情的胡同之一。王朔以"动物凶猛"为名描绘了文革时期大院子弟的青春记忆——打架、恋爱、无所事事的荒诞岁月。鸦儿胡同的四合院墙头上曾是少年们翻墙打闹的"战场"。胡同口可望见后海的水面与垂柳，银锭桥上的风景是那个年代北京少年最熟悉的画面。此处是感受王朔京味文学与什刹海老北京胡同生活的独特之地。', '北京', 39.912500, 116.365900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/6/6d/2014.09.04.153332_Ya%27er_Hutong_Beijing.jpg"]'),
('《动物凶猛》', '西城区新街口街道新街口电影院旧址', '王朔', '现代', '新街口电影院旧址位于北京市西城区新街口街道，是王朔《动物凶猛》中马小军看电影的场景地。旧址保留有上世纪五十年代的电影院建筑与老放映厅，高大的门廊与方柱展现了那个年代公共建筑的苏式风格。电影院是文革时期大院子弟重要的社交与娱乐场所，马小军与伙伴们在此看《地道战》《南征北战》，也在此邂逅了青春期的爱情。老放映厅内的木质座椅排列整齐，银幕已泛黄。此处是了解王朔文学中"大院子弟"亚文化与上世纪七十年代北京城市生活的独特历史空间。', '北京', 39.912500, 116.365900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/cf/Temple_of_ancient_monarchs%2C_Beijing%2C_China_-_panoramio.jpg"]'),
('《黄金时代》', '海淀区中关村街道北京大学燕南园', '王小波', '现代', '北京大学燕南园位于北京市海淀区中关村街道，是王小波《黄金时代》的创作背景地之一。燕南园保留有民国时期的小洋楼与古槐树，是北大最幽静的教授住宅区。王小波在北大读书期间深受自由主义思想影响，《黄金时代》中"那一天我二十一岁"的坦率叙事开创了中国当代文学的新风格。园中小楼掩映在古木丛中，学术大师们曾在此居住——冰心、朱光潜、冯友兰的足迹遍布其间。此处弥漫着浓厚的学术与自由气息，是了解王小波文学精神源流与北大百年人文传统的重要空间。', '北京', 39.959300, 116.298200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/0/02/Yuyuantan_Park_2010.jpg"]'),
('《沉默的大多数》', '海淀区中关村街道中国人民大学老校区', '王小波', '现代', '中国人民大学老校区位于北京市海淀区中关村街道，是王小波《沉默的大多数》的创作地。老校区保留有上世纪五十年代的建筑、老礼堂与古槐树，建筑风格体现了苏联援华时期的影响。王小波在人大任教期间写下了大量杂文随笔，以理性、幽默与反讽的笔触探讨中国社会的种种荒诞。"沉默的大多数"已成为中国知识界最广泛引用的概念之一。校园中的林荫道曾是王小波散步思考的地方，老礼堂见证了无数学术讲座与文化活动。此处是感受王小波独立思考精神与中国当代知识分子文化的重要学术空间。', '北京', 39.959300, 116.298200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/d8/Renmin_University_Entrance.JPG"]'),
('《红楼梦》', '海淀区四季青镇曹雪芹故居正白旗村', '曹雪芹', '清代', '曹雪芹故居正白旗村也是《红楼梦》最重要的创作圣地。曹雪芹在此"举家食粥酒常赊"的困顿中完成了中国文学史上最伟大的小说。正白旗村保留有清代民居与曹雪芹纪念馆，展示了曹雪芹从江南富贵之家到北京西山穷困潦倒的人生巨变。"满纸荒唐言，一把辛酸泪。都云作者痴，谁解其中味"道出了创作的艰辛与孤独。纪念馆中陈列有《红楼梦》的版本沿革、脂砚斋批注本影印件与研究资料。香山脚下的秋日红叶与"黛玉葬花"的意境遥相呼应。此处是红学研究者与文学爱好者必访的朝圣之地。', '北京', 39.959300, 116.298200, '其他', '["https://img0.baidu.com/it/u=3329033203,70328571&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《红楼梦》', '西城区什刹海街道恭王府萃锦园遗址', '曹雪芹', '清代', '恭王府萃锦园遗址位于北京市西城区什刹海街道，是《红楼梦》中大观园的原型地之一。萃锦园保留有清代园林建筑、古碑与太湖石假山，"一入园门，便有大块假山挡住"的描写与恭王府的布局高度吻合。园内亭台楼阁依水而建，回廊曲折通幽，"蘅芜苑""潇湘馆"等景点名称与小说中的场景一一对应。恭王府是清代规模最大的王府，"恭王府半部清朝史"的说法广为流传。园中古木参天，太湖石嶙峋，四季景致各异。此处是走进《红楼梦》大观园世界的最直观空间体验。', '北京', 39.912500, 116.365900, '其他', '["https://img0.baidu.com/it/u=2198735899,2678393818&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=652"]'),
('《京华烟云》', '东城区东交民巷老建筑群', '林语堂', '现代', '东交民巷老建筑群位于北京市东城区，是林语堂《京华烟云》中姚家、曾家居所的原型地。东交民巷保留有清末民初的欧式建筑群——法国邮政局、英国公使馆、日本正金银行等建筑风格各异。林语堂以"现代版《红楼梦》"的气魄描绘了民国时期北京上层社会的家族兴衰，姚木兰与曾荪亚的爱情故事贯穿全书。东交民巷曾是各国使馆区，中西文化在此碰撞交融。建筑立面上的巴洛克雕饰、拱形窗户与铸铁阳台保留了殖民时期的原始风貌。此处是感受《京华烟云》中民国北京上流社会生活与东交民巷百年建筑之美的独特空间。', '北京', 39.928600, 116.416600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/57/%E5%8C%97%E4%BA%AC%E5%B8%82%E4%B8%9C%E5%9F%8E%E5%8C%BA%E5%9B%BD%E6%B0%91%E7%BB%8F%E6%B5%8E%E5%92%8C%E7%A4%BE%E4%BC%9A%E5%8F%91%E5%B1%95%E7%AC%AC%E5%8D%81%E5%9B%9B%E4%B8%AA%E4%BA%94%E5%B9%B4%E8%A7%84%E5%88%92%E5%92%8C%E4%BA%8C%E3%80%87%E4%B8%89%E4%BA%94%E5%B9%B4%E8%BF%9C%E6%99%AF%E7%9B%AE%E6%A0%87%E7%BA%B2%E8%A6%81.pdf"]'),
('《京华烟云》', '西城区什刹海街道后海北沿老洋房', '林语堂', '现代', '后海北沿老洋房位于北京市西城区什刹海街道，是林语堂《京华烟云》中北京上层社会生活的原型地。老洋房保留有民国时期的欧式建筑与老花园，古槐树枝繁叶茂。林语堂笔下的姚家生活优雅从容，后海一带正是民国时期北京名门望族聚居之地。后海水面波光粼粼，垂柳拂岸，远处鼓楼钟楼巍然矗立。民国时期的洋房花园中，名媛淑女品茗赏花，文人雅士吟诗作画。此处将什刹海的老北京风情与民国上流社会的生活方式完美融合，是了解《京华烟云》文学背景与老北京名门文化的优雅之地。', '北京', 39.912500, 116.365900, '其他', '["https://img0.baidu.com/it/u=263041772,4173855784&fm=253&fmt=auto&app=138&f=JPEG?w=1067&h=800"]'),
('《北京人》', '东城区交道口街道南锣鼓巷北段老胡同', '曹禺', '现代', '南锣鼓巷北段老胡同位于北京市东城区交道口街道，是曹禺《北京人》中曾家大院的原型地。老胡同保留有清末民初四合院、老门楼与古槐树，胡同宽而深，两侧院落规整。曹禺在《北京人》中描绘了一个没落的封建大家庭在抗战前夕的精神困境——曾皓、曾文清等人物各怀心事，在旧时代的阴影中苟延残喘。四合院的高墙大院既是庇护也是囚笼，正如曹禺所揭示的封建家族制度的双重性。古槐树荫庇着院落，门楼上的砖雕已模糊不清。此处是感受曹禺戏剧中"北京人"精神困境与老北京四合院建筑之美的文学地标。', '北京', 39.928600, 116.416600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/2/2d/Skyline_of_Beijing_CBD_with_B-5906_approaching_%2820211016171955%29_%281%29.jpg"]'),
('《雷雨》', '东城区东交民巷圣弥额尔天主堂', '曹禺', '现代', '东交民巷圣弥额尔天主堂位于北京市东城区，是曹禺《雷雨》中周朴园公馆的原型地之一。天主堂保留有清末民初的欧式建筑与老花园，哥特式尖塔直指天空。曹禺以周朴园的公馆为舞台，揭示了封建资产阶级家庭的虚伪与罪恶。天主堂的欧式建筑风格与周朴园"留学德国"的人设吻合——外表文明优雅，内里专制残酷。教堂内彩色玻璃窗在阳光下流光溢彩，庄严的管风琴声回荡在穹顶之下。此处是感受曹禺戏剧艺术中"雷雨"般的家族冲突与东交民巷异国建筑风情的独特之地。', '北京', 39.928600, 116.416600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/f/f2/Djmx_church01.jpg"]'),
('《文化苦旅・道士塔》', '海淀区颐和园万寿山佛香阁遗址', '余秋雨', '现代', '颐和园万寿山佛香阁遗址位于北京市海淀区，是余秋雨《文化苦旅·道士塔》中北京历史的见证地之一。佛香阁保留有清代建筑与古碑，是颐和园的标志性建筑，高达41米，矗立在万寿山之巅。余秋雨在《文化苦旅》中以道士塔为切入点探讨中国文化遗产的流失与保护，佛香阁作为皇家建筑文化的代表形成了一种对照。阁上远眺昆明湖碧波万顷，十七孔桥如长虹卧波。古柏苍翠环绕，琉璃瓦在阳光下金光闪烁。此处是感受清代皇家建筑巅峰之作与余秋雨文化反思精神的壮美之地。', '北京', 39.959300, 116.298200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/0/06/%E9%A2%90%E5%92%8C%E5%9B%AD%E4%B8%87%E5%AF%BF%E5%B1%B1%E4%BD%9B%E9%A6%99%E9%98%81.jpg"]'),
('《文化苦旅・莫高窟》', '房山区云居寺石经山雷音洞遗址', '余秋雨', '现代', '云居寺石经山雷音洞遗址也是余秋雨《文化苦旅·莫高窟》中佛教文化的重要参照地。雷音洞保留有隋代石经板、古碑与石窟，是中国佛教石刻文化的最高成就。余秋雨在《莫高窟》中以敦煌为中心探讨佛教艺术的辉煌与文化的脆弱，云居寺的石经同样体现了古代僧人"以石为纸"的文化保存智慧。石经山上九个洞窟中镶嵌着数千块石经板，僧人们历经千年接力刻经的毅力令人敬畏。此处是与敦煌莫高窟并列的中国佛教文化瑰宝，也是理解余秋雨文化苦旅精神的重要一站。', '北京', 39.748700, 116.143300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/a/a1/Entrance_to_Yunju_Temple_%2820150223134448%29.JPG"]'),
('《雅舍小品》', '东城区东四街道梁实秋故居', '梁实秋', '现代', '东四街道梁实秋故居位于北京市东城区，是梁实秋创作《雅舍小品》的居所之一。故居保留有民国建筑与梁实秋生平陈列，四合院格局方正，院中古槐如盖。梁实秋在北京生活多年，北京的四合院、胡同、茶馆、小吃构成了他散文中最温暖的生活素材。"一碗豆汁儿配焦圈""涮羊肉的铜锅"——梁实秋以幽默优雅的笔触将最平凡的日常升华为文学。故居所在的东四胡同幽静古朴，青砖灰瓦的院墙在阳光下投出温暖的影子。此处是感受梁实秋闲适散文之美与老北京四合院生活的文学故居。', '北京', 39.928600, 116.416600, '其他', '["https://img0.baidu.com/it/u=1850125893,2595713050&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=652"]'),
('《最后一次的讲演》', '西城区长安街李公朴殉难处', '闻一多', '现代', '长安街李公朴殉难处位于北京市西城区，是闻一多《最后一次的讲演》的创作背景地。殉难处保留有民国碑刻、古柏与纪念雕像，铭记着李公朴为民主自由而牺牲的英勇事迹。闻一多在昆明得知李公朴被刺后悲愤交加，发表了激昂的"最后一次的讲演"，随后也惨遭暗杀。北京长安街上的纪念碑将这段历史永远铭刻。闻一多"拍案而起"的形象成为中国知识分子为真理献身的永恒象征。古柏苍翠挺拔，纪念雕像目光坚毅。此处是缅怀民主先烈与感受知识分子"士可杀不可辱"精神的庄严纪念之地。', '北京', 39.912500, 116.365900, '其他', '["https://img1.baidu.com/it/u=3149878953,1536537897&fm=253&fmt=auto&app=120&f=JPEG?w=500&h=706"]'),
('《青春之歌》', '海淀区中关村街道清华大学老图书馆', '杨沫', '现代', '清华大学老图书馆位于北京市海淀区中关村街道，是杨沫《青春之歌》中林道静参加革命的背景地之一。老图书馆保留有民国建筑、老书架与古槐树，建筑风格庄严典雅，红砖灰石。杨沫在《青春之歌》中描绘了一二九运动时期清华学生投身抗日救亡运动的热血场景。老图书馆曾是学生自治运动的集会地点，阶梯教室中回荡着"停止内战，一致对外"的呼声。古槐树下的林荫道见证了那个激情燃烧的年代。此处是感受民国时期学生运动精神与清华百年学术传统的重要历史空间。', '北京', 39.959300, 116.298200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/0/02/Yuyuantan_Park_2010.jpg"]'),
('《红旗谱》', '西城区金融街街道京汉铁路总工会旧址', '梁斌', '现代', '京汉铁路总工会旧址位于北京市西城区金融街街道，是梁斌《红旗谱》中工人运动的原型地。旧址保留有上世纪二十年代的建筑、老照片与古碑，记载了1923年京汉铁路工人大罢工的壮烈历史。梁斌在《红旗谱》中将北方工人阶级的觉醒与斗争融入家族叙事，京汉铁路工人运动是其中最重要的历史背景。旧址内展示有罢工时期的传单、旗帜与领导人照片，再现了"二七"大罢工的悲壮场景。此处是了解中国早期工人运动史与梁斌红色文学创作背景的重要革命遗存。', '北京', 39.912500, 116.365900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/b/b1/Revolution_of_1911_Museum.jpg"]'),
('《野火春风斗古城》', '西城区大栅栏街道地下党活动旧址', '李英儒', '现代', '大栅栏街道地下党活动旧址位于北京市西城区，是李英儒《野火春风斗古城》中共产党员秘密活动的场景地。旧址保留有清末民初的民居建筑、老地道与古碑，房屋中的暗门、密室与地道展示了地下工作者的隐蔽智慧。李英儒以抗日战争时期华北敌后为背景，描绘了杨晓冬等共产党员深入敌占区开展地下斗争的惊险故事。大栅栏自古为北京商业中心，人流密集的商业街区正是地下工作者活动的理想掩护。此处是了解抗日战争时期地下党斗争历史与大栅栏老城区风貌的重要红色遗存。', '北京', 39.912500, 116.365900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/9d/Red_building_of_Peking_University.JPG"]'),
('《敌后武工队》', '房山区十渡风景区抗日旧址', '冯志', '现代', '十渡风景区抗日旧址位于北京市房山区，是冯志《敌后武工队》中抗日故事的背景地。旧址保留有抗日时期的密营、战壕与瀑布，峡谷中的隐蔽地形曾是敌后武工队活动的天然掩护。冯志以冀中平原敌后武工队的真实经历为素材，描绘了抗日军民在敌人"铁壁合围"中坚持斗争的英勇事迹。十渡峡谷蜿蜒幽深，拒马河水清澈，两岸山峰如屏。密营藏于山洞之中，从外部几乎无法发现。此处将北京近郊的壮美山水与抗日战争的红色记忆完美融合，是感受敌后抗战历史与京郊山水之美的独特之地。', '北京', 39.748700, 116.143300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/1b/%E6%B9%96%E5%8C%97%E7%9C%81%E4%B8%8D%E5%8F%AF%E7%A7%BB%E5%8A%A8%E9%9D%A9%E5%91%BD%E6%96%87%E7%89%A9%E5%90%8D%E5%BD%95%EF%BC%88%E7%AC%AC%E4%B8%80%E6%89%B9%EF%BC%89.pdf"]'),
('《北京的春节》', '东城区龙潭湖公园龙潭庙会遗址', '老舍', '现代', '龙潭湖公园龙潭庙会遗址位于北京市东城区，是老舍《北京的春节》中庙会场景的原型地。遗址保留有清代建筑、古碑与传统民俗表演场所，每年春节期间龙潭庙会仍是北京最热闹的庙会之一。老舍以细腻温暖的笔触描绘了老北京过年的全过程——腊八粥、糖瓜祭灶、除夕守岁、初一拜年，庙会是其中最欢乐的高潮。庙会上的糖葫芦、风车、面人、空竹表演构成了最浓郁的年味。锣鼓喧天的舞狮舞龙队伍在人群中穿行。此处是感受老舍散文中老北京年俗文化与龙潭庙会百年传统的欢乐之地。', '北京', 39.928600, 116.416600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/57/%E5%8C%97%E4%BA%AC%E5%B8%82%E4%B8%9C%E5%9F%8E%E5%8C%BA%E5%9B%BD%E6%B0%91%E7%BB%8F%E6%B5%8E%E5%92%8C%E7%A4%BE%E4%BC%9A%E5%8F%91%E5%B1%95%E7%AC%AC%E5%8D%81%E5%9B%9B%E4%B8%AA%E4%BA%94%E5%B9%B4%E8%A7%84%E5%88%92%E5%92%8C%E4%BA%8C%E3%80%87%E4%B8%89%E4%BA%94%E5%B9%B4%E8%BF%9C%E6%99%AF%E7%9B%AE%E6%A0%87%E7%BA%B2%E8%A6%81.pdf"]'),
('《北平的四季》', '西城区什刹海街道什刹海荷花市场遗址', '郁达夫', '现代', '什刹海荷花市场遗址位于北京市西城区什刹海街道，是郁达夫《北平的四季》中夏日荷花盛开的描绘地。遗址保留有清代码头、古碑与荷花池，夏日荷花满池粉红，"接天莲叶无穷碧"的景象在此完美呈现。郁达夫以深情的笔触描绘了北平四季的独特魅力——"北平的夏天也有它的特别的好处"。什刹海荷花市场在清代便是京城消暑纳凉的胜地，茶棚、凉棚沿湖而设，文人雅士在此品茗赏荷。黄昏时分晚霞映照在荷塘水面上，钟鼓楼的剪影倒映在碧水之中。此处是感受郁达夫笔下北平夏日风情与什刹海千年荷韵的诗意空间。', '北京', 39.912500, 116.365900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/1c/Platform_of_Beihai_North_Station_%2820210929183514%29.jpg"]'),
('《观沧海》', '秦皇岛市昌黎县碣石山仙台顶遗址', '曹操', '东汉', '碣石山仙台顶遗址位于河北省秦皇岛市昌黎县，是曹操《观沧海》的真实登临地。仙台顶保留有汉代观海台基址与古碑，"东临碣石，以观沧海"正是曹操北征乌桓凯旋途中在此登山观海所作。站在仙台顶上，渤海浩渺无际，"日月之行，若出其中；星汉灿烂，若出其里"的宇宙意象扑面而来。碣石山自古为"神岳"，秦始皇、汉武帝均曾登临。山上松柏苍翠，怪石嶙峋，海风劲吹。此处是感受曹操诗歌中帝王气魄与渤海壮阔景观的文学圣地。', '河北', 39.712700, 119.162500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/1a/Qinhuangdao_%E7%A7%A6%E7%9A%87%E5%B2%9B.jpg"]'),
('《易水歌》', '保定市易县荆轲塔遗址', '荆轲', '战国', '荆轲塔遗址位于河北省保定市易县，是荆轲"风萧萧兮易水寒，壮士一去兮不复还"的出发地。遗址保留有辽代砖塔、荆轲墓与古碑，塔身八角十三层，矗立在荒野之中。荆轲受燕太子丹之托赴秦刺杀秦王，在易水边与众人告别，高渐离击筑而歌，"士皆垂泪涕泣"。荆轲塔塔身风化严重但雄浑依旧，周边荒草萋萋，易水河在远处静静流淌。秋日塔影投射在枯黄的原野上，悲壮之气弥漫。此处是中国古代最悲壮的送别之地，也是感受荆轲侠义精神与易水千年悲歌的朝圣之所。', '河北', 39.348900, 115.497600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/df/Qxl.JPG"]'),
('《送魏大从军》', '张家口市怀来县鸡鸣驿古城遗址', '陈子昂', '唐代', '鸡鸣驿古城遗址位于河北省张家口市怀来县，是陈子昂《送魏大从军》的送别地。古城保留有明代城墙、城门与古驿舍，是中国现存最完整的古代驿站。城墙周长近两公里，夯土城墙上的马道仍可通行。陈子昂在此送别友人从军赴边，"匈奴犹未灭，魏绛复从戎"的豪迈诗句在古城中回荡。驿城内保留有驿丞署、公馆院、马号等完整的邮驿建筑系统，展现了明清时期官方通信系统的严密。城墙外的鸡鸣山巍然矗立，暮色中的古城静谧而苍凉。此处是了解中国古代驿站制度与边塞送别诗文化的最佳实物遗存。', '河北', 40.415400, 115.517700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/9f/Jimingyi_1.jpg"]'),
('《燕歌行》', '承德市宽城县喜峰口长城遗址', '高适', '唐代', '喜峰口长城遗址位于河北省承德市宽城县，是高适《燕歌行》"汉家烟尘在东北"的描绘地。遗址保留有明代长城、敌楼与古战场，长城蜿蜒在陡峭的山脊之上。喜峰口自古为北方重要军事关隘，辽金元明清各代均有激烈战事。高适以此为背景描绘了边疆战士的悲壮与将帅的腐败，"战士军前半死生，美人帐下犹歌舞"的对比令人痛心。敌楼残垣在山巅矗立，长城如巨龙在群山间起伏。1933年喜峰口抗战更为此地增添了近代抗日的悲壮色彩。此处是感受边塞诗与长城军事文化的壮美之地。', '河北', 40.611400, 118.492000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/43/2016%E5%B9%B4%E5%BA%A6%E5%85%A8%E5%9B%BD%E5%8D%9A%E7%89%A9%E9%A6%86%E5%90%8D%E5%BD%95.pdf"]'),
('《渡易水》', '保定市易县易水古渡遗址', '骆宾王', '唐代', '易水古渡遗址位于河北省保定市易县，是骆宾王《渡易水》"此地别燕丹，壮士发冲冠"的创作地。古渡保留有明清古码头、古碑与渡船遗迹，易水河在此处流势平缓。骆宾王路过易水时触景生情，想起荆轲刺秦的悲壮往事，以"昔时人已没，今日水犹寒"表达了对英雄的缅怀与时光流逝的感慨。古码头的石阶被水流冲刷得光滑圆润，渡口两岸垂柳依依。秋日河水清澈见底，水面倒映着两岸金黄的树叶。此处是感受初唐诗歌中怀古伤今情怀与易水千年古渡风光的诗意之地。', '河北', 39.348900, 115.497600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/df/Qxl.JPG"]'),
('《铜雀台》', '邯郸市临漳县铜雀台遗址', '杜牧', '唐代', '铜雀台遗址位于河北省邯郸市临漳县，是杜牧《赤壁》"铜雀春深锁二乔"的描绘地。遗址保留有汉代夯土台基与古碑，铜雀台为三国曹操所建，与金虎台、冰井台并称"邺城三台"。曹操在此宴饮赋诗，"对酒当歌，人生几何"的豪情至今回荡。台基高约十余米，虽历经两千年风雨侵蚀但规模依然可辨。临漳县是古代邺城所在地，曹魏文化遗迹丰富。夕阳下的夯土台基投射出巨大的影子，"铜雀春深"的繁华早已化为尘土。此处是了解曹魏文化与三国历史的重要考古遗址，也是感受杜牧咏史诗意境的文学故地。', '河北', 36.335200, 114.619400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/7b/%E6%AD%A6%E7%81%B5%E4%B8%9B%E5%8F%B0_10.jpg"]'),
('《邯郸冬至夜思家》', '邯郸市丛台区丛台遗址', '白居易', '唐代', '丛台遗址位于河北省邯郸市丛台区，是白居易《邯郸冬至夜思家》"抱膝灯前影伴身"的创作地。丛台保留有战国夯土台基与古碑，为赵武灵王所建，是赵国检阅军队与观看歌舞的场所。白居易冬至之夜寓居邯郸，孤独思乡，"想得家中夜深坐，还应说着远行人"的温暖笔触感动了千百年来的游子。丛台虽经历代修缮但基址未变，登台远眺可俯瞰邯郸古城全貌。"胡服骑射"的改革精神与"邯郸学步"的成语故事均源于此地。此处是感受战国赵文化与唐代思乡诗意境的历史名胜。', '河北', 36.636300, 114.493000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/74/%E6%B2%B3%E5%8C%97%E9%82%AF%E9%83%B8%E5%B8%82%E6%B0%91%E7%94%A8%E2%80%9C%E6%AF%9B%E7%8C%B4%E2%80%9D%E6%8A%80%E8%89%BA%E5%86%8D%E7%8E%B0%E6%88%90%E8%AF%AD%E6%95%85%E4%BA%8B%E5%9C%BA%E6%99%AF.webm"]'),
('《赵州桥》', '石家庄市赵县赵州桥遗址', '汪遵', '唐代', '赵州桥遗址位于河北省石家庄市赵县，是汪遵"百尺长虹横水面"的描绘地。赵州桥又名安济桥，建于隋代大业年间，由匠师李春设计建造，是世界现存最古老的敞肩石拱桥。桥身全长64.4米，单孔净跨37.02米，桥面宽阔平坦。桥身上雕刻有精美的龙凤纹饰与力士像，栏板上的浮雕历经一千四百余年仍清晰可辨。赵州桥以巧妙的力学结构实现了"桥上行人桥下船"的通行需求，在世界桥梁史上具有里程碑意义。洨河水在桥下静静流淌，映照着古桥优美的弧线。此处是中国古代工程智慧的最高代表之一。', '河北', 37.756200, 114.776200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/72/Anji_Bridge%2C_Zhao_County%2C_2020-09-06_05.jpg"]'),
('《出塞》', '秦皇岛市山海关区老龙头遗址', '王昌龄', '唐代', '老龙头遗址位于河北省秦皇岛市山海关区，是王昌龄《出塞》"秦时明月汉时关"的描绘地。老龙头是万里长城唯一入海处，长城如巨龙探入渤海，气势磅礴。遗址保留有明代长城、海神庙与澄海楼，城墙在海浪拍打下矗立数百年。王昌龄以雄浑笔触描绘了边关将士的豪情与思乡之情，"但使龙城飞将在，不教胡马度阴山"的壮志千年不灭。海神庙面朝大海，庙内供奉天后圣母。登上澄海楼可远眺渤海与长城交汇的壮观景象。此处是万里长城最具视觉震撼力的景观，也是感受边塞诗豪迈气概的绝佳之地。', '河北', 40.000000, 119.775900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/9c/Qinhuangdao_Shanhaiguan_Airport_2020.jpg"]'),
('《使至塞上》', '张家口市张北县野狐岭遗址', '王维', '唐代', '野狐岭遗址位于河北省张家口市张北县，是王维《使至塞上》"大漠孤烟直，长河落日圆"的有感而发之地。野狐岭是古代中原与草原的天然分界线，海拔约1600米，北望坝上草原辽阔无际，南眺华北平原沃野千里。遗址保留有古战场遗迹与烽火台，成吉思汗曾在此以少胜多大败金军。王维出使河西途经此地，荒凉壮阔的塞外景象激发了千古名句。秋日草原金黄，大风呼啸，天地之间只有人与自然的对话。此处是感受唐代边塞诗中雄浑壮美意境与蒙古高原苍茫风光的最佳观景地。', '河北', 41.158900, 114.719600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/2/2b/%E6%B8%85%E6%B2%B3%E5%B2%B8%E4%B8%8A%E6%98%AF%E6%88%91%E5%AE%B6_-_panoramio.jpg"]'),
('《白雪歌送武判官归京》', '承德市围场县塞罕坝将军泡子遗址', '岑参', '唐代', '塞罕坝将军泡子遗址位于河北省承德市围场县，是岑参《白雪歌送武判官归京》"忽如一夜春风来，千树万树梨花开"的描绘地。将军泡子保留有清代古战场遗址、湖泊与辽阔草原，康熙曾在此围猎并击败噶尔丹叛军。岑参以奇丽的笔触描绘了边塞雪景的壮美与送别友人的深情。冬季银装素裹，白桦林在雪中如梨花绽放；夏季草原碧绿，野花遍地，湖水如镜。"瀚海阑干百丈冰，愁云惨淡万里凝"的苍茫意境在此得到完美呈现。此处是感受唐代边塞诗与坝上草原四季之美的壮丽之地。', '河北', 41.938000, 117.760000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/31/Paektu-san.jpg"]'),
('《登恒山》', '大同市浑源县恒山悬空寺遗址', '贾岛', '唐代', '悬空寺遗址位于山西省大同市浑源县恒山金龙峡，是贾岛"恒岳居其北"的描绘地。悬空寺始建于北魏太和十五年，距今已有一千五百余年历史，是中国唯一的佛道儒三教合一的独特寺庙。寺院依山势凌空而建，整座建筑嵌入悬崖峭壁之中，仅靠数根立木支撑，令人叹为观止。殿宇楼阁之间以栈道相连，最高处距地面约50米。殿内保存有北魏至明代的佛像、壁画与碑刻。恒山为五岳之北岳，自古以"险"著称。此处是中国古代建筑奇迹与恒山险峻之美的最佳体现，也是了解北魏佛教文化的重要遗存。', '山西', 39.698200, 113.699100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/de/Hangingtemple20190929.jpg"]'),
('《塞上曲》', '张家口市宣化区清远楼遗址', '王昌龄', '唐代', '清远楼遗址位于河北省张家口市宣化区，是王昌龄《塞上曲》"不破楼兰终不还"的有感而发之地。清远楼保留有明代钟楼与古碑，是宣化古城的标志性建筑。楼高25米，三层木结构，四面设券门，通达四条大街，故又称"钟楼"。楼内悬挂明代大钟一口，重约千斤。宣化自古为边塞重镇，辽金时期即为军事要地，明代更是九边重镇之一。王昌龄笔下的边塞将士保家卫国的豪情在此得到真实的历史呼应。登楼远眺可见宣化古城全貌与远处燕山群峰。此处是了解明代边防军事文化与宣化古城历史的重要地标。', '河北', 40.608500, 115.054800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/2/28/%E9%92%9F%E6%A5%BC%EF%BC%88%E6%B8%85%E8%BF%9C%E6%A5%BC%EF%BC%89%E5%8D%97%E5%90%91.jpg"]'),
('《从军行》', '承德市滦平县金山岭长城西段遗址', '杨炯', '唐代', '金山岭长城西段遗址位于河北省承德市滦平县，是杨炯《从军行》"宁为百夫长，胜作一书生"的描绘地。金山岭长城被誉为万里长城最精华的段落，保留有明代长城、敌楼67座，城墙蜿蜒于崇山峻岭之间。西段敌楼密集，城墙保存完好，未经现代修缮，保留了最原始的长城风貌。杨炯以"初唐四杰"之笔描绘了从军报国的豪情壮志。晨雾中的长城如游龙穿行于云海之间，日出时分金色的阳光洒在古老的城墙上。秋季红叶映衬着灰色城墙，色彩绚烂。此处是摄影家天堂与感受长城原始之美的最佳之地。', '河北', 40.941500, 117.332800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/9c/Great_Wall_of_China_at_Jinshanling_5.jpg"]'),
('《题苍岩山》', '石家庄市井陉县苍岩山桥楼殿遗址', '李世民', '唐代', '苍岩山桥楼殿遗址位于河北省石家庄市井陉县，是唐太宗李世民"云边起梵宫"的描绘地。桥楼殿建于隋代，横跨在两崖绝壁之间的天然石桥之上，是中国最奇特的古建筑之一。殿宇凌空飞架，下临深谷百余米，"桥殿飞虹"的奇观令人叹为观止。殿内保留有隋唐至明清的佛像、壁画与碑刻。苍岩山自古为"太行八陉"之要塞，山势险峻，古柏参天。电影《卧虎藏龙》中李慕白纵身一跃的场景即取景于此。此处是中国古代建筑与自然完美结合的典范，也是感受太行山雄奇险秀之美的绝佳之地。', '河北', 38.032300, 114.145100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/ce/Mount_cangyan_2007.jpg"]'),
('《晓渡滹沱河》', '石家庄市正定县滹沱河古渡遗址', '刘因', '元代', '滹沱河古渡遗址位于河北省石家庄市正定县，是元代诗人刘因《晓渡滹沱河》"寒声入雁行"的创作地。古渡保留有明清古码头、古碑与渡船遗迹，滹沱河自太行山奔流而出，在正定城下形成宽阔的水面。正定古城自古为华北重镇，"九省通衢"的地理优势使古渡成为南北交通的枢纽。刘因清晨渡河时被萧瑟的秋景所感，雁阵南飞、寒声入耳，写下了这首触动人心的诗作。古码头石阶被河水冲刷得光滑圆润，河面上偶有白鹭飞过。此处是感受元代诗歌中北方河流景致与正定古城千年渡口文化的幽静之地。', '河北', 38.146500, 114.570500, '其他', '["https://img0.baidu.com/it/u=3018301193,2028679127&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《黄金台》', '保定市定兴县黄金台遗址', '陈子昂', '唐代', '黄金台遗址位于河北省保定市定兴县，是陈子昂"遥望黄金台"描绘的招贤圣地。遗址保留有战国夯土台基与古碑，传说燕昭王在此筑台置金招纳天下贤士，郭隗、乐毅、邹衍等人才纷至沓来，燕国因此强盛。陈子昂以黄金台为典故表达了怀才不遇的感慨，"前不见古人，后不见来者"的孤独呐喊穿越千年。台基高约数米，虽经两千余年风雨但轮廓仍可辨识。周边田野开阔，秋日金黄的庄稼在风中摇曳。此处是中国古代"尊贤重士"理念的重要象征地，也是感受初唐诗人壮志难酬心境的历史名胜。', '河北', 39.263000, 115.808000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/df/Qxl.JPG"]'),
('《丛台》', '邯郸市丛台区丛台七贤祠遗址', '李白', '唐代', '丛台七贤祠遗址位于河北省邯郸市丛台区，是李白"鼓震丛台倾"创作地。七贤祠保留有明代建筑与古碑，纪念赵国七位贤士——蔺相如、廉颇、赵奢、李牧等。李白游历邯郸时登丛台怀古，追忆赵国鼎盛时期的辉煌。丛台始建于战国时期赵武灵王时代，历经两千多年，是邯郸的精神地标。祠内保留有七贤石像与历代文人题诗碑刻。"胡服骑射"的改革故事与"完璧归赵"的外交智慧均发生在此城之中。登台远眺，邯郸古城尽收眼底。此处是了解战国赵文化与李白怀古诗意境的重要文化遗存。', '河北', 36.636300, 114.493000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/7b/%E6%AD%A6%E7%81%B5%E4%B8%9B%E5%8F%B0_10.jpg"]'),
('《送李侍御赴安西》', '保定市定州市开元寺塔遗址', '高适', '唐代', '开元寺塔遗址位于河北省保定市定州市，是高适《送李侍御赴安西》"心事一杯中"的送别地。开元寺塔又名料敌塔，建于北宋真宗年间，高83.7米，是中国现存最高的砖塔。塔身十一层八角形，外观雄伟挺拔。定州自古为军事重镇，此塔兼具宗教与军事瞭望功能。高适在此送别友人远赴安西都护府，"功名万里外，心事一杯中"表达了对友人前途的祝福与离别的惆怅。登塔可远眺华北平原辽阔景象。塔内保留有宋代壁画与碑刻。此处是中国古代砖塔建筑的巅峰之作，也是感受唐代送别诗文化的历史名塔。', '河北', 38.516200, 114.990200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/43/Dingzhou_Liaodi_Pagoda_3.jpg"]'),
('《北征》', '石家庄市井陉县苍岩山古驿道遗址', '杜甫', '唐代', '苍岩山古驿道遗址位于河北省石家庄市井陉县，是杜甫《北征》"寒月照白骨"的描绘地。古驿道保留有唐代驿路与古石桥，是古代晋冀交通的重要通道。杜甫在安史之乱期间北上觐见唐肃宗，途经此地目睹战争的惨烈——"乾坤含疮痍，忧虞何时毕"的沉痛呐喊令人动容。驿道蜿蜒在太行山深处，两侧悬崖峭壁，古柏苍翠。石板路上的车辙印痕记录了千年的行旅。秋日山色斑斓，古驿道在金黄与殷红中蜿蜒前行。此处是感受杜甫诗歌中忧国忧民情怀与太行古道沧桑之美的重要文学遗存。', '河北', 38.032300, 114.145100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/b/b6/Liberation_Square%2C_Shijiazhuang.jpg"]'),
('《塞下曲》', '张家口市赤城县独石口长城遗址', '卢纶', '唐代', '独石口长城遗址位于河北省张家口市赤城县，是卢纶《塞下曲》"单于夜遁逃"的描绘地。遗址保留有明代长城与敌楼，城墙沿山脊蜿蜒，气势磅礴。独石口自古为北方草原通往中原的重要关隘，"独石孤悬"的险要地形使其成为历代兵家必争之地。卢纶以"月黑雁飞高，单于夜遁逃。欲将轻骑逐，大雪满弓刀"的简练笔触描绘了边疆战事的紧张与将士的英勇。长城敌楼在群山中矗立，周边游客稀少，保留着最原始的荒凉之美。此处是感受唐代边塞诗与明代长城军事防御体系的野性之地。', '河北', 40.912600, 115.831300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/2/23/The_Great_Wall_of_China_at_Jinshanling-edit.jpg"]'),
('《长城》', '秦皇岛市山海关区角山长城遗址', '徐渭', '明代', '角山长城遗址位于河北省秦皇岛市山海关区，是明代徐渭"长城万里跨龙头"的描绘地。角山是万里长城从老龙头入海后第一座翻越的高峰，长城在此陡然攀升，坡度近60度。遗址保留有明代长城、敌楼与栖贤寺，城墙保存完好。徐渭以豪放的笔触描绘了长城跨越山海的雄姿。登上角山长城最高处可同时远眺渤海碧波与燕山群峰，"山海相依"的壮观景象令人震撼。晨曦中海雾弥漫，长城若隐若现如仙境。此处是万里长城"山海"二字的最佳诠释地，也是感受明代长城建筑艺术与山海关雄伟气势的绝佳之地。', '河北', 40.000000, 119.775900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/b/b2/Shanhaiguan.jpg"]'),
('《避暑山庄》', '承德市双桥区避暑山庄烟雨楼遗址', '乾隆', '清代', '避暑山庄烟雨楼遗址位于河北省承德市双桥区，是乾隆"凭栏俯瞰水云乡"的创作地。烟雨楼是避暑山庄内最具诗意的建筑之一，仿嘉兴南湖烟雨楼而建，矗立在如意洲上。楼高两层，四面环水，烟雨蒙蒙时如同江南水乡。避暑山庄是中国现存最大的皇家园林，占地面积达564万平方米，集南北园林之大成。乾隆帝多次在烟雨楼赋诗题字，留下大量诗文。楼前湖水如镜，荷叶田田，远处山峦起伏。此处是了解清代皇家园林艺术巅峰成就与乾隆诗文创作背景的重要文化遗产。', '河北', 40.974700, 117.943300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/b/bc/Chengde_Mountain_Resort_22630-Chengde_%2842954495010%29.jpg"]'),
('《普陀宗乘之庙》', '承德市双桥区普陀宗乘之庙大红台遗址', '乾隆', '清代', '普陀宗乘之庙大红台遗址位于河北省承德市双桥区，是乾隆"巍巍耸碧空"的描绘地。大红台是普陀宗乘之庙的核心建筑，仿拉萨布达拉宫而建，高25米，外墙涂以红色，气势恢宏。普陀宗乘之庙俗称"小布达拉宫"，是承德外八庙中规模最大的一座，为清代接待蒙藏贵族而建。庙内保留有清代佛像、壁画与碑刻，融合了汉藏建筑艺术的精华。乾隆以此庙象征多民族国家的大一统，具有重要的政治与宗教意义。此处是了解清代民族政策与藏传佛教建筑艺术的重要皇家寺庙。', '河北', 40.974700, 117.943300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/a/a2/Putuo_Zongcheng_Temple.jpg"]'),
('《白洋淀》', '保定市安新县白洋淀荷花大观园遗址', '康熙', '清代', '白洋淀荷花大观园遗址位于河北省保定市安新县，是康熙"帆开远树丛"的描绘地。白洋淀是华北平原最大的淡水湖泊，由143个淀泊组成，总面积366平方公里。大观园保留有清代古码头、荷花池与古碑，夏季千亩荷花竞相绽放，"接天莲叶无穷碧，映日荷花别样红"的景象在此完美呈现。康熙与乾隆均多次驾临白洋淀，留下大量诗文。淀中芦苇丛生，水鸟翔集，是华北地区最重要的湿地生态系统。抗日战争时期的"雁翎队"也在此留下了传奇故事。此处是感受华北水乡风光与白洋淀千年文化的生态之地。', '河北', 38.935300, 115.935500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/5c/%E7%99%BD%E6%B4%8B%E6%B7%80%E6%99%AF%E5%8C%BA%E7%9A%84%E6%99%9A%E9%9C%9E.jpg"]'),
('《狼牙山》', '保定市易县狼牙山棋盘陀遗址', '聂荣臻', '现代', '狼牙山棋盘陀遗址位于河北省保定市易县，是"狼牙山五壮士"英勇事迹的发生地。1941年秋，八路军五位战士为掩护部队和群众转移，在弹尽粮绝后跳下悬崖，其中三人壮烈牺牲，两人被树枝挂住幸存。棋盘陀海拔约1105米，山势险峻，悬崖绝壁。遗址保留有抗战纪念碑、纪念亭与原始森林，纪念碑上镌刻着"狼牙山五壮士纪念塔"大字。登上棋盘陀可俯瞰易水河谷与太行群山。此处是中国抗日战争中最悲壮的英雄故事发生地，是进行爱国主义教育与缅怀抗日先烈的红色圣地。', '河北', 39.348900, 115.497600, '其他', '["https://img1.baidu.com/it/u=4101657196,2511675384&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1542"]'),
('《游盘山》', '天津市蓟州区盘山挂月峰遗址', '乾隆', '清代', '盘山挂月峰遗址位于天津市蓟州区，是乾隆"早知有盘山，何必下江南"的描绘地。挂月峰是盘山主峰，海拔864.4米，因形似一轮弯月悬挂而得名。盘山保留有清代古寺、塔林与摩崖石刻，自古为京东名山，历代帝王将相频繁游览。乾隆曾32次游历盘山，留下1702首诗作。山上松柏苍翠，奇石嶙峋，"上盘松、中盘石、下盘水"构成了盘山独特的三盘景致。秋日红叶满山，冬季银装素裹。此处是天津最著名的山岳景观，也是感受清代帝王文化与京东山水之美的文化名山。', '天津', 40.045800, 117.408400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/8/81/Tianjin_Eye_and_Tianjin.jpg"]'),
('《题清西陵》', '保定市易县清西陵泰陵遗址', '乾隆', '清代', '清西陵泰陵遗址位于河北省保定市易县，是乾隆"寝园寂寞几经年"的描绘地。泰陵是雍正帝陵寝，也是清西陵中规模最大、保存最完好的帝陵。陵区保留有清代建筑群、石牌坊、神道与古柏林，布局严谨，气势恢宏。泰陵背靠永宁山，前朝易水河，山环水抱，风水绝佳。石牌坊高大精美，神道两侧的石象生栩栩如生。古柏林苍翠挺拔，数百年老树遮天蔽日。清西陵共埋葬4位帝王、9位皇后与57位妃嫔。此处是了解清代皇家丧葬制度与陵寝建筑艺术的重要世界文化遗产。', '河北', 39.348900, 115.497600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/df/Qxl.JPG"]'),
('《邯郸道》', '邯郸市邯山区邯郸古城遗址', '岑参', '唐代', '邯郸古城遗址位于河北省邯郸市邯山区，是岑参《邯郸道》"走马章台日半斜"的描绘地。古城保留有战国夯土城墙与古碑，是战国七雄之赵国的都城所在地。邯郸作为赵都长达158年，"胡服骑射"的军事改革、"完璧归赵"的外交智慧、"邯郸学步"的趣闻典故均源于此城。岑参以"走马章台"描绘了邯郸繁华的市井风貌。古城墙夯土层次分明，展示了战国时期高超的筑城技术。城址周边出土了大量赵国青铜器、瓦当与货币。此处是了解战国赵文化与邯郸两千年城市历史的重要考古遗址。', '河北', 36.594800, 114.531000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/3f/State_Council_Gazette_-_2019_-_Issue_30.pdf"]'),
('《易水怀古》', '保定市易县荆轲故里遗址', '马戴', '唐代', '荆轲故里遗址位于河北省保定市易县，是马戴《易水怀古》"荆轲西去更谁哀"的创作地。遗址保留有汉代荆轲祠与古碑，纪念这位"风萧萧兮易水寒"的千古义士。马戴途经易水追忆荆轲刺秦的壮举，以"大河东去少人行"表达了对英雄逝去后世事苍凉的感慨。荆轲祠虽历代修缮但保留了汉代建筑风格的古朴庄严，祠内石碑记载了荆轲刺秦的完整故事。易水河在祠前静静流淌，两岸柳树依依。秋风起时河面涟漪荡漾，"壮士一去兮不复还"的悲歌似乎仍在水面回响。此处是缅怀荆轲侠义精神与感受易水怀古诗意的千年古祠。', '河北', 39.348900, 115.497600, '其他', '["https://img1.baidu.com/it/u=806750821,2480667932&fm=253&fmt=auto&app=120&f=JPEG?w=838&h=500"]');
INSERT INTO works (title, scenic_spot, author, dynasty, description, province, latitude, longitude, category, images) VALUES
('《荷花淀》', '保定市安新县白洋淀荷花淀遗址', '孙犁', '现代', '白洋淀荷花淀遗址位于河北省保定市安新县，是孙犁"荷花淀派"文学的发源地。遗址保留有原始芦苇荡与荷花池，水面浩渺，芦苇如林。孙犁以白洋淀抗日军民的故事为素材，塑造了水生嫂等勤劳勇敢的冀中妇女形象。"她们轻轻划着船，船两旁的水哗哗哗"的清新笔触开创了中国文学的诗意叙事传统。夏季荷花盛开时，粉色花朵在碧绿的荷叶间摇曳，芦苇荡中传来鸟鸣与船桨声。月光下的荷花淀如梦似幻，正是水生嫂们编苇席的场景。此处是感受孙犁文学中诗意抗战与白洋淀水乡之美的文学圣地。', '河北', 38.935300, 115.935500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/5/5c/%E7%99%BD%E6%B4%8B%E6%B7%80%E6%99%AF%E5%8C%BA%E7%9A%84%E6%99%9A%E9%9C%9E.jpg"]'),
('《芦花荡》', '保定市安新县白洋淀芦花荡遗址', '孙犁', '现代', '白洋淀芦花荡遗址位于河北省保定市安新县，是孙犁《芦花荡》中老头子痛打鬼子的故事发生地。遗址保留有原始芦苇荡与古码头，深秋时节芦花飘飞如雪。孙犁以一位年近七旬的老船夫为主角，描绘了他以智慧和勇气痛打日寇的传奇故事。"一片苇叶也没有"的芦花荡中，老头子利用水中暗桩设伏，让日本鬼子吃尽苦头。芦苇荡纵横交错，水道如迷宫，是天然的游击战场。秋日芦花满天飞舞，白色花絮与蓝天碧水构成了壮美的画卷。此处是感受抗日战争中民间智慧与白洋淀秋日芦花之美的红色文学遗存。', '河北', 38.935300, 115.935500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/95/Zhouzhuang1.jpg"]'),
('《小兵张嘎》', '保定市安新县白洋淀嘎子村遗址', '徐光耀', '现代', '白洋淀嘎子村遗址位于河北省保定市安新县，是徐光耀《小兵张嘎》的原型地。遗址保留有清末民初民居、老磨坊与嘎子纪念馆，展示了抗日小英雄嘎子的成长故事。嘎子聪明勇敢，以木头手枪缴获敌人真枪的故事家喻户晓。纪念馆中陈列有抗日时期的老照片、武器与生活用品，再现了白洋淀地区军民一体抗日的生动场景。老磨坊的石磨仍保留着使用痕迹，院中枣树年年结果。嘎子村四周水道环绕，芦苇丛生，是典型的白洋淀水乡村落。此处是了解白洋淀抗日传奇与感受冀中少年英雄精神的爱国主义教育基地。', '河北', 38.935300, 115.935500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/f/f4/Hengshui_Lake%2C_Hebei%2C_China3.jpg"]'),
('《红旗谱》', '保定市蠡县梁斌故居遗址', '梁斌', '现代', '梁斌故居遗址位于河北省保定市蠡县，是《红旗谱》的创作地。故居保留有清代建筑与古碑，院落方正，青砖灰瓦。梁斌以蠡县、高阳一带的农民革命斗争为素材，塑造了朱老忠、严志和等不屈不挠的农民英雄形象。"大闹千里堤""反割头税运动"等情节均有真实历史原型。故居内展示有梁斌手稿、生平照片与创作资料。蠡县自古为冀中平原重要的农业区域，广袤的麦田在风中翻涌如金色波浪。此处是了解中国革命文学创作源流与冀中农民运动历史的重要文学故居。', '河北', 38.488000, 115.583400, '其他', '["https://img0.baidu.com/it/u=3809511248,4081722558&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=377"]'),
('《播火记》', '保定市高阳县布里村遗址', '梁斌', '现代', '布里村遗址位于河北省保定市高阳县，是梁斌《播火记》中高蠡暴动的核心原型地。遗址保留有清代民居与革命旧址，1932年高蠡暴动在此爆发，冀中农民在共产党领导下武装起义反抗国民党统治。梁斌以这段历史为素材创作了《播火记》，"播火"寓意革命火种在冀中平原的传播。旧址内保留有暴动时期的武器、旗帜与领导人照片。布里村四周平原辽阔，冬日麦苗如茵。革命先烈的鲜血浸润了这片土地。此处是了解冀中早期革命运动史与梁斌红色文学创作背景的重要革命遗存。', '河北', 38.700500, 115.778800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/c5/ChinaBaodingGaoyang.png"]'),
('《敌后武工队》', '保定市清苑区冉庄地道战遗址', '冯志', '现代', '冉庄地道战遗址位于河北省保定市清苑区，是冯志《敌后武工队》的核心原型地。遗址保留有明清地道与古民居，地道总长16公里，连接村中各户，形成了完善的地下战斗网络。抗日战争时期冉庄军民利用地道与日寇进行了艰苦卓绝的斗争，地道中设有指挥部、弹药库、医疗室等设施。冯志以冀中敌后武工队的真实经历为素材，描绘了军民团结抗日的英勇事迹。地道入口隐蔽在灶台、水井、墙壁之中，设计巧妙。此处是中国抗日战争中人民战争智慧的杰出代表，也是国家级重点文物保护单位。', '河北', 38.765000, 115.489800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/43/2016%E5%B9%B4%E5%BA%A6%E5%85%A8%E5%9B%BD%E5%8D%9A%E7%89%A9%E9%A6%86%E5%90%8D%E5%BD%95.pdf"]'),
('《野火春风斗古城》', '保定市莲池区古莲花池遗址', '李英儒', '现代', '古莲花池遗址位于河北省保定市莲池区，是李英儒《野火春风斗古城》中地下党活动的场景地。古莲花池始建于元代，是中国十大名园之一，保留有元代园林建筑、古碑与荷花池。李英儒以保定沦陷时期地下党的斗争为背景，古莲花池作为城市文化地标出现在小说中。园内亭台楼阁依水而建，回廊曲折幽深，假山奇石嶙峋。夏季荷花满池粉红，"映日荷花别样红"的景象在此完美呈现。古碑上记载着历代文人的题诗。此处是了解保定古城文化底蕴与抗日战争时期地下斗争历史的园林名胜。', '河北', 38.883300, 115.520900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/7c/Baoding_Ancient_Lotus_Pond_bridge.jpg"]'),
('《哦，香雪》', '张家口市怀来县鸡鸣驿村遗址', '铁凝', '现代', '鸡鸣驿村遗址位于河北省张家口市怀来县，是铁凝《哦，香雪》的真实原型地。遗址保留有明清古民居与古驿站城墙，香雪用鸡蛋换铅笔盒的感人故事就发生在这样的小山村。铁凝以细腻温暖的笔触描绘了改革开放初期山村少女对现代文明的渴望——火车每天只停一分钟，这一分钟成为连接山村与外部世界的唯一窗口。村中老屋低矮，土墙斑驳，小路蜿蜒在山坡上。铁道从村旁穿过，汽笛声是最动听的现代之音。此处是感受铁凝文学中质朴人性之美与华北山村原始风貌的温情文学地标。', '河北', 40.415400, 115.517700, '其他', '["https://upload.wikimedia.org/wikipedia/commons/9/9f/Jimingyi_1.jpg"]'),
('《笨花》', '衡水市饶阳县大官亭镇遗址', '铁凝', '现代', '大官亭镇遗址位于河北省衡水市饶阳县，是铁凝《笨花》的核心原型地，也是铁凝故乡。遗址保留有清末民初民居、老商铺与古槐树，展现了冀中平原农村的传统风貌。铁凝以故乡为原型，在《笨花》中描绘了从清末到解放后冀中农村几代人的命运变迁。"笨花"即棉花，冀中平原广袤的棉田是这片土地最重要的经济作物。老商铺的木质柜台保留着传统经营的痕迹，古槐树冠如华盖，见证了百年沧桑。此处是了解铁凝文学根脉与冀中平原农村百年变迁的重要文学故地。', '河北', 38.235400, 115.725600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/3/3f/State_Council_Gazette_-_2019_-_Issue_30.pdf"]'),
('《平原枪声》', '衡水市枣强县肖张镇遗址', '李晓明', '现代', '肖张镇遗址位于河北省衡水市枣强县，是李晓明《平原枪声》中马英等抗日英雄的故事发生地。遗址保留有清代民居与革命旧址，展示了冀中平原军民在日寇"铁壁合围"中坚持斗争的英勇事迹。李晓明以亲身经历为素材，塑造了马英、苏建梅等抗日英雄形象。"平原无险可守"的地理条件使游击战更加艰难，但冀中军民以智慧和勇气创造了平原游击战的奇迹。镇中老屋低矮，街巷狭窄。冬日平原上白雪覆盖，远处村庄炊烟袅袅。此处是了解冀中平原抗日斗争史与红色文学创作的重要革命遗存。', '河北', 37.513500, 115.724600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/16/CADAL11110518_%E5%9B%9B%E5%B9%B4%E4%BE%86%E7%9A%84%E7%BE%8E%E5%9C%8B%E9%81%A0%E6%9D%B1%E5%A4%96%E4%BA%A4.djvu"]'),
('《烈火金刚》', '沧州市献县本斋乡遗址', '刘流', '现代', '本斋乡遗址位于河北省沧州市献县，是刘流《烈火金刚》的核心原型地，也是回族抗日英雄马本斋的故乡。遗址保留有清代民居与马本斋纪念馆，展示了马本斋率领回民支队抗击日寇的壮烈历史。刘流以冀中抗日军民的英勇事迹为素材，塑造了史更新等铁骨铮铮的英雄形象。纪念馆中陈列有马本斋用过的武器、军装与生平照片。本斋乡回汉杂居，清真寺与关帝庙并立，体现了民族团结抗日的精神。此处是缅怀回族抗日英雄与了解冀中抗战历史的重要红色纪念地。', '河北', 38.190300, 116.122400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/43/2016%E5%B9%B4%E5%BA%A6%E5%85%A8%E5%9B%BD%E5%8D%9A%E7%89%A9%E9%A6%86%E5%90%8D%E5%BD%95.pdf"]'),
('《青春之歌》', '秦皇岛市山海关区山海关古城遗址', '杨沫', '现代', '山海关古城遗址位于河北省秦皇岛市山海关区，是杨沫《青春之歌》的文学背景地之一。古城保留有明代城墙、"天下第一关"匾额与古民居，是万里长城东端的重要关隘。杨沫在《青春之歌》中描绘了知识女性林道静从个人觉醒到投身革命的成长历程。山海关古城雄伟壮观，城墙高达14米，箭楼矗立在城门之上。"天下第一关"五个大字苍劲有力，由明代书法家萧显所题。城外长城蜿蜒入山，城内老街商铺林立。此处是了解万里长城东端雄关与近代革命青年成长历程的历史文化名城。', '河北', 40.000000, 119.775900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/43/2016%E5%B9%B4%E5%BA%A6%E5%85%A8%E5%9B%BD%E5%8D%9A%E7%89%A9%E9%A6%86%E5%90%8D%E5%BD%95.pdf"]'),
('《太阳照在桑干河上》', '张家口市涿鹿县桑干河遗址', '丁玲', '现代', '桑干河遗址位于河北省张家口市涿鹿县，是丁玲《太阳照在桑干河上》的核心背景地。遗址保留有明清古码头与河流，桑干河自山西流入河北，在此形成宽阔的河谷。丁玲以1946年华北土地改革运动为背景，描绘了暖水屯农民打倒地主翻身做主人的激烈斗争。桑干河两岸是肥沃的农田，秋日金黄的庄稼一望无际。"太阳照在桑干河上"象征着新时代的曙光照亮了古老的大地。河水清澈，两岸杨柳依依，远处燕山群峰在暮色中显出深蓝的轮廓。此处是了解中国土地改革历史与丁玲革命文学创作的重要文学地标。', '河北', 40.379700, 115.205900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/f/fd/%E5%8D%81%E6%9C%88%E7%9A%84%E7%81%B5%E5%B1%B1_-_Lingshan_Mountain_in_October_-_2011.10_-_panoramio.jpg"]'),
('《取经》', '石家庄市正定县正定古城遗址', '贾大山', '现代', '正定古城遗址位于河北省石家庄市正定县，是贾大山《取经》等小说的核心原型地，也是贾大山的故乡。古城保留有明清古民居、古城墙与多座古寺，历史文化底蕴深厚。贾大山以正定古城的日常生活为素材，以幽默质朴的笔触描绘了小城中各色人物的喜怒哀乐。正定古城有"九楼四塔八大寺"之称，是华北地区保存古建筑最多的城市之一。古城墙斑驳苍老，城门洞中偶有自行车穿行。街巷中的老茶馆、理发店保留着传统小城的烟火气。此处是感受贾大山小说中华北小城生活与正定千年古城文化的文学故地。', '河北', 38.146500, 114.570500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/4/49/Shijiazhuang_Municipal_Government%27s_2011_Work_Report.pdf"]'),
('《花市》', '石家庄市正定县隆兴寺遗址', '贾大山', '现代', '隆兴寺遗址位于河北省石家庄市正定县，是贾大山文学作品的核心背景地之一。隆兴寺始建于隋代，是中国十大名寺之一，保留有宋代建筑、古碑与佛像。寺内摩尼殿为中国现存最古老的木构建筑之一，殿内壁画精美绝伦。高达21.3米的铜铸千手千眼观音像是中国最高的铜佛像，被誉为"正定大佛"。贾大山常以隆兴寺为创作背景，寺院中的僧人、香客构成了他笔下独特的人物群像。古柏苍翠环绕，钟声在古城上空回荡。此处是了解宋代建筑艺术巅峰与正定佛教文化的重要古建筑群。', '河北', 38.146500, 114.570500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/7a/%E6%AD%A3%E5%AE%9A%E9%9A%86%E5%85%B4%E5%AF%BA%E6%91%A9%E5%B0%BC%E6%AE%BF2026.3.jpg"]'),
('《红楼梦》', '石家庄市正定县荣国府遗址', '曹雪芹', '清代', '正定县荣国府遗址位于河北省石家庄市正定县，是1987年电视剧《红楼梦》的拍摄地。荣国府严格按照曹雪芹原著中对荣国府的描写建造，保留有清代建筑风格的大门、正厅、花园等完整建筑群。府中房屋112间，游廊曲折通幽，假山池塘点缀其间。"荣禧堂"匾额高悬，林黛玉初入贾府时"步步留心，时时在意"的场景在此得以实景还原。府中花园按"大观园"布局设计，潇湘馆、怡红院等景点一一呈现。此处是中国最完整的《红楼梦》实景建筑群，也是走进曹雪芹文学世界的最直观体验空间。', '河北', 38.146500, 114.570500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/1/13/Zhengding_County%2C_Shijiazhuang.jpg"]'),
('《史记・刺客列传》', '保定市易县荆轲刺秦遗址', '司马迁', '西汉', '荆轲刺秦遗址位于河北省保定市易县，是司马迁《史记·刺客列传》中荆轲刺秦故事的核心发生地。遗址保留有战国古驿道、易水河与荆轲墓，司马迁以"风萧萧兮易水寒，壮士一去兮不复还"的千古绝唱记录了这段惊心动魄的历史。荆轲受燕太子丹之命携督亢地图与樊於期人头赴咸阳刺杀秦王，"图穷匕见"的紧张时刻至今令人屏息。易水河在遗址前静静流淌，古驿道的石板路通向远方的群山。此处是中国古代侠义精神的最高象征地，也是感受《史记》中刺客列传壮烈历史的朝圣之所。', '河北', 39.348900, 115.497600, '其他', '["https://upload.wikimedia.org/wikipedia/commons/b/bc/Beidaihe_panorama_from_the_south.jpg"]'),
('《水经注・滱水注》', '保定市涞源县白石山遗址', '郦道元', '北魏', '白石山遗址位于河北省保定市涞源县，是郦道元《水经注·滱水注》中"山多白石"的描绘地。白石山海拔2096米，因山体多白色大理石而得名。遗址保留有明代古寺、古驿道与摩崖石刻，山上奇峰林立，云海翻涌。郦道元在《水经注》中详细描述了滱水（今唐河）源出白石山的地理风貌。白石山拥有中国最长最宽的玻璃栈道，悬于万丈悬崖之上。"双雄石""仙人晒靴"等奇石形态各异。秋日红叶映衬着白色岩壁，色彩对比强烈。此处是了解北魏地理学巨著与太行山雄奇地貌的壮美之地。', '河北', 39.357800, 114.694600, '其他', '["https://img1.baidu.com/it/u=3680738906,2354028721&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1176"]'),
('《徐霞客游记・游恒山记》', '大同市浑源县恒山悬空寺遗址', '徐霞客', '明代', '恒山悬空寺遗址位于山西省大同市浑源县，是徐霞客《游恒山记》中"层楼高悬"的描绘地。悬空寺始建于北魏，距今一千五百余年，是中国唯一佛道儒三教合一的悬空建筑。徐霞客亲临此地后惊叹不已，在游记中详细记录了悬空寺的建筑奇观与恒山的险峻地势。寺院凌空架于翠屏峰半崖之上，仅靠数根木柱支撑，"上延霄客，下绝嚣浮"。殿内保存有北魏至明代佛像与壁画。从谷底仰望，悬空寺如同镶嵌在悬崖上的微型宫殿。此处是中国古代建筑工程的极致之作，也是感受徐霞客探险精神的必访之地。', '山西', 39.698200, 113.699100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/de/Hangingtemple20190929.jpg"]'),
('《游苍岩山记》', '石家庄市井陉县苍岩山桥楼殿遗址', '王世贞', '明代', '苍岩山桥楼殿遗址位于河北省石家庄市井陉县，是明代文学家王世贞《游苍岩山记》"桥跨两山，楼建于桥"的描绘地。桥楼殿建于隋代，横跨在两座悬崖之间的天然石桥之上，殿宇凌空飞架，建筑与自然浑然天成。王世贞亲临此地后赞叹不已，详细记录了桥楼殿的奇绝与苍岩山的秀美。殿内保留有隋唐至明清的壁画与佛像，色彩依稀可辨。两侧悬崖陡峭如削，峡谷深不见底，山风呼啸。古柏从岩缝中生长而出，生命力顽强。此处是太行山中最令人惊叹的古建筑奇观，也是感受明代文人游记中山水审美的经典之地。', '河北', 38.032300, 114.145100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/c/ce/Mount_cangyan_2007.jpg"]'),
('《赵州桥铭》', '石家庄市赵县赵州桥遗址', '张嘉贞', '唐代', '赵州桥遗址位于河北省石家庄市赵县，唐代张嘉贞为赵州桥撰写的《赵州桥铭》详细记载了这座桥的建筑工艺与历史。赵州桥又名安济桥，建于隋代开皇年间，由匠师李春主持设计建造。张嘉贞以"制造奇特，人不知其所以为"高度评价了赵州桥的工程成就。桥身全长64.4米，单孔净跨37.02米，两端各设两个小拱，既减轻了桥身重量又利于泄洪。栏板上的龙凤浮雕精美绝伦。赵州桥比欧洲同类桥梁早七百余年。此处是了解唐代碑铭文学与中国古代桥梁工程巅峰成就的世界文化遗产。', '河北', 37.756200, 114.776200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/72/Anji_Bridge%2C_Zhao_County%2C_2020-09-06_05.jpg"]'),
('《铜雀台赋》', '邯郸市临漳县铜雀台遗址', '曹植', '三国魏', '铜雀台遗址位于河北省邯郸市临漳县，是曹植《铜雀台赋》"浮双阙乎太清"描绘铜雀台盛景之地。建安十五年曹操建成铜雀台，次年曹植登台赋诗，写下了这篇传世名赋。赋中描绘了铜雀台的宏伟壮观——"建高门之嵯峨兮，浮双阙乎太清"，展现了曹魏鼎盛时期的文化气象。曹植才华横溢，"七步成诗"的故事广为流传。遗址保留有汉代夯土台基与古碑，虽经两千年侵蚀但规模仍可辨识。临漳县是古邺城所在地，建安文学在此达到巅峰。此处是了解建安文学与三国曹魏文化的重要考古遗址。', '河北', 36.335200, 114.619400, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/7b/%E6%AD%A6%E7%81%B5%E4%B8%9B%E5%8F%B0_10.jpg"]'),
('《丛台赋》', '邯郸市丛台区丛台遗址', '枚乘', '西汉', '丛台遗址位于河北省邯郸市丛台区，是西汉枚乘《丛台赋》"览平原之敞"描绘丛台风光之地。丛台始建于战国赵武灵王时期，是赵王检阅军队、观赏歌舞的重要场所。枚乘以恢弘的笔触描绘了丛台上俯瞰邯郸平原的壮阔景象，展现了赵国鼎盛时期的繁华。丛台保留有战国夯土台基与明代重建建筑，台高约7米，占地面积3500余平方米。台上建有据胜亭、七贤祠等建筑。邯郸是成语之都，"负荆请罪""完璧归赵"等成语均源于此城。此处是了解战国赵文化与汉赋文学的重要文化遗址。', '河北', 36.636300, 114.493000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/7/74/%E6%B2%B3%E5%8C%97%E9%82%AF%E9%83%B8%E5%B8%82%E6%B0%91%E7%94%A8%E2%80%9C%E6%AF%9B%E7%8C%B4%E2%80%9D%E6%8A%80%E8%89%BA%E5%86%8D%E7%8E%B0%E6%88%90%E8%AF%AD%E6%95%85%E4%BA%8B%E5%9C%BA%E6%99%AF.webm"]'),
('《燕昭王筑黄金台赋》', '保定市定兴县黄金台遗址', '王勃', '唐代', '黄金台遗址位于河北省保定市定兴县，是王勃《燕昭王筑黄金台赋》描绘燕昭王招贤纳士故事之地。遗址保留有战国夯土台基与古碑。王勃以"初唐四杰"之才描绘了燕昭王置千金于台上、"卑身厚币以招贤者"的千古佳话。郭隗首先自荐，随后乐毅从魏国、邹衍从齐国纷纷前来投效，燕国因此强盛，最终攻下齐国七十余城。黄金台的故事成为中国古代"尊贤重士"的最高典范。台基虽经两千余年风雨但轮廓清晰可辨。此处是了解战国礼贤下士传统与初唐辞赋文学的重要历史遗存。', '河北', 39.263000, 115.808000, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/df/Qxl.JPG"]'),
('《狼牙山五壮士》', '保定市易县狼牙山五勇士纪念塔遗址', '沈重', '现代', '狼牙山五勇士纪念塔遗址位于河北省保定市易县，是沈重报告文学《狼牙山五壮士》的核心纪念地。纪念塔矗立在狼牙山主峰棋盘陀之巅，高21.5米，塔身正面镌刻"狼牙山五勇士纪念塔"大字。1941年9月25日，五位八路军战士在弹尽粮绝后纵身跳下悬崖，以生命谱写了抗日战争中最壮烈的英雄诗篇。纪念塔四周松柏苍翠，山风猎猎。登上塔顶可俯瞰易水河谷与太行群峰。每年清明时节无数人前来祭扫缅怀。此处是中国抗日战争中最感人的英雄故事纪念地，是进行爱国主义教育的红色圣地。', '河北', 39.348900, 115.497600, '其他', '["https://img0.baidu.com/it/u=399589422,2755162020&fm=253&fmt=auto&app=120&f=JPEG?w=889&h=500"]'),
('《白洋淀纪事》', '保定市安新县白洋淀圈头村遗址', '孙犁', '现代', '白洋淀圈头村遗址位于河北省保定市安新县，是孙犁《白洋淀纪事》的核心创作地与生活地。遗址保留有明清古民居与古码头，圈头村四面环水，是白洋淀腹地最具水乡特色的村落。孙犁在白洋淀生活期间深入了解了淀区军民的抗日故事，创作了《白洋淀纪事》等经典作品。圈头村的音乐会是国家级非物质文化遗产，传承数百年不断。村中小巷蜿蜒曲折，老屋临水而建，船是最主要的交通工具。夏季荷花映日，冬季冰面如镜。此处是感受孙犁文学中白洋淀风土人情与淀区水乡生活的最本真之地。', '河北', 38.935300, 115.935500, '其他', '["https://img2.baidu.com/it/u=3144788817,3147590261&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《风云初记》', '衡水市武强县周窝镇遗址', '孙犁', '现代', '周窝镇遗址位于河北省衡水市武强县，是孙犁《风云初记》中抗日战争初期故事的发生地。遗址保留有清末民初民居与老商铺，展现了冀中平原农村在战争初期的社会面貌。孙犁以1937年抗战爆发初期冀中平原的风云变幻为背景，描绘了各阶层人物在民族危亡时刻的不同选择。周窝镇如今已发展为中国北方最大的乐器生产基地，"音乐小镇"的美誉名扬四方。老商铺改造为乐器工坊，传统与现代在此奇妙交融。此处是了解孙犁抗战文学与冀中乡村百年变迁的独特文学地标。', '河北', 38.041400, 115.982500, '其他', '["https://img2.baidu.com/it/u=2445165058,3511437655&fm=253&fmt=auto&app=138&f=JPEG?w=1067&h=800"]'),
('《铁木前传》', '衡水市深州市王家井镇遗址', '孙犁', '现代', '王家井镇遗址位于河北省衡水市深州市，是孙犁《铁木前传》中铁匠傅老刚与木匠黎老东故事的发生地。遗址保留有清代民居与老作坊，展现了冀中平原传统手工业的生产场景。孙犁以铁匠与木匠两家的友谊变迁为主线，折射了农业合作化运动中农村社会关系的深刻变化。老铁匠铺中的铁砧、风箱保留着使用痕迹，"叮叮当当"的打铁声似乎仍在回响。木匠作坊中的刨子、墨斗陈列如初。深州蜜桃闻名天下，春日桃花如云似霞。此处是感受孙犁后期文学中乡村人情冷暖与冀中传统手工业文化的质朴之地。', '河北', 37.509300, 115.559600, '其他', '["https://img2.baidu.com/it/u=616848648,924530991&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=889"]'),
('《红旗谱》', '保定市安新县白洋淀端村遗址', '梁斌', '现代', '白洋淀端村遗址位于河北省保定市安新县，是梁斌《红旗谱》中朱老忠等人活动的场景地。遗址保留有清末民初民居与古码头，端村是白洋淀边最具历史文化底蕴的古村之一。梁斌在《红旗谱》中将白洋淀地区的农民革命斗争融入家族叙事，端村的渡口、码头、芦苇荡构成了故事的重要空间。端村以制作羽绒制品闻名，家家户户院中晾晒着洁白的鹅绒。古码头石阶入水，渡船摇曳。夏季白洋淀水面浩渺，远处芦苇如林。此处是了解梁斌革命文学与白洋淀水乡传统生活的重要文学场景地。', '河北', 38.935300, 115.935500, '其他', '["https://img0.baidu.com/it/u=3197970891,3212228735&fm=253&fmt=auto&app=138&f=JPEG?w=667&h=500"]'),
('《野火春风斗古城》', '保定市莲池区保定陆军军官学校遗址', '李英儒', '现代', '保定陆军军官学校遗址位于河北省保定市莲池区，是李英儒《野火春风斗古城》中革命青年活动的场景地。学校始建于1902年，是中国近代军事教育的摇篮，保留有民国建筑与校史陈列。蒋介石、叶挺、傅作义等大批军事将领均毕业于此。李英儒以保定沦陷时期为背景，描绘了共产党员深入敌占区进行地下斗争的惊险故事。校内建筑中西合璧，操场宽阔。校史馆中陈列有各期毕业生名录、老照片与军事教材。此处是了解中国近代军事教育史与保定抗战地下斗争历史的重要红色遗存。', '河北', 38.883300, 115.520900, '其他', '["https://img2.baidu.com/it/u=3920676252,3576108476&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《登鹳雀楼》', '运城市永济市鹳雀楼唐代台基遗址', '王之涣', '唐代', '鹳雀楼唐代台基遗址位于山西省运城市永济市，是王之涣《登鹳雀楼》"白日依山尽，黄河入海流。欲穷千里目，更上一层楼"的诞生地。遗址保留有唐代夯土台基与宋代碑刻，是鹳雀楼原始建筑的基址所在。鹳雀楼始建于北周，因楼上常有鹳雀栖息而得名，唐代是其最辉煌的时期。台基残高约三米，夯土层次分明。此处面对黄河，远眺中条山，"白日依山尽"的壮丽景象真实可见。诗中"更上一层楼"的哲理激励了无数后人。此处是中国最著名的登楼诗创作地，也是感受唐诗意境与黄河雄浑之美的文学圣地。', '山西', 34.867200, 110.447500, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/%E9%B9%B3%E9%9B%80%E6%A5%BC.jpg/1280px-%E9%B9%B3%E9%9B%80%E6%A5%BC.jpg"]'),
('《凉州词二首・其一》', '运城市永济市普救寺莺莺塔遗址', '王之涣', '唐代', '普救寺莺莺塔遗址位于山西省运城市永济市，是王之涣《凉州词》"黄河远上白云间，一片孤城万仞山"的创作背景地之一。莺莺塔保留有明代砖塔与唐代碑刻，塔高约36米，因回音效应而闻名——在塔前击石可听到蛙鸣般的回声，是中国古代建筑声学的奇迹。普救寺始建于唐代，是《西厢记》故事的发生地。王之涣在此远眺黄河蜿蜒西去的壮阔景象，写下了这首千古绝唱。塔身砖雕精美，四周古柏苍翠。此处是唐诗与元曲两大文学经典的交汇之地，也是感受黄河壮美与普救寺千年佛教文化的名胜古迹。', '山西', 34.867200, 110.447500, '其他', '["https://img2.baidu.com/it/u=2929213031,2116446385&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《江雪》', '运城市永济市柳宗元故里柳园', '柳宗元', '唐代', '柳宗元故里柳园位于山西省运城市永济市，是柳宗元出生地与《江雪》"千山鸟飞绝，万径人踪灭"的创作背景地。柳园保留有唐代建筑遗存与古碑，园内设有柳宗元纪念馆，展示其生平、著作与文学成就。柳宗元是唐宋八大家之一，与韩愈并称"韩柳"，是古文运动的领袖。《江雪》以极简的笔触描绘了天地苍茫中独钓老翁的孤绝意境，成为中国古诗中最具画面感的作品之一。园内古槐树枝繁叶茂，石径幽深。永济自古为河东文化重镇。此处是了解柳宗元文学成就与河东文化传统的重要文学纪念地。', '山西', 34.867200, 110.447500, '其他', '["https://img2.baidu.com/it/u=2995629592,581035262&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《送杜少府之任蜀州》', '运城市河津市龙门古渡遗址', '王勃', '唐代', '龙门古渡遗址位于山西省运城市河津市，是王勃《送杜少府之任蜀州》"海内存知己，天涯若比邻"的送别地。古渡保留有明清古码头与古碑，黄河在此穿越龙门峡谷奔涌而出。龙门古渡自古为秦晋交通要道，"鲤鱼跳龙门"的传说即源于此。王勃在此送别赴蜀州任职的杜少府，以"海内存知己"的旷达胸怀超越了离别的感伤，开创了送别诗的新境界。黄河水在龙门处被两岸夹峙，激流奔涌，气势磅礴。两岸石壁陡峭，古柏倒挂。此处是感受初唐诗人豪迈胸襟与黄河龙门壮观景象的文学名渡。', '山西', 35.596600, 110.712400, '其他', '["https://img0.baidu.com/it/u=1712135631,4024743893&fm=253&fmt=auto&app=138&f=JPEG?w=600&h=500"]'),
('《雁门太守行》', '忻州市代县雁门关镇边祠遗址', '李贺', '唐代', '雁门关镇边祠遗址位于山西省忻州市代县，是李贺《雁门太守行》"黑云压城城欲摧，甲光向日金鳞开"的描绘地。镇边祠保留有明代建筑、古碑与历代名将雕像，祠内供奉着在雁门关御敌保国的历代名将——李牧、卫青、霍去病、薛仁贵、杨业等。李贺以奇诡瑰丽的笔触描绘了雁门关战场的惨烈与将士的英勇。雁门关自古为中原抵御北方游牧民族的第一要塞，"天下九塞，雁门为首"。关城巍峨矗立于恒山山脉的勾注山上。此处是中国边塞军事文化的最高象征地，也是感受李贺诗歌奇绝之美的壮丽关隘。', '山西', 39.066400, 112.960000, '其他', '["https://img0.baidu.com/it/u=1741260901,349617618&fm=253&fmt=auto&app=138&f=JPEG?w=889&h=500"]'),
('《出塞二首・其一》', '忻州市代县雁门关长城遗址', '王昌龄', '唐代', '雁门关长城遗址位于山西省忻州市代县，是王昌龄《出塞》"秦时明月汉时关，万里长征人未还"的真实写照。遗址保留有明代长城、敌楼与古战场，长城沿山脊蜿蜒，气势雄浑。雁门关是中国历史上最重要的军事关隘之一，见证了三千年来无数次的战争与和平。王昌龄以雁门关为背景感叹边疆将士的悲壮命运，"但使龙城飞将在，不教胡马度阴山"的豪迈成为千古绝唱。关城两侧山势险峻，"一夫当关，万夫莫开"。秋日关外草原金黄，关内树木苍翠。此处是万里长城最具军事历史价值的关隘之一。', '山西', 39.066400, 112.960000, '其他', '["https://img2.baidu.com/it/u=4184628563,2231755514&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1181"]'),
('《使至塞上》', '大同市云冈区云冈石窟第 20 窟遗址', '王维', '唐代', '云冈石窟第20窟遗址位于山西省大同市云冈区，是王维《使至塞上》的创作背景地之一。第20窟保留有北魏大佛——高约13.7米的露天大佛是云冈石窟的标志性形象，面容慈祥庄严，体现了北魏佛教艺术的最高成就。王维出使塞上途经大同，壮阔的北方景象与佛教文化交相辉映。云冈石窟开凿于北魏和平年间，现存45个主要洞窟、252个小窟龛、51000余尊石雕造像，是中国三大石窟之一。大佛在夕阳中金光闪烁，庄严肃穆。此处是了解北魏佛教石刻艺术巅峰与感受唐代边塞文化的世界文化遗产。', '山西', 40.088700, 113.149800, '其他', '["https://img1.baidu.com/it/u=4022752300,1126736794&fm=253&fmt=auto&app=138&f=JPEG?w=681&h=500"]'),
('《登恒山》', '大同市浑源县恒山悬空寺遗址', '贾岛', '唐代', '恒山悬空寺遗址位于山西省大同市浑源县，是贾岛《登恒山》"恒岳居其北"的描绘地。悬空寺始建于北魏太和十五年，凌空架于翠屏峰半崖之上，是中国唯一佛道儒三教合一的悬空古刹。贾岛以"苦吟诗人"之名著称，登恒山时以简洁有力的笔触记录了北岳的险峻与壮美。寺院40间殿阁楼台依山势层层叠起，木柱支撑，回廊相连，最高处距地面约50米。殿内保存有北魏至明代佛像八十余尊。恒山为五岳之北岳，"人天北柱"的题额高悬于崖壁。此处是中国古代建筑工程奇迹与恒山雄险之美的极致体现。', '山西', 39.698200, 113.699100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/de/Hangingtemple20190929.jpg"]'),
('《题西林壁》', '忻州市五台县五台山佛光寺东大殿遗址', '苏轼', '北宋', '五台山佛光寺东大殿遗址位于山西省忻州市五台县，是苏轼《题西林壁》的创作地之一。东大殿建于唐大中十一年，是中国现存最古老的木结构建筑之一，被梁思成誉为"中国第一国宝"。殿内保留有唐代壁画、彩塑与古碑，佛像庄严端正，壁画色彩鲜艳。苏轼"不识庐山真面目，只缘身在此山中"的哲理诗句在此获得了佛教禅理的深层呼应。东大殿斗拱雄大，出檐深远，展现了唐代建筑的恢弘气度。五台山是中国四大佛教名山之首。此处是中国古建筑研究的圣殿与佛教文化的重要遗存。', '山西', 38.728000, 113.255200, '其他', '["https://img1.baidu.com/it/u=1759586037,2516738687&fm=253&fmt=auto&app=120&f=JPEG?w=1234&h=800"]'),
('《游山西村》', '临汾市翼城县西阎镇古村落', '陆游', '南宋', '西阎镇古村落位于山西省临汾市翼城县，是陆游《游山西村》"山重水复疑无路，柳暗花明又一村"的原型地之一。古村落保留有明清古民居、古戏台与古驿道，展现了晋南传统农村的生活风貌。陆游以质朴的笔触描绘了山村农家的热情好客——"莫笑农家腊酒浑，丰年留客足鸡豚"。古村中老屋排列整齐，石板路蜿蜒在田畴之间，古戏台上的木雕精美如初。春日桃花映红山坡，秋日柿子挂满枝头。驿道旁的老槐树见证了数百年的乡村生活。此处是感受陆游田园诗意与晋南古村落静谧之美的文学故地。', '山西', 35.738900, 111.718400, '其他', '["https://img2.baidu.com/it/u=453066027,2671080976&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1484"]'),
('《过雁门关》', '忻州市代县雁门关李牧祠遗址', '陈子昂', '唐代', '雁门关李牧祠遗址位于山西省忻州市代县，是陈子昂《过雁门关》中追忆战国名将李牧的纪念地。李牧祠保留有明代建筑与古碑，纪念赵国名将李牧在雁门关击退匈奴的赫赫战功。陈子昂途经雁门关时以"匈奴犹未灭"表达了对边疆安全的忧虑与对古代名将的缅怀。李牧是战国四大名将之一，以少胜多大败匈奴十余万骑兵，使赵国北境得保数十年安宁。祠内保留有李牧石像与历代文人题诗碑刻。雁门关城墙巍峨，山风猎猎。此处是了解战国军事文化与初唐诗人怀古情怀的重要历史遗存。', '山西', 39.066400, 112.960000, '其他', '["https://img0.baidu.com/it/u=1559276806,4052646584&fm=253&fmt=auto&app=138&f=JPEG?w=752&h=500"]'),
('《塞下曲》', '大同市左云县八台子长城遗址', '卢纶', '唐代', '八台子长城遗址位于山西省大同市左云县，是卢纶《塞下曲》"月黑雁飞高，单于夜遁逃"的描绘地。遗址保留有明代长城与敌楼，独特的是长城旁矗立着一座天主教堂，中西建筑在此奇妙并存。卢纶以简练的四句诗描绘了月夜追敌的紧张场景，成为边塞诗中最经典的短篇之一。长城在此沿山脊起伏，敌楼保存较为完好。教堂的尖塔与长城的烽火台形成了跨越文化的独特天际线。秋日草原金黄，大风呼啸。此处是感受唐代边塞诗意境与中西文化奇妙交融的独特景观地。', '山西', 40.013200, 112.702600, '其他', '["https://img0.baidu.com/it/u=469307785,1342058376&fm=253&fmt=auto&app=120&f=JPEG?w=500&h=889"]'),
('《从军行》', '朔州市右玉县杀虎口长城遗址', '杨炯', '唐代', '杀虎口长城遗址位于山西省朔州市右玉县，是杨炯《从军行》"宁为百夫长，胜作一书生"的描绘地。杀虎口是古代中原通往草原的重要关隘，也是"走西口"的起点，保留有明代长城与关城。杨炯以"初唐四杰"之豪情描绘了从军报国的壮志，"宁为百夫长"的誓言激励了无数边疆将士。杀虎口关城雄踞两山之间，"一夫当关"之势尽显。明清时期无数山西百姓从此口出关谋生，"走西口"的民歌至今传唱。秋日关外草原辽阔无际，关内杨树金黄。此处是了解边塞军事文化与"走西口"民俗历史的重要关口遗存。', '山西', 39.990000, 112.466900, '其他', '["https://img0.baidu.com/it/u=4053672008,937739249&fm=253&fmt=auto&app=138&f=JPEG?w=751&h=500"]'),
('《题恒山》', '大同市浑源县恒山北岳庙遗址', '李白', '唐代', '恒山北岳庙遗址位于山西省大同市浑源县，是李白"危楼高百尺，手可摘星辰"的描绘地。北岳庙保留有明代建筑、古碑与李白手书"壮观"碑刻，是祭祀北岳恒山的重要庙宇。李白登恒山后被其雄伟壮观所震撼，挥毫写下"壮观"二字。北岳庙依山而建，层层递进，殿宇庄严。"壮观"碑刻笔力遒劲，是李白存世不多的书法真迹之一。恒山为五岳之北岳，"人天北柱"之称当之无愧。庙前古柏苍翠，山风劲吹。站在庙中可远眺恒山群峰的险峻轮廓。此处是感受李白豪放书风与恒山北岳文化的重要道教圣地。', '山西', 39.698200, 113.699100, '其他', '["https://img2.baidu.com/it/u=3735812111,4255952647&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1422"]'),
('《滕王阁序》', '运城市万荣县飞云楼遗址', '王勃', '唐代', '飞云楼遗址位于山西省运城市万荣县，是王勃《滕王阁序》创作背景地之一。飞云楼保留有明代建筑、古碑与木雕，楼高约23米，全木结构，无一铁钉，被誉为"中华第一木楼"。飞云楼与滕王阁、黄鹤楼并称"中国古代三大名楼"。王勃曾游历河东地区，飞云楼的建筑之美为其后来创作《滕王阁序》提供了灵感。楼身斗拱层叠，翼角翔举，如同展翅欲飞的大鸟。楼内木雕精美绝伦，龙凤呈祥的图案栩栩如生。此处是中国古代木构建筑艺术的巅峰之作，也是了解初唐文人游历与文学创作的重要地标。', '山西', 35.415800, 110.838400, '其他', '["https://img0.baidu.com/it/u=3599171375,640252627&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=899"]'),
('《咏史》', '临汾市翼城县晋国博物馆遗址', '左思', '西晋', '晋国博物馆遗址位于山西省临汾市翼城县，是左思《咏史》的创作背景地。博物馆建在晋国早期都城遗址之上，保留有西周至春秋时期的墓葬、青铜器与车马坑。左思以"郁郁涧底松，离离山上苗"的比喻讽刺了门阀制度下人才被埋没的社会现实。晋国是春秋时期最强大的诸侯国之一，晋文公"退避三舍"的典故家喻户晓。博物馆中的车马坑规模宏大，青铜礼器造型精美。"曲沃代翼"的历史在此留下了深刻的考古印记。此处是了解西周至春秋晋国文化与西晋咏史诗创作背景的重要考古遗址。', '山西', 35.738900, 111.718400, '其他', '["https://img0.baidu.com/it/u=3579771580,1363500719&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《三都赋・魏都赋》', '临汾市翼城县晋国故城遗址', '左思', '西晋', '晋国故城遗址位于山西省临汾市翼城县，是左思《三都赋·魏都赋》中核心描绘地。故城保留有西周至春秋时期的夯土城墙与古碑，是春秋晋国都城"翼"的所在地。左思耗时十年写就的《三都赋》以恢弘的笔触描绘了三国时期魏蜀吴三国都城的盛景，引发了"洛阳纸贵"的千古佳话。晋国故城城墙夯土层次分明，展示了西周至春秋时期高超的筑城技术。城址内出土了大量晋国青铜器与陶器。翼城自古为晋文化核心区域。此处是了解春秋晋国都城规制与西晋辞赋文学创作的重要考古遗址。', '山西', 35.738900, 111.718400, '其他', '["https://img1.baidu.com/it/u=3551255639,2819070520&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=621"]'),
('《登鹳雀楼》', '运城市永济市黄河大铁牛遗址', '王之涣', '唐代', '黄河大铁牛遗址位于山西省运城市永济市，是王之涣《登鹳雀楼》的创作背景地之一。遗址保留有唐代铁牛四尊、铁人四尊与铁柱等，是唐代开元年间为固定黄河浮桥而铸造的镇河之物。铁牛每尊重约30-70吨，造型雄浑有力，是中国古代最大的铁铸文物。鹳雀楼近在咫尺，"白日依山尽，黄河入海流"的壮阔景象从铁牛处亦可远眺。铁牛在黄河泥沙中掩埋千年后重见天日，保存完好。此处是了解唐代冶铁工艺与黄河航运文化的重要考古发现，也是感受盛唐国力与鹳雀楼诗意的独特之地。', '山西', 34.867200, 110.447500, '其他', '["https://img0.baidu.com/it/u=3770361885,2551325913&fm=253&fmt=auto&app=138&f=JPEG?w=656&h=437"]'),
('《普救寺》', '运城市永济市普救寺梨花深院遗址', '王实甫', '元代', '普救寺梨花深院遗址位于山西省运城市永济市，是元代王实甫《西厢记》中崔莺莺与张生相会之地。梨花深院保留有元代建筑风格的庭院与古碑，"愿天下有情人终成眷属"的千古名句即出自此处。王实甫以唐代元稹《莺莺传》为蓝本，将崔莺莺与张生的爱情故事改编为大团圆结局，成为中国古典戏曲中最动人的爱情经典。梨花深院中古梨树春日花开如雪，"梨花院落溶溶月"的意境浪漫至极。院墙上的月影斑驳，仿佛莺莺月下听琴的身影。此处是中国古典爱情文学的最重要场景地。', '山西', 34.867200, 110.447500, '其他', '["https://img0.baidu.com/it/u=2534981020,3562852554&fm=253&fmt=auto&app=138&f=JPEG?w=749&h=500"]'),
('《西厢记》', '运城市永济市普救寺莺莺塔遗址', '王实甫', '元代', '普救寺莺莺塔遗址位于山西省运城市永济市，是王实甫《西厢记》中崔莺莺居住之地。莺莺塔保留有明代砖塔、唐代碑刻与古槐树，塔高约36米，方形十三层。莺莺塔最神奇之处在于其回音效应——在塔前特定位置击石，可听到类似蛙鸣的回声，被列为世界六大奇塔之一。王实甫笔下的崔莺莺"闲愁万种，无语怨东风"的形象成为中国古典文学中最美的女性形象之一。塔旁古槐树相传为张生翻墙赴约时攀爬之树。此处是走进《西厢记》爱情世界的最直观空间，也是体验古代建筑声学奇迹的独特之地。', '山西', 34.867200, 110.447500, '其他', '["https://img2.baidu.com/it/u=2929213031,2116446385&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]');
INSERT INTO works (title, scenic_spot, author, dynasty, description, province, latitude, longitude, category, images) VALUES
('《游晋祠》', '太原市晋源区晋祠圣母殿遗址', '李白', '唐代', '晋祠圣母殿遗址位于山西省太原市晋源区，是李白"晋祠流水如碧玉"的描绘地。圣母殿建于北宋天圣年间，是晋祠的主体建筑，也是中国现存最早的木构殿堂式建筑之一。殿内保留有宋代彩塑侍女像43尊，神态各异，被誉为"中国古代雕塑的杰出之作"。李白游晋祠时被其山水与建筑之美深深打动。圣母殿前的鱼沼飞梁是中国现存最早的十字形桥梁。周柏与唐槐苍翠挺拔，难老泉水清澈甘甜。晋祠是纪念周成王弟叔虞的祠堂。此处是了解宋代建筑与雕塑艺术巅峰成就的国宝级文物保护单位。', '山西', 37.715200, 112.477800, '其他', '["https://img1.baidu.com/it/u=627306564,999245779&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1600"]'),
('《晋祠》', '太原市晋源区晋祠难老泉遗址', '欧阳修', '北宋', '晋祠难老泉遗址位于山西省太原市晋源区，是欧阳修"晋祠之水天下无"的描绘地。难老泉保留有宋代泉眼、古碑与亭台，泉水从地下岩石中涌出，清澈甘甜，千年不竭。难老泉与周柏、宋代侍女像并称"晋祠三绝"。欧阳修以简洁有力的笔触赞美了晋祠泉水的独特品质。泉眼处水波荡漾，碧绿如玉，与周围的古建筑、古木形成了诗意的画卷。难老泉水灌溉着周围万亩良田，是太原城的重要水源之一。"难老"之名寓意永远年轻，泉水长流不息。此处是感受晋祠水文化与宋代文人审美的清幽之地。', '山西', 37.715200, 112.477800, '其他', '["https://img2.baidu.com/it/u=1891633268,2819357487&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=736"]'),
('《题平遥古城》', '晋中市平遥县平遥古城南大街北段遗址', '乾隆', '清代', '平遥古城南大街北段遗址位于山西省晋中市平遥县，是乾隆"明清风貌世无双"的描绘地。南大街被誉为"中国的华尔街"，保留有明清古商铺、古民居与古街，是中国票号文化的发源地。日升昌票号在此诞生，开创了中国金融业的先河。古街两侧商铺鳞次栉比，红灯笼高挂，老字号招牌古朴典雅。平遥古城是中国保存最完整的明清古城，城墙周长6.4公里。北段商铺保留了最原始的明清商业风貌，未经现代商业化改造。此处是了解明清商业文化与中国票号金融史的世界文化遗产。', '山西', 37.189500, 112.176400, '其他', '["https://img2.baidu.com/it/u=3265402744,461943239&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《乔家大院》', '晋中市祁县乔家大院德兴堂遗址', '乾隆', '清代', '乔家大院德兴堂遗址位于山西省晋中市祁县，是乾隆"民宅看乔家"的描绘地。德兴堂是乔家大院六个大院之一，保留有清代建筑、古碑与精美的砖木石雕。乔家大院始建于清乾隆年间，由晋商乔致庸家族所建，占地面积8724平方米。大院呈"双喜"字布局，院落套院落，层次分明。砖雕、木雕、石雕"三雕"艺术精美绝伦，被誉为"北方民居建筑的明珠"。德兴堂内的百寿图屏风、九龙灯均为稀世珍品。此处是了解清代晋商文化与北方民居建筑艺术巅峰的国宝级古建筑群。', '山西', 37.357900, 112.335100, '其他', '["https://img0.baidu.com/it/u=939360575,2171129533&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《游五台山》', '忻州市五台县五台山南山寺遗址', '徐霞客', '明代', '五台山南山寺遗址位于山西省忻州市五台县，是徐霞客《游五台山》中重点描绘的景点。南山寺始建于元代，保留有明代建筑、古碑与精美壁画，依山势层层而建，殿宇庄严。徐霞客在游记中详细记录了五台山的地理、气候与寺庙建筑，展现了明代旅行家的科学精神与文学才华。南山寺以石雕艺术著称，殿前石栏上雕刻有佛教故事与花卉图案，工艺精湛。五台山是文殊菩萨道场，佛教圣地。寺院四周松柏苍翠，梵音袅袅。此处是感受徐霞客探险精神与五台山佛教文化的重要古刹。', '山西', 38.728000, 113.255200, '其他', '["https://img2.baidu.com/it/u=1082050650,1481809730&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《水调歌头・明月几时有》', '忻州市五台县五台山显通寺铜殿遗址', '苏轼', '北宋', '五台山显通寺铜殿遗址位于山西省忻州市五台县，是苏轼《水调歌头·明月几时有》的创作背景地之一。铜殿建于明万历年间，全部以铜铸造，高8.3米，宽4.7米，是中国现存最大的铜制建筑。殿内铜佛庄严，铜壁上铸有佛教故事浮雕。显通寺是五台山历史最悠久的寺院，始建于东汉永平年间。苏轼"但愿人长久，千里共婵娟"的美好祝愿与佛教的慈悲精神遥相呼应。寺内古柏参天，钟声悠远。此处是了解明代铜铸建筑工艺与五台山佛教文化源流的重要文物保护单位。', '山西', 38.728000, 113.255200, '其他', '["https://img1.baidu.com/it/u=2621906336,3782914525&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1159"]'),
('《长恨歌》', '运城市永济市杨贵妃故里遗址', '白居易', '唐代', '杨贵妃故里遗址位于山西省运城市永济市，是白居易《长恨歌》创作灵感地之一。遗址保留有唐代建筑风格的纪念馆、古碑与杨贵妃塑像，展示了杨玉环从永济少女到大唐贵妃的传奇一生。白居易以"回眸一笑百媚生，六宫粉黛无颜色"的华丽笔触描绘了杨贵妃的绝世容颜与唐明皇的爱情悲剧。"天长地久有时尽，此恨绵绵无绝期"的哀叹成为中国古典爱情诗最深沉的告白。纪念馆中陈列有杨贵妃生平资料与唐代服饰复原品。此处是了解唐代宫廷文化与《长恨歌》文学背景的重要纪念地。', '山西', 34.867200, 110.447500, '其他', '["https://img2.baidu.com/it/u=1810999242,2760275943&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1473"]'),
('《卖炭翁》', '运城市芮城县永乐宫遗址', '白居易', '唐代', '永乐宫遗址位于山西省运城市芮城县，是白居易《卖炭翁》的创作背景地之一。永乐宫原名大纯阳万寿宫，是元代道教全真派三大祖庭之一，为纪念吕洞宾而建。宫内保留有元代壁画约960平方米，是中国现存面积最大、保存最完整的道教壁画。三清殿《朝元图》描绘了286位神仙朝拜元始天尊的宏大场景，人物形象栩栩如生，线条流畅，色彩艳丽。永乐宫曾因三门峡水库建设整体搬迁，堪称中国文物保护史上的壮举。此处是了解元代壁画艺术巅峰与道教文化的国宝级文物保护单位。', '山西', 34.693900, 110.694200, '其他', '["https://img2.baidu.com/it/u=4138767829,2987968945&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《九月九日忆山东兄弟》', '运城市永济市王官谷遗址', '王维', '唐代', '王官谷遗址位于山西省运城市永济市，是王维隐居地与《九月九日忆山东兄弟》"遥知兄弟登高处，遍插茱萸少一人"的创作灵感地。王官谷保留有唐代古寺遗迹、摩崖石刻与瀑布，谷深林密，溪水潺潺。王维早年在此隐居读书，"每逢佳节倍思亲"的千古名句正是少年王维身在异乡的真情流露。王官谷中瀑布飞流直下，岩壁上的摩崖石刻记录了历代文人的游览足迹。谷内古树参天，鸟鸣幽谷，远离尘嚣。秋日红叶满谷，茱萸果实在枝头殷红如珠。此处是感受王维田园诗意与中条山幽谷之美的隐逸文学圣地。', '山西', 34.867200, 110.447500, '其他', '["https://img2.baidu.com/it/u=3847277036,4131148123&fm=253&fmt=auto&app=138&f=JPEG?w=1067&h=800"]'),
('《送元二使安西》', '运城市盐湖区解州关帝庙遗址', '王维', '唐代', '解州关帝庙遗址位于山西省运城市盐湖区，是王维《送元二使安西》的送别地之一。关帝庙保留有宋代建筑、明代碑刻与关羽雕像，是全球关帝庙的祖庙，也是中国现存规模最大的关帝庙。庙宇占地面积约22万平方米，建筑群宏伟壮观。王维在河东地区送别友人元二赴安西都护府，"劝君更尽一杯酒，西出阳关无故人"的深情嘱咐成为中国送别诗的千古绝唱。庙内春秋楼中关羽夜读春秋的塑像栩栩如生。解州是关羽故里，忠义文化在此根深蒂固。此处是了解关公文化与唐代送别诗背景的国宝级文物保护单位。', '山西', 35.026000, 111.006700, '其他', '["https://img0.baidu.com/it/u=1295272759,1018651252&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《小二黑结婚》', '长治市武乡县李峪村遗址', '赵树理', '现代', '李峪村遗址位于山西省长治市武乡县，是赵树理《小二黑结婚》的原型地。遗址保留有清末民初民居与老戏台，展现了太行山区农村的传统风貌。赵树理以太行山区真实的婚姻故事为素材，塑造了勇敢追求自由恋爱的小二黑与小芹形象。"三仙姑""二诸葛"等封建迷信人物的刻画入木三分，辛辣幽默。赵树理被誉为"山药蛋派"的旗帜，其作品语言通俗生动，深受农民喜爱。太行山区的石板路、老磨坊、土窑洞构成了故事的生活空间。此处是了解赵树理文学与太行山区农村婚姻变革的重要文学原型地。', '山西', 36.837200, 112.864600, '其他', '["https://img0.baidu.com/it/u=2731278302,1458841956&fm=253&fmt=auto&app=138&f=JPEG?w=700&h=392"]'),
('《李有才板话》', '长治市沁水县尉迟村遗址', '赵树理', '现代', '尉迟村遗址位于山西省长治市沁水县，是赵树理《李有才板话》的创作地，也是赵树理的故乡。遗址保留有清末民初民居与赵树理故居，展示了沁水山区的传统乡村风貌。赵树理以家乡的民间艺术——板话（一种说唱形式）为载体，通过李有才这个农民说唱艺人的视角揭示了减租减息运动中的阶级斗争。"板话"节奏明快、讽刺辛辣，是晋东南民间文化的瑰宝。赵树理故居中保留有其手稿与生平照片。沁水山区山势险峻，溪水潺潺。此处是了解赵树理"山药蛋派"文学源流与沁水民间文化的重要故居地。', '山西', 35.691000, 112.187100, '其他', '["https://img1.baidu.com/it/u=2670162542,3039776851&fm=253&fmt=auto&app=138&f=JPEG?w=667&h=500"]'),
('《三里湾》', '长治市平顺县西沟村遗址', '赵树理', '现代', '西沟村遗址位于山西省长治市平顺县，是赵树理《三里湾》的原型地。遗址保留有明清古民居与老磨坊，西沟村因劳模李顺达、申纪兰而闻名全国。赵树理以农业合作化运动为背景，描绘了三里湾农民从个体劳动到集体合作的社会变革。西沟村依山傍水，梯田层层叠叠，老石磨在院中静静矗立。申纪兰"男女同工同酬"的倡议从西沟走向全国。太行山区的石板房、老窑洞保留着传统山村的质朴风貌。此处是了解中国农业合作化运动史与赵树理乡土文学的重要革命与文学双重遗产地。', '山西', 36.200100, 113.436100, '其他', '["https://img2.baidu.com/it/u=2237157261,2115794957&fm=253&fmt=auto&app=138&f=JPEG?w=1067&h=800"]'),
('《吕梁英雄传》', '吕梁市临县碛口镇李家山村遗址', '马烽', '现代', '李家山村遗址位于山西省吕梁市临县碛口镇，是马烽《吕梁英雄传》的原型地之一。遗址保留有明清古民居与古窑洞，村落依山而建，层层叠叠如同布达拉宫。马烽以吕梁山区抗日军民的英勇事迹为素材，描绘了普通百姓在民族危亡时刻的觉醒与抗争。李家山村的窑洞民居建筑艺术独特——石砌拱券窑洞层层嵌入黄土崖壁，既防寒保暖又经久耐用。碛口曾是黄河边最繁忙的水旱码头，"九曲黄河第一镇"的美誉名扬四方。此处是了解吕梁抗日文学与黄河边窑洞建筑艺术的独特文化遗存。', '山西', 37.950800, 110.992900, '其他', '["https://img2.baidu.com/it/u=525395599,292462124&fm=253&fmt=auto&app=138&f=JPEG?w=1199&h=800"]'),
('《吕梁英雄传》', '吕梁市兴县蔡家崖村遗址', '马烽', '现代', '蔡家崖村遗址位于山西省吕梁市兴县，是马烽《吕梁英雄传》的核心背景地，也是抗日战争时期晋绥边区首府所在地。遗址保留有革命旧址与老窑洞，贺龙、关向应等革命领导人曾在此指挥作战。马烽以晋绥边区军民的抗日斗争为背景，塑造了雷石柱等英勇的游击队员形象。蔡家崖纪念馆中陈列有大量革命文物——武器、文件、生活用品，再现了晋绥边区的峥嵘岁月。黄土高原上的窑洞朴素而坚固。此处是了解晋绥边区革命史与马烽抗日文学创作的重要红色纪念地。', '山西', 38.463100, 111.127200, '其他', '["https://img2.baidu.com/it/u=1729056395,1279682650&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1737"]'),
('《我们村里的年轻人》', '晋中市昔阳县大寨村遗址', '马烽', '现代', '大寨村遗址位于山西省晋中市昔阳县，是马烽《我们村里的年轻人》的原型地。遗址保留有明清古民居与老梯田，大寨因"农业学大寨"运动而闻名全国。马烽以大寨青年农民建设家乡的故事为素材，描绘了新中国农村年轻一代的朝气蓬勃。大寨人"自力更生，艰苦奋斗"的精神将荒山变成了层层梯田。虎头山上松柏苍翠，梯田如同巨大的阶梯从山脚一直延伸到山顶。大寨纪念馆中展示了大寨人改天换地的奋斗历程。此处是了解中国农业发展史与太行山区梯田景观的红色文化与农耕文化交融之地。', '山西', 37.612500, 113.706900, '其他', '["https://img0.baidu.com/it/u=3468174393,1338098850&fm=253&fmt=auto&app=138&f=JPEG?w=667&h=500"]'),
('《创业史》', '吕梁市文水县刘胡兰村遗址', '柳青', '现代', '刘胡兰村遗址位于山西省吕梁市文水县，是柳青《创业史》的创作背景地之一，更是革命烈士刘胡兰的故乡。遗址保留有清代民居与刘胡兰纪念馆，纪念馆中陈列有刘胡兰生前遗物与革命事迹资料。毛泽东亲笔题词"生的伟大，死的光荣"高悬于纪念馆大厅。柳青以农业合作化运动为背景创作了《创业史》，文水县的农村变革是其重要的创作素材之一。村中老屋低矮，黄土院墙斑驳。刘胡兰就义处的纪念碑肃穆庄严。此处是缅怀革命先烈与了解中国农村社会变革的重要爱国主义教育基地。', '山西', 37.438300, 112.028300, '其他', '["https://img1.baidu.com/it/u=2325452720,3973745247&fm=253&fmt=auto&app=138&f=JPEG?w=400&h=300"]'),
('《白鹿原》', '运城市万荣县闫景村遗址', '陈忠实', '现代', '闫景村遗址位于山西省运城市万荣县，是陈忠实《白鹿原》中白鹿村的原型地之一。遗址保留有明清古民居、老祠堂与古戏台，展现了北方宗族村落的传统格局。陈忠实以白鹿原上白鹿两家的恩怨情仇为主线，描绘了中国近现代半个世纪的历史风云。闫景村的祠堂是宗族权力的象征，古戏台上演过无数悲欢离合。老民居的砖雕门楼、石雕影壁展现了北方建筑的粗犷之美。黄土高原上的麦田金黄一片。此处是感受陈忠实史诗文学与北方宗族村落文化的重要文学原型地。', '山西', 35.415800, 110.838400, '其他', '["https://img0.baidu.com/it/u=15853004,2942230656&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《平凡的世界》', '吕梁市柳林县军渡村遗址', '路遥', '现代', '军渡村遗址位于山西省吕梁市柳林县，是路遥《平凡的世界》中孙少平外出打工的场景地之一。遗址保留有明清古码头、老窑洞与黄河风光，军渡是黄河边的重要渡口。路遥以陕北与晋西为背景，描绘了孙少平等年轻人在改革开放初期的奋斗与成长。黄河在军渡处水面宽阔，渡船往来不绝。古码头的石阶被河水冲刷得光滑圆润。老窑洞依黄土崖壁而建，冬暖夏凉。夕阳下黄河水面波光粼粼，远处吕梁山脉苍茫起伏。此处是感受路遥文学中黄土高原苍凉之美与黄河渡口文化的文学场景地。', '山西', 37.429300, 110.889200, '其他', '["https://img2.baidu.com/it/u=2746249884,1761181819&fm=253&fmt=auto&app=138&f=JPEG?w=490&h=324"]'),
('《人生》', '吕梁市临县碛口镇西湾村遗址', '路遥', '现代', '西湾村遗址位于山西省吕梁市临县碛口镇，是路遥《人生》中高加林故乡的原型地之一。遗址保留有明清古民居、老窑洞与古驿道，村落依山傍河，布局严谨。路遥以陕北农村青年高加林的人生抉择为主线，探讨了理想与现实、城市与乡村之间的深刻矛盾。西湾村的窑洞建筑保存完好，院落层层叠起，被誉为"明代民居活化石"。黄河在村前缓缓流过，碛口古镇近在咫尺。晨雾中的西湾村如世外桃源。此处是了解路遥乡土文学与黄河边明清古村落建筑艺术的国家历史文化名村。', '山西', 37.950800, 110.992900, '其他', '["https://img0.baidu.com/it/u=2497713235,1401987317&fm=253&fmt=auto&app=138&f=JPEG?w=1199&h=800"]'),
('《三国演义》', '太原市清徐县罗贯中故居遗址', '罗贯中', '明代', '罗贯中故居遗址位于山西省太原市清徐县，是《三国演义》作者罗贯中的出生地。遗址保留有明代建筑、古碑与罗贯中纪念馆，展示了这位伟大小说家的生平与创作历程。罗贯中以"七实三虚"的手法将三国历史演绎为波澜壮阔的文学巨著，"滚滚长江东逝水，浪花淘尽英雄"的开篇成为中国文学最经典的咏叹。纪念馆中陈列有《三国演义》各版本、研究资料与三国人物画像。清徐县自古为并州文化重镇。此处是了解中国古典小说四大名著之一的创作源流与罗贯中文学生涯的重要文学纪念地。', '山西', 37.607200, 112.358900, '其他', '["https://img2.baidu.com/it/u=2095603952,3009909406&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《三国演义》', '运城市盐湖区解州关帝庙遗址', '罗贯中', '明代', '解州关帝庙遗址位于山西省运城市盐湖区，是罗贯中《三国演义》中关羽故事的重要背景地。关帝庙是全球关帝庙的祖庙，保留有宋代建筑、明代碑刻与关羽雕像，占地面积约22万平方米。罗贯中在《三国演义》中将关羽塑造为"义绝"的化身——"桃园结义""千里走单骑""过五关斩六将"的故事深入人心。春秋楼中关羽夜读《春秋》的塑像栩栩如生。庙内古柏参天，碑廊中历代名人题词琳琅满目。此处是了解关公忠义文化与《三国演义》文学背景的国宝级文物保护单位。', '山西', 35.026000, 111.006700, '其他', '["https://img0.baidu.com/it/u=1295272759,1018651252&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《水浒传》', '忻州市代县雁门关遗址', '施耐庵', '明代', '雁门关遗址位于山西省忻州市代县，是施耐庵《水浒传》中林冲雪夜上梁山必经之地。遗址保留有明代长城、敌楼与古战场，关城巍峨矗立于恒山山脉的勾注山上。"风雪山神庙"是《水浒传》中最经典的章节之一，林冲被高俅迫害充军沧州，途经雁门关时大雪纷飞，天寒地冻。雁门关自古为"天下九塞，雁门为首"，三千年来见证了无数次的战争与传奇。关城内的古街保留了明清风貌，城墙上的箭垛仍可辨识。此处是感受《水浒传》中英雄命运与雁门关千年军事文化的壮丽关隘。', '山西', 39.066400, 112.960000, '其他', '["https://img0.baidu.com/it/u=936056529,1607068667&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1200"]'),
('《西游记》', '大同市云冈区云冈石窟遗址', '吴承恩', '明代', '云冈石窟遗址位于山西省大同市云冈区，是吴承恩《西游记》创作灵感来源地之一。石窟保留有北魏石刻佛像51000余尊、古碑与摩崖石刻，是中国三大石窟之一，世界文化遗产。云冈石窟中天王、力士、飞天的形象与《西游记》中天兵天将的描写有着深层的文化渊源。第20窟露天大佛高13.7米，面容慈祥庄严，是云冈的标志。石窟中的佛教故事浮雕生动展现了佛教宇宙观与神话传说。石窟开凿于北魏和平年间，历时约60年。此处是了解北魏佛教艺术与《西游记》文化灵感源流的世界级文化遗产。', '山西', 40.088700, 113.149800, '其他', '["https://img2.baidu.com/it/u=2588374438,1613891128&fm=253&fmt=auto&app=120&f=JPEG?w=800&h=1172"]'),
('《红楼梦》', '晋中市祁县乔家大院遗址', '曹雪芹', '清代', '乔家大院遗址位于山西省晋中市祁县，是曹雪芹《红楼梦》中大观园原型地之一。大院保留有清代建筑、古碑与精美的砖木石雕，占地面积8724平方米，呈"双喜"字布局。乔家大院的院落规制、建筑装饰与《红楼梦》中贾府的描写有诸多吻合之处。大院内的砖雕"百寿图"、木雕"九龙壁"均为艺术珍品。乔致庸以儒商之道经营茶叶、票号，创造了晋商辉煌。大院中的老物件——红木家具、瓷器、字画展现了清代富商的生活品味。此处是了解清代晋商文化与《红楼梦》建筑原型的重要古建筑群。', '山西', 37.357900, 112.335100, '其他', '["https://img1.baidu.com/it/u=2165342168,884113848&fm=253&fmt=auto&app=138&f=JPEG?w=1067&h=800"]'),
('《水经注・河水注》', '临汾市吉县壶口瀑布孟门山遗址', '郦道元', '北魏', '壶口瀑布孟门山遗址位于山西省临汾市吉县，是郦道元《水经注·河水注》中"孟门即龙门之上口也"的重点记载地。孟门山矗立于黄河壶口瀑布下游，两块巨石横卧河中，将黄河一分为二。郦道元在《水经注》中详细描述了黄河在壶口段的奔腾咆哮——"水势益大，浩浩荡荡"。壶口瀑布是中国第二大瀑布，黄河之水在此从20余米高处倾泻而下，惊涛骇浪，水雾弥漫，气势磅礴。"黄河之水天上来"的壮观在此得到最直观的呈现。此处是了解北魏地理学巨著与黄河壶口壮美景观的必访之地。', '山西', 36.098300, 110.681700, '其他', '["https://img1.baidu.com/it/u=3243294499,3839775936&fm=253&fmt=auto&app=138&f=JPEG?w=1062&h=800"]'),
('《徐霞客游记・游恒山记》', '大同市浑源县恒山悬空寺遗址', '徐霞客', '明代', '恒山悬空寺遗址位于山西省大同市浑源县，是徐霞客《游恒山记》中"层楼高悬"的重点描绘景点。悬空寺始建于北魏太和十五年，距今已有一千五百余年。徐霞客亲临此地后在游记中详细描述了悬空寺的奇绝建筑与恒山的雄险地势——"缘危壁，入悬空寺，寺对翠屏峰"。寺院凌空架于峭壁之上，殿宇楼阁以栈道相连，仰望如空中楼阁。殿内保存有北魏至明代佛道儒三教塑像。恒山金龙峡两壁如削，深谷风声呼啸。此处是中国古代建筑史上最令人惊叹的奇迹之一，也是感受徐霞客探险精神的必访之地。', '山西', 39.698200, 113.699100, '其他', '["https://upload.wikimedia.org/wikipedia/commons/d/de/Hangingtemple20190929.jpg"]'),
('《游晋祠记》', '太原市晋源区晋祠圣母殿遗址', '袁宏道', '明代', '晋祠圣母殿遗址位于山西省太原市晋源区，是明代文学家袁宏道《游晋祠记》"晋祠之胜，在水不在山"的描绘地。圣母殿保留有宋代建筑、古碑与圣母像，是晋祠的核心建筑。袁宏道以公安派清新自然的文风记录了晋祠的山水之美，尤其赞叹了难老泉水的清澈与周柏的苍翠。圣母殿前的鱼沼飞梁是中国现存最早的十字形桥梁，建筑学价值极高。殿内43尊宋代彩塑侍女像神态各异，是中国古代雕塑的瑰宝。此处是感受明代游记文学中山水审美与宋代建筑雕塑艺术的国宝级文物保护单位。', '山西', 37.715200, 112.477800, '其他', '["https://img1.baidu.com/it/u=627306564,999245779&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1600"]'),
('《晋祠》', '太原市晋源区晋祠难老泉遗址', '梁衡', '现代', '晋祠难老泉遗址位于山西省太原市晋源区，是梁衡《晋祠》中"晋祠的美，在山，在树，在水"的描绘地。难老泉保留有宋代泉眼与古碑，泉水从岩石中涌出，清澈甘甜，千年不竭。梁衡以散文家的细腻笔触描绘了晋祠"三美"——周柏的苍劲、泉水的清澈、建筑的精美，将晋祠之美提炼为"历史的美"与"自然的美"的完美结合。难老泉与周柏、宋代侍女像并称"晋祠三绝"。泉水汇入智伯渠灌溉万亩良田。此处是感受梁衡散文中审美哲学与晋祠千年水文化的清幽之地。', '山西', 37.715200, 112.477800, '其他', '["https://img2.baidu.com/it/u=1891633268,2819357487&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=736"]'),
('《吕梁赋》', '吕梁市离石区北武当山遗址', '余秋雨', '现代', '北武当山遗址位于山西省吕梁市离石区，是余秋雨《吕梁赋》"吕梁之山，雄踞晋西"的描绘地。北武当山保留有明代古寺、古碑与摩崖石刻，主峰海拔2254米，是吕梁山脉的最高峰之一。余秋雨以恢弘的笔触描绘了吕梁山区的雄浑壮美与深厚的文化底蕴。北武当山因形似湖北武当山而得名，山上古寺依崖而建，道教文化浓厚。登顶远眺，黄土高原沟壑纵横，气势苍茫。秋日红叶满山，冬季银装素裹。此处是感受余秋雨文化散文中山西大地之美与吕梁山脉雄奇景观的壮丽之地。', '山西', 37.517500, 111.150800, '其他', '["https://img2.baidu.com/it/u=4142079785,2961292883&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=725"]'),
('《山西赋》', '晋中市平遥县平遥古城遗址', '余秋雨', '现代', '平遥古城遗址位于山西省晋中市平遥县，是余秋雨《山西赋》"平遥古城，明清风貌"的描绘地。平遥古城是中国保存最完整的明清古城，城墙周长6.4公里，保留有明清古民居、古城墙与古街。余秋雨在《山西赋》与《抱愧山西》中深入探讨了山西晋商文化的辉煌与衰落。古城内票号林立，"汇通天下"的金融帝国从这里起步。南大街上的老字号商铺保留了最原始的明清商业风貌。城墙上可俯瞰古城全景，灰色的屋顶鳞次栉比。此处是了解明清商业文化与余秋雨文化反思精神的世界文化遗产。', '山西', 37.189500, 112.176400, '其他', '["https://img2.baidu.com/it/u=2517895612,1779588230&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1422"]'),
('《走西口》', '朔州市右玉县杀虎口遗址', '余秋雨', '现代', '杀虎口遗址位于山西省朔州市右玉县，是余秋雨《走西口》与《抱愧山西》的重点描绘地。杀虎口是古代中原通往蒙古草原的重要关口，也是"走西口"的起点。明清时期无数山西百姓从此口出关赴内蒙古谋生，"哥哥你走西口，小妹妹我实在难留"的民歌至今传唱。余秋雨以深沉的笔触描绘了晋商从这条苦难之路上崛起的传奇历程。关城保留有明代长城与古战场遗迹。关口两侧山势夹峙，秋日草原金黄。此处是了解"走西口"民俗文化与余秋雨文化散文中晋商精神的重要历史关口。', '山西', 39.990000, 112.466900, '其他', '["https://img1.baidu.com/it/u=1220083921,3026883040&fm=253&fmt=auto&app=138&f=JPEG?w=1600&h=800"]'),
('《抱愧山西》', '晋中市祁县乔家大院遗址', '余秋雨', '现代', '乔家大院遗址位于山西省晋中市祁县，是余秋雨《抱愧山西》中重点描绘的晋商大院。余秋雨以"抱愧"为题反思了世人对山西文化的忽视——"在全国最具文化保守色彩的省份里，偏偏出现了最具开放意识的商人"。乔家大院是这一反思的核心实例。大院保留有清代建筑与精美的"三雕"艺术，六个大院呈"双喜"字布局。乔致庸以"儒商"之名开创了晋商辉煌，茶叶贸易遍及全国。大院中的百寿图、九龙灯为镇院之宝。此处是了解余秋雨文化反思与晋商"汇通天下"商业精神的重要文化地标。', '山西', 37.357900, 112.335100, '其他', '["https://img1.baidu.com/it/u=2165342168,884113848&fm=253&fmt=auto&app=138&f=JPEG?w=1067&h=800"]'),
('《抱愧山西》', '晋中市平遥县日升昌票号遗址', '余秋雨', '现代', '日升昌票号遗址位于山西省晋中市平遥县，是余秋雨《抱愧山西》的重点描绘地。日升昌是中国第一家票号，创立于清道光三年，开创了中国金融业"汇通天下"的新纪元。遗址保留有清代建筑、古碑与票号文物，柜台、账房、金库保存完好。余秋雨以日升昌为核心探讨了晋商的金融智慧——"以信用为本，以义利并重"的经营之道。票号内的暗号、密押系统展示了古代金融安全技术的精妙。平遥南大街上日升昌的门面朴素低调。此处是了解中国金融业起源与余秋雨文化散文中晋商精神的最重要票号遗存。', '山西', 37.189500, 112.176400, '其他', '["https://img1.baidu.com/it/u=1421839340,2213344760&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《太阳照在桑干河上》', '大同市阳高县桑干河遗址', '丁玲', '现代', '桑干河遗址（阳高段）位于山西省大同市阳高县，是丁玲《太阳照在桑干河上》的核心背景地。桑干河自山西西北部蜿蜒流过阳高县境，两岸是肥沃的农田。丁玲以1946年华北土地改革运动为背景，描绘了暖水屯农民推翻地主阶级统治的激烈斗争。阳高县的农村景观与小说中的描写高度吻合——广袤的麦田、低矮的土屋、蜿蜒的河流。桑干河水在秋日显得清澈而宁静。"太阳照在桑干河上"象征着新时代的曙光。此处是了解中国土地改革历史与丁玲革命文学的重要文学地标。', '山西', 40.361700, 113.750200, '其他', '["https://img1.baidu.com/it/u=1466444890,722073080&fm=253&fmt=auto&app=138&f=JPEG?w=720&h=500"]'),
('《暴风骤雨》', '长治市武乡县王家峪村遗址', '周立波', '现代', '王家峪村遗址位于山西省长治市武乡县，是周立波《暴风骤雨》的创作背景地之一，更是八路军总部所在地。遗址保留有革命旧址与老窑洞，朱德、彭德怀、左权等将领曾在此指挥百团大战等重大战役。武乡被誉为"八路军的故乡"，全县9万人参军参战。周立波在太行山区的革命经历为其后来创作《暴风骤雨》提供了丰富的素材。窑洞中保留有指挥所、电台室与会议室。村外太行山脉巍峨起伏。此处是中国抗日战争最重要的指挥中枢之一，也是进行红色教育的圣地。', '山西', 36.837200, 112.864600, '其他', '["https://img0.baidu.com/it/u=2129544803,997961848&fm=253&fmt=auto&app=120&f=JPEG?w=668&h=500"]'),
('《红旗谱》', '吕梁市兴县黑茶山遗址', '梁斌', '现代', '黑茶山遗址位于山西省吕梁市兴县，是梁斌《红旗谱》的创作背景地之一，更是1946年"四八"烈士遇难地。王若飞、秦邦宪、叶挺、邓发等革命先烈因飞机撞山而壮烈牺牲。遗址保留有革命纪念碑与烈士陵园，纪念碑上镌刻着烈士们的英名。黑茶山海拔约2200米，山势险峻，常年云雾缭绕。梁斌以晋西北革命根据地为创作背景之一，这片红色土地为其文学创作提供了深厚的历史底蕴。此处是缅怀"四八"烈士与了解晋西北革命史的重要红色纪念地，也是吕梁山区自然风光的代表景观之一。', '山西', 38.463100, 111.127200, '其他', '["https://img1.baidu.com/it/u=369627609,793403220&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=778"]'),
('《野火春风斗古城》', '太原市杏花岭区山西国民师范旧址', '李英儒', '现代', '山西国民师范旧址位于山西省太原市杏花岭区，是李英儒《野火春风斗古城》的核心背景地之一。旧址保留有民国建筑群，是中国共产党早期在山西开展革命活动的重要场所。高君宇、贺昌等革命先烈曾在此求学并从事革命宣传。李英儒以华北敌占区的地下斗争为主线，太原作为重要的故事发生地频繁出现。旧址建筑中西合璧，红砖灰顶，教室、礼堂保存完好。校园中的古槐树见证了无数热血青年投身革命的青春岁月。此处是了解山西早期革命运动与抗战地下斗争历史的重要红色教育基地。', '山西', 37.893500, 112.570300, '其他', '["https://img2.baidu.com/it/u=3766039019,854125181&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《敌后武工队》', '吕梁市交城县卦山遗址', '冯志', '现代', '卦山遗址位于山西省吕梁市交城县，是冯志《敌后武工队》中抗日故事的背景地。卦山保留有唐代天宁寺与古柏林，因山形如卦而得名。唐代天宁寺依山而建，殿宇庄严，古碑林立。抗日战争时期，交城县是晋绥边区的重要组成部分，敌后武工队在太行山与吕梁山之间的丘陵地带开展游击作战。冯志以真实的战斗经历为素材，描绘了武工队员深入敌后、出奇制胜的英勇故事。卦山古柏千株，苍翠蔽日，是"华北柏之冠"。此处是了解抗日游击战历史与唐代佛教文化的幽静山林之地。', '山西', 37.551300, 112.155900, '其他', '["https://img0.baidu.com/it/u=4261110373,3281621308&fm=253&fmt=auto&app=138&f=JPEG?w=1067&h=800"]'),
('《敌后武工队》', '吕梁市交城县卦山遗址', '冯志', '现代', '卦山遗址位于山西省吕梁市交城县，是冯志《敌后武工队》中抗日故事的背景地之一。卦山以唐代天宁寺与千株古柏著称，被誉为"华北柏之冠"。交城县在抗日战争时期是晋绥边区的重要区域，敌后武工队在此山区开展了艰苦卓绝的游击战争。冯志以冀中敌后武工队的真实经历为素材，卦山的深山密林为武工队提供了天然的隐蔽场所。天宁寺古碑上记载了历代高僧的修行故事，殿内佛像庄严。游客稀少，山林幽静，是太行山与吕梁山过渡地带最具自然与文化魅力的小众景点。此处是体验红色文化与佛教文化交融的独特之地。', '山西', 37.551300, 112.155900, '其他', '["https://img0.baidu.com/it/u=4261110373,3281621308&fm=253&fmt=auto&app=138&f=JPEG?w=1067&h=800"]'),
('《吕梁儿女》', '吕梁市中阳县柏洼山遗址', '马烽', '现代', '柏洼山遗址位于山西省吕梁市中阳县，是马烽《吕梁儿女》中抗日故事的背景地。柏洼山保留有明代古寺、古碑与茂密的山林，山势雄浑，古柏参天。马烽以吕梁山区抗日军民的英勇事迹为素材，描绘了普通百姓在民族危亡时刻的觉醒与抗争。柏洼山中的古寺依山而建，殿宇在古柏林中若隐若现。抗日战争时期，吕梁山区是晋绥根据地的重要组成部分，无数抗日军民在此浴血奋战。游客稀少，山林清幽，鸟鸣不绝。此处是体验吕梁山区红色文化与山水风光的小众文学与历史遗存。', '山西', 37.356700, 111.179500, '其他', '["https://img2.baidu.com/it/u=3196400108,4171896138&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1198"]'),
('《送元二使安西》', '咸阳市渭城区渭城古渡遗址', '王维', '唐代', '渭城古渡遗址位于陕西省咸阳市渭城区，是王维《送元二使安西》"渭城朝雨浥轻尘，客舍青青柳色新"的真实送别地。遗址保留有唐代码头夯土基址、明清碑刻与古柳，渭水在此处流势平缓。王维在细雨蒙蒙的清晨送别友人元二远赴安西都护府，"劝君更尽一杯酒，西出阳关无故人"的深情嘱咐成为中国送别诗的千古绝唱。古码头的夯土基址保留了唐代渡口的原始形态。渭水两岸古柳依依，春日新绿如烟。此处是唐代最著名的送别之地，也是感受王维诗歌中离别之情与渭水古渡风光的文学名渡。', '陕西', 34.361900, 108.737200, '其他', '["https://img1.baidu.com/it/u=4236440118,21770427&fm=253&fmt=auto&app=138&f=JPEG?w=1611&h=800"]'),
('《长恨歌》', '西安市临潼区华清宫长生殿遗址', '白居易', '唐代', '华清宫长生殿遗址位于陕西省西安市临潼区，是白居易《长恨歌》"七月七日长生殿，夜半无人私语时"的诞生地。遗址保留有唐代建筑基址、温泉池与古碑，长生殿是唐明皇与杨贵妃七夕密誓之所。白居易以华丽而深情的笔触描绘了这段帝王爱情的绚烂与哀伤——"在天愿作比翼鸟，在地愿为连理枝"。温泉池中的泉水温热如昔，唐代建筑基址的柱础石排列有序。骊山在长生殿后方巍然矗立，松柏苍翠。此处是中国古典爱情诗最伟大作品的诞生地，也是感受唐代皇家温泉文化的重要遗存。', '陕西', 34.366700, 109.214200, '其他', '["https://img2.baidu.com/it/u=3560998416,3748169643&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=738"]'),
('《登鹳雀楼》', '渭南市蒲城县鹳雀楼遗址', '王之涣', '唐代', '蒲城鹳雀楼遗址位于陕西省渭南市蒲城县，是王之涣《登鹳雀楼》的原始创作地。遗址保留有唐代夯土台基与宋代柱础，是鹳雀楼最早的建筑基址。王之涣"白日依山尽，黄河入海流。欲穷千里目，更上一层楼"的千古名篇正是在此登楼远眺时所作。与现代重建的鹳雀楼不同，此处保留了最原始的历史厚重感——风化的夯土、残存的柱础诉说着千年沧桑。周边平原辽阔，远处山脉如黛。此处是了解鹳雀楼原始建筑遗存与唐诗创作背景的考古价值极高的文学遗址。', '陕西', 34.955600, 109.586200, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/%E9%B9%B3%E9%9B%80%E6%A5%BC.jpg/1280px-%E9%B9%B3%E9%9B%80%E6%A5%BC.jpg"]'),
('《使至塞上》', '榆林市榆阳区镇北台遗址', '王维', '唐代', '镇北台遗址位于陕西省榆林市榆阳区，是王维《使至塞上》"大漠孤烟直，长河落日圆"的最佳观景点之一。镇北台保留有明代长城与古碑，是万里长城上最大的烽火台，高约30米，被誉为"万里长城第一台"。登台远眺，毛乌素沙漠辽阔无际，"大漠孤烟"的意境在此得到最真实的呈现。台基四层方形结构逐层递缩，建筑雄伟壮观。长城从镇北台向东西两方延伸，消失在沙漠与丘陵之间。黄昏时分落日浑圆如血，大漠苍茫。此处是感受唐代边塞诗壮美意境与明代长城军事文化的最震撼观景地。', '陕西', 38.277400, 109.734700, '其他', '["https://img1.baidu.com/it/u=2466138510,1949513412&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1400"]'),
('《秋兴八首・其六》', '西安市雁塔区曲江池遗址', '杜甫', '唐代', '曲江池遗址位于陕西省西安市雁塔区，是杜甫《秋兴八首》"曲江头"的核心取景地。遗址保留有唐代池岸、古碑与园林遗迹，曲江池是唐代长安城最著名的皇家园林与公共游览地。杜甫以"花萼夹城通御气，芙蓉小苑入边愁"的沉郁笔触追忆了曲江池昔日的繁华与安史之乱后的萧条。唐代曲江池水面辽阔，两岸杨柳如烟，帝王将相与文人墨客在此宴饮赋诗。池岸的唐代夯土遗存保留了原始的湖岸线形态。此处是了解唐代长安城市文化与杜甫晚年诗歌创作的重要园林遗址。', '陕西', 34.222000, 108.926900, '其他', '["https://img2.baidu.com/it/u=3559433545,627518276&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=750"]'),
('《过华清宫绝句三首・其一》', '西安市临潼区华清宫贵妃池遗址', '杜牧', '唐代', '华清宫贵妃池遗址位于陕西省西安市临潼区，是杜牧《过华清宫绝句》"一骑红尘妃子笑，无人知是荔枝来"的描绘地。贵妃池保留有唐代温泉池、古碑与建筑基址，池形如海棠花瓣，精巧典雅。贵妃池是唐明皇为杨贵妃专门修建的沐浴之所，"温泉水滑洗凝脂"的奢华生活在此展现无遗。杜牧以辛辣的讽刺揭示了帝王荒淫误国的历史教训。温泉水至今仍温热，池底的石刻花纹依稀可辨。骊山翠柏环绕，温泉蒸汽袅袅。此处是了解唐代皇家温泉文化与杜牧讽喻诗艺术的重要考古遗存。', '陕西', 34.366700, 109.214200, '其他', '["https://img1.baidu.com/it/u=304215598,2474048764&fm=253&fmt=auto&app=120&f=JPEG?w=822&h=800"]'),
('《乐游原》', '西安市雁塔区乐游原青龙寺遗址', '李商隐', '唐代', '乐游原青龙寺遗址位于陕西省西安市雁塔区，是李商隐《乐游原》"夕阳无限好，只是近黄昏"的创作地。遗址保留有唐代寺基、古碑与樱花林，青龙寺是唐代密宗重要道场，日本空海大师曾在此修行。李商隐登乐游原远眺长安城时写下了这首千古绝唱，"夕阳无限好"的感叹成为中国古诗中最经典的人生隐喻。乐游原是唐代长安城的制高点，可俯瞰全城。春日樱花盛开时粉白花海与古寺遗址交相辉映，美不胜收。此处是感受唐诗中最深沉的人生感悟与中日佛教文化交流的重要遗址。', '陕西', 34.222000, 108.926900, '其他', '["https://img0.baidu.com/it/u=2171173431,1042773201&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《送杜少府之任蜀州》', '西安市长安区杜陵遗址', '王勃', '唐代', '杜陵遗址位于陕西省西安市长安区，是王勃《送杜少府之任蜀州》中送别杜少府的真实地点。遗址保留有汉代夯土陵冢、古碑与古柏，杜陵是汉宣帝刘询的陵墓。王勃在此送别友人，"海内存知己，天涯若比邻"的旷达成为中国送别诗最伟大的名句。杜陵陵冢高大雄伟，周边平原辽阔。古柏苍翠环绕，鸟鸣幽静。唐代杜甫也自称"杜陵布衣""少陵野老"，与此地渊源深厚。陵区游客极少，保留了最原始的汉代陵墓风貌。此处是感受初唐送别诗豪迈气概与汉代帝陵庄严之美的小众文学地标。', '陕西', 34.157900, 108.941400, '其他', '["https://img2.baidu.com/it/u=3284496510,1600650994&fm=253&fmt=auto&app=138&f=JPEG?w=750&h=500"]'),
('《出塞二首・其一》', '榆林市神木县杨家城遗址', '王昌龄', '唐代', '杨家城遗址位于陕西省榆林市神木县，是王昌龄《出塞》"秦时明月汉时关"的描绘地。遗址保留有宋代夯土城墙、古碑与古战场，杨家城是北宋名将杨业（杨继业）镇守的边防重镇。王昌龄以边关将士的悲壮命运为主题，"但使龙城飞将在，不教胡马度阴山"的豪迈穿越千年。城墙蜿蜒于黄土高原之上，夯土风化严重但规模仍可辨识。"杨家将"的忠勇故事与此城紧密相连。城外毛乌素沙漠边缘的草原辽阔苍茫。此处是了解北宋边防军事与杨家将文化的重要考古遗址，也是感受边塞诗意境的壮美之地。', '陕西', 38.842400, 110.498700, '其他', '["https://img0.baidu.com/it/u=2991664084,2166560833&fm=253&fmt=auto&app=138&f=JPEG?w=683&h=500"]');
INSERT INTO works (title, scenic_spot, author, dynasty, description, province, latitude, longitude, category, images) VALUES
('《凉州词二首・其一》', '延安市宝塔区宝塔山遗址', '王之涣', '唐代', '宝塔山遗址位于陕西省延安市宝塔区，是王之涣《凉州词》"黄河远上白云间"的创作背景地之一。宝塔山保留有唐代塔基、明代塔身与古碑，宝塔高44米，是延安的标志性建筑。延安宝塔与黄河之间的壮阔景象为王之涣的诗歌创作提供了灵感。宝塔山还是中国革命的圣地，毛泽东等革命领袖在延安十三年间领导了抗日战争与解放战争。登上宝塔可俯瞰延安城全貌与延河蜿蜒流过的优美景象。此处是唐代边塞诗文化与中国革命红色文化交融的独特地标。', '陕西', 36.585300, 109.489600, '其他', '["https://img0.baidu.com/it/u=1686046983,2889084410&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《塞下曲六首・其一》', '延安市安塞区王家坪遗址', '卢纶', '唐代', '王家坪遗址位于陕西省延安市安塞区，是卢纶《塞下曲》"月黑雁飞高，单于夜遁逃"的描绘地。遗址保留有唐代古战场遗迹、古碑与窑洞，安塞地处陕北黄土高原腹地，自古为边防前沿。卢纶以简练的笔触描绘了月夜追敌的紧张与英勇。王家坪在抗日战争时期是八路军总部所在地，毛泽东、朱德等领导人曾在此指挥作战。窑洞中保留有指挥部与会议室。安塞腰鼓是国家级非物质文化遗产，"黄土高原上的摇滚乐"震撼人心。此处是唐代边塞军事文化与延安红色文化交融的独特历史空间。', '陕西', 36.863500, 109.328100, '其他', '["https://img1.baidu.com/it/u=3650429782,3914507455&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《从军行七首・其四》', '榆林市靖边县统万城遗址', '王昌龄', '唐代', '统万城遗址位于陕西省榆林市靖边县，是王昌龄《从军行》"黄沙百战穿金甲，不破楼兰终不还"的描绘地。统万城是十六国时期匈奴族赫连勃勃所建的大夏国都城，是中国历史上唯一由游牧民族建造的都城遗址。遗址保留有夯土城墙与宫殿基址，白色城墙在沙漠中矗立如雪，蔚为壮观。城墙夯土坚如磐石，"锥入一寸者杀之"的严苛筑城标准使其历经一千六百年仍基本完好。城址周边是毛乌素沙漠，沙丘起伏，荒凉壮美。此处是中国古代最神秘的都城遗址，也是感受边塞诗中大漠孤城意境的绝佳之地。', '陕西', 37.599200, 108.793700, '其他', '["https://img0.baidu.com/it/u=3759304480,500462433&fm=253&fmt=auto&app=138&f=JPEG?w=727&h=500"]'),
('《题西林壁》', '宝鸡市眉县太白山拔仙台遗址', '苏轼', '北宋', '太白山拔仙台遗址位于陕西省宝鸡市眉县，是苏轼《题西林壁》创作地之一。拔仙台是太白山主峰，海拔3771.2米，是秦岭最高峰，也是中国大陆东半壁最高峰。遗址保留有唐代古寺遗迹、古碑与壮美的云海风光。苏轼"不识庐山真面目，只缘身在此山中"的哲理在秦岭之巅获得了更宏大的自然呼应。拔仙台上常年云雾缭绕，夏季野花遍地，冬季积雪不化。"太白积雪六月天"是关中八景之一。高山湖泊大爷海碧蓝如镜。此处是感受秦岭自然壮美与宋代哲理诗意境的极高海拔文学体验地。', '陕西', 34.274100, 107.749900, '其他', '["https://img2.baidu.com/it/u=1560134087,4258073383&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《望岳》', '渭南市华阴市华山长空栈道遗址', '杜甫', '唐代', '华山长空栈道遗址位于陕西省渭南市华阴市，是杜甫《望岳》"会当凌绝顶，一览众山小"的核心取景地。长空栈道保留有唐代摩崖石刻与古栈道，是华山最险峻的景点——栈道凿于南峰绝壁之上，宽仅30余厘米，脚下万丈深渊。杜甫以青年时期的壮志豪情写下了"会当凌绝顶"的千古名句。华山为五岳之西岳，以"险"著称天下。长空栈道的铁链在山风中摇曳，悬崖上的石刻记录了历代勇者的足迹。此处是中国最险峻的登山体验地，也是感受杜甫诗歌中青春壮志与华山天险之美的极致之地。', '陕西', 34.566000, 110.087100, '其他', '["https://img2.baidu.com/it/u=1578136458,1937088216&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《春望》', '西安市新城区大明宫遗址含元殿基址', '杜甫', '唐代', '大明宫含元殿基址位于陕西省西安市新城区，是杜甫《春望》"国破山河在，城春草木深"的诞生地。含元殿保留有唐代夯土台基、柱础与古碑，是大明宫的正殿，也是唐代最宏伟的宫殿建筑。含元殿台基东西长约75米，南北宽约40米，气势恢宏。杜甫在安史之乱中目睹长安城的残破萧条，以"感时花溅泪，恨别鸟惊心"的沉痛笔触写下了这首千古绝唱。台基上的柱础石排列整齐，展示了唐代宫殿建筑的宏大规模。此处是了解唐代宫殿建筑巅峰与杜甫忧国诗篇的重要考古遗址。', '陕西', 34.266500, 108.959900, '其他', '["https://img1.baidu.com/it/u=3041126044,1971722954&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《月夜忆舍弟》', '咸阳市乾县乾陵无字碑遗址', '杜甫', '唐代', '乾陵无字碑遗址位于陕西省咸阳市乾县，是杜甫《月夜忆舍弟》"露从今夜白，月是故乡明"的创作背景地。无字碑保留有唐代碑刻、石雕与古柏，是武则天的功德碑——碑面无字，千古之谜。乾陵是唐高宗李治与武则天的合葬墓，是中国唯一的"二帝合葬"陵墓。神道两侧的石翁仲、翼马、鸵鸟石雕造型精美。"六十一蕃臣像"展现了唐代的国际影响力。乾陵"因山为陵"，以梁山为陵体，气势磅礴。此处是了解唐代帝陵制度与武则天历史传奇的国宝级文物保护单位。', '陕西', 34.527300, 108.239300, '其他', '["https://img0.baidu.com/it/u=511074113,4285154601&fm=253&fmt=auto&app=138&f=JPEG?w=784&h=500"]'),
('《渭川田家》', '西安市蓝田县辋川别业遗址', '王维', '唐代', '辋川别业遗址位于陕西省西安市蓝田县，是王维《渭川田家》"斜光照墟落，穷巷牛羊归"的描绘地。遗址保留有唐代园林基址、古碑与竹林，辋川别业是王维晚年隐居之所。王维以"诗中有画，画中有诗"的独特风格描绘了辋川的田园风光——"明月松间照，清泉石上流"的意境在此完美呈现。辋川山水秀美，竹林茂密，溪水潺潺。王维在此创作了大量山水田园诗，辋川成为中国文学中"诗意栖居"的最高象征。游客极少，山林幽静。此处是感受王维田园诗境与唐代文人隐逸文化的最重要文学遗存。', '陕西', 34.151300, 109.323300, '其他', '["https://img1.baidu.com/it/u=1747016050,3166365906&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《终南别业》', '西安市长安区终南山南五台遗址', '王维', '唐代', '终南山南五台遗址位于陕西省西安市长安区，是王维《终南别业》"行到水穷处，坐看云起时"的创作地。南五台保留有唐代古寺、古碑与山林风光，五座山峰并列，各有古寺。王维在终南山隐居时以禅意的笔触描绘了随遇而安的人生境界——"偶然值林叟，谈笑无还期"。南五台山势险峻，古木参天，溪流纵横。唐代文人"终南捷径"的典故即源于此山。山中古寺梵音袅袅，清泉从岩石间涌出。此处是感受王维禅诗意境与终南山隐逸文化的幽静山林之地。', '陕西', 34.157900, 108.941400, '其他', '["https://img1.baidu.com/it/u=385344001,3765564346&fm=253&fmt=auto&app=138&f=JPEG?w=752&h=500"]'),
('《送梓州高参军还京》', '宝鸡市陈仓区大散关遗址', '高适', '唐代', '大散关遗址位于陕西省宝鸡市陈仓区，是高适"北风吹断马嘶声"的描绘地。大散关保留有宋代关隘、古碑与古战场遗址，是关中通往汉中的重要军事关隘。陆游"铁马秋风大散关"的名句更使此关名扬天下。高适在此送别从军友人，北风呼啸中战马嘶鸣的壮烈场景令人动容。大散关地处秦岭险要，两山夹峙，一夫当关。三国时期蜀汉与曹魏在此多次交战。关城虽已残破但夯土基址清晰可辨。此处是了解秦岭军事关隘文化与唐宋边塞诗创作的重要历史遗存。', '陕西', 34.354600, 107.387500, '其他', '["https://img2.baidu.com/it/u=3041634426,275623495&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《蜀道难》', '汉中市宁强县剑门关遗址', '李白', '唐代', '剑门关遗址（宁强段）位于陕西省汉中市宁强县，是李白《蜀道难》"蜀道之难，难于上青天"的描绘地。遗址保留有唐代古驿道、古碑与摩崖石刻，蜀道从关中翻越秦岭进入汉中盆地。李白以"噫吁嚱，危乎高哉"的惊叹开篇，描绘了蜀道的艰险——"连峰去天不盈尺，枯松倒挂倚绝壁"。古驿道的石板路在悬崖峭壁间蜿蜒，栈道痕迹依稀可辨。秦岭山势雄浑壮阔，峡谷深邃幽暗。此处是感受李白浪漫主义诗歌巅峰之作与古蜀道艰险之美的重要文学遗存。', '陕西', 32.829400, 106.257400, '其他', '["https://img2.baidu.com/it/u=1212663752,3680788967&fm=253&fmt=auto&app=120&f=JPEG?w=800&h=1401"]'),
('《梦游天姥吟留别》', '宝鸡市眉县太白山大爷海遗址', '李白', '唐代', '太白山大爷海遗址位于陕西省宝鸡市眉县，是李白《梦游天姥吟留别》"天姥连天向天横，势拔五岳掩赤城"的创作灵感地。大爷海保留有唐代古寺遗迹与古碑，是秦岭最高峰太白山顶的高山湖泊，海拔3590米。大爷海碧蓝如宝石，四周峰峦环绕，终年积雪不化。李白以奇幻瑰丽的笔触描绘了梦中仙境的壮美，太白山的高山云海与冰川湖泊正是这种仙境意象的现实呼应。"太白积雪六月天"是关中八景之一。此处是中国大陆东部最高的高山湖泊，也是感受李白浪漫诗境与秦岭极高海拔自然之美的险远之地。', '陕西', 34.274100, 107.749900, '其他', '["https://img2.baidu.com/it/u=393400127,2265259704&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1762"]'),
('《将进酒》', '西安市碑林区碑林博物馆石台孝经遗址', '李白', '唐代', '碑林博物馆石台孝经遗址位于陕西省西安市碑林区，是李白《将进酒》"天生我材必有用，千金散尽还复来"的创作背景地之一。碑林保留有唐代碑刻、古亭与古柏，是中国最大的碑石博物馆，收藏碑石4000余方。石台孝经是唐玄宗李隆基亲笔书写并注释的《孝经》碑刻，是碑林最珍贵的藏品之一。碑林中还保存有颜真卿、柳公权、欧阳询等书法大家的碑刻真迹。李白在长安时期的豪放与失意交织，"天生我材"的自信成为中国文学最具感染力的人生宣言。此处是中国书法艺术的最高殿堂。', '陕西', 34.230300, 108.940300, '其他', '["https://img0.baidu.com/it/u=1723434140,3072737989&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=656"]'),
('《茅屋为秋风所破歌》', '西安市长安区杜甫草堂遗址', '杜甫', '唐代', '西安杜甫草堂遗址位于陕西省西安市长安区，是杜甫《茅屋为秋风所破歌》"安得广厦千万间，大庇天下寒士俱欢颜"的诞生地。遗址保留有唐代建筑基址、古碑与园林，是杜甫在长安困居时期的居所遗存。杜甫在长安十年间经历了从满怀希望到贫困潦倒的人生巨变，"朝扣富儿门，暮随肥马尘"的辛酸成就了他伟大的现实主义诗歌。草堂遗址中古柏苍翠，石径幽深。与成都杜甫草堂不同，此处游客极少，保留了更本真的历史氛围。此处是了解杜甫长安时期创作与唐代知识分子命运的重要文学遗存。', '陕西', 34.157900, 108.941400, '其他', '["https://img1.baidu.com/it/u=2854991183,1932923592&fm=253&fmt=auto&app=120&f=PNG?w=500&h=300"]'),
('《琵琶行》', '西安市莲湖区大唐西市遗址', '白居易', '唐代', '大唐西市遗址位于陕西省西安市莲湖区，是白居易《琵琶行》"江州司马青衫湿"的创作背景地之一。遗址保留有唐代市场基址、古碑与商铺遗迹，大唐西市是唐代长安城最繁华的国际贸易市场，丝绸之路的东方起点。白居易在长安时期频繁出入西市，市场中来自中亚、波斯、大食的商人与货物汇聚于此。遗址中的街道、店铺、排水沟展示了唐代城市商业的先进规划。胡姬酒肆、珠宝铺、绸缎庄在此鳞次栉比。此处是了解唐代国际贸易与丝绸之路文化的重要考古遗址。', '陕西', 34.265600, 108.933000, '其他', '["https://img2.baidu.com/it/u=796536123,1484543333&fm=253&fmt=auto&app=138&f=JPEG?w=1067&h=800"]'),
('《卖炭翁》', '西安市未央区大明宫遗址玄武门遗址', '白居易', '唐代', '大明宫玄武门遗址位于陕西省西安市未央区，是白居易《卖炭翁》"满面尘灰烟火色，两鬓苍苍十指黑"的描绘地。遗址保留有唐代夯土城墙与古碑，玄武门是大明宫北门，也是唐代政变的著名发生地。白居易以"宫市"制度为背景，揭示了宦官强买平民货物的社会黑暗——卖炭老翁辛苦烧炭却被宫中太监以"半匹红纱一丈绫"强行换走。玄武门城墙夯土高大，展现了唐代宫城的森严。此处是了解唐代宫城建筑与白居易讽喻诗社会批判精神的重要考古遗址。', '陕西', 34.292900, 108.946700, '其他', '["https://img2.baidu.com/it/u=3187380227,2298882717&fm=253&fmt=auto&app=138&f=JPEG?w=667&h=500"]'),
('《题都城南庄》', '西安市长安区崔护故居遗址', '崔护', '唐代', '崔护故居遗址位于陕西省西安市长安区，是崔护《题都城南庄》"去年今日此门中，人面桃花相映红"的诞生地。遗址保留有唐代建筑基址、古碑与桃林，春日桃花盛开时粉红花海如云似霞。崔护清明时节独游长安南郊，偶遇美丽少女，次年重访时"人面不知何处去，桃花依旧笑春风"的惆怅成为中国古诗中最经典的邂逅与错过主题。故居所在的长安区自古为京畿之地，桃林遍布。此处是感受唐代爱情诗中最美好的春日邂逅与长安南郊桃花风光的浪漫文学之地。', '陕西', 34.157900, 108.941400, '其他', '["https://img1.baidu.com/it/u=3773871223,2182166422&fm=253&fmt=auto&app=120&f=JPEG?w=500&h=636"]'),
('《过香积寺》', '西安市长安区香积寺遗址', '王维', '唐代', '香积寺遗址位于陕西省西安市长安区，是王维《过香积寺》"古木无人径，深山何处钟"的描绘地。香积寺保留有唐代建筑与古碑，始建于唐高宗永隆二年，是中国净土宗祖庭。王维以禅意的笔触描绘了香积寺的幽静——"泉声咽危石，日色冷青松"，被誉为唐代山水诗的巅峰之作。寺内古柏参天，善导大师塔矗立院中。"安史之乱"中的香积寺之战是唐军收复长安的决定性战役。寺院四周山林清幽，游客极少。此处是感受王维禅诗意境与净土宗佛教文化的清幽古刹。', '陕西', 34.157900, 108.941400, '其他', '["https://img0.baidu.com/it/u=4125522632,3334909646&fm=253&fmt=auto&app=138&f=JPEG?w=667&h=500"]'),
('《终南山》', '西安市长安区终南山翠华山遗址', '王维', '唐代', '终南山翠华山遗址位于陕西省西安市长安区，是王维《终南山》"太乙近天都，连山接海隅"的描绘地。翠华山保留有唐代古寺、古碑与独特的地质遗迹，是国家地质公园。王维以"白云回望合，青霭入看无"的空灵笔触描绘了终南山的云雾缭绕与山色变幻。翠华山的"天池"是山崩堰塞湖，碧水如镜，四周悬崖峭壁。"太乙"即终南山的别称，唐代文人视其为通天之山。山中古寺隐于林间，溪水在乱石间奔流。此处是了解秦岭地质奇观与王维山水诗审美的自然与文学交融之地。', '陕西', 34.157900, 108.941400, '其他', '["https://img2.baidu.com/it/u=4240233274,2164027184&fm=253&fmt=auto&app=138&f=JPEG?w=667&h=500"]'),
('《白鹿原》', '西安市蓝田县白鹿原影视城滋水县城', '陈忠实', '现代', '白鹿原影视城滋水县城位于陕西省西安市蓝田县，是陈忠实《白鹿原》的核心原型地。影视城保留有清末民初关中民居、老祠堂与古戏台，严格按照小说中白鹿村的描写建造。陈忠实以白鹿原上白鹿两家半个世纪的恩怨为主线，描绘了中国近现代史上最波澜壮阔的农村社会变迁。祠堂是宗族权力的象征，"乡约"石碑镌刻着封建秩序的严苛。古戏台上秦腔高亢激越。关中民居的厚重土墙、窄院深宅体现了"房子半边盖"的独特建筑风格。此处是走进陈忠实史诗文学世界与体验关中民俗文化的最直观空间。', '陕西', 34.151300, 109.323300, '其他', '["https://img2.baidu.com/it/u=2937942594,1446748485&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《平凡的世界》', '延安市延川县郭家沟村', '路遥', '现代', '郭家沟村位于陕西省延安市延川县，是路遥《平凡的世界》中"双水村"的真实原型地。村庄保留有典型的陕北窑洞、老磨坊与古巷，黄土高原的沟壑纵横。路遥以孙少安、孙少平兄弟的奋斗历程为主线，描绘了二十世纪七八十年代中国农村从封闭走向开放的历史巨变。窑洞依山而建，土墙斑驳，磨坊中的石磨仍保留原貌。村中小路蜿蜒于沟梁之间，黄土在风中飞扬。路遥曾在延川县城与乡村间往返体验生活，积累了大量创作素材。此处是走进路遥文学世界、感受陕北农村质朴生活的最真实文学原型地。', '陕西', 36.878100, 110.194200, '其他', '["https://img2.baidu.com/it/u=2118186690,1698505871&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《人生》', '延安市延川县文安驿古镇', '路遥', '现代', '文安驿古镇位于陕西省延安市延川县，是路遥《人生》中高加林与刘巧珍爱情故事的背景地。古镇保留有陕北窑洞、老商铺与古驿道，始建于西魏大统三年，是陕北古驿道上的重要驿站。路遥以"城乡交叉地带"的矛盾为主题，描绘了高加林在理想与现实之间的挣扎与抉择。古驿道的石板路磨损光滑，两侧窑洞商铺鳞次栉比。文安驿也是知青上山下乡的历史见证地，习近平曾在附近的梁家河村插队。此处是了解路遥文学创作与陕北驿站文化的重要小众古镇。', '陕西', 36.878100, 110.194200, '其他', '["https://img2.baidu.com/it/u=2157654188,3245449246&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=602"]'),
('《秦腔》', '商洛市丹凤县棣花古镇', '贾平凹', '现代', '棣花古镇位于陕西省商洛市丹凤县，是贾平凹《秦腔》中"清风街"的原型地，也是贾平凹的故乡。古镇保留有陕南民居、老戏台与古桥，宋金时期的二郎庙展现了古镇悠久的历史。贾平凹以故乡为蓝本，描绘了关中农村在社会转型期的阵痛与嬗变——土地流转、文化消解、乡村凋敝。古镇的老戏台上秦腔高亢激越，老街青石板路两侧的民居古色古香。丹江从古镇旁蜿蜒流过，水清见底。贾平凹文学馆坐落于此，展示了其文学创作的心路历程。此处是走进贾平凹文学原乡的最佳目的地。', '陕西', 33.694800, 110.326900, '其他', '["https://img1.baidu.com/it/u=3859115865,2227386048&fm=253&fmt=auto&app=138&f=JPEG?w=1067&h=800"]'),
('《废都》', '西安市莲湖区回民街北院门遗址', '贾平凹', '现代', '回民街北院门遗址位于陕西省西安市莲湖区，是贾平凹《废都》中"西京"的核心原型地。遗址保留有明清古民居、老商铺与古巷，北院门是明清时期的官署所在地。贾平凹以知识分子庄之蝶的精神困境为主线，描绘了九十年代初都市知识分子的迷茫与堕落。古巷幽深，青砖灰瓦的明清民居保留着旧时的格局。与回民街核心区的喧闹不同，北院门老巷中游客稀少，保留了最本真的西安市井气息。高家大院的明代建筑精美绝伦。此处是感受贾平凹笔下"西京"知识分子生活场景与明清西安城市文化的幽静文学之地。', '陕西', 34.265600, 108.933000, '其他', '["https://img0.baidu.com/it/u=350104071,3878862988&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=887"]'),
('《浮躁》', '商洛市商州区仙娥湖遗址', '贾平凹', '现代', '仙娥湖遗址位于陕西省商洛市商州区，是贾平凹《浮躁》中"州河"的原型地。遗址保留有原始湖泊、古码头与山林风光，仙娥湖依丹江而成，碧水如镜。贾平凹以改革开放初期商州农村的社会变革为背景，描绘了金狗等人在物质与精神之间的"浮躁"状态。湖面平静时倒映着两岸青山，微风起时碧波荡漾。古码头的石阶延伸入水中，诉说着曾经的水运繁华。丹江是汉江最大支流，水质清澈。山林中鸟鸣不绝，四季景色各异。此处是了解贾平凹早期创作与商洛山水风光的清幽文学之地。', '陕西', 33.862700, 109.941200, '其他', '["https://img2.baidu.com/it/u=2551510062,3784391713&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《古炉》', '铜川市耀州区陈炉古镇', '贾平凹', '现代', '陈炉古镇位于陕西省铜川市耀州区，是贾平凹《古炉》中"古炉村"的原型地。古镇保留有明清瓷窑、老作坊与古民居，是中国北方最大的民窑——耀州窑的延续地，烧瓷历史长达一千四百余年。贾平凹以"文革"时期陈炉古镇为背景，描绘了特殊年代普通人的命运。古镇依山而建，层层叠叠的窑洞与瓷窑交错排列。"罐罐垒墙"是陈炉独特的建筑风格——用废弃的陶罐砌成墙壁和台阶。至今仍有窑工在传统柴窑中烧制耀州青瓷。此处是感受千年窑火不息的陶瓷文化与贾平凹文学世界的活态古镇。', '陕西', 34.908700, 108.980700, '其他', '["https://img2.baidu.com/it/u=3645817221,2907730103&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=652"]'),
('《带灯》', '汉中市洋县华阳古镇', '贾平凹', '现代', '华阳古镇位于陕西省汉中市洋县，是贾平凹《带灯》中"樱镇"的原型地。古镇保留有陕南民居、老商铺与古桥，地处秦岭南麓深处，是中国四大国宝动物（朱鹮、大熊猫、金丝猴、羚牛）的栖息地。贾平凹以基层女干部带灯的工作与生活为主线，描绘了当代农村基层治理的困境与坚守。古镇老街青石板铺地，两侧明清建筑保存完好。华阳古镇自汉代起即为傥骆道上的重要驿站，三国时期蜀汉军队多次经此翻越秦岭。此处是感受秦岭深处生态之美与贾平凹乡土文学世界的极静之地。', '陕西', 33.223000, 107.546700, '其他', '["https://img0.baidu.com/it/u=1106136240,2172086788&fm=253&fmt=auto&app=138&f=JPEG?w=846&h=800"]'),
('《山本》', '商洛市山阳县漫川关古镇', '贾平凹', '现代', '漫川关古镇位于陕西省商洛市山阳县，是贾平凹《山本》中"漫川关"的真实描绘地。古镇保留有明清古民居、老商铺与古战场遗址，地处陕鄂交界的秦楚咽喉之地。贾平凹以二十世纪二三十年代的秦岭为背景，描绘了军阀混战、土匪横行中普通百姓的苦难与挣扎。古镇的骡帮会馆、武昌会馆展现了昔日商贸的繁华。"朝秦暮楚"的成语典故即源于此地。古镇两侧山势陡峭，河水在峡谷中奔流。明清时期的鸳鸯双戏楼全国罕见。此处是了解秦楚文化交融与贾平凹秦岭文学的边地古镇。', '陕西', 33.530200, 109.882700, '其他', '["https://img0.baidu.com/it/u=3212983023,3331005014&fm=253&fmt=auto&app=138&f=JPEG?w=1423&h=800"]'),
('《创业史》', '西安市长安区皇甫村遗址', '柳青', '现代', '皇甫村遗址位于陕西省西安市长安区，是柳青《创业史》中梁生宝互助组的原型地。遗址保留有关中民居、老磨坊与古巷，柳青在此深入生活十四年，与农民同吃同住同劳动。《创业史》以新中国成立初期农业合作化运动为背景，描绘了梁生宝带领农民走互助合作道路的艰辛历程。村中的旧窑洞是柳青的写作之地，磨坊中的石磨记录着当年的农耕生活。柳青将自己的稿费全部捐给皇甫村用于建设。此处是了解中国当代文学"深入生活"创作传统与关中农村社会变迁的重要文学遗存。', '陕西', 34.157900, 108.941400, '其他', '["https://img1.baidu.com/it/u=3920400713,2743610145&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《保卫延安》', '延安市宝塔区王家坪革命旧址', '杜鹏程', '现代', '王家坪革命旧址位于陕西省延安市宝塔区，是杜鹏程《保卫延安》中延安保卫战的核心背景地。旧址保留有革命时期窑洞、古碑与历史文物，王家坪是抗日战争和解放战争时期八路军总司令部与中央军委所在地。杜鹏程以1947年延安保卫战为背景，描绘了彭德怀指挥西北野战军以少胜多的壮烈战役。毛泽东、朱德、彭德怀曾在此运筹帷幄。窑洞中的指挥桌、军事地图保留原貌。延河从旧址旁流过，宝塔山矗立对岸。此处是了解延安保卫战历史与中国革命军事文学的重要红色文化遗存。', '陕西', 36.585300, 109.489600, '其他', '["https://img1.baidu.com/it/u=3650429782,3914507455&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《红日》', '延安市吴起县吴起镇革命旧址', '吴强', '现代', '吴起镇革命旧址位于陕西省延安市吴起县，是吴强《红日》创作的革命背景地之一。旧址保留有革命时期窑洞、古碑与历史文物，1935年10月中央红军长征到达吴起镇，标志着二万五千里长征的胜利结束。毛泽东在此指挥了"切尾巴"战役，歼灭国民党追兵一个骑兵团。吴起县地处陕北黄土高原，沟壑纵横，地势险要。旧址中的窑洞保留了当年红军的生活场景。"长征是宣言书，长征是宣传队，长征是播种机"的论断在此发表。此处是了解红军长征胜利与中国革命历史的重要红色地标。', '陕西', 36.927500, 108.175600, '其他', '["https://img1.baidu.com/it/u=1406453326,2134213966&fm=253&fmt=auto&app=120&f=JPEG?w=1067&h=800"]'),
('《红岩》', '延安市宝塔区枣园革命旧址', '罗广斌', '现代', '枣园革命旧址位于陕西省延安市宝塔区，是罗广斌《红岩》革命精神的背景地之一。旧址保留有革命时期窑洞、古柏与历史文物，枣园是1943年至1947年中共中央书记处所在地。毛泽东、周恩来、朱德等领导人在此居住和工作，指导了大生产运动与整风运动。枣园的窑洞依山而建，院中古柏苍翠，枣树成林。毛泽东的"为人民服务"演讲即在枣园发表。园区内的石磨、纺车展现了"自己动手，丰衣足食"的革命精神。此处是了解延安时期党中央领导机关工作生活与革命文学精神的核心红色遗址。', '陕西', 36.585300, 109.489600, '其他', '["https://img2.baidu.com/it/u=1562235530,1652644577&fm=253&fmt=auto&app=120&f=JPEG?w=800&h=1044"]'),
('《史记・项羽本纪》', '西安市临潼区鸿门宴遗址', '司马迁', '西汉', '鸿门宴遗址位于陕西省西安市临潼区，是司马迁《史记・项羽本纪》中鸿门宴的真实发生地。遗址保留有汉代夯土台基、古碑与古战场遗迹，鸿门宴是中国历史上最著名的饭局——项羽设宴邀刘邦赴会，范增举玉玦示意杀刘邦，项庄舞剑意在沛公，樊哙闯帐护主。司马迁以"史家之绝唱，无韵之离骚"的笔法将这一历史事件写成千古名篇。夯土台基上保留有汉代遗迹，周边平原辽阔。"项庄舞剑""鸿门宴"已成为中国文化中最经典的典故。此处是感受楚汉争霸历史与司马迁史学文学巅峰的重要古战场遗址。', '陕西', 34.366700, 109.214200, '其他', '["https://img0.baidu.com/it/u=59530496,1915972206&fm=253&fmt=auto&app=138&f=JPEG?w=1067&h=800"]'),
('《史记・秦始皇本纪》', '西安市临潼区秦始皇兵马俑一号坑遗址', '司马迁', '西汉', '秦始皇兵马俑一号坑遗址位于陕西省西安市临潼区，是司马迁《史记・秦始皇本纪》记载的秦始皇陵核心陪葬坑。一号坑保留有秦代兵马俑六千余尊、古战车与兵器，是世界第八大奇迹。司马迁记载秦始皇陵"以水银为百川江河大海"，地下宫殿规模宏大。一号坑东西长230米，南北宽62米，坑内兵马俑按军阵排列，每尊面部表情各异。秦俑高约1.8米，身着铠甲，手持兵器，栩栩如生。此处虽为知名景点，但一号坑深处的修复区域游客较少，可近距离观察秦俑制作工艺的精湛细节。', '陕西', 34.366700, 109.214200, '其他', '["https://img0.baidu.com/it/u=3631383826,3143341692&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《阿房宫赋》', '西安市未央区阿房宫遗址前殿基址', '杜牧', '唐代', '阿房宫遗址前殿基址位于陕西省西安市未央区，是杜牧《阿房宫赋》"覆压三百余里，隔离天日"的描绘地。遗址保留有秦代夯土台基、古碑与柱础，前殿基址东西长1270米，南北宽426米，是中国古代最大的宫殿建筑基址。杜牧以"六王毕，四海一，蜀山兀，阿房出"的磅礴气势开篇，"楚人一炬，可怜焦土"的结尾警示后世。夯土台基高达十余米，气势恢宏。考古发掘表明阿房宫实际未完全建成，项羽焚烧的可能是咸阳宫而非阿房宫。此处是了解秦代宫殿建筑规模与杜牧赋体文学艺术的重要考古遗址。', '陕西', 34.292900, 108.946700, '其他', '["https://img0.baidu.com/it/u=3662911478,3544820674&fm=253&fmt=auto&app=138&f=JPEG?w=681&h=500"]'),
('《过秦论》', '咸阳市秦都区咸阳宫遗址', '贾谊', '西汉', '咸阳宫遗址位于陕西省咸阳市秦都区，是贾谊《过秦论》中描述的秦代宫殿核心遗址。遗址保留有秦代夯土台基、古碑与建筑遗迹，咸阳宫是秦帝国的政治中心——秦始皇在此发号施令，统一文字、度量衡与货币。贾谊以"仁义不施而攻守之势异也"的深刻论断总结了秦朝速亡的历史教训。咸阳宫遗址中出土了精美的秦代壁画残片，是中国最早的宫殿壁画。台基上的夯土层清晰可辨，展示了秦代建筑技术的先进。周边渭河平原辽阔，古都咸阳的历史厚重感扑面而来。此处是了解秦帝国政治制度与贾谊政论文学的国宝级遗址。', '陕西', 34.329600, 108.706900, '其他', '["https://img0.baidu.com/it/u=744789195,3536471156&fm=253&fmt=auto&app=120&f=JPEG?w=800&h=1070"]'),
('《滕王阁序》', '西安市雁塔区大雁塔遗址', '王勃', '唐代', '大雁塔遗址位于陕西省西安市雁塔区，是王勃《滕王阁序》创作背景地之一。大雁塔保留有唐代砖塔、古碑与佛教文物，始建于唐高宗永徽三年，是玄奘法师为保存从印度带回的经卷而建。塔高64米，七层方形砖塔庄严肃穆。唐代进士及第后有"雁塔题名"的传统，王勃等初唐四杰均与此地有深厚渊源。塔内保存有玄奘翻译的佛经与唐代碑刻。大雁塔是丝绸之路东方的文化地标，见证了唐代佛教文化的鼎盛。此处是了解唐代佛教文化与初唐文学繁荣的标志性古建筑。', '陕西', 34.222000, 108.926900, '其他', '["https://img0.baidu.com/it/u=1529688404,1753826547&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1200"]'),
('《岳阳楼记》', '西安市碑林区西安碑林博物馆', '范仲淹', '北宋', '西安碑林博物馆位于陕西省西安市碑林区，是范仲淹《岳阳楼记》碑刻的重要收藏地。碑林保留有宋代碑刻、古亭与古柏，始建于北宋元祐二年，收藏碑石4000余方，是中国最大的碑石博物馆。范仲淹"先天下之忧而忧，后天下之乐而乐"的千古名句被镌刻于碑石之上。碑林中还收藏有《开成石经》《大秦景教流行中国碑》等国宝级碑刻。颜真卿、柳公权、欧阳询等书法大家的碑刻真迹荟萃于此。碑林古柏参天，碑廊幽静。此处是中国书法艺术的最高殿堂，也是宋代文学经典永恒传承的石刻宝库。', '陕西', 34.230300, 108.940300, '其他', '["https://img2.baidu.com/it/u=1165461467,2487495974&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1068"]'),
('《醉翁亭记》', '西安市长安区终南山醉翁亭遗址', '欧阳修', '北宋', '终南山醉翁亭遗址位于陕西省西安市长安区，是欧阳修《醉翁亭记》创作背景地之一。遗址保留有宋代亭基、古碑与山林风光，终南山自古为文人雅士的隐居胜地。欧阳修"醉翁之意不在酒，在乎山水之间也"的旷达人生态度在终南山的青山绿水间得到了最佳呈现。终南山峰峦叠嶂，溪流淙淙，四季景色各异——春花烂漫，夏荫浓郁，秋叶如火，冬雪皑皑。亭基旁古柏苍翠，鸟鸣不绝。终南山是中国道教、佛教的重要圣地。此处是感受欧阳修散文美学与终南山隐逸文化的幽静山林之地。', '陕西', 34.157900, 108.941400, '其他', '["https://img2.baidu.com/it/u=3395798111,4190304576&fm=253&fmt=auto&app=138&f=JPEG?w=750&h=500"]'),
('《水经注・渭水注》', '西安市临潼区华清池遗址', '郦道元', '北魏', '华清池遗址位于陕西省西安市临潼区，是郦道元《水经注・渭水注》重点记载的名泉。遗址保留有唐代温泉池、古碑与建筑基址，华清池的温泉开发始于西周，已有三千年历史。郦道元以严谨的地理学笔法记录了骊山温泉的位置、水温与地形特征，是中国最早的温泉科学文献之一。华清池温泉水温43度，含有多种矿物质。唐代在此修建了规模宏大的温泉宫殿群。骊山苍翠环绕，温泉蒸汽袅袅。此处是了解中国温泉文化三千年历史与郦道元地理学著作的重要自然与文化遗存。', '陕西', 34.366700, 109.214200, '其他', '["https://img2.baidu.com/it/u=241420332,3463992433&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《徐霞客游记・游太华山记》', '渭南市华阴市华山长空栈道遗址', '徐霞客', '明代', '华山长空栈道遗址（徐霞客段）位于陕西省渭南市华阴市，是徐霞客《游太华山记》"华山之险，天下第一"的描绘地。遗址保留有唐代摩崖石刻与古栈道，徐霞客在明代万历年间登临华山，以详实的笔触记录了华山五峰的地形、岩石与植被。长空栈道凿于南峰绝壁之上，下临万丈深渊，是华山最险峻的景观。徐霞客"五岳归来不看山"的感叹使华山之险名扬天下。栈道上的铁链在山风中摇曳，悬崖石壁上的摩崖石刻记录了历代探险者的足迹。此处是感受明代旅行文学与华山天险之美的极致探险体验地。', '陕西', 34.566000, 110.087100, '其他', '["https://img2.baidu.com/it/u=1578136458,1937088216&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《游华山记》', '渭南市华阴市华山西峰遗址', '袁宏道', '明代', '华山西峰遗址位于陕西省渭南市华阴市，是袁宏道《游华山记》"西峰之胜，甲于华山"的描绘地。西峰保留有唐代古寺、古碑与壮美的云海风光，西峰又名莲花峰，海拔2082米，峰顶有翠云宫与斧劈石。袁宏道以性灵派独特的审美眼光描绘了华山西峰的险峻与秀美——绝壁如刀削斧劈，云海在脚下翻涌。"沉香劈山救母"的神话传说使斧劈石成为华山最著名的景观之一。夕阳西下时西峰金光万道，壮美非常。古寺隐于峰顶石壁之间，钟声在山谷中回荡。此处是感受明代性灵文学与华山西峰壮美的登山体验之地。', '陕西', 34.566000, 110.087100, '其他', '["https://img0.baidu.com/it/u=2504793672,1862840364&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《文化苦旅・道士塔》', '西安市雁塔区大雁塔遗址', '余秋雨', '现代', '大雁塔遗址（余秋雨段）位于陕西省西安市雁塔区，是余秋雨《文化苦旅・道士塔》中敦煌文化传播的关联地。大雁塔是玄奘法师从印度取经归来后翻译佛经的重要场所，保留有唐代砖塔与佛教文物。余秋雨以沉痛的笔触讲述了敦煌莫高窟文物被道士王圆箓卖给外国探险家的悲惨历史。大雁塔作为中国佛教文化东传的象征，与敦煌莫高窟的西域文化交流形成了丝绸之路上的文化呼应。塔身古朴庄严，七层砖塔直指苍穹。此处是了解丝绸之路文化交流与余秋雨文化反思文学的历史文化地标。', '陕西', 34.222000, 108.926900, '其他', '["https://img0.baidu.com/it/u=1529688404,1753826547&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1200"]'),
('《文化苦旅・莫高窟》', '咸阳市乾县乾陵壁画墓遗址', '余秋雨', '现代', '乾陵壁画墓遗址位于陕西省咸阳市乾县，是余秋雨《文化苦旅・莫高窟》中唐代壁画的核心收藏地。遗址保留有唐代壁画、古碑与石雕，乾陵陪葬墓中的壁画是中国唐代绘画艺术的巅峰之作。永泰公主墓、章怀太子墓、懿德太子墓中的壁画色彩鲜艳，线条流畅，展现了唐代宫廷生活的华丽与优雅。"仕女图""马球图""狩猎出行图"等壁画堪称国宝。余秋雨以莫高窟为起点，追溯了中国古代壁画艺术的辉煌传统。此处是了解唐代壁画艺术巅峰与中国古代绘画美学的地下艺术宝库。', '陕西', 34.527300, 108.239300, '其他', '["https://img0.baidu.com/it/u=3541164141,2565367744&fm=253&fmt=auto&app=120&f=JPEG?w=500&h=744"]'),
('《山居笔记・一个王朝的背影》', '延安市黄陵县黄帝陵遗址', '余秋雨', '现代', '黄帝陵遗址位于陕西省延安市黄陵县，是余秋雨《山居笔记・一个王朝的背影》中中华民族始祖文化的见证地。遗址保留有汉代陵冢、古碑与古柏，黄帝陵被誉为"天下第一陵"，是中华民族的精神象征。陵区内的"黄帝手植柏"相传已有五千年历史，树干苍劲，枝叶繁茂。祭祀广场的祭祀大殿庄严肃穆，每年清明公祭黄帝典礼在此举行。"桥山龙驭"是黄帝陵八景之一。陵冢高大浑厚，四周古柏森森。余秋雨以深沉的文化反思审视了中华文明的源头与传承。此处是了解中华民族根祖文化的最神圣精神圣地。', '陕西', 35.579400, 109.262800, '其他', '["https://img1.baidu.com/it/u=1151633738,1257790503&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1766"]'),
('《千年一叹》', '西安市临潼区秦始皇陵遗址', '余秋雨', '现代', '秦始皇陵遗址位于陕西省西安市临潼区，是余秋雨《千年一叹》中秦代文明的核心见证地。遗址保留有秦代夯土陵冢、古碑与陪葬坑，秦始皇陵是中国历史上第一座规模宏大的帝王陵墓。陵冢高约76米，周长约2公里，"以水银为百川江河大海"的记载至今未被考古发掘验证。余秋雨以"千年一叹"的深沉叹息追溯了人类古文明的兴衰。陵区内的铜车马坑出土了精美的秦代铜车马，工艺精湛。陵冢四周植被茂密，气势磅礴。此处是了解秦帝国雄伟气概与余秋雨文明反思的世界文化遗产级考古遗址。', '陕西', 34.366700, 109.214200, '其他', '["https://img0.baidu.com/it/u=3340042376,238729221&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《行者无疆》', '宝鸡市扶风县法门寺遗址', '余秋雨', '现代', '法门寺遗址位于陕西省宝鸡市扶风县，是余秋雨《行者无疆》中佛教文化的重要遗址。法门寺保留有唐代地宫、古碑与佛教文物，始建于东汉末年，因供奉释迦牟尼佛指骨舍利而闻名天下。1987年地宫发掘出土了四枚佛指骨舍利与2499件唐代珍贵文物，震惊世界。唐代皇帝曾七次开启地宫迎奉佛骨，"三十年一开，则岁丰人和"。地宫中的金银器、琉璃器、丝织品展示了唐代工艺的登峰造极。法门寺塔始建于明代，砖塔庄严挺拔。此处是了解唐代佛教文化鼎盛与地宫考古的世界级佛教圣地。', '陕西', 34.375200, 107.900400, '其他', '["https://img1.baidu.com/it/u=1887785799,1416151054&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1537"]'),
('《借我一生》', '西安市长安区贾平凹故居遗址', '余秋雨', '现代', '贾平凹故居遗址位于陕西省西安市长安区，是余秋雨《借我一生》中提及的文学名人成长地。故居保留有陕南风格民居、老书房与古碑，是贾平凹在西安时期的居所。贾平凹从商洛山区走进西安城，以"废都""秦腔""古炉"等作品构建了当代文学中最庞大的秦地文学世界。书房中保留有手稿、藏书与文房四宝。贾平凹以"丑石"般朴拙的外表蕴含着深邃的文学力量。故居四周古木参天，环境清幽。余秋雨在文中回忆了与贾平凹等当代作家的交往。此处是了解当代中国文学大家创作生活的小众文学故居。', '陕西', 34.157900, 108.941400, '其他', '["https://img2.baidu.com/it/u=1196343234,3164326716&fm=253&fmt=auto&app=120&f=JPEG?w=889&h=500"]'),
('《秦腔》', '西安市莲湖区易俗社遗址', '贾平凹', '现代', '易俗社遗址位于陕西省西安市莲湖区，是贾平凹《秦腔》中秦腔艺术核心传承地的真实原型。遗址保留有民国建筑、古戏台与历史文物，易俗社创办于1912年，是中国最古老的话剧社团之一，也是秦腔最重要的演出机构。贾平凹以秦腔为文化符号，描绘了关中农村传统文化在现代化进程中的消解与坚守。易俗社的舞台上演出了无数经典秦腔剧目——《三滴血》《火焰驹》等。鲁迅曾题赠"古调独弹"匾额。秦腔高亢激越，被誉为中国戏曲的"活化石"。此处是了解秦腔艺术百年传承与贾平凹文化小说的重要表演艺术遗存。', '陕西', 34.265600, 108.933000, '其他', '["https://img0.baidu.com/it/u=3639738576,1411385169&fm=253&fmt=auto&app=120&f=JPEG?w=800&h=1044"]'),
('《凉州词二首・其一》', '武威市凉州区凉州古城钟楼遗址', '王之涣', '唐代', '凉州古城钟楼遗址位于甘肃省武威市凉州区，是王之涣《凉州词》"黄河远上白云间，一片孤城万仞山"的核心取景地。遗址保留有明代钟楼、唐代夯土城墙残段与古碑，凉州是古丝绸之路重镇，"凉州七里十万家"盛极一时。王之涣以苍凉雄浑的笔触描绘了边塞孤城的壮美与将士的思乡之情——"羌笛何须怨杨柳，春风不度玉门关"。钟楼为明代重修，雕梁画栋。唐代城墙残段夯土层清晰，展示了丝路重镇的军事防御体系。凉州文化融汇中原与西域。此处是感受唐代边塞诗最经典意境与河西走廊丝路文化的重要历史遗存。', '甘肃', 37.928300, 102.637800, '其他', '["https://img0.baidu.com/it/u=4273087390,2087237080&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1066"]');
INSERT INTO works (title, scenic_spot, author, dynasty, description, province, latitude, longitude, category, images) VALUES
('《凉州词二首・其一》', '武威市凉州区雷台汉墓遗址', '王翰', '唐代', '雷台汉墓遗址位于甘肃省武威市凉州区，是王翰《凉州词》"葡萄美酒夜光杯，欲饮琵琶马上催"的创作背景地。遗址保留有东汉墓葬、铜车马仪仗与古碑，最重要的出土文物是举世闻名的"马踏飞燕"——铜奔马凌空飞驰，三足腾空，一足踏在飞燕背上，被定为中国旅游标志。王翰以豪放的笔触描绘了边塞将士"醉卧沙场君莫笑，古来征战几人回"的壮烈与悲凉。墓葬中的铜车马仪仗队由99件铜器组成，规模宏大。此处是了解东汉墓葬文化与唐代边塞诗豪迈意境的国宝级考古遗址。', '甘肃', 37.928300, 102.637800, '其他', '["https://img0.baidu.com/it/u=3609698081,2502751227&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《使至塞上》', '张掖市高台县骆驼城遗址', '王维', '唐代', '骆驼城遗址位于甘肃省张掖市高台县，是王维《使至塞上》"大漠孤烟直，长河落日圆"的最佳观景点之一。遗址保留有汉代夯土城墙、宫殿基址与古驿道，是河西走廊保存最完整的古城遗址之一，面积达30余万平方米。骆驼城始建于汉代，历经魏晋南北朝至唐代，是丝绸之路上的重要城镇。城墙夯土层清晰，瓮城、马面等军事设施保存完好。城外是辽阔的戈壁荒漠，日落时分"大漠孤烟"的意境在此得到最真实的呈现。此处是河西走廊最壮观的古城遗址，感受丝路古城的千年沧桑。', '甘肃', 39.378200, 99.819400, '其他', '["https://img0.baidu.com/it/u=2300063210,2063896560&fm=253&fmt=auto&app=138&f=JPEG?w=948&h=347"]'),
('《白雪歌送武判官归京》', '酒泉市瓜州县锁阳城遗址', '岑参', '唐代', '锁阳城遗址位于甘肃省酒泉市瓜州县，是岑参《白雪歌送武判官归京》"忽如一夜春风来，千树万树梨花开"的创作地。遗址保留有唐代夯土城墙、寺庙遗址与古垦区，是世界文化遗产"丝绸之路：长安—天山廊道"的组成部分。锁阳城始建于汉代，唐代为瓜州郡治所，岑参曾在此任职。城墙高达十余米，角楼、马面保存完好。城内的塔尔寺遗址保留有唐代佛塔基座。城外古垦区的灌溉渠系展示了唐代河西走廊的农业成就。戈壁中的孤城在落日余晖下雄浑壮美。此处是丝绸之路上最震撼的唐代古城遗址。', '甘肃', 40.520600, 95.782500, '其他', '["https://img2.baidu.com/it/u=3428096243,1565296533&fm=253&fmt=auto&app=138&f=JPEG?w=1200&h=800"]'),
('《逢入京使》', '武威市古浪县古浪峡遗址', '岑参', '唐代', '古浪峡遗址位于甘肃省武威市古浪县，是岑参《逢入京使》"故园东望路漫漫，双袖龙钟泪不干"的诞生地。遗址保留有明代长城、古驿道与摩崖石刻，古浪峡地势险要，两山夹峙，是河西走廊的东大门，历来为军事必争之地。岑参西行赴安西途中经过古浪峡，偶遇入京使者，"马上相逢无纸笔，凭君传语报平安"的匆忙与深情感人至深。明代长城在山脊上蜿蜒延伸，烽燧矗立山巅。古驿道的车辙痕迹深深嵌入岩石之中。此处是感受唐代边塞诗人西行之路艰辛与河西走廊军事关隘的小众历史遗存。', '甘肃', 37.470300, 102.897500, '其他', '["https://img0.baidu.com/it/u=2538190255,1892024604&fm=253&fmt=auto&app=138&f=JPEG?w=666&h=500"]'),
('《关山月》', '天水市秦安县关山古道遗址', '李白', '唐代', '关山古道遗址位于甘肃省天水市秦安县，是李白《关山月》"明月出天山，苍茫云海间"的描绘地。遗址保留有唐代驿路、古关隘与摩崖石刻，关山是陇山的重要组成部分，是关中通往陇西的必经之路。李白以雄浑苍凉的笔触描绘了边关将士在明月下思念故乡的深情——"长风几万里，吹度玉门关"。古驿道在群山间蜿蜒曲折，两侧草原辽阔，牛羊成群。关山秋日红叶漫山，冬日白雪皑皑。关隘遗址的夯土墙体在风雨中斑驳。此处是感受李白边塞诗中天山明月意境与陇西山川壮美的幽静古道。', '甘肃', 34.858900, 105.669000, '其他', '["https://img1.baidu.com/it/u=1980215557,3324510384&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=888"]'),
('《秦州杂诗二十首・其十二》', '天水市麦积区麦积山仙人崖遗址', '杜甫', '唐代', '麦积山仙人崖遗址位于甘肃省天水市麦积区，是杜甫《秦州杂诗》"山头南郭寺，水号北流泉"的核心取景地。遗址保留有北魏石窟、唐代寺庙与古碑，仙人崖由三座悬崖组成，崖壁上开凿有石窟与佛龛。杜甫流寓秦州时以深沉的笔触记录了天水的山水人文——"秦州城北寺，出郭少人来"。仙人崖的石窟中保存有北魏至明代的塑像与壁画，虽不如麦积山石窟宏大但更加幽静。悬崖上的古寺凌空而建，殿宇在云雾中若隐若现。此处是感受杜甫秦州诗歌与天水石窟艺术的清幽之地。', '甘肃', 34.570900, 105.890100, '其他', '["https://img1.baidu.com/it/u=2902832210,2989512462&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1521"]'),
('《送元二使安西》', '酒泉市敦煌市阳关镇古董滩遗址', '王维', '唐代', '阳关古董滩遗址位于甘肃省酒泉市敦煌市，是王维《送元二使安西》"西出阳关无故人"的真实发生地。遗址保留有汉代烽燧、古驿道与散落的陶片，"古董滩"因地表散落大量汉唐陶片而得名。阳关是汉代丝绸之路南线的重要关隘，与玉门关并称为河西走廊的"两关"。王维送别友人西出阳关远赴安西都护府，"劝君更尽一杯酒"的深情使阳关成为中国文学中离别的永恒符号。戈壁上的烽燧孤独矗立，远处的沙漠与雪山交相辉映。此处是感受丝绸之路壮美与王维送别诗极致深情的荒漠古关遗址。', '甘肃', 40.142100, 94.661800, '其他', '["https://img2.baidu.com/it/u=4155928768,127979319&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《从军行七首・其四》', '嘉峪关市峪泉镇长城第一墩遗址', '王昌龄', '唐代', '长城第一墩遗址位于甘肃省嘉峪关市峪泉镇，是王昌龄《从军行》"黄沙百战穿金甲，不破楼兰终不还"的描绘地。遗址保留有明代夯土墩台与讨赖河峡谷，长城第一墩是明代万里长城最西端的起点墩台，矗立在讨赖河北岸的悬崖边缘。墩台下方的讨赖河峡谷深达80余米，峡谷两壁如刀削般陡峭。祁连山雪峰在南方连绵起伏，戈壁在北方延伸至天际。王昌龄笔下边关将士的壮烈豪情在此得到最雄浑的地理呈现。此处是万里长城的真正起点，也是感受边塞诗壮美意境与河西走廊雄浑地貌的极致观景地。', '甘肃', 39.773100, 98.289200, '其他', '["https://img2.baidu.com/it/u=3685507605,1810731958&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1069"]'),
('《燕歌行》', '白银市景泰县永泰古城遗址', '高适', '唐代', '永泰古城遗址位于甘肃省白银市景泰县，是高适《燕歌行》创作背景地。遗址保留有明代夯土城墙、城门与民居，永泰古城始建于明万历年间，因城墙形似金龟而又名"永泰龟城"。城墙周长1700余米，墙高12米，设有角楼、炮台与护城河。高适以"战士军前半死生，美人帐下犹歌舞"的悲愤揭示了边关将士与统帅之间的巨大反差。城内至今仍有居民生活，老宅、古井保留了明清原貌。城外是辽阔的戈壁荒漠，风沙弥漫。此处是中国保存最完整的明代军事古城之一，也是感受边塞诗苍凉意境的绝佳之地。', '甘肃', 37.183200, 104.063300, '其他', '["https://img0.baidu.com/it/u=610530970,3158116576&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=800"]'),
('《塞下曲六首・其一》', '张掖市甘州区黑水国遗址', '卢纶', '唐代', '黑水国遗址位于甘肃省张掖市甘州区，是卢纶《塞下曲》"月黑雁飞高，单于夜遁逃"的描绘地。遗址保留有汉代夯土城墙、墓葬群与古垦区，黑水国是汉代张掖郡治所遗址，因黑河（弱水）流经而得名。城墙在戈壁中矗立，风化的夯土层记录了两千年的沧桑。墓葬群中出土了大量汉代陶器、木简与丝织品。卢纶笔下月黑风高的边塞夜战场景在黑水国荒凉的古战场上获得了最真实的想象空间。黑河在城外蜿蜒流过，两岸荒漠与绿洲交替。此处是了解汉代河西走廊城镇建设与边塞诗军事意境的重要考古遗址。', '甘肃', 38.925900, 100.449800, '其他', '["https://img1.baidu.com/it/u=2024375793,356681316&fm=253&fmt=auto&app=138&f=JPEG?w=1067&h=800"]'),
('《出塞二首・其一》', '嘉峪关市石关峡悬臂长城遗址', '王昌龄', '唐代', '悬臂长城遗址位于甘肃省嘉峪关市石关峡，是王昌龄《出塞》"秦时明月汉时关，万里长征人未还"的最佳观景点之一。悬臂长城保留有明代长城与敌楼，长城依山势而建，从戈壁平原直冲山巅，如臂凌空，故名"悬臂"。城墙沿陡峭的山脊蜿蜒而上，最陡处坡度近45度。登上悬臂长城顶端，可俯瞰石关峡全貌——祁连雪山在南，戈壁荒漠在北，长城在群山间蜿蜒消失。王昌龄千年前的边塞豪情在此化为眼前的壮阔景象。此处是嘉峪关景区中最险峻的长城段落，感受明代边防军事工程与边塞诗意境的震撼之地。', '甘肃', 39.773100, 98.289200, '其他', '["https://img0.baidu.com/it/u=1732078550,512922687&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1600"]'),
('《陇西行四首・其二》', '定西市陇西县陇西古城遗址', '陈陶', '唐代', '陇西古城遗址位于甘肃省定西市陇西县，是陈陶《陇西行》"可怜无定河边骨，犹是春闺梦里人"的创作背景地。遗址保留有明代夯土城墙与威远楼，陇西是古丝绸之路重镇，自汉代起即为陇右的政治军事中心。陈陶以极度的悲悯描绘了边关将士战死沙场而家人仍在梦中期盼归来的惨痛——这两句诗被誉为中国古典战争诗中最令人心碎的名句。威远楼始建于北宋，为陇上第一名楼。陇西也是李氏家族的郡望之地，"天下李氏出陇西"。此处是了解丝路重镇军事历史与唐代战争诗悲悯精神的历史文化名城。', '甘肃', 35.002400, 104.634400, '其他', '["https://img2.baidu.com/it/u=477105149,6207229&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=741"]'),
('《送李侍御赴安西》', '酒泉市肃州区酒泉古城钟鼓楼遗址', '高适', '唐代', '酒泉古城钟鼓楼遗址位于甘肃省酒泉市肃州区，是高适送别友人李侍御赴安西都护府的送别地。遗址保留有明代钟楼、古碑与酒泉遗址，高适"功名万里外，心事一杯中"的送别名句在此诞生。酒泉得名于汉武帝时霍去病击败匈奴后将御酒倾入泉中与将士共饮的传说，"酒泉"之名流传至今。钟鼓楼为明代建筑，飞檐翘角，雕梁画栋。城内的酒泉遗址保留有汉代泉池。酒泉是河西走廊的重要城镇，丝路东西方商旅在此交汇。此处是了解河西走廊丝路文化与唐代送别诗豪迈深情的历史名城遗址。', '甘肃', 39.745000, 98.507800, '其他', '["https://img2.baidu.com/it/u=618830414,1970286991&fm=253&fmt=auto&app=138&f=JPEG?w=883&h=800"]'),
('《碛中作》', '酒泉市瓜州县星星峡遗址', '岑参', '唐代', '星星峡遗址位于甘肃省酒泉市瓜州县，是岑参《碛中作》"走马西来欲到天，辞家见月两回圆"的描绘地。遗址保留有清代烽燧、古驿道与摩崖石刻，星星峡是甘肃与新疆的分界处，自古为丝绸之路的咽喉要道。岑参两次出塞经过此地，在茫茫戈壁中写下了对家乡的深切思念——"今夜不知何处宿，平沙万里绝人烟"。星星峡因夜晚繁星满天而得名。烽燧在戈壁中孤独矗立，古驿道消失在无垠的沙漠之中。此处是感受唐代边塞诗人西行之路最孤寂段落与丝路荒漠壮美的极远之地。', '甘肃', 40.520600, 95.782500, '其他', '["https://img0.baidu.com/it/u=2754441763,1915030504&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《胡笳歌送颜真卿使赴河陇》', '武威市凉州区鸠摩罗什寺遗址', '岑参', '唐代', '鸠摩罗什寺遗址位于甘肃省武威市凉州区，是岑参《胡笳歌送颜真卿使赴河陇》的创作背景地。遗址保留有东晋古塔、唐代寺庙与古碑，鸠摩罗什寺是为纪念伟大的佛经翻译家鸠摩罗什而建。鸠摩罗什在凉州居住十七年，翻译了大量佛经，对中国佛教文化产生了深远影响。岑参以"凉秋八月萧关道，北风吹断天山草"的苍凉笔触送别颜真卿赴河陇任职。寺内古塔为中国仅存的鸠摩罗什舌舍利塔，塔身古朴庄严。此处是了解佛教东传历史与唐代边塞诗苍凉意境的重要佛教文化遗存。', '甘肃', 37.928300, 102.637800, '其他', '["https://img0.baidu.com/it/u=2932509179,573594482&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《秦州杂诗二十首・其一》', '天水市秦州区南郭寺遗址', '杜甫', '唐代', '南郭寺遗址位于甘肃省天水市秦州区，是杜甫《秦州杂诗》"满目悲生事，因人作远游"的诞生地。遗址保留有唐代古槐、寺庙与古碑，南郭寺始建于南北朝，因位于天水城南而得名。杜甫于公元759年流寓秦州时多次到访南郭寺，以深沉的笔触记录了自己颠沛流离的命运与天水的山水风光。寺内有一株相传为杜甫亲手所植的古柏，树龄已逾千年。南郭寺依山而建，殿宇层叠，古木参天。寺内的"北流泉"清澈甘甜，终年不涸。此处是了解杜甫秦州时期诗歌创作与天水古寺文化的幽静之地。', '甘肃', 34.580900, 105.724900, '其他', '["https://img0.baidu.com/it/u=2568563179,4077280210&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1419"]'),
('《送刘昱》', '平凉市泾川县泾川古城遗址', '韦应物', '唐代', '泾川古城遗址位于甘肃省平凉市泾川县，是韦应物送别友人途经之地。遗址保留有明代夯土城墙与王母宫石窟，泾川是古丝绸之路重镇，自汉代起即为关中通往陇右的交通要道。韦应物诗中描绘的驿路漫漫与友人离别之情在泾川古道上得到了真实呈现。王母宫石窟开凿于北魏，保存有精美的佛像与壁画。泾河从古城旁蜿蜒流过，两岸黄土高原沟壑纵横。泾川也是"西王母"文化的发源地，"瑶池"传说即源于此。此处是了解丝路驿站文化与西王母民俗信仰的历史文化名城。', '甘肃', 35.332400, 107.367900, '其他', '["https://img0.baidu.com/it/u=2095359757,282760754&fm=253&fmt=auto&app=120&f=JPEG?w=1200&h=800"]'),
('《题金城临河驿楼》', '兰州市城关区白塔山遗址', '岑参', '唐代', '白塔山遗址位于甘肃省兰州市城关区，是岑参《题金城临河驿楼》"古戍依重险，高楼见五凉"的描绘地。遗址保留有明代白塔、寺庙与古碑，白塔山因山巅有白塔寺而得名。白塔始建于元代，为纪念一位西藏萨迦派喇嘛而建，塔身七级八面，洁白如玉。岑参以金城（兰州古称）为背景描绘了黄河边军事重镇的雄伟景象。登上白塔山可俯瞰兰州全城与黄河穿城的壮阔景象。中山桥横跨黄河两岸，是兰州的标志性景观。此处是俯瞰黄河穿城的最佳观景地，也是感受岑参边塞诗金城意境的历史文化名山。', '甘肃', 36.061100, 103.834300, '其他', '["https://img0.baidu.com/it/u=951991762,3092737969&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1200"]'),
('《凉州馆中与诸判官夜集》', '武威市凉州区文庙遗址', '岑参', '唐代', '凉州文庙遗址位于甘肃省武威市凉州区，是岑参《凉州馆中与诸判官夜集》"弯弯月出挂城头，城头月出照凉州"的创作地。遗址保留有明代建筑、古碑与西夏碑，凉州文庙始建于明代，是河西走廊保存最完整的文庙建筑群。岑参在凉州任职期间与同僚夜宴赋诗，"花门楼前见秋草，岂能贫贱相看老"的豪放映射了边塞文人的壮志。文庙中收藏的"西夏碑"是全国唯一的西夏文与汉文双语碑刻，极为珍贵。大成殿建筑精美，孔子像庄严。此处是了解河西走廊儒学文化与唐代边塞诗人凉州生活的重要文化遗存。', '甘肃', 37.928300, 102.637800, '其他', '["https://img2.baidu.com/it/u=1794837862,128977120&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《塞下曲》', '张掖市山丹县焉支山遗址', '卢纶', '唐代', '焉支山遗址位于甘肃省张掖市山丹县，是卢纶《塞下曲》的描绘地。遗址保留有唐代寺庙、古驿道与摩崖石刻，焉支山是河西走廊中段的重要山脉，"失我焉支山，令我妇女无颜色"的匈奴民歌使焉支山闻名天下。焉支山盛产胭脂草，匈奴妇女用其制作化妆品，"胭脂"一词即由"焉支"音转而来。霍去病击败匈奴后在焉支山举行了历史上最盛大的军事庆典。山上草原辽阔，夏季野花遍地。唐代隋炀帝也曾在焉支山召开万国博览会。此处是了解汉匈战争历史与河西走廊草原文化的壮美历史名山。', '甘肃', 38.784900, 101.088100, '其他', '["https://img0.baidu.com/it/u=3528605406,2663813530&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《从军行》', '酒泉市金塔县肩水金关遗址', '杨炯', '唐代', '肩水金关遗址位于甘肃省酒泉市金塔县，是杨炯《从军行》"宁为百夫长，胜作一书生"的创作背景地。遗址保留有汉代夯土关隘、烽燧与古驿道，肩水金关是汉代河西走廊最重要的军事关隘之一，也是丝绸之路上的重要交通检查站。遗址中出土了大量汉代简牍——"肩水金关汉简"记录了汉代边防军事、驿传制度与日常生活。杨炯以初唐知识分子投笔从戎的豪情壮志呼应了汉代边关将士的英勇。关隘夯土在戈壁中风化斑驳。此处是了解汉代丝路军事关隘制度与初唐边塞诗豪迈精神的重要考古遗址。', '甘肃', 39.983500, 98.900600, '其他', '["https://img1.baidu.com/it/u=749031594,401055100&fm=253&fmt=auto&app=138&f=JPEG?w=1201&h=800"]'),
('《度破讷沙二首・其二》', '酒泉市敦煌市鸣沙山北麓遗址', '李益', '唐代', '鸣沙山北麓遗址位于甘肃省酒泉市敦煌市，是李益《度破讷沙》的描绘地。遗址保留有汉代烽燧、古驿道与壮美的沙漠风光，鸣沙山北麓是敦煌古城通往西域的出发点。李益以"破讷沙头雁正飞，鸊鹈泉上战初归"的笔触描绘了唐代边关将士战后归来的场景。与鸣沙山月牙泉核心区不同，北麓游客极少，保留了最原始的大漠风光。沙丘起伏如波涛，烽燧在沙漠中孤独矗立。日出时分金色的沙漠与天边的曙光交相辉映，壮美非常。此处是感受敦煌大漠原始风光与唐代边塞诗军旅意境的清幽沙漠观景地。', '甘肃', 40.142100, 94.661800, '其他', '["https://img2.baidu.com/it/u=41070390,4202874896&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《夜上受降城闻笛》', '白银市靖远县受降城遗址', '李益', '唐代', '受降城遗址位于甘肃省白银市靖远县，是李益《夜上受降城闻笛》"回乐烽前沙似雪，受降城外月如霜"的诞生地。遗址保留有唐代夯土城墙、烽燧与古碑，受降城是唐代为接受突厥降部而建的军事城堡。李益在月明之夜登上城楼，听到远方传来的笛声，"不知何处吹芦管，一夜征人尽望乡"的深切思乡之情感人至深。城墙夯土在月光下呈银白色，恰如"沙似雪""月如霜"的诗中意境。城外戈壁辽阔，黄河在远处蜿蜒。此处是感受唐代边塞诗中最动人的思乡意境与唐代军事城堡的荒凉古战场遗址。', '甘肃', 36.561600, 104.686200, '其他', '["https://img0.baidu.com/it/u=2987777319,4004646805&fm=253&fmt=auto&app=138&f=JPEG?w=889&h=500"]'),
('《陇西行》', '定西市临洮县秦长城遗址', '王维', '唐代', '秦长城遗址位于甘肃省定西市临洮县，是王维《陇西行》的描绘地。遗址保留有秦代夯土城墙、烽燧与古驿道，临洮秦长城是秦始皇"万里长城"的西端起点，比嘉峪关明长城更为古老。城墙夯土层中的秦代夯杵痕迹清晰可辨，展示了两千两百年前的筑城技术。秦长城沿洮河东岸的山脊蜿蜒延伸，气势雄浑。蒙恬将军曾率三十万大军在此驻守，"却匈奴七百余里"。临洮也是貂蝉故里与马家窑彩陶文化发源地。此处是了解秦代万里长城起源与唐代边塞诗历史背景的国宝级长城遗址。', '甘肃', 35.376000, 103.861400, '其他', '["https://img0.baidu.com/it/u=71650857,3259346805&fm=253&fmt=auto&app=138&f=JPEG?w=751&h=500"]'),
('《送狄宗亨》', '平凉市崆峒山香山寺遗址', '王昌龄', '唐代', '崆峒山香山寺遗址位于甘肃省平凉市，是王昌龄送别诗的描绘地。遗址保留有明代寺庙、古碑与摩崖石刻，崆峒山是道教第一山，传说黄帝曾在此向广成子问道。香山寺位于崆峒山后峰，远离核心景区的喧闹，保留了最原始的宗教氛围。秋日山中红叶漫山，层林尽染，正如"秋在万山深处红"的诗意。寺庙依山而建，殿宇隐于古柏林中。崆峒山融道教、佛教于一山，是中国最重要的宗教名山之一。崆峒武术与少林、武当齐名。此处是感受崆峒山道教文化与唐代送别诗秋日山林意境的幽静古刹。', '甘肃', 35.542600, 106.665300, '其他', '["https://img2.baidu.com/it/u=1591893261,3334436221&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1422"]'),
('《题麦积山天堂》', '天水市麦积区麦积山石窟天堂洞遗址', '王仁裕', '五代', '麦积山石窟天堂洞遗址位于甘肃省天水市麦积区，是五代诗人王仁裕《题麦积山天堂》"蹑尽悬空万仞梯，等闲身共白云齐"的描绘地。天堂洞位于麦积山石窟最高处，保留有北魏石刻佛像与壁画，需攀登悬空栈道方可到达。麦积山石窟始建于后秦，历经一千六百余年营建，现存窟龛221个，泥塑石雕7800余尊，被誉为"东方雕塑陈列馆"。麦积山如农家麦垛矗立于秦岭山林之中。天堂洞中的佛像面容安详，衣褶飘逸。此处是感受中国石窟艺术巅峰与五代文人登临诗意的悬崖上的艺术殿堂。', '甘肃', 34.570900, 105.890100, '其他', '["https://img1.baidu.com/it/u=3845815669,1348916548&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1422"]'),
('《游崆峒山》', '平凉市崆峒山棋盘岭遗址', '杜甫', '唐代', '崆峒山棋盘岭遗址位于甘肃省平凉市，是杜甫《游崆峒山》"崆峒西极昆仑丘，黄帝问道广成子"的描绘地。棋盘岭保留有明代古亭、古碑与摩崖石刻，传说广成子在此与黄帝下棋论道。杜甫在安史之乱后西行途经崆峒山，以沉郁的笔触描绘了崆峒山的雄伟与黄帝问道的远古传说。棋盘岭上奇石如棋盘，古柏苍翠。崆峒山群峰叠嶂，悬崖峭壁间道观与寺庙星罗棋布。"崆峒"之名源自道教"空洞无为"的哲学理念。此处是了解黄帝问道文化与杜甫晚年西行诗歌创作的道教圣山之地。', '甘肃', 35.542600, 106.665300, '其他', '["https://img1.baidu.com/it/u=3397849731,1658205828&fm=253&fmt=auto&app=138&f=JPEG?w=667&h=500"]'),
('《敦煌》', '酒泉市敦煌市西千佛洞遗址', '季羡林', '现代', '西千佛洞遗址位于甘肃省酒泉市敦煌市，是季羡林"敦煌文化的灿烂，是世界文化的瑰宝"的描绘地。遗址保留有北魏至元代的石窟、壁画与佛像，西千佛洞开凿于党河河谷西岸的悬崖上，是敦煌石窟群的重要组成部分。现存洞窟22个，壁画面积约800平方米。与莫高窟相比，西千佛洞规模较小但保存状况更好，游客极少。季羡林作为敦煌学大家，毕生致力于敦煌文化的研究与保护。石窟中的北魏壁画线条流畅，色彩鲜艳。此处是近距离感受敦煌石窟艺术真谛的最清幽小众石窟。', '甘肃', 40.142100, 94.661800, '其他', '["https://img1.baidu.com/it/u=3454842770,1680424348&fm=253&fmt=auto&app=138&f=JPEG?w=775&h=500"]'),
('《祁连山》', '张掖市肃南县祁连山草原康乐草原遗址', '海子', '现代', '康乐草原遗址位于甘肃省张掖市肃南县祁连山腹地，是海子诗歌中雪山与草原意象的现代演绎地。康乐草原保留有原始草原、雪山与藏族风情，海拔约3000米，四周祁连山雪峰环绕。草原辽阔无际，夏季野花遍地——金露梅、银露梅、紫云英在风中摇曳。裕固族牧民的帐篷散落在草原上，牛羊成群。海子"面朝大海，春暖花开"的诗意在这片高原草原上获得了不同的呈现——面朝雪山，百花盛开。祁连山融雪汇成溪流在草原间蜿蜒。此处是感受祁连山草原壮美与现代诗歌自然意象的高海拔文学体验地。', '甘肃', 38.836600, 99.615600, '其他', '["https://img2.baidu.com/it/u=3732734085,2868294747&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《大漠祭》', '武威市古浪县黄花滩村', '雪漠', '现代', '黄花滩村位于甘肃省武威市古浪县，是雪漠《大漠祭》中老顺一家生活的原型地。村庄保留有清末民初的民居、老磨坊与壮阔的沙漠风光，黄花滩地处腾格里沙漠边缘，是中国荒漠化治理的重要区域。雪漠以父辈的真实生活为素材，描绘了西北农民在恶劣自然环境中与天斗与地斗的坚韧生存。黄沙漫漫，风起时沙尘蔽日。村中的老磨坊、土墙院落记录着几代人与沙漠抗争的历史。近年来的生态移民工程使大量村民迁至新区，老村逐渐归于沉寂。此处是了解西北荒漠农民生存史与雪漠乡土文学的真实原生态文学现场。', '甘肃', 37.470300, 102.897500, '其他', '["https://img0.baidu.com/it/u=994493970,349562890&fm=253&fmt=auto&app=120&f=JPEG?w=890&h=500"]'),
('《猎原》', '武威市凉州区长城乡沙漠公园遗址', '雪漠', '现代', '长城乡沙漠公园遗址位于甘肃省武威市凉州区，是雪漠《猎原》中孟八爷等人狩猎的地方。遗址保留有原始沙漠、胡杨林与古驿道，腾格里沙漠在此展现出荒凉而壮美的面貌。雪漠以老猎人孟八爷的狩猎生活为主线，描绘了西北农民在沙漠边缘与自然抗争的苦难与尊严。胡杨林在秋日金黄如火，"生而不死一千年，死而不倒一千年，倒而不朽一千年"的传说使胡杨成为坚韧生命力的象征。沙漠中的古驿道消失在风沙之中。此处是感受腾格里沙漠原始风光与雪漠西北乡土文学中人与自然抗争精神的荒凉之地。', '甘肃', 37.928300, 102.637800, '其他', '["https://img0.baidu.com/it/u=3106244327,1895844289&fm=253&fmt=auto&app=120&f=JPEG?w=664&h=500"]'),
('《白虎关》', '武威市凉州区黄羊镇遗址', '雪漠', '现代', '黄羊镇遗址位于甘肃省武威市凉州区，是雪漠《白虎关》中莹儿和灵官生活的地方。遗址保留有清末民初的民居、老商铺与农田，黄羊镇是凉州区南部的农业小镇，祁连山雪水滋润着这片绿洲。雪漠以莹儿的命运为主线，描绘了西北农村妇女在传统与现代之间的挣扎与觉醒。镇上的老商铺保留着民国时期的格局，土墙院落中的磨坊、水井记录着农耕生活的艰辛。农田在祁连山脚下铺展，小麦与玉米在风中摇曳。此处是了解河西走廊绿洲农业文化与雪漠"大漠三部曲"文学世界的西北乡村原生态空间。', '甘肃', 37.928300, 102.637800, '其他', '["https://img2.baidu.com/it/u=1733844511,2041927792&fm=253&fmt=auto&app=138&f=JPEG?w=1067&h=800"]'),
('《敦煌本纪》', '酒泉市敦煌市三危山老君堂遗址', '叶舟', '现代', '三危山老君堂遗址位于甘肃省酒泉市敦煌市，是叶舟《敦煌本纪》中敦煌文化的发源地之一。遗址保留有唐代寺庙、摩崖石刻与古碑，三危山是敦煌的圣山——"三危"之名见于《尚书》"窜三苗于三危"。老君堂位于三危山主峰，是道教圣地。叶舟以清末民初的敦煌为背景，描绘了索、沈两个家族守护敦煌文化遗产的壮烈故事。三危山峰峦叠嶂，山势险峻，莫高窟即开凿于三危山对面的鸣沙山断崖上。远眺三危山，三座山峰并列如三把利剑直刺苍穹。此处是了解敦煌文化根脉与叶舟史诗文学的宗教圣山。', '甘肃', 40.142100, 94.661800, '其他', '["https://img1.baidu.com/it/u=1361721501,4008730809&fm=253&fmt=auto&app=138&f=JPEG?w=686&h=500"]'),
('《敦煌本纪》', '酒泉市敦煌市月牙泉镇雷音寺遗址', '叶舟', '现代', '雷音寺遗址位于甘肃省酒泉市敦煌市月牙泉镇，是叶舟《敦煌本纪》中佛教文化的核心场景地。遗址保留有唐代寺庙、古碑与佛像，雷音寺始建于西晋，是敦煌最古老的佛教寺院之一。"雷音"之名源自《西游记》中如来佛祖居住的大雷音寺。叶舟以敦煌的佛教文化为线索，描绘了信仰与文明在丝路上的传承。寺院依沙丘而建，殿宇庄严，佛像金碧辉煌。鸣沙山在寺院背后高耸，月牙泉在不远处碧波荡漾。此处是了解敦煌佛教文化传承与叶舟《敦煌本纪》文学场景的清幽古刹。', '甘肃', 40.142100, 94.661800, '其他', '["https://img2.baidu.com/it/u=4010787873,1703190407&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=736"]'),
('《黄河远上》', '兰州市城关区黄河铁桥中山桥遗址', '雷达', '现代', '黄河铁桥中山桥遗址位于甘肃省兰州市城关区，是雷达《黄河远上》中兰州的标志性建筑。中山桥始建于清光绪三十四年，由德国人设计建造，是黄河上第一座近代桥梁，被誉为"天下黄河第一桥"。雷达以深情的笔触描绘了中山桥与黄河在兰州城中交织的壮阔景象。铁桥横跨黄河南北两岸，桥身钢架结构在阳光下闪烁。黄河水在桥下奔涌，浊浪翻滚。北岸白塔山苍翠，南岸金城关雄踞。夜晚中山桥灯火辉煌，倒映在黄河中如金龙卧波。此处是感受兰州黄河文化与近代桥梁工程的地标性历史建筑。', '甘肃', 36.061100, 103.834300, '其他', '["https://img0.baidu.com/it/u=4047529157,3895420530&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《西路军魂》', '张掖市高台县西路军纪念馆遗址', '黎汝清', '现代', '高台西路军纪念馆遗址位于甘肃省张掖市高台县，是黎汝清《西路军魂》的核心背景地。遗址保留有革命旧址、烈士墓与纪念馆，1937年红军西路军在高台与国民党马步芳部队展开了惨烈的攻防战，军长董振堂等三千余名将士壮烈牺牲。黎汝清以西路军高台血战为背景，描绘了红军将士在孤立无援中浴血奋战的悲壮。纪念馆中陈列有烈士遗物、战斗图片与历史文献。烈士墓园庄严肃穆，松柏苍翠。祁连山雪峰在远处沉默矗立。此处是了解红军西路军英勇事迹与中国革命军事文学的重要红色纪念地。', '甘肃', 39.378200, 99.819400, '其他', '["https://img1.baidu.com/it/u=468195886,956968414&fm=253&fmt=auto&app=138&f=JPEG?w=1067&h=800"]'),
('《保卫延安》', '庆阳市华池县南梁革命根据地遗址', '杜鹏程', '现代', '南梁革命根据地遗址位于甘肃省庆阳市华池县，是杜鹏程《保卫延安》的重要背景地。遗址保留有革命旧址、老窑洞与南梁纪念馆，南梁是二十世纪三十年代刘志丹、谢子长等创建的陕甘边革命根据地的中心。1934年陕甘边区苏维埃政府在此成立，被誉为"两点一存"——全国革命低潮时期硕果仅存的革命根据地之一。窑洞中的指挥部、军械所保留原貌。陇东黄土高原沟壑纵横，地势险要。此处是了解陕甘边革命根据地创建史与中国革命文学的重要红色摇篮。', '甘肃', 36.461100, 107.989100, '其他', '["https://img2.baidu.com/it/u=918063746,1484829993&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《西游记》', '张掖市临泽县丹霞地质公园冰沟景区', '吴承恩', '明代', '冰沟丹霞景区位于甘肃省张掖市临泽县，是吴承恩《西游记》中火焰山的原型地之一。景区保留有独特的丹霞地貌、古驿道与摩崖石刻，冰沟丹霞以奇特的砂岩柱状地貌著称——形如宫殿、城堡、石柱的红色砂岩在荒漠中矗立如鬼斧神工。吴承恩笔下"火焰山"的炽热景象在这片赤红色的丹霞地貌中获得了最震撼的现实呈现。与七彩丹霞不同，冰沟丹霞以立体造型取胜，"卢浮魅影""神驼迎宾"等景观形态逼真。日出日落时红色砂岩在光影中变幻莫测。此处是感受大自然鬼斧神工与古典名著奇幻意境的地质奇观。', '甘肃', 39.152500, 100.164200, '其他', '["https://img2.baidu.com/it/u=697290275,3509626317&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1044"]'),
('《西游记》', '酒泉市瓜州县锁阳城遗址', '吴承恩', '明代', '锁阳城遗址（西游记段）位于甘肃省酒泉市瓜州县，是吴承恩《西游记》中唐僧师徒西行经过的地方。锁阳城保留有唐代夯土城墙、寺庙遗址与古驿道，是世界文化遗产"丝绸之路"的重要组成部分。玄奘法师西行取经时确实经过瓜州（唐代称瓜州），在此获得老胡人指引穿越八百里莫贺延碛沙漠。吴承恩以玄奘真实经历为蓝本创作了《西游记》。锁阳城的夯土城墙高大雄伟，城外戈壁荒凉辽阔。塔尔寺遗址中的唐代佛塔基座保存完好。此处是追溯玄奘真实西行路线与《西游记》文学源头的丝路古城。', '甘肃', 40.520600, 95.782500, '其他', '["https://img2.baidu.com/it/u=3428096243,1565296533&fm=253&fmt=auto&app=138&f=JPEG?w=1200&h=800"]'),
('《三国演义》', '天水市秦安县街亭古战场遗址', '罗贯中', '明代', '街亭古战场遗址位于甘肃省天水市秦安县，是罗贯中《三国演义》中"马谡失街亭"的发生地。遗址保留有汉代夯土城墙、古战场遗址与古碑，街亭是陇山古道的咽喉要地，历来为军事必争之地。诸葛亮第一次北伐时派马谡守街亭，马谡违令上山扎营被张郃断水围攻，蜀军大败——"挥泪斩马谡"的故事成为千古经典。街亭地势险要，群山环绕，关隘遗址的夯土墙体依稀可辨。周边为秦安县的桃园，春日桃花盛开。此处是了解三国军事历史与《三国演义》经典故事的重要古战场遗址。', '甘肃', 34.858900, 105.669000, '其他', '["https://img0.baidu.com/it/u=2254190885,2443798492&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《三国演义》', '定西市陇西县姜维故里遗址', '罗贯中', '明代', '姜维故里遗址位于甘肃省定西市陇西县，是罗贯中《三国演义》中姜维的出生地。遗址保留有汉代姜维墓、古碑与姜维纪念馆，姜维是三国时期蜀汉名将，字伯约，天水冀县人。姜维原为曹魏天水郡中郎将，诸葛亮第一次北伐时投降蜀汉，后继承诸葛亮遗志九伐中原。《三国演义》中姜维"胆大如斗"的描写使其成为忠勇的象征。故里中的姜维墓古柏环绕，庄严肃穆。纪念馆展示了姜维的生平事迹与三国历史。陇西自古为"天下李氏"的郡望之地。此处是了解三国名将姜维与陇西历史文化的重要人文遗址。', '甘肃', 35.002400, 104.634400, '其他', '["https://img0.baidu.com/it/u=2376878538,1444978670&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《水经注・河水注》', '临夏州永靖县炳灵寺石窟遗址', '郦道元', '北魏', '炳灵寺石窟遗址位于甘肃省临夏州永靖县，是郦道元《水经注・河水注》中重点记载的景点。遗址保留有北魏至明代的石窟、壁画与佛像，炳灵寺石窟开凿于黄河北岸的小积石山悬崖上，始建于西秦建弘元年，已有一千六百余年历史。郦道元以严谨的地理学笔法记录了炳灵寺的位置与地貌特征。石窟中的第169窟保存有中国最早的有纪年题记的佛教壁画。唐代大佛高达27米，气势恢宏。刘家峡水库碧波万顷，需乘船方能抵达石窟。此处是了解中国早期佛教艺术与郦道元地理文献的世界级石窟宝库。', '甘肃', 35.938100, 103.319100, '其他', '["https://img0.baidu.com/it/u=2094248701,3564502750&fm=253&fmt=auto&app=138&f=JPEG?w=1067&h=800"]'),
('《大唐西域记》', '酒泉市瓜州县锁阳城遗址', '玄奘', '唐代', '锁阳城遗址（大唐西域记段）位于甘肃省酒泉市瓜州县，是玄奘《大唐西域记》中记载的西行途经之地。锁阳城在唐代为瓜州郡治所，玄奘法师在此停留数日后偷渡出关西行取经。《大唐西域记》详细记录了玄奘从瓜州穿越八百里莫贺延碛沙漠到达伊吾（今哈密）的艰难历程——"上无飞鸟，下无走兽，复无水草"。锁阳城夯土城墙保存完好，是丝绸之路上保存最完整的唐代城址之一。城外戈壁荒漠与远处的雪山形成鲜明对比。此处是追溯玄奘真实西行路线的世界文化遗产级丝路古城。', '甘肃', 40.520600, 95.782500, '其他', '["https://img2.baidu.com/it/u=3428096243,1565296533&fm=253&fmt=auto&app=138&f=JPEG?w=1200&h=800"]'),
('《游崆峒山记》', '平凉市崆峒山雷声峰遗址', '袁宏道', '明代', '崆峒山雷声峰遗址位于甘肃省平凉市，是袁宏道《游崆峒山记》"崆峒山，天下之险也"的描绘地。雷声峰是崆峒山的核心景点之一，保留有明代寺庙、古碑与摩崖石刻。雷声峰因雷雨时雷声在峰间回荡如雷鼓而得名。袁宏道以性灵派独特的审美眼光描绘了崆峒山的险峻奇绝——峰峦如剑，悬崖如壁。雷声峰上的道观凌空而建，殿宇在云雾中若隐若现。崆峒山是中国道教第一山，"广成子修道之地"。山中古木参天，泉水淙淙。此处是感受崆峒山天险与明代性灵文学审美的道教圣山核心景观。', '甘肃', 35.542600, 106.665300, '其他', '["https://img0.baidu.com/it/u=3106804285,1768908856&fm=253&fmt=auto&app=138&f=JPEG?w=1067&h=800"]'),
('《麦积山石窟记》', '天水市麦积区麦积山石窟散花楼遗址', '冯国瑞', '现代', '麦积山石窟散花楼遗址位于甘肃省天水市麦积区，是冯国瑞"麦积山石窟，中国古代雕塑艺术的宝库"的描绘地。散花楼保留有北魏至隋代的精美泥塑与壁画，是麦积山石窟最具代表性的洞窟之一。冯国瑞是二十世纪三十年代重新发现麦积山石窟的学者，其著作使这座被遗忘的石窟宝库重新引起世界关注。散花楼中的佛像面容安详，衣褶飘逸，"东方微笑"的美誉由此而来。麦积山如农家麦垛矗立于秦岭山林之中，悬空栈道在绝壁上蜿蜒。此处是感受中国泥塑艺术巅峰与学者探索精神的世界文化遗产。', '甘肃', 34.570900, 105.890100, '其他', '["https://img2.baidu.com/it/u=1774954144,341279325&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=890"]'),
('《祁连山的回声》', '张掖市肃南县马蹄寺石窟遗址', '朱仲玉', '现代', '马蹄寺石窟遗址位于甘肃省张掖市肃南县，是朱仲玉《祁连山的回声》的核心背景地。遗址保留有北魏至元代的石窟、壁画与佛像，马蹄寺因传说中天马在此留下蹄印而得名。石窟开凿于祁连山北麓的悬崖上，"三十三天"洞窟沿悬崖开凿如蜂巢般层层叠叠，需攀爬陡峭的岩体内通道方可到达最高处。朱仲玉以祁连山为背景描绘了河西走廊的历史文化。石窟周边草原辽阔，祁连山雪峰近在眼前。裕固族牧民的帐篷散落在草原上。此处是了解祁连山石窟艺术与河西走廊多民族文化的壮美之地。', '甘肃', 38.836600, 99.615600, '其他', '["https://img1.baidu.com/it/u=4194120634,2804757472&fm=253&fmt=auto&app=120&f=JPEG?w=800&h=1044"]'),
('《河西走廊》', '武威市凉州区鸠摩罗什寺遗址', 'CCTV 纪录片', '现代', '鸠摩罗什寺遗址（河西走廊段）位于甘肃省武威市凉州区，是CCTV纪录片《河西走廊》中重点记载的佛教文化遗址。鸠摩罗什寺保留有东晋古塔、唐代寺庙与古碑，是为纪念伟大的佛经翻译家鸠摩罗什而建。纪录片《河西走廊》以河西走廊的历史变迁为主线，生动展现了鸠摩罗什在凉州十七年翻译佛经的伟大贡献。鸠摩罗什翻译的《金刚经》《法华经》《阿弥陀经》深刻影响了中国佛教文化的发展。寺内的鸠摩罗什舌舍利塔是中国仅存的此类佛塔。此处是了解佛教东传与河西走廊文明史的重要佛教圣地。', '甘肃', 37.928300, 102.637800, '其他', '["https://img0.baidu.com/it/u=2932509179,573594482&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《河西走廊》', '酒泉市敦煌市玉门关遗址', 'CCTV 纪录片', '现代', '玉门关遗址位于甘肃省酒泉市敦煌市，是CCTV纪录片《河西走廊》中丝绸之路的重要关隘。遗址保留有汉代夯土关隘、烽燧与古驿道，玉门关始建于西汉，因西域和田玉经此输入中原而得名。"羌笛何须怨杨柳，春风不度玉门关"的名句使玉门关成为中国文学中最著名的边关符号。关城夯土方形，边长约24米，墙高约10米，保存基本完好。关城周边是辽阔的戈壁荒漠，烽燧在天际线上孤独矗立。玉门关是汉代丝绸之路北线的重要关隘，与阳关并称"两关"。此处是感受丝路古关苍凉壮美的世界文化遗产。', '甘肃', 40.142100, 94.661800, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/a/af/Dunhuang.yumenguan.jpg/1280px-Dunhuang.yumenguan.jpg"]'),
('《走河西》', '张掖市甘州区大佛寺遗址', '雷达', '现代', '大佛寺遗址位于甘肃省张掖市甘州区，是雷达《走河西》中重点记载的景点。大佛寺保留有西夏卧佛、明代寺庙与古碑，始建于西夏永安元年，因寺内供奉有国内最大的室内卧佛而闻名。卧佛身长34.5米，肩宽7.5米，金装彩绘，安详平和。雷达以深情的笔触描绘了河西走廊的文化瑰宝。大佛寺还收藏有明代金泥书《大般若波罗蜜多经》等珍贵文物。大殿建筑宏伟壮观，殿内壁画色彩鲜艳。马可・波罗曾到访此寺并在游记中记载。此处是了解西夏佛教文化与河西走廊艺术遗存的国宝级古寺。', '甘肃', 38.925900, 100.449800, '其他', '["https://img2.baidu.com/it/u=4239073385,577832969&fm=253&fmt=auto&app=138&f=JPEG?w=667&h=500"]'),
('《甘肃行》', '兰州市城关区五泉山遗址', '茅盾', '现代', '五泉山遗址位于甘肃省兰州市城关区，是茅盾《甘肃行》中重点描绘的景点。遗址保留有汉代古泉、明代寺庙与古碑，五泉山因山中有甘露泉、掬月泉、摸子泉、惠泉、蒙泉五眼名泉而得名。传说霍去病征战西域途经此地，马鞭击地涌出五泉。茅盾以文学家的敏锐观察记录了兰州的山水人文风貌。五泉山依皋兰山北坡而建，古建筑群层层叠叠。泉水清澈甘甜，四季不涸。山中古柏苍翠，寺庙梵音袅袅。此处是了解兰州山水文化与茅盾西北纪行文学的城市中的清幽名山。', '甘肃', 36.061100, 103.834300, '其他', '["https://img0.baidu.com/it/u=3063018685,1704427410&fm=253&fmt=auto&app=138&f=JPEG?w=692&h=500"]');
INSERT INTO works (title, scenic_spot, author, dynasty, description, province, latitude, longitude, category, images) VALUES
('《兰州赋》', '兰州市城关区黄河母亲雕塑遗址', '余秋雨', '现代', '黄河母亲雕塑遗址位于甘肃省兰州市城关区，是余秋雨《兰州赋》中重点描绘的景点。雕塑保留有现代艺术造型与黄河风光，"黄河母亲"雕塑由甘肃著名雕塑家何鄂于1986年创作，长6米、宽2.2米、高2.6米，母亲安详慈爱，婴儿天真活泼，象征中华民族生生不息的伟大力量。余秋雨以深沉的文化叙事赞颂了黄河作为中华民族母亲河的伟大。雕塑位于黄河南岸，面朝黄河，背靠皋兰山。黄河水在雕塑前奔涌而过，气势磅礴。此处是感受黄河文明精神内涵与兰州城市文化的标志性公共艺术空间。', '甘肃', 36.061100, 103.834300, '其他', '["https://img0.baidu.com/it/u=3335318307,114772467&fm=253&fmt=auto&app=138&f=JPEG?w=670&h=500"]'),
('《文化苦旅・莫高窟》', '酒泉市敦煌市莫高窟藏经洞遗址', '余秋雨', '现代', '莫高窟藏经洞遗址位于甘肃省酒泉市敦煌市，是余秋雨《文化苦旅・莫高窟》的核心场景地。藏经洞即莫高窟第17窟，1900年道士王圆箓偶然发现此洞中封存有五万余件唐至宋代的经卷、文书与绢画。余秋雨以沉痛的笔触描述了这批稀世珍宝被斯坦因、伯希和等外国探险家以极低价格掠走的悲惨历史——"一个古老民族的伤口在滴血"。藏经洞面积仅数平方米，却是二十世纪最伟大的考古发现之一。"敦煌学"由此诞生，成为国际显学。此处是了解敦煌文化劫难与余秋雨文化苦旅的中国文化史上最痛心的角落。', '甘肃', 40.142100, 94.661800, '其他', '[]'),
('《文化苦旅・道士塔》', '酒泉市敦煌市莫高窟道士塔遗址', '余秋雨', '现代', '莫高窟道士塔遗址位于甘肃省酒泉市敦煌市，是余秋雨《文化苦旅・道士塔》的核心场景地。道士塔是王圆箓的墓塔，保留有清代塔身与古碑。余秋雨在文中写道："看莫高窟，不是看死了一千年的标本，而是看活了一千年的生命"。王圆箓是藏经洞的发现者，也是敦煌文物外流的直接经手人。余秋雨以"历史的误会"为切入点，反思了中国近代文化遗产保护的惨痛教训。道士塔低矮朴素，与莫高窟的辉煌形成鲜明对比。此处是理解中国近代文化命运与余秋雨文化反思文学最深刻的精神叩问之地。', '甘肃', 40.142100, 94.661800, '其他', '["https://img1.baidu.com/it/u=2488123203,572137177&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《红旗谱》', '庆阳市华池县南梁革命根据地遗址', '梁斌', '现代', '南梁革命根据地遗址（红旗谱段）位于甘肃省庆阳市华池县，是梁斌《红旗谱》中革命故事的背景地之一。遗址保留有革命旧址、老窑洞与纪念馆，南梁是陕甘边革命根据地的核心区域。梁斌以冀中平原农民革命为主线，而南梁作为全国革命根据地的重要组成部分，其革命精神与《红旗谱》中"朱老忠"的抗争精神一脉相承。窑洞中的革命遗物记录着先辈的艰苦奋斗。陇东黄土高原的沟壑在夕阳下呈现出苍凉壮美。此处是了解陕甘边革命历史与中国革命文学精神传承的红色教育基地。', '甘肃', 36.461100, 107.989100, '其他', '["https://img2.baidu.com/it/u=918063746,1484829993&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《敌后武工队》', '庆阳市华池县南梁革命根据地遗址', '冯志', '现代', '南梁革命根据地遗址（敌后武工队段）位于甘肃省庆阳市华池县，是冯志《敌后武工队》中抗日故事的背景地之一。遗址保留有革命旧址、老窑洞与纪念馆，南梁在抗日战争时期是陕甘宁边区的重要组成部分。冯志以冀中平原抗日武工队为原型，描绘了敌后抗日军民深入敌占区进行破坏与瓦解的英勇故事。南梁的革命传统与敌后武工队的战斗精神息息相通。窑洞中的军事地图、通信设备保留原貌。黄土高原的沟壑地形为游击战提供了天然屏障。此处是了解抗日根据地建设与敌后游击战文学的重要红色纪念地。', '甘肃', 36.461100, 107.989100, '其他', '["https://img2.baidu.com/it/u=918063746,1484829993&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《平凡的世界》', '平凉市静宁县界石铺红军长征纪念馆遗址', '路遥', '现代', '界石铺红军长征纪念馆遗址位于甘肃省平凉市静宁县，是路遥《平凡的世界》革命历史背景的延伸地。遗址保留有革命旧址、老窑洞与纪念馆，1935年10月红一方面军长征途经界石铺，毛泽东在此发表了重要讲话。界石铺是红军长征途中陕甘交界的关键节点。路遥在《平凡的世界》中以陕北黄土高原为背景，融入了革命历史对普通人命运的深远影响。纪念馆中陈列有红军遗物与历史照片。陇东高原沟壑纵横，古道蜿蜒。此处是了解红军长征陇东段历史与路遥文学中革命精神传承的红色文化遗存。', '甘肃', 35.516600, 105.730000, '其他', '["https://img2.baidu.com/it/u=2431803576,4167594933&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《人生》', '定西市通渭县榜罗镇会议遗址', '路遥', '现代', '榜罗镇会议遗址位于甘肃省定西市通渭县，是路遥《人生》革命历史背景的关联地。遗址保留有革命旧址、老窑洞与纪念馆，1935年9月红军长征途中在榜罗镇召开了重要的政治局常委会议，正式决定以陕北作为领导中国革命的大本营。路遥在作品中深刻融入了陕甘地区的革命传统对普通人精神世界的影响。会议旧址中的长桌、煤油灯保留原貌。通渭县自古以文化著称，"家中无字画，不是通渭人"。此处是了解红军长征关键决策与陕甘文化传统的重要革命历史遗址。', '甘肃', 35.210700, 105.242200, '其他', '["https://img1.baidu.com/it/u=2109797126,3226509270&fm=253&fmt=auto&app=120&f=JPEG?w=1080&h=721"]'),
('《敦煌》', '酒泉市敦煌市敦煌古城遗址', '井上靖', '日本', '敦煌古城遗址位于甘肃省酒泉市敦煌市，是日本作家井上靖《敦煌》的核心取景地。遗址保留有仿唐代建筑、古碑与壮阔的沙漠风光，敦煌古城是为拍摄电影而建的仿古建筑群，再现了唐宋时期敦煌城的繁华景象。井上靖以北宋初年一个书生流落敦煌的故事为主线，描绘了丝绸之路上的文化碰撞与藏经洞文物的命运。古城坐落在鸣沙山脚下，城墙内的街道、商铺、酒肆再现了丝路重镇的风貌。沙漠在城墙外延伸至天际。此处是感受丝路文化与日本文学视角下敦煌传奇的独特文学体验地。', '甘肃', 40.142100, 94.661800, '其他', '["https://img1.baidu.com/it/u=2505596664,3778556865&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=500"]'),
('《丝绸之路》', '武威市凉州区雷台汉墓遗址', '斯文・赫定', '瑞典', '雷台汉墓遗址（丝绸之路段）位于甘肃省武威市凉州区，是瑞典探险家斯文・赫定《丝绸之路》中重点记载的景点。遗址保留有东汉墓葬、铜车马仪仗与古碑，雷台汉墓最重要的出土文物是举世闻名的"马踏飞燕"铜奔马，被定为中国旅游标志。斯文・赫定是十九世纪末至二十世纪初最伟大的丝路探险家之一，他多次穿越河西走廊，记录了沿途的古城遗址与文物。雷台汉墓的铜车马仪仗队由99件铜器组成，展现了东汉丝路贸易的繁荣。此处是了解丝绸之路考古发现与国际丝路探险文学的国宝级汉墓遗址。', '甘肃', 37.928300, 102.637800, '其他', '["https://img0.baidu.com/it/u=3609698081,2502751227&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《出塞二首・其一》', '葫芦岛市绥中县九门口长城遗址', '王昌龄', '唐代', '九门口长城遗址位于辽宁省葫芦岛市绥中县，是王昌龄《出塞》"秦时明月汉时关，万里长征人未还"描绘的边塞雄姿之一。九门口长城是明代万里长城唯一的水上长城——长城横跨九江河，河上建有九座水门，城在水上，水流城下，气势磅礴。长城在此处也是东北与华北的天然分界线。城墙沿山脊蜿蜒，敌楼矗立山巅。九江河在九道水门下奔涌而过，"一片石"古战场见证了吴三桂引清军入关的历史。王昌龄笔下的边塞苍凉在此化为长城与河流交织的壮美画卷。此处是了解明代水上长城军事工程与唐代边塞诗意境的国宝级长城遗址。', '辽宁', 40.325600, 120.344100, '其他', '["https://img1.baidu.com/it/u=4038500383,2256121213&fm=253&fmt=auto&app=138&f=JPEG?w=686&h=500"]'),
('《燕歌行》', '朝阳市双塔区柳城遗址', '高适', '唐代', '柳城遗址位于辽宁省朝阳市双塔区，是高适《燕歌行》"汉家烟尘在东北，汉将辞家破残贼"的创作地。柳城是唐代营州治所，东北第一军事重镇，也是安禄山起兵叛乱的发源地。高适以边塞将士的壮烈牺牲为主题，揭示了唐代军事体制中"战士军前半死生，美人帐下犹歌舞"的深刻矛盾。柳城遗址保留有唐代夯土城墙与建筑基址，周边的朝阳双塔在城市天际线上矗立。朝阳是东北地区最古老的城市之一，"三燕古都"的历史可追溯至前燕、后燕、北燕时期。此处是了解唐代东北军事边防与高适边塞诗创作的重要历史遗存。', '辽宁', 41.571800, 120.451000, '其他', '["https://img0.baidu.com/it/u=3343248422,3159076107&fm=253&fmt=auto&app=138&f=JPEG?w=889&h=500"]'),
('《长相思・山一程》', '牡丹江市宁安市宁古塔将军府遗址', '纳兰性德', '清代', '宁古塔将军府遗址位于黑龙江省牡丹江市宁安市，是纳兰性德《长相思》"山一程，水一程，身向榆关那畔行，夜深千帐灯"的记录地。宁古塔是清代东北最重要的军事重镇与流放地，无数文人士大夫被流放至此。纳兰性德随康熙帝东巡经过宁古塔一带，以深沉的笔触描绘了塞外行军的艰辛与思乡之情——"风一更，雪一更，聒碎乡心梦不成"。将军府遗址保留有清代建筑基址。宁安是渤海国上京龙泉府所在地，历史悠久。此处是了解清代东北军事驻防与纳兰性德词中塞外行旅的重要历史遗存。', '黑龙江', 44.340300, 129.463300, '其他', '["https://img0.baidu.com/it/u=4045552060,3838686114&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1433"]'),
('《采桑子・塞上咏雪花》', '哈尔滨市阿城区金上京会宁府遗址', '纳兰性德', '清代', '金上京会宁府遗址位于黑龙江省哈尔滨市阿城区，是纳兰性德《采桑子》"别有根芽，不是人间富贵花"咏叹塞外雪花之地。遗址保留有金代夯土城墙与宫殿基址，是女真族建立的金朝开国都城。金太祖完颜阿骨打在此称帝，开创了金朝一百二十年的历史。纳兰性德以满族贵族的身份追忆先祖创业之地，对塞外雪花的咏叹充满了民族情感。城墙遗址规模宏大，东西两城总面积达六平方公里。城内出土了大量金代文物。此处是了解金代开国历史与纳兰性德民族情感文学的重要考古遗址。', '黑龙江', 45.547000, 126.958000, '其他', '["https://img2.baidu.com/it/u=2806380363,2040589404&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1438"]'),
('《松花江放船歌》', '吉林市船营区松花湖五虎岛遗址', '康熙', '清代', '松花湖五虎岛遗址位于吉林省吉林市船营区，是康熙帝《松花江放船歌》"松花江，江水清，夜来雨过春涛生"的描绘地。松花湖因丰满水电站蓄水而成，湖面辽阔，群山环抱。康熙帝在第二次东巡时乘船游览松花江，被江上风光深深打动而赋诗。五虎岛是松花湖中最大的岛屿，因五座山峰状如卧虎而得名。湖水碧绿如翡翠，两岸青山层层叠叠。冬季松花湖沿岸出现壮美的雾凇景观，"忽如一夜春风来，千树万树梨花开"。此处是感受松花江壮美风光与清帝东巡文化的吉林山水名胜。', '吉林', 43.833000, 126.540900, '其他', '["https://img1.baidu.com/it/u=2446336116,446407926&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1107"]'),
('《入乌拉街》', '吉林市龙潭区乌拉街古城遗址', '乾隆', '清代', '乌拉街古城遗址位于吉林省吉林市龙潭区，是乾隆帝"山连长白雄东北，水汇松花控上游"的描绘地。遗址保留有清代打牲乌拉总管衙门基址与满族古建筑，乌拉街是清代"打牲乌拉"的所在地——专门为皇室采集东珠、人参、貂皮等贡品。乌拉街曾是乌拉国的都城，明代女真乌拉部在此建城称王。古城内保留有百花点将台、三府等满族古建筑。冬季松花江沿岸的雾凇奇观使乌拉街成为"雾凇之都"。此处是了解清代满族贡品文化与女真乌拉国历史的东北古城遗存。', '吉林', 43.910600, 126.562100, '其他', '["https://img2.baidu.com/it/u=3567205030,2148365479&fm=253&fmt=auto&app=120&f=JPEG?w=711&h=405"]'),
('《瑷珲城》', '黑河市爱辉区瑷珲古城魁星阁遗址', '乾隆', '清代', '瑷珲古城魁星阁遗址位于黑龙江省黑河市爱辉区，是乾隆帝"黑龙江上水云腥，壮士连营听鼓鼙"的描绘地。遗址保留有清代建筑遗迹与古碑，瑷珲古城始建于明代，清代为黑龙江将军驻地。1858年沙俄逼迫清政府签订《瑷珲条约》，割让黑龙江以北六十余万平方公里土地——这是中国近代史上最耻辱的不平等条约之一。瑷珲历史陈列馆以"爱辉——Loss"为主题，全面展示了这段屈辱历史。黑龙江在城外奔涌，对岸即为俄罗斯。此处是铭记国耻、了解中俄边境历史的重要爱国主义教育基地。', '黑龙江', 50.252200, 127.490600, '其他', '["https://img0.baidu.com/it/u=2365287002,2533496438&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《登千山》', '鞍山市铁东区千山仙人台遗址', '李世民', '唐代', '千山仙人台遗址位于辽宁省鞍山市铁东区，是唐太宗李世民"积翠岫千重，苍茫望不穷"的描绘地。仙人台是千山最高峰，海拔708米，为东北三大名山之首的千山之巅。仙人台因传说中仙人在此下棋而得名，峰顶巨石如棋盘。千山古称千朵莲花山，山中有999座峰峦。李世民东征高句丽时途经千山，被山中层峦叠嶂的壮美所震撼。仙人台周边古松苍翠，云雾缭绕。登上仙人台可俯瞰千山全貌——群峰如莲花般层层绽放。此处是感受东北名山之首壮美与唐太宗东征历史的千山之巅体验地。', '辽宁', 41.108600, 122.994600, '其他', '["https://img0.baidu.com/it/u=1673287498,3445405050&fm=253&fmt=auto&app=120&f=JPEG?w=800&h=1067"]'),
('《题医巫闾山》', '锦州市北镇市医巫闾山望海寺遗址', '耶律楚材', '元代', '医巫闾山望海寺遗址位于辽宁省锦州市北镇市，是耶律楚材《题医巫闾山》"闾山万仞倚青天，形势嵯峨控北边"的描绘地。望海寺保留有辽代建筑遗址与古碑，医巫闾山是中国古代五大镇山中的北方镇山，被誉为"东北名山之首"。耶律楚材是元代著名政治家与诗人，契丹族后裔，以深厚的汉学修养描绘了闾山的雄伟壮丽。望海寺位于闾山高处，传说天气晴好时可远望渤海。历代帝王多次来此祭祀山神。闾山古木参天，奇石林立。此处是了解中国古代镇山文化与耶律楚材诗歌的北方圣山。', '辽宁', 41.598900, 121.795800, '其他', '["https://img1.baidu.com/it/u=1986826334,2884531594&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《辽东行》', '丹东市凤城市凤凰山老牛背遗址', '王建', '唐代', '凤凰山老牛背遗址位于辽宁省丹东市凤城市，是王建《辽东行》"辽东万里辽水曲，古戍无城复无屋"的描绘地。老牛背保留有唐代古战场遗迹，是凤凰山最险峻的景观——山脊如刀刃般锋利，两侧绝壁千仞，仅容一人侧身通过。凤凰山是辽东第一险山，主峰攒云峰海拔836米。王建以唐代边塞将士的视角描绘了辽东的荒凉与艰险。唐太宗东征高句丽时曾在凤凰山一带征战。山中古松苍翠，溪流淙淙。秋日红叶漫山，冬日冰瀑悬挂。此处是感受辽东第一险山的极致体验与唐代东北边塞诗意境的登山探险之地。', '辽宁', 40.452200, 124.066600, '其他', '["https://img1.baidu.com/it/u=1549785928,1498008226&fm=253&fmt=auto&app=138&f=JPEG?w=889&h=500"]'),
('《送辽阳使还》', '辽阳市白塔区辽阳白塔遗址', '岑参', '唐代', '辽阳白塔遗址位于辽宁省辽阳市白塔区，是岑参"辽阳望河县，白首无由见"的描绘地。辽阳白塔是东北现存最高的辽代砖塔，高71米，八角十三层密檐式结构，始建于辽代。塔身砖雕精美，飞天、莲花、佛像等装饰栩栩如生。辽阳古称辽东城，是东北地区最古老的城市之一，自战国至清代一直是辽东的政治军事中心。岑参以边塞诗人的视角描绘了辽阳的遥远与边关将士的思乡之情。白塔在辽阳城中巍然矗立，历经千年风雨。此处是了解辽代建筑艺术与东北古城历史的标志性辽代古塔。', '辽宁', 41.270300, 123.172700, '其他', '["https://img0.baidu.com/it/u=3394254723,2056405740&fm=253&fmt=auto&app=120&f=JPEG?w=800&h=1181"]'),
('《契丹风土歌》', '赤峰市巴林左旗辽上京遗址', '萧总管', '辽代', '辽上京遗址位于内蒙古自治区赤峰市巴林左旗，是萧总管《契丹风土歌》"契丹家住云沙中，耆车如水马若龙"描绘契丹风情之地。遗址保留有辽代夯土城墙与宫殿基址，辽上京是契丹族建立的辽朝五京之首，也是中国历史上第一座草原都城。城址分皇城与汉城两部分，总面积达五平方公里。辽上京的城市规划兼具游牧与农耕文化特色。遗址中出土了大量辽代文物——契丹文碑刻、三彩器、鎏金铜器等。巴林左旗草原辽阔，契丹民族的骑射文化在此发源。此处是了解辽代草原帝国文明的最重要考古遗址。', '内蒙古', 43.970700, 119.379600, '其他', '["https://img2.baidu.com/it/u=1406605926,650516284&fm=253&fmt=auto&app=138&f=JPEG?w=890&h=500"]'),
('《题长白山》', '白山市抚松县长白山南坡鸭绿江大峡谷遗址', '刘建封', '清代', '长白山南坡鸭绿江大峡谷遗址位于吉林省白山市抚松县，是清末刘建封"长白山雄天北极，鸭绿江水向南流"的描绘地。大峡谷是火山喷发后形成的天然裂谷，深达数百米，全长约70公里。刘建封是清末勘查长白山的第一人，1908年他率队攀登长白山并详细记录了长白山的地理地貌。峡谷两壁陡峭如削，火山岩层纹理清晰。峡谷底部溪流奔涌，汇入鸭绿江。长白山南坡原始森林茂密，岳桦林在高海拔地带呈现出独特的风貌。此处是了解长白山火山地质与清末探险历史的壮美峡谷景观。', '吉林', 42.338500, 127.449700, '其他', '["https://img1.baidu.com/it/u=4222249352,857339964&fm=253&fmt=auto&app=120&f=JPEG?w=1196&h=800"]'),
('《黑龙江》', '黑河市逊克县逊克大平台雾凇遗址', '吴兆骞', '清代', '逊克大平台雾凇遗址位于黑龙江省黑河市逊克县，是清代流放诗人吴兆骞"黑龙江上水漫漫，万里西风雁影寒"的描绘地。大平台位于库尔滨河畔，每年冬季出现壮美的雾凇景观——雾凇持续时间长达四个月，规模与品质堪称中国之最。吴兆骞因"丁酉科场案"被流放宁古塔二十余年，以悲凉的笔触描绘了东北极寒之地的荒凉与壮美。库尔滨河不冻河段蒸腾的水汽在零下三四十度的严寒中凝结成冰晶，将两岸树木装点成玉树琼花。此处是感受中国最壮美雾凇景观与清代流放文学苍凉意境的极寒之地。', '黑龙江', 49.564400, 128.478300, '其他', '["https://img2.baidu.com/it/u=4125312131,360167335&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=652"]'),
('《宁古塔杂诗》', '牡丹江市海林市横道河子镇中东铁路机车库遗址', '吴兆骞', '清代', '横道河子镇中东铁路机车库遗址位于黑龙江省牡丹江市海林市，是吴兆骞"宁古塔边霜雪寒，征人到此泪阑干"描绘流放生活的关联地。遗址保留有十五座扇形机车库，是中东铁路上保存最完整的铁路遗址群，始建于1903年。横道河子是中东铁路上的重要车站，俄式建筑群保存完好——尖顶教堂、木刻楞房屋、石砌车库在白雪中别具异国风情。吴兆骞流放途经此地附近时留下的悲凉诗句见证了清代文人的命运。中东铁路机车库是工业遗产与建筑艺术的完美结合。此处是了解中东铁路历史与清代流放文学的独特工业遗产小镇。', '黑龙江', 44.574900, 129.380400, '其他', '["https://img1.baidu.com/it/u=1598554531,2402756638&fm=253&fmt=auto&app=138&f=JPEG?w=1067&h=800"]'),
('《游千山》', '鞍山市铁东区千山龙泉寺遗址', '王尔烈', '清代', '千山龙泉寺遗址位于辽宁省鞍山市铁东区，是清代关东才子王尔烈"千山不足千，人造一株莲"的描绘地。龙泉寺保留有明代建筑、古碑与泉水，始建于唐代，是千山五大禅林之首。王尔烈是清代乾隆朝翰林院编修，以才学著称关东。龙泉寺依山而建，殿宇层叠，古松环绕。寺内"曹雪芹纪念馆"展示了曹雪芹家族与千山的渊源。寺前的龙泉清澈甘甜，终年不涸。千山有999座山峰，"千山不足千"正是王尔烈的精妙概括。此处是了解东北佛教文化与清代关东文人风骨的千山禅林圣地。', '辽宁', 41.108600, 122.994600, '其他', '["https://img1.baidu.com/it/u=378733901,507573949&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《医巫闾山》', '锦州市北镇市北镇庙遗址', '乾隆', '清代', '北镇庙遗址位于辽宁省锦州市北镇市，是乾隆帝"万古此山当塞北，千秋庙貌壮幽州"的描绘地。北镇庙保留有明清建筑群与古碑，是历代帝王祭祀医巫闾山山神的专用庙宇，也是中国五大镇山中保存最完整的镇山庙。北镇庙始建于隋开皇十四年，现存建筑为明清重建。大殿中供奉有医巫闾山山神塑像，庄严威武。庙中保存有元、明、清三代帝王祭祀碑刻56通，被誉为"碑林"。北镇庙背靠闾山，面朝辽河平原，气势恢宏。此处是了解中国古代镇山祭祀制度与帝王文化的国宝级古建筑群。', '辽宁', 41.598900, 121.795800, '其他', '["https://img2.baidu.com/it/u=2471796252,2159029536&fm=253&fmt=auto&app=138&f=JPEG?w=665&h=500"]'),
('《哈尔滨》', '哈尔滨市道外区道外巴洛克建筑群遗址', '郑板桥', '清代', '道外巴洛克建筑群遗址位于黑龙江省哈尔滨市道外区，是文学作品中描绘的哈尔滨特色建筑群落。建筑群保留有清末至民国时期的"中华巴洛克"风格建筑——外立面采用欧洲巴洛克式雕花装饰，内部为中国传统合院布局，形成了独特的"中西合璧"建筑风格。道外区是老哈尔滨的商业中心，曾经商贾云集。巴洛克建筑的精美雕花在岁月中斑驳却仍见精致——飞天、龙凤、花卉等中国传统图案与欧式卷草、柱头交织。此处是了解近代中国城市建筑文化交融与老哈尔滨商业繁华的独特历史建筑群。', '黑龙江', 45.792100, 126.649200, '其他', '["https://img2.baidu.com/it/u=1727188079,1231770238&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1200"]'),
('《长白山》', '延边州安图县长白山北坡地下森林遗址', '吴大澂', '清代', '长白山北坡地下森林遗址位于吉林省延边州安图县，是清末勘界大臣吴大澂"长白雄峙镇东陲，万壑千峰拥翠微"的描绘地。地下森林是火山喷发后形成的谷底森林，位于长白山北坡海拔约1000米处。谷底距地表深约七八十米，原始森林在谷底茂密生长——红松、冷杉、云杉参天蔽日。吴大澂在光绪年间赴中朝边境勘界，亲临长白山考察，对长白山的雄伟壮丽留下了深刻印象。地下森林空气清新，负氧离子含量极高。此处是感受长白山火山地质奇观与原始森林生态的独特地下景观。', '吉林', 42.756700, 128.902400, '其他', '["https://img2.baidu.com/it/u=2256710021,3422115545&fm=253&fmt=auto&app=138&f=JPEG?w=762&h=500"]'),
('《瑷珲怀古》', '黑河市爱辉区瑷珲古城海关遗址', '魏源', '清代', '瑷珲古城海关遗址位于黑龙江省黑河市爱辉区，是魏源"瑷珲城下血模糊，割地求和计太疏"描绘近代屈辱历史之地。遗址保留有清代建筑遗迹与历史文物，瑷珲海关是清代黑龙江地区最重要的对外贸易口岸。魏源是晚清"睁眼看世界"的先驱思想家，"师夷长技以制夷"的主张对中国近代化产生了深远影响。1858年《瑷珲条约》的签订使中国丧失了黑龙江以北的广袤领土。瑷珲古城在黑龙江畔静静矗立，对岸的俄罗斯布拉戈维申斯克清晰可见。此处是铭记近代国耻与了解魏源忧国思想的重要历史教育遗址。', '黑龙江', 50.252200, 127.490600, '其他', '["https://img2.baidu.com/it/u=2257122781,3892970526&fm=253&fmt=auto&app=138&f=JPEG?w=683&h=500"]'),
('《东北抗日联军第一路军歌》', '通化市通化县兴林镇河里抗日根据地遗址', '杨靖宇', '现代', '河里抗日根据地遗址位于吉林省通化市通化县兴林镇，是杨靖宇《东北抗日联军第一路军歌》的诞生地。遗址保留有抗联密营、司令部旧址与革命文物，河里地区是东北抗日联军第一路军的核心活动区域。杨靖宇将军在白山黑水之间率领抗联战士与日本侵略者进行了艰苦卓绝的斗争，最终壮烈牺牲。密营隐藏在茂密的原始森林中，当年抗联战士在零下四十度的严寒中坚持战斗。通化地区群山连绵，森林茂密。此处是了解东北抗联英勇斗争史与杨靖宇革命精神的重要红色纪念地。', '吉林', 41.679100, 125.756100, '其他', '["https://img1.baidu.com/it/u=457594026,2201733708&fm=253&fmt=auto&app=138&f=JPEG?w=666&h=500"]'),
('《露营之歌》', '牡丹江市林口县八女投江遗址', '李兆麟', '现代', '八女投江遗址位于黑龙江省牡丹江市林口县，是李兆麟《露营之歌》"火烤胸前暖，风吹背后寒"创作之地。遗址是1938年东北抗联八位女战士面对日寇围攻宁死不屈、集体投江牺牲的地方。八位女英雄中最大的23岁，最小的仅13岁，她们的英勇壮举震撼了中国人民。李兆麟以真实的抗联生活为素材创作了《露营之歌》，描绘了东北抗联战士在极端恶劣环境中战斗的艰辛。乌斯浑河在遗址旁静静流淌。八女投江纪念碑在河畔庄严矗立。此处是中国抗战史上最悲壮的英雄故事发生地。', '黑龙江', 45.278800, 130.284400, '其他', '["https://img0.baidu.com/it/u=3728864926,540014326&fm=253&fmt=auto&app=138&f=JPEG?w=795&h=500"]'),
('《沁园春・雪》', '哈尔滨市尚志市亚布力大锅盔山遗址', '毛泽东', '现代', '亚布力大锅盔山遗址位于黑龙江省哈尔滨市尚志市，是毛泽东《沁园春・雪》"北国风光，千里冰封，万里雪飘"东北雪景灵感的呈现地之一。大锅盔山海拔1374米，是张广才岭主峰，冬季积雪深厚，是亚布力滑雪场的核心区域。毛泽东1936年在陕北写下《沁园春・雪》，"望长城内外，惟余莽莽；大河上下，顿失滔滔"的壮阔意境在东北雪原上得到最震撼的现实呈现。大锅盔山冬季银装素裹，林海雪原无边无际。此处是感受"北国风光"壮美与中国现代诗词最伟大作品意境的冰雪胜地。', '黑龙江', 45.209600, 127.960200, '其他', '["https://img1.baidu.com/it/u=1962858439,3999868462&fm=253&fmt=auto&app=138&f=JPEG?w=896&h=800"]'),
('《题镜泊湖》', '牡丹江市宁安市镜泊湖吊水楼瀑布遗址', '刘少奇', '现代', '镜泊湖吊水楼瀑布遗址位于黑龙江省牡丹江市宁安市，是刘少奇"镜泊湖水平如镜，两岸青山列画屏"的描绘地。吊水楼瀑布是镜泊湖最壮观的景观，丰水期瀑布宽达300余米，落差约20米，水流如千军万马奔腾而下，声震山谷。镜泊湖是中国最大的火山堰塞湖，由万年前火山喷发后熔岩堵塞牡丹江而成。湖面辽阔如镜，两岸青山倒映其中。冬季瀑布冰封，形成壮美的冰瀑景观。湖中盛产红尾鱼等冷水鱼种。此处是了解火山堰塞湖地质奇观与东北自然风光的中国最大火山湖景区。', '黑龙江', 44.340300, 129.463300, '其他', '["https://img1.baidu.com/it/u=3837404796,1156400603&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《五大连池》', '黑河市五大连池市老黑山火山口遗址', '郭沫若', '现代', '老黑山火山口遗址位于黑龙江省黑河市五大连池市，是郭沫若"五大连池胜，天然火山群"的描绘地。老黑山是五大连池火山群中最年轻的火山——1719至1721年喷发形成，距今仅三百余年。火山口直径350米，深约140米，口壁黑色熔岩如刀削般陡峭。五大连池因五座火山堰塞湖而得名，是中国最典型的火山地质博物馆。老黑山周边的翻花石海、喷气锥等火山地貌保存完好。矿泉水富含多种微量元素，有"药泉"之称。此处是了解中国最年轻火山地质景观的世界地质公园核心景区。', '黑龙江', 48.517200, 126.196800, '其他', '["https://img2.baidu.com/it/u=771871967,1537849258&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=658"]'),
('《大兴安岭》', '呼伦贝尔市根河市敖鲁古雅使鹿部落遗址', '老舍', '现代', '敖鲁古雅使鹿部落遗址位于内蒙古自治区呼伦贝尔市根河市，是老舍"大兴安岭，多么美丽的地方"的描绘地。敖鲁古雅是中国最后的使鹿部落——鄂温克族猎民世代在大兴安岭原始森林中以放养驯鹿为生。老舍在访问东北时对大兴安岭的壮美留下了深刻印象。部落中的驯鹿温顺可爱，鄂温克族的"撮罗子"（帐篷）在白桦林间散落。大兴安岭原始森林中的兴安落叶松参天蔽日。根河是中国"冷极"，冬季最低温可达零下五十余度。此处是了解中国最后的驯鹿文化与大兴安岭原始生态的独特民族文化体验地。', '内蒙古', 50.780400, 121.520300, '其他', '["https://img1.baidu.com/it/u=821195008,2858563904&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《呼伦贝尔草原》', '呼伦贝尔市陈巴尔虎旗莫日格勒河遗址', '叶圣陶', '现代', '莫日格勒河遗址位于内蒙古自治区呼伦贝尔市陈巴尔虎旗，是叶圣陶描绘的"天苍苍，野茫茫"的草原景象。莫日格勒河被老舍誉为"天下第一曲水"——河水在呼伦贝尔大草原上蜿蜒曲折，百转千回，从空中俯瞰如玉带飘落在绿毯之上。草原辽阔无际，牛羊成群，蒙古包散落其间。夏季草原百花盛开，骏马奔驰。"天苍苍，野茫茫，风吹草低见牛羊"的诗句在此获得最真实的呈现。蒙古族的那达慕大会在草原上热烈举行。此处是感受呼伦贝尔草原极致之美与中国草原文学意象的最壮阔天然牧场。', '内蒙古', 49.326900, 119.425700, '其他', '["https://img2.baidu.com/it/u=1963325002,558528002&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《沈阳故宫》', '沈阳市沈河区沈阳故宫十王亭遗址', '乾隆', '清代', '沈阳故宫十王亭遗址位于辽宁省沈阳市沈河区，是乾隆帝"大政当阳十亭列，八旗制度此权舆"的描绘地。十王亭是沈阳故宫最具特色的建筑——大政殿居中，左右各五座亭子分列两侧，代表满族八旗制度。沈阳故宫始建于1625年，是清太祖努尔哈赤与清太宗皇太极的宫殿。十王亭是八旗王公大臣举行朝会的场所，体现了满族早期"八王共治"的政治传统。大政殿八角重檐攒尖顶，黄琉璃瓦覆顶，庄严华丽。此处是了解清初满族政治制度与宫殿建筑的世界文化遗产。', '辽宁', 41.795900, 123.458800, '其他', '["https://img1.baidu.com/it/u=3317430974,1527730135&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《奉天府》', '沈阳市沈河区张氏帅府大青楼遗址', '张作霖', '现代', '张氏帅府大青楼遗址位于辽宁省沈阳市沈河区，是近代东北历史中"大帅府里风云起"的核心场景地。大青楼始建于1922年，是张作霖与张学良父子的官邸核心建筑，三层罗马式青砖建筑气势恢宏。张作霖从草莽英雄到"东北王"的传奇人生在此展开。1928年张作霖在皇姑屯事件中遇难后，张学良在大青楼发出了"东北易帜"通电，维护了国家统一。大青楼中保留有会客厅、办公室与小青楼。此处是了解近代东北政治风云与张氏父子传奇人生的重要近代史遗址。', '辽宁', 41.795900, 123.458800, '其他', '["https://img1.baidu.com/it/u=3837493825,3099822351&fm=253&fmt=auto&app=138&f=JPEG?w=479&h=475"]'),
('《大连港》', '大连市中山区大连港老码头遗址', '郭沫若', '现代', '大连港老码头遗址位于辽宁省大连市中山区，是郭沫若"大连港口水连天，巨轮如梭往又还"的描绘地。大连港老码头保留有近代港口建筑与设施，大连港始建于1899年，是东北地区最大的综合性港口。郭沫若以诗意的笔触描绘了大连港的繁忙与壮阔。大连港在近代史上经历了沙俄、日本殖民统治，1945年回归中国。老码头的石砌码头、铁轨、吊车记录着百年港口的沧桑。港口面朝黄海，碧波万顷。大连是中国最重要的不冻港之一。此处是了解大连港百年历史与近代东北海洋贸易文化的重要近代工业遗产。', '辽宁', 38.918600, 121.644800, '其他', '["https://img1.baidu.com/it/u=1154948113,911277011&fm=253&fmt=auto&app=120&f=JPEG?w=800&h=1044"]'),
('《呼兰河传》', '哈尔滨市呼兰区萧红故居遗址', '萧红', '现代', '萧红故居遗址位于黑龙江省哈尔滨市呼兰区，是萧红《呼兰河传》的创作地与故事发生地。故居保留有清末民初的北方民居——正房、厢房围成的四合院，院中有磨坊、菜园与水井。萧红在此度过了童年时光，祖父的后花园成为她文学世界中最温暖的记忆——"花开了，就像睡醒了似的；鸟飞了，就像在天上逛似的"。《呼兰河传》以童年视角描绘了二十世纪初东北小城的人情冷暖与社会众生相。呼兰河在故居不远处静静流淌。此处是走进萧红文学世界与感受东北小城近代生活的最重要文学故居。', '黑龙江', 45.889400, 126.587000, '其他', '["https://img0.baidu.com/it/u=1772020107,1761257879&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《生死场》', '哈尔滨市呼兰区呼兰河老码头遗址', '萧红', '现代', '呼兰河老码头遗址坐落于哈尔滨市呼兰区呼兰河畔，是萧红长篇小说《生死场》中农民苦难生活的真实背景地。码头始建于清末，曾是呼兰河流域重要的水运枢纽，承载着两岸百姓的日常生计与悲欢离合。至今仍保留着清末民初的码头建筑、老渡船与古碑刻，河岸边芦苇丛生，旧日的石阶与系船桩依稀可辨。萧红笔下那些在土地上挣扎求生的农民，便在这片河滩上演绎着生与死的轮回。这里远离城市喧嚣，秋日河水清冽，冬季冰封千里，四季风景各有韵味，是体验萧红文学世界与呼兰河畔原始风貌的绝佳之地。', '黑龙江', 45.889400, 126.587000, '其他', '["https://img2.baidu.com/it/u=757250652,958273004&fm=253&fmt=auto&app=120&f=JPEG?w=1282&h=800"]'),
('《马伯乐》', '哈尔滨市道里区中央大街北段遗址', '萧红', '现代', '中央大街北段遗址位于哈尔滨市道里区，是萧红小说《马伯乐》中主人公马伯乐逃难至哈尔滨后流连的场所。这段街区保留着大量清末民初的欧式建筑，巴洛克风格的穹顶与新艺术运动的铁艺阳台错落有致，老商铺的木质招牌依然散发着时代气息。与中央大街南段的热闹不同，北段更为静谧，窄巷深处偶见斑驳的砖墙与铸铁窗棂。萧红以犀利笔触刻画了马伯乐在乱世中的懦弱与逃避，而这些老建筑正是那个动荡年代的无声见证。冬日雪覆街面，行人稀少，更添一份历史的苍凉感。', '黑龙江', 45.755300, 126.616400, '其他', '["https://img2.baidu.com/it/u=2978749984,3850306243&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《额尔古纳河右岸》', '呼伦贝尔市根河市敖鲁古雅使鹿部落遗址', '迟子建', '现代', '敖鲁古雅使鹿部落遗址位于呼伦贝尔市根河市，是迟子建长篇小说《额尔古纳河右岸》中鄂温克族生活的真实原型地。这里地处大兴安岭深处，是中国最后一个使鹿部落的栖息地。原始森林莽莽苍苍，驯鹿在苔藓地上悠然觅食，鄂温克族人搭建的撮罗子散落林间。迟子建以深沉笔触记录了这个古老民族百年来的迁徙、信仰与衰落，每一棵白桦树都承载着萨满鼓声的回响。冬季气温低至零下五十度，冰雪覆盖一切，夏日则林间野花遍地、清溪潺潺，堪称中国最原始的人文与自然融合之境。', '内蒙古', 50.780400, 121.520300, '其他', '["https://img1.baidu.com/it/u=821195008,2858563904&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《白雪乌鸦》', '哈尔滨市道外区道外巴洛克建筑群遗址', '迟子建', '现代', '道外巴洛克建筑群遗址位于哈尔滨市道外区，是迟子建长篇小说《白雪乌鸦》中哈尔滨鼠疫故事的核心背景地。1910年冬，一场惨烈的鼠疫席卷哈尔滨，道外区是重灾区。如今这里仍保留着大量清末民初的巴洛克风格建筑，中式四合院与欧式立面奇妙结合，雕花门楣与铁艺阳台见证了中西文化的碰撞。迟子建在小说中以细腻笔触还原了那个特殊冬天里普通人的恐惧、勇气与温情。老街巷中偶有居民晾晒衣物，旧日药铺、杂货店的招牌依稀可辨，秋冬时节霜雪覆盖屋顶，更添历史沧桑之感。', '黑龙江', 45.792100, 126.649200, '其他', '["https://img2.baidu.com/it/u=1727188079,1231770238&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1200"]'),
('《伪满洲国》', '长春市南关区伪满皇宫同德殿遗址', '迟子建', '现代', '伪满皇宫同德殿遗址位于长春市南关区，是迟子建长篇小说《伪满洲国》中溥仪傀儡生涯的核心场景地。同德殿建于1938年，是溥仪日常起居与接见日本关东军高官的场所，建筑融合了中日两国风格，内部装饰精致而压抑。迟子建以宏大叙事展现了伪满洲国十四年间东北人民的屈辱与抗争，同德殿正是那段历史的缩影。殿内保留着溥仪的书房、卧室及会议厅，墙上旧照片记录着那个荒诞年代的种种细节。这里是了解东北沦陷史最直观的窗口，建筑本身的压迫感令人深思。', '吉林', 43.863900, 125.350000, '其他', '["https://img2.baidu.com/it/u=2699739478,1334044022&fm=253&fmt=auto&app=138&f=JPEG?w=664&h=443"]'),
('《人世间》', '长春市朝阳区长春光机所旧址', '梁晓声', '现代', '长春光机所旧址位于长春市朝阳区，是梁晓声长篇小说《人世间》中周秉昆等工人阶级生活劳作的重要背景参考地。这座始建于上世纪五十年代的科研机构，保留着典型的苏式建筑风格——红砖外墙、宽敞的厂房与整齐的林荫道，见证了新中国工业化的峥嵘岁月。梁晓声在小说中深情书写了东北工人家庭五十年的悲欢离合，而这些老厂房正是那个火热年代的物质载体。厂区内老式标语、宣传栏依稀可辨，秋日银杏金黄，冬季白雪覆盖，处处弥漫着浓郁的时代记忆。', '吉林', 39.921000, 116.486400, '其他', '["https://img2.baidu.com/it/u=1493575404,3469825599&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《人世间》', '长春市二道区吉林大路老街区遗址', '梁晓声', '现代', '吉林大路老街区遗址位于长春市二道区，是梁晓声长篇小说《人世间》中周家所在光字片的原型参考地之一。这片老街区保留着上世纪五六十年代的低矮平房、筒子楼与窄巷，是东北普通工人家庭聚居的典型社区。梁晓声笔下周秉昆一家的喜怒哀乐便在这样的街巷中展开，邻里间的鸡毛蒜皮与守望相助构成了最真实的人间烟火。冬日炊烟袅袅，积雪覆盖屋顶，夏季老槐树浓荫蔽日，街边小贩的叫卖声不绝于耳，是感受东北市井生活与《人世间》文学世界的绝佳之地。', '吉林', 43.864900, 125.374000, '其他', '["https://img0.baidu.com/it/u=856357527,2632677301&fm=253&fmt=auto&app=138&f=JPEG?w=889&h=500"]'),
('《雪城》', '牡丹江市西安区牡丹江老城区遗址', '梁晓声', '现代', '牡丹江老城区遗址位于牡丹江市西安区，是梁晓声知青文学代表作《雪城》的原型地。小说以上世纪七十年代末知青返城为背景，描绘了一代人在命运转折中的迷茫与奋争。老城区保留着清末民初的民居、老商铺与狭窄古巷，斑驳的砖墙上依稀可见旧日标语。牡丹江穿城而过，冬季江面冰封，两岸银装素裹，正如小说中那个寒冷而充满希望的年代。这里远离现代商业的喧嚣，街巷中偶有老人闲坐聊天，保留着东北小城特有的质朴与温情，是体验知青文学精神家园的静谧之地。', '黑龙江', 44.577200, 129.615300, '其他', '["https://img1.baidu.com/it/u=3347975191,362277449&fm=253&fmt=auto&app=120&f=JPEG?w=500&h=667"]'),
('《今夜有暴风雪》', '大庆市萨尔图区大庆油田第一口油井遗址', '梁晓声', '现代', '大庆油田第一口油井遗址位于大庆市萨尔图区，是梁晓声知青小说《今夜有暴风雪》的核心背景地。1959年松基三井喷出工业油流，揭开了大庆油田开发的序幕，也成为一代人青春与理想的象征。遗址保留着上世纪六十年代的钻井平台、老厂房与铁人精神标语，铁塔巍然矗立在茫茫草原之上。梁晓声以暴风雪之夜为背景，书写了知青们在北大荒的热血与迷茫。冬季这里风雪呼啸，气温低至零下三十度，夏日则草原碧绿、野花烂漫，是感受石油文化与知青精神的独特场所。', '黑龙江', 46.629500, 125.114200, '其他', '["https://img1.baidu.com/it/u=981324953,2796492140&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《闯关东》', '大连市旅顺口区闯关东纪念馆遗址', '高满堂', '现代', '闯关东纪念馆遗址位于大连市旅顺口区，是高满堂电视剧文学《闯关东》的重要背景参考地。旅顺口作为闯关东移民登陆东北的重要港口，见证了数百万山东人背井离乡、闯荡关东的悲壮历史。纪念馆保留着清末民初的码头建筑、老渡船模型与珍贵历史照片，再现了移民们漂洋过海的艰辛旅程。高满堂笔下朱开山一家的创业史便从这里启程。港口老仓库的石墙上布满青苔，海风中似乎仍回荡着百年前移民的呼唤，是了解闯关东历史与东北移民文化的珍贵窗口。', '辽宁', 38.851300, 121.261900, '其他', '["https://img2.baidu.com/it/u=4238507771,1055014980&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]');
INSERT INTO works (title, scenic_spot, author, dynasty, description, province, latitude, longitude, category, images) VALUES
('《闯关东》', '黑河市爱辉区瑷珲古城遗址', '高满堂', '现代', '瑷珲古城遗址位于黑河市爱辉区，是高满堂电视剧文学《闯关东》中朱开山一家扎根东北的重要场景地。古城始建于明代，清代成为黑龙江将军驻地，1858年《瑷珲条约》在此签订，割让了大片国土。如今古城墙残垣犹存，将军府修复后庄严肃穆，瑷珲历史陈列馆内珍藏着大量珍贵文物与历史文献。高满堂笔下闯关东者在这片边疆土地上开荒拓殖的故事，与古城的沧桑历史交相辉映。冬日黑龙江冰封如镜，夏季两岸绿意盎然，是体验边疆历史与闯关东精神的庄严之地。', '黑龙江', 50.252200, 127.490600, '其他', '["https://img2.baidu.com/it/u=2986978483,667736132&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1157"]'),
('《老酒馆》', '大连市中山区大连港老码头遗址', '高满堂', '现代', '大连港老码头遗址位于大连市中山区，是高满堂电视剧文学《老酒馆》中陈怀海经营老酒馆的场景参考地。大连港自清末开埠以来便是东北最重要的海运门户，老码头保留着清末民初的港口建筑、石砌仓库与铸铁系缆桩。高满堂以老酒馆为舞台，展现了闯关东后代在大连的悲欢离合与民族气节。码头附近旧日的日俄建筑错落有致，海风带着咸腥味拂过斑驳的石墙，黄昏时分渔船归港，灯火点点，保留着百年港城的原始韵味，是感受大连近代史与市井烟火的独特场所。', '辽宁', 38.918600, 121.644800, '其他', '["https://img1.baidu.com/it/u=1154948113,911277011&fm=253&fmt=auto&app=120&f=JPEG?w=800&h=1044"]'),
('《钢铁年代》', '鞍山市铁西区鞍钢老厂区遗址', '高满堂', '现代', '鞍钢老厂区遗址位于鞍山市铁西区，是高满堂电视剧文学《钢铁年代》的核心背景地。鞍山钢铁公司始建于1916年，新中国成立后成为共和国钢铁工业的长子。老厂区保留着上世纪五十年代的苏式厂房、高炉残体与巨型烟囱，车间内老式轧钢机锈迹斑斑却气势犹在。高满堂笔下的尚铁龙等钢铁工人便在这些厂房中挥汗如雨，铸造着新中国的钢铁脊梁。厂区内红砖墙上的标语依稀可辨，铁轨蜿蜒消失在远方，是感受共和国工业史与东北老工业基地精神的震撼之地。', '辽宁', 41.119700, 122.957700, '其他', '["https://img1.baidu.com/it/u=1127862558,860635446&fm=253&fmt=auto&app=138&f=JPEG?w=894&h=500"]'),
('《林海雪原》', '牡丹江市海林市威虎山夹皮沟遗址', '曲波', '现代', '威虎山夹皮沟遗址位于牡丹江市海林市，是曲波长篇小说《林海雪原》中杨子荣智取威虎山、深入匪巢的传奇故事发生地。这里地处张广才岭深处，林海莽莽，冬季积雪没膝，正是小说中描绘的那片白雪皑皑的深山老林。遗址保留着当年剿匪战斗的旧址、土匪据点残迹与蜿蜒的古驿道，山谷间寒风呼啸，松涛阵阵。曲波以亲身经历为素材，将杨子荣的英勇机智与座山雕的狡诈凶残刻画得淋漓尽致。夏日山花烂漫、溪水潺潺，冬季银装素裹、雪压青松，是体验红色文化与林海雪原壮美景色的绝佳之地。', '黑龙江', 44.574900, 129.380400, '其他', '["https://img0.baidu.com/it/u=2635379493,3956921485&fm=253&fmt=auto&app=138&f=JPEG?w=1067&h=800"]'),
('《林海雪原》', '牡丹江市海林市杨子荣烈士陵园遗址', '曲波', '现代', '杨子荣烈士陵园遗址位于牡丹江市海林市，是《林海雪原》中英雄杨子荣牺牲后的安息之所。陵园庄严肃穆，松柏苍翠环绕，杨子荣烈士墓碑高耸，纪念馆内陈列着英雄的遗物、战斗照片与珍贵史料，再现了剿匪战斗的惊心动魄。曲波在小说中以深沉笔触描写了战友们的英勇牺牲，而这座陵园正是那段历史的永恒纪念。每年清明时节，前来祭扫的群众络绎不绝，鲜花与挽联寄托着后人对英雄的无限敬仰。陵园周边山林静谧，是缅怀革命先烈、感受红色精神的庄严之地。', '黑龙江', 44.574900, 129.380400, '其他', '["https://img1.baidu.com/it/u=520862124,388964097&fm=253&fmt=auto&app=138&f=JPEG?w=667&h=500"]'),
('《暴风骤雨》', '哈尔滨市尚志市元宝镇元宝村遗址', '周立波', '现代', '元宝村遗址位于哈尔滨市尚志市元宝镇，是周立波长篇小说《暴风骤雨》中土地改革运动的真实原型地。1946年周立波深入元宝村参加土改工作，亲身经历了翻天覆地的社会变革，并以此为素材创作了这部经典之作。村中保留着清末民初的东北民居、老磨坊与土改纪念馆，展示着土改时期的珍贵文物与历史照片。小说中赵玉林、郭全海等人物的原型便生活在这片黑土地上。夏日稻田碧绿、秋季金穗翻浪，村庄四周群山环抱，黑土地肥沃深厚，是了解中国土地改革历史与东北乡村风貌的重要文化地标。', '黑龙江', 45.209600, 127.960200, '其他', '["https://img0.baidu.com/it/u=2951502141,2616307128&fm=253&fmt=auto&app=138&f=JPEG?w=803&h=500"]'),
('《暴风骤雨》', '哈尔滨市尚志市尚志镇赵一曼纪念馆遗址', '周立波', '现代', '赵一曼纪念馆遗址位于哈尔滨市尚志市，与《暴风骤雨》的革命背景相呼应。赵一曼是东北抗日联军著名女英雄，1936年在此地区英勇就义。纪念馆内保留着赵一曼的遗物、书信与珍贵历史照片，再现了这位巾帼英雄的壮烈人生。周立波在《暴风骤雨》中书写的革命精神，与赵一曼的英勇事迹一脉相承。纪念馆建筑庄严朴素，周边松林环绕，四季常青，每年吸引大量瞻仰者前来缅怀。这里是感受东北抗战精神与革命传统的重要教育基地，也是理解东北近现代史的珍贵窗口。', '黑龙江', 45.209600, 127.960200, '其他', '["https://img1.baidu.com/it/u=2052823005,1044485221&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=642"]'),
('《铁道游击队》', '沈阳市和平区沈阳铁路局旧址', '刘知侠', '现代', '沈阳铁路局旧址位于沈阳市和平区，是刘知侠长篇小说《铁道游击队》中铁路工人革命斗争的重要背景参考地。这座建于清末的铁路管理机构，见证了中国铁路从清末到民国再到新中国的百年变迁。建筑为典型的欧式风格，红砖外墙、拱形门窗，内部保留着民国时期的办公设施与老式火车模型。刘知侠笔下铁道游击队员们在铁路线上神出鬼没的英勇事迹，与这座铁路重镇的历史紧密相连。建筑周边老铁轨蜿蜒，冬日积雪覆盖，更添一份历史的厚重感。', '辽宁', 41.788900, 123.406200, '其他', '["https://img0.baidu.com/it/u=2059610520,1475804102&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《敌后武工队》', '通化市通化县兴林镇河里抗日根据地遗址', '冯志', '现代', '河里抗日根据地遗址位于通化市通化县兴林镇，是东北抗联活动的重要据点，与冯志《敌后武工队》中描写的抗日斗争精神相呼应。这里地处长白山余脉深处，山高林密、沟壑纵横，是天然的游击战场。遗址保留着抗联密营、地窨子、哨所旧址与纪念碑，林间小道蜿蜒曲折，当年战士们在冰天雪地中坚持抗战的艰苦可想而知。夏日山林葱郁、野花遍地，冬季白雪封山、寂静无声，仿佛仍能听到抗联战士的脚步声。这里是体验东北抗联精神与长白山原始风光的珍贵红色遗址。', '吉林', 41.679100, 125.756100, '其他', '["https://img1.baidu.com/it/u=457594026,2201733708&fm=253&fmt=auto&app=138&f=JPEG?w=666&h=500"]'),
('《野火春风斗古城》', '沈阳市沈河区沈阳故宫十王亭遗址', '李英儒', '现代', '沈阳故宫十王亭遗址位于沈阳市沈河区，是李英儒长篇小说《野火春风斗古城》中地下党活动场景的历史参考地。十王亭建于清太祖努尔哈赤时期，是八旗王公议政之所，建筑呈雁翅排列，气势恢宏。李英儒笔下地下党员在敌占城市中的惊险斗争，与这座古城的深邃历史形成了跨越时空的呼应。亭阁飞檐翘角、彩绘斑斓，广场上青石板路光滑如镜。这里虽为沈阳故宫的组成部分，但十王亭区域游客相对较少，清晨或傍晚时分尤为静谧，是感受清初历史与革命文学交织的独特场所。', '辽宁', 41.795900, 123.458800, '其他', '["https://img1.baidu.com/it/u=3317430974,1527730135&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《平原枪声》', '长春市德惠市德惠战役遗址', '李晓明', '现代', '德惠战役遗址位于长春市德惠市，是李晓明长篇小说《平原枪声》中东北解放战争场景的重要历史参考地。1947年德惠战役是东北战场上的关键战役之一，双方在松花江畔展开了激烈的攻防战。遗址保留着战壕残迹、纪念碑与纪念馆，馆内陈列着战役中使用的武器、文件与珍贵照片。李晓明笔下的平原游击战与东北战场的壮烈相互映照。遗址周边是广袤的松嫩平原，夏日庄稼翠绿、秋季金黄遍野，冬季白雪茫茫，大地辽阔而肃穆，是了解东北解放战争历史的重要红色教育基地。', '吉林', 44.521600, 125.700000, '其他', '["https://img1.baidu.com/it/u=3638542327,2584555698&fm=253&fmt=auto&app=138&f=JPEG?w=465&h=351"]'),
('《烈火金刚》', '丹东市宽甸县青山沟抗联遗址', '刘流', '现代', '青山沟抗联遗址位于丹东市宽甸县，与刘流长篇小说《烈火金刚》中描写的抗日烽火相呼应。青山沟地处鸭绿江畔，群山环抱、溪流纵横，是东北抗联活动的重要区域。遗址保留着抗日旧址、密营遗迹与纪念设施，山谷中瀑布飞泻、清潭如镜，自然风光与红色记忆交相辉映。刘流笔下抗日英雄们在敌后浴血奋战的壮烈场景，在这片山林中找到了最真实的注脚。春日山花烂漫、夏季绿荫蔽日、秋天枫叶如火、冬季冰瀑悬崖，四季景色各异，是兼具自然之美与革命精神的珍贵之地。', '辽宁', 40.731200, 124.783400, '其他', '["https://img1.baidu.com/it/u=1340038303,3450652403&fm=253&fmt=auto&app=138&f=JPEG?w=667&h=500"]'),
('《青春之歌》', '沈阳市和平区东北大学旧址', '杨沫', '现代', '东北大学旧址位于沈阳市和平区，是杨沫长篇小说《青春之歌》中林道静等青年学生投身革命的场景参考地。东北大学始建于1923年，张学良曾任校长，是民国时期东北最高学府。旧址保留着典型的民国建筑风格，红砖礼堂、拱形门廊与林荫大道见证了无数青年学子的激昂岁月。杨沫笔下那些在民族危亡之际奋起抗争的青年身影，与这座校园的历史精神一脉相承。秋日校园银杏金黄、落叶纷飞，冬季白雪覆盖老建筑更显庄重，是感受民国教育史与青年革命精神的文化圣地。', '辽宁', 41.788900, 123.406200, '其他', '["https://img2.baidu.com/it/u=4199436042,2807994996&fm=253&fmt=auto&app=138&f=JPEG?w=1067&h=800"]'),
('《苦菜花》', '通化市集安市鸭绿江抗联遗址', '冯德英', '现代', '鸭绿江抗联遗址位于通化市集安市，与冯德英长篇小说《苦菜花》中描写的抗日精神遥相呼应。集安地处鸭绿江畔，与朝鲜隔江相望，是东北抗联重要的活动区域。遗址保留着抗日旧址、密营遗迹与纪念设施，鸭绿江水在群山间蜿蜒流淌，两岸青山如画。抗联战士们曾在这片山水间与日寇周旋，留下了可歌可泣的英雄故事。冯德英笔下革命母亲的坚韧形象，在东北这片热土上同样有着深厚的现实基础。春日江畔桃花盛开、夏季碧水青山、秋天层林尽染、冬季江面冰封，是集自然美景与红色记忆于一体的独特之地。', '吉林', 41.126100, 126.194000, '其他', '["https://img0.baidu.com/it/u=2495383895,3600593944&fm=253&fmt=auto&app=120&f=JPEG?w=1422&h=800"]'),
('《迎春花》', '吉林市桦甸市红石砬子抗联遗址', '冯德英', '现代', '红石砬子抗联遗址位于吉林市桦甸市，是冯德英长篇小说《迎春花》的核心历史背景参考地。这里地处长白山区，松花江上游，群山连绵、森林茂密，是东北抗日联军第一路军的重要根据地。遗址保留着抗联密营、战壕、哨所与纪念碑，山间古木参天，溪流清澈见底。冯德英笔下那些在苦难中绽放的迎春花般的革命者，正是以这样的山林为战场。松花江在山谷间蜿蜒流过，春日冰雪消融、山花烂漫，夏季林海苍翠、凉风习习，秋天红叶满山、层林尽染，是体验东北抗联精神与长白山原始风光的珍贵场所。', '吉林', 42.972100, 126.743200, '其他', '["https://img2.baidu.com/it/u=3884845782,2467285423&fm=253&fmt=auto&app=138&f=JPEG?w=664&h=387"]'),
('《山菊花》', '延边州敦化市寒葱岭抗联遗址', '冯德英', '现代', '寒葱岭抗联遗址位于延边州敦化市，是冯德英长篇小说《山菊花》中东北抗联活动的重要场景参考地。寒葱岭海拔千余米，地处长白山腹地，冬季积雪深厚、气候严寒，是当年抗联战士浴血奋战的艰苦战场。遗址保留着抗日密营、战壕残迹与纪念碑，密林中弹痕累累的老树见证着那段烽火岁月。冯德英笔下那些如山菊花般坚韧不屈的革命者，便在这样的冰天雪地中坚持斗争。夏日山林葱郁、野花遍地，秋天满山红叶与金色白桦交相辉映，冬季银装素裹、分外壮观，是感受抗联精神与长白山自然之美的静谧之地。', '吉林', 43.355100, 128.231600, '其他', '["https://img2.baidu.com/it/u=758848381,1871814246&fm=253&fmt=auto&app=138&f=JPEG?w=667&h=500"]'),
('《东北抗日联军》', '哈尔滨市尚志市赵尚志纪念馆遗址', '佚名', '现代', '赵尚志纪念馆遗址位于哈尔滨市尚志市，是记录东北抗日联军英雄事迹的重要纪念场所。赵尚志是东北抗联第三军军长，与杨靖宇齐名，被誉为南杨北赵。纪念馆内保留着赵尚志的遗物、战斗照片与珍贵历史文献，再现了这位民族英雄从投身革命到壮烈牺牲的传奇一生。馆舍建筑庄严朴素，周边松柏苍翠、肃穆宁静。尚志市原名珠河县，因纪念赵尚志而改名，这座城市本身便是一座活的纪念碑。每年清明与抗战纪念日，前来瞻仰的群众络绎不绝，是了解东北抗联历史与民族精神的重要教育基地。', '黑龙江', 45.209600, 127.960200, '其他', '["https://img0.baidu.com/it/u=3023356139,4135164718&fm=253&fmt=auto&app=138&f=JPEG?w=889&h=500"]'),
('《大染坊》', '营口市站前区营口老码头遗址', '陈杰', '现代', '营口老码头遗址位于营口市站前区，是陈杰长篇小说《大染坊》中主人公陈寿亭创业经商的场景参考地。营口是东北最早的对外通商口岸，开埠于1861年，老码头见证了东北近代商业的兴衰。遗址保留着清末民初的码头建筑、石砌仓库与古碑刻，辽河入海口处帆影点点，旧日的繁华依稀可辨。陈杰笔下陈寿亭从乞丐到染坊大亨的传奇创业史，正是在这样的通商口岸背景下展开。码头周边老街巷狭窄幽深，百年老店的招牌斑驳可辨，海风中弥漫着咸腥气息，是感受东北近代商业史与市井文化的独特场所。', '辽宁', 40.672600, 122.258900, '其他', '["https://img2.baidu.com/it/u=339469247,2450026510&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《闯关东前传》', '哈尔滨市道外区道外三道街遗址', '高满堂', '现代', '道外三道街遗址位于哈尔滨市道外区，是高满堂电视剧文学《闯关东前传》中闯关东移民聚集生活的重要场景地。道外区是哈尔滨最早的华人聚居区，三道街更是当年闯关东者落脚谋生的核心地带。这里保留着大量清末民初的中华巴洛克建筑，中式四合院的格局配上欧式浮雕立面，形成了独特的建筑风貌。高满堂笔下那些背井离乡、闯荡关东的山东人，便在这样的街巷中开始了新生活。老商铺、杂货店、小酒馆的痕迹依稀可辨，冬日飘雪覆盖青砖灰瓦，更添一份移民历史的厚重与苍凉。', '黑龙江', 45.792100, 126.649200, '其他', '["https://img0.baidu.com/it/u=2762730117,9453462&fm=253&fmt=auto&app=138&f=JPEG?w=525&h=500"]'),
('《平原上的摩西》', '沈阳市铁西区艳粉街', '双雪涛', '现代', '艳粉街位于沈阳市铁西区，是双雪涛中篇小说《平原上的摩西》核心叙事空间，也是作者的成长之地。铁西区曾是中国最大的重工业基地，上世纪九十年代大规模下岗潮使这片区域陷入沉寂与阵痛。艳粉街保留着五六十年代的苏式红砖楼、老修车铺与窄巷，墙壁斑驳、管道裸露，空气中似乎仍弥漫着机油与煤烟的气息。双雪涛以冷峻笔触书写了那个时代东北普通家庭的命运沉浮，小说中的案件与救赎都在这片衰败而温情的街区中展开。冬日积雪覆盖老楼，黄昏灯光昏暗，是感受东北工业转型阵痛与文学记忆的真实之地。', '辽宁', 41.802800, 123.348900, '其他', '["https://img2.baidu.com/it/u=1458122955,1124494610&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1066"]'),
('《冬泳》', '沈阳市铁西区工人村三宿舍', '班宇', '现代', '工人村三宿舍位于沈阳市铁西区，是新中国第一个工人住宅区，也是班宇中篇小说《冬泳》中孙旭晨、黎东升等人生活的原型地。这片建于上世纪五十年代的工人社区，曾是东北产业工人的骄傲与归属，红砖楼排列整齐，楼间距宽阔，绿化带中老槐树枝繁叶茂。然而随着国企改革的推进，大批工人下岗，社区逐渐衰败。班宇以冷峻而深情的笔触描写了这些在时代洪流中挣扎的普通人，冬泳成为他们对抗命运的隐喻。冬日楼前积雪覆盖，走廊里昏暗的灯光映照着斑驳的墙壁，是感受东北工人阶级命运变迁与新东北文学精神的真实之地。', '辽宁', 41.802800, 123.348900, '其他', '["https://img0.baidu.com/it/u=957472357,3764193242&fm=253&fmt=auto&app=120&f=JPEG?w=667&h=500"]'),
('《仙症》', '沈阳市皇姑区北陵公园后山松林', '郑执', '现代', '北陵公园后山松林位于沈阳市皇姑区，是郑执中篇小说《仙症》中王战团发病、作者童年玩耍的场景地。北陵即清昭陵，是皇太极与孝端文皇后的合葬陵寝，后山松林古木参天，清代所植古松苍劲挺拔，树龄逾三百年。林间石板路蜿蜒曲折，偶有废弃的防空工事半掩于土中，增添了几分神秘气息。郑执笔下那位患有精神疾病的姑父王战团，便常在这片松林中游荡，时而清醒时而癫狂。松林深处寂静幽暗，阳光透过针叶洒落斑驳光影，冬季白雪压松枝，是体验沈阳皇家园林野趣与东北文学记忆的隐秘之所。', '辽宁', 41.824200, 123.425200, '其他', '["https://img2.baidu.com/it/u=1785134329,3047289675&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=751"]'),
('《飞行家》', '沈阳市大东区东塔机场旧址', '双雪涛', '现代', '东塔机场旧址位于沈阳市大东区，是东北最早的机场之一，也是双雪涛小说《飞行家》中李明奇梦想造飞机的原型地。机场始建于上世纪三十年代日据时期，曾是日本关东军的军用机场，抗战胜利后由中国空军接管。旧址保留着上世纪三十年代的俄式机库、跑道残迹与部分航空设施，斑驳的混凝土与锈蚀的铁件诉说着那段动荡的航空史。双雪涛笔下那个执着于飞行梦想的小人物，正是在这样的工业废墟中寄托着不切实际却动人心魄的理想。机场周边已渐被城市包围，但老机库的轮廓依然可辨，是感受沈阳近代航空史与文学想象力的独特场所。', '辽宁', 41.806300, 123.469500, '其他', '["https://img0.baidu.com/it/u=1294643695,1826863686&fm=253&fmt=auto&app=138&f=JPEG?w=750&h=500"]'),
('《逍遥游》', '沈阳市沈河区万柳塘公园', '班宇', '现代', '万柳塘公园位于沈阳市沈河区，是班宇小说《逍遥游》中许玲玲、赵东阳等人散步休憩的场景地。公园始建于上世纪五十年代，以湖心亭与石桥闻名，湖畔杨柳依依、荷叶田田。班宇笔下那些身患重病、生活困窘却仍渴望自由与尊严的人物，便在这座老公园中短暂地获得了逍遥的片刻。湖心亭虽经岁月洗礼略显陈旧，却更添一份质朴温情。春日柳絮飘飞、夏季荷花盛开、秋天芦苇摇曳、冬季冰面上偶有少年嬉戏，这座承载着沈阳市民集体记忆的老公园，是感受东北市井温情与班宇文学世界的安静之所。', '辽宁', 41.795900, 123.458800, '其他', '["https://img0.baidu.com/it/u=3073033087,271478256&fm=253&fmt=auto&app=120&f=JPEG?w=667&h=500"]'),
('《生吞》', '沈阳市和平区南湖公园湖心岛', '郑执', '现代', '南湖公园湖心岛位于沈阳市和平区，是郑执长篇小说《生吞》中黄姝、秦理秘密约会的场景地。南湖公园始建于1938年，是沈阳市区内最大的湖泊公园之一，湖心岛通过石桥与岸边相连，岛上绿树成荫、曲径通幽。郑执以悬疑笔法讲述了一群少年在成长过程中遭遇的暴力与救赎，湖心岛成为小说中纯真与黑暗交织的象征空间。岛上保留着上世纪六十年代的游乐设施残迹与石桥，夏日荷花映水、蝉鸣阵阵，冬季湖面冰封、银装素裹，黄昏时分游人散去后格外静谧，是体验沈阳城市记忆与青春文学意象的独特之地。', '辽宁', 41.788900, 123.406200, '其他', '["https://img0.baidu.com/it/u=3589823078,3623416194&fm=253&fmt=auto&app=138&f=JPEG?w=794&h=500"]'),
('《群山之巅》', '大兴安岭地区塔河县十八站鄂伦春族乡', '迟子建', '现代', '十八站鄂伦春族乡位于大兴安岭地区塔河县，是迟子建长篇小说《群山之巅》中龙盏镇的真实原型地。这里地处大兴安岭腹地，是鄂伦春族世代聚居的家园，保留着传统的木刻楞房屋、桦树皮器具与狩猎文化遗存。迟子建以这座边陲小镇为背景，展现了形形色色人物的命运纠葛与人性幽微。群山连绵、林海苍茫，冬季气温低至零下四十度，白雪封山长达半年之久。夏日短暂而热烈，野花遍地、蘑菇丛生，鄂伦春族猎民的篝火故事在夜空下回荡。这里是中国最偏远的乡镇之一，是体验大兴安岭原始风貌与迟子建文学世界的极北之地。', '黑龙江', 52.334200, 124.710000, '其他', '["https://img1.baidu.com/it/u=121679602,1149108426&fm=253&fmt=auto&app=138&f=JPEG?w=607&h=404"]'),
('《世界上所有的夜晚》', '大兴安岭地区呼中区呼中镇', '迟子建', '现代', '呼中镇位于大兴安岭地区呼中区，被誉为中国最冷小镇，是迟子建中篇小说《世界上所有的夜晚》中女主人公旅行疗伤的场景地。这里冬季极端气温可达零下五十二度，是全国气温最低的城镇。小镇隐藏在大兴安岭深处，原始森林环绕，呼中河穿镇而过。迟子建笔下那位失去丈夫的女主人公，在这座偏远小镇上遇见了各种各样的人与事，在寒冷中获得了心灵的慰藉。夏日林间野花烂漫、溪水潺潺，冬季冰雪王国般的景象令人震撼。小镇居民质朴热情，保留着大兴安岭林区特有的生活方式，是远离尘嚣、体验极寒之美与文学疗愈精神的静谧之地。', '黑龙江', 52.033500, 123.599700, '其他', '["https://img1.baidu.com/it/u=1145831472,1971125483&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1228"]'),
('《伪满洲国》', '长春市宽城区伪满国务院旧址', '迟子建', '现代', '伪满国务院旧址位于长春市宽城区，是迟子建长篇小说《伪满洲国》中溥仪伪政权行政中心的核心场景地。这座建于1936年的庞大建筑群，曾是伪满洲国最高行政机关所在地，建筑风格融合了日式简约与西式古典元素，气势恢宏而压抑。迟子建在小说中以冷静笔触还原了伪满十四年间的政治荒诞与民间疾苦，国务院的会议厅、走廊与办公室都成为历史的无声见证。建筑内部保留着大量原始装饰与办公设施，石质楼梯回响着历史的脚步声。这里是了解伪满洲国傀儡政权运作机制与东北沦陷史的重要历史遗址。', '吉林', 43.901900, 125.326900, '其他', '["https://img1.baidu.com/it/u=1345655727,553997190&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《额尔古纳河右岸》', '呼伦贝尔市根河市满归镇', '迟子建', '现代', '满归镇位于呼伦贝尔市根河市，是迟子建长篇小说《额尔古纳河右岸》中鄂温克族使鹿部落的重要迁徙地。满归镇地处大兴安岭北麓，原始森林密布，额尔古纳河支流在山谷间蜿蜒流淌。鄂温克族人曾在这片林海中放牧驯鹿、采集野果，过着半游牧的传统生活。迟子建以第一人称叙述了一个鄂温克族老奶奶的百年人生，满归镇的山林、河流与季节更替都融入了小说的叙事血脉。夏日森林苍翠、野花遍地，冬季白雪茫茫、驯鹿踏雪而行，是体验大兴安岭极北风光与鄂温克族文化的珍贵之地。', '内蒙古', 50.780400, 121.520300, '其他', '["https://img0.baidu.com/it/u=2489016388,3285006257&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《年轮》', '哈尔滨市道外区南三道街', '梁晓声', '现代', '南三道街位于哈尔滨市道外区，是道外巴洛克建筑群的核心地带，也是梁晓声长篇小说《年轮》中郝梅、张萌等人童年生活的场景地。这条老街保留着大量中华巴洛克风格建筑，中式四合院外包裹着欧式浮雕立面，形成了独特的中西合璧风貌。梁晓声笔下那群在特殊年代中成长的少年，便在这样的街巷中经历了友情、爱情与命运的考验。老街上杂货铺、理发店、小饭馆的痕迹依稀可辨，砖雕花饰精美绝伦。冬日雪落青砖，老街更显沧桑，是感受哈尔滨近代市井文化与知青一代青春记忆的珍贵历史街区。', '黑龙江', 45.792100, 126.649200, '其他', '["https://img2.baidu.com/it/u=3834363360,3708742870&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=500"]'),
('《父亲》', '哈尔滨市平房区哈飞老厂区', '梁晓声', '现代', '哈飞老厂区位于哈尔滨市平房区，是新中国航空工业的摇篮，也是梁晓声中篇小说《父亲》中父亲工作的场景地。哈尔滨飞机制造厂始建于1952年，是中国第一架直升机的诞生地，老厂区保留着上世纪五十年代的苏式厂房、装配车间与办公楼。梁晓声笔下那位默默奉献的父亲形象，正是千千万万航空工人的缩影。厂房内巨型龙门吊高耸入云，老式机床锈迹斑斑却气势犹在，车间外林荫道上法桐树亭亭如盖。秋日金叶飘落、冬季雪压厂房，是感受新中国航空工业发展史与东北工人阶级奉献精神的重要工业遗址。', '黑龙江', 45.597700, 126.637200, '其他', '["https://img0.baidu.com/it/u=878350750,3575553831&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《老农民》', '大连市瓦房店市复州城镇', '高满堂', '现代', '复州城镇位于大连市瓦房店市，是辽南历史文化名城，也是高满堂电视剧文学《老农民》中牛大胆、马仁礼等人生活的原型地。复州城始建于辽代，有近千年历史，保留着明清古城墙残迹、清代县衙与传统辽南民居。高满堂笔下那些在土地上摸爬滚打的老农民，便在这样的古镇中经历了从土改到改革开放的沧桑巨变。古镇街道狭窄幽深，青石板路磨得光亮，老戏台、古井与百年老槐树散发着浓郁的乡土气息。春日果花盛开、秋季苹果飘香，是感受辽南乡村历史与中国农民命运变迁的文化古镇。', '辽宁', 39.627200, 121.980000, '其他', '["https://img2.baidu.com/it/u=4272349178,885053305&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=606"]'),
('《温州一家人》', '大连市甘井子区大连湾老码头', '高满堂', '现代', '大连湾老码头位于大连市甘井子区，是东北重要的港口之一，也是高满堂电视剧文学《温州一家人》中周万顺创业的场景地。大连湾自清末以来便是东北海运的重要节点，老码头保留着近代的港口设施、石砌堤坝与老仓库。高满堂笔下温州商人周万顺背井离乡、艰苦创业的故事，在这座港口城市找到了扎实的现实土壤。码头附近渔船密集，海鲜市场烟火气十足，海风中弥漫着咸腥气息。黄昏时分落日映照海面，远处灯塔闪烁，是感受东北港口商业文化与改革开放创业精神的独特场所。', '辽宁', 38.953000, 121.525700, '其他', '["https://img1.baidu.com/it/u=1154948113,911277011&fm=253&fmt=auto&app=120&f=JPEG?w=800&h=1044"]'),
('《闯关东中篇》', '吉林市船营区吉林西站', '高满堂', '现代', '吉林西站位于吉林市船营区，是中国最美的火车站之一，也是高满堂电视剧文学《闯关东中篇》中宋家姐妹逃难经过的场景地。车站建于1928年，由林徽因参与设计，融合了哥特式尖顶、巴洛克穹顶与中国传统飞檐元素，堪称中西建筑艺术的完美结合。高满堂笔下闯关东移民们在这座车站来来往往，见证了东北近代的悲欢离合。车站钟楼巍然矗立，彩色玻璃窗在阳光下斑斓夺目，候车大厅穹顶高敞。冬日白雪覆盖尖顶，更显童话般的美感，是感受中国近代铁路建筑艺术与东北移民历史的文化瑰宝。', '吉林', 43.833000, 126.540900, '其他', '["https://img2.baidu.com/it/u=2604163879,367918835&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《大江东去》', '沈阳市铁西区沈阳重型机械厂旧址', '阿耐', '现代', '沈阳重型机械厂旧址位于沈阳市铁西区，是新中国重型工业的摇篮，也是阿耐长篇小说《大江东去》中东北国企改革的原型参考地。工厂始建于上世纪五十年代，曾是中国最大的重型机械制造企业之一，老厂区保留着苏式厂房、巨型龙门吊与运输铁轨。阿耐笔下宋运辉等人在改革开放浪潮中的奋斗与抉择，与东北老工业基地的转型阵痛紧密相连。厂房内老式机床沉默矗立，车间外野草从铁轨缝隙中探出头来，秋日夕阳映照红砖墙面，更添一份工业时代落幕的悲壮。这里是了解东北国企改革历史与中国工业转型的重要遗址。', '辽宁', 41.802800, 123.348900, '其他', '["https://img0.baidu.com/it/u=1374563690,2364093717&fm=253&fmt=auto&app=120&f=JPEG?w=1080&h=800"]'),
('《杨靖宇将军》', '白山市靖宇县保安村三道崴子殉国地', '郭澄清', '现代', '三道崴子殉国地位于白山市靖宇县保安村，是抗日民族英雄杨靖宇将军1940年2月23日壮烈牺牲的地方。杨靖宇孤身一人与日寇周旋数日，最终在弹尽粮绝中英勇就义，日军剖开其腹部只发现树皮与棉絮。殉国地保留着纪念碑、纪念亭与杨靖宇将军的塑像，周边松柏苍翠、庄严肃穆。每年二月二十三日与清明节，前来祭奠的群众络绎不绝。郭澄清等作家以这段历史为素材创作了感人至深的文学作品。冬季白雪覆盖山林，寒风呼啸，更能体会英雄当年在冰天雪地中坚持战斗的悲壮，是中国最令人动容的红色纪念地之一。', '吉林', 42.388200, 126.810200, '其他', '["https://img1.baidu.com/it/u=621585899,2822422614&fm=253&fmt=auto&app=138&f=JPEG?w=667&h=500"]'),
('《赵尚志》', '鹤岗市萝北县梧桐河赵尚志牺牲地', '王忠瑜', '现代', '梧桐河赵尚志牺牲地位于鹤岗市萝北县，是抗日民族英雄赵尚志将军1942年2月12日被叛徒出卖后壮烈牺牲的地方。赵尚志是东北抗联第三军军长，一生戎马，九死一生，最终在这片冰封的河畔倒下。牺牲地保留着纪念碑、纪念亭与英雄事迹陈列，松花江支流梧桐河在冬季冰封如镜，两岸白桦林寂静无声。王忠瑜等作家以赵尚志的传奇一生为素材创作了大量文学作品，将这位民族英雄的形象深深铭刻在国人心中。这里地处偏远，游客稀少，冬日苍茫大地更显英雄气概，是缅怀抗联先烈的庄严之地。', '黑龙江', 47.576000, 130.832600, '其他', '["https://img2.baidu.com/it/u=731620674,3810343088&fm=253&fmt=auto&app=138&f=JPEG?w=667&h=500"]'),
('《八女投江》', '牡丹江市林口县刁翎镇三家子村', '颜一烟', '现代', '三家子村位于牡丹江市林口县刁翎镇，是1938年八女投江壮举的发生地。八位东北抗联女战士在弹尽粮绝后，面对日寇围追堵截，宁死不屈，挽臂投入乌斯浑河。颜一烟等作家以这段悲壮历史为素材创作了大量文学作品。遗址保留着抗联密营遗址、纪念碑与八女投江纪念馆，乌斯浑河在山谷间静静流淌，两岸群山肃穆。每年清明时节，前来祭奠的群众在河边献上鲜花与挽联。夏日河水清澈、山花烂漫，冬季冰封千里、寂静庄严，是中国最感人的女性革命纪念地之一，承载着不屈的民族精神。', '黑龙江', 45.278800, 130.284400, '其他', '["https://img2.baidu.com/it/u=160467685,1158966937&fm=253&fmt=auto?w=1325&h=800"]'),
('《林海雪原》', '牡丹江市海林市横道河子镇威虎山影视城', '曲波', '现代', '威虎山影视城位于牡丹江市海林市横道河子镇，是根据曲波长篇小说《林海雪原》打造的影视拍摄基地。影视城按照小说描写1比1还原了夹皮沟村、土匪窝、威虎厅等经典场景，使杨子荣智取威虎山的传奇故事有了最直观的视觉呈现。横道河子镇本身便是一座百年古镇，保留着大量俄式木屋建筑与中东铁路遗迹。影视城依山傍水，冬季白雪覆盖，与小说中描绘的林海雪原场景高度契合。夏日山林苍翠、溪水潺潺，秋天红叶满山，是体验红色经典文学与东北民俗文化的综合性旅游景点。', '黑龙江', 44.574900, 129.380400, '其他', '["https://img2.baidu.com/it/u=967042366,256780821&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《暴风骤雨》', '哈尔滨市尚志市元宝镇元宝山', '周立波', '现代', '元宝山位于哈尔滨市尚志市元宝镇，是周立波长篇小说《暴风骤雨》中农民运动的重要背景地。元宝山因形似元宝而得名，山脚下便是土地改革运动的原型村庄元宝村。山上保留着土改纪念碑与观景台，站在山顶可俯瞰整个元宝村与周围广袤的黑土地。周立波笔下农民们分田分地、翻身做主人的壮烈场景，便在这片山脚下的土地上真实发生。夏日山坡绿草如茵、田间稻浪翻滚，秋季金黄遍野、丰收在望，冬季白雪覆盖，大地沉寂。这里是了解中国土地改革运动发源地与东北乡村自然风貌的重要文化景观。', '黑龙江', 45.209600, 127.960200, '其他', '["https://img1.baidu.com/it/u=3484830338,2193878227&fm=253&fmt=auto&app=138&f=JPEG?w=761&h=500"]'),
('《车间主任》', '沈阳市铁西区沈阳机床厂老厂区', '谈歌', '现代', '沈阳机床厂老厂区位于沈阳市铁西区，是新中国机床工业的摇篮，也是谈歌中篇小说《车间主任》中东北国企工人生活的原型地。工厂始建于1935年，新中国成立后发展为亚洲最大的机床制造企业。老厂区保留着苏式厂房、巨型车间与运输铁轨，车间内老式机床排列整齐，虽已停产却仍气势恢宏。谈歌笔下那位在国企改革阵痛中坚守岗位的车间主任形象，正是无数东北工人的真实写照。厂区内红砖墙上标语斑驳，铁轨间野草丛生，秋日夕阳映照老厂房，更添一份工业时代的悲壮与温情。', '辽宁', 41.802800, 123.348900, '其他', '["https://img0.baidu.com/it/u=1374563690,2364093717&fm=253&fmt=auto&app=120&f=JPEG?w=1080&h=800"]'),
('《大厂》', '长春市朝阳区一汽老厂区', '谈歌', '现代', '一汽老厂区位于长春市朝阳区，是新中国汽车工业的发源地，也是谈歌小说《大厂》中汽车工业改革的原型参考地。1953年第一汽车制造厂在这里奠基，毛泽东亲笔题写厂名，1956年第一辆国产解放牌卡车在这里驶下生产线。老厂区保留着苏式办公楼、总装车间与一汽纪念馆，厂门前的解放卡车雕塑成为城市地标。谈歌笔下大型国企在市场经济冲击下的阵痛与转型，在一汽的历史中找到了最真实的注脚。厂区内林荫道宽阔、银杏金黄，是感受共和国汽车工业发展史与东北老工业基地精神的重要遗址。', '吉林', 39.921000, 116.486400, '其他', '["https://img1.baidu.com/it/u=3815439295,2168116161&fm=253&fmt=auto&app=138&f=JPEG?w=686&h=500"]'),
('《掌心化雪》', '呼伦贝尔市新巴尔虎右旗呼伦湖西岸', '鲍尔吉・原野', '现代', '呼伦湖西岸位于呼伦贝尔市新巴尔虎右旗，是鲍尔吉·原野散文集《掌心化雪》中草原生活的真实背景地。呼伦湖是内蒙古第一大湖，湖面辽阔如海，西岸远离景区核心，保留着最原始的草原与湖泊风貌。蒙古族牧民的传统蒙古包散落在湖畔草原上，牛羊悠然觅食，骏马奔腾在天际线上。鲍尔吉·原野以诗意的笔触记录了这片草原上的风、雪、花与人，每一个细节都充满了对大地的深情。夏日湖水碧蓝、草原翠绿，秋季芦苇金黄、候鸟南飞，冬季冰封万里、银装素裹，是体验蒙古高原壮美与草原文学灵魂的纯净之地。', '内蒙古', 48.665000, 116.823700, '其他', '["https://img2.baidu.com/it/u=2314130269,4047417305&fm=253&fmt=auto&app=138&f=JPEG?w=1067&h=800"]'),
('《草原》', '呼伦贝尔市陈巴尔虎旗莫日格勒河草原', '老舍', '现代', '莫日格勒河草原位于呼伦贝尔市陈巴尔虎旗，被誉为天下第一曲水，也是老舍散文《草原》中描绘的真实场景地。莫日格勒河蜿蜒曲折流淌在广袤草原上，据说全长二百余公里的河道直线距离仅十余公里，弯曲程度令人叹为观止。老舍笔下天苍苍、野茫茫的壮阔画面，在这里得到了最完美的呈现。夏日草原碧绿如毯、河水如银带飘飞，蒙古族牧民骑马赶着牛羊在河畔草原上游牧。秋季草色渐黄、长空万里，冬季白雪茫茫、大地苍凉。这里是中国最典型的草原景观之一，是感受草原文化与自然之美的圣地。', '内蒙古', 49.326900, 119.425700, '其他', '["https://img2.baidu.com/it/u=1963325002,558528002&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《百炼成钢》', '鞍山市铁西区鞍钢老厂区', '艾芜', '现代', '鞍钢老厂区位于鞍山市铁西区，是新中国钢铁工业的摇篮，也是艾芜长篇小说《百炼成钢》中钢铁工人生活的原型地。鞍山钢铁公司始建于日据时期，新中国成立后成为全国最大的钢铁联合企业。老厂区保留着上世纪五十年代的炼钢高炉、轧钢车间与运输铁轨，巨型烟囱直插云霄，车间内炉火曾日夜不息。艾芜笔下那些在高温炉前挥汗如雨的钢铁工人，正是新中国工业化进程中最光辉的群体。厂区内铁水映红的记忆虽已远去，但老式设备的轮廓依然震撼人心，是了解共和国钢铁工业发展史与东北工人精神的重要工业遗产。', '辽宁', 41.119700, 122.957700, '其他', '["https://img1.baidu.com/it/u=1127862558,860635446&fm=253&fmt=auto&app=138&f=JPEG?w=894&h=500"]'),
('《八级工匠》', '大连市甘井子区大连造船厂老厂区', '邓刚', '现代', '大连造船厂老厂区位于大连市甘井子区，是中国重要的造船基地，也是邓刚中篇小说《八级工匠》中造船工人生活的原型地。大连造船厂始建于1898年，历经沙俄、日本占领与新中国建设，是中国海军舰艇的重要生产基地。老厂区保留着巨型船坞、龙门吊与百年船台，海风中锈蚀的钢铁散发着工业时代的气息。邓刚笔下那位技艺精湛的八级工匠形象，正是无数造船工人精益求精精神的缩影。船坞内巨轮身影依稀可辨，海浪拍打着石砌码头，黄昏时分落日映照船台，是感受中国百年造船工业史与大国工匠精神的震撼之地。', '辽宁', 38.953000, 121.525700, '其他', '["https://img0.baidu.com/it/u=2474908948,3946428016&fm=253&fmt=auto&app=138&f=JPEG?w=646&h=500"]'),
('《沸腾的群山》', '抚顺市抚顺西露天矿旧址', '李云德', '现代', '抚顺西露天矿旧址位于抚顺市，是亚洲最大的露天煤矿，也是李云德长篇小说《沸腾的群山》中煤矿工人生活的原型地。这座矿坑始于清代，日据时期被疯狂掠夺，新中国成立后成为国家能源建设的重要基地。矿坑长达六千余米、深逾四百米，站在矿坑边缘俯瞰，层层环绕的矿道如同大地的年轮，令人震撼。李云德笔下那些在矿山上日夜奋战的煤矿工人，便在这座巨大的矿坑中挥洒着青春与汗水。如今矿坑已部分转型为矿山公园，保留着采矿设备与运输铁轨，是了解中国煤矿工业发展史的独特工业景观。', '辽宁', 41.880600, 123.957300, '其他', '["https://img2.baidu.com/it/u=2005794570,1619402947&fm=253&fmt=auto&app=138&f=JPEG?w=1199&h=800"]'),
('《五月的矿山》', '阜新市海州露天矿国家矿山公园', '萧军', '现代', '海州露天矿国家矿山公园位于阜新市，是新中国第一个大型机械化露天煤矿，也是萧军散文《五月的矿山》中煤矿建设的原型地。矿坑面积达七平方公里，深三百余米，是中国工业化初期的标志性工程。萧军以激昂的笔触记录了五十年代矿山建设的火热场景，矿工们驾驶着苏联援助的大型采矿设备在矿坑中日夜奋战。如今矿坑已停产并转型为国家矿山公园，保留着巨型电镐、运输铁路与矿区建筑。站在矿坑观景台上，层层叠叠的矿道环绕而下，如同大地的伤疤，既震撼又令人深思，是了解中国煤矿工业历史与资源型城市转型的珍贵遗址。', '辽宁', 42.011800, 121.648600, '其他', '["https://img2.baidu.com/it/u=1753575175,1981948421&fm=253&fmt=auto&app=138&f=JPEG?w=753&h=500"]'),
('《乘风破浪》', '齐齐哈尔市富拉尔基区中国一重老厂区', '草明', '现代', '中国一重老厂区位于齐齐哈尔市富拉尔基区，是新中国重型装备制造业的摇篮，也是草明长篇小说《乘风破浪》中重型机械工人生活的原型地。工厂始建于1954年，是中国第一台万吨水压机的诞生地。老厂区保留着苏式厂房、巨型锻压设备与运输铁轨，车间内巨型水压机高耸如山，令人叹为观止。草明笔下那些在重型机械前乘风破浪的工人们，正是新中国工业化进程中最豪迈的群体。厂区内嫩江从侧旁流过，冬季冰封千里，夏日绿树成荫，是感受共和国重型装备制造史与东北工业精神的重要遗址。', '黑龙江', 47.208300, 123.638400, '其他', '["https://img0.baidu.com/it/u=497755600,865215657&fm=253&fmt=auto&app=138&f=JPEG?w=792&h=500"]'),
('《观书有感・其一》', '三明市尤溪县朱熹故居半亩方塘', '朱熹', '南宋', '朱熹故居半亩方塘位于三明市尤溪县，是南宋理学大师朱熹的出生地，也是千古名句问渠那得清如许、为有源头活水来的诞生地。半亩方塘保留着宋代池塘原貌，一泓清水碧绿如玉，池中天光云影共徘徊，正如诗中所描绘的意境。朱熹故居周边保留着宋代建筑遗存、手书碑刻与朱子文化展馆，庭院中古树参天、石径幽深。尤溪县位于闽中山区，四周群山环抱、溪流纵横，保留着闽中传统村落的质朴风貌。春日山花烂漫、秋季丹桂飘香，是体验朱子理学发源地文化底蕴与闽中山水之美的清幽之地。', '福建', 26.169900, 118.190700, '其他', '["https://img0.baidu.com/it/u=144461194,3444277850&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=500"]');
INSERT INTO works (title, scenic_spot, author, dynasty, description, province, latitude, longitude, category, images) VALUES
('《武夷茶歌》', '南平市武夷山市九曲溪古筏码头', '范仲淹', '北宋', '九曲溪古筏码头位于南平市武夷山市，是北宋名臣范仲淹《武夷茶歌》中年年春自东南来、建溪先暖冰微开的真实描绘地。古筏码头是武夷山九曲溪竹筏漂流的起点，溪畔保留着宋代摩崖石刻与千年古樟，古筏系缆的石桩历经千年风雨仍屹立溪边。武夷山是中国乌龙茶与红茶的发源地，范仲淹以诗歌赞美了武夷茶的清香与山水的秀美。九曲溪水清澈见底，两岸丹霞峰峦倒映水中，竹筏顺流而下，移步换景。春日茶山翠绿、夏季溪水清凉、秋天丹桂飘香、冬季山色空濛，是体验武夷茶文化与丹霞山水诗意的绝佳之地。', '福建', 27.756400, 118.035300, '其他', '["https://img2.baidu.com/it/u=1956338070,2171013661&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=752"]'),
('《洛阳桥》', '泉州市洛江区洛阳桥万安渡遗址', '蔡襄', '北宋', '洛阳桥万安渡遗址位于泉州市洛江区，是北宋名臣蔡襄《洛阳桥》中跨海飞梁叠石成、晓风十里渡瑶琼的创作地。洛阳桥始建于北宋皇祐五年（1053年），由蔡襄主持修建，是中国第一座跨海大石桥，开创了筏型基础与种蛎固基的工程技术。桥长八百余米，桥面铺以巨型花岗岩条石，两侧石将军威武矗立，古碑刻记载着千年建桥传奇。大桥横跨洛阳江入海口，潮起潮落间桥墩上牡蛎密布，正是古人以生物固桥的智慧结晶。黄昏时分桥上远眺，江海交汇处波光粼粼，是感受宋代桥梁工程奇迹与海丝文化的世界遗产。', '福建', 24.940000, 118.671400, '其他', '["https://img0.baidu.com/it/u=2542718452,195642776&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《登鼓山》', '福州市晋安区鼓山喝水岩', '蔡襄', '北宋', '鼓山喝水岩位于福州市晋安区，是北宋名臣蔡襄《登鼓山》中郡楼千尺倚崔嵬、万里风烟入望来的描绘地。喝水岩得名于传说中高僧一声断喝使泉水改道的故事，岩壁上保留着自宋至清的摩崖石刻数百方，蔡襄、朱熹等名家题刻荟萃，堪称石刻书法艺术的露天博物馆。岩下古泉清冽甘甜，游客可掬水品味。鼓山海拔九百余米，从喝水岩上望，福州城与闽江尽收眼底，正如蔡襄诗中所描绘的万里风烟。春日杜鹃盛开、夏季林荫蔽日、秋天桂花飘香、冬季云雾缭绕，是品鉴宋代书法石刻与俯瞰福州全城的文化胜地。', '福建', 26.081800, 119.328400, '其他', '["https://img0.baidu.com/it/u=3345262988,827325829&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《泉州》', '泉州市鲤城区开元寺镇国塔', '王十朋', '南宋', '开元寺镇国塔位于泉州市鲤城区，是南宋诗人王十朋《泉州》中泉州古城山作屏、紫云双塔插天青的核心取景地。开元寺始建于唐垂拱二年（686年），寺内东西双塔（镇国塔与仁寿塔）是中国现存最高的石质塔楼，高达四十余米，历经千年地震而不倒。塔身浮雕精美绝伦，人物花鸟栩栩如生，是宋代石雕艺术的巅峰之作。开元寺还保留着唐代大殿、宋代石经幢与古榕树，千年古刹香烟缭绕。泉州作为海上丝绸之路起点城市，开元寺见证了中外文化的交融，是感受闽南佛教文化与海丝遗产的世界级文化瑰宝。', '福建', 24.907600, 118.587300, '其他', '["https://img0.baidu.com/it/u=2094867896,2212442238&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《太姥山》', '宁德市福鼎市太姥山夫妻峰', '谢灵运', '南北朝', '太姥山夫妻峰位于宁德市福鼎市，是南北朝诗人谢灵运《太姥山》中太姥山高插天碧、海上三山落平地的描绘地。太姥山矗立于东海之滨，主峰覆鼎峰海拔九百余米，山上奇石嶙峋、洞穴幽深，有三十六峰、四十五石之说。夫妻峰两石相依，形似一对恩爱夫妻，是太姥山最具代表性的景观之一。谢灵运作为中国山水诗鼻祖，曾多次游历闽东山水。山上保留着唐代白云寺与历代摩崖石刻，云雾缭绕时恍若仙境。春日杜鹃映红山谷、夏季云海翻腾、秋天层林尽染、冬季偶有雾凇，是体验闽东海岸山岳之美与山水诗意境的壮美之地。', '福建', 27.324600, 120.216400, '其他', '["https://img1.baidu.com/it/u=329139446,1883711657&fm=253&fmt=auto&app=138&f=JPEG?w=750&h=500"]'),
('《清源山》', '泉州市丰泽区清源山老君岩', '朱熹', '南宋', '清源山老君岩位于泉州市丰泽区，是南宋理学大师朱熹题咏清源山、闽海蓬莱第一山的名胜之地。老君岩是中国现存最大的道教石雕老子坐像，高五点六三米，雕刻于宋代，老子面容慈祥、神态自若，衣褶飘逸如风。朱熹曾在清源山讲学授徒，留下了深厚的理学文化印记。清源山海拔五百余米，山上奇石遍布、古木参天，保留着宋代道教石刻、唐代古寺与历代名人题刻。山间泉水潺潺、茶园翠绿，是泉州人休闲品茗的后花园。春日山花烂漫、秋天桂花飘香，是感受道教文化与闽南山水雅趣的清幽之地。', '福建', 24.891200, 118.613000, '其他', '["https://img0.baidu.com/it/u=3036220086,3326511541&fm=253&fmt=auto&app=120&f=JPEG?w=667&h=500"]'),
('《土楼》', '龙岩市永定区初溪土楼群集庆楼', '郭沫若', '现代', '初溪土楼群集庆楼位于龙岩市永定区，是郭沫若赞叹土楼不土洋楼羞的闽西客家土楼杰作。集庆楼建于明永乐年间，距今已逾六百年，是初溪土楼群中最古老、最宏伟的圆形土楼。楼高四层，外径六十余米，楼内七十二个独立单元各设楼梯，是客家土楼中绝无仅有的设计。土楼以生土夯筑而成，墙厚近两米，冬暖夏凉，具有极强的防御功能。初溪土楼群坐落在山谷之中，周围梯田层叠、溪流环绕，保留着最原始的客家村落风貌。春日山花烂漫、秋季稻浪金黄，是体验客家土楼建筑智慧与闽西乡村田园之美的世界遗产。', '福建', 24.723100, 116.732000, '其他', '["https://img0.baidu.com/it/u=2429916649,4257152599&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1200"]'),
('《湄洲岛》', '莆田市秀屿区湄洲岛鹅尾神石园', '林则徐', '清代', '湄洲岛鹅尾神石园位于莆田市秀屿区，是清代民族英雄林则徐题咏海上女神护苍生、湄洲香火遍寰瀛的场景地。鹅尾神石园位于湄洲岛最南端，因形似鹅尾而得名，海蚀地貌千姿百态，奇石如天然雕塑散落海滨。湄洲岛是妈祖文化的发源地，每年吸引全球数百万妈祖信众朝圣。林则徐曾在闽地为官多年，对妈祖信仰有深厚感情。神石园内海浪拍打礁石，浪花飞溅，退潮时可在礁石间拾贝。春日海风和煦、夏季碧海蓝天、秋天潮音阵阵、冬季海浪壮观，是体验妈祖文化与闽海自然奇观的独特之地。', '福建', 25.318700, 119.092700, '其他', '["https://img1.baidu.com/it/u=3247193713,295367556&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=875"]'),
('《冠豸山》', '龙岩市连城县冠豸山竹安寨', '纪晓岚', '清代', '冠豸山竹安寨位于龙岩市连城县，是清代大学士纪晓岚赞叹连城山水甲闽西、冠豸雄奇天下稀的名胜之地。竹安寨建于明代，是客家先民避乱的山寨，寨墙依悬崖而建，地势险要、一夫当关万夫莫开。冠豸山因主峰形似古代法官所戴獬豸冠而得名，以丹霞地貌闻名，赤壁丹崖、奇峰怪石错落有致。寨内保留着明代古寨门、摩崖石刻与幽深峡谷，一线天仅容一人侧身通过。山上清泉飞泻、古木参天，春日杜鹃映红崖壁、夏季绿荫蔽日、秋天丹枫如火、冬季云雾缭绕，是体验闽西丹霞奇观与客家山寨文化的壮美之地。', '福建', 25.710400, 116.754600, '其他', '["https://img1.baidu.com/it/u=3406291588,3211623958&fm=253&fmt=auto&app=120&f=JPEG?w=667&h=500"]'),
('《东山岛》', '漳州市东山县铜山古城', '黄道周', '明代', '铜山古城位于漳州市东山县，是明代学者黄道周题咏风吹一石万钧动、摇落千年不记秋的场景地。铜山古城始建于明洪武年间，是明代海防重镇，城墙依山傍海而建，保留着明代城门、古炮台与石刻。城内最著名的风动石重约二百吨，矗立于海滨悬崖之上，风起时微微摇晃却千年不倒，被誉为天下第一奇石。黄道周是明末大儒与民族英雄，其故里便在东山岛，故城中留有大量与其相关的遗迹。古城外碧海蓝天、沙滩绵延，渔船点点，是感受明代海防历史与闽南海岛风光的独特之地。', '福建', 23.701400, 117.428200, '其他', '["https://img2.baidu.com/it/u=2444242117,2052591069&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《金湖》', '三明市泰宁县大金湖甘露寺', '朱熹', '南宋', '大金湖甘露寺位于三明市泰宁县，是南宋理学大师朱熹赞叹泰宁山水甲天下、金湖风光胜画图的著名景点。甘露寺始建于宋绍兴年间，是一座悬空寺庙，仅以一根巨型木柱支撑于两峰之间的岩洞中，建筑奇巧令人叹为观止。大金湖是福建最大的人工湖泊，湖面浩渺，两岸丹霞峰峦倒映水中，碧水丹山交相辉映。朱熹曾在泰宁讲学，对这里的山水赞不绝口。乘船游湖，移步换景，春日山花映水、夏季碧波荡漾、秋天层林尽染、冬季烟雨朦胧，是体验丹霞水上风光与宋代悬空建筑奇观的绝佳之地。', '福建', 26.900000, 117.176000, '其他', '["https://img2.baidu.com/it/u=3907595279,2183250327&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1065"]'),
('《安平桥》', '泉州市晋江市安平桥遗址', '朱熹', '南宋', '安平桥遗址位于泉州市晋江市，是南宋理学大师朱熹题咏天下无桥长此桥的古代桥梁奇迹。安平桥始建于南宋绍兴八年（1138年），全长两千余米，是中国现存最长的古代石桥，有五里桥之称。桥面以花岗岩条石铺就，桥墩形式多样，有方形、船形与半船形之分，体现了宋代高超的桥梁工程技术。桥上保留着宋代石塔、石将军与历代碑刻，桥两端各有古寺守护。潮起时桥下碧波荡漾，退潮后滩涂上红树林郁郁葱葱。这座千年古桥横跨安海湾，是感受宋代桥梁工程成就与泉州海丝文化的世界遗产。', '福建', 24.781500, 118.551900, '其他', '["https://img0.baidu.com/it/u=3677871187,1088630269&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=652"]'),
('《鸳鸯溪》', '宁德市屏南县鸳鸯溪白水洋', '陆游', '南宋', '鸳鸯溪白水洋位于宁德市屏南县，是南宋诗人陆游题咏鸳鸯溪畔水悠悠、两岸青山锁碧流的自然奇观。白水洋是一块面积达八万平方米的巨型花岗岩河床，溪水在平坦的岩面上薄薄流淌，水深仅没脚踝，被誉为天下绝景万米水上广场。鸳鸯溪因每年秋冬有数千对鸳鸯在此栖息越冬而得名，是中国最大的鸳鸯栖息地。溪谷两岸原始森林茂密，瀑布从悬崖上飞泻而下，清潭碧绿如翡翠。夏日游客赤脚在浅水岩面上嬉戏，秋天鸳鸯成群结对戏水，是体验闽东山水奇观与珍稀鸟类生态的独特之地。', '福建', 26.908500, 118.985900, '其他', '["https://img2.baidu.com/it/u=1471260105,2332369674&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=556"]'),
('《鼓浪屿》', '厦门市思明区鼓浪屿日光岩郑成功水操台', '郑成功', '明代', '鼓浪屿日光岩郑成功水操台位于厦门市思明区，是明代民族英雄郑成功训练水师、收复台湾的重要军事遗址。水操台位于日光岩顶，海拔九十余米，是鼓浪屿最高点，站在台上可俯瞰整个厦门港与台湾海峡。郑成功曾在此练兵操演水师，留下了开辟荆榛逐荷夷、十年始克复先基的豪迈诗句。岩壁上保留着明代摩崖石刻与古炮台遗迹，巨石嶙峋间古榕盘根错节。鼓浪屿万国建筑博览与海上花园的美誉举世闻名，日光岩更是其精华所在。黄昏时分金色阳光洒满海面，是感受郑成功抗荷精神与鼓浪屿海岛风情的必游之地。', '福建', 24.445400, 118.082300, '其他', '["https://img2.baidu.com/it/u=1587615128,3259149511&fm=253&fmt=auto&app=138&f=JPEG?w=752&h=500"]'),
('《台湾竹枝词》', '台南市安平区安平古堡', '沈光文', '清代', '安平古堡位于台南市安平区，是清代文人沈光文《台湾竹枝词》中台湾西望海漫漫、万里烟波接远天的描绘地。安平古堡原名热兰遮城，由荷兰殖民者建于1624年，是台湾最古老的城堡。1662年郑成功收复台湾后将此作为王城，见证了台湾从殖民到回归的重要历史。古堡保留着荷兰时期的城墙残迹、清代纪念碑与瞭望塔，红砖墙上布满岁月的痕迹。沈光文被誉为台湾文学之祖，其竹枝词记录了早期台湾的风土人情。古堡外安平老街古朴热闹，黄昏时分登塔远眺台湾海峡，波光粼粼，是了解台湾开发史与海峡文化的重要古迹。', '台湾', 22.993700, 120.166100, '其他', '["https://img2.baidu.com/it/u=212624143,3419957943&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1336"]'),
('《春愁》', '台中市雾峰区雾峰林家花园', '丘逢甲', '清代', '雾峰林家花园位于台中市雾峰区，是清代爱国诗人丘逢甲《春愁》中春愁难遣强看山、往事惊心泪欲潸的创作地。林家花园是台湾最大的传统建筑群之一，始建于清咸丰年间，融合了闽南、客家与西洋建筑风格。丘逢甲在甲午战败、台湾割让日本后，悲愤写下此诗，字字泣血。花园保留着清代宅第、戏台、书院与园林，雕梁画栋精美绝伦。1999年九二一地震后经修复，更显历史厚重。园内古木参天、花草繁茂，是感受台湾近代伤痛史与清代闽台建筑艺术的重要文化遗产。', '台湾', 24.061400, 120.700000, '其他', '["https://img2.baidu.com/it/u=1993961065,1481649588&fm=253&fmt=auto&app=138&f=JPEG?w=750&h=500"]'),
('《阿里山》', '嘉义县阿里山乡阿里山森林铁路十字路站', '吴凤', '清代', '阿里山森林铁路十字路站位于嘉义县阿里山乡，是清代义士吴凤故事与阿里山高云作裳、森林万顷郁苍苍诗句的相关景点。阿里山森林铁路始建于日据时期，全长七十余公里，是世界仅存的三条登山铁路之一。十字路站海拔一千五百余米，保留着日式木造车站建筑与老式蒸汽火车。铁路穿越热带、亚热带与温带三个植被带，沿途桧木林、樱花林与云海美不胜收。火车在蜿蜒的山间铁道上缓缓爬升，汽笛声回荡在万顷森林中。春日樱花盛开、夏季绿荫蔽日、秋天枫红层染、冬季云雾缭绕，是体验阿里山森林文化与高山铁路之美的独特之地。', '台湾', 23.480000, 120.574000, '其他', '["https://img1.baidu.com/it/u=649131968,1159817696&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=733"]'),
('《日月潭》', '南投县鱼池乡日月潭玄奘寺', '蒋介石', '现代', '日月潭玄奘寺位于南投县鱼池乡，是日月潭水碧于天、两岸青山锁翠烟诗意描绘的重要景点。玄奘寺坐落于日月潭畔青龙山上，供奉着唐代高僧玄奘的舍利子，是台湾佛教的重要圣地。日月潭是台湾最大的天然湖泊，因潭面以拉鲁岛为界，北半部形如日轮、南半部状似月钩而得名。从玄奘寺远眺，湖面碧波荡漾，四周群山环抱，晨昏变幻间湖水呈现不同色彩。寺内古木参天、钟声悠扬，保留着珍贵的佛教文物。春日湖畔山樱花盛开、夏季碧水青山、秋天枫叶映湖、冬季薄雾轻笼，是感受台湾高山湖泊之美与佛教文化的清幽胜地。', '台湾', 23.749800, 120.683700, '其他', '["https://img1.baidu.com/it/u=3132313108,827481726&fm=253&fmt=auto&app=138&f=JPEG?w=712&h=472"]'),
('《垦丁》', '屏东县恒春镇垦丁鹅銮鼻灯塔', '连横', '清代', '垦丁鹅銮鼻灯塔位于屏东县恒春镇，是清代史家连横《垦丁》中鹅銮鼻上望沧溟、万里波涛接杳冥的描绘地。鹅銮鼻灯塔建于清光绪八年（1882年），是台湾最南端的灯塔，也是远东地区最大的灯塔之一，因曾配备武装防御设施而有东亚之光的美誉。灯塔白色圆柱体矗立于珊瑚礁岩之上，塔下热带植物茂密、海岸线蜿蜒曲折。站在灯塔旁远眺，巴士海峡与太平洋在此交汇，碧海蓝天无际。日出时分金光洒满海面，黄昏灯塔亮起，是感受台湾南端热带海洋风光与清代海防历史的壮美之地。', '台湾', 22.682800, 120.488100, '其他', '["https://img0.baidu.com/it/u=77597486,1857345885&fm=253&fmt=auto&app=138&f=JPEG?w=836&h=500"]'),
('《淡水》', '新北市淡水区淡水红毛城', '林则徐', '清代', '淡水红毛城位于新北市淡水区，是清代民族英雄林则徐相关诗句淡水河边古戍楼、夕阳无语照汀洲的描绘地。红毛城始建于1628年，由西班牙人兴建，后经荷兰人改建，是台湾现存最古老的欧式建筑之一。城堡红砖外墙厚达两米，城楼上铸铁古炮指向淡水河口，见证了台湾四百年来的殖民与抗争历史。城堡旁英国领事官邸为维多利亚式建筑，红砖拱廊优雅别致。淡水河在此汇入台湾海峡，黄昏时分夕阳西下，河面金光闪烁，被誉为台湾八景之一。这里是了解台湾殖民历史与欣赏淡水夕照的必游之地。', '台湾', 25.169400, 121.448600, '其他', '["https://img1.baidu.com/it/u=2339573130,1158581928&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《九份》', '新北市瑞芳区九份竖崎路', '三毛', '现代', '九份竖崎路位于新北市瑞芳区，是三毛等作家笔下充满乡愁与怀旧气息的山城老街。竖崎路是九份最具代表性的石阶古道，两旁日式木造建筑鳞次栉比，红灯笼高挂，茶馆飘出阵阵茶香。九份曾因金矿开采而繁华一时，矿业衰落后沉寂多年，后因电影《悲情城市》而重新被世人发现。三毛曾描写九份的黄昏是一杯浓浓的乡愁，石阶上远眺基隆港与东海，山城灯火与海上渔火交相辉映。春日山花绽放、夏季海风清凉、秋天云雾缭绕、冬季细雨纷飞，是体验台湾矿山文化与怀旧美学的浪漫之地。', '台湾', 25.109200, 121.810400, '其他', '["https://img2.baidu.com/it/u=1362791461,4126465795&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1042"]'),
('《鹿港》', '彰化县鹿港镇鹿港龙山寺', '余光中', '现代', '鹿港龙山寺位于彰化县鹿港镇，是现代诗人余光中相关作品中鹿港的钟声、敲打着千年的乡愁意象的所在地。龙山寺始建于明永历年间，是台湾保存最完整的清代寺庙建筑，木雕、石雕与交趾陶工艺精美绝伦，被誉为台湾紫禁城。鹿港曾是台湾最繁华的港口城市，有一府二鹿三艋舺之说。余光中等作家以鹿港为意象，寄托了对中华传统文化的眷恋与海峡两岸的乡愁。龙山寺内梵音缭绕、香火鼎盛，寺外老街古朴热闹，传统糕点与手工艺品琳琅满目。这里是感受台湾传统信仰文化与鹿港历史风华的重要古迹。', '台湾', 24.051800, 120.516100, '其他', '["https://img2.baidu.com/it/u=1629861351,1801375165&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《太鲁阁》', '花莲县秀林乡太鲁阁峡谷九曲洞', '杨牧', '现代', '太鲁阁峡谷九曲洞位于花莲县秀林乡，是现代诗人杨牧作品中太鲁阁的山是大地的脊梁意象的壮美实景。九曲洞是太鲁阁峡谷最险峻的路段，步道凿穿大理石岩壁，头顶悬崖千仞，脚下立雾溪奔腾咆哮。太鲁阁峡谷由立雾溪历经千万年切割而成，峡谷两壁大理石纹路清晰可见，白色岩壁与碧绿溪水形成强烈对比。杨牧生于花莲，对太鲁阁的山水有着深沉的情感寄托。步道全长约两公里，穿行在隧道与明洞之间，光影变幻如梦似幻。这里是台湾最壮观的峡谷景观，也是感受大自然鬼斧神工与台湾地质之美的震撼之地。', '台湾', 23.976900, 121.601700, '其他', '["https://img1.baidu.com/it/u=447267774,1323162287&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《澎湖》', '澎湖县马公市澎湖天后宫', '郑成功', '明代', '澎湖天后宫位于澎湖县马公市，是明代民族英雄郑成功相关诗句澎湖岛外水连天、万顷波涛起暮烟的描绘地。澎湖天后宫始建于明代万历年间，是台湾最古老的妈祖庙，也是全台湾历史最悠久的寺庙之一。宫内保留着宋代妈祖神像、明清古碑与精美木雕，香火鼎盛、梵音不绝。郑成功曾以澎湖为跳板收复台湾，天后宫见证了这段波澜壮阔的历史。宫外澎湖湾碧海蓝天，渔船点点，退潮时珊瑚礁滩五彩斑斓。夏日阳光灿烂、冬季东北季风强劲，是感受澎湖海洋文化与妈祖信仰的精神圣地。', '台湾', 23.566000, 119.566500, '其他', '["https://img2.baidu.com/it/u=4040583057,1669254854&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《宜兰》', '宜兰县宜兰市冬山河亲水公园', '龙应台', '现代', '冬山河亲水公园位于宜兰县宜兰市，与现代作家龙应台散文中冬山河的水流淌着台湾的乡愁意象相关联。冬山河是兰阳平原上最美的河流，经过整治后成为台湾亲水休闲的典范。公园内河道蜿蜒、草坪开阔，夏日举办的宜兰国际童玩艺术节吸引无数游客。龙应台以细腻笔触书写了台湾土地上的记忆与情感，冬山河畔的宁静田园正是这种乡愁的物质载体。河水清澈见底，两岸稻田在微风中翻起绿浪，远处雪山山脉若隐若现。春日油菜花金黄、夏季绿意盎然、秋天稻穗低垂、冬季水鸟群集，是体验宜兰田园风光与台湾乡土情怀的宁静之地。', '台湾', 24.757000, 121.758000, '其他', '["https://img0.baidu.com/it/u=889719383,297920993&fm=253&fmt=auto&app=138&f=JPEG?w=889&h=500"]'),
('《花莲》', '花莲县花莲市七星潭', '席慕蓉', '现代', '七星潭位于花莲县花莲市，是现代诗人席慕蓉作品中七星潭的浪是大海的心跳意象的真实海滨。七星潭并非潭而是一片弧形海湾，太平洋的海浪在此拍打着满是圆润鹅卵石的海滩，浪声如鼓、气势磅礴。背靠中央山脉，面朝浩瀚太平洋，山海之间形成了独特的壮阔景观。席慕蓉的诗歌充满了对美与自然的赞叹，七星潭的海浪、星空与山影正是这种诗意的完美注脚。清晨可观日出破晓、夜晚可赏漫天繁星，夏日海水湛蓝、冬季巨浪翻涌。海滩上鹅卵石在浪花退去时发出清脆的碰撞声，是感受太平洋壮美与花莲自然诗意的浪漫之地。', '台湾', 23.976900, 121.601700, '其他', '["https://img0.baidu.com/it/u=445971976,2063025614&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=875"]'),
('《金门》', '金门县金城镇金门莒光楼', '胡适', '现代', '金门莒光楼位于金门县金城镇，是现代学者胡适等人相关作品中莒光楼上望神州、万里河山一望收意象的所在地。莒光楼建于1952年，是金门最具代表性的地标建筑，融合了中国传统宫殿式建筑风格，红柱金瓦、飞檐翘角，气势庄严。楼内设有博物馆，陈列着金门历史文物、战地遗存与两岸关系史料。登楼远眺，对岸厦门的高楼大厦隐约可见，海峡两岸近在咫尺。金门曾是两岸军事对峙的前线，823炮战的炮弹如今被打造成金门菜刀闻名遐迩。这里是了解两岸历史关系与金门战地文化的重要纪念性建筑。', '台湾', 24.436300, 118.317500, '其他', '["https://img2.baidu.com/it/u=2541810192,2224080425&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=750"]'),
('《马祖》', '连江县南竿乡马祖天后宫', '余光中', '现代', '马祖天后宫位于连江县南竿乡，与现代诗人余光中作品中马祖的风吹着两岸的乡愁意象相关联。马祖天后宫相传建于宋代，供奉妈祖林默娘的肉身，是马祖列岛最重要的信仰中心。传说妈祖的遗体漂流至此被渔民安葬，马祖因此得名。天后宫保留着清代寺庙建筑与珍贵的妈祖神像，香火鼎盛。余光中等作家以马祖为意象，寄托了海峡两岸割不断的乡愁。宫外海风强劲，碧海环绕，闽东式石头古厝错落山间。夏日蓝天碧海、冬季东北季风呼啸，入夜后蓝眼泪（夜光藻）点亮海面，是感受马祖妈祖文化与海峡乡愁的神圣之地。', '台湾', 26.160000, 119.950000, '其他', '["https://img2.baidu.com/it/u=1593483408,189284394&fm=253&fmt=auto&app=138&f=JPEG?w=380&h=572"]'),
('《台湾通史・序诗》', '台北市中正区台北府城北门', '连横', '清代', '台北府城北门位于台北市中正区，是清代史家连横《台湾通史·序诗》中堂堂华夏气、耿耿照乾坤的描绘地。台北府城北门又名承恩门，建于清光绪十年（1884年），是台北府城现存唯一保持清代原貌的城门。北门为闽南式碉堡建筑，城楼红砖砌筑、燕尾屋脊飞扬，气势雄浑。连横以一生之力撰写《台湾通史》，寄托了对中华文化在台湾传承的深切期望，北门正是这种华夏气象的物质象征。城门周边经过景观重塑，成为台北西区历史地标。古老城门与现代都市形成强烈对比，是了解台湾近代城市发展史与中华文化认同的重要古迹。', '台湾', 25.032000, 121.519900, '其他', '["https://img0.baidu.com/it/u=1787750114,2043145405&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=333"]'),
('《繁星・春水》', '福州市鼓楼区杨桥路冰心故居', '冰心', '现代', '冰心故居位于福州市鼓楼区杨桥路，是现代文学大师冰心创作《繁星·春水》等经典作品的出生与成长之地。故居为典型的清代福州民居，三坊七巷风格，白墙灰瓦、飞檐翘角，庭院中古井、天井与花木保留着百年前的格局。冰心在这里度过了美好的童年时光，母爱、童真与大海成为她一生创作的永恒主题。故居内陈列着冰心的手稿、书信与生平照片，书房中仿佛还飘散着墨香。繁星闪烁在寂静的夜空，春水在指间流淌，冰心以最柔软的笔触温暖了无数读者的心灵。这里是了解冰心文学世界与福州三坊七巷文化的珍贵故居。', '福建', 26.081900, 119.303800, '其他', '["https://img1.baidu.com/it/u=1518112196,739491345&fm=253&fmt=auto&app=138&f=JPEG?w=751&h=500"]'),
('《京华烟云》', '漳州市芗城区天宝镇林语堂故居', '林语堂', '现代', '林语堂故居位于漳州市芗城区天宝镇，是现代文学大师林语堂的出生地，也是长篇小说《京华烟云》创作背景的重要参考地。林语堂被誉为两脚踏东西文化、一心评宇宙文章的文学巨匠，故居为典型的闽南传统建筑，红砖瓦房、燕尾脊飞扬，庭院中龙眼树与荔枝树浓荫蔽日。馆内陈列着林语堂的手稿、书信、照片与生平文物，书房中仿佛还飘散着烟斗的余味。《京华烟云》以北京为背景，但林语堂对故乡闽南的记忆深深融入了他的创作血脉。天宝镇四周青山环绕、溪流潺潺，是了解林语堂文学世界与闽南乡土文化的重要故居。', '福建', 24.510300, 117.654300, '其他', '["https://img2.baidu.com/it/u=1914632724,2697723725&fm=253&fmt=auto&app=138&f=JPEG?w=1067&h=800"]'),
('《致橡树》', '厦门市思明区鼓浪屿漳州路舒婷故居', '舒婷', '现代', '舒婷故居位于厦门市思明区鼓浪屿漳州路，是朦胧诗代表作《致橡树》的创作地。鼓浪屿上万国建筑错落有致，舒婷的故居便掩映在绿树花丛之中，欧式建筑优雅别致。舒婷在这座海岛上度过了青春年华，岛上的榕树、凤凰木与海浪声成为她诗歌创作的灵感源泉。我如果爱你，绝不像攀援的凌霄花——这首诗以独立、平等的爱情观震撼了一代人。故居内陈列着舒婷的手稿、书信与生平照片，窗外琴声悠扬、海风轻拂。鼓浪屿四季如春，花木繁茂，是感受朦胧诗歌温暖力量与鼓浪屿人文风情的文学圣地。', '福建', 24.445400, 118.082300, '其他', '["https://img1.baidu.com/it/u=2596480481,3476766021&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《皮囊》', '泉州市晋江市东石镇大房村', '蔡崇达', '现代', '大房村位于泉州市晋江市东石镇，是蔡崇达非虚构作品《皮囊》中作者的故乡与核心叙事空间。这座闽南小渔村保留着传统的红砖古厝、老祠堂与曲折的古巷，石条路磨得光亮，祠堂里的族谱记载着家族数百年的迁徙与繁衍。蔡崇达以诚挚笔触书写了父亲的病痛、母亲的坚强与小镇青年的梦想与迷茫，每一处场景都在大房村中有迹可循。村外是广阔的海面，渔船在晨曦中出海、暮色中归来，海风中弥漫着海蛎与鱼干的气息。这里是闽南渔村生活的原始样本，也是感受《皮囊》中人间至情与乡土温度的真实之地。', '福建', 24.781500, 118.551900, '其他', '["https://img0.baidu.com/it/u=3746078427,1177418901&fm=253&fmt=auto&app=138&f=JPEG?w=579&h=388"]'),
('《文化苦旅・闽越人》', '南平市武夷山市武夷山天心永乐禅寺', '余秋雨', '现代', '天心永乐禅寺位于南平市武夷山市，是余秋雨《文化苦旅》中福建篇章的核心取景地。禅寺始建于唐代贞元年间，坐落在武夷山风景区核心地带，寺后便是举世闻名的大红袍母树茶园。余秋雨以文化行者的视角审视闽越文明的源流，天心寺承载的禅茶文化正是这种文明的精髓。寺内保留着唐代建筑风格、宋代古碑与明清重修的殿堂，梵音与茶香在山谷间交织。大红袍母树仅存六株，生长在九龙窠岩壁之上，被誉为茶中之王。春日新茶吐翠、秋天桂花飘香，是体验武夷禅茶文化与丹霞山水意境的清幽胜地。', '福建', 27.756400, 118.035300, '其他', '["https://img0.baidu.com/it/u=1804997255,4102694429&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《徐霞客游记・游武夷山记》', '南平市武夷山市武夷山九曲溪五曲', '徐霞客', '明代', '武夷山九曲溪五曲位于南平市武夷山市，是明代旅行家徐霞客《游武夷山记》中武夷九曲、曲曲皆奇的经典描绘地。五曲是九曲溪的精华段落，溪面开阔，两岸丹霞峰峦倒映水中，有武夷山水甲天下之美誉。徐霞客曾在此驻足多日，详细记录了九曲溪的地貌、植被与人文景观。五曲附近保留着明代古码头、摩崖石刻与朱熹曾讲学的武夷精舍遗址。乘竹筏顺流而下，两岸悬崖上的汉代悬棺与宋代摩崖题刻依次展现。春日山花映水、夏季溪水清凉、秋天层林尽染、冬季烟雨朦胧，是体验丹霞山水之美与明代旅行文学精神的经典之地。', '福建', 27.756400, 118.035300, '其他', '["https://img2.baidu.com/it/u=2083377501,323215748&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1200"]'),
('《泉州府志》', '泉州市鲤城区西街北段', '何乔远', '明代', '西街北段位于泉州市鲤城区，是明代学者何乔远《泉州府志》中重点记载的古街区。西街是泉州最古老的街道，始于唐代，繁盛于宋元，至今已有一千三百余年历史。北段远离游客密集的开元寺一带，保留着更为原始的闽南古民居、老商铺与窄巷。红砖古厝、石条铺地、燕尾脊飞扬，街巷中老阿婆在门前泡着功夫茶，传统手工艺作坊依然经营着祖辈的手艺。何乔远在府志中详细记载了西街的市井繁华与宗教多元，这些记载至今仍可在北段街巷中找到对应。这里是感受泉州千年古城最真实烟火气与闽南建筑之美的静谧老街。', '福建', 24.907600, 118.587300, '其他', '["https://img1.baidu.com/it/u=295707892,4192319593&fm=253&fmt=auto&app=138&f=JPEG?w=664&h=500"]'),
('《三坊七巷志》', '福州市鼓楼区三坊七巷文儒坊', '徐熥', '明代', '文儒坊位于福州市鼓楼区三坊七巷核心区域，是明代文人徐熥《三坊七巷志》中记载的重要巷坊。三坊七巷是中国规模最大的明清古建筑街区，被誉为中国城市里坊制度的活化石。文儒坊因历代文人儒士聚居而得名，是三坊七巷中最为安静雅致的一坊。坊内保留着明清古民居、老祠堂与幽深古巷，白墙灰瓦、飞檐翘角，马鞍墙高耸如屏。坊中曾走出过多位状元、进士与近代名人。古巷中石板路幽深，老宅门前的石鼓与门当诉说着往日的荣耀。春日庭院花木扶疏、秋天桂花飘香，是品味福州文脉与明清建筑艺术的文化胜地。', '福建', 26.081900, 119.303800, '其他', '["https://img0.baidu.com/it/u=886435320,1054373403&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《土楼记》', '龙岩市永定区初溪土楼群余庆楼', '林语堂', '现代', '余庆楼位于龙岩市永定区初溪土楼群中，是林语堂《土楼记》中重点描绘的客家圆楼。余庆楼建于明代，是初溪土楼群中保存最为完好的土楼之一，楼高三层，外径约四十余米，以生土夯筑而成，墙厚逾一米。楼内至今仍有客家居民居住，保留着传统的宗族生活方式与民俗文化。林语堂对客家土楼的建筑智慧赞叹不已，称其为东方的古城堡。楼内天井宽敞、回廊环绕，古碑与民俗陈列展示着客家先民的迁徙历史。土楼外梯田层叠、溪流环绕，春日油菜花金黄、秋天稻穗低垂，是体验客家土楼居住文化与闽西田园风光的世界遗产。', '福建', 24.723100, 116.732000, '其他', '["https://img0.baidu.com/it/u=1455046523,860751289&fm=253&fmt=auto&app=138&f=JPEG?w=787&h=500"]'),
('《太姥山记》', '宁德市福鼎市太姥山白云寺', '袁枚', '清代', '太姥山白云寺位于宁德市福鼎市太姥山中，是清代文人袁枚《太姥山记》中重点描绘的古寺。白云寺始建于唐代，坐落在太姥山半山腰的岩洞之中，寺庙依岩而建，三面环石，仅正面对外开放，冬暖夏凉、清幽异常。袁枚在游记中赞叹太姥山的奇石与古寺，称其有太姥无俗石，个个皆神工之美。寺周保留着历代摩崖石刻与古碑，岩壁上苔藓斑驳、古藤攀附。从寺前远眺，云海翻腾、峰峦如岛，恍若置身仙境。春日杜鹃盛开、夏季清凉避暑、秋天层林尽染、冬季偶有雾凇，是体验闽东山岳禅修文化与太姥山自然奇观的隐秘胜地。', '福建', 27.324600, 120.216400, '其他', '["https://img0.baidu.com/it/u=7490432,2940259535&fm=253&fmt=auto&app=138&f=JPEG?w=755&h=500"]'),
('《湄洲岛记》', '莆田市秀屿区湄洲岛祖庙山', '冰心', '现代', '湄洲岛祖庙山位于莆田市秀屿区，是冰心散文《湄洲岛记》中重点描绘的妈祖信仰圣地。妈祖祖庙始建于宋雍熙四年（987年），是全球五千余座妈祖庙的祖庙，每年吸引数百万海内外信众前来朝拜。祖庙山上殿宇层叠、金碧辉煌，巨型妈祖石雕像面朝大海，守护着万里航程。冰心对妈祖文化有着深厚情感，在文中赞美了湄洲岛的海天胜景与妈祖的大爱精神。祖庙山上古木参天、碑刻林立，登临山顶可俯瞰整个湄洲岛与辽阔的台湾海峡。春日海风和煦、夏季碧海蓝天、秋天渔火点点、冬季潮音庄严，是感受妈祖信仰源流与闽海文化的精神圣地。', '福建', 25.318700, 119.092700, '其他', '["https://img1.baidu.com/it/u=2316980855,1534935807&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=1117"]'),
('《东山岛记》', '漳州市东山县铜陵镇顶街', '黄道周', '明代', '铜陵镇顶街位于漳州市东山县，是明代学者黄道周《东山岛记》中重点描绘的古街。顶街是东山岛最古老的街区，始建于明代，依铜山古城而建，保留着明清古民居、老商铺与城墙遗址。黄道周是明末大儒与民族英雄，生于东山岛，在此度过了青少年时光。街巷狭窄幽深，石板路磨得光滑，老宅的石雕门楣与木质花窗工艺精湛。街尽头便是铜山古城墙，登城远眺可见碧海蓝天与风动石的雄姿。顶街至今保留着闽南渔村的生活气息，鱼干晾晒在屋檐下，海风中弥漫着咸鲜味道，是体验东山岛历史文化与闽南海岛风情的原始老街。', '福建', 23.701400, 117.428200, '其他', '["https://img2.baidu.com/it/u=3029745269,1368521203&fm=253&fmt=auto&app=138&f=JPEG?w=889&h=500"]'),
('《冠豸山记》', '龙岩市连城县冠豸山石门湖', '纪晓岚', '清代', '冠豸山石门湖位于龙岩市连城县，是清代大学士纪晓岚《冠豸山记》中重点描绘的山水景观。石门湖嵌在冠豸山丹霞峰峦之间，湖水碧绿如翡翠，两岸赤壁丹崖倒映水中，山水一色、美不胜收。乘船游湖，穿行在峡谷之间，抬头仰望只见一线天光，岩壁上摩崖石刻与古藤交织。纪晓岚游历此地后赞叹连城山水甲闽西，石门湖正是其中精华。湖畔保留着明代古寺遗迹，寺前古木参天，清泉从岩缝中涌出。春日山花映湖、夏季绿荫蔽日、秋天丹枫映水、冬季云雾缭绕，是体验闽西丹霞山水与清代文人雅趣的清幽之地。', '福建', 25.710400, 116.754600, '其他', '["https://img1.baidu.com/it/u=1834617594,1036945040&fm=253&fmt=auto&app=138&f=PNG?w=739&h=500"]'),
('《金湖记》', '三明市泰宁县尚书第建筑群', '朱熹', '南宋', '尚书第建筑群位于三明市泰宁县，是南宋理学大师朱熹相关文献《金湖记》中提及的明代官宅建筑群。尚书第建于明天启年间，是明代兵部尚书李春烨的府第，是江南保存最完好的明代民居建筑群之一。整座建筑群占地五千余平方米，由五幢主楼与辅助建筑组成，飞檐翘角、雕梁画栋，木雕石雕精美绝伦。府第内天井连通、回廊环绕，布局严谨而不失灵动。朱熹曾在泰宁讲学，对这里的人文教化影响深远。建筑群周边古街古巷保留着明清风貌，是了解明代官宦建筑艺术与泰宁理学文化的珍贵遗产。', '福建', 26.900000, 117.176000, '其他', '["https://img2.baidu.com/it/u=3441797918,3208154955&fm=253&fmt=auto&app=138&f=JPEG?w=686&h=500"]'),
('《安平桥记》', '泉州市晋江市安海镇白塔寺', '朱熹', '南宋', '白塔寺位于泉州市晋江市安海镇，与南宋理学大师朱熹《安平桥记》中描述的安平桥遗址遥相呼应。白塔寺始建于南宋，寺内白塔高耸，与安平桥东端相望，是这座千年古桥的重要地标。朱熹曾在泉州讲学，对安平桥的宏伟工程赞叹不已。白塔寺保留着宋代石塔、古碑与明清重修的殿堂，寺内香火鼎盛、梵音缭绕。寺前便是天下无桥长此桥的安平桥起点，千年石桥横跨安海湾，潮起潮落间蚝壳密布桥墩。春日寺前花木扶疏、秋天海风习习，是感受宋代桥梁文化与闽南佛教信仰交融的历史圣地。', '福建', 24.781500, 118.551900, '其他', '["https://img1.baidu.com/it/u=1455730790,1719377535&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1778"]'),
('《台北人》', '台北市大安区永康街', '白先勇', '现代', '永康街位于台北市大安区，是白先勇长篇小说《台北人》中多次描绘的台北都市生活场景。永康街形成于日据时期，如今是台北最具文艺气息的街区之一，两旁日式木造建筑与现代咖啡馆交错并存。白先勇笔下那些从大陆流落台湾的外省人，在台北的街巷中品味着故国之思与身世之叹。永康街上老咖啡馆的木质桌椅、书店的旧书香气与街角的芒果冰店，构成了台北独特的生活美学。街巷中梧桐树荫浓密，偶有猫咪在墙头懒洋洋地晒太阳。这里是感受白先勇文学中外省人乡愁与台北城市温度的文艺街区。', '台湾', 25.026400, 121.543400, '其他', '["https://img0.baidu.com/it/u=3923445212,3681008852&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=654"]'),
('《撒哈拉的故事》', '新北市淡水区真理街三毛故居', '三毛', '现代', '三毛故居位于新北市淡水区真理街，是台湾传奇女作家三毛《撒哈拉的故事》等作品的创作背景地之一。故居为日式木造建筑，掩映在淡水真理大学附近的绿树之中。三毛在这里度过了少年时光，淡水河的夕阳、观音山的轮廓与小镇的温柔，都融入了她日后浪迹天涯的文字之中。故居内陈列着三毛的手稿、书信与生平照片，书架上摆满了她挚爱的书籍。三毛以自由不羁的灵魂感动了无数读者，从淡水到撒哈拉，她的足迹遍布世界。故居外淡水老街古朴热闹，黄昏时分淡水河畔夕阳如画，是追寻三毛文学足迹与淡水人文风情的温暖之地。', '台湾', 25.169400, 121.448600, '其他', '["https://img1.baidu.com/it/u=2224691579,3507421325&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=654"]'),
('《目送》', '台北市中正区台湾大学椰林大道', '龙应台', '现代', '台湾大学椰林大道位于台北市中正区，是龙应台散文集《目送》中多次描绘的校园景观。椰林大道是台湾大学的标志性景观，两排高大的椰子树整齐排列，从校门一直延伸到总图书馆，形成了独特的热带学术氛围。龙应台以目送为主题，书写了生命中一次次的离别与不舍，椰林大道上无数学子匆匆来去的身影，正是这种人生哲思的最佳注脚。大道两旁保留着日据时期的学术建筑、老图书馆与百年古樟。春日凤凰花火红如焰、秋天落叶纷飞，是感受台湾学术精神与龙应台散文中生命温度的校园圣地。', '台湾', 25.032000, 121.519900, '其他', '["https://img1.baidu.com/it/u=1848014326,2625180054&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=500"]'),
('《菩提十书》', '高雄市鼓山区佛光山藏经楼', '林清玄', '现代', '佛光山藏经楼位于高雄市鼓山区，是林清玄散文集《菩提十书》的创作灵感来源地与禅修体验场所。佛光山由星云大师创建于1967年，是台湾规模最大的佛教道场之一。藏经楼珍藏着大量佛教经典与艺术珍品，建筑庄严宏伟，金色佛塔在阳光下熠熠生辉。林清玄在佛光山潜心修行多年，将禅意融入散文创作，以清澈优美的文字启迪人心。山上殿堂林立、花木繁茂、梵音缭绕，大佛像慈悲端坐于莲台之上。春日樱花盛开、夏季菩提树浓荫蔽日，是体验台湾佛教文化与林清玄禅意文学的精神圣地。', '台湾', 22.650100, 120.281000, '其他', '["https://img0.baidu.com/it/u=925078669,1075192143&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《城南旧事》', '新北市板桥区林海音故居', '林海音', '现代', '林海音故居位于新北市板桥区，是台湾文学大师林海音创作《城南旧事》等经典作品的重要生活场所。林海音生于日本、长于北京、定居台湾，一生跨越三地的经历赋予了她独特的文学视角。故居为日式木造建筑，保留着林海音的手稿、书信与生平陈列。《城南旧事》以童年在北京南城的记忆为素材，却是在台湾完成创作的，英子的天真目光穿越海峡，连接着两岸的共同记忆。故居内书房简朴雅致，窗外绿竹摇曳。林海音作为台湾文学编辑的开拓者，发掘培养了大批作家，这座故居也是台湾文学发展史的重要见证。', '台湾', 25.009600, 121.459000, '其他', '["https://img1.baidu.com/it/u=3277159212,3822929079&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1157"]'),
('《孽子》', '台北市万华区华西街北段', '白先勇', '现代', '华西街北段位于台北市万华区，是白先勇长篇小说《孽子》中核心叙事空间。华西街曾是台北最繁华的夜市街区，北段远离游客密集区域，保留着更为原始的老街风貌。白先勇以悲悯笔触描写了一群被家庭与社会放逐的边缘少年，他们在台北新公园与华西街之间游荡，寻找归属与温暖。老街上日式建筑与闽南式骑楼交错，昏暗的灯光下老商铺的招牌斑驳可辨。龙山寺的钟声隐约传来，为这片充满世俗气息的街区增添了几分超脱。这里是感受白先勇文学中人性幽微与台北底层社会温情的独特场所。', '台湾', 25.035300, 121.499900, '其他', '["https://img2.baidu.com/it/u=464376356,879941067&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=652"]');
INSERT INTO works (title, scenic_spot, author, dynasty, description, province, latitude, longitude, category, images) VALUES
('《巨流河》', '高雄市左营区左营旧城', '齐邦媛', '现代', '左营旧城位于高雄市左营区，是齐邦媛长篇自传《巨流河》中作者在台湾生活的重要场景地。左营旧城是台湾现存最完整的清代古城之一，始建于清康熙年间，保留着东、南、北三座城门与部分城墙。齐邦媛随国民政府迁台后在左营附近定居，《巨流河》中她从东北到台湾的一生漂泊，在这座南方古城中找到了暂时的安宁。城墙内外古寺、老街与眷村遗迹共存，热带植物在城头上肆意生长。莲池潭碧波荡漾、龙虎塔色彩斑斓，是感受台湾眷村文化与《巨流河》中大时代个人命运的历史之地。', '台湾', 22.687600, 120.294400, '其他', '["https://img0.baidu.com/it/u=3086422058,2774401369&fm=253&fmt=auto&app=138&f=JPEG?w=667&h=500"]'),
('《孤独六讲》', '台南市东区成功大学成功湖', '蒋勋', '现代', '成功大学成功湖位于台南市东区，是蒋勋散文集《孤独六讲》中多次描绘的校园意象。成功大学是台南最具历史底蕴的高等学府，校园内保留着日据时期的学术建筑与百年古树。成功湖位于校园中心，湖面不大却宁静雅致，湖畔榕树浓荫蔽日，学子们在湖边阅读、沉思。蒋勋在《孤独六讲》中探讨了情欲、革命、暴力、思维、伦理与语言的孤独，成功湖的静谧恰是这种孤独美学的空间注脚。春日凤凰花红、秋天落叶满径，是体验台南学术氛围与蒋勋美学思想的清幽校园。', '台湾', 22.983800, 120.222900, '其他', '["https://img0.baidu.com/it/u=635232300,716056271&fm=253&fmt=auto&app=120&f=JPEG?w=666&h=500"]'),
('《台湾通史》', '台南市中西区赤嵌楼', '连横', '清代', '赤嵌楼位于台南市中西区，是清代史家连横《台湾通史》中重点记载的重要历史遗址。赤嵌楼原名普罗民遮城，由荷兰人建于1653年，是台湾最古老的建筑遗址之一。1661年郑成功收复台湾后将其改为承天府治所。连横在《台湾通史》中详细记载了赤嵌楼从荷兰殖民到清代治理的沧桑变迁。楼前九座赑屃碑是清乾隆年间为表彰平定林爽文之乱而立，石龟驮碑、气势庄严。赤嵌楼夜景灯火辉煌，红墙映衬着月色格外迷人。这里是了解台湾四百年开发史与中华文化在台传承的最重要历史遗址之一。', '台湾', 22.992100, 120.197100, '其他', '["https://img2.baidu.com/it/u=3020496162,596048756&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=750"]'),
('《海角七号》', '屏东县恒春镇恒春古城南门', '魏德圣', '现代', '恒春古城南门位于屏东县恒春镇，是魏德圣导演电影文学《海角七号》的核心取景地。恒春古城建于清光绪元年（1875年），是台湾保存最完整的清代古城之一，南门城楼保留着原始的城墙与城门洞。《海角七号》以恒春小镇为背景，讲述了跨越时空的爱情故事，让这座偏远小镇一夜成名。城门内外老街古朴宁静，传统闽南骑楼下偶有老人闲坐品茶。恒春半岛地处台湾最南端，热带风情浓郁，落山风季节风声呼啸。古城外垦丁碧海蓝天、珊瑚礁环绕，是感受台湾南端热带风光与电影文学浪漫情怀的独特之地。', '台湾', 22.682800, 120.488100, '其他', '["https://img0.baidu.com/it/u=1409690174,3887532696&fm=253&fmt=auto?w=391&h=259"]'),
('《那些年，我们一起追的女孩》', '彰化县彰化市精诚中学', '九把刀', '现代', '精诚中学位于彰化县彰化市，是九把刀自传体小说及电影《那些年，我们一起追的女孩》的核心取景地。精诚中学是彰化地区知名的私立学校，校园保留着日据时期的建筑风格，老教室的木质课桌、黑板与操场上的篮球架，构成了一代台湾学子共同的青春记忆。九把刀以真实的校园生活为素材，书写了少年时代纯真而青涩的爱恋，引发了无数读者的共鸣。教室窗外阳光透过凤凰木洒落课本，操场上的奔跑与欢笑仿佛从未远去。这里是感受台湾校园青春文化与纯爱文学温度的怀旧之地。', '台湾', 24.075700, 120.541900, '其他', '["https://img0.baidu.com/it/u=19636319,4116441826&fm=253&fmt=auto&app=138&f=JPEG?w=667&h=500"]'),
('《艋舺》', '台北市万华区艋舺龙山寺', '钮承泽', '现代', '艋舺龙山寺位于台北市万华区，是钮承泽导演电影文学《艋舺》的核心取景地。龙山寺始建于清乾隆三年（1738年），是台北最古老的寺庙之一，历经地震、台风与战火仍屹立不倒。寺庙建筑精美绝伦，石雕龙柱、交趾陶与木雕藻井堪称闽南寺庙艺术的巅峰。《艋舺》以八十年代台北万华区的帮派故事为背景，龙山寺前的广场正是少年们聚集的地方。寺内香火鼎盛，信众虔诚祈祷，寺外万华老街烟火气浓郁。晨钟暮鼓中，这座古寺以宽容姿态接纳着每一个灵魂，是感受台北最深厚的民间信仰与市井温情的文化地标。', '台湾', 25.035300, 121.499900, '其他', '["https://img1.baidu.com/it/u=2608847374,3642418595&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《悲情城市》', '新北市瑞芳区九份基山街', '侯孝贤', '现代', '九份基山街位于新北市瑞芳区，是侯孝贤导演电影《悲情城市》的核心取景地。基山街是九份最热闹的老街，窄窄的石板路两旁是鳞次栉比的日式木造建筑、老茶馆与小吃摊。侯孝贤以二二八事件为背景，在这条老街上拍摄了林家兄弟的悲情故事，让九份从被遗忘的矿山小镇一跃成为国际知名景点。基山街保留着日据时期的建筑格局，红灯笼、茶烟与芋圆的香气弥漫在狭窄的巷道中。黄昏时分站在街尽头远眺基隆港与东海，山城灯火与海上渔火交相辉映，是体验台湾近代伤痛历史与山城怀旧美学的必游之地。', '台湾', 25.109200, 121.810400, '其他', '["https://img2.baidu.com/it/u=1165406379,1416326698&fm=253&fmt=auto&app=138&f=JPEG?w=333&h=499"]'),
('《饮食男女》', '台北市士林区阳明山竹子湖', '李安', '现代', '阳明山竹子湖位于台北市士林区，是李安导演电影《饮食男女》的核心取景地之一。竹子湖位于阳明山国家公园内，海拔约六百七十米，是一处火山堰塞湖遗迹形成的盆地。李安以台北一个家庭的饮食日常为主线，探讨了亲情、爱情与代际关系，竹子湖的自然与人文成为影片的诗意注脚。盆地内梯田错落，春日海芋花田洁白如雪，夏季绣球花五彩缤纷，秋天芒花飘摇，冬季云雾缭绕。周边温泉资源丰富，日式温泉旅馆散落山间。这里远离台北都市喧嚣，是感受阳明山自然之美与台湾生活美学的清幽之地。', '台湾', 25.092700, 121.524500, '其他', '["https://img2.baidu.com/it/u=2616295291,4208193319&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《我们台湾这些年》', '台中市西区精明一街', '廖信忠', '现代', '精明一街位于台中市西区，是廖信忠《我们台湾这些年》中描绘的台中城市生活缩影。精明一街是台中最早的徒步街区，两旁欧式建筑与露天咖啡座营造出浓郁的异国情调。廖信忠以一个台湾普通人的视角，讲述了从解严到千禧年间台湾社会的变迁，台中作为台湾中部最大的城市，正是这种变迁的生动舞台。街道两旁法国梧桐树荫浓密，精品店、画廊与独立书店错落其间。周末街头艺人的吉他声与咖啡的香气交织，是台中最具小资情调的角落。这里是感受台湾城市现代化进程与台中生活美学的休闲文艺街区。', '台湾', 24.141200, 120.662500, '其他', '["https://img2.baidu.com/it/u=1244725944,2323006875&fm=253&fmt=auto&app=120&f=JPEG?w=1200&h=798"]'),
('《平潭看海记》', '福州市平潭县北港村石头厝', '邓燕婷', '现代', '北港村石头厝位于福州市平潭县，是邓燕婷散文《平潭看海记》中石头厝、平潭的灵魂的核心取景地。北港村坐落在平潭岛东海岸，是一座以花岗岩石头建筑闻名的传统渔村。明清时期的石砌民居依山面海而建，灰色石墙与蓝色大海形成鲜明对比，被誉为中国最美石头村。石头厝以就地取材的花岗岩块垒砌而成，墙面纹理粗犷质朴，屋顶以石头压瓦防御海风。村中窄巷蜿蜒、石阶起伏，海风中弥漫着海蛎壳与渔网的气息。黄昏时分夕阳映照石头厝，金光洒满村庄，是感受平潭海岛石头建筑文化与东海渔村风情的独特之地。', '福建', 25.498900, 119.790900, '其他', '["https://img1.baidu.com/it/u=1071511620,1090108247&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《霞浦的海》', '宁德市霞浦县三沙光影栈道', '舒婷', '现代', '霞浦三沙光影栈道位于宁德市霞浦县三沙镇，是中国最美滩涂摄影圣地之一。栈道沿海岸线蜿蜒而建，全长约两公里，视野极为开阔。舒婷在《霞浦的海》中将此地比作上帝打翻的调色盘，形象描绘了霞浦滩涂在不同光线下呈现出的斑斓色彩。日出与日落时分，海面上渔网、竹竿、小舟构成的剪影与天空的霞光交相辉映，美不胜收。紫菜养殖架在潮水退去后形成独特的几何图案，吸引了无数摄影爱好者前来创作。此地游客相对较少，保留了原始的渔村风貌与淳朴的渔民生活气息。', '福建', 26.885200, 120.005500, '其他', '["https://img1.baidu.com/it/u=863105088,1895098642&fm=253&fmt=auto&app=138&f=JPEG?w=667&h=500"]'),
('《泉州的石头》', '泉州市晋江市五店市传统街区', '蔡其矫', '现代', '泉州晋江五店市传统街区位于晋江市中心，是闽南地区保存最完整的传统街区之一。蔡其矫在《泉州的石头》中感叹泉州的石头会说话，正是对五店市红砖古厝、石雕艺术的生动写照。街区内保留了明清至民国时期的闽南红砖厝、番仔楼、宗祠庙宇等百余座传统建筑，红砖白石、燕尾翘脊，尽显闽南建筑精髓。蔡氏古民居群、庄氏家庙等建筑精美绝伦，石刻、木雕、砖雕工艺令人叹为观止。街区内还保留了布袋戏、南音等非物质文化遗产的展演空间，是了解闽南文化的绝佳窗口。', '福建', 24.781500, 118.551900, '其他', '["https://img0.baidu.com/it/u=3876436348,2344087965&fm=253&fmt=auto&app=138&f=JPEG?w=749&h=500"]'),
('《火山岛的风》', '漳州市漳浦县火山岛地质公园', '余光中', '现代', '漳州漳浦火山岛地质公园位于漳浦县前亭镇，是中国唯一的滨海火山地质公园。余光中在《火山岛的风》中写道火山岛的风带着亿万年的记忆，形象描绘了这片古老地质奇观的沧桑与壮美。公园内保留了距今约两千万年前的火山喷发遗迹，玄武岩柱状节理规模宏大，被誉为海上兵马俑。南碇岛上140万根石柱拔海而立，气势磅礴。黑色火山岩与蔚蓝大海形成强烈视觉对比，海蚀洞、熔岩流痕迹随处可见。此地游客不多，保留了原始的地质风貌与海岛渔村的宁静氛围。', '福建', 24.117100, 117.613600, '其他', '["https://img0.baidu.com/it/u=3069722297,3940690667&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=720"]'),
('《培田古村记》', '龙岩市连城县培田古村落', '林语堂', '现代', '龙岩连城培田古村落位于连城县宣和乡，距今已有八百余年历史，是中国十大最美古村落之一。林语堂在《培田古村记》中赞其为客家建筑的活化石，形象概括了培田的建筑价值。村内保留了明清时期的客家古民居三十余座，以九厅十八井为代表的大型院落气势恢宏，雕梁画栋、飞檐翘角，尽显客家建筑艺术精华。官厅、衍庆堂、双灼堂等古建筑保存完好，门楣上的石刻楹联、木雕窗花工艺精湛。村内古街、古巷、古井、古树点缀其间，溪水穿村而过，四周青山环抱，宛如世外桃源。', '福建', 25.710400, 116.754600, '其他', '["https://img2.baidu.com/it/u=770893464,2918345143&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《桂峰村的秋》', '三明市尤溪县桂峰古村落', '冰心', '现代', '三明尤溪桂峰古村落位于尤溪县洋中镇，始建于北宋，已有千年历史，是中国历史文化名村。冰心在《桂峰村的秋》中赞叹桂峰的秋是一幅浓墨重彩的山水画，描绘了古村秋日的绚丽景致。村内保留了明清古民居三十九座，依山而建，层层叠叠，错落有致。黑瓦白墙、马头墙、美人靠等建筑元素独具特色，石板小巷蜿蜒曲折。村口古桂飘香，秋日时节丹桂满枝，金黄银杏与红枫交织，色彩斑斓。蔡氏宗祠、玉泉书院等文化遗存见证了耕读传家的历史传统，是闽中山区难得的原生态古村落。', '福建', 26.169900, 118.190700, '其他', '["https://img1.baidu.com/it/u=2458566310,860793901&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1199"]'),
('《洞宫山游记》', '南平市政和县洞宫山', '郁达夫', '现代', '南平政和洞宫山位于政和县杨源乡，海拔一千四百余米，是闽北地区重要的道教名山与自然景观。郁达夫在《洞宫山游记》中称其为闽北的秘境，赞叹山中原始森林遮天蔽日、溪瀑飞泻的壮美景象。洞宫山因传说中神仙在此修炼而得名，保留了宋代古刹、道观遗迹与摩崖石刻。山中云海翻涌，古木参天，珍稀动植物资源丰富。麒麟峰、虎潭瀑布等自然景观令人叹为观止。此地交通不便，游客极少，保留了原始的自然风貌与淳朴的山村生活气息，是真正的世外秘境。', '福建', 27.366400, 118.855700, '其他', '["https://img0.baidu.com/it/u=1282288647,3654486848&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=633"]'),
('《嵩口古镇》', '福州市永泰县嵩口古镇', '林徽因', '现代', '福州永泰嵩口古镇位于永泰县大樟溪畔，始建于南宋，已有八百余年历史，是中国历史文化名镇。林徽因在《嵩口古镇》中感叹嵩口是时光停留的地方，形象描绘了古镇悠然自得的生活节奏。镇内保留了明清古民居一百二十余座，以用坦厝、下新厝等大型院落为代表，建筑风格融合了闽中与闽南特色。古渡口、古廊桥、古碇步保存完好，大樟溪清澈见底，两岸古榕成荫。古镇经过微改造后保留了原住民的生活形态，老理发店、老杂货铺依然营业，充满烟火气息与人文温度。', '福建', 25.866900, 118.932000, '其他', '["https://img1.baidu.com/it/u=1941568815,3176426180&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1199"]'),
('《沙坡尾的黄昏》', '厦门市思明区沙坡尾艺术西区', '舒婷', '现代', '厦门思明区沙坡尾艺术西区位于厦门港旧渔港区域，是厦门最后的活态渔港遗存。舒婷在《沙坡尾的黄昏》中写道沙坡尾的黄昏是厦门最温柔的时刻，深情描绘了这片老渔港在夕阳下的迷人风韵。沙坡尾因沙滩呈弧形坡状而得名，曾是厦门最繁忙的渔港码头。如今保留了避风坞、旧船坞、石砌海堤等渔港遗迹，老渔民仍在此修补渔网。艺术西区由旧厂房改造而成，文创店铺、独立咖啡馆与老渔港和谐共存，新旧交融。黄昏时分渔船归港，夕阳将海面染成金色，是体验厦门本土渔港文化的绝佳去处。', '福建', 24.445400, 118.082300, '其他', '["https://img0.baidu.com/it/u=3275513121,4082718740&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1316"]'),
('《妈祖的故乡》', '莆田市秀屿区湄洲岛港里村', '冰心', '现代', '莆田秀屿区湄洲岛港里村位于湄洲岛东南端，是海上女神妈祖的出生地与羽化升天之处。冰心在《妈祖的故乡》中深情讴歌了妈祖海上女神的伟大精神。港里村保留了妈祖故居遗址、天后祖祠、妈祖文化园等重要遗迹，是全世界两亿多妈祖信众的精神圣地。村内古厝依山面海，红砖白石的闽南建筑风格与蔚蓝海景交相辉映。每年妈祖诞辰与升天日，来自世界各地的信众齐聚于此，盛况空前。港里村远离湄洲岛主景区的喧嚣，保留了渔村的原始风貌，海风习习，民风淳朴，是感受妈祖文化最本真的地方。', '福建', 25.318700, 119.092700, '其他', '["https://img1.baidu.com/it/u=3175702618,3249117482&fm=253&fmt=auto&app=120&f=JPEG?w=500&h=701"]'),
('《女诫扇绮谭》', '台南市中西区蜗牛巷', '佐藤春夫', '现代', '台南中西区蜗牛巷位于台南老城区核心地带，是日本作家佐藤春夫《女诫扇绮谭》的核心取景地。这条隐匿于骑楼之间的窄巷，保留了清代古民居、日式老屋与战后民宅，见证了台南数百年的历史变迁。佐藤春夫于1920年游历台南时，在此巷中邂逅了充满异国风情的街巷景致，写下了这篇充满魔幻色彩的短篇小说。巷内青苔斑驳的老墙、攀爬的九重葛、木质百叶窗构成了独特的视觉美感。如今巷中设有文学散步路线的指引标识，沿途可感受日据时期台南的文学氛围与生活风情，是文学爱好者探访台南的必到之处。', '台湾', 22.992100, 120.197100, '其他', '["https://img1.baidu.com/it/u=297219254,1698937532&fm=253&fmt=auto&app=138&f=JPEG?w=638&h=500"]'),
('《台湾文学史》', '台南市中西区叶石涛故居', '叶石涛', '现代', '台南中西区叶石涛故居位于台南市府前路，是台湾文学史家叶石涛的出生地与成长之处。故居为日式木造建筑，保留了叶石涛的手稿、书信、藏书与生平陈列，是了解台湾文学发展脉络的重要场所。叶石涛毕生致力于台湾文学的整理与研究，其《台湾文学史纲》被誉为台湾文学研究的里程碑。故居经过修复后对外开放，室内陈设还原了叶石涛的书房与生活场景，木质地板、日式拉门、庭院花木营造出静谧的文学氛围。周边是台南府城文化核心区域，步行可达孔庙、赤崁楼等古迹，文化底蕴深厚。', '台湾', 22.992100, 120.197100, '其他', '[]'),
('《忘忧森林》', '南投县鹿谷乡忘忧森林', '简媜', '现代', '南投鹿谷忘忧森林位于鹿谷乡与竹山镇交界处，海拔约两千公尺，因1999年九二一大地震后堰塞湖淹没杉林而形成。简媜在《忘忧森林》中写道忘忧森林是大自然的眼泪，以细腻笔触描绘了这片枯木沼泽的苍凉之美。枯死的柳杉笔直伫立于湖水之中，倒影与薄雾交织，宛如仙境。晨间云雾缭绕时，整片森林如梦似幻，被誉为台湾九寨沟。因海拔较高、道路陡峭，游客需乘坐接驳车或徒步上山，保留了较为原始的自然生态。四季景色各异，秋冬枯木苍劲，春夏新绿萌发，是台湾中部最具魔幻气质的自然景观。', '台湾', 23.749800, 120.683700, '其他', '["https://img1.baidu.com/it/u=3768745101,3654186278&fm=253&fmt=auto&app=138&f=JPEG?w=600&h=402"]'),
('《清水断崖》', '花莲县秀林乡清水断崖', '席慕蓉', '现代', '花莲秀林清水断崖位于苏花公路沿线，是台湾八大奇景之一。席慕蓉在《清水断崖》中以太平洋的眼泪来形容断崖与海洋交汇处的壮美景象。清水断崖北起和仁、南至崇德，绵延约二十一公里，几乎垂直入海的大理石断崖最高处达一千多公尺，气势磅礴。湛蓝的太平洋海水拍打着洁白的大理石崖壁，层次分明的蓝色海面与翠绿山崖形成强烈对比。苏花公路在断崖间蜿蜒穿行，一侧是峭壁千仞，一侧是万顷碧波，险峻与壮美并存。清晨与黄昏时分光影变幻，是台湾东海岸最震撼人心的自然奇观。', '台湾', 23.976900, 121.601700, '其他', '["https://img1.baidu.com/it/u=3418579764,2099689527&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=738"]'),
('《鹿野的风》', '台东县鹿野乡鹿野高台', '龙应台', '现代', '台东鹿野高台位于鹿野乡龙田村，是台湾著名的热气球嘉年华举办地与飞行伞基地。龙应台在《鹿野的风》中写道鹿野的风带着稻田的香气，深情描绘了纵谷平原上稻浪翻涌的田园风光。高台海拔约三百五十公尺，视野辽阔，可俯瞰花东纵谷的壮丽全景。夏季稻田金黄一片，热气球升空时五彩缤纷，与蓝天绿野交相辉映。每年六至八月的热气球嘉年华吸引大量游客前来。高台下方的龙田村保留了日据时期的移民村规划格局，绿色隧道林荫蔽日，骑行其间悠然惬意。此地远离都市喧嚣，是感受台东慢生活的绝佳之处。', '台湾', 22.758300, 121.144900, '其他', '["https://img2.baidu.com/it/u=3294281945,3403952921&fm=253&fmt=auto&app=120&f=JPEG?w=500&h=667"]'),
('《奋起湖的火车》', '嘉义县竹崎乡奋起湖老街', '黄春明', '现代', '嘉义竹崎奋起湖老街位于阿里山森林铁路中途站，海拔约一千四百公尺，因三面环山形似畚箕而得名。黄春明在《奋起湖的火车》中感叹奋起湖的火车载着阿里山的记忆，深情描绘了老街与森林铁路的百年渊源。奋起湖是阿里山小火车最大的中继站，旅客在此换车、用餐，老街因此繁荣。街上保留了日据时期的木造老屋、铁道便当店与传统杂货铺，奋起湖便当闻名全台。老街旁的铁道旁有百年肖楠树林与杉木步道，清幽宜人。晨间云雾缭绕，小火车鸣笛穿行于山林之间，充满怀旧情调，是体验阿里山铁道文化的最佳据点。', '台湾', 23.480000, 120.574000, '其他', '["https://img0.baidu.com/it/u=4231180991,2822029152&fm=253&fmt=auto&app=120&f=GIF?w=500&h=500"]'),
('《内湾的记忆》', '新竹县横山乡内湾老街', '吴浊流', '现代', '新竹横山内湾老街位于横山乡内湾村，依油罗溪而建，是新竹山区重要的客家聚落。吴浊流在《内湾的记忆》中写道内湾的老街藏着新竹的乡愁，深情回忆了这座山村小镇的质朴风情。老街保留了日据时期的内湾戏院、刘兴钦漫画馆与客家传统老屋，骑楼下的摊位售卖野姜花粽、客家擂茶等传统美食。内湾吊桥横跨油罗溪，桥上可远眺翠绿山峦与清澈溪水。老街尽头的内湾车站是台铁内湾线的终点站，日式木造车站保存完好。每逢假日老街热闹非凡，但平日清幽宁静，是感受新竹客家山村风情的好去处。', '台湾', 24.838800, 121.017700, '其他', '["https://img2.baidu.com/it/u=1056148449,1921306486&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=647"]'),
('《杀鬼》', '苗栗县南庄乡南庄老街', '甘耀明', '现代', '苗栗南庄老街位于南庄乡中正路一带，依蓬莱溪而建，是苗栗县最具代表性的客家山城聚落。甘耀明在《杀鬼》中以南庄客家的秘境来形容这座隐匿于山林间的小镇。老街保留了日据时期的南庄旧邮局、乃木崎石板阶梯与百年桂花巷，桂花酿、客家麻糬等传统美食飘香四溢。蓬莱溪护鱼步道清幽宜人，溪水清澈见底，鱼群悠游其间。向天湖畔是赛夏族矮灵祭的举办地，原住民文化与客家文化在此交融。春日桐花满山、夏日萤火虫漫舞、秋日桂花飘香、冬日山岚缭绕，四季皆有不同风情，是苗栗最迷人的山城小镇。', '台湾', 24.560200, 120.821400, '其他', '["https://img0.baidu.com/it/u=289999752,4229300330&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=652"]'),
('《见晴古道》', '宜兰县大同乡太平山见晴古道', '简媜', '现代', '宜兰大同太平山见晴怀古步道位于太平山国家森林游乐区内，海拔约一千九百公尺，曾被评选为全球最美二十八条小路之一。简媜在《见晴古道》中赞叹见晴古道是太平山最美的步道，细腻描绘了步道在云雾中若隐若现的梦幻景致。步道全长约九百公尺，沿途保留了日据时期运材铁道的轨迹、旧铁轨与木桥遗构，铁轨上覆满青苔与蕨类植物，岁月感十足。两侧是茂密的原始桧木林，空气中弥漫着芬多精的清香。天晴时可远眺兰阳平原与太平洋，云雾涌来时步道如仙境般飘渺，是台湾最具诗意的森林步道。', '台湾', 24.752100, 121.753000, '其他', '["https://img2.baidu.com/it/u=186003131,2807237011&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=395"]'),
('《荒人手记》', '台北市中正区牯岭街旧书市', '朱天文', '现代', '台北中正区牯岭街旧书市位于台北市中正区牯岭街，曾是台湾最著名的旧书集散地。朱天文在《荒人手记》中以旧书市藏着台北的灵魂来形容这条充满文化记忆的老街。牯岭街因杨德昌电影《牯岭街少年杀人事件》而闻名于世，但其作为旧书街的历史更为悠久。全盛时期街上有近百家旧书店，文人雅士在此淘书、交流，是台北文学圈的重要聚集地。如今旧书店虽已减少，但牯岭街小剧场仍是台北重要的实验剧场，文艺氛围浓厚。周边是台北最具日式风情的街区，老屋、巷弄间藏着无数文学故事与历史记忆。', '台湾', 25.032000, 121.519900, '其他', '["https://img2.baidu.com/it/u=3248181366,4120979679&fm=253&fmt=auto&app=138&f=JPEG?w=304&h=414"]'),
('《城邦暴力团》', '台北市大同区大稻埕北段', '张大春', '现代', '台北大同区大稻埕北段位于台北市大同区迪化街北端，是清末至日据时期台北最繁华的商业区。张大春在《城邦暴力团》中以大稻埕台北的江湖来形容这片充满传奇色彩的老街区。大稻埕因晒谷场而得名，曾是台湾茶叶、布料、中药材的最大集散地。迪化街北段保留了巴洛克式骑楼、闽南式长条街屋与洋楼，建筑立面雕饰精美。霞海城隍庙香火鼎盛，永乐市场布料行琳琅满目。近年来老屋新生运动蓬勃发展，咖啡馆、文创店铺与百年老铺和谐共存。每逢年货大街期间人潮涌动，是感受台北百年商业文化的最佳场所。', '台湾', 25.063300, 121.513600, '其他', '["https://img1.baidu.com/it/u=1631238556,3179185854&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《笠山农场》', '高雄市美浓区钟理和纪念馆', '钟理和', '现代', '高雄美浓钟理和纪念馆位于美浓区广林里朝元寺旁，是台湾著名的文学纪念馆。钟理和被誉为倒在血泊中的笔耕者，其代表作《笠山农场》以美浓的客家农村生活为背景，描绘了日据时期台湾农民的生存状态与爱情故事。纪念馆保留了钟理和的手稿、书信、日记与藏书，以及其生平照片与创作年表。馆舍为简朴的客家式建筑，周围是广袤的稻田与远处的笠山，正是小说中描绘的田园风光。美浓是台湾最具代表性的客家聚落，擂茶、粄条、油纸伞等客家文化元素丰富。纪念馆游客稀少，环境清幽，是文学爱好者追寻台湾乡土文学足迹的圣地。', '台湾', 22.897900, 120.542100, '其他', '["https://img1.baidu.com/it/u=2544852566,213094874&fm=253&fmt=auto&app=138&f=JPEG?w=1096&h=500"]'),
('《孽子》', '彰化县鹿港镇龙山寺', '白先勇', '现代', '彰化鹿港龙山寺位于鹿港镇龙山街，始建于明永历年间，是台湾保存最完整的清代古刹之一。白先勇《孽子》中龙山寺承载着深厚的信仰文化，而鹿港龙山寺作为台湾龙山寺系统的重要代表，更具建筑艺术价值。寺庙占地一千六百余坪，五进三院的格局气势恢宏，木雕、石雕、彩绘工艺精湛绝伦，被誉为台湾紫禁城。八卦藻井不用一钉一铁、纯榫卯结构，是台湾古建筑的巅峰之作。戏台前的石埕广场保留了传统庙会活动空间，龙柱、石狮、交趾陶等装饰华丽。鹿港老街上保留了摸乳巷、半边井、九曲巷等独特的聚落空间，历史文化底蕴深厚。', '台湾', 24.051800, 120.516100, '其他', '["https://img2.baidu.com/it/u=1629861351,1801375165&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《沉默之岛》', '澎湖县西屿乡西屿灯塔', '苏伟贞', '现代', '澎湖西屿灯塔位于西屿乡外垵村西南端，建于清同治年间，是台湾最古老的灯塔之一。苏伟贞在《沉默之岛》中以澎湖的灯塔照亮了孤独的岛屿来描绘灯塔在茫茫大海中的孤寂与坚守。灯塔白色圆柱造型矗立于玄武岩海崖之上，与湛蓝的大海和翠绿的草原构成壮美画面。灯塔园区保留了日据时期的洋式宿舍、雾笛与蓄水池等附属设施。西屿落日是澎湖最著名的景观之一，黄昏时分灯塔剪影与晚霞交相辉映，美不胜收。外垵渔港的夜景被誉为澎湖小希腊，渔村灯火点点映照在港湾水面，宁静而浪漫。', '台湾', 23.569500, 119.579500, '其他', '["https://img1.baidu.com/it/u=3194768069,548488074&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=752"]'),
('《金门的风》', '金门县金城镇翟山坑道', '余光中', '现代', '金门金城翟山坑道位于金门县金城镇古岗村，建于1963年，是冷战时期金门最重要的军事工程之一。余光中在《金门的风》中写道金门的风带着两岸的乡愁，深刻表达了金门作为两岸历史交汇点的特殊情感。翟山坑道全长约一百零一公尺，A字形结构的花岗岩坑道深入山腹，可容纳四十二艘小型登陆艇。坑道内水面如镜，倒映着岩壁纹理与灯光，形成独特的视觉景观。每年金门坑道音乐节在此举办，乐声在水面与岩壁间回荡，音效震撼。坑道外可眺望大担岛与厦门，两岸近在咫尺。金门的闽南古厝、风狮爷、高粱田构成独特的战地与闽南文化交融景观。', '台湾', 24.436300, 118.317500, '其他', '["https://img0.baidu.com/it/u=3551852464,2262659090&fm=253&fmt=auto&app=138&f=JPEG?w=514&h=500"]'),
('《芹壁村的石头屋》', '连江县北竿乡芹壁村', '席慕蓉', '现代', '连江北竿芹壁村位于马祖北竿岛东北方，依山面海而建，是马祖地区保存最完整的闽东石头屋聚落。席慕蓉在《芹壁村的石头屋》中赞叹芹壁村是马祖的宝石，形象描绘了石头屋聚落在蔚蓝海面映衬下的璀璨之美。芹壁村因村落前方海中的龟岛形似芹菜壁而得名，花岗岩石屋层层叠叠依山而建，灰色石墙与蓝色大海形成鲜明对比。村内保留了天后宫、石板路、古井与防空洞等历史遗迹，部分石屋经修复后改造为民宿与咖啡馆。夜晚灯火映照石墙，倒影落入海面，被誉为东方地中海。此地游客稀少，保留了马祖战地渔村的原始风貌与宁静氛围。', '台湾', 26.160000, 119.950000, '其他', '["https://img1.baidu.com/it/u=1812319718,2249591172&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《高美湿地的日落》', '台中市清水区高美湿地', '蒋勋', '现代', '台中清水高美湿地位于清水区大甲溪出海口南岸，是台湾西海岸最重要的生态湿地之一。蒋勋在《高美湿地的日落》中赞叹高美湿地的日落是台湾最美的日落，深情描绘了湿地在夕阳下的梦幻景致。湿地面积约七百余公顷，拥有丰富的潮间带生态，云林莞草、大安水蓑衣等稀有植物在此生长。退潮时广袤的泥滩地上招潮蟹、弹涂鱼成群出没，候鸟在此觅食栖息。木栈道延伸入湿地深处，日落时分天空与水面被染成金红色，风力发电机的剪影点缀其间，构成极具视觉冲击力的画面。高美湿地的日落已成为台中最具代表性的自然景观。', '台湾', 24.268600, 120.559600, '其他', '["https://img0.baidu.com/it/u=3204168516,2715879382&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《太鲁阁的山》', '花莲县秀林乡太鲁阁九曲洞', '杨牧', '现代', '花莲秀林太鲁阁九曲洞位于太鲁阁国家公园中横公路沿线，是太鲁阁峡谷最精华的路段之一。杨牧在《太鲁阁的山》中以太鲁阁的山是大地的脊梁来形容峡谷的雄伟壮丽。九曲洞步道全长约七百公尺，沿立雾溪峡谷蜿蜒而行，两侧大理石峭壁高耸入云，最窄处仅数公尺之遥。溪水在千万年间切割出深邃的峡谷，岩壁上的褶皱纹理清晰可见，记录着板块运动与河流侵蚀的地质历史。步道内有多处明隧道与水景台，可近距离感受溪水奔腾与峡谷回音。九曲洞步道如九道弯曲般穿行于峭壁之间，光影变幻，步步皆景，是世界级的峡谷奇观。', '台湾', 23.976900, 121.601700, '其他', '["https://img1.baidu.com/it/u=447267774,1323162287&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《日月潭记》', '南投县鱼池乡日月潭玄奘寺', '余秋雨', '现代', '南投鱼池日月潭玄奘寺位于日月潭青龙山巅，面对拉鲁岛，背靠青龙山，是供奉唐代高僧玄奘法师顶骨舍利的佛教圣地。余秋雨在《日月潭记》中称日月潭为台湾的明珠，而玄奘寺正是这颗明珠上最具文化深度的圣迹。寺庙建于1965年，中式殿堂庄严肃穆，三楼供奉玄奘法师金身与顶骨舍利。寺前阶梯可俯瞰日月潭全景，湖面碧波万顷、群山环抱，拉鲁岛如翡翠镶嵌湖心。日月潭因其北半部形如日轮、南半部形如月钩而得名，晨昏光影变化万千。玄奘寺远离涵碧步道的喧嚣，环境清幽，是日月潭畔最具禅意与文化底蕴的景点。', '台湾', 23.749800, 120.683700, '其他', '["https://img1.baidu.com/it/u=3132313108,827481726&fm=253&fmt=auto&app=138&f=JPEG?w=712&h=472"]'),
('《茶与禅》', '台北市文山区猫空茶园', '林清玄', '现代', '台北文山猫空茶园位于文山区指南里，是台北市区海拔最高的产茶区。林清玄在《茶与禅》中感叹茶与禅是台湾的灵魂，以禅意笔触描绘了猫空茶园中品茗悟道的意境。猫空因溪床壶穴地形被闽南语称为猫空而得名，自清代以来即为台北重要的铁观音与包种茶产区。茶园依山而建，层层梯田茶树翠绿如毯，搭乘猫空缆车升空可俯瞰台北盆地全景。山上保留了数十家传统茶馆，品茗赏景、听风看云，远离都市喧嚣。夜晚茶馆中俯瞰台北璀璨夜景别有风味。指南宫、樟树步道等景点点缀山间，春日鲁冰花盛开、秋日桂花飘香，是台北最具人文气息的慢生活体验地。', '台湾', 24.989200, 121.570400, '其他', '["https://img2.baidu.com/it/u=2280619657,1333230013&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=652"]'),
('《饮酒・其五》', '九江市庐山市康王谷桃花源遗址', '陶渊明', '东晋', '九江庐山康王谷桃花源遗址位于庐山市境内，是陶渊明采菊东篱下悠然见南山的真实原型地。陶渊明在《饮酒·其五》中描绘的南山即指庐山，而康王谷则是其隐居田园生活的核心区域。谷中保留了晋代古驿道遗迹、陶渊明隐居处遗址，以及历代文人墨客留下的摩崖石刻。康王谷因秦末楚义帝避难于此而得名，峡谷幽深，溪水潺潺，两岸桃花春日盛开，宛如世外桃源。谷中还有著名的庐山瀑布水源之一的谷帘泉，被唐代茶圣陆羽评为天下第一泉。此地游客稀少，远离庐山主景区的喧嚣，保留了陶渊明笔下田园牧歌的宁静意境。', '江西', 29.450800, 116.044900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Lushan_Geopark.jpg/1280px-Lushan_Geopark.jpg"]'),
('《望庐山瀑布》', '九江市庐山市秀峰黄岩瀑布遗址', '李白', '唐代', '九江庐山秀峰黄岩瀑布遗址位于庐山市秀峰景区内，是李白千古名句飞流直下三千尺疑是银河落九天的真实描绘地。唐代摩崖石刻保存于瀑布两侧岩壁之上，记录了历代文人对此瀑布的赞叹。黄岩瀑布水量丰沛时飞瀑如练，气势磅礴，水雾弥漫中可见彩虹横跨。古驿道从瀑布旁蜿蜒而过，青石板路上留下了千年行旅的足迹。秀峰因南唐后主李璟在此建开先寺而得名，周围群峰竞秀、林木葱郁。此地远离庐山北线主景区的喧嚣，游客较少，保留了唐代以来的原始山水风貌，是追寻李白诗境的绝佳去处。', '江西', 29.450800, 116.044900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Lushan_Geopark.jpg/1280px-Lushan_Geopark.jpg"]'),
('《题西林壁》', '九江市庐山市西林寺遗址', '苏轼', '北宋', '九江庐山西林寺遗址位于庐山市庐山北麓，是苏轼创作不识庐山真面目只缘身在此山中的诞生地。西林寺始建于东晋太和年间，曾是庐山三大名寺之一。苏轼元丰七年游庐山时在寺壁上题写了这首脍炙人口的《题西林壁》，寺内保留了唐代建筑基址与宋代碑刻。寺院坐北朝南，背倚香炉峰，前临锦绣谷，山势层叠环绕，正合诗中横看成岭侧成峰远近高低各不同的意境。古樟参天、清泉潺潺，禅意浓厚。寺院经历代重修，至今仍有僧人驻锡。此地游客稀少，环境清幽，是感受苏轼庐山诗意与禅思的最佳场所。', '江西', 29.450800, 116.044900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Lushan_Geopark.jpg/1280px-Lushan_Geopark.jpg"]'),
('《琵琶行》', '九江市浔阳区琵琶亭唐代台基遗址', '白居易', '唐代', '九江浔阳区琵琶亭唐代台基遗址位于浔阳江畔，是白居易创作同是天涯沦落人相逢何必曾相识的原始地点。唐元和十一年，白居易被贬为江州司马，秋夜在浔阳江头送客时偶遇琵琶女，写下了长篇叙事诗《琵琶行》。台基为唐代夯土结构，记录了这段千古佳话的发生地。遗址旁浔阳江水缓缓东流，秋风萧瑟时荻花摇曳，颇合诗中浔阳江头夜送客枫叶荻花秋瑟瑟的意境。周边保留了浔阳古城墙遗迹与老码头，江面上渔船往来，烟波浩渺。此地是感受白居易贬谪生涯与千古诗情的重要文化遗存。', '江西', 29.705000, 115.989900, '其他', '["https://img2.baidu.com/it/u=1637429159,3158714531&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=709"]'),
('《菩萨蛮・书江西造口壁》', '赣州市章贡区郁孤台遗址', '辛弃疾', '南宋', '赣州章贡区郁孤台遗址位于赣州老城区西北隅的贺兰山上，是辛弃疾创作青山遮不住毕竟东流去的诞生地。郁孤台始建于唐代，因隋文帝时赣州刺史余孝顷登台忧叹而得名。辛弃疾于南宋淳熙年间任江西提点刑狱时登台远望，面对赣江东流，感慨山河破碎，写下了这首慷慨激昂的《菩萨蛮》。台上保留了宋代台基与明代碑刻，视野开阔可俯瞰赣江与章贡两江交汇处。周边保留了赣州宋代古城墙、浮桥等历史遗迹，城墙上古榕盘踞，江面上浮桥摇曳。此地是感受辛弃疾爱国情怀与赣州千年历史文化的重要场所。', '江西', 25.831100, 114.935000, '其他', '["https://img2.baidu.com/it/u=416380716,1054047509&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《登快阁》', '吉安市泰和县快阁遗址', '黄庭坚', '北宋', '吉安泰和快阁遗址位于泰和县城东侧澄江之畔，是黄庭坚创作落木千山天远大澄江一道月分明的原始地点。快阁始建于唐乾符年间，因登阁可快览山水而得名。北宋元丰年间黄庭坚任泰和知县时常登阁远眺，澄江碧波、远山如黛，诗兴大发，留下了这首千古绝唱《登快阁》。遗址保留了宋代建筑基址与黄庭坚手书碑刻，石刻书法遒劲有力，极具艺术价值。阁前澄江水清如镜，两岸稻田青翠，远山层峦叠嶂。秋日登阁，千山落木萧萧、江月皎洁分明，与诗中意境完美契合。此地游客稀少，是品味黄庭坚诗意人生的绝佳之地。', '江西', 26.788600, 114.908000, '其他', '["https://img2.baidu.com/it/u=4058991046,1355088489&fm=253&fmt=auto&app=138&f=JPEG?w=701&h=500"]'),
('《滕王阁诗》', '南昌市东湖区滕王阁唐代台基遗址', '王勃', '唐代', '南昌东湖区滕王阁唐代台基遗址位于赣江东岸，是王勃创作落霞与孤鹜齐飞秋水共长天一色的原始建筑基址。滕王阁始建于唐永徽四年，为唐高祖之子滕王李元婴所建。唐上元二年王勃途经南昌，在滕王阁宴会上即席写下千古名篇《滕王阁序》。唐代夯土台基保存于现阁基之下，记录了这座名楼最初的规模与形制。赣江自南向北从阁前流过，水面宽阔，秋日夕阳西下时霞光万道、水天一色，正是王勃笔下壮丽景象。历代滕王阁屡毁屡建达二十九次之多，台基遗址见证了千年沧桑。此地是中国文学史上最著名的景观创作地之一。', '江西', 28.684900, 115.899300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/d/dd/Pavilion_of_Prince_Teng_3.jpg/1280px-Pavilion_of_Prince_Teng_3.jpg"]'),
('《石钟山记》', '九江市湖口县石钟山下钟山遗址', '苏轼', '北宋', '九江湖口县石钟山下钟山遗址位于鄱阳湖与长江交汇处，是苏轼《石钟山记》的核心考察地。北宋元丰七年苏轼乘舟夜至绝壁下亲自考察石钟山命名之由来，发现山石与水波激荡产生钟鸣之声，写下了这篇著名的考察散文。下钟山遗址保留了唐代摩崖石刻与古寺遗迹，山石嶙峋，形态各异。鄱阳湖水与长江水在此交汇，一清一浊泾渭分明，蔚为壮观。石钟山因山形似钟且水击石鸣而得名，山上古木参天、藤萝攀附。苏轼事必躬亲的科学精神与优美散文在此完美结合，此地是感受宋代文人求真精神的重要场所。', '江西', 29.731400, 116.218600, '其他', '["https://img1.baidu.com/it/u=4029451805,2538379395&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《宿新市徐公店》', '上饶市铅山县新市镇徐公店遗址', '杨万里', '南宋', '上饶铅山新市镇徐公店遗址位于铅山县境内，是杨万里创作儿童急走追黄蝶飞入菜花无处寻的原型地。南宋淳熙年间杨万里途经新市镇，在徐公店歇脚时偶见乡间儿童追蝶嬉戏的场景，即兴写下了这首充满田园童趣的小诗。遗址保留了宋代古民居与老茶馆的建筑遗存，青石板路斑驳古朴。新市镇地处赣闽交界的山间盆地，四周丘陵环绕，春日油菜花金黄遍野，蝴蝶翩翩飞舞，与诗中描绘的场景极为吻合。周边农田阡陌纵横，溪水潺潺，保留了江南乡村的原始风貌。此地远离旅游线路，游客罕至，是体验南宋乡村田园生活的隐秘之地。', '江西', 28.315400, 117.709600, '其他', '["https://img1.baidu.com/it/u=2539138696,828638131&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《白鹿洞书院》', '九江市庐山市白鹿洞书院朱子祠遗址', '朱熹', '南宋', '九江庐山白鹿洞书院朱子祠遗址位于庐山五老峰南麓，是朱熹传播问渠那得清如许为有源头活水来学术思想的重要场所。白鹿洞书院始建于南唐升元年间，南宋淳熙六年朱熹知南康军时重建书院并亲自讲学，制定了著名的《白鹿洞书院揭示》，成为后世书院教育的范本。朱子祠保留了宋代建筑与朱熹手书碑刻，庄严肃穆。书院坐落于幽谷之中，前有贯道溪流水潺潺，后有五老峰峰峦叠嶂，古木参天、桂花飘香。书院与岳麓书院、应天书院、嵩阳书院并称为中国四大书院，是中国古代教育史上的里程碑。此地环境清幽，是感受宋代理学文化与书院精神的圣地。', '江西', 29.450800, 116.044900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Lushan_Geopark.jpg/1280px-Lushan_Geopark.jpg"]'),
('《南安军》', '赣州市大余县梅关古道南安驿遗址', '文天祥', '南宋', '赣州大余梅关古道南安驿遗址位于大余县梅岭之上，是文天祥创作梅花南北路风雨湿征衣的原始地点。梅关古道始建于秦代，是古代中原通往岭南的咽喉要道。南宋祥兴元年文天祥兵败被俘后经梅关古道北押，途经南安时写下了这首悲壮的《南安军》。古驿道保留了唐代石板路面与宋代关隘遗迹，两旁梅花冬日盛开，暗香浮动。驿站遗址残存夯土墙基与石柱础，记录了千年驿路的繁忙与沧桑。梅岭关口一脚跨两省，北望江西南眺广东，古人南迁北归皆由此经过。此地游客稀少，冬日赏梅时节古道上梅香四溢，是追寻文天祥爱国精神的重要历史遗存。', '江西', 25.401400, 114.361700, '其他', '["https://img0.baidu.com/it/u=3935001394,1261954147&fm=253&fmt=auto&app=138&f=JPEG?w=1067&h=800"]');
INSERT INTO works (title, scenic_spot, author, dynasty, description, province, latitude, longitude, category, images) VALUES
('《清平乐・村居》', '上饶市铅山县瓢泉辛弃疾故居遗址', '辛弃疾', '南宋', '上饶铅山瓢泉辛弃疾故居遗址位于铅山县稼轩乡，是辛弃疾创作茅檐低小溪上青青草的真实生活地。南宋绍熙年间辛弃疾被罢官后隐居瓢泉长达十余年，在此创作了大量词作。瓢泉因泉眼形似葫芦瓢而得名，清泉汩汩流出，汇成小溪蜿蜒而去。故居遗址保留了宋代泉眼与古碑，周围是茂林修竹、农田溪流，正合词中茅檐低小、溪上青草的田园意境。辛弃疾在此过着半耕半读的生活，却始终心系家国，留下了众多慷慨悲壮的词篇。此地远离城镇喧嚣，保留了南宋乡村的宁静风貌，是感受辛弃疾晚年田园生活与爱国情怀的重要遗存。', '江西', 28.315400, 117.709600, '其他', '["https://img2.baidu.com/it/u=1686151504,4157579781&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《书湖阴先生壁》', '抚州市临川区王安石故居湖阴先生壁遗址', '王安石', '北宋', '抚州临川王安石故居湖阴先生壁遗址位于临川区文昌里历史街区，是王安石创作一水护田将绿绕两山排闼送青来的原始描绘地。王安石晚年退居金陵时常忆少年故乡风光，此诗即以临川故居附近的山水为背景。遗址保留了宋代民居建筑遗存与古碑，院墙斑驳、古树参天。故居前有小溪环绕农田，远处青山如屏，正合诗中一水护田两山送青的意境。临川自古文风鼎盛，王安石、曾巩、晏殊、汤显祖等文学巨匠皆出于此，被誉为才子之乡。文昌里历史街区保留了明清古建筑群，青砖灰瓦、马头墙林立，文化底蕴极为深厚。', '江西', 27.934800, 116.312000, '其他', '["https://img2.baidu.com/it/u=1405566860,3107887231&fm=253&fmt=auto&app=120&f=JPEG?w=750&h=500"]'),
('《泷冈阡表》', '吉安市永丰县沙溪镇欧阳修故居碑亭', '欧阳修', '北宋', '吉安永丰沙溪镇欧阳修故居碑亭位于永丰县沙溪镇，是欧阳修为父亲撰写《泷冈阡表》的立碑之处。碑亭保留了欧阳修手书碑刻，字迹端庄秀丽，被誉为宋代书法精品。欧阳修幼年丧父，由母亲郑氏以荻画地教其识字，成年后为感念父亲功德而作此文，其中祭而丰不如养之薄也体现了深厚的孝道思想。碑亭为宋代建筑风格，飞檐翘角，古朴庄严。周围是赣中丘陵地貌，稻田连绵、溪水潺潺，保留了欧阳修少年时代的乡村风貌。永丰县是欧阳修的故乡，至今保留了欧阳修纪念馆与多处文化遗迹。此地游客稀少，是追寻欧阳修文学足迹与孝道精神的清幽之地。', '江西', 27.318300, 115.442500, '其他', '["https://img1.baidu.com/it/u=2459571739,3751128351&fm=253&fmt=auto&app=138&f=JPEG?w=399&h=302"]'),
('《墨池记》', '抚州市临川区曾巩故居墨池遗址', '曾巩', '北宋', '抚州临川曾巩故居墨池遗址位于临川区文昌里，是曾巩创作则学固岂可以少哉的原始地点。曾巩为唐宋八大家之一，其《墨池记》借王羲之临池学书的故事阐述了勤学苦练的重要性。墨池遗址保留了宋代泉眼与古碑，池水清澈，传说为王羲之洗笔之处。曾巩在文中以此激励后学，强调天赋不如勤奋的道理。故居周围是临川古城的核心区域，明清古建筑群保存完好，青砖灰瓦间透露着浓郁的书卷气息。临川自古以文风鼎盛著称，曾巩与王安石、晏殊等同为临川文化的杰出代表。此地环境清幽，是感受宋代文人勤学精神与临川文化底蕴的重要场所。', '江西', 27.934800, 116.312000, '其他', '["https://img1.baidu.com/it/u=980145675,1876690713&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1282"]'),
('《过松源晨炊漆公店》', '上饶市弋阳县漆公店遗址', '杨万里', '南宋', '上饶弋阳漆公店遗址位于弋阳县境内的赣闽古驿道旁，是杨万里创作正入万山圈子里一山放过一山拦的原始地点。南宋诗人杨万里清晨从松源出发，途经崎岖山路到漆公店歇脚时写下了这首富含哲理的小诗。遗址保留了宋代古民居与老茶馆的建筑遗存，石板路蜿蜒于丘陵之间。弋阳地处赣东北山区，群山环绕、峰峦叠嶂，行走其间确有一山放过一山拦之感。周边龟峰丹霞地貌壮美，赤色山岩与翠绿植被交相辉映。古驿道穿行于田野与山林之间，保留了南宋时期赣闽交通要道的原始风貌。此地游客罕至，是体验宋代旅行者跋山涉水艰辛历程的独特场所。', '江西', 28.378400, 117.459100, '其他', '["https://img2.baidu.com/it/u=1267498843,105009799&fm=253&fmt=auto&app=138&f=JPEG?w=668&h=500"]'),
('《入彭蠡湖口》', '九江市湖口县石钟山望湖亭遗址', '谢灵运', '南北朝', '九江湖口石钟山望湖亭遗址位于石钟山顶，是谢灵运创作乘月听哀狖浥露馥芳荪的原始描绘地。谢灵运为中国山水诗开创者，南朝宋时曾泛舟鄱阳湖，途经湖口时登石钟山远眺，留下了《入彭蠡湖口》这首气势磅礴的山水诗。望湖亭遗址保留了晋代亭基与唐代碑刻，登高可俯瞰鄱阳湖浩渺水面与长江奔流交汇的壮观景象。鄱阳湖是中国最大的淡水湖，湖面烟波浩渺，候鸟翔集。石钟山扼守湖江交汇要冲，自古为军事要地。此地远离旅游热线，保留了南朝以来的原始山水意境，是追寻中国山水诗源头的重要文化遗存。', '江西', 29.731400, 116.218600, '其他', '["https://img1.baidu.com/it/u=4176062083,4126340603&fm=253&fmt=auto&app=120&f=JPEG?w=500&h=1111"]'),
('《晚泊浔阳望庐山》', '九江市浔阳区浔阳楼唐代遗址', '孟浩然', '唐代', '九江浔阳区浔阳楼唐代遗址位于浔阳江畔，是孟浩然途经九江时写下挂席几千里名山都未逢的感怀之地。浔阳楼始建于唐代，因地处浔阳古城江边而得名，历代文人墨客多有登临赋诗。唐代夯土台基保存于现楼基之下，记录了这座江楼最初的规模。浔阳楼因《水浒传》中宋江题反诗而更加闻名于世。楼前长江浩荡东流，江面上船帆往来，远处庐山隐约可见。周边保留了浔阳古城的历史街区，老巷、老铺、老码头构成了浓郁的古城氛围。此地是感受唐代诗人行旅江南、登楼望远情怀的重要文化遗存。', '江西', 29.705000, 115.989900, '其他', '["https://img2.baidu.com/it/u=122456930,3431409619&fm=253&fmt=auto&app=138&f=JPEG?w=897&h=800"]'),
('《题乌江亭》', '上饶市余干县乌江亭遗址', '杜牧', '唐代', '上饶余干乌江亭遗址位于余干县境内，是杜牧创作江东子弟多才俊卷土重来未可知的原始地点。杜牧途经此地时凭吊项羽乌江自刎的历史故事，借古讽今写下了这首著名的咏史绝句。遗址保留了汉代亭基与唐代碑刻，古亭虽已不存但台基依然可辨。亭前江水滔滔，岸边芦苇摇曳，秋日萧瑟之景令人遥想楚汉争霸的历史烟云。杜牧以江东子弟多才俊来为项羽惋惜，表达了对英雄末路的同情与对历史抉择的深层思考。周边是赣东北水乡地貌，河网密布、稻田连绵，保留了江南水乡的原始风貌。此地游客极少，是凭吊历史、品味杜牧咏史诗情的清幽之地。', '江西', 28.702000, 116.695600, '其他', '["https://img1.baidu.com/it/u=3430558047,1086280319&fm=253&fmt=auto&app=120&f=JPEG?w=500&h=750"]'),
('《浣溪沙・一曲新词酒一杯》', '南昌市进贤县晏殊故居遗址', '晏殊', '北宋', '南昌进贤晏殊故居遗址位于进贤县境内，是晏殊创作无可奈何花落去似曾相识燕归来的原始地点。晏殊为北宋著名词人、宰相，自幼聪颖过人，十四岁即以神童入试。故居遗址保留了宋代建筑基础与古碑，记录了这位太平宰相的生平事迹。晏殊词风温润典雅，善于以精致笔触描绘春花秋月、离愁别绪，其小令被誉为宋词中的珠玉之作。故居周围是赣中平原地貌，湖泊星罗棋布、稻田连绵。进贤县文风鼎盛，晏殊与其子晏几道并称为二晏，是宋词史上的父子双璧。此地游客稀少，是追寻北宋词坛领袖文学足迹的重要遗存。', '江西', 28.377000, 116.241200, '其他', '["https://img1.baidu.com/it/u=1657808988,2794792209&fm=253&fmt=auto&app=138&f=JPEG?w=667&h=500"]'),
('《临江仙・梦后楼台高锁》', '南昌市进贤县晏几道故居遗址', '晏几道', '北宋', '南昌进贤晏几道故居遗址位于进贤县境内，与父亲晏殊故居相邻，是晏几道创作落花人独立微雨燕双飞的原始地点。晏几道为晏殊第七子，继承了父亲的词学传统却风格更为深婉凄迷。故居遗址保留了宋代建筑与古碑，院落布局依稀可辨。晏几道一生仕途坎坷，却在词作中展现了极高的艺术成就，其《小山词》被誉为宋词中的精品。词中落花独立、微雨燕飞的意象历来为人称颂，被认为是宋词中最优美的画面之一。故居周围湖光山色秀美，春日花落雨细时与词中意境颇为吻合。此地与晏殊故居同为感受北宋二晏词学传统的重要文化遗存。', '江西', 28.377000, 116.241200, '其他', '["https://img2.baidu.com/it/u=3533314152,1537423822&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=736"]'),
('《过大孤山小孤山》', '九江市彭泽县小孤山遗址', '陆游', '南宋', '九江彭泽小孤山遗址位于彭泽县长江南岸，是陆游在《过大孤山小孤山》中描绘的大孤小孤江中央的实景地。小孤山屹立于长江急流之中，山高仅百余米却形势险峻，自古为长江要津。陆游南宋时期乘舟入蜀途经此地，被小孤山的奇秀所震撼，在日记中详细记录了山势与江景。遗址保留了唐代古寺启秀寺与摩崖石刻，寺庙依山而建，气势壮观。小孤山因形似古代妇人发髻而又名髻山，山上古木苍翠、庙宇庄严，山下江水奔腾、旋涡激荡。登山远眺可见长江浩荡东去，鄱阳湖口烟波浩渺。此地是感受长江天险与宋代文人行旅情怀的重要景观。', '江西', 29.898900, 116.549400, '其他', '["https://img0.baidu.com/it/u=3987145977,2365708959&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=652"]'),
('《偶成》', '上饶市婺源县朱熹故居遗址', '朱熹', '南宋', '上饶婺源朱熹故居遗址位于婺源县城内，是朱熹创作少年易老学难成一寸光阴不可轻的原始地点。朱熹祖籍婺源，虽出生于福建尤溪，但一生多次回乡祭祖讲学，对婺源有着深厚的故土情结。故居遗址保留了宋代建筑基础与古碑，院内有朱熹手植古樟。婺源以徽派古村落闻名于世，白墙黛瓦的古民居依山傍水，春日油菜花金黄遍野，秋日红枫如火。朱熹在此写下的《偶成》劝诫世人珍惜时光、勤勉学习，至今仍被广泛传颂。婺源素有书乡之称，朱熹的理学思想深刻影响了当地的文化传统。此地是感受朱熹故土情怀与婺源书香文化的重要场所。', '江西', 29.248400, 117.861400, '其他', '["https://img0.baidu.com/it/u=2264348485,3695839986&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1423"]'),
('《扬子江》', '九江市彭泽县扬子江渡口遗址', '文天祥', '南宋', '九江彭泽扬子江渡口遗址位于彭泽县长江岸边，是文天祥创作臣心一片磁针石不指南方不肯休的原始地点。南宋祥兴年间文天祥从镇江脱险后辗转至此渡江南归，面对滔滔江水写下了这首表达忠贞爱国之心的名诗。渡口遗址保留了宋代码头石阶与古碑，江岸上柳树成行，江面上白帆点点。文天祥以磁针石比喻自己矢志不渝的爱国之心，即使身处险境也誓不屈服。彭泽自古为长江重要渡口，陶渊明曾任彭泽令，文化底蕴深厚。渡口周边保留了古驿道与老渡口的原始风貌，江风猎猎、波涛汹涌。此地是缅怀文天祥民族气节与爱国精神的重要历史遗存。', '江西', 29.898900, 116.549400, '其他', '["https://img0.baidu.com/it/u=3211583761,2775076671&fm=253&fmt=auto&app=138&f=JPEG?w=764&h=500"]'),
('《登庐山五老峰》', '九江市庐山市庐山五老峰遗址', '李白', '唐代', '九江庐山五老峰遗址位于庐山东南部，是李白创作庐山东南五老峰青天削出金芙蓉的描绘地。五老峰因山峰并列如五位老人端坐而得名，是庐山最壮美的山峰之一。峰顶海拔约一千四百米，危崖峭壁、奇松怪石，被李白比喻为青天削出的金色芙蓉花。唐代摩崖石刻保存于山岩之上，记录了历代文人对五老峰的赞叹。登临峰顶可远眺鄱阳湖浩渺水面与赣北平原，云海翻涌时五峰若隐若现，气象万千。日出时分金光洒满峰峦，确如金芙蓉般灿烂辉煌。此地位于庐山东线游览区，游客相对较少，是体验庐山雄奇之美的绝佳观景点。', '江西', 29.450800, 116.044900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Lushan_Geopark.jpg/1280px-Lushan_Geopark.jpg"]'),
('《牡丹亭・惊梦》', '抚州市临川区汤显祖故居玉茗堂遗址', '汤显祖', '明代', '抚州临川汤显祖故居玉茗堂遗址位于临川区文昌里，是汤显祖创作原来姹紫嫣红开遍似这般都付与断井颓垣的原始地点。玉茗堂是汤显祖晚年退隐后的书房与创作场所，《牡丹亭》《紫钗记》《邯郸记》《南柯记》合称临川四梦皆在此完成。遗址保留了明代建筑基础与戏台遗迹，庭院中曾种植白色玉茗花。汤显祖以至情论闻名于世，《牡丹亭》中杜丽娘游园惊梦的场景已成为中国戏曲史上最经典的片段。文昌里历史街区经过修复保留了明清建筑群，汤显祖纪念馆与戏曲展演空间再现了临川四梦的艺术魅力。此地是中国戏曲文化的重要朝圣之地。', '江西', 27.934800, 116.312000, '其他', '["https://img2.baidu.com/it/u=2506379186,552818321&fm=253&fmt=auto&app=138&f=JPEG?w=550&h=452"]'),
('《游庐山记》', '九江市庐山市庐山栖贤寺遗址', '苏辙', '北宋', '九江庐山栖贤寺遗址位于庐山南麓栖贤谷中，是苏辙在《游庐山记》中描绘庐山之美在山南的原始地点。栖贤寺始建于南朝，唐代最为鼎盛，因传说有贤者在此隐居而得名。苏辙元丰年间游庐山时对栖贤谷的幽深秀美印象深刻，在游记中详细描述了山谷溪瀑、古木苍翠的壮美景象。遗址保留了唐代古寺建筑基础与摩崖石刻，谷中三峡涧水流湍急，飞瀑如帘。栖贤寺位于庐山南线，远离北线主景区的喧嚣，保留了原始的山林风貌。古寺虽已残破，但周围环境清幽、禅意浓厚，是感受庐山南麓幽深之美与宋代文人山水情怀的绝佳去处。', '江西', 29.450800, 116.044900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Lushan_Geopark.jpg/1280px-Lushan_Geopark.jpg"]'),
('《题落星寺》', '九江市庐山市落星寺遗址', '黄庭坚', '北宋', '九江庐山落星寺遗址位于庐山南麓落星湖畔，是黄庭坚创作落星开士深结屋龙阁老翁来赋诗的描绘地。落星寺因传说有星石坠落于此而得名，始建于唐代，曾是庐山南麓重要的佛教寺院。黄庭坚多次游庐山时到此访寺赋诗，留下了多首吟咏落星寺的诗篇。遗址保留了唐代寺基与宋代碑刻，寺前落星湖水清如镜，倒映着庐山群峰与蓝天白云。周围古木参天、藤萝缠绕，山鸟啼鸣声声入耳。庐山南麓游客稀少，保留了唐宋以来的原始山林风貌。此地是追寻黄庭坚庐山诗踪与感受唐代古寺清幽禅意的重要文化遗存。', '江西', 29.450800, 116.044900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Lushan_Geopark.jpg/1280px-Lushan_Geopark.jpg"]'),
('《象山书院》', '抚州市金溪县象山书院遗址', '陆九渊', '南宋', '抚州金溪象山书院遗址位于金溪县城内，是陆九渊传播宇宙便是吾心吾心即是宇宙心学思想的核心场所。象山书院始建于南宋淳熙年间，因陆九渊在金溪象山讲学而得名，是中国心学的发源地。遗址保留了宋代建筑基础与古碑，书院虽历经沧桑但规模依稀可辨。陆九渊提倡心即理，强调发明本心，与朱熹的理学思想形成了著名的鹅湖之会学术论辩。金溪县自古文风鼎盛，是王安石变法重臣曾布的故乡。书院周围保留了明清古建筑群，竹塘书院等文化遗存见证了金溪的耕读传统。此地游客罕至，是了解中国心学渊源与南宋学术思想的重要文化遗存。', '江西', 27.918800, 116.755100, '其他', '["https://img1.baidu.com/it/u=216071264,3966788395&fm=253&fmt=auto&app=138&f=JPEG?w=666&h=500"]'),
('《井冈山》', '吉安市井冈山市黄洋界哨口遗址', '毛泽东', '现代', '吉安井冈山黄洋界哨口遗址位于井冈山市茨坪西北面，是毛泽东创作黄洋界上炮声隆报道敌军宵遁的原始地点。1928年红军以不足一个营的兵力在黄洋界成功击退了敌军四个团的进攻，毛泽东闻讯后在回师途中欣然写下了《西江月·井冈山》。遗址保留了红军战壕、掩体工事与一门迫击炮，山势险峻、地形险要，素有一夫当关万夫莫开之势。黄洋界海拔一千三百余米，常年云雾缭绕，云海翻涌时蔚为壮观。哨口前方视野开阔，可俯瞰绵延群山与深邃峡谷。此地是中国革命史上的重要遗址，也是感受井冈山革命精神与壮美自然风光的红色圣地。', '江西', 26.748000, 114.289700, '其他', '["https://img2.baidu.com/it/u=305680295,4068093534&fm=253&fmt=auto&app=138&f=JPEG?w=750&h=500"]'),
('《桃花源记》', '九江市庐山市康王谷桃花源遗址', '陶渊明', '东晋', '九江庐山康王谷桃花源遗址位于庐山市境内，是陶渊明《桃花源记》中世外桃源的真实原型地。东晋末年陶渊明深感世事纷扰，以康王谷为蓝本创作了这篇千古名文，描绘了一个与世隔绝、怡然自乐的理想社会。遗址保留了晋代古驿道与陶渊明隐居处遗迹，峡谷入口狭窄曲折，深入后豁然开朗，与文中初极狭才通人复行数十步豁然开朗的描写惊人吻合。谷中平畴良田、竹篱茅舍，春日桃花灼灼盛开，溪水清澈见底。康王谷因山势封闭、交通不便而保留了原始的自然与人文风貌，远离庐山主景区的喧嚣。此地是中国田园文学的精神故乡，也是追寻桃花源理想的最本真之地。', '江西', 29.450800, 116.044900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Lushan_Geopark.jpg/1280px-Lushan_Geopark.jpg"]'),
('《滕王阁序》', '南昌市东湖区滕王阁唐代台基遗址', '王勃', '唐代', '南昌东湖区滕王阁唐代台基遗址是王勃千古名篇《滕王阁序》的诞生地，也是中国文学史上最辉煌的即席创作之一。唐上元二年王勃途经南昌赴交趾探父，恰逢洪州都督阎伯屿在滕王阁举办盛宴，年仅二十六岁的王勃挥毫写下了这篇气势恢宏的骈文。台基遗址保留了唐代夯土台基与宋代柱础，记录了滕王阁最初的建筑规模。序文中落霞与孤鹜齐飞秋水共长天一色的壮丽画面至今仍是中国文学中最经典的意象之一。赣江从阁前奔流而过，秋日黄昏时江天一色、霞光万道，与序文中的描写完美呼应。此地是中国文人追慕唐代风华的精神坐标。', '江西', 28.684900, 115.899300, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/d/dd/Pavilion_of_Prince_Teng_3.jpg/1280px-Pavilion_of_Prince_Teng_3.jpg"]'),
('《石钟山记》', '九江市湖口县石钟山下钟山遗址', '苏轼', '北宋', '九江湖口石钟山下钟山遗址是苏轼《石钟山记》的实地考察地，也是中国古代科学散文的典范之作。苏轼对前人关于石钟山命名由来的说法不满，元丰七年亲自乘舟至绝壁之下实地考察，发现山石中空与水波激荡产生钟鸣之声，于是写下了这篇求真务实的散文。遗址保留了唐代摩崖石刻与古寺遗迹，山石嶙峋、形态各异，水击石壁时确能听到回响之声。鄱阳湖与长江在此交汇，一清一浊泾渭分明，自古即为军事要冲。山上古木参天，登高可远眺浩渺湖面。苏轼事必躬亲的科学态度使此文超越了一般游记，成为中国散文史上的名篇。', '江西', 29.731400, 116.218600, '其他', '["https://img1.baidu.com/it/u=4029451805,2538379395&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《泷冈阡表》', '吉安市永丰县沙溪镇欧阳修故居碑亭', '欧阳修', '北宋', '吉安永丰沙溪镇欧阳修故居碑亭是欧阳修为父亲撰写《泷冈阡表》并立碑的地方，碑文被誉为中国古代祭文中的巅峰之作。欧阳修幼年丧父，由母亲郑氏以荻画地教其识字，这段经历成为千古佳话。碑亭保留了欧阳修亲笔书写的碑刻，书法端正秀丽，情真意切。文中祭而丰不如养之薄也传达了深沉的孝道思想，影响深远。碑亭建筑为宋代风格，飞檐翘角，周围古樟掩映。永丰县是赣中腹地的文化名县，欧阳修纪念馆与文忠公祠等遗迹散布县内。碑亭所在的沙溪镇保留了赣中乡村的淳朴风貌，田野开阔、溪流清澈，是追寻欧阳修孝道精神的清幽之地。', '江西', 27.318300, 115.442500, '其他', '["https://img1.baidu.com/it/u=2459571739,3751128351&fm=253&fmt=auto&app=138&f=JPEG?w=399&h=302"]'),
('《墨池记》', '抚州市临川区曾巩故居墨池遗址', '曾巩', '北宋', '抚州临川曾巩故居墨池遗址是曾巩《墨池记》的创作地，也是中国古代勤学精神的重要象征。曾巩借王羲之临池学书、池水尽黑的故事，阐述了学固岂可以少哉的深刻道理。墨池遗址保留了宋代泉眼与古碑，池水虽已不似传说中那般墨黑，但清泉汩汩、古意盎然。曾巩为唐宋八大家之一，文风朴实严谨、说理透彻。故居位于临川文昌里历史街区核心区域，周围明清古建筑群保存完好，粉墙黛瓦间弥漫着浓郁的书卷气息。临川是中国著名的才子之乡，王安石、曾巩、晏殊、汤显祖皆出于此。此地环境清幽，是品味宋代文人风骨与临川文脉的重要场所。', '江西', 27.934800, 116.312000, '其他', '["https://img1.baidu.com/it/u=980145675,1876690713&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1282"]'),
('《白鹿洞书院揭示》', '九江市庐山市白鹿洞书院朱子祠遗址', '朱熹', '南宋', '九江庐山白鹿洞书院朱子祠遗址是朱熹制定《白鹿洞书院揭示》的核心场所，也是中国古代书院教育制度的奠基之地。南宋淳熙六年朱熹知南康军时重建白鹿洞书院，亲自讲学并制定了博学之审问之慎思之明辨之笃行之的教育纲领，成为后世七百余年书院教育的范本。朱子祠保留了宋代建筑与朱熹手书碑刻，殿堂庄严、碑石林立。书院坐落于庐山五老峰南麓的幽谷之中，贯道溪穿院而过，溪水清澈见底。古木参天、桂花飘香，环境极为清幽。白鹿洞书院与岳麓书院、应天书院、嵩阳书院并称中国四大书院，是中国教育史与理学思想的圣地。', '江西', 29.450800, 116.044900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Lushan_Geopark.jpg/1280px-Lushan_Geopark.jpg"]'),
('《指南录后序》', '赣州市章贡区郁孤台遗址', '文天祥', '南宋', '赣州章贡区郁孤台遗址不仅承载了辛弃疾的爱国词章，也是文天祥《指南录后序》中臣心一片磁针石精神的重要背景地。文天祥于南宋末年在赣州组织勤王义军，郁孤台下的赣江曾见证了他为保家卫国而奋斗的身影。遗址保留了宋代台基与明清碑刻，台上视野开阔，可俯瞰章贡两江交汇与赣州古城全貌。文天祥在《指南录后序》中详述了自己九死一生的逃亡经历，字字血泪。赣州宋代古城墙保存完好，绵延数公里，是全国保存最完整的宋城墙。浮桥横跨贡江，古榕掩映城楼，历史厚重感扑面而来。此地是感受南宋末年志士仁人爱国精神的重要历史遗存。', '江西', 25.831100, 114.935000, '其他', '["https://img2.baidu.com/it/u=416380716,1054047509&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《牡丹亭》', '抚州市临川区汤显祖故居玉茗堂遗址', '汤显祖', '明代', '抚州临川汤显祖故居玉茗堂遗址是汤显祖创作《牡丹亭》的场所，同样也是《紫钗记》《邯郸记》《南柯记》等临川四梦的诞生地。玉茗堂以汤显祖喜爱的白色山茶花命名，是他晚年退隐后专心戏曲创作的书房。《牡丹亭》中杜丽娘与柳梦梅的至情故事跨越生死，是中国戏曲史上的不朽经典。遗址保留了明代建筑基础与戏台遗迹，庭院中曾繁花似锦。汤显祖被誉为东方的莎士比亚，与莎士比亚同年辞世。文昌里历史街区经修复后设有汤显祖纪念馆与戏曲展演空间，定期上演昆曲版《牡丹亭》。此地是中国戏曲文化的精神高地与朝圣之地。', '江西', 27.934800, 116.312000, '其他', '["https://img2.baidu.com/it/u=2506379186,552818321&fm=253&fmt=auto&app=138&f=JPEG?w=550&h=452"]'),
('《柳如是别传》', '九江市修水县陈寅恪故居遗址', '陈寅恪', '现代', '九江修水陈寅恪故居遗址位于修水县义宁镇，是近代学术大师陈寅恪的出生地与童年成长之处。陈寅恪被誉为教授的教授，其晚年力作《柳如是别传》以明末才女柳如是为主角，实为借古人之杯酒浇自己之块垒。故居为清代建筑风格，保留了陈寅恪手稿、家族照片与生平陈列。修水陈氏家族为近代文化世家，陈寅恪之祖父陈宝箴为湖南巡抚、父亲陈三立为近代著名诗人，一门三代皆为文化巨擘。故居周围是赣西北山区，修河穿城而过，青山绿水环绕。此地游客极少，环境清幽，是了解陈寅恪家学渊源与近代学术史的重要场所。', '江西', 29.025300, 114.546900, '其他', '["https://img0.baidu.com/it/u=1842853695,3684221962&fm=253&fmt=auto&app=138&f=JPEG?w=750&h=500"]'),
('《小李飞刀》', '南昌市新建区古龙故居遗址', '古龙', '现代', '南昌新建古龙故居遗址位于新建区境内，是武侠小说大师古龙的祖籍地与创作灵感来源之一。古龙原名熊耀华，祖籍江西南昌，其代表作《小李飞刀》系列塑造了李寻欢这一经典武侠人物形象，小李飞刀例不虚发已成为中国武侠文化的标志性符号。故居遗址保留了民国时期建筑与古龙早期手稿。古龙开创了新派武侠小说的独特风格，以简洁凌厉的笔触、悬疑推理的结构和对人性深刻的洞察著称，与金庸、梁羽生并称为中国武侠小说三大宗师。故居周围是赣江平原地貌，水网密布、稻田连绵。此地是武侠迷追寻古龙文学足迹的独特之地。', '江西', 28.692600, 115.815000, '其他', '["https://img1.baidu.com/it/u=3410100219,908250730&fm=253&fmt=auto&app=138&f=JPEG?w=687&h=500"]'),
('《大江东去》', '南昌市东湖区八一广场老厂房遗址', '阿耐', '现代', '南昌东湖区八一广场老厂房遗址是阿耐小说《大江东去》中宋运辉工作的化工厂原型地，也是改革开放初期中国工业发展的缩影。小说以宋运辉、雷东宝、杨巡三个人物为主线，展现了改革开放从农村到城市、从个体到国企的波澜壮阔历程。老厂房遗址保留了上世纪七八十年代的工业建筑、烟囱与厂区布局，红砖墙上的标语依稀可辨。南昌作为重要的工业城市，见证了中国从计划经济向市场经济转型的全过程。《大江东去》改编为电视剧《大江大河》后广受好评。此地是感受中国改革开放初期工业记忆与时代变迁的独特场所。', '江西', 28.684900, 115.899300, '其他', '["https://img1.baidu.com/it/u=2753588137,3209656502&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=667"]'),
('《小镇上的将军》', '南昌市新建区生米镇老街遗址', '陈世旭', '现代', '南昌新建生米镇老街遗址是陈世旭小说《小镇上的将军》的原型地，保留了清末民初的民居、老商铺与街巷格局。小说以一位退伍将军回到赣中小镇的生活为主线，描绘了改革开放初期中国乡镇社会的众生相。老街两旁为砖木结构的二层商铺，青石板路磨得光滑，檐下挂着竹帘与布幌，充满了赣中小镇的烟火气息。生米镇地处赣江西岸，因三国时期诸葛亮在此煮米未熟而发兵的传说得名。镇上保留了古渡口、宗祠与老戏台等文化遗存。此地远离旅游线路，游客罕至，保留了赣中乡镇最真实的生活状态，是感受中国基层社会变迁的鲜活标本。', '江西', 28.692600, 115.815000, '其他', '["https://img2.baidu.com/it/u=2906555981,3753846521&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=653"]'),
('《文化苦旅・庐山》', '九江市庐山市牯岭老别墅遗址', '余秋雨', '现代', '九江庐山牯岭老别墅遗址位于庐山牯岭镇，是余秋雨《文化苦旅·庐山》中重点描绘的文化景观。十九世纪末至二十世纪初，英、美、法等国传教士与外交官在牯岭建造了数百座欧式别墅，使庐山成为万国建筑博物馆。老别墅群保留了哥特式、罗马式、巴洛克式等多种西方建筑风格，石墙红顶掩映在云雾松林之间。余秋雨在文中以独特视角审视庐山的文化层累，从政治到宗教、从中国到西方，揭示了庐山作为文化高地的深层意义。牯岭海拔约一千一百米，夏季凉爽宜人，曾是近代中国最著名的避暑胜地。老别墅中部分已改为展览馆，游客可入内参观，感受百年前中西文化交融的独特氛围。', '江西', 29.450800, 116.044900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Lushan_Geopark.jpg/1280px-Lushan_Geopark.jpg"]'),
('《徐霞客游记・江右游日记》', '上饶市弋阳县龟峰老人峰遗址', '徐霞客', '明代', '上饶弋阳龟峰老人峰遗址位于弋阳县龟峰景区内，是徐霞客《江右游日记》中重点描绘的丹霞地貌奇观。老人峰因山石形似一位端坐的老者而得名，是龟峰最具标志性的景观。徐霞客于明崇祯年间游历江西时登临龟峰，在日记中赞叹其山石之奇为平生所未见。遗址保留了明代摩崖石刻，记录了历代文人对龟峰的赞美。龟峰属典型的丹霞地貌，红色砂岩经亿万年风化侵蚀形成了形态各异的山峰，有如龟、如鹰、如佛、如仙的诸多象形石。景区内还保留了南岩寺等古代石窟寺遗迹。此地是世界自然遗产中国丹霞的组成部分，也是感受徐霞客探险精神的重要场所。', '江西', 28.378400, 117.459100, '其他', '["https://img2.baidu.com/it/u=2844068458,3517886468&fm=253&fmt=auto&app=138&f=JPEG?w=800&h=1067"]'),
('《水经注・赣水注》', '赣州市章贡区八境台遗址', '郦道元', '北魏', '赣州章贡区八境台遗址位于赣州古城北门城墙之上，是郦道元《水经注·赣水注》中重点记载的历史景观。八境台始建于北宋嘉祐年间，因登台可望八方美景而得名。郦道元虽为北魏时人，但其《水经注》中对赣水流域的详细记载为后世了解赣州地理提供了珍贵资料。遗址保留了宋代建筑基础与古碑，台上视野开阔，可俯瞰章贡两江交汇的壮观景象。赣州古城墙始建于汉代，现存宋代城墙绵延数公里，城墙上古炮台、马面、垛口保存完好。八境台下赣江奔流不息，浮桥横跨江面，古榕盘踞城头。此地是赣州千年城市历史的见证，也是感受宋代城市文明的重要遗存。', '江西', 25.831100, 114.935000, '其他', '["https://img1.baidu.com/it/u=674385519,798620357&fm=253&fmt=auto&app=138&f=JPEG?w=762&h=500"]'),
('《游庐山记》', '九江市庐山市庐山秀峰遗址', '杨万里', '南宋', '九江庐山秀峰遗址位于庐山南麓，是杨万里《游庐山记》中重点描绘的景区。秀峰因群峰竞秀而得名，包括鹤鸣峰、双剑峰、姐妹峰等诸峰，山势秀丽多姿。杨万里于南宋时期游览庐山，被秀峰的清幽秀美所折服，在游记中留下了生动细致的描写。遗址保留了唐代摩崖石刻与黄岩瀑布，李白的飞流直下三千尺即描绘此处瀑布。秀峰还保留了南唐中主李璟创建的开先寺遗迹，寺院虽已不存但石刻犹在。秀峰位于庐山南线，远离北线牯岭的游客集中区域，保留了较为原始的山林风貌。春日山花烂漫、夏日飞瀑如练、秋日红叶满山，是庐山最具秀美气质的景区。', '江西', 29.450800, 116.044900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Lushan_Geopark.jpg/1280px-Lushan_Geopark.jpg"]'),
('《象山语录》', '抚州市金溪县象山书院遗址', '陆九渊', '南宋', '抚州金溪象山书院遗址是陆九渊讲学并形成《象山语录》的核心场所，也是中国心学思想的发祥地。陆九渊在此讲学时提出心即理的核心观点，主张学问应从发明本心入手，与朱熹的格物致知形成了南宋学术史上最著名的理学与心学之争。遗址保留了宋代建筑基础与古碑，书院规模依稀可辨。象山书院鼎盛时期学生达数千人，学风自由开放。陆九渊与朱熹在鹅湖寺进行的鹅湖之会是中国哲学史上的经典论辩。金溪县保留了明清古建筑群与多处书院遗迹，耕读文化传统深厚。此地是中国哲学史上心学流派的源头之地，也是了解宋代学术论辩与书院文化的重要场所。', '江西', 27.918800, 116.755100, '其他', '["https://img1.baidu.com/it/u=216071264,3966788395&fm=253&fmt=auto&app=138&f=JPEG?w=666&h=500"]'),
('《永乐大典》总纂', '吉安市吉水县解缙故居遗址', '解缙', '明代', '吉安吉水解缙故居遗址位于吉水县城内，是明代大才子解缙的出生地与成长之处。解缙为明初第一才子，永乐元年奉命总纂《永乐大典》，这部汇集古今图书七八千种、共计两万两千余卷的巨著是中国古代最大的类书，也是世界文化史上的伟大工程。故居遗址保留了明代建筑基础与古碑，院落布局清晰可辨。解缙自幼聪颖过人，有才高八斗、学富五车之誉，然因性格耿直而屡遭贬谪，最终含冤而死。吉水素有状元之乡美誉，历代共出进士五百余人。故居周围保留了明清古建筑群与文化遗存，是感受明代文人风骨与吉安庐陵文化的重要场所。', '江西', 27.229800, 115.135500, '其他', '["https://img1.baidu.com/it/u=3355828622,3511988764&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=607"]'),
('《紫钗记》', '抚州市临川区汤显祖故居玉茗堂遗址', '汤显祖', '明代', '抚州临川汤显祖故居玉茗堂遗址同样是《紫钗记》的创作地。《紫钗记》取材于唐代蒋防的传奇小说《霍小玉传》，讲述了霍小玉与李益之间凄美动人的爱情故事。汤显祖在原作基础上大幅改编，将悲剧结局改为大团圆，体现了他以情抗理的至情思想。玉茗堂保留了明代建筑遗迹与戏台基址，汤显祖在此完成了临川四梦的创作。《紫钗记》是四梦中最早的一部，已展现出汤显祖对情感主题的深刻关注。文昌里历史街区经修复后古韵犹存，粉墙黛瓦的明清建筑群保存完好。此地是了解汤显祖戏曲创作历程与明代戏曲文化的重要场所。', '江西', 27.934800, 116.312000, '其他', '["https://img2.baidu.com/it/u=2506379186,552818321&fm=253&fmt=auto&app=138&f=JPEG?w=550&h=452"]'),
('《忠雅堂集》', '上饶市铅山县蒋士铨故居遗址', '蒋士铨', '清代', '上饶铅山蒋士铨故居遗址位于铅山县城内，是清代著名诗人、戏曲家蒋士铨的出生地与创作之处。蒋士铨与袁枚、赵翼并称为乾隆三大家，其《忠雅堂集》收录了诗歌、戏曲、散文等多种体裁的作品，展现了清代中期文学的最高水平。故居保留了清代建筑与古碑，院落雅致、花木扶疏。蒋士铨以忠孝节义为创作主题，戏曲作品尤为人称道。铅山县自古文风鼎盛，辛弃疾晚年曾隐居于此，留下了大量词作。县内保留了明清古建筑群与河口古镇等历史遗存。故居所在街区青砖灰瓦、古木参天，是感受清代文学氛围与赣东北人文底蕴的清幽之地。', '江西', 28.315400, 117.709600, '其他', '["https://img1.baidu.com/it/u=2512464817,1334919187&fm=253&fmt=auto&app=138&f=JPEG?w=667&h=500"]'),
('《元白诗笺证稿》', '九江市修水县陈寅恪故居遗址', '陈寅恪', '现代', '九江修水陈寅恪故居遗址同样是《元白诗笺证稿》的创作地。陈寅恪以考据精密、识见宏通著称，《元白诗笺证稿》是其以诗证史方法论的代表作，通过对白居易、元稹诗歌的深入笺注，还原了唐代中期的政治生态与社会风貌。故居为清代建筑风格，保留了陈寅恪家族世代积累的文化遗存。修水陈氏一族以学术传家，陈宝箴的维新思想、陈三立的同光体诗歌、陈寅恪的史学研究构成了中国近代学术史上最辉煌的家族传承。故居周围修河蜿蜒、青山环抱，赣西北山区的清幽环境正适合学术沉思。此地是了解近代中国最杰出学术家族的珍贵文化遗存。', '江西', 29.025300, 114.546900, '其他', '["https://img0.baidu.com/it/u=1842853695,3684221962&fm=253&fmt=auto&app=138&f=JPEG?w=750&h=500"]'),
('《楚留香传奇》', '南昌市新建区古龙故居遗址', '古龙', '现代', '南昌新建古龙故居遗址同样是《楚留香传奇》系列小说的创作灵感地。楚留香是古龙笔下最潇洒风流的武侠人物，闻香识人、智勇双全，被誉为武侠小说中最具魅力的盗帅形象。古龙以独特的侦探推理式写法颠覆了传统武侠小说的叙事模式，每个案件都充满悬疑与反转。故居遗址保留了民国建筑与古龙早期创作相关的遗物。古龙一生创作了七十余部武侠小说，《楚留香传奇》与《小李飞刀》并列为其最具影响力的系列作品。南昌作为古龙的祖籍地，赣江奔流、英雄辈出的气质与古龙小说中的侠义精神颇为契合。此地是武侠文化爱好者探访古龙文学世界的独特之地。', '江西', 28.692600, 115.815000, '其他', '["https://img1.baidu.com/it/u=3410100219,908250730&fm=253&fmt=auto&app=138&f=JPEG?w=687&h=500"]'),
('《都挺好》', '南昌市东湖区老城区民德路弄堂', '阿耐', '现代', '南昌东湖区老城区民德路弄堂是阿耐小说《都挺好》中苏家老宅的原型地，保留了清末民初的民居与老商铺。小说以苏家三兄妹的家庭矛盾为主线，深刻揭示了中国式家庭中的重男轻女、啃老、养老等社会问题，引发了广泛的社会讨论。民德路弄堂为南昌老城区典型的里弄建筑，砖木结构的二层楼房紧密排列，窄巷中晾衣绳交错、自行车依墙停放，充满了老城区的生活气息。弄堂深处保留了水井、石板路与老式木门窗，居民们的日常生活依然保持着传统节奏。《都挺好》改编为同名电视剧后热播全国，此地成为感受中国城市家庭生活变迁的鲜活空间。', '江西', 28.684900, 115.899300, '其他', '["https://img1.baidu.com/it/u=1824288015,3340436685&fm=253&fmt=auto&app=138&f=JPEG?w=657&h=1276"]'),
('《井冈山的斗争》', '吉安市井冈山市茅坪八角楼后山遗址', '毛泽东', '现代', '吉安井冈山茅坪八角楼后山遗址是毛泽东撰写《井冈山的斗争》的历史背景地，保留了红军密营与革命遗迹。1928年毛泽东在茅坪八角楼的油灯下写下了《中国的红色政权为什么能够存在》和《井冈山的斗争》两篇光辉著作，为中国革命指明了农村包围城市的道路。后山密营是红军在敌人围剿时的秘密驻扎地，保留了简易草棚、哨所与交通壕。井冈山地处罗霄山脉中段，林木茂密、地势险要，是天然的军事屏障。茅坪周围竹海连绵、溪水潺潺，八角楼至今保留着当年的简朴陈设。此地是中国革命道路的起点之一，也是感受井冈山斗争精神的红色圣地。', '江西', 26.748000, 114.289700, '其他', '[]'),
('《可爱的中国》', '上饶市弋阳县方志敏纪念馆遗址', '方志敏', '现代', '上饶弋阳方志敏纪念馆遗址位于弋阳县城内，是方志敏《可爱的中国》的创作背景地与革命精神传承场所。方志敏为中国共产党早期领导人，1935年在狱中写下了《可爱的中国》《清贫》等不朽文章，以满腔热血表达了对祖国的深沉热爱与对革命胜利的坚定信念。纪念馆保留了方志敏的革命旧址、书信手稿与烈士遗物，展厅中再现了方志敏波澜壮阔的革命生涯。弋阳是方志敏的故乡，龟峰脚下的田野与村庄正是他少年时代成长的地方。纪念馆庄严肃穆、松柏苍翠，每年清明时节前来瞻仰的群众络绎不绝。此地是感受革命先烈爱国精神与共产党人初心使命的重要教育基地。', '江西', 28.378400, 117.459100, '其他', '["https://img0.baidu.com/it/u=3448197272,2310852759&fm=253&fmt=auto&app=138&f=JPEG?w=750&h=500"]'),
('《闪闪的红星》', '上饶市婺源县李坑古村遗址', '王愿坚', '现代', '上饶婺源李坑古村遗址位于婺源县秋口镇，是电影《闪闪的红星》的主要拍摄地，也是徽派古村落的典型代表。王愿坚的同名小说以少年潘冬子为主角，讲述了红军时期赣东北地区的革命斗争故事。李坑古村保留了明清古民居数十座，白墙黛瓦的徽派建筑沿溪而建，小桥流水、古树掩映，宛如一幅天然的水墨画。村中的小溪是电影中潘冬子送盐的经典场景拍摄地。李坑因南宋理学家李侗的后裔在此定居而得名，耕读文化传统深厚。春日油菜花金黄、秋日红枫如火，四季景色各异。此地既有革命文化底蕴，又有徽派古村的秀美风光，是婺源最具代表性的古村之一。', '江西', 29.248400, 117.861400, '其他', '["https://img1.baidu.com/it/u=412190152,3644861623&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=750"]'),
('《庐山恋》', '九江市庐山市庐山含鄱口遗址', '毕必成', '现代', '九江庐山含鄱口遗址位于庐山东南部五老峰与汉阳峰之间的山谷口，是电影《庐山恋》的核心取景地。毕必成编剧的《庐山恋》于1980年上映，是新中国第一部以爱情为主题的电影，被誉为中国银幕初吻。含鄱口因面对鄱阳湖如口含之而得名，是庐山观日出与眺望鄱阳湖的最佳位置。遗址保留了民国时期建筑与观日台，清晨旭日从鄱阳湖面升起时金光万道、云蒸霞蔚，壮美无比。电影中男女主角在此相遇相恋的场景已成为中国电影史上的经典画面。含鄱口下方是庐山植物园，四季花木繁茂。此地是中国改革开放文化记忆的重要象征，也是庐山最浪漫的景点之一。', '江西', 29.450800, 116.044900, '其他', '["https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Lushan_Geopark.jpg/1280px-Lushan_Geopark.jpg"]'),
('《景德镇的瓷器》', '景德镇市珠山区古窑民俗博览区清代镇窑遗址', '郭沫若', '现代', '景德镇珠山区古窑民俗博览区清代镇窑遗址是郭沫若《景德镇的瓷器》中重点描绘的瓷都文化景观，也是世界上唯一仍在使用的传统柴窑。清代镇窑建于清乾隆年间，窑体呈拱形，长约二十米，一次可烧制数万件瓷器。郭沫若参观景德镇后写下了赞美瓷都工艺的诗文，称赞景德镇瓷器为中华民族的伟大创造。遗址保留了清代瓷窑原貌与传统制瓷作坊，游客可观看从拉坯、施釉到烧窑的完整流程。景德镇千年窑火不断，御窑厂、民窑遗址星罗棋布。博览区内还复原了明清时期的瓷业街市，展现了瓷都辉煌的手工业文明。此地是了解中国陶瓷文化与传统手工艺的最佳场所。', '江西', 29.300300, 117.202300, '其他', '["https://img0.baidu.com/it/u=3067033448,2322349788&fm=253&fmt=auto&app=120&f=JPEG?w=800&h=1044"]'),
('《婺源的春天》', '上饶市婺源县江岭梯田遗址', '余秋雨', '现代', '上饶婺源江岭梯田遗址位于婺源县溪头乡，是余秋雨《婺源的春天》中重点描绘的田园风光。江岭梯田依山而建，层层叠叠延伸至山顶，春日油菜花盛开时金黄遍野，与白墙黛瓦的徽派古村落交相辉映，被誉为中国最美乡村的标志性景观。余秋雨在文中盛赞婺源春天的绚丽与宁静，认为这里保留了中国传统农耕文明最美好的样貌。梯田周围保留了明清古民居与古驿道，溪水潺潺、古树掩映。清晨云雾从山谷中升腾，梯田若隐若现如人间仙境。秋日稻谷金黄时同样壮美。江岭是婺源油菜花观赏的核心景区，每年春季吸引大量摄影爱好者与游客前来，是感受中国乡村田园之美的绝佳之地。', '江西', 29.248400, 117.861400, '其他', '["https://img0.baidu.com/it/u=2753541387,3480397785&fm=253&fmt=auto&app=138&f=JPEG?w=500&h=635"]'),
('《龙虎山游记》', '鹰潭市贵溪市龙虎山天师府遗址', '徐霞客', '明代', '鹰潭贵溪龙虎山天师府遗址位于龙虎山景区内，是徐霞客《龙虎山游记》中重点描绘的道教圣地。龙虎山是中国道教正一派的发源地，天师府始建于东汉，为历代天师起居传道之所，已有近两千年历史。徐霞客于明崇祯年间游历龙虎山，在日记中详细记录了丹霞地貌的奇特与天师府的庄严。遗址保留了宋代建筑基础与古碑，府内古木参天、殿宇巍峨。龙虎山丹霞地貌壮美，赤色山峰倒映在泸溪河碧水之中，竹筏漂流其间如画中行。龙虎山还保留了春秋战国时期的崖墓群，千古之谜至今未解。此地是世界自然遗产与世界地质公园，也是感受中国道教文化与丹霞奇观的绝佳场所。', '江西', 28.292700, 117.245200, '其他', '["https://img0.baidu.com/it/u=3394780638,3414766962&fm=253&fmt=auto&app=138&f=JPEG?w=1067&h=800"]');
